local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:1012"] = {n="疯狂的德鲁伊",s="朵丹尼尔兽穴的一场屠杀，让德鲁伊们的灵魂饱受折磨。凯尼斯·静风是灰谷东部的一名暗夜精灵哨兵，他在抵抗被遗忘者毒素侵蚀时，通过幻象得知了这场屠杀。",h="朵丹尼尔兽穴的一场屠杀，让德鲁伊们的灵魂饱受折磨。凯尼斯·静风是灰谷东部的一名暗夜精灵哨兵，他在抵抗被遗忘者毒素侵蚀时，通过幻象得知了这场屠杀。",kw={"灰谷","朵丹尼尔兽穴","林歌神殿","被遗忘者","疯狂的德鲁伊","凯尼斯·静风","玛沃里斯·裂云","坦尼尔·黑木","尤希尔·唤月"},ang={["class:Druid"]="身为德鲁伊，你可以赐予坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云一份庄严的仁慈。你将同样修习塞纳里奥之道的同道从炼金毒药造成的疯狂中解脱出来。",["faction:Alliance"]="身为联盟的一员，你看到被遗忘者的残暴早已蔓延到洛丹伦之外。他们将瘟疫带到遥远的土地，让无辜者在睡梦中丧命。",["race:NightElf"]="身为暗夜精灵，你会将朵丹尼尔兽穴中沉睡德鲁伊遭屠杀的惨剧，视为对自然与 Kaldorei 的暴行。被遗忘者必须为此付出代价。"},sec={{t="屠杀的幻象",b="凯尼斯·静风在清醒时的幻象中目睹了一场屠杀。这名暗夜精灵哨兵正抵抗着灰谷东部发现的被遗忘者毒素的侵蚀，却看到了朵丹尼尔兽穴的土丘下发生的惨剧。亡灵渗透者在德鲁伊们沉睡时下毒，将他们屠杀殆尽。毒液将他们的灵魂从躯体中撕裂出来，让他们化作狂乱尖啸的幽魂。"},{t="赐予遇害首领的仁慈",b="凯尼斯·静风请求你平息朵丹尼尔兽穴地下的痛苦。德鲁伊们的亡魂因惨烈的死法而陷入疯狂，在地下洞穴中无法解脱。他们结社的三位首领，坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云，也仍在不得安息的亡魂之中。让他们安息，这座兽穴才有望从亵渎的创伤中开始恢复。"}},faq={{q="是谁毒害了朵丹尼尔兽穴的德鲁伊？",a="被遗忘者渗透者毒杀了朵丹尼尔兽穴的德鲁伊。凯尼斯·静风饱受从灰谷亡灵密探身上收集的被遗忘者毒素的折磨，并在幻象中目睹了这桩罪行。",al={"谁杀了 朵丹尼尔 的德鲁伊","谁谋杀了德鲁伊","被遗忘者 毒害德鲁伊"}},{q="德鲁伊们为何变成了疯狂的幽灵？",a="德鲁伊们在睡梦中被杀后，化作了疯狂的幽魂。被遗忘者的炼金毒药以违背自然、痛苦万分的方式，将他们的灵魂从躯体中撕裂出来。",al={"德鲁伊为何变成幽灵","德鲁伊为何发疯","德鲁伊为何疯狂"}},{q="坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云是谁？",a="坦尼尔·黑木、尤希尔·唤月和玛沃里斯·裂云曾领导朵丹尼尔兽穴的德鲁伊结社。他们的灵魂让兽穴中的疯狂持续不散，因此必须让他们安息，其他亡魂才能获得安宁。",al={"德鲁伊首领","坦尼尔·黑木","尤希尔·唤月","玛沃里斯·裂云"}},{q="朵丹尼尔兽穴位于何处？",a="朵丹尼尔兽穴位于灰谷东南部的地下，就在林歌神殿废墟的南面。",al={"朵丹尼尔 位置","朵丹尼尔 在哪里","灰谷兽穴"}},{q="谁会给予让德鲁伊安息的任务？",a="凯尼斯·静风是灰谷东部林歌神殿的一名暗夜精灵，在你协助他研究被遗忘者的疫病后，他会请求你帮忙。",al={"谁给予 疯狂的德鲁伊 任务","凯尼斯·静风 任务","在哪里接 疯狂的德鲁伊 任务"}},{q="消灭首领就能彻底净化兽穴吗？",a="消灭三位首领能够减轻兽穴中灵魂的痛苦。凯尼斯说，这是帮助其余疯狂幽魂获得安宁的一步。",al={"朵丹尼尔 得救了吗","大兽穴净化了吗"}}},fp="13,200,21.331.0,27.374.0,48.202.0,40.172.0,65.203.0,42.104.0,46.139.0,48.160.0"}
P.entries["quest:1013"] = {n="乌尔之书",s="看守者贝尔杜加派部落勇士前往影牙城堡，寻找《乌尔之书》。在幽暗城的炼金房，他寻求达拉然已故法师Ur留下的论著，让被遗忘者利用其中关于其他位面的研究。",h="看守者贝尔杜加派部落勇士前往影牙城堡，寻找《乌尔之书》。在幽暗城的炼金房，他寻求达拉然已故法师Ur留下的论著，让被遗忘者利用其中关于其他位面的研究。",kw={"炼金房","阿鲁高","贝尔杜加","乌尔之书","达拉然","芬鲁斯","肯瑞托","影牙城堡","狼人"},ang={["class:Mage"]="《乌尔之书》是肯瑞托历史中阴暗的一部分。它揭示了对异界生物的理论研究，如何被阿鲁高这类心智不稳的施法者扭曲成毁灭性的诅咒。",["class:Warlock"]="Ur对凡人现实之外领域的好奇，与术士对异位面知识的渴求如出一辙。贝尔杜加说，Ur之所以失败，是因为他缺乏运用自身发现的胆量。",["faction:Horde"]="肃清影牙城堡并掌控阿鲁高的研究资料，有助于稳定银松森林的局势，遏制部落领地附近的野生狼人威胁。",["race:Undead"]="找回这本书是在为希尔瓦娜斯女士和皇家药剂师学会效力。这也支持了被遗忘者的信念：要生存，就必须接受禁忌知识，抛开凡人的畏缩。"},sec={{t="异界魔法的遗物",b="在第三次大战摧毁达拉然之前，才华横溢的人类巫师Ur致力于研究艾泽拉斯之外的领域。肯瑞托严格管控召唤术以及与外层位面的接触，但Ur仍在研究来自其他维度的生物，其中包括凶残的狼人。他不愿贸然运用这些异界力量，认为它们极其危险，难以控制。这份克制使他留下的著作成了那些少有顾忌之人觊觎的珍宝。"},{t="落入黑暗之手",b="大法师阿鲁高在入驻影牙城堡之前，拿到了Ur的论著，并利用了其中的研究。阿鲁高没有Ur的顾虑，将嗜血的狼人召唤到了银松森林。狼人的诅咒吞噬了焚木村和周围的山谷。如今，这部书被遗弃在城堡的高塔中，由阿鲁高那些凶残的宠物看守。"},{t="被遗忘者的野心",b="看守者贝尔杜加和皇家药剂师学会认为，Ur的命运体现的是凡人的软弱，而非对狂妄自大的警示。贝尔杜加相信，是良知让Ur在危险来临时无法采取行动。被遗忘者为幽暗城寻求《乌尔之书》，意在抛开其中的学术顾虑，利用书中关于异次元的知识。他们要确保自身的存续，并维护希尔瓦娜斯·风行者在洛丹伦各地的统治。"}},faq={{q="Ur是谁？",a="乌尔是一位出色的达拉然法师，在第三次大战之前研究魔法和其他世界。他研究过包括狼人在内的异次元生物，并在天灾军团入侵达拉然时丧生。",al={"ur的传说","ur是谁","法师ur"}},{q="《乌尔之书》在哪里？",a="《乌尔之书》位于影牙城堡深处，在吞噬者芬鲁斯房间内的书架上。",al={"书在哪里","乌尔之书位置","影牙城堡书籍位置"}},{q="看守者贝尔杜加是谁？",a="看守者贝尔杜加是幽暗城炼金房的一名被遗忘者档案管理员兼研究者。他收集黑暗、奥术与异界知识，以增强被遗忘者的力量，确保他们的存续。",al={"贝尔杜加","看守者贝尔杜加","任务给予者"}},{q="被遗忘者为什么想要这本书？",a="贝尔杜加及其同僚想要乌尔对异位面生物的研究，好让被遗忘者掌握那些力量。他们认为，乌尔未能在天灾军团的入侵中幸存，是因为良知阻止他利用自己的发现，而幽暗城无意抱有这样的顾虑。",al={"被遗忘者为何想要乌尔之书","幽暗城获取乌尔之书的目的"}},{q="这本书是如何流落到影牙城堡的？",a="达拉然陷落后，大法师阿鲁高得到了Ur的笔记，并利用它们将狼人召唤到了洛丹伦。他夺取影牙城堡时，将这些研究资料带到了那里。",al={"阿鲁高如何得到这本书","书为何在影牙城堡"}},{q="《乌尔之书》与狼人诅咒有关吗？",a="有关。Ur的研究描述了狼人起源的维度。阿鲁高利用这部论著，将这些野兽释放到银松森林，导致狼人在当地肆虐。",al={"狼人起源书籍","乌尔之书狼人"}}},fp="14,216,29.416.0,24.315.0,23.407.1,11.212.0,32.118.0,24.181.0,36.218.0,43.174.0,46.168.0"}
P.entries["quest:1014"] = {n="除掉阿鲁高",s="在瑟伯切尔，达拉尔·道恩维沃尔派遣勇士讨伐阿鲁高。这位叛离正道的大法师盘踞在影牙城堡，他麾下的狼人威胁着被遗忘者对银松森林的控制。",h="在瑟伯切尔，达拉尔·道恩维沃尔派遣勇士讨伐阿鲁高。这位叛离正道的大法师盘踞在影牙城堡，他麾下的狼人威胁着被遗忘者对银松森林的控制。",kw={"阿鲁高","达拉尔·道恩维沃尔","阿鲁高的头颅","瑟伯切尔","影牙城堡","银松森林","希尔瓦娜斯","狼人"},ang={["class:Mage"]="身为法师，你将面对一位因召唤异界之物而扭曲的肯瑞托法师，警示着滥用奥术的狂妄之举。",["faction:Horde"]="身为部落的一员，你将协助击败一位盘踞已久的巫师，打通要道，展现部落在东部王国日益扩大的影响力。",["race:Undead"]="身为被遗忘者，你将协助巩固己方西南边境，保护瑟伯切尔与幽暗城之间的道路。"},sec={{t="黑暗女王的眼中钉",b="影牙城堡耸立于林地之上，大法师阿鲁高在那里统领着狼人。被遗忘者已将瑟伯切尔作为据点，但银松森林依旧危机四伏，各方争夺激烈。愧疚与黑暗法术令阿鲁高陷入疯狂，他将凶残的狼人释放到了洛丹伦。他麾下贪婪的野兽在林间小径游荡，阻挠希尔瓦娜斯·风行者女士巩固这片地区的控制。"},{t="直取野兽的咽喉",b="达拉尔·道恩维沃尔知道，在森林各处猎杀狼人无法根除危险。祸患的源头就在影牙城堡之中。你必须攻入这座古老的要塞，杀穿阿鲁高的狼人族群，在他高踞的巢穴中直面这位疯狂的巫师。他被斩下的头颅就是死亡的证明，而击败他便能打破他对这片地区的控制。"}},faq={{q="达拉尔·道恩维沃尔为什么要除掉阿鲁高？",a="达拉尔·道恩维沃尔想要除掉阿鲁高，因为他麾下的狼人已在银松森林泛滥成灾。只要这位法师还活着，被遗忘者就无法将这片地区变成稳固的据点。",al={"为什么要杀死阿鲁高","达拉尔·道恩维沃尔的目标","阿鲁高目标"}},{q="在哪里可以找到阿鲁高？",a="大法师阿鲁高就在影牙城堡中，那里高踞于银松森林南部的上方。",al={"阿鲁高在哪里","阿鲁高的位置","寻找阿鲁高"}},{q="完成任务需要什么证明？",a="达拉尔·道恩维沃尔需要被斩下的阿鲁高的头颅，以证明这位巫师已经死亡。",al={"达拉尔需要什么","阿鲁高的头颅任务","死亡证明"}},{q="阿鲁高对部落构成了什么威胁？",a="阿鲁高统领着大批受到诅咒的狼人，袭扰部落军队，并威胁着被遗忘者对整个银松森林的控制。他还掌握着强大的攻击魔法。",al={"阿鲁高为什么危险","狼人威胁银松森林","阿鲁高是否构成威胁"}},{q="达拉尔·道恩维沃尔效忠于谁？",a="达拉尔·道恩维沃尔效忠于希尔瓦娜斯·风行者女士和被遗忘者。他以瑟伯切尔为据点，致力于加强被遗忘者对洛丹伦各地的控制。",al={"道恩维沃尔为谁效力","瑟伯切尔的领导者"}},{q="击败阿鲁高之后会怎样？",a="阿鲁高的死亡打破了他对银松森林的魔法控制，让被遗忘者得以将势力扩展到洛丹伦西部各地，无需再忌惮他统一指挥的狼群。",al={"阿鲁高死后","阿鲁高死亡的结果"}}},fp="15,176,31.405.0,30.330.0,43.162.0,26.87.0,47.86.0,42.164.0,32.143.0,38.168.1"}
P.entries["quest:1016"] = {n="元素护腕",s="银风避难所的暗夜精灵正面对受污染的水域，并寻找幕后的黑手。哨兵维尔莉妮·星坠请你从敌对元素生物身上收集完好的护腕，以便用占卜卷轴查明是谁召唤了它们。",h="银风避难所的暗夜精灵正面对受污染的水域，并寻找幕后的黑手。哨兵维尔莉妮·星坠请你从敌对元素生物身上收集完好的护腕，以便用占卜卷轴查明是谁召唤了它们。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","召唤者","密斯特拉湖","哨兵维尔莉妮·星坠","银风避难所"},ang={["class:Mage"]="身为法师，你能认出召唤元素生物所佩戴的束缚上带有其主人的奥术印记，并循着这些印记追溯鲁莽召唤行为的源头。",["faction:Alliance"]="身为联盟的一员，援助Silverwind Sentinels能巩固你在灰谷中部争夺激烈的腹地中的地位。",["race:NightElf"]="身为暗夜精灵，你知道灰谷的天然水池是神圣之地。奥术召唤者引入外来腐化的行为，是对Kaldorei的冒犯。"},sec={{t="受污染的水域",b="失控的水元素如今正在侵扰灰谷的神圣水域。与自然栖居在世间的荒野之灵不同，这些生物显露出人为召唤的迹象。在银风避难所，哨兵认为它们的突然出现表明外来的腐化正沿着林间水道向更深处蔓延。"},{t="占卜召唤者",b="哨兵维尔莉妮·星坠相信，有人蓄意束缚并释放了这些元素生物。她给你一张魔法占卜卷轴，帮助查明罪魁祸首。这个法术需要一种与被召唤生物相关的施法材料：在这些灵体消散前，从它们身上取下的完好护腕。卷轴会读取这些束缚上残留的奥术印记，追查召唤出元素生物的人。"},{t="巫师的干涉",b="对完好的护腕使用占卜卷轴后，奥术残留证实了维尔莉妮最深的忧虑：一名独自行动的法师正在不断向灰谷的池水中召入腐化的元素生物。这个发现激怒了暗夜精灵守卫。他们如今正准备迅速惩处这名威胁林地圣洁的召唤者。"}},faq={{q="灰谷为什么会有水元素？",a="这些敌对的水元素并非与灰谷和谐共存的自然生灵。一名外来的施法者召唤了它们，扰乱了神圣的池水，激怒了暗夜精灵。",al={"元素生物为何在此","灰谷水元素","元素生物从何而来"}},{q="谁提供元素护腕任务？",a="哨兵维尔莉妮·星坠交付这项任务。她驻守在灰谷密斯特拉湖畔的银风避难所。",al={"任务给予者","谁提供元素护腕","元素护腕接取地点"}},{q="占卜卷轴有什么用途？",a="占卜卷轴会读取元素生物身上残留的魔法印记。对五副完好的护腕使用卷轴，就能沿着奥术纽带追查到创造它们的召唤者。",al={"卷轴有什么作用","占卜卷轴用途","为何使用占卜卷轴"}},{q="为什么仪式只能使用完好的护腕？",a="只有完好的护腕才能保留足够稳定的奥术共鸣，供卷轴分析。消灭元素生物时，往往会损坏或击碎束缚它的魔法，使这些束缚无法揭示召唤者的身份。",al={"为何需要完好的护腕","破损的护腕","完好的元素护腕"}},{q="使用卷轴占卜后会发生什么？",a="将使用过的占卜卷轴交还给哨兵维尔莉妮·星坠后，她会查明肇事的施法者，并在后续任务召唤者中派你去追猎这名召唤者。",al={"元素护腕后续","接下来做什么","元素护腕的下一个任务"}},{q="哨兵维尔莉妮为什么如此在意这些元素生物？",a="暗夜精灵崇敬灰谷森林与水域的自然纯净。一名凡人巫师蓄意用腐化的元素生物污染湖泊、破坏其平衡，这是对他们守护职责的侮辱。",al={"哨兵 维尔莉妮的动机","暗夜精灵为何在意元素生物"}}},fp="17,203,14.288.0,21.319.0,19.294.1,44.167.0,38.126.0,43.164.0,47.200.0,39.183.1,61.199.0"}
P.entries["quest:1017"] = {n="召唤者",s="哨兵维尔莉妮·星坠从银风避难所派人南下出击。调查密斯特拉湖附近遭到腐化的水元素后，哨兵 派遣冒险者越过边界，进入贫瘠之地，杀死盘踞在鬼雾峰顶的亡灵法师萨瑞鲁斯·法伯尼。",h="哨兵维尔莉妮·星坠从银风避难所派人南下出击。调查密斯特拉湖附近遭到腐化的水元素后，哨兵 派遣冒险者越过边界，进入贫瘠之地，杀死盘踞在鬼雾峰顶的亡灵法师萨瑞鲁斯·法伯尼。",kw={"灰谷","鬼雾峰","月神之光","萨瑞鲁斯·法伯尼","银风避难所","贫瘠之地","维尔莉妮·星坠","水元素"},ang={["class:Mage"]="与法伯尼交锋，意味着联盟的奥术师将面对一名亡灵施法者，他将元素召唤扭曲到了肆无忌惮的极端。",["class:Priest"]="从 Sentinels 手中接过月神之光，让你的道路与女神罕见的神迹恩典相连，共同抵御亡灵的腐化。",["faction:Alliance"]="深入贫瘠之地打击一名被遗忘者，以果敢的武力展示，回应了部落在灰谷南部边疆的侵扰。",["race:NightElf"]="萨瑞鲁斯越过森林边界，以奥术亵渎自然，这是对 Kaldorei 的侮辱。处决他，既关乎林地的平衡，也关乎尊严。"},sec={{t="跨越边界",b="若无重大缘由，暗夜精灵很少派斥候南下进入贫瘠之地。调查密斯特拉湖周围水元素的异常骚动后，哨兵维尔莉妮·星坠查出，幕后操纵者是萨瑞鲁斯·法伯尼，一名就在边界另一侧施展法术的被遗忘者召唤师。对银风避难所的 哨兵 而言，敌方法师竟敢在离家园如此之近的地方亵渎自然，实在无法容忍。"},{t="峰顶的召唤师",b="萨瑞鲁斯·法伯尼将巢穴建在鬼雾峰高处，这座嶙峋的山峰上遍布火刃氏族的教徒。他在那里召唤成群的水元素，迫使它们服从自己的意志，并从部落领地公然挑战暗夜精灵的权威。要接近他，就必须冒险深入敌境，杀穿他召唤的大军。哨兵 要求带回他的首级，以此证明他们的复仇之手能够伸向森林之外。"},{t="艾露恩 的祝福",b="维尔莉妮·星坠收下法伯尼的首级，将月神之光赠予斩杀他的人。这一剂凝聚月光的神圣药水，是女祭司与 哨兵 珍视的护身之物，能在死亡逼近时提供完全的庇护。当邪恶魔法在卡利姆多蔓延时，这份赠礼让人想起暗夜精灵所受的神恩。"}},faq={{q="萨瑞鲁斯·法伯尼是谁？",a="萨瑞鲁斯·法伯尼是一名亡灵法师，逃入贫瘠之地后，在鬼雾峰顶安身。他以奥术召唤奴役水元素，激起了附近灰谷中 哨兵 的怒火。",al={"萨瑞鲁斯·法伯尼","召唤者 是谁","法伯尼 背景故事"}},{q="鬼雾峰位于何处？",a="鬼雾峰是贫瘠之地北部一座嶙峋的山峰，就在灰谷边界正南方。萨瑞鲁斯·法伯尼就在峰顶等候。",al={"鬼雾峰在哪里","鬼雾峰位置","如何找到鬼雾峰"}},{q="哨兵维尔莉妮·星坠为何要杀死萨瑞鲁斯？",a="萨瑞鲁斯一直在亵渎并腐化灰谷边界附近的水元素。维尔莉妮无法容忍他的挑衅，决心终结他违背自然的召唤法术，证明敌人无法隔着边界肆意嘲弄 哨兵。",al={"为何杀死 萨瑞鲁斯","维尔莉妮·星坠 的动机"}},{q="作为奖励的月神之光是什么？",a="月神之光是一瓶受到神圣月光祝福的稀有药水。在危急时刻饮下，便能在短时间内完全免疫伤害和法术效果，从必死的险境中逃生。",al={"月神之光药水","月神之光背景故事"}},{q="这个任务的前置任务是什么？",a="在此之前，冒险者要从灰谷密斯特拉湖周围具有占卜能力的水元素身上收集完整的护腕。维尔莉妮借助这些护腕查明是谁在操纵元素。",al={"召唤者 前置条件","召唤者 前置任务"}},{q="联盟玩家进入贫瘠之地为何危险？",a="贫瘠之地属于部落，是牛头人和兽人的家园。进入这里的联盟士兵和冒险者，随时可能遭到部落巡逻队和敌对勇士的拦截。",al={"贫瘠之地的危险","部落领地任务"}}},fp="13,237,21.376.0,24.422.0,17.314.1,25.206.0,32.146.0,54.233.0,45.195.0,29.180.0,59.164.0"}
P.entries["quest:102"] = {n="西部荒野的豺狼人",s="成群的豺狼人威胁着仍住在西部荒野草原上的人们。丹努文队长在哨兵岭召集志愿者猎杀它们，担心它们与死亡矿井中的盗贼勾结。",h="成群的豺狼人威胁着仍住在西部荒野草原上的人们。丹努文队长在哨兵岭召集志愿者猎杀它们，担心它们与死亡矿井中的盗贼勾结。",kw={"丹努文","死亡矿井","豺狼人","爪子","人民军","哨兵岭","暴风城","西部荒野"},ang={["faction:Alliance"]="对联盟而言，西部荒野艰难度日的乡民与暴风要塞中的贵族矛盾重重，后者对他们的困境置之不理。",["race:Human"]="身为人类，看到西部荒野金色的田野被豺狼人占据，你便能明白，经历近来的战乱后，王国的复苏依然如此脆弱。"},sec={{t="被王室遗弃",b="哨兵岭是西部荒野的主要防线，由当地志愿者驻守，而非王国军队。暴风城没有派兵保护外围的农田，人们便组建了人民军。丹努文队长曾在西部荒野务农。如今，他率领着民兵，拒绝抛弃自己的家园。\n\n民兵依靠途经此地的旅人协助守住外围防线，抵御平原上不断聚集的威胁。"},{t="草原上的食腐者",b="豺狼人威胁着在西部荒野艰难求生的难民和流民。丹努文的斥候认为，这些豺狼人群与盘踞在死亡矿井的强盗勾结。因此，他派出猎手收集豺狼人的爪子。他希望遏制豺狼人日益频繁的巡逻，并瓦解这些野兽与匪徒之间的一切合作。"}},faq={{q="丹努文队长是谁？",a="丹努文队长指挥着哨兵岭的志愿守军。他曾是西部荒野的农夫，在暴风城撤回支援后挺身而出，拒绝抛弃仍留在这里的人们。",al={"丹努文队长","丹努文是谁","哨兵岭任务给予者"}},{q="为什么对抗豺狼人的是人民军，而非暴风城的士兵？",a="暴风城的贵族对西部荒野的困境大多置之不理，导致这片地区没有王国士兵驻守。流离失所的农夫和劳工组建了人民军，保护自己的土地免受强盗和野兽侵扰。",al={"为什么没有暴风城军队","暴风城卫兵在哪里","为什么组建民兵"}},{q="西部荒野的豺狼人有组织吗？",a="豺狼人通常是混乱无序的食腐者，但丹努文队长发现了一些迹象，表明西部荒野的豺狼人群与盘踞在死亡矿井的盗贼相互配合。它们可能在为这些罪犯守卫外围地带。",al={"豺狼人是否与迪菲亚合作","豺狼人同盟","死亡矿井盗贼与豺狼人"}},{q="丹努文队长为什么索要豺狼人的爪子？",a="丹努文队长索要豺狼人的爪子，以此证明这些野兽已被杀死，从草原上清除。",al={"为什么要豺狼人的爪子","爪子悬赏","击杀证明"}},{q="豺狼人通常出没在哪里？",a="豺狼人的狩猎队和营地遍布西部荒野中部与南部的平原。它们在废弃农庄周围的旷野和山坡附近游荡。",al={"豺狼人位置","西部荒野哪里有豺狼人"}},{q="豺狼人的威胁被遏制后会怎样？",a="人民军希望削减豺狼人和匪徒的数量，让人们能够重返平原，恢复这片曾经养活王国的粮仓。",al={"西部荒野接下来会怎样","民兵目标","暴风城的粮仓"}}},fx={["939494a1"]={q="丹努文队长为什么要你巡逻西部荒野？",a="丹努文队长不肯放弃自己的故乡。暴风城王室抛弃了西部荒野，让仍留在这里的农民和居民暴露在猖獗的暴行之下。丹努文和人民军决心夺回这片土地，让它重新成为昔日富饶的粮仓，但只要豺狼人仍在肆意游荡、侵扰当地居民，他们就无法保障平原的安全。",al={"为什么巡逻西部荒野","丹努文的动机","为什么杀西部荒野的豺狼人"}},["91e73c26"]={q="豺狼人为什么会在西部荒野？",a="在草原上游荡的豺狼人似乎正与盘踞在死亡矿井的盗贼协同行动。这些劫掠者趁王国撤军之机恐吓当地农场，并与匪徒勾结，让哨兵岭和剩下的居民始终遭到围困、彼此隔绝。",al={"豺狼人是谁","豺狼人为什么在这里","西部荒野豺狼人死亡矿井"}}},fp="19,191,22.427.0,32.307.0,23.192.0,74.225.0,37.188.0,44.110.0,37.158.0,50.159.0"}
P.entries["quest:1020"] = {n="奥雷迪尔的药剂",s="在灰谷，奥雷迪尔的药剂即将送往阿斯特兰纳，用来救治一名患病的孩子。奥雷迪尔·阔叶派一位联盟旅者，将用珍稀植物制成的药剂送去。",h="在灰谷，奥雷迪尔的药剂即将送往阿斯特兰纳，用来救治一名患病的孩子。奥雷迪尔·阔叶派一位联盟旅者，将用珍稀植物制成的药剂送去。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","药剂","奥雷迪尔·阔叶","皮尔图拉斯·怀特姆恩","蕾拉"},ang={["class:Priest"]="身为牧师，你知道草药能暂时减轻蕾拉身体上的痛苦，而她挥之不去的疾病则需要Elune的神圣干预与月亮仪式。",["profession:Herbalism"]="草药学展现了植物知识如何用于战场救治：从灰谷采来的草药，例如巴斯兰的头发，足以左右一个孩子的生死。",["race:NightElf"]="身为暗夜精灵，你帮助保护阿斯特兰纳的孩子，也让族人在这片争夺不休的森林中更加团结。"},sec={{t="父亲的绝望",b="在阿斯特兰纳，皮尔图拉斯·怀特姆恩看着女儿蕾拉因一种严重而神秘的疾病日渐衰弱。当地已无人知道该如何医治，他便在希望消逝之前，向灰谷各地的草药师求助。"},{t="林间竞速",b="奥雷迪尔·阔叶用巴斯兰的头发等必需材料调制了一剂药水，以遏制蕾拉的病情。他将药剂托付给你，派你沿着林间大道向南再向东前往阿斯特兰纳，蕾拉正等待着这剂药。"},{t="短暂的喘息",b="奥雷迪尔的药水缓解了蕾拉的痛苦，却无法根除那侵蚀她灵魂的超自然疾病。这剂药争取了时间，让人们能在古老的卡多雷废墟中寻找受艾露恩祝福的圣物，或许能彻底救回她。"}},faq={{q="阿斯特兰纳里是谁病了？",a="皮尔图拉斯·怀特姆恩年幼的女儿蕾拉·怀特姆恩在阿斯特兰纳卧病不起。她的病情危急，父亲正焦急地寻找救治她的药。",al={"谁病了","谁需要药剂","阿斯特兰纳患病的孩子"}},{q="是谁调制了奥雷迪尔的药剂？",a="奥雷迪尔·阔叶是灰谷北部的一位暗夜精灵草药师，他收到从巴斯兰鬼屋采集的植物材料后，调制了这剂药。",al={"谁调制了药剂","奥雷迪尔·阔叶","药剂来自哪里"}},{q="皮尔图拉斯·怀特姆恩在哪里？",a="皮尔图拉斯·怀特姆恩住在阿斯特兰纳，这座联盟城镇坐落在贯穿灰谷中部的大道旁。他在一间林中居所内守着女儿的病床。",al={"皮尔图拉斯的位置","皮尔图拉斯在哪里","阿斯特兰纳寻找皮尔图拉斯"}},{q="奥雷迪尔的药剂能彻底治好蕾拉吗？",a="不能。药水暂时稳住了蕾拉的病情，让她的父亲重新燃起希望，但她的疾病还需要更深层的灵性救助。旅者们正在寻找月神之泪。",al={"蕾拉治好了吗","药剂有效吗","药剂效果"}},{q="这剂药用了哪些材料？",a="主要材料是巴斯兰的头发，采自迈斯特拉岗哨以北、巴斯兰鬼屋那片受诅咒的土地。",al={"药剂材料","药剂用什么制成","巴斯兰的头发"}},{q="阿斯特兰纳当地的医者为什么不自行调制这剂药？",a="阿斯特兰纳常用的药物对蕾拉的疾病无效，因此皮尔图拉斯向精通草药的奥雷迪尔·阔叶求助。奥雷迪尔懂得如何处理灰谷北部那些药效强劲的植物。",al={"为什么找奥雷迪尔","阿斯特兰纳的医者为何无能为力","为什么找阔叶"}}},fp="14,124,18.193.0,27.237.0,17.228.1,25.154.0,26.142.0,36.177.0,43.171.1,47.118.0,62.199.0"}
P.entries["quest:1021"] = {n="身陷危险的树妖！",s="伊莉亚娜正在灰谷寻找她的姐妹，她们为夺回一件被盗的圣物而出发，之后便下落不明。她请求旅人前往遭到腐化的萨维亚废墟寻找她们。",h="伊莉亚娜正在灰谷寻找她的姐妹，她们为夺回一件被盗的圣物而出发，之后便下落不明。她请求旅人前往遭到腐化的萨维亚废墟寻找她们。",kw={"安妮莉亚","灰谷","塞纳留斯的树枝","塞纳留斯","树妖","伊莉亚娜","萨特","萨维亚"},ang={["class:Druid"]="身为德鲁伊，你与塞纳留斯的子嗣有着深厚的亲缘。你立誓净化从萨维亚这类萨特据点蔓延而出的恶魔腐化。",["faction:Alliance"]="身为联盟旅人，在地区威胁日益加剧之际帮助伊莉亚娜，能加深联盟与灰谷神秘居民之间的联系。",["race:NightElf"]="身为暗夜精灵，你与塞纳留斯的女儿——树妖有着深厚的联系。她们的苦难，以及萨维亚古老精灵神殿遭到的亵渎，都在呼唤你的荣誉感与精神职责。"},sec={{t="心急如焚的姐妹",b="树妖伊莉亚娜在灰谷等候，为姐妹们的安危忧心不已。她们前往森林北部遭到腐化的地区，寻找被萨特偷走的圣物——塞纳留斯的树枝。她们曾答应很快就会回来，可两天过去了，依然杳无音讯。如今，伊莉亚娜请求路过的联盟旅人赶在为时已晚之前找到她们。"},{t="萨维亚废墟",b="萨维亚位于东北方，是一片古老的暗夜精灵神殿建筑群，早已遭到燃烧军团的腐化。受邪能污染的萨特盘踞在废墟中，让搜寻之路危机四伏。在废墟深处，树妖远征队的领队安妮莉亚遭到当地恶魔的袭击，身负重伤，奄奄一息。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是生活在灰谷森林中的一名树妖。她担忧姐妹们的安危，派旅人前往萨维亚，寻找她们失踪的队伍。",al={"伊莉亚娜","谁发布邪恶的萨特！身陷危险的树妖！","任务发布者"}},{q="塞纳留斯的树枝是什么？",a="塞纳留斯的树枝是树妖和暗夜精灵珍视的圣物。灰谷北部的萨特偷走了它，安妮莉亚和她的姐妹们为夺回圣物，踏上了深入萨维亚的危险旅程。",al={"塞纳留斯的树枝","她们在寻找什么圣物","树妖圣物"}},{q="萨维亚是什么地方？",a="萨维亚是灰谷东部的一座古老暗夜精灵神殿。恶魔萨特占据了这片废墟，邪能腐化威胁着自然的守护者。",al={"萨维亚","萨维亚废墟","树妖在哪里"}},{q="安妮莉亚是谁？",a="安妮莉亚是一名树妖，她率领搜寻队，试图从萨特手中夺回塞纳留斯的树枝。伊莉亚娜请求旅人到萨维亚寻找她。",al={"安妮莉亚","失踪的树妖领队","安妮莉亚在哪里"}},{q="树妖为何与萨特为敌？",a="树妖是半神塞纳留斯的女儿，致力于保护自然，维系森林的平衡。萨特是被恶魔邪能魔法扭曲的古代暗夜精灵，他们腐化荒野，亵渎神圣的林地。",al={"树妖为何憎恨萨特","树妖与萨特的战争","萨特的腐化"}},{q="后续任务是什么？",a="找到安妮莉亚便完成了搜寻，并开启后续任务“塞纳留斯的树枝”，继续夺回被盗的圣物。",al={"后续任务","身陷危险的树妖任务链","邪恶的萨特后续"}}},fp="29,186,18.337.0,19.300.1,16.117.0,31.172.0,15.152.0,14.142.1,46.224.0,28.132.1"}
P.entries["quest:1022"] = {n="狼嚎谷",s="在狼嚎谷，狼人占据了费伍德森林附近的一座神殿废墟。哨兵梅丽瑞亚·霜影正在追查它们为何来到灰谷。",h="在狼嚎谷，狼人占据了费伍德森林附近的一座神殿废墟。哨兵梅丽瑞亚·霜影正在追查它们为何来到灰谷。",kw={"灰谷","费伍德森林","狼嚎谷","梅尔莎迪丝","梅丽瑞亚·霜影","月神镰刀","恐狼","梅尔莎迪丝之书","维琳德·星歌","狼人"},ang={["class:Priest"]="身为牧师，你或许会发现，寻找女祭司维琳德·星歌的经历，是一个关于献身Elune、令人心情沉重的故事。",["faction:Alliance"]="身为联盟的一员，你加入了追查可怕狼人起源的行列，这些狼人正在卡利姆多北部和东部王国游荡。",["race:NightElf"]="身为暗夜精灵，Mel'Thandris的神殿遭到亵渎，触动了你守护灰谷的职责。女祭司维琳德·星歌的幻象，让你得以窥见这份重担中的悲伤。"},sec={{t="令人胆寒的存在",b="狼人的嚎叫从灰谷北部的一座神殿废墟中传来。梅尔莎的神殿位于费伍德森林边界附近，穿过一条洞穴通道便可抵达。哨兵梅丽瑞亚·霜影担心，狼人会给这片林地带来另一场灾难。暗夜精灵哨兵已经投入了大量精力，抵御来自费伍德森林的恶魔腐化。"},{t="鲜活的编年史",b="梅丽瑞亚派遣探寻者前往被狼人占据的神殿，查阅梅尔莎之书。梅尔莎曾赐福于书页，使其能够记录重大事件。在敌对的狼人环伺之下翻开这本典籍，就会召出女祭司维琳德·星歌的幽灵幻象。幻象揭示了她召唤神秘的月神镰刀的经过，而那次召唤改变了她的命运。"}},faq={{q="狼嚎谷位于何处？",a="狼嚎谷位于灰谷中北部，就在费伍德森林边界的西南方。一条洞穴通道通往谷内，直达梅尔莎迪丝的神殿废墟。",al={"狼嚎谷位置","如何前往狼嚎谷","梅尔莎迪丝的神殿在哪里"}},{q="谷中的狼形人是什么？",a="这些狼形人是狼人，具体来说，属于恐狼狼群。这些凶残而违背自然的野兽用双腿行走，突然出现在卡利姆多，在费伍德森林边境附近的废墟中散布恐惧。",al={"灰谷狼形人","狼嚎谷的怪物是什么","恐狼狼人"}},{q="梅尔莎迪丝之书是什么？",a="梅尔莎迪丝之书是神殿废墟中的一件魔法遗物。梅尔莎迪丝曾赐福于书页，使其能够记录关键事件，并向研读者展现这些事件的幻象。",al={"梅尔莎迪丝之书","典籍有什么作用","梅尔莎迪丝的书"}},{q="维琳德·星歌是谁？",a="维琳德·星歌是一位暗夜精灵女祭司，曾参与费伍德森林附近对抗恶魔的斗争。梅尔莎迪丝之书或许能揭示更多关于她的故事。",al={"维琳德·星歌","女祭司维琳德","典籍中的幽灵是谁"}},{q="谁给予这个任务？",a="哨兵梅丽瑞亚·霜影在灰谷的艾森娜神殿提出了这个请求。费伍德森林的恶魔入侵，以及附近狼人来历不明的突然现身，都令她忧心忡忡。",al={"谁提供狼嚎谷任务","狼嚎谷任务给予者","梅丽瑞亚·霜影"}},{q="哨兵梅丽瑞亚为何关心这座神殿？",a="灰谷的哨兵守卫着这片土地，抵御来自费伍德森林的腐化。狼形人占据了边界附近一处古老的暗夜精灵圣地后，哨兵需要查明此事是否由恶魔操纵，还是出现了新的威胁。",al={"为何调查狼嚎谷","林歌神殿哨兵"}}},fp="16,145,19.337.0,20.319.1,34.164.0,34.196.0,33.171.0,25.151.1,21.171.0,48.220.0"}
P.entries["quest:1023"] = {n="莱恩的净化",s="在法拉希姆湖，莱恩的净化从寻找泰洛尼斯变成了一场沉重的遗物回收。莱恩·狼行者派这位暗夜精灵哨兵前往那里，如今你必须取回他的日记和鱼人手中的一颗发光的宝石，再回阿斯特兰纳向她复命。",h="在法拉希姆湖，莱恩的净化从寻找泰洛尼斯变成了一场沉重的遗物回收。莱恩·狼行者派这位暗夜精灵哨兵前往那里，如今你必须取回他的日记和鱼人手中的一颗发光的宝石，再回阿斯特兰纳向她复命。",kw={"灰谷","阿斯特兰纳","发光的宝石","法拉希姆湖","鱼人","莱恩的净化","哨兵","泰洛尼斯"},ang={["faction:Alliance"]="身为联盟的一员，你协助莱恩·狼行者和Sentinels以阿斯特兰纳为据点，守卫灰谷北部的通路。",["race:NightElf"]="身为暗夜精灵，你知道一位哨兵同胞在法拉希姆湖遇难，意味着危险正悄然逼近卡利姆多古老的圣林。"},sec={{t="陨落的斥候",b="莱恩·狼行者派你前往法拉希姆湖，寻找暗夜精灵哨兵泰洛尼斯。你在水边发现他已经死去。他的遗物中有一本完好的日记，记述了他的任务，以及他对灰谷种种异常骚动的调查发现。"},{t="发光的宝石",b="泰洛尼斯追寻一颗罕见的发光石头来到法拉希姆湖，但如今它落在了湖中凶悍的鱼人手里。你需要取回这颗宝石和泰洛尼斯的日记，才能继续他开始的工作。"},{t="阿斯特兰纳的哀伤",b="当你带着泰洛尼斯的消息回到阿斯特兰纳时，莱恩·狼行者悲痛不已。尽管腐化正威胁着森林，她仍须安排一支巡逻队，找回阵亡战友的遗体。莱恩请你接手泰洛尼斯的工作，重组那根他曾寄望能减缓熊怪攻势的魔棒。"}},faq={{q="泰洛尼斯是谁？",a="泰洛尼斯是一名暗夜精灵斥候，莱恩·狼行者派他从阿斯特兰纳出发，调查法拉希姆湖并取得一颗神秘宝石。他尚未完成使命，就被凶猛的野兽杀害了。",al={"泰洛尼斯","泰洛尼斯是谁","泰洛尼斯的故事"}},{q="在哪里能找到发光的宝石？",a="灰谷西北部法拉希姆湖及其周围的鱼人携带着发光的宝石，就在发现泰洛尼斯遗体的地方附近。",al={"发光的宝石在哪里","发光的宝石位置","寻找发光的宝石"}},{q="莱恩·狼行者为何如此重视这项任务？",a="泰洛尼斯是莱恩多年的挚友，他相信那根魔棒能减缓熊怪对她族人的袭击。熊怪仍在劫掠灰谷，因此即使他已经死去，莱恩仍急于推进他未竟的工作。",al={"为何进行莱恩的净化","莱恩·狼行者的动机"}},{q="这个任务结束后，泰洛尼斯的遗体会如何安置？",a="莱恩·狼行者承诺从阿斯特兰纳派出一支哨兵分队，寻回泰洛尼斯的遗体，为他举行悼念和暗夜精灵传统葬礼。",al={"泰洛尼斯遗体的下落","泰洛尼斯的遭遇"}},{q="泰洛尼斯的日记有什么用？",a="泰洛尼斯的日记记录了他对达图尔的调查，这名人类巫师曾使用德鲁伊魔法，试图与熊怪交好并控制它们。日记中还有他关于寻回达图尔魔棒各个部件的笔记。",al={"泰洛尼斯的日记","日记是什么"}},{q="交付这个任务后，任务链还会继续吗？",a="会。当你把宝石和日记交给莱恩·狼行者后，她会请你继续泰洛尼斯的工作，寻找达图尔魔棒剩余的部件。",al={"任务进展","泰洛尼斯之后的任务"}}},fp="17,193,14.234.0,15.162.0,18.282.1,16.186.0,31.121.0,48.208.0,47.156.0,29.202.0,51.146.0"}
P.entries["quest:1024"] = {n="莱恩的净化",s="一颗发光的宝石让灰谷的莱恩的净化迎来了转机。莱恩·狼行者派你前往伊瑞斯湖以东，向树妖莎尔蒂恩请教如何修复达图尔的古老魔棒。",h="一颗发光的宝石让灰谷的莱恩的净化迎来了转机。莱恩·狼行者派你前往伊瑞斯湖以东，向树妖莎尔蒂恩请教如何修复达图尔的古老魔棒。",kw={"灰谷","达图尔的魔棒","发光的宝石","伊瑞斯湖","月亮井","莱恩·狼行者","莱恩的净化","莎尔蒂恩","泰洛尼斯"},ang={["class:Druid"]="身为德鲁伊，帮助莎尔蒂恩能让你履行塞纳里奥的职责，修复自然与Kaldorei魔法之间断裂的纽带。",["faction:Alliance"]="身为联盟的一员，协助保护古老的神器并巩固阿斯特兰纳的北部防线，能为对抗这一地区日益增长的威胁贡献力量。",["race:NightElf"]="修复魔棒，就能继续泰洛尼斯未竟的调查，探究灰谷熊怪遭遇的困境。"},sec={{t="泰洛尼斯笔记中的线索",b="莱恩·狼行者研读着哨兵泰洛尼斯留下的实地调查笔记，他在调查灰谷熊怪的困境时丧生。他的研究指向一根古老的魔棒，由一位名叫达图尔的暗夜精灵制成。莱恩·狼行者已经找回了一颗发光的宝石，但她身为女猎手的本领无法解开这件遗物背后的奥术与自然之谜。"},{t="寻访塞纳留斯的女儿",b="莱恩·狼行者派你向东北方的伊瑞斯湖进发，寻找住在月亮井旁的树妖莎尔蒂恩。身为塞纳留斯的女儿的一员，莎尔蒂恩了解森林与古老的遗物。把发光的宝石带给她，她或许能告诉你，修复达图尔的变形魔棒还需要些什么。"}},faq={{q="泰洛尼斯是谁？",a="泰洛尼斯是一名暗夜精灵斥候，受阿斯特兰纳派遣，调查在灰谷蔓延的腐化。他在这次任务中丧生，但找回的日记提供了一条线索：修复达图尔的魔棒或许能帮助这片土地。",al={"泰洛尼斯","泰洛尼斯笔记","泰洛尼斯是谁"}},{q="达图尔的变形魔棒是什么？",a="达图尔的变形魔棒是一件古老的魔法神器，莱恩·狼行者希望它能帮助她调查灰谷的熊怪。找回的发光的宝石是修复它所需的部件之一。",al={"达图尔的魔棒","魔棒是什么"}},{q="在哪里能找到莎尔蒂恩？",a="莎尔蒂恩住在阿斯特兰纳东北方一口隐蔽的月亮井旁，就在伊瑞斯湖东侧的山丘间。沿着道路向东走，在抵达林中树居附近的危险地带之前转向北方。",al={"莎尔蒂恩在哪里","莎尔蒂恩位置","寻找树妖"}},{q="发光的宝石是什么？",a="发光的宝石是达图尔的魔棒的一个部件，从泰洛尼斯调查所涉的废墟中找回。莎尔蒂恩需要用它来寻找魔棒的其他部件。",al={"发光的宝石","宝石有什么用","泰洛尼斯宝石"}},{q="莱恩·狼行者为什么派你去找树妖？",a="莱恩·狼行者是一名女猎手，也是阿斯特兰纳哨兵的领袖，致力于守卫这座城镇。树妖是塞纳留斯的女儿，她们了解古老的遗物，也懂得如何让自然恢复生机。",al={"为什么找树妖","莱恩·狼行者树妖","为什么找莎尔蒂恩"}},{q="伊瑞斯湖周围的森林为何面临危险？",a="腐化与动荡正在灰谷的野生生物和熊怪部族之间蔓延。莱恩·狼行者希望修复魔棒能帮助她了解熊怪的困境。",al={"灰谷腐化","灰谷为何遭到腐化","伊瑞斯湖危险"}}},fp="17,147,25.303.0,33.287.0,16.207.0,21.183.0,28.193.0,24.166.0,46.189.0,45.159.0"}
P.entries["quest:1025"] = {n="先发制人",s="莱恩·狼行者派遣联盟守卫者，迎击灰谷的污林熊怪。腐化让这个部族成为阿斯特兰纳以东道路上的威胁。",h="莱恩·狼行者派遣联盟守卫者，迎击灰谷的污林熊怪。腐化让这个部族成为阿斯特兰纳以东道路上的威胁。",kw={"灰谷","阿斯特兰纳","弗伦","污林","熊怪","莱恩·狼行者","哨兵"},ang={["class:Druid"]="身为德鲁伊，你从Foulweald的疯狂中看到了警示：邪能污秽正在侵蚀卡利姆多神圣的荒野。",["faction:Alliance"]="身为联盟守卫者，你协助维持阿斯特兰纳通往东部哨站的道路畅通，让物资和旅人得以通行。",["race:NightElf"]="身为kaldorei，你不得不面对残酷的现实，与那些心智已被腐化吞噬的昔日森林同胞作战。"},sec={{t="大道上的威胁",b="如今，熊怪开始袭击从阿斯特兰纳向东通往弗伦河的道路上的旅人。哨兵莱恩·狼行者派遣能干的守卫者，进攻大道南侧的污林营地。这些袭击让这条贯穿灰谷的要道危机四伏，威胁着所有途经此地的人。"},{t="苦涩的往事",b="污林曾是暗夜精灵的朋友和盟友。长久以来，卡多雷与熊怪都敬畏着自然与荒野诸神。燃烧军团的入侵留下了污秽，摧毁了许多熊怪的心智。昔日和平的邻居变成了凶暴的劫掠者，如今无辜的旅人也遭到他们的袭击。"}},faq={{q="谁提供这项任务，位于何处？",a="哨兵莱恩·狼行者在阿斯特兰纳提供这项防御任务，那里是灰谷中部最主要的暗夜精灵聚居地。",al={"任务给予者","谁提供先发制人","莱恩·狼行者位置"}},{q="灰谷的熊怪为何充满敌意？",a="污林熊怪受到了燃烧军团在第三次大战期间留下的恶魔污秽侵蚀。他们的心智变得狂暴，驱使他们袭击旅人和昔日的盟友。",al={"熊怪为何疯狂","污林的敌意","熊怪腐化"}},{q="污林熊怪营地在哪里？",a="污林熊怪营地位于阿斯特兰纳向东延伸的主路南侧，弗伦河以西。",al={"污林位置","哪里能找到污林","熊怪在哪里"}},{q="熊怪一直都是暗夜精灵的敌人吗？",a="不是。熊怪与暗夜精灵曾和睦相处了数千年。灰谷和费伍德森林中的恶魔腐化，让污林熊怪这样的部族变得充满敌意。",al={"熊怪与暗夜精灵的历史","熊怪曾经友善吗","卡多雷与熊怪"}},{q="这项任务与阿斯特兰纳的其他事件有关吗？",a="莱恩发起的打击行动是阿斯特兰纳防御的一部分。她还指派守卫者调查被腐化的月亮井，并协助净化森林。",al={"前置任务","莱恩与净化的关联"}},{q="具体需要消灭哪些熊怪？",a="莱恩要求击杀一名污林卫兵、两名巨熊、十名图腾师和十二名战士，以瓦解这个部族在道路附近的指挥体系。",al={"任务目标","需要击杀谁","污林目标"}}},fp="21,161,21.283.0,16.313.0,48.118.0,42.164.0,36.96.0,52.172.0,53.141.0,42.151.0"}
P.entries["quest:1026"] = {n="莱恩的净化",s="在灰谷，莱恩的净化让达图尔的变形魔棒离完整又近了一步。莎尔蒂恩知道它的铁杆藏在哪里，就在费伍德森林边界附近的一只箱子里。搜寻之路通向那些因腐化而改变的树人。",h="在灰谷，莱恩的净化让达图尔的变形魔棒离完整又近了一步。莎尔蒂恩知道它的铁杆藏在哪里，就在费伍德森林边界附近的一只箱子里。搜寻之路通向那些因腐化而改变的树人。",kw={"灰谷","疯狂的古树","达图尔的魔棒","费伍德森林","铁杆","月亮井","莱恩的净化","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="费伍德森林不断侵袭的污染让古树陷入疯狂，这令人想起翡翠梦境为治愈满目疮痍的地表世界所作的抗争。",["faction:Alliance"]="腐化熊怪与恶魔势力的敌对行动日益加剧，要保障灰谷北部道路的安全，重铸达图尔的遗物至关重要。",["race:NightElf"]="杀死Crazed Ancients令人痛苦万分。在恶魔的疫病毒害它们的灵魂之前，这些活着的树木曾是深受喜爱的伙伴，也是森林的守卫。"},sec={{t="枯败之地附近的碎片",b="莱恩·狼行者派你去找莎尔蒂恩，她守护着灰谷深处的一口月亮井。莎尔蒂恩知道达图尔的变形魔棒的铁杆在哪里，但要拿到它，就必须面对北部林地中蔓延的污染。铁杆锁在一只旧箱子里，箱子位于费伍德森林边界附近一片幽静的林间空地上。"},{t="堕落的守护者",b="打开箱子需要木制钥匙，而钥匙就在疯狂的古树和枯萎的古树手中。这些树人在通往北方费伍德森林的山路上游荡，从恶魔荒土向南蔓延的腐化打破了它们与自然的和谐。它们曾是荒野的守护者，如今却饱受折磨，充满敌意，而钥匙就在它们身上。"}},faq={{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位树妖，居于灰谷一口僻静的月亮井旁，那里位于阿斯特兰纳以东、费伍德森林道路以南。她了解森林的历史和达图尔的古老技艺，并为试图修复魔棒的人提供指引。",al={"莎尔蒂恩","月亮井的守护者是谁","莎尔蒂恩的故事"}},{q="树人为何遭到腐化？",a="第三次大战遗留的恶魔污染仍在从费伍德森林向南蔓延，侵入灰谷。它侵蚀着北部山脊一带的树人，让这些古老的守护者陷入疯狂，也扭曲了它们与大地的联系。",al={"腐化的树人","树人为何发疯","疯狂的古树的故事"}},{q="达图尔的变形魔棒是什么？",a="达图尔的变形魔棒是一件附有魔法的遗物，由如今已经死去的邪恶巫师达图尔制成。组装并净化后，它能将持有者伪装成熊怪，莱恩需要借助这种力量调查当地的部族。",al={"达图尔的魔棒","变形魔棒","魔棒有什么作用"}},{q="隐藏的箱子在哪里？",a="装着铁杆的破旧箱子位于一片幽静的小林间空地上，就在那条从灰谷向北攀升、通往费伍德森林的山路西侧。",al={"破旧箱子的位置","铁杆在哪里","箱子在哪里"}},{q="莎尔蒂恩为何哀悼树人？",a="莎尔蒂恩为树人哀伤，因为它们是卡多雷森林亘古以来的看护者，被尊为神圣的自然之灵。它们的疯狂与腐化尚无已知的治愈之法，因此，结束它们的生命带来的是悲伤，而非恶意。",al={"莎尔蒂恩与树人","莎尔蒂恩为何悲伤"}},{q="这项任务在整个净化任务线中处于什么位置？",a="莱恩的净化要收集达图尔那根断裂魔棒的各个部件。集齐铁杆和其他部件后，接下来就要净化魔棒中残留的魔法。",al={"莱恩的净化任务线","莱恩任务线"}}},fp="17,207,26.301.0,20.315.0,18.218.0,30.199.0,21.197.1,34.147.0,38.225.0,54.175.0"}
P.entries["quest:1027"] = {n="莱恩的净化",s="在灰谷，莱恩·狼行者与莎尔蒂恩正在寻找达图尔的变形魔棒的最后一块部件。她们希望这件遗物能帮助净化森林，减缓熊怪对当地暗夜精灵的袭击。",h="在灰谷，莱恩·狼行者与莎尔蒂恩正在寻找达图尔的变形魔棒的最后一块部件。她们希望这件遗物能帮助净化森林，减缓熊怪对当地暗夜精灵的袭击。",kw={"灰谷","达图尔的魔棒","朵丹尼尔","铁质柄头","月亮井","莱恩的净化","莎尔蒂恩"},ang={["class:Druid"]="身为德鲁伊，当你踏上朵丹尼尔遭到亵渎的土地时，便能看到塞纳里奥议会和Kaldorei德鲁伊在灰谷蒙受的损失。",["faction:Alliance"]="身为联盟的一员，你知道，随着部落军队从碎木推进，灰谷抵御腐化的战斗关系到联盟对卡利姆多北部的控制。",["race:NightElf"]="身为暗夜精灵，寻回达图尔的传世之物，是对朵丹尼尔逝去的守护者的缅怀，也是对古老Kaldorei土地的捍卫。"},sec={{t="朵丹尼尔的废墟",b="达图尔的变形魔棒的铁质柄头曾交由朵丹尼尔兽穴的暗夜精灵德鲁伊保管。灾难降临了这片圣地，守护者惨遭杀害。随着庇护所沦陷，柄头的藏匿之处也无人知晓。如今，食腐动物和游荡的软泥怪正吞噬着南部道路以东废墟中的残存之物。"},{t="重铸达图尔的遗物",b="达图尔是一名已经死去的邪恶巫师，但他制造的法杖拥有变形之力。莱恩·狼行者与莎尔蒂恩正在设法将它重新拼合，希望借此减缓熊怪对灰谷暗夜精灵的袭击。铁质柄头是莎尔蒂恩所需的最后一块部件，找到它后，她才能尝试在月亮井边修复断裂的法杖。"}},faq={{q="铁质柄头是什么？",a="铁质柄头是达图尔的魔棒的最后一块部件。没有它，就无法重铸这件遗物，也无法引导它的力量净化灰谷。",al={"铁质柄头","法杖最后的部件","柄头是什么"}},{q="朵丹尼尔的德鲁伊遭遇了什么？",a="朵丹尼尔兽穴的德鲁伊在圣地沦陷时惨遭杀害。他们的庇护所如今已被遗弃，只有软泥怪和野兽潜伏其中，而谈及他们的命运令莎尔蒂恩深感痛苦。",al={"朵丹尼尔德鲁伊","谁杀害了德鲁伊","朵丹尼尔"}},{q="朵丹尼尔位于何处？",a="朵丹尼尔位于灰谷南部，在通往贫瘠之地边界的大路以东，碎木岗哨以南。",al={"朵丹尼尔在哪里","朵丹尼尔位置"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一名树妖，照料着灰谷的一口神圣月亮井。她帮助莱恩·狼行者寻找达图尔的魔棒散落的部件，并指导修复工作。",al={"莎尔蒂恩","莎尔蒂恩是谁"}},{q="柄头为何被软泥怪吞下？",a="兽穴沦陷后，胶状的软泥怪侵占了这片地区，吞噬了被遗弃的遗物、箱子和尸体。软泥怪将铁质柄头连同其他残骸一并吞了下去。",al={"软泥怪箱子","柄头软泥怪","软泥怪为何有它"}},{q="找到柄头之后会怎样？",a="当你将柄头交还给莎尔蒂恩，她就能开始修复法杖。修复之后，它就能帮助莱恩·狼行者净化森林。",al={"下一步","莎尔蒂恩做什么"}}},fp="17,174,22.281.0,26.328.0,24.127.0,41.175.0,27.117.0,18.155.0,37.172.0,38.136.0"}
P.entries["quest:1028"] = {n="莱恩的净化",s="在莎尔蒂恩的指引下，莱恩的净化如今引领你带着重铸的达图尔的变形魔棒前往一座山中神殿。那里的石盆蕴藏着恢复法杖附魔所需的魔力。",h="在莎尔蒂恩的指引下，莱恩的净化如今引领你带着重铸的达图尔的变形魔棒前往一座山中神殿。那里的石盆蕴藏着恢复法杖附魔所需的魔力。",kw={"灰谷","石盆","达图尔的魔棒","隐藏的神殿","月亮井","莱恩的净化","重铸的法杖","莎尔蒂恩"},ang={["class:Druid"]="身为德鲁伊，你能感受到神殿微妙的共鸣，它映照着暗夜精灵古老技艺与自然原始能量之间的深厚联系。",["faction:Alliance"]="身为联盟的一员，你通过修复这件遗物，帮助莱恩·狼行者保卫阿斯特兰纳，并治愈卡利姆多北部遭到腐化的土地。",["race:NightElf"]="身为暗夜精灵，你能看出灰谷隐于山中的神殿，是先祖在近世入侵发生之前，于荒野中建造的宁静圣地。"},sec={{t="通往高处的小径",b="莎尔蒂恩让你离开她的月亮井，前往灰谷东南部荒野中的山坡。灰谷的古老神殿往往坐落在高耸的山崖间，远离道路，隐于茂密的林冠之下。你必须沿着岩壁穿过没有路标的荒地，攀上蜿蜒的小径，这些路径大多只有哨兵和林中隐士才知晓。"},{t="修复达图尔的变形魔棒",b="一只石盆静静地坐落在林中幽静的角落。神殿虽已沉寂，却仍蕴藏着暗夜精灵在很久以前留下的守护魔法。将重铸的达图尔的变形魔棒放入石盆，神殿沉睡的力量便会苏醒。魔力流入法杖，恢复其附魔，使它能够净化这片土地。"}},faq={{q="隐藏的神殿在哪里？",a="神殿位于莎尔蒂恩的月亮井东南方的群山中。离开大路，沿着岩石峭壁前行，寻找一条蜿蜒通向山脊的小径。",al={"神殿位置","神殿在哪里","如何找到神殿","隐藏神殿的路径"}},{q="达图尔是谁？",a="达图尔是一名邪恶的巫师，他制造了这根法杖，如今已经死去。莱恩希望借助法杖的魔力，调查灰谷的熊怪袭击事件。",al={"达图尔是谁","达图尔的故事","法杖的制造者"}},{q="为什么要将达图尔的魔棒放入神殿？",a="莎尔蒂恩能够重铸断裂的法杖，但它古老的附魔已经耗尽。隐藏的神殿蕴藏着未受侵扰的自然魔法，能够恢复它的力量。",al={"为何给法杖充能","法杖用途","神殿有什么作用"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一名树妖，住在灰谷东部一口幽静的月亮井旁。她帮助莱恩·狼行者研究可能净化受污染荒野的遗物与仪式。",al={"莎尔蒂恩","任务给予者","月亮井旁的女祭司"}},{q="法杖重新充能后会怎样？",a="神殿恢复法杖的力量后，你便可以将它交还给莎尔蒂恩，用于莱恩对灰谷熊怪的调查。",al={"接下来做什么","神殿之后","下一步"}},{q="神殿有守卫吗？",a="神殿是一处宁静的圣地，但野兽和堕落的熊怪部族在周围的山林中游荡，让攀登之路危机四伏。",al={"神殿有怪物吗","神殿的危险"}}},fp="17,158,23.316.0,22.306.0,35.163.0,15.144.0,54.162.0,18.173.0,40.132.0,22.147.0"}
P.entries["quest:1029"] = {n="莱恩的净化",s="在伊瑞斯湖，莎尔蒂恩将为阿斯特兰纳的莱恩·狼行者修复的达图尔的变形魔棒交给你。你带着魔棒返回，报告任务成功的消息，并向牺牲的斥候泰洛尼斯致敬。",h="在伊瑞斯湖，莎尔蒂恩将为阿斯特兰纳的莱恩·狼行者修复的达图尔的变形魔棒交给你。你带着魔棒返回，报告任务成功的消息，并向牺牲的斥候泰洛尼斯致敬。",kw={"灰谷","阿斯特兰纳","达图尔的魔棒","莱恩·狼行者","莱恩的净化","莎尔蒂恩","泰洛尼斯"},ang={["faction:Alliance"]="作为联盟旅人，帮助莱恩·狼行者会提升你在阿斯特兰纳深居简出的Sentinels中的声望。",["race:NightElf"]="作为暗夜精灵，继承泰洛尼斯的遗志让阿斯特兰纳得以告慰，也表明即使卡利姆多的神圣林地面临日益严重的威胁，牺牲的同胞仍被铭记。"},sec={{t="魔棒重铸",b="达图尔的变形魔棒已用从灰谷受腐化地区收集的部件和古老宝石碎片重新铸成。在伊瑞斯湖附近，树妖莎尔蒂恩净化并恢复了它的魔力，随后让你沿林间道路前往阿斯特兰纳。莱恩·狼行者正等待着这件修复的神器。"},{t="纪念泰洛尼斯",b="泰洛尼斯最初寻找达图尔的魔棒，是希望借此遏制熊怪对他族人的袭击。他是莱恩的多年挚友，却在法拉希姆湖的岛上被鱼人杀害，那些鱼人夺走了他寻找的宝石。将修复的魔棒带给莱恩，是一场悲喜交织的胜利，也让泰洛尼斯的牺牲有了意义，尽管他未能亲眼见证使命完成。"}},faq={{q="达图尔的变形魔棒是什么？",a="达图尔的变形魔棒是已故邪恶巫师达图尔制造的一根魔棒。修复后，它可以帮助莱恩调查灰谷的熊怪袭击事件。",al={"达图尔的魔棒","魔棒有什么作用"}},{q="泰洛尼斯是谁？",a="泰洛尼斯是一名年轻的暗夜精灵哨兵，莱恩·狼行者派他在灰谷寻找蕴含古老魔法的部件。鱼人夺走了他寻找的宝石，并在法拉希姆湖的岛上杀害了他，留下路过的联盟旅人完成他的使命。",al={"泰洛尼斯是谁","泰洛尼斯之死"}},{q="莱恩·狼行者是谁？",a="莱恩·狼行者是一位经验丰富的暗夜精灵哨兵指挥官，驻守在阿斯特兰纳中心。她负责灰谷中部的防御，抵御恶魔的污染、敌对的萨特和遭到腐化的当地野兽。",al={"莱恩","莱恩·狼行者"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一名树妖，住在伊瑞斯湖以东的月亮井附近。她熟知森林及其中的古老遗物，能够净化受腐化的遗物，并修复蕴含力量的古老器具。",al={"莎尔蒂恩","伊瑞斯湖女祭司"}},{q="这个任务发生在哪里？",a="你从灰谷中部的伊瑞斯湖畔出发，沿主要道路向西前往阿斯特兰纳，那是这片地区最主要的联盟据点。",al={"任务地点","去哪里"}},{q="将魔棒交给莱恩后会发生什么？",a="泰洛尼斯的最后一次任务取得成功，让莱恩感到欣慰和自豪。灰谷的净化仍在继续，她正在寻找运用魔棒力量的方法，以对抗林地中挥之不去的腐化。",al={"下一个任务","莱恩的净化后续"}}},fp="17,165,16.293.0,16.348.1,39.170.0,16.263.0,24.203.0,18.188.0,33.133.0,47.188.1"}
P.entries["quest:103"] = {n="长明的灯塔",s="葛瑞森船长在西部荒野灯塔守望着海岸。鱼人杀害了活着的守塔人后，他便寻求灯油，让灯火继续燃烧，指引船只安全驶过暗礁。",h="葛瑞森船长在西部荒野灯塔守望着海岸。鱼人杀害了活着的守塔人后，他便寻求灯油，让灯火继续燃烧，指引船只安全驶过暗礁。",kw={"灯火","葛瑞森船长","一瓶油","无尽之海","收割怪物","老瞎眼","西部荒野灯塔"},ang={["faction:Alliance"]="西部荒野的灯火帮助驶向暴风城港口的商船和军舰避开王国日渐崩塌的海岸，免于搁浅。",["profession:Engineering"]="游荡在西部荒野农场里的看守傀儡携带着易挥发的机械液体，可以用来点燃提灯。"},sec={{t="幽灵的职责",b="西部荒野灯塔坐落在西部荒野西南岸外的一座岩石小岛上。它的灯光曾指引水手穿过无尽之海的浅水区。后来，老瞎眼率领鱼人发动袭击，杀害了守塔人及其家人，这项职责也随之中断。葛瑞森船长死于这些岩石旁的水域，如今化作幽灵守望着灯塔。他生前未能阻止那场屠杀，但他绝不会让灯塔的光芒熄灭。"},{t="为灯火添油",b="已经没有活着的守塔人照料灯火，因此葛瑞森船长需要一种不同寻常的燃料。看守傀儡游荡在西部荒野荒废的农田里，锈蚀的躯体内装着一瓶瓶机械油。格雷森派你上岸，从这些破损的构造体身上取回油。有了这些油，灯火就能继续燃烧，指引船长们驶过暗礁。"}},faq={{q="葛瑞森船长是谁？",a="葛瑞森船长是一名水手的幽灵，他因船只失事而葬身于西部荒野险恶的海岸。他守望着西部荒野灯塔，帮助仍活着的水手避开同样的命运。",al={"葛瑞森船长","灯塔幽灵","西部荒野灯塔的幽灵是谁"}},{q="原来的守塔人遭遇了什么？",a="老瞎眼率领鱼人发动袭击，杀害了守塔人及其家人。化作幽灵的葛瑞森船长只能无助地看着这一切。",al={"守塔人遭遇了什么","谁杀害了守塔人","守塔人一家遇害"}},{q="灯塔燃烧所需的油从哪里来？",a="游荡在西部荒野荒废农场和田地里的看守傀儡携带着灯塔所需的油。",al={"哪里获取灯油","收割怪物的油","一瓶油"}},{q="格雷森为什么如此在意让灯火长明？",a="格雷森希望灯火能指引水手穿越无尽之海，避开沿岸的礁石。他就死在那些暗礁上，如今守望着灯塔。",al={"为何点燃火炬","格雷森的动机","灯塔火焰的用途"}},{q="老瞎眼是谁？",a="老瞎眼是一个臭名昭著的鱼人，在西部荒野海岸游荡，率众袭击沿岸聚落。他手下的袭击者杀害了守塔人及其家人。",al={"老瞎眼","瞎眼","西部荒野鱼人首领"}},{q="西部荒野灯塔在哪里？",a="西部荒野灯塔坐落在西部荒野西南海岸外的一座岩石小岛上。你可以游过沿岸的浅水区抵达那里。",al={"灯塔位置","西部荒野灯塔在哪里","寻找灯塔"}}},fx={["44c879dd"]={q="为什么灯塔的燃油要从 麦田傀儡 身上获取？",a="游荡在西部荒野废弃农田中的机械造物 麦田傀儡，靠一瓶瓶重型机械油运转。灯塔看守人的一家已经遇害，正常的补给线路也已中断，葛瑞森船长只能依靠从这些失控的自动机械身上回收的燃料，维持灯塔的信号火焰。",al={"麦田魔像 的燃油","为何从 麦田傀儡 获取燃油","麦田魔像 目标"}},cbe3424a={q="葛瑞森船长为什么需要你帮忙，而不亲自收集燃油？",a="葛瑞森船长是一个不得安息的幽灵，被束缚在西部荒野灯塔附近。他的灵魂无法前往内陆，亲自猎杀那些失控的 麦田傀儡，因此只能依靠路过的冒险者深入农田，收集维持灯塔所需的燃料。",al={"葛瑞森为何需要冒险者","葛瑞森为何无法获取燃油","葛瑞森为何选择冒险者"}}},fp="19,185,15.419.0,18.348.0,23.190.0,49.131.0,54.98.0,51.150.0,20.161.0,41.145.0"}
P.entries["quest:1030"] = {n="莱恩的净化",s="在灰谷，莱恩·狼行者正设法与未受腐化的熊怪交谈。在密斯特拉湖东南方，克罗格让人难得地窥见了幸存熊怪对暗夜精灵的怨恨。",h="在灰谷，莱恩·狼行者正设法与未受腐化的熊怪交谈。在密斯特拉湖东南方，克罗格让人难得地窥见了幸存熊怪对暗夜精灵的怨恨。",kw={"灰谷","达图尔的变形魔棒","魔苔","熊怪","克罗格","密斯特拉湖","莱恩·狼行者","莱恩的净化"},ang={["class:Druid"]="对德鲁伊而言，熊怪的困境令人深感悲痛：他们曾是自然的亲密盟友，如今却因挥之不去的恶魔腐化而饱受疯狂折磨。",["faction:Alliance"]="对联盟而言，阿斯特兰纳能否存续，取决于能否查明边境道路沿线的危险。这场秘密会面有助于保卫灰谷东部。",["race:NightElf"]="对暗夜精灵而言，克罗格的话表明，灰谷的许多原住民都认为 Kaldorei 行事鲁莽，屡次为这片土地招来毁灭，而非守护这片土地。"},sec={{t="毛皮与利爪的伪装",b="莱恩·狼行者相信，那位已故的暗夜精灵原本打算用修复后的达图尔的变形魔棒，伪装成熊怪接近他们。灰谷的林地已变得危机四伏，疯狂在各个部族中蔓延，直接交涉已无可能。魔棒能让你化身为熊怪，借此尝试避开他们对领地入侵者的怒火，找到愿意交谈的对象。"},{t="流亡者的怨恨",b="在密斯特拉湖东南方，克罗格远离族人独自生活，未受魔苔侵染。他以为你也是同族，便毫无顾忌地诉说自己的流亡与悲伤。他并不把暗夜精灵视为盟友或保护者。相反，他认为，正是他们的傲慢与昔日的过错，导致恶魔的腐化肆虐他的族群。"}},faq={{q="达图尔的变形魔棒有什么作用？",a="达图尔的变形魔棒能让持有者短暂变成熊怪。这层伪装让你能接近未受腐化的熊怪，而不至于立刻遭到攻击。",al={"魔棒有什么作用","达图尔的变形魔棒","熊怪伪装魔棒"}},{q="克罗格是谁？",a="克罗格是一名未受腐化的熊怪，流亡在密斯特拉湖东南方。他躲过了侵染族人的魔苔，独居在一条沿岸插着火把的溪流对岸，哀悼失去的部族，怨恨着暗夜精灵。",al={"克罗格是谁","未受腐化的熊怪 密斯特拉湖","密斯特拉湖东南方的熊怪"}},{q="为什么不用魔棒，克罗格就会攻击？",a="克罗格惧怕外来者，也不信任他们，尤其是暗夜精灵，他认为他们应为族人的衰亡负责。没有魔棒的伪装，他就会把你当作入侵者，为保卫营地而发动攻击。",al={"克罗格为什么攻击","克罗格主动攻击","为什么对克罗格使用魔棒"}},{q="克罗格为什么将腐化归咎于暗夜精灵？",a="克罗格将肆虐森林的恶魔腐化归咎于暗夜精灵的傲慢。他认为，古代 卡多雷 滥用奥术，给卡利姆多带来了毁灭，却让这片土地上的原住部族承受苦难。",al={"克罗格为什么憎恨暗夜精灵","熊怪责怪暗夜精灵","克罗格对暗夜精灵的仇恨"}},{q="在哪里能找到克罗格？",a="克罗格住在灰谷的密斯特拉湖东南方。一条蜿蜒的土路沿途插着燃烧的火把，穿过一条小溪，通往他独居的营地。",al={"克罗格在哪里","克罗格位置","寻找未受腐化的熊怪"}},{q="魔苔是什么，又如何影响了熊怪？",a="魔苔是一种在灰谷蔓延的恶魔滋生物，侵染着土壤与植物。在它的影响下，当地的熊怪部族陷入暴戾的疯狂，社会也随之分崩离析。",al={"魔苔是什么","魔苔 熊怪","熊怪为什么发疯"}}},fp="17,189,23.363.0,22.316.1,44.164.0,13.225.0,47.193.0,56.201.0,25.152.0,52.178.0"}
P.entries["quest:1031"] = {n="塞纳留斯的树枝",s="在灰谷东部，安妮莉亚临终前的恳求让你踏上了寻回塞纳留斯的树枝的道路。加萨里斯夺走了这件圣物，伊莉亚娜正等待它归来。",h="在灰谷东部，安妮莉亚临终前的恳求让你踏上了寻回塞纳留斯的树枝的道路。加萨里斯夺走了这件圣物，伊莉亚娜正等待它归来。",kw={"安妮莉亚","灰谷树妖","塞纳留斯的树枝","加萨里斯","伊莉亚娜","夜道谷","萨特"},ang={["class:Druid"]="身为德鲁伊，你视塞纳留斯的遗物为圣物，因为他教导了最早的凡人德鲁伊。从受恶魔污染的萨特手中夺回他的树枝，是你在信仰上义不容辞的责任。",["faction:Alliance"]="身为联盟的一员，你可以帮助灰谷的树妖，抵御荒野东部的恶魔威胁。",["race:NightElf"]="身为暗夜精灵，你深知塞纳留斯的女儿们是备受爱戴的盟友。为安妮莉亚复仇，清除那些亵渎你祖辈森林的萨特。"},sec={{t="临终的请求",b="你在灰谷东部寻找失踪的树妖时，发现安妮莉亚已奄奄一息。这位身负重伤的塞纳留斯之女指向北方的萨特废墟。她用最后的气息说出，夺走塞纳留斯的树枝的是加萨里斯，并恳求你将它夺回。"},{t="废墟中的腐化",b="加萨里斯藏身于萨维亚的古老精灵废墟之中。萨特是燃烧军团的古老仆从，他们将与塞纳留斯有关的圣物视为珍贵的战利品，肆意亵渎和嘲弄。从加萨里斯手中夺回树枝，既能回应安妮莉亚的恳求，也能帮助保护灰谷的神圣植物，使其免受这些仆从散播的腐化侵蚀。"},{t="树妖的悲痛",b="你将树枝交还给伊莉亚娜，但安妮莉亚已经逝去。这件圣物免遭恶魔腐化，而安妮莉亚的死讯让她尚在人世的同胞悲痛不已。灰谷的树妖必须面对战争，以及周围步步紧逼的腐化。"}},faq={{q="塞纳留斯的树枝是什么？",a="塞纳留斯的树枝是一件与森林之王塞纳留斯有关的自然圣物，深受他的树妖女儿们珍爱。萨特夺走了它，安妮莉亚在带领姐妹们夺回圣物时受了致命伤；她用最后一口气说出，窃贼就是加萨里斯。",al={"塞纳留斯的树枝圣物","树枝是什么","塞纳留斯的树枝"}},{q="谁杀死了安妮莉亚？",a="安妮莉亚试图夺回塞纳留斯的树枝时，在萨特占据的萨维亚废墟中受了致命伤。她临终前说出，夺走树枝的萨特就是加萨里斯。",al={"安妮莉亚的凶手","谁袭击了安妮莉亚","谁杀死了树妖"}},{q="加萨里斯在哪里？",a="加萨里斯藏在萨维亚废墟中，就在安妮莉亚临终所在之处的北方。",al={"加萨里斯位置","寻找加萨里斯","在哪里击杀加萨里斯"}},{q="找回塞纳留斯的树枝后，该把它送到哪里？",a="将找回的树枝交给灰谷艾森娜神殿的伊莉亚娜。",al={"交还塞纳留斯的树枝","伊莉亚娜位置","树枝交给谁"}},{q="萨特为什么想要塞纳留斯的圣物？",a="萨特是因恶魔契约而发生转变的古代暗夜精灵。他们憎恨自然和塞纳留斯，偷窃或腐化圣物既能为恶魔主人效力，也能宣泄他们对昔日同胞的怨恨。",al={"萨特的动机","为什么偷塞纳留斯的树枝","加萨里斯为什么夺走它"}},{q="安妮莉亚与伊莉亚娜是什么关系？",a="安妮莉亚和伊莉亚娜是亲密的树妖伙伴，也是情同手足的姐妹，在灰谷的荒野中自由奔跑、嬉戏了无数个日夜，直到腐化带来的危险夺去了安妮莉亚的生命。",al={"安妮莉亚与伊莉亚娜","树妖是姐妹吗"}}},fp="22,156,15.261.0,23.320.0,23.222.1,31.265.0,18.177.0,27.69.0,60.76.0,44.199.0,27.189.0"}
P.entries["quest:1032"] = {n="猎杀萨特！",s="在艾森娜神殿，伊莉亚娜请求联盟勇士打击灰谷的萨特。她为妹妹安妮莉亚的死悲痛不已，一心寻求复仇，并请你带回萨特的角作为证明。",h="在艾森娜神殿，伊莉亚娜请求联盟勇士打击灰谷的萨特。她为妹妹安妮莉亚的死悲痛不已，一心寻求复仇，并请你带回萨特的角作为证明。",kw={"安妮莉亚","灰谷","树妖","伊莉亚娜","萨特","萨特的角","猎杀萨特"},ang={["class:Druid"]="身为德鲁伊，为死去的树妖复仇并取下恶魔萨特的角，就是在打击塞纳留斯所钟爱的荒野中的腐化。",["faction:Alliance"]="身为联盟勇士，你帮助削减萨特的数量，让灰谷的森林少受周围荒野威胁的侵扰。",["race:NightElf"]="身为暗夜精灵，你知道萨特是耻辱的象征，提醒着族人上层精灵在远古堕落为邪能奴仆的往事。帮助伊莉亚娜，就是清除这片土地上先祖遗留的祸患。"},sec={{t="树妖的悲痛",b="安妮莉亚的死让身在艾森娜神殿的伊莉亚娜陷入悲痛。树妖是与自然紧密相连的森林之灵，通常活泼而宁静，凡人很难寻见她们的踪迹。安妮莉亚惨遭杀害，打破了姐姐心中的宁静。如今，伊莉亚娜向联盟旅人求助，请他们消灭那些犯下暴行的恶魔野兽。"},{t="堕落的同族",b="萨特曾是暗夜精灵，却在上古之战期间遭到恶魔能量的腐化。他们潜伏在灰谷各处遭到亵渎的林地中，作为燃烧军团的仆从，残害森林中的居民。将他们的角带给伊莉亚娜，既能证明复仇已成，也能打击正在侵入灰谷东部的邪能力量。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是一名树妖，居住在灰谷的艾森娜神殿。她天性温和，如今正哀悼被当地萨特杀害的妹妹安妮莉亚。",al={"伊莉亚娜背景","任务发布者是谁","林歌神殿树妖"}},{q="安妮莉亚是谁？",a="安妮莉亚是一名树妖，也是伊莉亚娜深爱的妹妹。她们曾在灰谷古老的树冠下度过漫长岁月，直到萨特伏击并杀害了安妮莉亚。",al={"安妮莉亚","伊莉亚娜的妹妹","谁死了"}},{q="伊莉亚娜为什么索要萨特的角？",a="伊莉亚娜索要萨特的角，是为了证明杀害安妮莉亚的生物已经被消灭。她希望这能让妹妹的灵魂得到安宁。",al={"为什么要萨特的角","萨特的角证明"}},{q="萨特是什么？",a="萨特是暗夜精灵在上古之战期间受到燃烧军团的恶魔力量腐化后变成的生物。他们栖居在腐化的聚居地中，散播污秽，残害森林之灵。",al={"萨特背景","灰谷的萨特是什么"}},{q="林歌神殿在哪里？",a="林歌神殿是一处古老、近乎荒废的暗夜精灵废墟，位于灰谷最东部，靠近艾萨拉边界。伊莉亚娜在艾森娜神殿等候，并不在林歌神殿。",al={"林歌神殿位置","林歌神殿在哪里"}},{q="这与其他狩猎任务有关吗？",a="即使安妮莉亚的大仇得报，伊莉亚娜仍会继续收取萨特的角。灰谷的守卫者依然在努力将萨特逐出森林。",al={"萨特的角任务","后续任务","可重复萨特任务"}}},fp="14,170,15.293.0,17.325.0,16.139.0,15.143.0,38.150.0,16.196.0,21.173.0,37.135.0"}
P.entries["quest:1033"] = {n="月神之泪",s="在阿斯特兰纳，皮尔图拉斯·怀特姆恩正为患病的女儿蕾拉寻找解药。用巴斯兰的头发熬制的药剂减缓了她的病情，却未能根除病根。他请你从伊瑞斯湖带回月神之泪，希望它的神圣力量能驱除她体内的腐化。",h="在阿斯特兰纳，皮尔图拉斯·怀特姆恩正为患病的女儿蕾拉寻找解药。用巴斯兰的头发熬制的药剂减缓了她的病情，却未能根除病根。他请你从伊瑞斯湖带回月神之泪，希望它的神圣力量能驱除她体内的腐化。",kw={"灰谷","阿斯特兰纳","解药","艾露恩","月神之泪","伊瑞斯湖","奥雷迪尔·阔叶","皮尔图拉斯·怀特姆恩","蕾拉","水元素"},ang={["class:Druid"]="身为德鲁伊，你熟悉灰谷的水域，也了解那些守卫着伊瑞斯湖宁静湖心、反复无常的元素生物。",["class:Priest"]="身为虔诚信奉Elune的牧师，你明白，当祈祷需要借助实物时，人们会寄望于神圣遗物，以对抗黑暗而违背自然的瘟疫。",["faction:Alliance"]="身为联盟的一员，在危险蔓延至灰谷各处之际，你帮助阿斯特兰纳的守卫者渡过家中的危机。",["race:NightElf"]="身为暗夜精灵，你深知人们相信以月神之名命名的圣石，也相信Elune的恩泽能够净化寻常药物无法触及的创伤。"},sec={{t="父亲日益加深的恐慌",b="皮尔图拉斯·怀特姆恩年幼的女儿蕾拉在阿斯特兰纳身患重病。他原本希望用巴斯兰的头发熬制的药剂能治好她，但奥雷迪尔·阔叶的药剂虽然减缓了病情，却未能根除她体内的病根。寻常药物已不足以治好她。如今，皮尔图拉斯转而求助于族人的古老传统，寻找蕴含神圣净化之光的解药。"},{t="伊瑞斯湖的圣石",b="奥雷迪尔·阔叶曾提到，如果草药熬制的药剂无效，还有一种更强的解药：月神之泪，那是一块位于阿斯特兰纳以东、伊瑞斯湖岛上的圣石。暗夜精灵相信，这块石头蕴含月神的祝福，能够净化生灵体内的腐化。躁动不安的水元素在湖泊的浅滩和岸边巡游，守卫着这片水域。"},{t="一线希望",b="当你把圣石带回阿斯特兰纳时，皮尔图拉斯打算将它浸入给蕾拉熬制的药汤中。他向你道谢，但腐化仍未消退，她的生命依然危在旦夕。"}},faq={{q="月神之泪是什么？",a="月神之泪是一块圣石，位于灰谷伊瑞斯湖的湖心岛上。暗夜精灵的传说称，它能清除剧毒和挥之不去的腐化。",al={"月神之泪是什么","月神之泪物品","伊瑞斯湖的圣石"}},{q="奥雷迪尔先前的解药为何没能奏效？",a="奥雷迪尔·阔叶用巴斯兰的头发熬制的药剂减缓了蕾拉的病情，却无法将她治愈。草药的效力不足，皮尔图拉斯便转而寻求神圣的解药。",al={"奥雷迪尔的解药为何无效","奥雷迪尔的解药有效吗","蕾拉仍然患病"}},{q="伊瑞斯湖在哪里？",a="伊瑞斯湖位于灰谷，在阿斯特兰纳以东。沿大路向东出城，再沿着一条注入湖泊的溪流旁的土路向北走。",al={"伊瑞斯湖在哪里","伊瑞斯湖位置","如何找到伊瑞斯湖"}},{q="伊瑞斯湖周围潜伏着什么危险？",a="伊瑞斯湖及其湖心岛上栖息着领地意识强烈的水元素。任何想靠近岛屿、取得月神之泪的人，都必须经过这些充满敌意的自然之灵。",al={"伊瑞斯湖敌人","伊瑞斯湖有什么会发动攻击"}},{q="皮尔图拉斯打算如何使用这块圣石？",a="皮尔图拉斯打算将月神之泪浸入给女儿蕾拉熬制的药汤中，希望它的净化之力能驱除她的病痛。",al={"如何使用月神之泪","月神之泪药汤"}},{q="蕾拉·怀特姆恩是谁？",a="蕾拉·怀特姆恩是皮尔图拉斯·怀特姆恩年幼的暗夜精灵女儿，住在阿斯特兰纳。一股非自然的腐化使她身患重病，危及她的生命。",al={"蕾拉是谁","皮尔图拉斯的女儿"}}},fp="12,274,24.320.0,22.345.0,17.177.1,21.161.0,37.172.0,27.152.0,35.154.0,40.141.0,24.172.0"}
P.entries["quest:1034"] = {n="星尘废墟",s="在阿斯特兰纳，皮尔图拉斯·怀特姆恩仍在为女儿蕾拉寻找疗法。月神之泪缓解了她的梦魇，但高烧依然不退。奥雷迪尔·阔叶让他前往南方，在暗夜精灵的古老石迹间寻找能降温的星尘。",h="在阿斯特兰纳，皮尔图拉斯·怀特姆恩仍在为女儿蕾拉寻找疗法。月神之泪缓解了她的梦魇，但高烧依然不退。奥雷迪尔·阔叶让他前往南方，在暗夜精灵的古老石迹间寻找能降温的星尘。",kw={"灰谷","阿斯特兰纳","治疗","艾露恩","高烧","奥雷迪尔","皮尔图拉斯","敷药","蕾拉","星尘"},ang={["class:Druid"]="为了采集能缓解病痛的星尘，你要在被淹没的废墟中对抗躁动的水之灵。它们的存在表明，灰谷的平衡十分脆弱。",["class:Priest"]="Elune的恩典平息了蕾拉的梦魇，但要保全凡人的生命，肉体或许还需要在祈祷之外借助尘世的药物。",["profession:Herbalism"]="要在灌木间找到闪烁的粉末，就需要懂得辨认灰谷潮湿地带的珍稀植物。",["race:NightElf"]="阿斯特兰纳南面的废墟是古老kaldorei文明的遗迹。其中残存的魔法仍可用于治疗。"},sec={{t="父亲未消的绝望",b="皮尔图拉斯·怀特姆恩守在女儿蕾拉身旁，恶疾正灼烧着她的身体。月神之泪让她稍稍摆脱了梦魇的折磨，但病痛仍未消退。她依然备受高烧煎熬，寻常药物已无能为力。神殿的医者们分身乏术，皮尔图拉斯只得求助于源自自然的古老疗法，希望能救回她的性命。"},{t="星尘的微光",b="年迈的草药师奥雷迪尔·阔叶指引皮尔图拉斯前往星尘废墟，那里位于阿斯特兰纳南面的河对岸。在这座古老的卡多雷圣所中，覆霜般闪烁的尘埃落在倒塌的大理石柱与拱门之间的植物上。这种被称为星尘的粉末天生带有寒意，足以驱散异常的热度。皮尔图拉斯希望将它研磨成敷药，缓解蕾拉的高烧。"},{t="水中的潜伏者",b="水元素和野生动物让淹水石迹间的霜尘采集变得危险。灰谷的平衡发生变化，元素或遭腐化，或被惊扰，在灌木最茂密的沉水广场周围翻涌。你涉入看似平静的浅水，提防浑浊深处的伏击。必须从闪光的灌木上采集足够的纯净尘埃，带回阿斯特兰纳。"}},faq={{q="皮尔图拉斯为什么需要星尘？",a="皮尔图拉斯·怀特姆恩的女儿蕾拉在阿斯特兰纳高烧不退。月神之泪缓解了她的梦魇，但高烧依旧。奥雷迪尔·阔叶说，星尘废墟中覆霜般的尘埃可以制成敷药，为她降温。",al={"为何需要星尘","星尘废墟的用途","蕾拉高烧的疗法"}},{q="星尘废墟位于何处？",a="星尘废墟位于灰谷中部、阿斯特兰纳以南，环绕着一座小湖，四周是草木丛生的古老卡多雷石构遗迹。",al={"星尘废墟的位置","星尘废墟在哪里","寻找星尘废墟"}},{q="这里的星尘是什么？",a="星尘是积聚在湖边植被上的霜状尘埃。皮尔图拉斯希望利用它的降温功效制成敷药，缓解女儿的高烧。",al={"星尘是什么","星尘的性质","星尘的背景故事"}},{q="星尘能彻底治愈蕾拉吗？",a="皮尔图拉斯希望星尘敷药能让蕾拉退烧。能否让她完全恢复体力，要在治疗后才会知晓。",al={"星尘能治愈蕾拉吗","蕾拉痊愈","女孩获救了吗"}},{q="星尘废墟有哪些威胁？",a="凶猛的水元素潜伏在被淹废墟的水面之下，守卫着这片水域。任何涉过浅水、搜寻闪光灌木的人都会受到它们的威胁。",al={"星尘废墟的敌人","星尘废墟有什么会发起攻击"}},{q="奥雷迪尔是谁？",a="奥雷迪尔·阔叶是一位暗夜精灵草药师，住在灰谷北部的迈斯特拉岗哨附近。他研究当地植物已有数百年，在神殿的疗法力有不逮时，为皮尔图拉斯提供有关珍稀草药疗法的建议。",al={"谁告诉皮尔图拉斯有关星尘的事","奥雷迪尔·阔叶"}}},fp="21,249,28.347.0,21.391.0,22.392.0,32.229.0,40.134.0,33.144.0,41.133.1,48.178.0,15.227.0"}
P.entries["quest:1035"] = {n="坠星湖",s="坠星湖中的月亮石或许是蕾拉唯一的希望，她的高烧虽已退去，体力却几乎耗尽。她的父亲皮尔图拉斯·怀特姆恩派你前往阿斯特兰纳东南方的湖水，那里有一只腐化的沼泽兽智者守着陨落的石头。",h="坠星湖中的月亮石或许是蕾拉唯一的希望，她的高烧虽已退去，体力却几乎耗尽。她的父亲皮尔图拉斯·怀特姆恩派你前往阿斯特兰纳东南方的湖水，那里有一只腐化的沼泽兽智者守着陨落的石头。",kw={"灰谷","阿斯特兰纳","陨落的月亮石","坠星湖","皮尔图拉斯·怀特姆恩","蕾拉","沼泽兽智者"},ang={["class:Druid"]="敌对的沼泽兽沼泽兽表明，可悲的失和正蔓延于灰谷的自然守护者之间。对那些寻求恢复平衡的人来说，与它们交战令人心情沉重。",["class:Priest"]="人们寻求陨落的月亮石，是为了其中的神圣能量。它们的治愈恩泽与月亮女神 Elune 相连，能够帮助挽救一个垂死的孩子。",["faction:Alliance"]="帮助皮尔图拉斯·怀特姆恩，也是在支持联盟履行职责，保护阿斯特兰纳的居民，抵御逐渐侵蚀灰谷的腐化。",["race:NightElf"]="对 Kaldorei 而言，保护阿斯特兰纳的孩子是整个族群共同承担的神圣职责。取回蕴含 Elune 祝福的月亮石，是仁慈与虔敬之举。"},sec={{t="女儿渐弱的气息",b="皮尔图拉斯·怀特姆恩眼看着年幼的女儿蕾拉在连日的病痛中一步步走向死亡。用巴斯兰的头发和星尘制成的药物退去了她的高烧，却让她的身体虚弱不堪。皮尔图拉斯担心她只剩下几息可活，随后灵魂便会永远消逝在黑夜之中。"},{t="陨落的月亮石",b="皮尔图拉斯寄望于月亮石，希望它能恢复蕾拉的体力。这些来自天际的碎片曾坠入阿斯特兰纳东南方的坠星湖，暗夜精灵曾采集它们，用于疗伤。如今，凶暴的元素生物或腐化的树皮占据了这些石头，要取得一块，就得用刀剑与法术面对危险。"},{t="沼泽兽的领地",b="自从沼泽兽沼泽兽占据周围的荒野，暗夜精灵便难以再轻易进入坠星湖。它们的首领沼泽兽智者在湖心小岛上囤积着陨落的月亮石。要夺回一块，你必须在蕾拉的体力耗尽之前，迎战并杀死神谕。皮尔图拉斯将取回的石头碾碎，调入茶中，蕾拉饮下后恢复了体力。"}},faq={{q="蕾拉已经退烧，为什么还需要月亮石？",a="高烧严重耗损了蕾拉的生命力，仅靠休息已无法让她恢复。皮尔图拉斯相信，只有陨落的月亮石所蕴含的恢复之力，才能在她因衰竭而死之前，让她耗尽的精神重获生机。",al={"为什么需要月亮石","蕾拉 仍然患病","蕾拉 已退烧"}},{q="坠星湖在哪里？",a="坠星湖位于灰谷中东部，在阿斯特兰纳的东南方。敌对的沼泽兽盘踞在湖水中，湖中央有一座小岛。",al={"坠星湖在哪里","湖泊位置","沼泽兽 湖泊位置"}},{q="谁持有陨落的月亮石？",a="湖中敌对沼泽兽的首领沼泽兽智者持有月亮石。神谕的巢穴就在坠星湖中央的一座岛上。",al={"谁掉落月亮石","沼泽兽智者 位置","哪里获取月亮石"}},{q="这个任务之后会发生什么？",a="这是皮尔图拉斯寻找疗法的最后一步。他需要一块陨落的月亮石来恢复蕾拉的体力，送回石头后，她的命运便会揭晓。",al={"是否有后续任务","接下来是什么","任务后续"}},{q="沼泽兽 为什么囤积月亮石？",a="随着灰谷的野生生物和沼泽兽变得愈发狂躁、腐化，沼泽兽 开始以暴力驱逐外来者。它们的神谕收集并守护着这些月之遗物，不让阿斯特兰纳的暗夜精灵取得它们。",al={"树人为什么拿走石头","神谕 囤积月亮石"}},{q="哪些前置任务会引向这项任务？",a="这条任务线始于巴斯兰的头发，随后是奥雷迪尔的药剂、月神之泪和星尘废墟。每一步都要收集稀有材料，以治疗蕾拉日益恶化的病情。",al={"坠星湖前置任务线","前置任务","之前是什么任务"}}},fp="15,181,27.264.0,20.299.0,23.365.1,60.160.0,33.153.0,29.141.0,30.151.1,50.230.0,42.180.0"}
P.entries["quest:1037"] = {n="维琳德·星歌",s="在灰谷，梅丽瑞亚·霜影正在打听前任指挥官的消息。维琳德·星歌在对抗从费伍德森林蔓延而来的腐化时失踪了，梅丽瑞亚派你前往达纳苏斯寻找答案。",h="在灰谷，梅丽瑞亚·霜影正在打听前任指挥官的消息。维琳德·星歌在对抗从费伍德森林蔓延而来的腐化时失踪了，梅丽瑞亚派你前往达纳苏斯寻找答案。",kw={"灰谷","达纳苏斯","费伍德森林","梅丽瑞亚·霜影","哨兵","塞恩提尔·刃纹","维琳德·星歌","战士区"},ang={["class:Priest"]="身为 Elune 的祭司，面对一位曾奋力遏制费伍德森林恶魔腐化的信仰姐妹，你或许会感到亲近。",["faction:Alliance"]="身为联盟的一员，你见识到了达纳苏斯严格的军事规程，战场失踪事件的消息被限于 Sentinels 指挥层内部。",["race:NightElf"]="身为暗夜精灵的守护者，你面对的是一位备受敬重的指挥官兼女祭司的命运，而第三次大战之后的卡利姆多北部局势依然脆弱。"},sec={{t="失踪的前任",b="梅丽瑞亚·霜影在灰谷守望，接替了曾驻守此地的维琳德·星歌。维琳德是一位女祭司，奉命遏制从费伍德森林向南蔓延的恶魔腐化。最初的报告称，她已经控制住了威胁，但随着时间推移，她的战事逐渐受挫。随后，她毫无征兆地失踪了，也未正式卸任，留下了未竟的战事，至今下落不明。"},{t="战士区的秘密",b="森林中令人不安的线索促使梅丽瑞亚派你前往达纳苏斯。在战士区，哨兵 指挥官塞恩提尔·刃纹负责军事部署。哨兵 知道维琳德已经失踪，但指挥层对其中的详情守口如瓶。你需要说服塞恩提尔，她才会透露更详尽的记录。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位驻守灰谷的女祭司，也是 哨兵 的指挥官。她奉命守住北部边境，抵御来自费伍德森林的恐怖恶魔，后来却在任上失踪了。",al={"维琳德·星歌 背景故事","维琳德 是谁","女祭司 维琳德"}},{q="为什么哨兵梅丽瑞亚现在要打听她的消息？",a="维琳德失踪后，梅丽瑞亚·霜影接替了她的职位。狼嚎谷中的发现让她再次担忧起维琳德的遭遇，以及灰谷的安危。",al={"为何调查 维琳德","梅丽瑞亚 任务缘由"}},{q="完成这个任务需要去哪里？",a="从灰谷前往泰达希尔之上的达纳苏斯。塞恩提尔·刃纹指挥官驻守在战士区。",al={"维琳德·星歌 任务交付地点","塞恩提尔·刃纹位置"}},{q="为什么刃纹指挥官不愿开口？",a="哨兵 知道维琳德失踪了，但她最后几次任务的详情涉及敏感的军事事务。达纳苏斯的领袖不会轻易向外人透露这些信息。",al={"为何保密","塞恩提尔为何不愿开口"}},{q="维琳德与费伍德森林有什么关联？",a="维琳德曾率领 哨兵 遏制从费伍德森林蔓延而来的恶魔腐化。她的战事起初取得了成功，后来却逐渐受挫，不久后她便失踪了。",al={"维琳德 费伍德森林","费伍德森林发生了什么"}},{q="这个任务的直接前置任务是什么？",a="这个任务紧接着“狼嚎谷”，你在那个任务中调查灰谷森林深处发生的诡异而充满敌意的事件。",al={"维琳德·星歌 前置任务","前一个任务"}}},fp="16,210,22.386.0,22.312.1,25.191.0,45.166.0,45.122.0,47.172.0,45.159.0,40.108.0"}
P.entries["quest:1038"] = {n="维琳德的日记",s="在达纳苏斯，维琳德的日记让 哨兵 展开了一场调查。调查围绕哨兵维琳德·星歌展开，她在服役多年后失踪，塞恩提尔·刃纹请你从 哨兵 的住处取回她的日记。",h="在达纳苏斯，维琳德的日记让 哨兵 展开了一场调查。调查围绕哨兵维琳德·星歌展开，她在服役多年后失踪，塞恩提尔·刃纹请你从 哨兵 的住处取回她的日记。",kw={"刃纹","宿舍","达纳苏斯","日记","梅尔莎兰","哨兵","星歌","辛特尔","贸易区","维琳德"},ang={["class:Priest"]="身为牧师，你能看出维琳德是一位受人敬重、献身神圣职责的女祭司。你有理由追查究竟是什么让她偏离了正途。",["faction:Alliance"]="身为联盟的一员，你能看到，当暗夜精灵的高级军官需要接受调查时，遍布卡利姆多的威胁如何考验达纳苏斯尚显稚嫩的联盟领导层。",["race:NightElf"]="身为暗夜精灵，维琳德·星歌的故事让你想起 The Sisterhood of Elune 与 Sentinels 默默作出的牺牲。她的突然失踪令达纳苏斯的同胞们不安。"},sec={{t="备受信赖的哨兵",b="女祭司维琳德·星歌为暗夜精灵效力多年，深受他们信赖。当她悄然离开岗位、不知所踪时，哨兵 认为她是因私事离开，并期待她归来。后来，外来者发现了与 梅尔莎迪丝之书 有关的线索。直到这时，哨兵 的首领才允许调查维琳德的私人物品。"},{t="宿舍中的箱子",b="塞恩提尔·刃纹驻守在达纳苏斯的战士区，他将维琳德上锁的箱子的钥匙交给你。箱子存放在贸易区的 哨兵 宿舍里。里面放着维琳德的私人日记，记载着她执行的任务和心中所想。日记的内容令 哨兵 不安：其中隐约提到了一些秘密事务，促使维琳德独自离开泰达希尔。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位受人敬重的暗夜精灵女祭司，也是哨兵指挥官。她忠诚尽职，深受同僚敬重，后来却在一次缘由不明的任务中失踪。",al={"维琳德·星歌 背景故事","维琳德 是谁","维琳德 的过往"}},{q="维琳德的箱子在哪里？",a="维琳德的箱子位于达纳苏斯贸易区一栋建筑的楼上，在 哨兵 的宿舍里。从旁边的锁甲店穿过高架桥，就能到达那里。",al={"维琳德 的箱子位置","维琳德的日记 在哪里","达纳苏斯 哨兵 宿舍"}},{q="哨兵 为什么没有早些寻找她？",a="哨兵 信赖维琳德无可指摘的声誉。她的指挥官们相信，她因私事离开自有充分的理由，等事情办完便会回来。",al={"哨兵 为何没有理会 维琳德","为何无人报告 维琳德 失踪"}},{q="日记里发现了什么？",a="维林德的日记表明，她的离去比普通的休假更令人不安。塞恩提尔·刃纹立刻寻求外界帮助，追查她的行踪。",al={"维林德的日记内容","维琳德 写了什么"}},{q="维琳德与 梅尔莎迪丝之书 有什么关联？",a="这部古老的精灵典籍提到了维琳德过去的调查与活动。正是这些记载，最初引来了研究者和冒险者，调查她的去向。",al={"梅尔莎迪丝之书 与 维琳德","为何是 梅尔莎迪丝之书"}},{q="找到她的私人物品后，调查会指向何处？",a="日记中的线索指向贫瘠之地，循着维琳德南下的足迹，通往卡利姆多的交通枢纽和港口。",al={"维琳德的日记 之后去哪里","维琳德的日记 后续任务"}}},fp="17,223,18.346.0,26.372.1,24.179.0,33.192.0,48.165.0,38.155.0,54.173.0,60.114.1"}
P.entries["quest:1039"] = {n="贫瘠之地的港口",s="塞恩提尔·刃纹派你从达纳苏斯前往棘齿城，寻找维琳德·星歌。哨兵认为她乘船穿过无尽之海，前往了东部王国，而追寻她的踪迹需要穿越危险的部落领地。",h="塞恩提尔·刃纹派你从达纳苏斯前往棘齿城，寻找维琳德·星歌。哨兵认为她乘船穿过无尽之海，前往了东部王国，而追寻她的踪迹需要穿越危险的部落领地。",kw={"灰谷","棘齿城","月神镰刀","热砂港","贫瘠之地","塞恩提尔·刃纹","维琳德·星歌","码头管理员迪兹维格"},ang={["faction:Alliance"]="作为一名联盟斥候，你要穿过贫瘠之地中部落巡逻的区域，才能抵达中立的地精码头，因此务必谨慎。",["race:NightElf"]="身为暗夜精灵，维琳德·星歌的失踪让达纳苏斯的领袖们深感沉重。重走她那段绝望的旅程，是kaldorei的职责所在。"},sec={{t="追寻女祭司",b="维琳德·星歌的私人物品中留下的线索表明，她曾设法乘船渡海前往东部王国。棘齿城是贫瘠之地唯一仍在运作的港口，来自卡利姆多北部的旅人可以在此安排向南或向东的航程，无需从暗夜精灵的领地启航。塞恩提尔·刃纹派你南下，在港务长的账簿中查找维琳德的名字。"},{t="危险的旅途",b="通往棘齿城的道路穿过部落领地的腹地。灰谷以南，兽人斥候和牛头人巡逻队在莫尔杉壁垒与干旱的贫瘠之地四处巡逻。棘齿城由中立的热砂港管理，这里的地精法律将贸易置于阵营纷争之上。在码头，码头管理员迪兹维格记录着每一位乘客和每一箱货物。"}},faq={{q="哨兵为什么派我前往贫瘠之地？",a="棘齿城是卡利姆多中部主要的中立贸易港口。维琳德·星歌在设法乘船前往东部王国时失踪，因此暗夜精灵认为，她可能没有通过正式的军事渠道，而是搭乘了一艘地精商船。",al={"为什么去棘齿城","为什么去贫瘠之地港口"}},{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格负责棘齿城码头的船只离港事务和货运记录。他为热砂港效力，保管着记录港口往来船只、乘客与货物的账簿。",al={"迪兹维格是谁","棘齿城港务长"}},{q="联盟成员为什么能在棘齿城安然无恙？",a="棘齿城由中立的热砂港管理，而非部落。这里的地精将商业和利润放在首位，地精打手则负责维持秩序，只要联盟旅人不在城内拔出武器，就可以在此做生意。",al={"棘齿城对联盟安全吗","棘齿城守卫会攻击我吗"}},{q="找到码头管理员迪兹维格之后会发生什么？",a="查阅记录后，迪兹维格确认维琳德已经乘坐一艘开往东部王国的船离开。他让你前往荆棘谷的藏宝海湾，渡过无尽之海，继续追寻她的踪迹。",al={"贫瘠之地港口之后做什么","维琳德后续任务"}},{q="联盟旅人如何安全抵达棘齿城？",a="联盟旅人可以从灰谷向南，经过银翼树林，再从主路东侧的山丘绕过有守卫驻扎的莫尔杉壁垒。进入贫瘠之地后，沿着通往东部海岸的小路前进，就能抵达棘齿城的码头。",al={"联盟去棘齿城最安全的路线","联盟怎么去棘齿城"}},{q="维琳德·星歌是谁？",a="维琳德·星歌曾是一名暗夜精灵女祭司，也是梅丽瑞亚·霜影在灰谷的前任。她奉命清除森林中的恶魔，却在尚未取得多少进展时失踪了。如今，她的踪迹似乎延伸到了大海彼岸。",al={"维琳德是谁","维琳德·星歌背景故事"}}},fp="16,207,22.351.0,20.335.0,46.265.0,28.208.0,48.233.0,48.197.1,51.240.0,24.225.0"}
P.entries["quest:104"] = {n="海岸上的威胁",s="在西部荒野的岩石海岸上，葛瑞森船长的幽灵呼唤旅人前去对付 海岸上的威胁。鱼人将灯塔看守人一家赶离岗位后，他的船触礁失事。那一家人回来了，但老瞎眼又带领鱼人发动袭击，杀害了他们。如今，格雷森要取下这位酋长的性命，为这片海岸讨回公道。",h="在西部荒野的岩石海岸上，葛瑞森船长的幽灵呼唤旅人前去对付...",kw={"葛瑞森船长","海岸的威胁","无尽之海","鱼人","老瞎眼","老瞎眼的鳞片","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="西部荒野的沿海水域承载着暴风城至关重要的海运。赶走老瞎眼这样的首领，有助于保护南部航线免遭破坏。",["race:Human"]="身为人类，你知道灯塔看守人一家被害，是西部荒野逐渐失去安宁的一段惨痛往事。他们的死让你又多了一个为同胞复仇的理由。"},sec={{t="黑暗中的灯火",b="西部荒野灯塔曾指引船只穿过南部海岸遍布嶙峋礁石的浅滩。鱼人吓跑了灯塔看守人一家，葛瑞森船长的船随后在黑暗中触礁。那一家人回来重新点燃了灯火，但危险仍在海岸徘徊。"},{t="海岸的祸患",b="老瞎眼纠集了沿岸那些心智较弱的鱼人，带领它们进攻灯塔。在第二次袭击中，看守人一家丧命，葛瑞森船长只能无助地看着。如今，这位幽灵船长要求杀死瞎眼，并带回一片鳞片作为证明。他希望让死者安息，保护无尽之海上的水手。"}},faq={{q="老瞎眼是谁？",a="老瞎眼是一位狡猾的鱼人酋长，在西部荒野南部海岸游荡。他纠集其他鱼人，带领它们袭击沿岸的人类定居点。",al={"瞎眼","瞎眼是谁","海岸上的威胁是谁"}},{q="葛瑞森船长为什么想要杀死老瞎眼？",a="葛瑞森船长想要杀死老瞎眼，是因为鱼人将灯塔看守人一家赶离了岗位。海岸陷入黑暗，格雷森的船触礁失事。后来，格雷森亲眼看着瞎眼带领鱼人发动第二次袭击，杀害了返回灯塔的看守人及其家人。",al={"格雷森的仇怨","为什么杀死瞎眼","格雷森的往事"}},{q="在哪里可以找到老瞎眼？",a="老瞎眼在西部荒野灯塔及附近鱼人营地周围的开阔海滩和浅滩上游荡。",al={"瞎眼的位置","瞎眼在哪里","寻找瞎眼"}},{q="格雷森要求带回什么证明？",a="葛瑞森船长要求带回老瞎眼的一片鳞片，作为这位酋长已经死去的证明。",al={"死亡证明","瞎眼的鳞片","交任务"}},{q="葛瑞森船长生前是什么人？",a="葛瑞森船长生前是一名航海船长，他的船在西部荒野灯塔下方的礁石上失事。他的灵魂仍徘徊在海岸附近，寻求向鱼人复仇，也希望过往船只能在更安全的水域航行。",al={"葛瑞森船长","灯塔旁的幽灵","灯塔幽灵"}},{q="灯塔看守人一家遭遇了什么？",a="老瞎眼侵扰灯塔后，灯塔看守人一家最初逃离了那里。他们回来重新点亮灯火，但瞎眼带领鱼人发动了第二次袭击，杀害了全家人。",al={"看守人一家","谁住在灯塔","灯塔惨案"}}},fx={["871c093a"]={q="葛瑞森船长为什么需要你杀死老瞎眼？",a="葛瑞森船长是个幽灵，被束缚在他的船触礁破碎的那片岩岸。他没有实体，无力亲手为惨遭杀害的灯塔看守人一家复仇，也无法为这片海岸伸张正义，因此不能亲自击杀那个鱼人首领。此外，西部荒野的西南海滩沿岸没有任何成建制的军队或卫兵，这项职责便完全落在了过往冒险者的肩上。",al={"葛瑞森为何无法杀死老瞎眼","葛瑞森为何需要冒险者","葛瑞森为何需要帮助"}}},fp="18,331,20.302.0,24.344.0,20.161.0,48.264.0,32.116.0,32.89.0,32.205.0,48.181.0"}
P.entries["quest:1040"] = {n="藏宝海湾的航道",s="码头管理员迪兹维格的记录让寻找维琳德·星歌的线索从棘齿城延伸到了藏宝海湾。联盟旅人从那里继续寻找地精商队车夫拉兹戈特。",h="码头管理员迪兹维格的记录让寻找维琳德·星歌的线索从棘齿城延伸到了藏宝海湾。联盟旅人从那里继续寻找地精商队车夫拉兹戈特。",kw={"黑色鱼鹰号","藏宝海湾","旅行者拉兹戈特","前往藏宝海湾的航程","棘齿城","月神镰刀","维琳德·星歌","码头管理员迪兹维格"},ang={["faction:Alliance"]="身为联盟旅人，在棘齿城和藏宝海湾这样的中立地精港口，你需要耐心，也需要外交手腕。一路上少不了与雇佣兵和财团官僚打交道。",["race:NightElf"]="身为 Kaldorei，你有迫切的理由找到维琳德·星歌。她带着月神镰刀一同失踪，在灰谷的森林中留下了一个危险的谜团。"},sec={{t="跨海的线索",b="码头管理员迪兹维格的记录将寻找暗夜精灵哨兵维琳德·星歌的线索从灰谷引向了大海。在地精港口棘齿城，迪兹维格找到了旧航运清单，上面记载着维琳德预订了黑色鱼鹰号的船票。这艘船的目的地是荆棘谷的藏宝海湾。"},{t="通往藏宝海湾",b="一艘中立的地精渡船横跨无尽之海，往返于棘齿城和东部王国的最南端。在藏宝海湾，线索指向了旅行者拉兹戈特，他是迪兹维格向维琳德推荐的一名地精运输主管。她曾打听过穿越南方荒野的危险陆路旅程。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌曾是一位暗夜精灵女祭司，领导着抵御费伍德森林恶魔势力的行动。她的行动受挫，随后便失踪了。哨兵 正在追查她跨海旅行的踪迹。",al={"维琳德","维琳德 是谁","维琳德·星歌 的故事"}},{q="维琳德为什么前往藏宝海湾？",a="维琳德前往藏宝海湾，是为了寻找横渡无尽之海的船只。黑色鱼鹰号从棘齿城驶向藏宝海湾，她在那里打听了前往人类和矮人王国的陆路行程。",al={"为什么去藏宝海湾","维琳德 藏宝海湾","她为什么去藏宝海湾"}},{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格为热砂港管理棘齿城的航运码头。他生性急躁，保管着往返卡利姆多与东部王国的船舶日志和乘客名册。",al={"迪兹维格","迪兹维格 是谁","码头管理员"}},{q="旅行者拉兹戈特是谁？",a="旅行者拉兹戈特是一名驻扎在藏宝海湾的地精车夫。他负责协调补给车队和陆路运输，穿过荆棘谷危机四伏的丛林，前往更远的地方。",al={"拉兹戈特","旅行者拉兹戈特","拉兹戈特 是谁"}},{q="维琳德乘坐了哪艘船？",a="码头管理员迪兹维格的航运记录显示，维琳德·星歌预订了黑色鱼鹰号的船票。这艘船从棘齿城出发，横渡无尽之海，驶向藏宝海湾。",al={"维琳德 的船","维琳德 乘坐了哪艘船","黑色鱼鹰号"}},{q="如何从棘齿城前往藏宝海湾？",a="热砂港经营着一条客运渡船航线，从棘齿城南面的码头出发，横渡无尽之海。渡船停靠在荆棘谷最南端的藏宝海湾。",al={"前往藏宝海湾","如何前往藏宝海湾","前往藏宝海湾的船"}}},fp="20,141,22.253.0,21.306.0,24.199.0,36.195.0,28.210.0,26.176.0,27.172.0,42.164.0"}
P.entries["quest:1041"] = {n="商队通路",s="在藏宝海湾，寻找维琳德·星歌的线索指向了北方的夜色镇。旅行者拉兹戈特记得，这位失踪的暗夜精灵女祭司曾随他的商队穿过荆棘谷。",h="在藏宝海湾，寻找维琳德·星歌的线索指向了北方的夜色镇。旅行者拉兹戈特记得，这位失踪的暗夜精灵女祭司曾随他的商队穿过荆棘谷。",kw={"藏宝海湾","旅行者拉兹戈特","书记员达尔塔","夜色镇","暮色森林","荆棘谷","商队之路","维琳德·星歌"},ang={["faction:Alliance"]="身为联盟旅人，你在中立的地精港口与夜色镇这样的偏远联盟据点之间传递消息，将这个被近来的战争割裂的世界中的各处联系起来。",["race:NightElf"]="身为暗夜精灵，你或许和同胞一样关心维琳德·星歌的下落，她是一位信奉Elune的哨兵女祭司，秘密行动使她来到了东部王国。"},sec={{t="丛林中的女祭司",b="旅行者拉兹戈特记得，维琳德·星歌曾是他商队的乘客。为了寻找这位失踪的暗夜精灵女祭司，你从灰谷来到了荆棘谷南端的藏宝海湾。她曾随他的商队穿越丛林，对一位暗夜精灵女祭司来说，这样的旅程并不寻常。"},{t="北上夜色镇",b="拉兹戈特说，他和维琳德在穿过荆棘谷北上的途中分道扬镳。她动身前往暮色森林，留下的踪迹指向夜色镇。书记员达尔塔保管着镇上的记录，其中包括进入镇子的陌生旅人的姓名。他的登记簿或许藏着有关维琳德下落的下一条线索。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位信奉艾露恩的暗夜精灵女祭司，她在神秘的情形下离开了位于卡利姆多的故乡。她的失踪引发了一场跨越大陆的搜寻，追寻她的足迹从灰谷一路深入东部王国。",al={"维琳德","维琳德是谁","在找谁"}},{q="维琳德为何随商队旅行？",a="维琳德随旅行者拉兹戈特的运输队穿过了地精的领地。她付费搭乘商队，踏上了穿越荆棘谷北上的危险旅程。",al={"为何随商队","维琳德商队","拉兹戈特商队"}},{q="书记员达尔塔是谁？",a="书记员达尔塔是暮色森林夜色镇的书记员兼档案管理员。当地怪事频发，危机四伏，而他负责登记外来者和访客。",al={"书记员达尔塔","达尔塔夜色镇","达尔塔是谁"}},{q="离开夜色镇后，这条任务线会通向哪里？",a="查阅书记员达尔塔的记录后，他会指引你去找乔纳森·卡尔文。与乔纳森交谈后，你便开始通过他的家人调查维琳德在暮色森林逗留期间的情况。",al={"下一个任务","接下来做什么","夜色镇之后"}},{q="从藏宝海湾前往夜色镇为何危险？",a="荆棘谷栖息着凶猛的野兽，也盘踞着敌对的巨魔部族和血帆海盗。北上的旅途危机重重，旅人需要紧靠大路行进。",al={"丛林危险","荆棘谷等级","荆棘谷危险"}},{q="这场调查从哪里开始？",a="搜寻始于灰谷，那里的暗夜精灵调查者注意到，维琳德带着一件力量强大的神器不明缘由地离开了。线索指向一艘驶往南方海域的船。",al={"起点","任务线从哪里开始","灰谷起点"}}},fp="16,171,25.306.0,18.304.0,24.239.0,41.162.0,20.155.0,49.170.1,55.177.0,35.186.0"}
P.entries["quest:1042"] = {n="卡尔文家族",s="在夜色镇，寻找维琳德·星歌的外来者找到了卡尔文家族。书记员达尔塔听说灰谷出现了狼人，便指引他们去找这些猎人。",h="在夜色镇，寻找维琳德·星歌的外来者找到了卡尔文家族。书记员达尔塔听说灰谷出现了狼人，便指引他们去找这些猎人。",kw={"卡洛尔","卡尔文","书记员达尔塔","夜色镇","暮色森林","乔纳森·卡尔文","维琳德·星歌","狼人"},ang={["class:Hunter"]="身为猎人，你能看出Carevin家族是一群当地的野兽猎手，专门追猎违背自然的邪物和受到诅咒的掠食者。",["faction:Alliance"]="身为联盟的旅人，你能体会到暮色森林的聚落必须多么离群而警惕，才能在这片饱受灾祸的林地中生存。",["race:NightElf"]="身为暗夜精灵，当你发现人类怪物猎手手中那些被砍下的生物头颅与维琳德·星歌有关时，你便得到了关于她旅程的一条令人不安的线索。"},sec={{t="利爪与暗影的踪迹",b="寻找维琳德·星歌的线索从卡利姆多的古老森林一路延伸至暮色森林。在夜色镇，书记员达尔塔没有找到精灵女祭司在镇上逗留的记录。但一提起灰谷出现的凶残狼人，他便仔细倾听起来。类似的野兽已经开始在镇子周围的林地中肆虐。"},{t="暗夜猎手",b="卡尔文家族猎杀着侵扰暮色森林的恐怖生物。这个家族以追踪恶魔、亡灵和其他怪物而闻名当地，也早已与狼人交过手。他们的追踪者卡洛尔最近拖着一串血淋淋的狼人头颅，穿过了夜色镇的街道。书记员达尔塔让你去找这个家族严厉的家长乔纳森·卡尔文，了解这些猎人掌握的狼人情报。"},{t="冷淡的接待",b="乔纳森·卡尔文对陌生人怀有深深的戒心。暮色森林正被恐怖吞噬，这让他对任何不请自来、打听狼人的人都心存警惕。在分享猎人们对这些野兽的了解之前，他要求先弄清面前的人是谁，又为何要探寻那些最好永远埋在黑暗中的事。"}},faq={{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是夜色镇卡尔文家族的家长。他的家族以经验丰富的猎人而闻名这片饱受灾祸的地区，追踪并猎杀恶魔、亡灵和凶恶的野兽。",al={"乔纳森·卡尔文","卡尔文是谁","卡尔文家族的家长"}},{q="书记员达尔塔为什么指引你去找卡尔文家族？",a="书记员达尔塔没有找到失踪的暗夜精灵维琳德·星歌的记录，却认出了你描述的狼人。克尔文家族的追踪者卡洛尔最近把这些生物被砍下的头颅带进了夜色镇，因此达尔塔让你去找这个家族，了解他们掌握的情况。",al={"为何拜访卡尔文","书记员达尔塔 卡尔文","为何去找乔纳森"}},{q="卡洛尔是谁？",a="卡洛尔是一名猎人兼追踪者，与夜色镇的卡尔文家族并肩行动。他最近带着一串被砍下的狼人头颅穿过镇子，这个骇人的迹象表明，狼人正在附近活动。",al={"卡洛尔","卡洛尔是谁","卡尔文猎人卡洛尔"}},{q="这个任务如何将灰谷与暮色森林联系起来？",a="搜寻从灰谷开始，维琳德·星歌在那里失踪，狼人也在那里出现。沿着商队的路线，你从卡利姆多跨海来到暮色森林，同样可怕的狼形野兽也在这里现身。",al={"与维琳德·星歌的关联","为何去暮色森林","灰谷到夜色镇"}},{q="乔纳森·卡尔文为什么如此怀疑陌生人？",a="暮色森林遍布暗影、亡灵和邪恶势力，幸存的居民都变得极为警惕。当陌生人前来打听致命的狼人时，乔纳森会怀疑其心怀不轨，直到你证明自己。",al={"卡尔文为何抱有敌意","卡尔文的怀疑"}},{q="克尔文家族擅长对付哪些怪物？",a="卡尔文家族猎杀构成威胁的怪物，尤其是恶魔、亡灵，以及出没于暮色森林的狼人这类奇异野兽。",al={"克尔文与怪物","克尔文家族猎杀什么"}}},fp="18,159,28.304.0,20.404.0,16.313.1,24.183.0,55.251.0,13.195.0,50.220.0,51.212.0,53.126.0"}
P.entries["quest:1043"] = {n="月神的镰刀",s="在夜色镇，月神镰刀的线索将你引向了猎杀狼人的行动。乔纳森·卡尔文派你前往最早发现这些野兽的罗兰之墓，将卡利姆多的一件古老暗夜精灵圣物与如今肆虐暮色森林的狼人联系起来。",h="在夜色镇，月神镰刀的线索将你引向了猎杀狼人的行动。乔纳森·卡尔文派你前往最早发现这些野兽的罗兰之墓，将卡利姆多的一件古老暗夜精灵圣物与如今肆虐暮色森林的狼人联系起来。",kw={"卡洛尔","夜色镇","暮色森林","乔纳森·卡尔文","夜行","罗兰之墓","月神镰刀","维琳德·星歌","狼人"},ang={["class:Druid"]="月神镰刀释放出的狂野狼人，警示着德鲁伊驾驭失控力量的代价。",["faction:Alliance"]="解开夜行狼人之谜，让夜色镇和联盟首次真正了解了那些徘徊在暮色森林南部的恐怖生物。",["race:NightElf"]="找到女祭司维琳德·星歌的长眠之地，便揭示了月神镰刀脱离 Sisterhood 监管后所付出的可怕代价。"},sec={{t="暗夜中的狩猎",b="你追寻女祭司维琳德·星歌的足迹，穿越卡利姆多，又与夜色镇的 卡尔文 一家交谈，随后与乔纳森·卡尔文有了共同的目标。夜行狼人已遍布暮色森林南部，赶走了矿工，还威胁着镇上残存的一切。卡尔文 并不完全了解这些野兽的超自然起源，但他明白，有人愿意猎杀它们是件好事。他指引你前往罗兰之墓，那座最早发现这些恶兽的矿洞。"},{t="罗兰之墓的幽魂",b="在罗兰之墓深处，成群凶残的夜行之间，矿道下方有一堆未被扰动的泥土。翻动泥土，便会显现出维琳德·星歌徘徊不散的幽魂。这位暗夜精灵女祭司带着月神镰刀来到这个洞穴，却在暮色森林地下丧命。维琳德哀叹，她释放的狼人如今四处肆虐，而女神赐予她的镰刀也已遗失。"}},faq={{q="该去哪里寻找镰刀的踪迹？",a="搜索暮色森林东南部的废弃矿洞罗兰之墓。杀出一条穿过夜行狼人的路，找到矿道中一堆未被扰动的泥土。",al={"镰刀在哪里","月神镰刀 位置","罗兰之墓洞穴"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是夜色镇 卡尔文 家族的一员。抵御邪恶的守卫者已所剩无几，他便与那些想要削减狼人数量的外来者交换情报。",al={"乔纳森·卡尔文","卡尔文 夜色镇"}},{q="维琳德·星歌在矿洞里遭遇了什么？",a="罗兰之墓深处一堆未被扰动的泥土，藏着维琳德·星歌的命运与镰刀下落的答案。检查它，便能知道该带什么回去交给乔纳森·卡尔文。",al={"维琳德·星歌 的命运","维琳德 遭遇了什么"}},{q="月神镰刀是什么？",a="月神镰刀是女祭司维琳德·星歌获得的一件暗夜精灵圣物。哨兵 相信，这是女神 艾露恩 赐予她的恩惠。",al={"镰刀是什么","月神镰刀 背景故事"}},{q="狼人为何会出现在暮色森林？",a="乔纳森·卡尔文说，狼人突然凭空出现，最早是在南方的罗兰之墓被发现的。矿洞中月神镰刀的踪迹揭示了它们出现的原因。",al={"暮色森林为何有狼人","暮色森林狼人起源"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇 卡尔文 家族的同伴。在你于罗兰之墓有所发现后，乔纳森指示他全力遏制狼人的威胁。",al={"非玩家角色 卡洛尔","卡洛尔是谁"}}},fp="19,237,18.439.0,23.381.1,40.150.0,24.167.0,46.185.1,28.160.0,38.176.1,13.168.1"}
P.entries["quest:1044"] = {n="回复珊蒂斯",s="追寻维琳德·星歌的踪迹，你从灰谷来到达纳苏斯，要在这里呈交一份报告。",h="追寻维琳德·星歌的踪迹，你从灰谷来到达纳苏斯，要在这里呈交一份报告。",kw={"回复珊蒂斯","达纳苏斯","暮色森林","乔纳森·卡尔文","罗兰之墓","月神镰刀","塞恩提尔·刃纹","维琳德·星歌","狼人"},ang={["class:Priest"]="身为牧师，你或许能感受到维琳德的故事在信仰上的分量：Elune的恩赐蕴含着强大的力量，而试图让未知的野兽屈从于自己的意志，则充满危险。",["faction:Alliance"]="身为联盟的一员，你能看到卡利姆多的暗夜精灵与暮色森林中饱受困扰的人类定居点之间的联系，双方都面临着潜藏在暗影中的威胁。",["race:NightElf"]="身为暗夜精灵，你可以协助领袖们追查一位失踪女祭司与一件神圣神器的下落。"},sec={{t="悲惨的真相",b="维琳德·星歌的踪迹从灰谷延伸，横跨两片大陆，通向暮色森林中闹鬼的林地与废弃的矿洞。她曾拿起月神镰刀，抵御入侵卡利姆多的恶魔，随后又用它召唤了凶猛的狼人。维琳德失去了对它们的控制，最终死在罗兰之墓矿洞深处。暮色森林只能独自面对这场灾难留下的恶果。"},{t="返回达纳苏斯",b="找回维林德的日记并查明她的命运后，暮色森林的乔纳森·卡尔文派你返回泰达希尔。哨兵塞恩提尔·刃纹在达纳苏斯听取你的报告。维琳德是高阶女祭司泰兰德·语风的挚友，因此她的遭遇让艾露恩姐妹会在情感与信仰上都遭受了打击。"},{t="失落的神器",b="维琳德的命运已经查明，但月神镰刀仍然下落不明。女神赐下这件武器，作为神圣的恩赐，如今它却遗失在荒野，远离那些敬奉它的女祭司。野性难驯的狼人游荡在东部王国各地，成为镰刀遗失后留下的威胁，久久不散，难以预料。"}},faq={{q="回复珊蒂斯是什么任务？",a="回复珊蒂斯为追寻维琳德·星歌的旅程画上了句号。暮色森林的乔纳森·卡尔文派你前往达纳苏斯，向塞恩提尔·刃纹报告她的命运与月神镰刀的下落。",al={"回复珊蒂斯任务","回复珊蒂斯经典旧世","月神镰刀任务结局"}},{q="维琳德·星歌是谁？",a="维琳德·星歌是一位信奉艾露恩的暗夜精灵女祭司，也是哨兵梅丽瑞亚·霜影在灰谷的前任。她奉命抵御费伍德森林的恶魔，获得了月神镰刀，随后便失踪了。她的踪迹越过大海，通向暮色森林。",al={"维琳德·星歌","维琳德是谁","维琳德遭遇了什么"}},{q="这个任务结束时，月神镰刀在哪里？",a="当你在达纳苏斯向塞恩提尔·刃纹报告时，月神镰刀仍然下落不明。乔纳森·卡尔文让你将查明的情况告知她。",al={"月神镰刀在哪里","是否找到了镰刀","月神镰刀位置"}},{q="泰兰德·语风与维琳德有什么关系？",a="在维琳德·星歌失踪之前，高阶女祭司泰兰德·语风与她是挚友。她的遭遇让暗夜精灵的领袖们心情沉重。",al={"泰兰德与维琳德","高阶女祭司的关联"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是暮色森林的一位人类居民，他协助你搜寻当地的矿洞。他发誓要遏制那里的狼人，随后派你前往卡利姆多，将调查所得告知维琳德的族人。",al={"乔纳森·卡尔文","谁提供回复珊蒂斯任务"}},{q="塞恩提尔·刃纹在哪里？",a="塞恩提尔·刃纹位于泰达希尔岛上的达纳苏斯。她为暗夜精灵的领袖效力，负责搜寻失踪的哨兵与女祭司。",al={"塞恩提尔·刃纹在哪里","塞恩提尔·刃纹位置","交付回复珊蒂斯任务"}}},fx={["6f485fee"]={q="乔纳森·卡尔文为什么派你返回达纳苏斯？",a="乔纳森·卡尔文意识到，暮色森林矿井中的发现，牵涉之广远远超出了守夜人的职责范围。维琳德·星歌曾为暗夜精灵和女神艾露恩效力，卡尔文认为，她的遭遇，以及月神镰刀令人不安的下落不明，都是必须直接送达达纳苏斯、告知她族人的要闻，不能就这样埋在矿井里。",al={"乔纳森·卡尔文为何要做这件事","乔纳森·卡尔文的动机","为何返回达纳苏斯"}}},fp="18,95,14.345.1,19.325.1,18.303.1,37.200.1,25.251.0,54.147.1,48.148.0,24.197.1,38.163.0"}
P.entries["quest:1045"] = {n="莱恩的净化",s="在密斯特拉湖，克罗格请你杀死兰恩·血牙。借助达图尔的变形魔棒伪装身份，你就能赢得未受腐化的熊怪的信任。克罗格怨恨暗夜精灵，也畏惧族人之中蔓延的腐化。他希望熊怪为自己族人的所作所为负责。",h="在密斯特拉湖，克罗格请你杀死兰恩·血牙。借助达图尔的变形魔棒伪装身份，你就能赢得未受腐化的熊怪的信任。克罗格怨恨暗夜精灵，也畏惧族人之中蔓延的腐化。他希望熊怪为自己族人的所作所为负责。",kw={"灰谷","血牙 的卫兵","腐化","达图尔的变形魔棒","熊怪","克罗格","密斯特拉湖","兰恩·血牙"},ang={["class:Druid"]="身为德鲁伊，你眼中的兰恩·血牙是一个迷失于恶魔腐化的自然生灵，威胁着灰谷的平衡。",["faction:Alliance"]="身为联盟的勇士，你借助达图尔的附魔魔棒悄然接近，深入敌后，对抗那些为非作歹的酋长。",["race:NightElf"]="身为暗夜精灵，你或许会觉得克罗格的话是一番严厉的指责。尽管你的族人长期守望着这片森林，当地部族仍将远古的大分裂和灰谷挥之不去的腐化归咎于 kaldorei 的傲慢。"},sec={{t="满怀怨恨的隐士",b="在密斯特拉湖附近，克罗格离群索居，流离失所，身心疲惫。他认为，暗夜精灵自古以来的傲慢，给卡利姆多带来了毁灭，也让黑暗的腐化在灰谷蔓延。达图尔的变形魔棒让你能够伪装身份，接近熊怪。克罗格憎恨 kaldorei，却既不主张屠杀，也不愿无辜者丧命。"},{t="约束自己的族人",b="克罗格相信，他的族人必须为自己的行为负责，而不是屈从于笼罩各部族的恶魔腐化。腐化并未赋予他们缺陷，只是放大了他们最恶劣的冲动。兰恩·血牙就是这种危险的例证。早在遭到腐化之前，这位酋长就已经冷酷无情，渴求力量，后来更是投身黑暗。如今，他威胁着精灵和无辜的野兽。克罗格不会让一个熊怪代表整个族群。"},{t="共同的职责",b="借助达图尔的魔法伪装身份后，你向兰恩·血牙及其精锐卫兵发起攻击。他们的死能够伸张正义，又不至于在各部族之间激起更多纷争。一个怨恨暗夜精灵的熊怪，与一名联盟的使者，面对灰谷中蔓延的疯狂，有着共同的目标：净化这片神圣的林地。"}},faq={{q="克罗格为什么憎恨暗夜精灵？",a="克罗格认为，暗夜精灵在远古时期滥用危险的魔法，导致了灰谷的腐化。他认为他们应为这片土地的污染和各部族的苦难负责。",al={"克罗格对暗夜精灵的仇恨","克罗格为什么憎恨精灵","克罗格的背景故事"}},{q="兰恩·血牙是谁？",a="兰恩·血牙是一位腐化堕落、渴求力量的熊怪酋长，在密斯特拉湖以东的群山中扎营。荼毒灰谷的黑暗力量已经让他陷入疯狂。他对暴力的渴望威胁着森林中的自然生灵。",al={"兰恩·血牙 的故事","血牙 是谁","兰恩·血牙"}},{q="克罗格为什么想要兰恩·血牙死？",a="克罗格怨恨暗夜精灵，却无法容忍屠杀无辜。他相信，熊怪必须追究自己族人的责任。腐化已经让 兰恩 成为整片森林的威胁。",al={"为什么要杀 兰恩·血牙","克罗格对付 血牙 的动机"}},{q="联盟玩家怎样才能与克罗格交谈而不遭到攻击？",a="达图尔的变形魔棒能让你化身熊怪，安全地接近克罗格。你在此前的旅途中就已获得了这根附魔魔棒。",al={"如何与克罗格交谈","达图尔的变形魔棒 克罗格","克罗格为什么友善"}},{q="兰恩·血牙在哪里？",a="克罗格的藏身处位于密斯特拉湖附近，兰恩·血牙和他的卫兵就在藏身处以东的群山中扎营。",al={"兰恩·血牙 的位置","兰恩·血牙 在哪里","血牙营地"}},{q="杀死兰恩·血牙如何帮助净化灰谷？",a="杀死兰恩·血牙，就能除掉一个因腐化而变得强大、最为凶残的熊怪，他威胁着森林中的每一个自然生灵。灰谷仍受腐化侵扰，但克罗格认为，这是让它重现昔日荣光的一小步。",al={"净化灰谷 兰恩","为什么 血牙 是 莱恩的净化 的一部分"}}},fp="17,259,15.361.0,18.424.0,13.319.1,36.169.0,22.228.0,40.198.0,63.164.0,32.101.0,55.227.0"}
P.entries["quest:1046"] = {n="莱恩的净化",s="当你带着兰恩·血牙的颅骨返回阿斯特兰纳，莱恩的净化便走到了终点。这场搜寻始于泰洛尼斯，如今灰谷的熊怪威胁已得到削弱。",h="当你带着兰恩·血牙的颅骨返回阿斯特兰纳，莱恩的净化便走到了终点。这场搜寻始于泰洛尼斯，如今灰谷的熊怪威胁已得到削弱。",kw={"灰谷","阿斯特兰纳","达图尔的变形魔棒","熊怪","克罗格","莱恩·狼行者","莱恩的净化","兰恩·血牙","泰洛尼斯"},ang={["faction:Alliance"]="作为联盟的一员，送回血牙的颅骨，表明你的人民决心与暗夜精灵哨兵并肩保卫阿斯特兰纳。",["race:NightElf"]="作为暗夜精灵，终结兰恩·血牙的暴行，既是对泰洛尼斯等阵亡盟友的告慰，也有助于收复灰谷的神圣林地。"},sec={{t="苦涩的战利品",b="兰恩·血牙倒下后，克罗格让你返回阿斯特兰纳。你带着这位酋长被斩下的颅骨，交给哨兵莱恩·狼行者，证明潜伏在森林深处的威胁已被铲除。"},{t="纪念泰洛尼斯",b="莱恩·狼行者将兰恩·血牙的颅骨与达图尔的变形魔棒一同安放在一处庄严之地。这件阴森的信物是为了纪念泰洛尼斯，正是他对净化腐化熊怪的调查，开启了这场艰难的行动。"}},faq={{q="兰恩·血牙是谁？",a="兰恩·血牙曾是灰谷森林中最凶残的腐化熊怪威胁。他的败亡除去了一个肆虐林地的酋长。",al={"兰恩·血牙","血牙的颅骨","兰恩·血牙生前是谁"}},{q="莱恩·狼行者为什么想要这颗颅骨？",a="莱恩·狼行者将兰恩·血牙的颅骨保存在达图尔的魔棒旁，以纪念胜利，铭记曾经战胜的危险。这颗颅骨证明，哨兵部队及其盟友铲除了一个危及灰谷的致命威胁。",al={"为什么要颅骨","狼行者颅骨","莱恩如何处置颅骨"}},{q="泰洛尼斯生前是谁？",a="泰洛尼斯是一名暗夜精灵调查员，他在搜寻初期的遇难，促使人们继续寻找净化宝石和达图尔的魔棒。完成这项工作，就是延续他未竟的使命。",al={"泰洛尼斯","泰洛尼斯是谁","泰洛尼斯自豪"}},{q="这个任务在哪里结束？",a="你在阿斯特兰纳与哨兵莱恩·狼行者交谈，完成这项工作。这里是灰谷主要的暗夜精灵聚居地。",al={"交任务地点","莱恩在哪里","莱恩·狼行者位置"}},{q="克罗格是谁？",a="克罗格是一位盟友，他让你将兰恩·血牙被斩下的颅骨带回阿斯特兰纳，让你的族人见证这场胜利。",al={"克罗格","谁给任务","非玩家角色克罗格"}},{q="达图尔的变形魔棒是什么？",a="达图尔的变形魔棒是在这一连串事件中组装而成的附魔遗物。它与熊怪的本性及净化有着深厚的魔法联系。",al={"达图尔的变形魔棒","变形魔棒","熊怪魔棒"}}},fp="17,162,15.206.0,20.209.1,22.139.0,41.217.0,16.190.1,26.126.0,13.135.0,21.123.0"}
P.entries["quest:1048"] = {n="Into The Scarlet Monastery",s="幽暗城的瓦里玛萨斯要你打击血色十字军的首领和勇士。他们的败亡至关重要，因此他要你回去向他报告。",h="幽暗城的瓦里玛萨斯要你打击血色十字军的首领和勇士。他们的败亡至关重要，因此他要你回去向他报告。",kw={"赫洛德","驯犬者洛克希","莫格莱尼","血色","血色勇士","血色修道院","幽暗城","瓦里玛萨斯","怀特迈恩"},sec={{t="向瓦里玛萨斯报告",b="瓦里玛萨斯派你去对付四名血色十字军人物：大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色勇士赫洛德，以及驯犬者洛克希。杀死他们后，你要回幽暗城向他报告。"}},faq={{q="是谁交给我这项任务？",a="瓦里玛萨斯交给你这项任务，并要你回幽暗城向他报告。",al={"谁派我来的","瓦里玛萨斯的任务"}},{q="我该打败谁？",a="目标包括大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色勇士赫洛德，以及驯犬者洛克希。",al={"要杀谁","血色目标"}},{q="我该向谁报告？",a="回幽暗城向瓦里玛萨斯报告。",al={"向瓦里玛萨斯报告","返回地点"}}},fp="26,145,24.228.0,26.76.0,28.129.0,23.44.0"}
P.entries["quest:1050"] = {n="泰坦神话",s="在铁炉堡，图书馆员麦伊·苍尘正在寻找《泰坦神话》，据说这本书曾存放在提瑞斯法古老的修道院中。研读此书或许能揭示，往昔能为前方的未知带来怎样的启示。",h="在铁炉堡，图书馆员麦伊·苍尘正在寻找《泰坦神话》，据说这本书曾存放在提瑞斯法古老的修道院中。研读此书或许能揭示，往昔能为前方的未知带来怎样的启示。",kw={"书","铁炉堡","图书馆员麦伊·苍尘","麦伊·苍尘","泰坦神话","古老的修道院","提瑞斯法林地","泰坦"},sec={{t="失落的书卷",b="在灾祸降临洛丹伦之前，提瑞斯法林地古老的修道院中有一座收藏学识的图书馆。麦伊请你为她带回一本名为《泰坦神话》的书。据说这本书就在那里，她希望通过研读此书揭开往昔的秘密。"}},faq={{q="谁在寻找这本书？",a="铁炉堡的图书馆员麦伊·苍尘请你为她带回《泰坦神话》。",al={"谁想要这本书","麦伊·苍尘的书","图书馆员麦伊"}},{q="据说《泰坦神话》在哪里？",a="传闻这本书就在提瑞斯法林地古老的修道院的图书馆中。",al={"书在哪里","修道院的书","泰坦书籍位置"}},{q="《泰坦神话》是什么？",a="《泰坦神话》是一本据说曾收藏在提瑞斯法林地古老的修道院图书馆中的书。",al={"这本书是什么","泰坦神话","神话书籍"}},{q="麦伊为什么想要这本书？",a="麦伊希望研读这本书能揭开往昔的秘密，帮助人们为未知做好准备。",al={"为什么要找这本书","麦伊为什么需要这本书","这本书有什么用"}}},fp="23,191,13.246.0,27.82.0,44.81.0,32.107.0,27.92.0"}
P.entries["quest:1052"] = {n="血色之路",s="安东修士说，你在凄凉之地对抗亡灵的事迹只是个开始，因为瘟疫真正的威胁在洛丹伦。他给了你一封盖有他印章的表彰信，让你交给南海镇的虔诚的莱雷恩。",h="安东修士说，你在凄凉之地对抗亡灵的事迹只是个开始，因为瘟疫真正的威胁在洛丹伦。他给了你一封盖有他印章的表彰信，让你交给南海镇的虔诚的莱雷恩。",kw={"安东修士","血色之路","壁炉谷","表彰信","洛丹伦","虔诚的莱雷恩","血色修道院","南海镇","提瑞斯法林地"},sec={{t="十字军的要塞",b="安东自豪地谈起血色十字军在洛丹伦的净化堡垒。十字军声称，从壁炉谷到提瑞斯法林地，一路都有他们的要塞。安东说，你在凄凉之地对抗亡灵的行动已经证明了你的实力，但瘟疫真正的威胁在洛丹伦。"},{t="送往南海镇的信",b="安东派你前往东部王国的南海镇，寻找一位名叫虔诚的莱雷恩的十字军战士。信上盖着安东的印章，安东说，凭这封信，莱雷恩 会护送你前往血色修道院，让你在那里获得贵宾般的礼遇。"},{t="莱雷恩 的反应",b="莱雷恩 拆开封印，读了信。得知安东仍在宣扬血色十字军，莱雷恩 感到不安，并告诉你，这里的事情超出了你的理解。"}},faq={{q="是谁派你踏上这段旅程？",a="安东修士给了你一封密封的表彰信，让你交给虔诚的莱雷恩。",al={"谁提供 血色之路","血色之路 任务给予者"}},{q="你被派往何处？",a="你要前往东部王国的南海镇，寻找十字军战士虔诚的莱雷恩。",al={"前往何处","莱雷恩 在哪里","血色之路 地点"}},{q="安东修士说这封信有什么用？",a="安东说，莱雷 一看到他盖印的信，就会带你前往血色修道院，让你在那里获得贵宾般的礼遇。",al={"信的作用","表彰信的用途"}},{q="血色十字军声称在洛丹伦占据了哪些领地？",a="安东修士说，血色十字军的要塞从壁炉谷一直延伸到提瑞斯法林地，他为这些净化堡垒感到自豪。",al={"血色十字军领地","血色十字军要塞在哪里"}}},fp="21,192,26.267.0,23.236.0,18.200.1,30.79.0,25.103.0,47.116.0,59.131.0"}
P.entries["quest:1053"] = {n="In the Name of the Light",s="南海镇的虔诚的莱雷恩要你去对付五名指定人物。事情办妥后，他等你回去报告。",h="南海镇的虔诚的莱雷恩要你去对付五名指定人物。事情办妥后，他等你回去报告。",kw={"赫洛德","大检察官怀特迈恩","驯犬者洛克希","虔诚的莱雷恩","scarlet champion","血色十字军指挥官莫格莱尼","南海镇"},sec={{t="莱雷恩的讨伐",b="南海镇的虔诚的莱雷恩派你去对付大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色勇士赫洛德和驯犬者洛克希。与他们交锋后，莱雷恩等你回去报告。"}},faq={{q="谁让我做这件事？",a="南海镇的虔诚的莱雷恩要你去对付五名指定人物，并向他回报。",al={"谁交代的","莱雷恩的任务"}},{q="我该面对谁？",a="指定人物包括大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色勇士赫洛德和驯犬者洛克希。",al={"该杀谁","目标"}},{q="我该向谁回报？",a="回南海镇向虔诚的莱雷恩报告。",al={"向何处报告","向莱雷恩报告"}}},fp="24,118,16.211.0,23.96.0,26.128.0,23.48.0"}
P.entries["quest:1054"] = {n="解除威胁",s="随着北方的蓟皮熊怪日益增多，恐惧在阿斯特兰纳蔓延。莱恩·狼行者要求在这个部族进攻城镇之前，杀死达尔·血爪。",h="随着北方的蓟皮熊怪日益增多，恐惧在阿斯特兰纳蔓延。莱恩·狼行者要求在这个部族进攻城镇之前，杀死达尔·血爪。",kw={"灰谷","阿斯特兰纳","解除威胁","达尔·血爪","熊怪","莱恩·狼行者","蓟皮"},ang={["class:Druid"]="身为德鲁伊，蓟皮的疯狂让你深感悲痛。灰谷挥之不去的污染，让高贵的熊怪沦为嗜血的野兽。",["faction:Alliance"]="你知道，阿斯特兰纳对联盟在卡利姆多中部的补给线与通讯至关重要，因此必须立即应对城镇北方的危险。",["race:NightElf"]="身为kaldorei，你既要承受杀死被疯狂腐化的古老盟友之痛，也不得不采取残酷的手段，保护阿斯特兰纳免遭毁灭。"},sec={{t="北方迫近的危机",b="阿斯特兰纳坐落在灰谷腹地，四面危机环伺。蓟皮熊怪就住在城镇北边。他们曾是平和的森林居民，如今却和许多同族一样，陷入疯狂，变得好勇斗狠。近几个月来，哨兵斥候发现他们的数量不断增长。如今，斥候们担心，他们对阿斯特兰纳发动有组织的进攻只是时间问题。"},{t="击杀酋长",b="莱恩·狼行者召集旅人，要求在蓟皮冲破阿斯特兰纳简陋的木栅之前出击。达尔·血爪统领着这个部族，为族人带来秩序和勇气。哨兵要求将他的颅骨带回阿斯特兰纳。他们希望他的死能打乱熊怪的协同作战，为这座饱受威胁的城镇争取宝贵的时间。"}},faq={{q="谁发布解除威胁任务？",a="暗夜精灵城镇阿斯特兰纳的哨兵指挥官莱恩·狼行者，请你采取行动。",al={"任务发布者","谁发布解除威胁","哪里接解除威胁"}},{q="阿斯特兰纳为什么要杀死达尔·血爪？",a="达尔·血爪统领着阿斯特兰纳北边的蓟皮部族。他们的数量正在迅速增长，莱恩·狼行者担心，若不瓦解他的领导，他就会率众进攻城镇。",al={"为何杀死达尔·血爪","达尔·血爪背景故事","为何攻击蓟皮"}},{q="蓟皮熊怪为什么敌视暗夜精灵？",a="熊怪与暗夜精灵曾是盟友，但遍布灰谷的恶魔势力与腐化影响，让包括蓟皮在内的许多部族陷入暴戾的狂乱，时刻疑惧领地遭到侵犯。",al={"熊怪为何攻击","灰谷被腐化的熊怪","蓟皮背景故事"}},{q="在哪里能找到达尔·血爪？",a="达尔·血爪就在灰谷阿斯特兰纳正北方的蓟皮村及其附近的兽穴中。",al={"达尔·血爪位置","达尔·血爪在哪里"}},{q="杀死达尔·血爪能永久消除熊怪的威胁吗？",a="不能。莱恩·狼行者说，达尔·血爪的死只能暂时遏制蓟皮的攻势。只要灰谷仍受腐化侵蚀，熊怪群体就依然是个威胁。",al={"蓟皮被击败了吗","阿斯特兰纳获救了吗"}},{q="需要什么来证明达尔·血爪已死？",a="你需要将达尔·血爪的颅骨直接交给阿斯特兰纳的莱恩·狼行者。",al={"交给莱恩什么","解除威胁任务交付物品"}}},fp="18,164,28.347.0,22.324.0,39.91.0,43.183.0,59.191.0,33.114.0,64.172.0,48.70.0"}
P.entries["quest:1055"] = {n="莱恩的净化",s="在灰谷的隐秘神殿，莱恩的净化迎来了转折。变形魔棒已组装完毕，魔力也已恢复，你必须将它送回月亮井圣所，交给莎尔蒂恩。",h="在灰谷的隐秘神殿，莱恩的净化迎来了转折。变形魔棒已组装完毕，魔力也已恢复，你必须将它送回月亮井圣所，交给莎尔蒂恩。",kw={"灰谷","阿斯特兰纳","艾露恩","隐秘神殿","月亮井","莱恩的净化","变形魔棒","莎尔蒂恩"},ang={["class:Priest"]="身为牧师，你协助莎尔蒂恩修复一件魔法圣物，莱恩在灰谷的调查需要用到它。",["faction:Alliance"]="身为联盟成员，确保灰谷的安全关系到你在卡利姆多北部的立足，也有助于保护阿斯特兰纳免受当地腐化和敌对势力的侵害。",["race:NightElf"]="身为暗夜精灵，修复法杖能帮助莱恩调查威胁阿斯特兰纳及周边林地的熊怪袭击。"},sec={{t="修复的圣物",b="在灰谷的隐秘神殿，你修复了变形魔棒。杖身、杖柄和发光的宝石已合为一体，法杖也已重新附魔。莎尔蒂恩需要用它来协助莱恩调查熊怪袭击事件。"},{t="返回莎尔蒂恩身边",b="莎尔蒂恩在森林中的月亮井旁等候，此前她一直指引你修复法杖。你将完好的圣物带给她，并确认它的魔力已经恢复。随后，哨兵守卫便能采取下一步行动，保护饱受围攻的家园。"}},faq={{q="这个任务阶段的目标是什么？",a="你已在隐秘神殿组装好变形魔棒。将它交还给莎尔蒂恩，她正在灰谷北部的月亮井旁等候。",al={"莱恩的净化第七步怎么做","这是什么任务","任务目标"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位树妖，照料着灰谷的一口神圣月亮井。她致力于净化古老森林中不断蔓延的腐化，并指引值得信赖的盟友收集圣物、净化部件、修复神圣的器物。",al={"莎尔蒂恩","莎尔蒂恩是谁","月亮井旁的女祭司"}},{q="莎尔蒂恩在哪里？",a="莎尔蒂恩在灰谷北部一口幽静的月亮井旁等候，那里位于阿斯特兰纳通往费伍德森林的主路以东。她守护着这片宁静的井水。",al={"莎尔蒂恩位置","莎尔蒂恩在哪里","月亮井在哪里"}},{q="变形魔棒是什么？",a="变形魔棒是达图尔创造的魔法物品。它恢复后的力量将用于帮助莱恩调查熊怪；至于它能赋予何种形态，要到之后才会揭晓。",al={"变形魔棒是什么","变形魔棒背景故事","法杖"}},{q="为什么组装法杖对阿斯特兰纳如此重要？",a="莱恩·狼行者希望借助法杖，让调查者接近熊怪，进一步了解威胁阿斯特兰纳的袭击。",al={"为什么进行莱恩的净化","阿斯特兰纳为何关心此事","莱恩的重要性"}},{q="组装好法杖就意味着净化系列任务结束了吗？",a="没有。接下来，莎尔蒂恩会让你返回阿斯特兰纳，告诉莱恩·狼行者法杖已经完成。",al={"这是最后一个任务吗","莱恩的净化到这里结束吗","系列任务结尾"}}},fp="17,147,16.232.0,20.242.0,47.140.0,18.221.0,28.149.0,34.163.0,52.133.0,48.105.0"}
P.entries["quest:1057"] = {n="夺回焦炭谷",s="在石爪峰，守护者奥巴格姆派遣联盟战士前往满目疮痍的焦炭谷，清除那里的血怒鹰身人。除掉它们，德鲁伊和看护者才能进入山谷，着手治愈这片焦土。",h="在石爪峰，守护者奥巴格姆派遣联盟战士前往满目疮痍的焦炭谷，清除那里的血怒鹰身人。除掉它们，德鲁伊和看护者才能进入山谷，着手治愈这片焦土。",kw={"血怒","焦炭谷","鹰身人","守护者奥巴格姆","收复焦炭谷","石爪山","石爪峰"},ang={["class:Druid"]="身为德鲁伊，你为塞纳里奥议会效力，捍卫自然的和谐。你帮助守护者们清除受污染的巢穴，好让他们开始用魔法重建森林。",["faction:Alliance"]="身为联盟英雄，你协助守住高山隘口和南部山谷，保护石爪峰各处脆弱的暗夜精灵定居点与圣地，使其免遭掠食者的威胁。",["race:NightElf"]="身为暗夜精灵，你敬重石爪山的荒野森林。将邪恶的鹰身人赶出遭外来机械亵渎的圣林，是刻不容缓的使命。"},sec={{t="受创的山谷",b="石爪峰以南，焦炭谷遍布灰烬和余火未熄的废墟，这里曾是一片草木繁茂的高山净土。一支机械化的伐木采矿大军横扫了这些神圣的山崖，砍光树木，引发了失控的大火。对石爪山一带的守护者而言，古老林地毁于工业贪欲，是一道无法坐视不理的伤口。"},{t="鹰身人的威胁",b="血怒鹰身人占据了机械引发的大火留下的灰烬之地。它们凶残而善于乘虚而入，成群盘踞在烟雾弥漫的低地，在那里筑巢，凶狠地伏击任何靠近山谷的人。守护者奥巴格姆和他的盟友无法踏上这片土地，播下新生的种子；鹰身人用暴力阻挡所有外来者。"},{t="扫清复苏之路",b="只有捣毁血怒的巢穴，修复工作才能开始。奥巴格姆派遣经验丰富的联盟战士深入这个族群，击杀其中的猎手、伏击者和飞羽。削减这群掠食者的数量，是让自然重掌这片土地、让森林之灵再次获得喘息之地的第一步。"}},faq={{q="焦炭谷是什么地方？",a="焦炭谷位于石爪山脉西南部的高地。工业伐木大军肆无忌惮地掠夺这片土地，大火吞噬了曾经繁茂的森林，将地表烧得只剩岩石。",al={"焦炭谷背景","焦炭谷发生了什么","为什么被烧毁"}},{q="守护者奥巴格姆是谁？",a="守护者奥巴格姆是石爪峰联盟定居点的一位林地守护者和看护者。他保护自然与森林之灵，努力遏制山间的荒芜，并驱退不断侵入的野兽。",al={"守护者奥巴格姆","谁提供收复焦炭谷任务","奥巴格姆背景"}},{q="鹰身人为什么住在焦炭谷？",a="血怒鹰身人在遭到破坏、满目疮痍的土地上繁衍。大火将山谷夷为平地后，这群善于乘虚而入的鹰身人迁入盆地，攻击任何试图进入的人。",al={"血怒鹰身人","这里为什么有鹰身人","石爪山的血怒鹰身人"}},{q="最初是谁放火烧毁了焦炭谷？",a="守护者奥巴格姆指出，祸首是一支由贪婪的实业家组成的机械化大军。他们的伐木机械肆意运转，扩张时不断使用炸药，引发了吞噬林地的毁灭性大火。",al={"谁烧毁了焦炭谷","机械化大军实业家","荆棘谷地精焦炭谷"}},{q="削减鹰身人的数量之后，还需要做什么？",a="一旦血怒的数量得到控制，守护者奥巴格姆便会着手播种，并引导修复魔法，让焦土重新孕育生命。",al={"焦炭谷后续任务","收复焦炭谷第二部分","接下来会发生什么"}},{q="部落冒险者可以接取这个任务吗？",a="不可以。守护者奥巴格姆驻守在石爪峰顶的联盟据点，因此只有联盟英雄才能为他清除血怒鹰身人。",al={"部落能做这个任务吗","部落收复焦炭谷"}}},fp="27,203,18.304.0,16.260.0,28.303.0,25.205.0,23.215.0,43.169.0,52.191.0,45.148.1,45.138.0"}
P.entries["quest:1058"] = {n="金吉尔的森林魔法",s="在小小的玛拉卡金，巫医金吉尔将三名暗夜精灵斥候关在粗陋的铁笼里。他派部落冒险者前往石爪峰，采集荒野中的材料，酿制一种阴森的森林魔法药剂。",h="在小小的玛拉卡金，巫医金吉尔将三名暗夜精灵斥候关在粗陋的铁笼里。他派部落冒险者前往石爪峰，采集荒野中的材料，酿制一种阴森的森林魔法药剂。",kw={"巨角鹿的眼球","灵龙","森林魔法","金吉尔","玛拉卡金","俘虏","石爪山","暮光奔跑者","巫医"},ang={["class:Druid"]="身为德鲁伊，你看到雄伟的 fey drakes、coursers 和古老森林的树液被采来制造致命毒药，这是对自然平衡的残酷扭曲。",["faction:Horde"]="身为部落的一员，你知道，要保住玛拉卡金，就必须镇压整片山脉中的暗夜精灵抵抗，即使要借助一位隐居巫医的非常手段。",["race:NightElf"]="身为暗夜精灵，你认为，用遭到扭曲的林地材料处决俘虏，是部落在石爪山犯下的尤为残酷的行径之一。",["race:Troll"]="身为巨魔，你知道，金吉尔阴森的幽默和实用的巫毒炼金术，正是暗矛巫医技艺的鲜明特征。"},sec={{t="苦涩的药剂",b="在部落的看管下，巫医金吉尔在玛拉卡金的红岩峡谷中施展巫术。三名暗夜精灵俘虏落入他手中后，他没有选择寻常的屠杀，而是为这些林地仇敌准备了一场充满嘲弄的仪式。他派旅人北上群峰，采集浓稠的树液、食肉猛兽 暮光豹 的胡须、一片闪光的灵龙的鳞片，以及当地 森林奔跑者 的数十只眼睛。"},{t="家园的滋味",b="金吉尔嬉闹的举止下，藏着巨魔残酷的幽默。他说，这剂药能让囚禁中的精灵感到宾至如归，尽管这里没有森林供他们嬉戏。但魔法生物的材料与浓缩树液混合后，却成了极不稳定的致命毒液。当金吉尔在洞穴里释放这剂药时，笼中的俘虏在毒气中窒息而亡。他们的肉身死去，祖灵化作发光的小精灵，飘入群山，只留下空荡荡的牢笼。"}},faq={{q="巫医金吉尔是谁？",a="巫医金吉尔是一名暗矛巨魔，身处石爪山脉南部的玛拉卡金。他运用巨魔炼金术、巫毒和审讯手段，协助部落对抗暗夜精灵。",al={"金吉尔 是谁","巫医金吉尔","金吉尔 的故事"}},{q="金吉尔为什么需要这么多巨角鹿的眼球？",a="金吉尔说，强大的森林魔法需要大量眼睛。巨魔巫医会在药剂中使用奇异的生物材料，但这荒唐的数量也很符合金吉尔古怪而睚眦必报的性情。",al={"为何需要 巨角鹿 的眼睛","三十只 巨角鹿 的眼睛","为何需要这么多眼睛"}},{q="任务结束时，笼中的暗夜精灵会遭遇什么？",a="你带回材料后，金吉尔会在洞穴中释放有毒的药剂。三名俘虏中毒身亡，灵魂化作小精灵飘走。",al={"精灵的遭遇","笼中精灵的命运","金吉尔 的俘虏"}},{q="这些材料都在哪里？",a="你可以在暗色湖周围和北部高地采集巨角鹿的眼球与石爪苔液。暮光 的胡须和稀有的灵龙的鳞片来自更北面的石爪峰附近，那里有魔法野兽出没。",al={"森林魔法材料位置","石爪苔液位置","灵龙的鳞片位置"}},{q="部落为什么在石爪山与暗夜精灵交战？",a="部落在邻近灰谷的伐木活动，招致了哨兵的激烈抵抗。暗夜精灵仍然控制着石爪峰及其神圣林地，居高俯视玛拉卡金等部落前哨。",al={"为何在 石爪山 对抗暗夜精灵","石爪山 部落与暗夜精灵的冲突","石爪山 战争"}},{q="垂死的精灵为什么会变成小精灵？",a="小精灵是死去的暗夜精灵的灵魂，与自然紧密相连。暗夜精灵死后，灵魂会化作发光的树木精魂，而非以普通幽灵或阴魂的形态徘徊。",al={"精灵为何变成小精灵","洞穴中的精灵亡魂","小精灵的故事"}}},fp="22,162,13.410.0,15.452.1,28.193.0,43.198.0,62.159.1,35.219.0,52.192.0,39.182.0"}
P.entries["quest:1059"] = {n="夺回焦炭谷",s="守护者奥巴格姆正向遥远的南方求援，以拯救焦炭谷。血怒鹰身人暂时被击退了，但要让这片受创的土地恢复生机，仅靠武力还不够。",h="守护者奥巴格姆正向遥远的南方求援，以拯救焦炭谷。血怒鹰身人暂时被击退了，但要让这片受创的土地恢复生机，仅靠武力还不够。",kw={"血怒鹰身人","焦炭谷","法芬德尔","菲拉斯","萨兰纳尔","守护者奥巴格姆","石爪峰","千针石林"},ang={["class:Druid"]="身为德鲁伊，你也肩负着塞纳里奥的职责：向当地驻军之外寻求援助，召唤原始的自然之灵，治愈因非自然力量的破坏而伤痕累累的土地。",["faction:Alliance"]="身为联盟的一员，你依靠石爪峰的据点，以及卡利姆多广袤争夺地带上各个边境哨站之间的联系。"},sec={{t="山谷的创伤",b="焦炭谷位于石爪山脉南部，覆盖着灰烬，惨烈的破坏在这里留下了累累伤痕。守护者奥巴格姆率领的联盟部队已将血怒鹰身人赶出了废墟中的巢穴，但她们随时可能卷土重来。奥巴格姆知道，武力只能暂时阻挡鹰身人。必须在她们返回并再次占据山谷之前，治愈这片饱受蹂躏的大地。"},{t="向南方求援",b="要让这片焦土恢复生机，林地的照料者们需要借助外界的力量。奥巴格姆派你南下，穿过千针石林的盐滩和峡谷，前往菲拉斯边境的萨兰纳尔。法芬德尔在那里等候。这位暗夜精灵德鲁伊以一种罕见的天赋闻名：召唤古老的森林之灵，让死寂的土壤重获生机。"}},faq={{q="守护者奥巴格姆是谁？",a="守护者奥巴格姆是石爪峰的一位丛林守护者。他负责指挥联盟净化并修复满目疮痍的焦炭谷。",al={"奥巴格姆是谁","守护者奥巴格姆"}},{q="法芬德尔在哪里？",a="法芬德尔位于萨兰纳尔，就在千针石林西部与菲拉斯接壤的边境。",al={"法芬德尔在哪","法芬德尔位置","寻找法芬德尔"}},{q="为什么要远赴菲拉斯寻求一位德鲁伊的帮助？",a="守护者奥巴格姆相信，法芬德尔能召唤古老的森林之灵，它们的力量足以治愈焦炭谷深重的创伤。",al={"为什么去菲拉斯","为什么找法芬德尔"}},{q="焦炭谷中有哪些威胁？",a="敌对的血怒鹰身人、火元素和野兽栖息在山谷中，在大火过后的土地上繁衍壮大。",al={"焦炭谷敌人","什么在攻击山谷"}},{q="这个任务需要战斗吗？",a="不需要战斗。你要穿越卡利姆多中部和南部，传递奥巴格姆的口信。",al={"这个任务难吗","焦炭谷任务战斗"}},{q="如何从石爪山脉前往千针石林？",a="从石爪山脉向东进入贫瘠之地，再沿黄金之路南下。乘坐升降梯下到千针石林，然后继续向西前往菲拉斯。",al={"怎么去千针石林","前往菲拉斯的路线"}}},fp="27,176,21.335.0,19.328.0,23.130.0,37.96.0,44.127.0,40.116.0,31.96.0,50.171.0"}
P.entries["quest:106"] = {n="年轻的恋人",s="梅贝尔·马科伦爱着托米·乔·斯通菲尔德，尽管两家是死对头。她请你把信带给河边的他。",h="梅贝尔·马科伦爱着托米·乔·斯通菲尔德，尽管两家是死对头。她请你把信带给河边的他。",kw={"艾尔文森林","世仇","情书","马科伦农场","梅贝尔·马科伦","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻的恋人"},ang={["faction:Alliance"]="作为途经艾尔文的联盟成员，你或许会替相互仇视的斯通菲尔德与马科伦家族两家传递消息。即使王国危机四伏，小小的情伤也依然存在。",["race:Human"]="作为熟悉艾尔文的人类，你听说过斯通菲尔德与马科伦家族两家的宿怨。梅贝尔和托米·乔的恋情，是邻里间一桩敏感的丑闻。"},sec={{t="禁忌之恋",b="在艾尔文南部的农耕地带，斯通菲尔德与马科伦家族两家的积怨已延续多年。梅贝尔若去探望托米·乔，就会惹怒家人。因此，她托付旅人穿过两座农场之间的界线，为她传递书信。"},{t="河畔幽会",b="托米·乔待在斯通菲尔德农场西边不远处的宁静河岸上，避开亲人的视线。梅贝尔的来信让他感到宽慰，也勾起了新的思念。分离之苦渐渐令他无法承受，两人开始设法秘密相会。"}},faq={{q="谁提供年轻的恋人任务？",a="艾尔文森林马科伦农场的梅贝尔·马科伦提供这个任务。她爱着托米·乔·斯通菲尔德，但两家是死对头，因此他们无法公开见面。",al={"谁提供年轻的恋人","找谁接年轻的恋人","年轻的恋人任务提供者"}},{q="在哪里能找到托米·乔·斯通菲尔德？",a="托米·乔·斯通菲尔德在斯通菲尔德农场西边不远处的河岸上等候，这座农场位于马科伦农场的正西方。他在那里避开家人的视线。",al={"托米·乔·斯通菲尔德在哪里","寻找托米·乔","托米·乔的位置"}},{q="为什么梅贝尔和托米·乔无法相聚？",a="斯通菲尔德与马科伦家族两家多年来一直互怀怨恨。两家都不许自家的孩子与对方来往，因此这对年轻恋人只能秘密通信。",al={"两家为何争斗","斯通菲尔德与马科伦的世仇","梅贝尔和托米·乔为何不能见面"}},{q="这个任务要你递送什么物品？",a="你要把梅贝尔的情书带给河边的托米·乔·斯通菲尔德。信中向他倾诉了她的爱意与忠贞，无论两家是否有仇。",al={"梅贝尔的信是什么","年轻的恋人要递送什么","艾尔文情书"}},{q="托米·乔收到信后有什么反应？",a="托米·乔欣喜万分，称梅贝尔是他乏味生活中的光芒。她的话让他再也无法忍受分离，因此他开始寻找让两人相会的办法。",al={"托米·乔有何反应","托米·乔的回应","送信后会发生什么"}},{q="这个任务发生在哪里？",a="故事发生在艾尔文森林南部，地点介于马科伦农场与斯通菲尔德农场旁的河流之间。人类王国这片宁静的农耕角落，正被一场琐碎的家族争端所困扰。",al={"年轻的恋人发生在哪里","年轻的恋人所在区域","斯通菲尔德农场的位置"}}},fp="12,138,19.252.0,24.243.0,33.165.0,40.161.0,41.162.0,43.130.0,39.166.0,33.194.0"}
P.entries["quest:1060"] = {n="写给金吉尔的信",s="达索克·快刀派你从贫瘠之地北部前往石爪山脉，给他的老朋友巫医金吉尔捎去消息。塞瑞娜·血羽已经倒下，达索克希望金吉尔得知此事。",h="达索克·快刀派你从贫瘠之地北部前往石爪山脉，给他的老朋友巫医金吉尔捎去消息。塞瑞娜·血羽已经倒下，达索克希望金吉尔得知此事。",kw={"血怒","达索克·快刀","鹰身人","写给金吉尔的信","玛拉卡金","塞瑞娜·血羽","石爪山脉","巫医金吉尔"},ang={["faction:Horde"]="身为部落战士，你将保障贫瘠之地内部商路安全的行动推进到争夺中的石爪山脉。",["race:Troll"]="身为巨魔，你在玛拉卡金找到了金吉尔的洞穴。这里是暗矛巨魔守卫进山要道的重要精神与战术据点。"},sec={{t="送往山中的消息",b="塞瑞娜·血羽倒下后，达索克·快刀派你前往石爪山脉。巫翼和血羽两个族群来自贫瘠之地北部西北方向的崎岖山岭，而非灌木荒地。如今你已击败塞瑞娜，达索克请你将她的死讯带给他的旧识巫医金吉尔。金吉尔住在险峻群山中的巨魔聚落玛拉卡金。"},{t="血怒之爪的回响",b="巫医金吉尔听闻塞瑞娜·血羽已经倒下，想起了早年的一场征战。暗影猎手洛克汉和四处游历的兽王雷克萨曾杀死塞瑞娜的姐姐血羽。塞瑞娜的死，让部落边境哨所与卡利姆多嗜血鹰身人之间的漫长争斗有了终于落幕的意味。"}},faq={{q="谁提供写给金吉尔的信任务？",a="完成对塞瑞娜·血羽的猎杀后，达索克·快刀会在贫瘠之地的十字路口交给你这项任务。",al={"任务给予者","哪里接任务","谁提供写给金吉尔的信"}},{q="在哪里可以找到巫医金吉尔？",a="巫医金吉尔住在玛拉卡金的一处洞穴中。这里是暗矛巨魔的营地，位于从贫瘠之地通往石爪山脉的主路旁。",al={"金吉尔 在哪里","金吉尔 位置","玛拉卡金位置"}},{q="达索克为什么派你前往石爪山脉？",a="达索克派你去告诉他的老朋友金吉尔，塞瑞娜·血羽的死已瓦解了鹰身人的威胁。他也借此将一位能干的冒险者引向石爪山脉，去应对部落在那里面临的更多挑战。",al={"为何前往 石爪山","达索克 为何送信"}},{q="金吉尔提到的是塞瑞娜的哪位姐姐？",a="金吉尔指的是血羽，也就是塞瑞娜的姐姐，她多年前曾肆虐卡利姆多。暗影猎手洛克汉和半食人魔战士雷克萨在随初建的部落四处征战时杀死了她。",al={"塞瑞娜 的姐姐","洛克汉 与雷克萨 鹰身人","血怒"}},{q="这个任务属于更大的任务链吗？",a="是的。这个任务接续鹰身强盗、鹰身人首领和塞瑞娜·血羽，为贫瘠之地北部的鹰身人猎杀行动画上句号。它也将你引向石爪山脉。",al={"任务链","前置条件","前置任务是什么"}},{q="哪个阵营可以接取这项任务？",a="只有部落可以接取这项任务。达索克·快刀和巫医金吉尔都在为部落边疆效力。",al={"是否仅限部落","联盟能否接取此任务"}}},fp="17,185,28.409.0,29.322.1,38.124.0,38.147.0,49.214.0,55.201.0,37.167.0,37.114.0"}
P.entries["quest:1061"] = {n="石爪之灵",s="石爪山的精魂躁动不安，佐尔·孤树派部落勇士西行，查明缘由。他们从奥格瑞玛出发，途经十字路口，直接向巨木谷附近的希雷斯·碎石报到。",h="石爪山的精魂躁动不安，佐尔·孤树派部落勇士西行，查明缘由。他们从奥格瑞玛出发，途经十字路口，直接向巨木谷附近的希雷斯·碎石报到。",kw={"十字路口","森林砍伐","巨木谷","希雷斯·碎石","石爪山脉","智慧谷","荆棘谷地精","佐尔·孤树"},ang={["class:Shaman"]="身为萨满祭司，你听到了元素的恳求，要你修复大地与生灵之间的纽带。",["faction:Horde"]="身为部落的一员，你帮助清除盘踞在石爪山与贫瘠之地之间交通要道上的不法商业财团。",["race:Tauren"]="身为牛头人，你肩负着族群传承的责任，要安抚大地，保护神圣的森林免遭地精砍伐。"},sec={{t="西方的呼声",b="在索尔的堡垒，佐尔·孤树聆听自然的声音，感受到石爪山脉传来的深切痛苦。伐木活动摧残着那里的森林，令岩峰间的元素之灵怒不可遏。部落萨满祭司听到了这份不安，担心西部高地遭受的破坏会打破卡利姆多的灵性平衡。"},{t="工业伐林",b="荆棘谷地精是一个不择手段的地精财团，正在巨木谷砍伐树木。它的作业队伍动用强力机械、锯子和蛮力，肆意摧残古老的林地，毫无节制地采伐。部落派年轻的萨满祭司希雷斯·碎石前往边境守望森林，召集守卫者抵抗这些破坏者。"}},faq={{q="这个任务由谁发布，发布者在哪里？",a="兽人顾问佐尔·孤树在奥格瑞玛的索尔的堡垒提供这个任务。",al={"任务发布者","哪里接任务","佐尔·孤树位置"}},{q="在哪里可以找到希雷斯·碎石？",a="希雷斯·碎石在石爪山脉巨木谷附近的小路旁等候，从贫瘠之地北部进入东侧入口后不远就能找到她。",al={"希雷斯位置","希雷斯·碎石在哪里","石爪山营地"}},{q="石爪山的精魂为何愤怒？",a="荆棘谷地精的地精正在将山林砍伐殆尽，激怒了这片土地的元素守护者。",al={"精魂为何愤怒","石爪山的动荡","愤怒的精魂"}},{q="如何从奥格瑞玛前往石爪山脉？",a="从奥格瑞玛向南，穿过贫瘠之地抵达十字路口，然后沿向西的道路穿过岩石隘口，进入石爪山。",al={"前往石爪山的道路","如何前往石爪山","前往石爪山的路线"}},{q="与希雷斯交谈后，接下来做什么？",a="希雷斯·碎石会在她的营地交给你地精侵略者任务，派你进入巨木谷，消灭伐木工，遏制他们的伐木活动。",al={"下一个任务","后续任务","石爪山的灵魂之后做什么"}},{q="部落为何干预石爪山的森林砍伐？",a="牛头人和兽人的萨满祭司敬畏元素之灵。地精肆无忌惮的伐木活动破坏了这片土地的灵性和谐，也威胁着贫瘠之地的边境。",al={"部落为何关心","牛头人为何关心石爪山"}}},fp="25,197,19.324.0,24.346.0,49.72.0,36.147.0,40.107.0,55.135.0,44.144.0,59.153.0"}
P.entries["quest:1062"] = {n="地精侵略者",s="在贫瘠之地与石爪山脉的交界处，希雷斯·碎石派部落前往狂风峭壁，打击荆棘谷地精的伐木工。他们的作业正在摧毁山中古老的林地。",h="在贫瘠之地与石爪山脉的交界处，希雷斯·碎石派部落前往狂风峭壁，打击荆棘谷地精的伐木工。他们的作业正在摧毁山中古老的林地。",kw={"地精","巨木谷","伐木工","希雷斯·碎石","灵魂","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="身为德鲁伊，你将狂风峭壁中生机盎然的林地与古树遭到摧毁，视为对你所守护的自然秩序的侵害。",["class:Shaman"]="身为萨满祭司，你能感受到当地的元素生物与自然之灵在呼号，在浓烟与地精机械的破坏中被愤怒蒙蔽。",["faction:Horde"]="身为部落的一员，你协助守卫贫瘠之地与高处山口之间的边境地带，使敌对的商业集团无法在卡利姆多中部建立坚固据点。",["race:Tauren"]="身为牛头人，你有迫切的理由对抗荆棘谷地精：它对石爪山脉森林的破坏，折磨着你与Earth Mother一同尊崇的大地之灵。"},sec={{t="痛苦中的森林",b="荆棘谷地精已深入石爪山脉，在峭壁与山谷间大肆破坏。它的伐木工砍光山坡上的树木，烧毁灌木丛，只留下一片焦土。对牛头人及其盟友而言，这不仅仅是一家采矿伐木公司对森林的破坏。与石爪山脉相连的原始之灵在折磨中哀嚎。驻守在山脉边界的希雷斯·碎石看到，地精无休止的侵袭已让这些灵魂被痛苦与愤怒蒙蔽。"},{t="武力的语言",b="荆棘谷地精的高管和雇工只在乎利润，道理无法说服他们。希雷斯派旅人穿过巨木谷，进入狂风峭壁，杀死十五名伐木工。部落打算用武力回应这家公司的贪婪，阻止森林遭到砍伐，并为牛头人长者争取时间，安抚这片土地上躁动的灵魂。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一名兽人萨满祭司，驻守在贫瘠之地与石爪山脉交界处的南部边界附近。她监视着敌对势力的侵入，并努力维护这一地区的灵魂平衡。",al={"希雷斯·碎石","任务给予者","谁给予地精侵略者任务"}},{q="地精为什么要砍伐石爪山脉的森林？",a="荆棘谷地精一味追逐利润，毫不在乎造成的破坏。它将石爪山脉的古老森林和矿藏丰富的丘陵视为可供采集、加工和出售的原料，全然不顾留给自然与灵魂的浩劫。",al={"荆棘谷地精为何伐木","荆棘谷地精在石爪山脉的动机","为什么砍树"}},{q="狂风峭壁在哪里？",a="狂风峭壁位于石爪山脉中部。从贫瘠之地边界沿山路向西北行进，穿过巨木谷，就能抵达峭壁。那里的森林已被荆棘谷地精的伐木营地和树木遭到砍光的山丘取代。",al={"狂风峭壁位置","伐木工在哪里","哪里能找到荆棘谷地精的伐木工"}},{q="灵魂对荆棘谷地精的到来有何反应？",a="希雷斯·碎石说，砍伐与焚烧带来的愤怒和痛苦，让大地之灵几近疯狂。它们的苦难扰乱了自然的平衡，也威胁着整个地区的灵魂安宁。",al={"石爪山脉的灵魂愤怒","石爪山脉灵魂的反应"}},{q="击杀荆棘谷地精的伐木工之后会怎样？",a="杀死伐木工只是对这项作业的第一轮打击。接下来，希雷斯会指引部落攻击这家公司的机械，并建议寻找牛头人长者作为向导，帮助安抚受伤的灵魂。",al={"地精侵略者之后","伐木工之后的任务"}},{q="部落为什么关心石爪山脉的伐木活动？",a="石爪山脉对牛头人的文化与精神生活意义重大。部落也认为，荆棘谷地精肆无忌惮的侵略和对资源的掠夺，威胁着部落在这一地区的影响力与灵魂的和谐。",al={"部落在石爪山脉的利益","部落为何对抗荆棘谷地精"}}},fp="15,183,17.399.0,21.343.0,26.213.0,53.223.0,32.234.0,59.201.0,55.207.1,52.237.0"}
P.entries["quest:1063"] = {n="长者",s="希雷斯·碎石从石爪山向雷霆崖传来消息。地精的伐木和采矿激怒了山中的元素，它们需要灵性上的引导，因此希雷斯派出使者，向长者高地的玛加萨·野性图腾寻求指点。",h="希雷斯·碎石从石爪山向雷霆崖传来消息。地精的伐木和采矿激怒了山中的元素，它们需要灵性上的引导，因此希雷斯派出使者，向长者高地的玛加萨·野性图腾寻求指点。",kw={"长者","长者高地","恐怖图腾","玛加萨","希雷斯·碎石","灵体","石爪山","牛头人","雷霆崖"},ang={["class:Shaman"]="身为萨满祭司，你深知石爪山元素动荡的严重性。前往长者高地寻求玛加萨的指点，反映出卡利姆多群峰间的灵性危机。",["faction:Horde"]="当石爪山边境的困境传入雷霆崖领袖的高堂时，你看到了部落各方的联系如何发挥作用。",["race:Tauren"]="身为牛头人，你看到了凯恩统一的各部族与居住在雷霆崖的恐怖图腾之间，平衡是何等脆弱，后者孤傲疏离，又极为恪守传统。"},sec={{t="石爪山的呼声",b="地精的伐木和采矿激怒了石爪山脉的元素之灵。希雷斯·碎石明白，仅凭武力无法平息这片土地在灵性上的苦痛，于是向年长的萨满祭司寻求智慧。希雷斯叫得出名字的部族领袖寥寥无几，却听说过玛加萨·野性图腾，这位长者以渊博的学识和威严的气度闻名。"},{t="长者高地的会面",b="玛加萨·野性图腾在雷霆崖的长者高地接见来客，这里汇集着萨满与灵性事务。恐怖图腾部族与凯恩·血蹄领导层的关系紧张，时常针锋相对。即便如此，玛加萨仍是一位极具威望的长者，她的意见在整个部落都举足轻重。你将石爪山的困境带到她面前，寻求她的指引。"},{t="务实的联盟",b="玛加萨·野性图腾将元素动乱的消息传给居住在城中的被遗忘者炼金师，而非仅仅依靠牛头人的传统仪式。她让部落中新近加入、也最为愤世嫉俗的盟友介入卡利姆多的灵性事务，展现出她运用权力、处理难题时的精明与不拘常规。"}},faq={{q="是谁派我去找玛加萨的？",a="在你与砍伐山林的荆棘谷地精的地精交战后，石爪山脉的希雷斯·碎石派你前去。",al={"任务给予者","任务由谁开启","希雷斯·碎石"}},{q="玛加萨·野性图腾在哪里？",a="玛加萨·野性图腾住在雷霆崖的长者高地上，那里位于东北侧的崖顶，通过木桥与中央台地相连。",al={"玛加萨位置","玛加萨在哪里","长者高地"}},{q="希雷斯为什么要向一位年长的牛头人求助？",a="地精的工业活动惊扰了石爪山的灵体。希雷斯明白，仅凭武力无法治愈这片土地，因此寻求灵性上的指引，以平息元素的怒火。",al={"为何称为长者","为何请教玛加萨"}},{q="玛加萨·野性图腾是谁？",a="玛加萨·野性图腾是一位年迈的老妪，也是恐怖图腾部族的女族长。她的部族极具攻击性，对统一的部落心存疑虑，而玛加萨在雷霆崖上拥有极大的政治与灵性影响力。",al={"长者背景故事","长者是谁","玛加萨背景"}},{q="与玛加萨交谈之后会发生什么？",a="玛加萨听取你关于石爪山的报告后，派你去找药剂师扎玛寻求帮助。这位被遗忘者使者位于灵魂高地下方的预见之池。",al={"接下来做什么","后续任务"}},{q="这个任务为什么叫“长者”？",a="这个称号指的是玛加萨·野性图腾。她年事已高，通晓萨满之道，又拥有女族长的权威，因此无论是她自己的氏族，还是其他牛头人，都称她为长者。",al={"为何称为老妪","长者称号"}}},fp="15,208,19.331.0,22.348.0,20.331.1,29.136.0,35.129.0,47.153.0,25.218.0,41.153.1,43.170.0"}
P.entries["quest:1064"] = {n="被遗忘者的援助",s="在雷霆崖，玛加萨·野性图腾派你为石爪山饱受侵蚀的灵魂寻求帮助。她向驻于预见之池的被遗忘者使者药剂师扎玛求助，希望将牛头人与亡灵的知识结合起来。",h="在雷霆崖，玛加萨·野性图腾派你为石爪山饱受侵蚀的灵魂寻求帮助。她向驻于预见之池的被遗忘者使者药剂师扎玛求助，希望将牛头人与亡灵的知识结合起来。",kw={"药剂师扎玛","被遗忘者的援助","玛加萨·野性图腾","预见之池","毒蛇信使","灵魂高地","石爪山脉","雷霆崖"},ang={["faction:Horde"]="部落对牛头人的援助，将卡利姆多与洛丹伦联结在自第三次大战以来逐渐形成的同盟之中。",["race:Tauren"]="牛头人常常依靠德鲁伊之道与 Earth Mother 来治愈大地。玛加萨转而求助于亡灵炼金师，展现了她在部族外交上不循常规的做法。",["race:Undead"]="对被遗忘者而言，以炼金术援助牛头人，是证明自身价值、在心存戒备的部落内部赢得信任的机会。"},sec={{t="务实的合作",b="玛加萨·野性图腾看重与被遗忘者结盟的实际价值。当石爪山脉的元素之灵遭到腐化、土地饱受苦难的消息传到雷霆崖时，她向亡灵寻求帮助。她相信，了解疾病的人能够帮助治愈疾病，因此派你去找皇家药剂师学会，而非寻求传统的德鲁伊疗法。"},{t="灵魂高地之下",b="药剂师扎玛驻于灵魂高地下方的预见之池，代表幽暗城在卡利姆多的利益。牛头人的萨满祭司、牧师和先知将这处洞穴视为静修的圣地，而扎玛的到来将被遗忘者的工作带到了他们中间。玛加萨派出一条蛇作为信使，先行通知扎玛，由此与被遗忘者的炼金研究者建立直接联系。"}},faq={{q="玛加萨·野性图腾为何就石爪山的问题向被遗忘者求助？",a="玛加萨相信，被遗忘者对瘟疫和疾病的了解能够帮助诊断并治疗石爪山脉的病症。",al={"为何提供 被遗忘者的援助","玛加萨 与亡灵","为何向 被遗忘者 求助"}},{q="在哪里可以找到药剂师扎玛？",a="药剂师扎玛住在预见之池，那是雷霆崖西北方台地上、灵魂高地下方的一处地下洞穴。上方台地水池附近的一条洞穴通道通往其中。",al={"药剂师扎玛 位置","扎玛 在哪里","预见之池入口"}},{q="接受玛加萨的任务后会发生什么？",a="当你接受玛加萨的请求时，她会召唤一条毒蛇信使。它时而蜿蜒爬行，时而腾空飞起，穿过雷霆崖前往药剂师扎玛那里，通报你即将到来。",al={"毒蛇信使","玛加萨 的蛇"}},{q="被遗忘者如何看待帮助石爪山的牛头人？",a="药剂师扎玛对石爪山饱受折磨的灵魂表示同情。她说，被遗忘者渴望提供帮助，并加强与部落的联系。",al={"被遗忘者 援助 石爪山 的动机","扎玛 为何提供帮助"}},{q="与扎玛交谈后会开启什么任务线？",a="见过扎玛后，调查转向被遗忘者的炼金术，并最终引出前往东部王国的任务前往塔伦米尔，让你在那里向更高阶的药剂师请教。",al={"接下来做什么","被遗忘者的援助 的后续任务"}},{q="被遗忘者为何驻扎在神圣的预见之池内？",a="预见之池汇聚了部落的学者、法师和先知。药剂师扎玛以正式使者和研究者的身份在那里工作，让她那些备受争议的实验远离主要通道。",al={"亡灵为何在预见之池","灵魂高地的亡灵"}}},fp="12,212,23.361.0,23.359.0,66.134.0,36.187.0,52.160.0,64.152.0,50.185.0,65.199.0"}
P.entries["quest:1065"] = {n="塔伦米尔之旅",s="药剂师扎玛正寻求一种不必公开交战就能将荆棘谷地精赶出石爪山脉的办法。她派你渡海前往塔伦米尔，拜访药剂师林度恩，皇家药剂师学会在洛丹伦的工作就在此开展。",h="药剂师扎玛正寻求一种不必公开交战就能将荆棘谷地精赶出石爪山脉的办法。她派你渡海前往塔伦米尔，拜访药剂师林度恩，皇家药剂师学会在洛丹伦的工作就在此开展。",kw={"药剂师林度恩","药剂师扎玛","希尔斯布莱德","前往塔伦米尔","石爪山","塔伦米尔","雷霆崖","幽暗城","荆棘谷地精"},ang={["faction:Horde"]="身为部落的一员，你往返于雷霆崖与塔伦米尔之间，将年轻的守护者与大海彼岸的盟友联系起来。",["race:Tauren"]="身为牛头人，石爪山遭到玷污令你深感痛心。接受被遗忘者的炼金术，意味着为了保护神圣的土地而作出令人不安的妥协。",["race:Undead"]="身为亡灵，你见证了皇家药剂师学会如何将化学知识带到大海彼岸，帮助远方的部落盟友。"},sec={{t="跨越无尽之海的求助",b="在雷霆崖，药剂师扎玛是连接被遗忘者与 大地母亲 子民的纽带。荆棘谷地精正在石爪山脉的神圣土地上伐木采矿，而牛头人发现，寻常手段无法阻止他们。扎玛向皇家药剂师学会的同僚求助，希望找到一种能震慑他们的化学药剂。她希望同僚们的炼金术能将这家公司赶走，避免陷入旷日持久的战争。"},{t="通往希尔斯布莱德之路",b="你从卡利姆多乘坐飞艇渡海，前往洛丹伦和幽暗城。从提瑞斯法林地出发，道路向南穿过银松森林，通往战火纷争的希尔斯布莱德丘陵。塔伦米尔坐落在人类农庄与废墟附近。这里曾是人类的小村落，如今已成为被遗忘者的据点，也是皇家药剂师学会开展研究的地方。"},{t="药剂师林度恩的技艺",b="药剂师林度恩在塔伦米尔研究性质不稳定的化学药剂和生物制剂。林度恩有时会在活体上试验混合药剂。扎玛的便笺说明了荆棘谷地精带来的麻烦，林度恩急切地接下了这项工作。学会很乐意有机会在新的地方试验其化合物，林度恩也开始准备对付地精的试剂。"}},faq={{q="药剂师扎玛为什么要派我远赴塔伦米尔？",a="药剂师扎玛需要一种药剂，好在不公开交战的情况下将荆棘谷地精赶出石爪山脉。她的同僚药剂师林度恩在塔伦米尔为皇家药剂师学会工作，能够配制她需要的炼金药剂。",al={"为什么去塔伦米尔","为什么派去找 林度恩","前往塔伦米尔的目的"}},{q="塔伦米尔在哪里？",a="塔伦米尔位于洛丹伦的希尔斯布莱德丘陵北部。从卡利姆多出发，先在杜隆塔尔乘坐飞艇前往提瑞斯法林地的幽暗城，再向南穿过银松森林，向东进入希尔斯布莱德。",al={"塔伦米尔在哪里","塔伦米尔位置","怎么去塔伦米尔"}},{q="药剂师扎玛和药剂师林度恩是谁？",a="药剂师扎玛和药剂师林度恩都隶属于被遗忘者的皇家药剂师学会。扎玛在雷霆崖的预见之池研究当地植物，帮助牛头人，而林度恩则在塔伦米尔进行炼金和瘟疫实验。",al={"扎玛 是谁","林度恩 是谁","药剂师们是谁"}},{q="被遗忘者为什么要帮忙对付石爪山的荆棘谷地精？",a="被遗忘者为了生存和行事便利而加入部落，牛头人则曾出面支持，确保他们在部落中占有一席之地。帮助牛头人对抗荆棘谷地精，既能巩固这份同盟，也能让被遗忘者的炼金师找到试验研究成果的地方。",al={"被遗忘者 为什么关心 石爪山","亡灵帮助牛头人 石爪山"}},{q="皇家药剂师学会是什么？",a="皇家药剂师学会是由被遗忘者炼金师和科学家组成的组织，总部位于洛丹伦废墟下方的幽暗城。在希尔瓦娜斯·风行者女士的指引下，他们研制药剂、毒药和各种瘟疫毒株，以保卫被遗忘者，消灭他们的敌人。",al={"皇家药剂师学会 是什么","被遗忘者 药剂师背景故事"}},{q="把便笺交给林度恩后会发生什么？",a="收到扎玛的请求后，药剂师林度恩开始准备解决办法。为了配制合适的混合药剂，你需要从敦霍尔德城堡的辛迪加暗影法师身上收集一瓶瓶无辜者之血。",al={"塔伦米尔之旅 后续任务","林度恩 需要什么"}}},fp="22,221,27.378.0,21.355.0,24.355.1,61.246.0,29.216.0,46.256.0,68.253.0,37.277.0,48.201.1"}
P.entries["quest:1066"] = {n="无辜者之血",s="塔伦米尔的药剂师林度恩正在寻求鲜血，用于一项对付石爪山脉荆棘谷地精的计划。皇家药剂师学会利用从当地匪徒身上收集的邪恶材料，让步步进逼的荆棘谷地精安分下来。",h="塔伦米尔的药剂师林度恩正在寻求鲜血，用于一项对付石爪山脉荆棘谷地精的计划。皇家药剂师学会利用从当地匪徒身上收集的邪恶材料，让步步进逼的荆棘谷地精安分下来。",kw={"药剂师林度恩","无辜者的鲜血","敦霍尔德城堡","暗影法师","石爪山脉","辛迪加","塔伦米尔","荆棘谷地精"},ang={["faction:Horde"]="身为部落的一员，你见证了部落遍及各地的联系如何发挥作用：洛丹伦的被遗忘者炼金术帮助保护着部落在卡利姆多的土地。",["race:Tauren"]="身为牛头人，采集无辜者鲜血的做法或许会让你感到不安。此举的目的是终结荆棘谷地精对卡利姆多荒野的破坏。",["race:Undead"]="对被遗忘者而言，效率比道德上的顾虑更重要。林度恩精于算计的做法，展现了皇家药剂师学会如何运用冷酷的逻辑，为他们活着的盟友解决难题。"},sec={{t="炼金术的解法",b="部落在石爪山脉的斗争始终未曾停歇，荆棘谷地精在那里蹂躏荒野，残害居民。药剂师林度恩提出用炼金药剂应对，而非派遣军队阻挡他们的利斧。他打算调配一种药剂，让这些雇佣兵麻痹、平静下来，变得虚弱而温顺。"},{t="从恶徒手中夺取",b="药剂师林度恩需要一种罕见而令人不安的材料：无辜者的鲜血。他没有亲自派遣部落成员去杀害无辜者，而是将目光转向了辛迪加的罪行。落魄贵族和亡命之徒占据着敦霍尔德城堡，那里的邪恶暗影法师采集无辜者的鲜血，用于亵渎仪式。林度恩便将这些法师当作获取炼金材料的目标。"}},faq={{q="药剂师林度恩为什么需要无辜者的鲜血？",a="药剂师林度恩需要无辜者的鲜血，作为一种实验药剂的关键材料。他希望制成一种毒素，消磨石爪山脉荆棘谷地精的暴戾之气，让他们安分下来，更容易控制。",al={"无辜者的鲜血用途","为何需要无辜者的鲜血","林度恩鲜血任务"}},{q="谁带着装有无辜者鲜血的小瓶？",a="辛迪加的暗影法师带着装有无辜者鲜血的小瓶。他们潜伏在塔伦米尔东南方的敦霍尔德城堡废墟中，留着这些鲜血供自己施法之用。",al={"谁掉落鲜血","何处获取无辜者的鲜血","无辜者的鲜血位置"}},{q="为什么希尔斯布莱德的任务会牵涉到石爪山脉？",a="卡利姆多的部落领袖向东部王国的皇家药剂师学会寻求科学援助。与荆棘谷地精的冲突发生在石爪山，而塔伦米尔的药剂师林度恩掌握着调配专用药剂所需的黑暗技艺。",al={"与石爪山的联系","塔伦米尔为何牵涉石爪山"}},{q="辛迪加是什么组织？",a="辛迪加由覆灭的奥特兰克王国昔日的人类贵族组成，他们如今沦为强盗、刺客和亡命之徒。为了夺回失去的土地，他们敲诈勒索，施展黑暗魔法，并劫掠途经希尔斯布莱德和奥特兰克的旅人。",al={"辛迪加是谁","辛迪加背景故事"}},{q="敦霍尔德城堡位于何处？",a="敦霍尔德城堡位于希尔斯布莱德丘陵，在塔伦米尔的东南方。这里曾是人类的要塞和关押兽人的收容所，如今已半成废墟，是辛迪加的一处重要据点。",al={"寻找敦霍尔德城堡","敦霍尔德在哪里"}},{q="部落在为获取这些鲜血而杀人吗？",a="没有。皇家药剂师学会虽然接受残忍的手段，但林度恩指示部下收集的，是辛迪加暗影法师已经从受害者身上采集的鲜血。",al={"部落是否杀害无辜者","无辜者的鲜血来源"}}},fp="18,189,19.351.0,22.331.0,46.204.0,36.168.0,60.251.0,22.247.0,32.177.0,49.165.0"}
P.entries["quest:1067"] = {n="返回雷霆崖",s="药剂师林度恩的毒素即将送往雷霆崖，扎玛正在那里等候。她需要这份配方来制作一种装置，将毒素散播出去，对付荆棘谷地精。",h="药剂师林度恩的毒素即将送往雷霆崖，扎玛正在那里等候。她需要这份配方来制作一种装置，将毒素散播出去，对付荆棘谷地精。",kw={"药剂师林度恩","药剂师扎玛","林度恩的毒药","预见之池","返回雷霆崖","皇家药剂师学会","塔伦米尔","剧毒粮草","荆棘谷地精"},ang={["faction:Horde"]="身为部落的一员，你看到被遗忘者的炼金师携手合作，对抗荆棘谷地精的破坏性活动。",["race:Tauren"]="身为Tauren，你知道玛加萨·野性图腾和长者们曾欢迎被遗忘者来到雷霆崖，希望他们能获得救赎或治愈。然而，灵魂高地下方的药剂师却在制造能够传播疫病的武器。",["race:Undead"]="身为Undead，你能看到皇家药剂师学会如何将洛丹伦的研究与卡利姆多的前哨站联系起来。"},sec={{t="跨越大陆的递送",b="药剂师林度恩用在希尔斯布莱德丘陵采集的材料制成了毒素。他想在活体上试验毒素，但这种液体需要一种散播手段。你带着这瓶毒素，穿过无尽之海前往莫高雷，药剂师扎玛正在那里等候。"},{t="扎玛的装置",b="药剂师扎玛在雷霆崖的灵魂高地下方工作，担任皇家药剂师学会的大使和研究员。她用林度恩的配方制成了一种名为剧毒粮草的气雾装置。她打算用它来对付荆棘谷地精的地精。"}},faq={{q="为什么要把毒素送到雷霆崖？",a="林度恩制成了液态毒素，但还需要一种大范围散播毒素的手段。扎玛能利用这份配方，制成一种名为剧毒粮草的气雾装置。",al={"为什么去雷霆崖","扎玛如何使用毒素","林度恩的毒素用途"}},{q="这种混合毒剂要用来对付谁？",a="这种毒素是为对付荆棘谷地精而准备的，这是一个地精采矿集团，业务遍及石爪山脉乃至更远的地方。",al={"谁会中毒","林度恩毒素的目标","交战对象"}},{q="药剂师扎玛在哪里？",a="药剂师扎玛位于雷霆崖灵魂高地下方的预见之池。",al={"寻找扎玛","药剂师扎玛在哪里","扎玛的位置"}},{q="幽暗城的药剂师为什么会在牛头人的城市里工作？",a="牛头人为被遗忘者提供了庇护，并帮助他们加入部落，希望他们能找到治愈自身苦难的方法。扎玛代表皇家药剂师学会，该组织在这里的工作却转向了瘟疫和武器，而非治疗。",al={"雷霆崖的被遗忘者","亡灵为什么在雷霆崖","莫高雷的药剂师"}},{q="交出毒素之后会发生什么？",a="扎玛收到这瓶毒素后，会制成剧毒粮草。随后，她会派你前往石爪山脉的一处荆棘谷地精设施使用它。",al={"下一个任务","返回雷霆崖之后","气雾装置任务"}},{q="最初的配方是谁研制的？",a="药剂师林度恩是皇家药剂师学会驻塔伦米尔的研究员，这种毒药就是他制成的。",al={"毒药的制作者","林度恩是谁","药剂师林度恩的故事"}}},fp="23,140,27.243.0,17.257.1,59.155.0,37.129.0,34.81.0,56.239.0,40.146.1,33.88.0"}
P.entries["quest:1068"] = {n="伐木机",s="在狂风峭壁，荆棘谷地精的伐木机伤害着石爪山脉的精魂。XT:4和XT:9肆意砍伐森林，希雷斯·碎石听见了精魂的哀号。",h="在狂风峭壁，荆棘谷地精的伐木机伤害着石爪山脉的精魂。XT:4和XT:9肆意砍伐森林，希雷斯·碎石听见了精魂的哀号。",kw={"伐木","希雷斯·碎石","伐木机","石爪山脉","荆棘谷地精","狂风峭壁","xt:4","xt:9"},ang={["class:Shaman"]="希雷斯指出，精魂魔法与自然之间有着密切联系。要维持元素平衡，就必须保护栖居在这片土地上的精魂。",["faction:Horde"]="随着部落在卡利姆多各处建立据点，遏制荆棘谷地精肆无忌惮的贪婪，对保护大地和确保石爪山脉的通行安全至关重要。",["profession:Engineering"]="XT系列伐木机械展现了先进的地精伐木机设计，将机械液压锯与蒸汽行走装置结合在一起。",["race:Tauren"]="没有灵魂的地精机械亵渎了石爪山脉的古老森林，违背了对Earth Mother的虔诚信仰。"},sec={{t="森林浩劫的幻象",b="兽人萨满祭司希雷斯·碎石驻守在贫瘠之地与石爪山脉之间尘土飞扬的边界上。她倾听着无形的灵界，但混乱淹没了石爪山脉精魂的大部分声音。一个幻象却异常清晰，令人心惊：人形机械以违背自然的速度横扫古老的森林。这些由地精制造、标记为XT:4和XT:9的伐木机正在摧残狂风峭壁的林地，让周围的自然之灵不断感受到痛苦。"},{t="让锯声止息",b="荆棘谷地精在巨木谷西北方的狂风峭壁开展作业。为了遏制破坏，部落的勇士前往那里，追踪这些伐木机械。摧毁XT:4和XT:9，能沉重打击山区的商业采伐，并暂时平息受伤树木精魂的哀号。希雷斯警告说，除非荆棘谷地精彻底撤出石爪山脉，否则这片土地还将遭受更加黑暗的暴行。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一名兽人萨满祭司，驻守在贫瘠之地与石爪山脉之间的南部边界上。她能感应大地的元素与精魂之力，为那些因荆棘谷地精迅速扩张而饱受折磨的森林精魂传达心声。",al={"希雷斯是谁","任务给予者希雷斯","希雷斯·碎石的故事"}},{q="XT:4和XT:9是什么？",a="XT:4和XT:9是荆棘谷地精在狂风峭壁使用的专用伐木机。地精操作员驾驶着这些蒸汽驱动的步行机械，砍伐古木的速度远超人力。",al={"伐木机是什么","xt4和xt9","伐木机目标"}},{q="狂风峭壁在哪里？",a="狂风峭壁位于石爪山脉北部，巨木谷的西北方。荆棘谷地精已将这里改造成一片庞大的工业伐木盆地。",al={"狂风峭壁位置","哪里能找到伐木机","机器在哪里"}},{q="萨满祭司为什么关心树木和德鲁伊魔法？",a="正如希雷斯所解释的，萨满祭司与精魂的沟通，同德鲁伊的自然魔法有着密切联系。生机盎然的森林遭受的创伤会在灵界回响，让感知敏锐的萨满祭司在察觉元素躁动的同时，也听见被屠戮的树木精魂的哀号。",al={"萨满祭司为什么关心树木","萨满祭司与德鲁伊的联系","自然之灵与萨满祭司"}},{q="这些伐木机归谁所有，又由谁操作？",a="这些伐木机属于荆棘谷地精，这是一个由地精经营、不择手段的商业集团，因无视当地生态与世代居住于此的居民，残酷掠夺宝贵的自然资源而在艾泽拉斯臭名昭著。",al={"谁制造了xt4","谁操作伐木机","荆棘谷地精的伐木机"}},{q="摧毁XT:4和XT:9能赶走荆棘谷地精吗？",a="不能。摧毁这些机器可以安抚哭泣的树木精魂，并阻碍当地的伐木作业，但荆棘谷地精在狂风峭壁各处仍保有大量工业据点。荒野的守护者必须继续抵抗他们在此地的势力。",al={"荆棘谷地精会离开吗","伐木机之后","任务结果"}}},fp="18,155,25.465.0,18.400.0,26.268.0,23.219.0,24.173.0,53.240.0,38.209.0,61.232.0"}
P.entries["quest:1069"] = {n="深苔蜘蛛的卵",s="麦伯克·米希瑞克斯看到了向藏宝海湾出售深苔蜘蛛的卵的商机。当地正风靡蜘蛛卵煎蛋，他便派旅人前往石爪山脉采集新鲜的卵，供海外贸易之用。",h="麦伯克·米希瑞克斯看到了向藏宝海湾出售深苔蜘蛛的卵的商机。当地正风靡蜘蛛卵煎蛋，他便派旅人前往石爪山脉采集新鲜的卵，供海外贸易之用。",kw={"藏宝海湾","深苔","迪兹维格","麦伯克·米希瑞克斯","煎蛋","棘齿城","希塞尔山谷","蜘蛛卵","狂风峭壁"},ang={["faction:Alliance"]="身为往来于贫瘠之地和石爪山暗夜精灵聚居地之间的联盟斥候，你可以利用棘齿城地精的中立地位赚取旅费。",["faction:Horde"]="身为穿越贫瘠之地、前往石爪山的部落旅人，你可以在棘齿城迅速赚些钱，用来对付当地的鹰身人和荆棘谷地精伐木工。",["profession:Cooking"]="身为厨师，你可以看到港口城市的食客如何将deepmoss蜘蛛卵这类奇特大胆的食物变成身份的象征。"},sec={{t="奢华的口味",b="藏宝海湾的富裕顾客和古怪海盗迷上了蜘蛛卵煎蛋，带动了无尽之海两岸对稀有食材的需求。棘齿城商人麦伯克·米希瑞克斯看到了向这座南方港口供货、大赚一笔的机会。东部王国没有这些蜘蛛，因此麦伯克将寻找蛛卵的目光投向了卡利姆多的荒野。"},{t="山间的蛛巢",b="石爪山脉中有深苔蜘蛛卵，荆棘谷地精曾在那里砍伐林木。你可以在狂风峭壁尚存的树木下找到成窝的蛛卵，也可以深入希塞尔山谷蛛网密布的深处寻找。采集蛛卵意味着要面对毒牙和密密麻麻的蜘蛛。即便是经验丰富的拾荒者，也可能受不了那些蛛群。"},{t="蒸汽蛤蜊快递",b="新鲜的蛛卵必须赶在腐坏或孵化之前运过大海。麦伯克与棘齿城的码头管理员迪兹维格合作，在驶往荆棘谷码头的地精商船上订下货舱。蛛卵装箱后，麦伯克便能从这门远洋美食贸易中赚取可观的利润。"}},faq={{q="麦伯克·米希瑞克斯为什么想要蜘蛛卵？",a="藏宝海湾的人们迷上了蜘蛛卵煎蛋，但当地没有蛛卵供应。麦伯克·米希瑞克斯看到了商机，棘齿城的地精商人可以通过向这座港口供货来获利。",al={"为什么要蜘蛛卵","麦伯克 蜘蛛卵","蛛卵有什么用"}},{q="哪里可以找到深苔蜘蛛的卵？",a="深苔蜘蛛的卵可以在贫瘠之地西北方的石爪山脉找到。可以在狂风峭壁尚存的树木下采集，也可以深入希塞尔山谷寻找。",al={"深苔 蛛卵在哪","蛛卵位置","石爪山脉蜘蛛卵位置"}},{q="麦伯克为什么警告人们不要去希塞尔山谷？",a="希塞尔山谷中有庞大的蛛群、密集的蛛网，以及被消化了一部分的猎物。麦伯克警告说，容易反胃的人应该改去狂风峭壁的树下采集蛛卵。",al={"希塞尔山谷警告","容易反胃 希塞尔"}},{q="蛛卵采集后由谁运输？",a="麦伯克与棘齿城码头的码头管理员迪兹维格合作，用商船将蛛卵运过大海，送往藏宝海湾。",al={"谁运输蛛卵","码头管理员运输","迪兹维格 蛛卵"}},{q="这些卵是生吃还是做熟后吃？",a="这些卵会被做成煎蛋，成为一道古怪的奢侈菜肴，供光顾藏宝海湾酒馆的富裕顾客和冒险者享用。",al={"蜘蛛卵怎么吃","蜘蛛卵煎蛋"}},{q="两个阵营的玩家都能完成这项任务吗？",a="可以。棘齿城是热砂港经营的开放港口，麦伯克·米希瑞克斯会向联盟和部落的旅人提供这份差事。",al={"这是中立任务吗","部落或联盟蜘蛛卵"}}},fp="20,234,18.360.0,22.352.0,24.298.0,41.187.0,44.178.0,42.185.0,34.121.0,33.126.0,48.128.0"}
P.entries["quest:107"] = {n="给威廉·匹斯特的信",s="“给威廉·匹斯特的信”是替艾尔文森林南部的米莱德·斯通菲尔德奔走的一项差事，旨在帮助一对出身世仇家族的秘密恋人。冒险者将米莱德的口信送给闪金镇的药剂师威廉·匹斯特，希望借助炼金术，让年轻的梅贝尔和托米·乔走到一起。",h="“给威廉·匹斯特的信”是替艾尔文森林南部的米莱德·斯通菲尔德奔走的一项差事，旨在帮助一对出身世仇家族的秘密恋人。冒险者将米莱德的口信送给闪金镇的药剂师威廉·匹斯特，希望借助炼金术，让年轻的梅贝尔和托米·乔走到一起。",kw={"艾尔文森林","闪金镇","米莱德·斯通菲尔德","狮王之傲旅店","梅贝尔·马科伦","米尔德丽德·斯通菲尔德","给威廉·匹斯特的信","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="当卫兵只顾应对军事威胁时，途经艾尔文森林的联盟冒险者常会帮助当地农户化解家庭危机。",["race:Human"]="斯通菲尔德家族和马科伦家族之间延续至今的仇怨，让艾尔文的人类邻里彼此疏远，也让心怀同情的长辈不得不依靠行事隐秘的信使。"},sec={{t="艾尔文的苦命恋人",b="斯通菲尔德家族和马科伦家族多年来一直比邻而居，住在艾尔文森林南部，但两家的深仇宿怨让正常往来成为奢望。年轻的托米·乔·斯通菲尔德和梅贝尔·马科伦夹在其中，只能在绝对保密的情况下相恋。双方父母始终心怀怨恨，米莱德·斯通菲尔德老奶奶却同情这对年轻恋人，想用一个不同寻常的办法让他们走到一起。"},{t="向闪金镇求助",b="米莱德·斯通菲尔德相信，寻常的劝说绝不可能打动这两家宿敌，于是派信使北上，前往闪金镇的狮王之傲旅店。她的口信要交给威廉·匹斯特，一位经验丰富的炼金师兼药剂师，也是米莱德相识多年的故人。威廉接过信，被梅贝尔和托米·乔的困境打动，决心用自己的炼金知识帮助他们。"}},faq={{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位炼金师兼药剂师，住在闪金镇的狮王之傲旅店。他是米尔德丽德·斯通菲尔德老奶奶的旧识，以调制草药和特制药水闻名。",al={"威廉·匹斯特是谁","威廉·匹斯特 闪金镇","炼金师 闪金镇"}},{q="是谁给威廉寄了信？",a="这封信出自斯通菲尔德农场的女家长米尔德丽德·斯通菲尔德老奶奶之手。她同情梅贝尔·马科伦和托米·乔·斯通菲尔德这段不被允许的恋情，希望威廉·匹斯特能想出办法帮助他们。",al={"谁寄的信","米莱德·斯通菲尔德的信","米莱德·斯通菲尔德"}},{q="梅贝尔和托米·乔为什么不能公开相守？",a="梅贝尔·马科伦和托米·乔·斯通菲尔德深深相爱，但他们的家族长期以来势同水火。米莱德·斯通菲尔德相信，威廉·匹斯特或许知道某种药水或计策，能让这对恋人冲破家族的敌意，走到一起。",al={"为什么帮助梅贝尔和托米·乔","年轻恋人任务 艾尔文","斯通菲尔德与马科伦的世仇"}},{q="在哪里能找到威廉·匹斯特？",a="威廉·匹斯特住在狮王之傲旅店里，这里是艾尔文森林闪金镇的中心酒馆，也是镇上的聚会场所。",al={"威廉·匹斯特在哪里","匹斯特的位置","狮王之傲旅店 炼金师"}},{q="米莱德·斯通菲尔德的真名是什么？",a="她的名字是米尔德丽德，威廉·匹斯特收到她的信时，提到自己已有多年没见过米尔德丽德，由此透露了她的名字。",al={"米莱德·斯通菲尔德的名字是什么","米莱德·斯通菲尔德的姓名"}},{q="威廉·匹斯特收到信后有什么反应？",a="读到米尔德丽德的信时，威廉说自己已有多年没见过米尔德丽德，也想知道她在信里说了些什么，因为她希望他的炼金技艺能帮助这对苦命恋人。",al={"威廉如何处理信件","威廉·匹斯特的反应"}}},fp="15,210,22.337.0,22.388.0,22.189.0,29.149.0,59.248.0,34.83.0,38.108.0,42.143.0"}
P.entries["quest:1070"] = {n="守卫石爪山",s="在灰谷，哨兵塞恩希尔派旅行者南下，探望凯拉·影矛。这名斥候与一位侏儒法师一同前往石爪山，监视荆棘谷地精的入侵行动，但她已音讯全无。",h="在灰谷，哨兵塞恩希尔派旅行者南下，探望凯拉·影矛。这名斥候与一位侏儒法师一同前往石爪山，监视荆棘谷地精的入侵行动，但她已音讯全无。",kw={"灰谷","凯拉·影矛","守卫石爪山","哨兵塞恩希尔","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["faction:Alliance"]="这标志着联盟的边境防务向南延伸，从灰谷的防御前哨扩展到石爪山脉中孤立的侦察哨位。",["race:Gnome"]="身为侏儒，哨兵们对侏儒魔法与机械装置的深切怀疑，可能会让你感到难以融入。在她们眼中，卡利姆多荒野中的侏儒法师是个古怪而难以预测的存在。",["race:NightElf"]="身为暗夜精灵，你能看到传统哨兵与来自东部王国的盟友在奥术和机械技艺上的隔阂，尤其是与侏儒之间的隔阂。"},sec={{t="南下的斥候",b="在阿斯特兰纳，哨兵塞恩希尔警戒着逼近这片古老森林的威胁。她的朋友凯拉·影矛奉哨兵莱恩·狼行者之命前往石爪山脉，调查高地上的动乱。塞恩希尔请路过的联盟勇士寻找凯拉；她一直没有收到消息，十分担心朋友的安危。"},{t="峭壁间的不安合作",b="凯拉的同伴是一位由联盟领袖指派的侏儒法师。暗夜精灵出于战略考虑加入了大联盟，但许多哨兵并不信任荒野中的奥术施法者和侏儒工匠。凯拉驻守在狂风峭壁上方高崖的一处前哨，监视荆棘谷地精大肆破坏荒野的行径。"}},faq={{q="谁提供这个任务？",a="灰谷阿斯特兰纳的暗夜精灵哨兵——哨兵塞恩希尔提供这个任务。",al={"任务提供者","从哪里开始","谁提供石爪山的守卫"}},{q="在哪里可以找到凯拉·影矛？",a="凯拉·影矛驻扎在石爪山脉的一道岩石山脊上，俯瞰着通往狂风峭壁的山谷入口。",al={"凯拉位置","寻找凯拉","凯拉·影矛位置"}},{q="哨兵塞恩希尔为什么担心凯拉？",a="凯拉前去调查石爪山危险的敌对入侵行动，却一直没有传回消息。塞恩希尔也对被指派与她同行的侏儒法师心存疑虑，认为这样的搭档预示着麻烦。",al={"为何担忧","塞恩希尔的担忧"}},{q="石爪山脉有哪些威胁？",a="荆棘谷地精是一个不择手段的地精采矿伐木集团，正在大肆摧残荒野。凶猛的本地野兽和敌对的部落势力也正从南方逼近。",al={"石爪山敌人","石爪山有谁"}},{q="塔拉是谁？",a="塔拉是哨兵塞恩希尔的名字。见到凯拉时，她会亲切地称老朋友为塔拉，并为这位朋友协调斥候与冒险者的工作感到自豪。",al={"塔拉是谁","提及塔拉"}},{q="找到凯拉·影矛之后会发生什么？",a="抵达凯拉所在之处便完成了这段旅程，随后还需继续协助她和她的侏儒搭档，监视逼近狂风峭壁的威胁。",al={"后续任务","接下来做什么"}}},fp="22,195,18.321.0,32.342.0,21.75.0,35.125.0,45.204.0,52.184.0,12.164.0,45.145.0"}
P.entries["quest:1071"] = {n="侏儒学者",s="在狂风峭壁，加克希姆·尘链正竭力阻止荆棘谷地精向森林推进。他请旅行者击退那里的工人，好让他筹备新的防御措施。",h="在狂风峭壁，加克希姆·尘链正竭力阻止荆棘谷地精向森林推进。他请旅行者击退那里的工人，好让他筹备新的防御措施。",kw={"毁林工","炸药","加克希姆·尘链","侏儒","伐木工","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["profession:Engineering"]="身为工程师，你或许能理解加克希姆为何坚信机械与化学能够化解环境危机，也能理解他对高能炸药的偏爱。",["race:Gnome"]="身为侏儒，你能看出加克希姆正在践行自己的抱负：他试图用聪明才智与高能炸药，应对自然与文明之间的冲突。",["race:NightElf"]="身为暗夜精灵，你知道Kaldorei哨兵对侏儒机械深怀疑虑。在石爪山脉，荆棘谷地精不断推进，任何有效的威慑手段都受到欢迎。"},sec={{t="矛盾重重的联盟",b="加克希姆·尘链代表着奥术、炼金术与工程学启蒙协会。在石爪山脉的古老林地中，他肩负着一项使命：向崇拜自然的暗夜精灵证明，侏儒的发明能够保护他们饱受威胁的土地。他将魔法、化学药剂与机械相结合，但荆棘谷地精步步紧逼，几乎不给他制造防御装置的时间。"},{t="在狂风峭壁争取时间",b="加克希姆派旅行者前往狂风峭壁浓烟滚滚的工地，击退风险投资公司. 伐木工和砍树工。只要他们撤退，他就能腾出时间整理工坊，并构思下一步的防御手段：有控制、有策略地使用高能炸药。"}},faq={{q="加克希姆·尘链是谁？",a="加克希姆·尘链是石爪山脉的一名联盟侏儒法师，也是一位工匠。他为奥术、炼金术和工程学启蒙协会效力，力图帮助暗夜精灵对抗工业入侵者。",al={"加克希姆","加克希姆·尘链是谁","任务给予者加克希姆"}},{q="为什么一个侏儒要保护暗夜精灵的森林？",a="加克希姆认为，他必须向心存疑虑的暗夜精灵证明，侏儒科学能够与自然共存，并守护他们的荒野。他运用奥术学、炼金术和工程学，对抗毫无节制的工业开发。",al={"侏儒为何在石爪山脉","为何帮助暗夜精灵","侏儒生态学"}},{q="狂风峭壁的荆棘谷地精是什么组织？",a="荆棘谷地精是一个由地精经营的商业集团，在狂风峭壁伐木，并进行露天采矿。为了攫取利润，他们的伐木工、毁林工和重型机械已遍布整座山谷。",al={"石爪山脉荆棘谷地精","荆棘谷地精是什么组织","狂风峭壁地精"}},{q="在哪里能找到伐木工和毁林工？",a="伐木工和毁林工遍布狂风峭壁。这片工业盆地位于石爪山脉主路旁，就在加克希姆所在位置的正东面。",al={"伐木工在哪里","哪里有毁林工","狂风峭壁位置"}},{q="加克希姆有时间思考后，打算做什么？",a="地精工人被击退后，加克希姆打算补充高能炸药。他准备在山间定点爆破，驱赶并吓退荆棘谷地精，让他们远离林地。",al={"加克希姆的计划","侏儒学者后续","炸药计划"}},{q="奥术、炼金术和工程学启蒙协会是什么？",a="奥术、炼金术和工程学启蒙协会是一个侏儒学术团体。它研究如何运用奥术法术、化学混合物与机械工程，解决艾泽拉斯各地的实际问题。",al={"侏儒学会","奥术学学会","开明议会是什么"}}},fx={["8136de5d"]={q="加克希姆·尘链为什么想削减荆棘谷地精的人手？",a="加克希姆·尘链认为，身为奥术学、炼金术与工程科学启蒙议会的一员，他有责任证明侏儒的聪明才智能够守护暗夜精灵的圣林。荆棘谷地精持续快速地砍伐森林，让他忙得不可开交，根本抽不出空来设计、组织和组装扭转局势所需的巧妙装置与炸药。",al={"为何杀死伐木工","加克希姆的动机","为何削减荆棘谷地精的人手"}},["7aed6e2a"]={q="加克希姆·尘链为什么需要你去对付地精？",a="加克希姆是发明家和研究员，可不是一支军队；而且他在石爪山脉也得不到联盟大军的有力支援。他既要确保营地安全，又要设法绘制新的机械设计图，实在无法独自击退源源不断涌来的荆棘谷地精伐木工。他只能依靠你这样的能干冒险者削减敌人的人数，好腾出精力研制对策。",al={"加克希姆为何需要我","加克希姆为何需要帮助","为何派冒险者去"}}},fp="17,192,19.373.0,29.245.0,24.232.0,51.221.0,46.193.0,47.163.0,54.192.0,81.228.0"}
P.entries["quest:1072"] = {n="老同事",s="在石爪山脉，加克希姆·尘链正寻求一件威力强大的装置，以及为它提供燃料的方法。这位侏儒工程师派你渡海前往铁炉堡，他的老相识洛玛克·链带能在那里制造一种名为硝酸甘油炸药的危险爆炸化合物。",h="在石爪山脉，加克希姆·尘链正寻求一件威力强大的装置，以及为它提供燃料的方法。这位侏儒工程师派你渡海前往铁炉堡，他的老相识洛玛克·链带能在那里制造一种名为硝酸甘油炸药的危险爆炸化合物。",kw={"炸药","加克希姆·尘链","铁炉堡","洛玛克·链带","ng-5","硝酸甘油炸药","石爪山脉","侏儒区"},ang={["faction:Alliance"]="作为联盟冒险者，你横跨一片大陆，从卡利姆多饱受战火摧残的峭壁前往安全的铁炉堡。",["profession:Engineering"]="作为工程师，尽管运输和调配危险重重，你仍能理解加克希姆和洛玛克对极致火力的追求。",["race:Gnome"]="作为侏儒，你深知学术人脉、古怪的竞争关系，以及可能变得极不稳定的爆炸化合物，都有着深远的影响。"},sec={{t="易爆的配方",b="在石爪山脉，加克希姆·尘链正筹划他迄今为止最雄心勃勃的工程。如此规模的机械，需要比普通火药或原油更强劲的燃料。他需要硝酸甘油炸药，也称NG-5，这种爆炸混合物威力十足，只要一切按计划进行，就能确保摧毁目标。"},{t="侏儒区的人脉",b="加克希姆认识的人中，只有一人能提炼NG-5：他的老相识洛玛克·链带。洛玛克住在遥远的东方，在铁炉堡深处的侏儒区侏儒区。你作为加克希姆的信使长途跋涉而来，洛玛克却一见面就满怀戒心，疑神疑鬼地盘问你。"}},faq={{q="谁发布老同事任务？",a="石爪山脉的侏儒工程师加克希姆·尘链会派你前往铁炉堡。",al={"任务发布者","谁发布老同事","加克希姆任务"}},{q="在哪里能找到洛玛克·链带？",a="洛玛克·链带住在侏儒区，也就是铁炉堡东部的侏儒区。",al={"洛玛克在哪里","洛玛克·链带位置","铁炉堡洛玛克"}},{q="硝酸甘油炸药是什么？",a="硝酸甘油炸药，也称NG-5，是一种极不稳定的化学炸药，洛玛克·链带能够制造它，而加克希姆·尘链想用它来驱动自己的强力装置。",al={"ng-5是什么","硝酸甘油炸药","ng 5"}},{q="加克希姆为什么派我大老远赶到铁炉堡？",a="加克希姆说，他的实验装置需要特殊的NG-5化合物作为燃料，而洛玛克·链带是唯一能制造它的人。",al={"为什么前往铁炉堡","为什么找洛玛克","为什么去侏儒区"}},{q="找到洛玛克·链带之后会发生什么？",a="你确认加克希姆的请求后，多疑的洛玛克会交给你失职 + 化学药剂 = 乐趣任务，要求你收集危险的试剂来调配这批混合物。",al={"下一个任务","老同事之后的任务","后续任务"}},{q="哪个阵营可以承接这项任务？",a="只有联盟冒险者可以承接这项工作。任务从石爪山脉的联盟侏儒加克希姆处开始，引领你前往联盟主城铁炉堡。",al={"是否仅限联盟","部落版本","部落能否完成"}}},fp="16,218,17.312.0,22.269.0,37.87.0,33.77.0,28.151.0,48.125.0,43.145.0,38.150.0"}
P.entries["quest:1073"] = {n="失职+药剂=快乐",s="联盟冒险者远渡重洋来到铁炉堡，寻找能用爆炸对付石爪山脉荆棘谷地精的办法。只要你带来所需的炼金试剂，洛玛克·链带就同意调制硝酸甘油炸药。",h="联盟冒险者远渡重洋来到铁炉堡，寻找能用爆炸对付石爪山脉荆棘谷地精的办法。只要你带来所需的炼金试剂，洛玛克·链带就同意调制硝酸甘油炸药。",kw={"初级坚韧药剂","加克希姆·尘链","铁炉堡","洛玛克·链带","法力药水","硝酸甘油炸药","石爪山脉","荆棘谷地精"},ang={["faction:Alliance"]="从石爪山脉到铁炉堡的漫长旅程，显出了支援联盟偏远哨站的艰难，这些哨站散布在危机四伏的卡利姆多各处。",["profession:Engineering"]="当普通火药奈何不了荆棘谷地精的钢铁时，炼金术与工程学结合便能带来更大的破坏。",["race:Gnome"]="洛玛克展现了侏儒才智中毫无约束、疯狂荒诞的一面，将化学反应的威力和理论置于安全与外交上的谨慎之上。"},sec={{t="不稳定的对策",b="加克希姆·尘链需要威力强大的炸药，为他用来对付荆棘谷地精的最先进装置提供支持。他驻扎在石爪山脉高处崎岖的山口，远离身在铁炉堡、性情古怪的昔日同僚洛玛克·链带。洛玛克研制出了硝酸甘油炸药，这种化合物极不稳定，破坏力惊人，光是想到有人会使用它，他就觉得滑稽，至于谁会被炸得粉身碎骨，他根本不在乎。"},{t="用药剂换爆炸",b="洛玛克迫不及待地想看到地精的机器被炸成碎片，也许还包括你，但他在铁炉堡的工坊已经用完了硝酸甘油炸药。在调制下一批之前，他要你带来初级法力药水和初级坚韧药剂。这些药剂为他的混合物提供基础试剂，而收集它们也能让洛玛克判断，你对炼金术是否还存有一丝敬意。"}},faq={{q="洛玛克·链带是谁？",a="洛玛克·链带是矮人首都铁炉堡里一位性情古怪的侏儒炼金师兼工匠。他是加克希姆·尘链的昔日同僚，研制出了极不稳定的炸药硝酸甘油炸药。",al={"洛玛克·链带","洛玛克是谁","铁炉堡侏儒"}},{q="洛玛克为什么要药剂，而不是常规的工程零件？",a="洛玛克将炼金术与机械知识结合，制造不稳定的反应。初级法力药水提供魔法能量，初级坚韧药剂则提供具有稳定作用的体液；两者都是他调制硝酸甘油炸药的基础试剂。",al={"为什么要药剂","炼金材料","为什么要法力药水"}},{q="为什么要派冒险者千里迢迢前往铁炉堡？",a="加克希姆·尘链孤身驻扎在石爪山脉的荒野，无法使用重型工业或化学工坊。铁炉堡的洛玛克·链带是加克希姆唯一信任，或者说足够畏惧的同僚，相信他手中有威力足以驱动自己最先进装置的炸药。",al={"为什么去铁炉堡","为什么要走这么远","加克希姆到铁炉堡"}},{q="硝酸甘油炸药是什么？",a="硝酸甘油炸药是洛玛克·链带调制的一种爆炸性化学混合物，以极不稳定著称，洛玛克称它为自己最伟大的创造。",al={"硝酸甘油炸药","炸药是什么","侏儒炸弹药液"}},{q="洛玛克在意荆棘谷地精或森林吗？",a="洛玛克既不在意荆棘谷地精，也不在意森林。他嘲笑用炸药拯救树木的想法，只想看地精或送货的人被炸得粉身碎骨。",al={"洛玛克在意自然吗","洛玛克的动机"}},{q="完成这项任务需要是炼金师吗？",a="不需要。洛玛克嘴上说要考验你的炼金技术，但只要拿到配方所需的药剂，他也接受通过交易、商人或其他工匠获得的试剂。",al={"需要炼金术吗","炼金术要求"}}},fp="28,241,19.370.0,24.369.0,23.190.0,66.247.0,57.250.0,28.129.0,57.181.0,53.182.0"}
P.entries["quest:1074"] = {n="失职+药剂=快乐",s="洛玛克·链带将易爆的NG-5送往石爪山脉，交给加克希姆·尘链。加克希姆需要用这种化学制剂引燃几辆装满炸药的货车，为联盟在这片争夺不休的山地中的行动制造佯攻。",h="洛玛克·链带将易爆的NG-5送往石爪山脉，交给加克希姆·尘链。加克希姆需要用这种化学制剂引燃几辆装满炸药的货车，为联盟在这片争夺不休的山地中的行动制造佯攻。",kw={"炸药","工程学","加克希姆·尘链","侏儒","洛玛克·链带","ng-5","硝酸甘油炸药","石爪山脉"},ang={["faction:Alliance"]="石爪山脉是争夺中的地区，一场大爆炸能为联盟人员争取行动空间，让他们推进自己的目标。",["profession:Engineering"]="处理NG-5时，必须谨慎对待这种易爆的化学制剂，以免它提前引爆。",["race:Gnome"]="侏儒的雄心让硝酸甘油炸药派上了用场，用它引燃一车车炸药，转移敌人的注意力。"},sec={{t="易爆的货物",b="洛玛克·链带交出了硝酸甘油炸药，也称NG-5，这是侏儒工程学制造的一种不稳定化合物。他警告你，务必小心处理。如果处置不当，这种化学制剂可能会在返回加克希姆·尘链身边的路上把你炸得粉身碎骨。"},{t="制造混乱的配方",b="加克希姆·尘链收到完好无损的罐子后，便解释了自己的打算。NG-5能引燃整车的炸药。加克希姆计划在石爪山脉制造一场大爆炸，引发混乱并引开敌人，让联盟得以在当地推进自己的目标。"}},faq={{q="NG-5是什么？",a="NG-5是硝酸甘油炸药的简称，是洛玛克·链带制造的一种极易爆炸的化合物。引燃重型炸药需要用到它。",al={"硝酸甘油炸药是什么","ng-5","洛玛克给了什么"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是石爪山脉的一名侏儒法师。他指挥联盟的爆破行动，利用爆炸转移当地威胁势力的注意力。",al={"加克希姆","加克希姆·尘链是谁"}},{q="洛玛克·链带是谁？",a="洛玛克·链带是一名工程师，也是加克希姆·尘链的同伴。他配制危险的NG-5化合物，再将其交给信使运送。",al={"洛玛克","洛玛克·链带是谁"}},{q="加克希姆为什么需要如此强大的爆炸威力？",a="加克希姆已经备好了几辆装满炸药的货车。NG-5能一次引爆它们，制造声势浩大的佯攻。",al={"为什么要用装满炸药的货车","加克希姆的计划","为什么要制造爆炸"}},{q="运输这种化学制剂有危险吗？",a="有。洛玛克警告说，NG-5很不稳定，处置不当就可能爆炸。在前往加克希姆那里的路上，务必小心。",al={"ng5会爆炸吗","ng-5安全吗"}},{q="这次运送的目的地在哪里？",a="运送的终点是加克希姆·尘链在石爪山脉山口中的哨站。",al={"加克希姆在哪里","石爪山脉的位置"}}},fp="28,223,19.225.0,24.266.1,13.134.0,24.150.0,23.131.0,44.124.0,39.113.0,36.87.0"}
P.entries["quest:1075"] = {n="马伦的卷轴",s="加克希姆·尘链想向暴风城法师区的科林·马伦求取一道法术。他需要奥术的帮助，从远处引爆他的NG-5炸药。",h="加克希姆·尘链想向暴风城法师区的科林·马伦求取一道法术。他需要奥术的帮助，从远处引爆他的NG-5炸药。",kw={"科林·马伦","西部荒野中的恶魔","炸药","加克希姆·尘链","法师区","ng-5","遥控引爆器","暴风城"},ang={["class:Mage"]="身为法师，你知道肯瑞托和暴风城的奥术施法者会与工程师合作。他们运用塑能和变化法术来解决机械问题。",["faction:Alliance"]="身为联盟的一员，你能看到侏儒工匠与在暴风城法师区研习的人类巫师合作。",["profession:Engineering"]="身为工程师，你知道不稳定的黑火药和奥术催化剂可以解决远距离点火之类的问题。",["race:Gnome"]="身为侏儒，只要能在舒适的距离之外制造更具毁灭性的爆炸，你就从不介意将技术与魔法结合起来。"},sec={{t="远距离的火花",b="机械引信无法满足加克希姆对控制的需求。他希望自己待在爆炸范围之外，只按一个按钮就能引爆炸药。奥术魔法或许能将他手中的指令传递给炸药。"},{t="法师区的联系",b="科林·马伦是一位人类施法者，掌握着实用的奥术知识。他思考着如何让远处传来的指令引燃炸药。随后，他开始编写加克希姆开展这项危险计划所需的咒语。"}},faq={{q="谁派我去找科林·马伦？",a="加克希姆·尘链派你去找科林·马伦。他需要从这位人类熟人那里取得一个奥术公式，才能完成遥控引爆器。",al={"任务给予者","谁给予马伦的卷轴任务","加克希姆任务"}},{q="在哪里能找到科林·马伦？",a="科林·马伦就在暴风城的法师区。在这个城区的高塔和商店周围，留意那些导师、学徒和奥术研究者，就能找到他。",al={"科林·马伦位置","科林·马伦在哪里","寻找马伦"}},{q="为什么加克希姆的爆炸装置需要法术？",a="加克希姆想在安全距离之外，只按一个按钮就能引爆他的NG-5炸药。他想借助马伦的奥术知识，实现瞬时遥控引爆，因为机械手段在远距离使用时可能十分笨重，或不够可靠。",al={"炸弹为什么需要魔法","遥控引爆背景故事","为什么要找法师"}},{q="NG-5是什么？",a="NG-5，也称硝酸甘油炸药，是加克希姆的老同事洛玛克·链带在铁炉堡调制的一种不稳定的炸药。加克希姆需要一套遥控引爆系统，让引爆者能够待在远超爆炸半径的地方。",al={"ng-5","ng5是什么","加克希姆炸药"}},{q="与科林·马伦交谈后，接下来要做什么？",a="科林·马伦考虑了远距离引爆法术的请求后，会在西部荒野中的恶魔任务中请你前往西部荒野帮他。",al={"下一个任务","马伦的卷轴之后的任务","科林·马伦后续任务"}},{q="科林·马伦是侏儒还是人类？",a="科林·马伦是一位人类法师。加克希姆说，马伦是个人类，应该很容易在暴风城的人群中认出来。",al={"科林·马伦种族","马伦是什么种族","马伦是人类吗"}}},fp="20,141,24.202.0,27.215.0,30.129.0,33.162.0,52.219.0,17.222.0,50.132.0,36.114.0"}
P.entries["quest:1076"] = {n="西部荒野中的恶魔",s="尘魔游荡在西部荒野，科林·马伦需要它们的残骸来施法。这位来自法师区的法师正在协助加克希姆·尘链进行一项不寻常的实验。他们的研究需要一张传讯卷轴，而尘土中蕴含着马伦为卷轴附魔所需的东西。",h="尘魔游荡在西部荒野，科林·马伦需要它们的残骸来施法。这位来自法师区的法师正在协助加克希姆·尘链进行一项不寻常的实验。他们的研究需要一张传讯卷轴，而尘土中蕴含着马伦为卷轴附魔所需的东西。",kw={"科林·马伦","尘魔","尘魔的残骸","加克希姆·尘链","法师区","传讯法术","卷轴","暴风城","西部荒野"},ang={["class:Mage"]="身为法师，你能看出附魔如何驾驭狂野的元素共鸣，将复杂的传讯法术束缚在卷轴之中。",["faction:Alliance"]="身为联盟的旅人，你从暴风城的高塔间走向西部荒野疏于照管的农田，王国的边陲已是一片破败。",["profession:Engineering"]="身为工程师，你能看出加克希姆·尘链如何借助奥术卷轴制作技艺，解决传讯难题。"},sec={{t="传讯所需的材料",b="科林·马伦正在为加克希姆·尘链准备一张传讯卷轴。这位法师正在协助那位工匠开展一项不寻常的研究，但这个法术需要的不只是墨水和羊皮纸。尘魔游荡在西部荒野，元素魔法在它们体内涌动。它们的残骸能提供一种不稳定的媒介，供马伦将加克希姆的法术束缚在羊皮纸上。"},{t="元素荒原",b="西部荒野曾是暴风城富饶的粮仓。干旱、匪患和疏于照管让这里的农田变得干枯荒芜。尘魔在此游荡，威胁着旅人和独居的农户。它们留下的残骸蕴含着凝聚的元素精华，正是马伦完成附魔所需的材料。"}},faq={{q="科林·马伦是谁？",a="科林·马伦是暴风城法师区的一位人类法师。他与城中的施法者合作，有时也会帮助加克希姆·尘链这样的外来研究者制作附魔卷轴和奥术材料。",al={"科林·马伦","任务给予者是谁","暴风城的法师"}},{q="科林·马伦为什么需要尘魔的残骸？",a="科林·马伦需要尘魔的残骸，为给加克希姆·尘链准备的传讯卷轴附魔。这些残骸蕴含着元素能量，有助于将法术束缚在羊皮纸上。",al={"为什么需要尘魔的残骸","尘魔的残骸有什么用","为什么去西部荒野"}},{q="哪里能找到尘魔？",a="尘魔游荡在西部荒野干燥的平原和贫瘠的农田中，尤其常见于通往哨兵岭的道路以南，那些疏于照管的农庄之间尘土飞扬的地带。",al={"尘魔位置","尘魔在哪里","西部荒野尘魔"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位雄心勃勃的侏儒发明家，正在研究深奥的工程学项目。科林·马伦帮助他为实验准备附魔卷轴。",al={"加克希姆","加克希姆·尘链","加克希姆是谁"}},{q="把残骸交给马伦后会发生什么？",a="有了这些残骸，科林·马伦便能完成传讯卷轴，并请你将它送给加克希姆·尘链，让这位发明家继续他的实验。",al={"任务奖励","接下来做什么","西部荒野中的恶魔之后"}},{q="尘魔是魔法生物还是自然生物？",a="尘魔是低等空气元素，形如由沙砾构成的活体旋风。它们在西部荒野干燥而动荡的土地上繁衍。",al={"尘魔是元素生物吗","尘魔背景故事"}}},fx={b0d4cd5a={q="尘魔的残骸有什么用？",a="科林·马伦需要尘魔的残骸，作为给一张特殊卷轴附魔的关键试剂。加克希姆·尘链的古怪实验需要一道传讯法术，而从这种旋风生物身上收集的元素材料，能让马伦将魔法附着在羊皮纸上。",al={"尘魔的残骸的用途","残骸有什么用","为什么需要尘魔的残骸"}},["9b2ec5a3"]={q="你要猎杀的尘魔是什么？",a="尘魔是混乱的风元素，在西部荒野贫瘠的平原和农田间游荡。当地动荡的狂风与狂野魔法将它们搅动起来，这些微型旋风会袭击任何挡住去路的旅者，对当地农夫和流浪者都构成致命威胁。",al={"尘魔是什么","尘魔猎杀目标","尘魔是哪些生物"}}},fp="18,250,24.333.0,20.278.0,21.211.0,46.163.0,28.150.0,24.160.0,49.152.0,45.139.0"}
P.entries["quest:1077"] = {n="给加克希姆的特快专递",s="在石爪山，加克希姆·尘链正等待一份来自暴风城的卷轴。科林·马伦提供了通讯卷轴，其中的奥术力量是制造遥控炸弹的关键，用来阻止荆棘谷地精砍伐森林。",h="在石爪山，加克希姆·尘链正等待一份来自暴风城的卷轴。科林·马伦提供了通讯卷轴，其中的奥术力量是制造遥控炸弹的关键，用来阻止荆棘谷地精砍伐森林。",kw={"科林·马伦","加克希姆·尘链","ng-5","遥控炸弹","通讯卷轴","石爪山","风险投资公司"},ang={["class:Mage"]="科林·马伦的技艺展现了巧思过人的工匠如何将羊皮纸上的简单附魔变成可用的奥术中继装置。",["faction:Alliance"]="身为联盟的一员，你能看到暴风城与卡利姆多偏远前哨之间的联系，那些前哨正在抵抗工业掠夺。",["profession:Engineering"]="加克希姆的计划将侏儒工程学与法术结合，让不稳定的NG-5炸药配上奥术引爆装置。"},sec={{t="奥术递送",b="加克希姆·尘链试图阻挠荆棘谷地精在石爪山脉的破坏活动。他制成了一种名为NG-5的爆炸混合物，却缺少可靠的远程引爆手段。加克希姆没有采用粗陋的引线，而是向无尽之海彼岸寻求帮助。他联系了暴风城法师区的科林·马伦，希望获得一份附魔的通讯卷轴。"},{t="远程佯攻",b="加克希姆·尘链计划将通讯卷轴的魔力与不稳定的NG-5混合物结合。卷轴远距离传递信息的力量可以从远处引爆炸药。加克希姆打算用一场猛烈的爆炸吸引注意，让行动人员有机会悄悄潜入荆棘谷地精的营地。"}},faq={{q="通讯卷轴有什么用途？",a="通讯卷轴能将话语传到远方，而加克希姆·尘链可以将它的魔力与NG-5结合，用作远程引爆装置。这样，他就能在安全距离外引爆炸药。",al={"为什么需要通讯卷轴","卷轴有什么作用","通讯卷轴用途"}},{q="科林·马伦是谁？",a="科林·马伦是暴风城法师区的一名联盟法师。他协助处理奥术事务，并制作加克希姆在石爪山所需的附魔卷轴。",al={"科林·马伦的故事","科林是谁"}},{q="加克希姆·尘链为什么要破坏荆棘谷地精的行动？",a="荆棘谷地精正在肆无忌惮地砍光石爪山脉的原始森林。加克希姆打算制造混乱、摧毁他们的作业设施，并窃取他们的工程图纸和往来信件，以减缓森林遭到砍伐的速度。",al={"为什么攻击风险投资公司","加克希姆的动机","风险投资公司与石爪山"}},{q="这趟递送会带冒险者前往何处？",a="这趟递送会让你从暴风城出发，跨越大海，前往卡利姆多石爪山脉峭壁间的联盟营地。",al={"递送目的地","加克希姆在哪里","石爪山的位置"}},{q="卷轴送达后会发生什么？",a="有了卷轴和NG-5，加克希姆便着手准备一场遥控爆炸来吸引注意。这为一名行动人员扫清了道路，使其得以进入狂风峭壁的作业区，取回伐木信件和结构图。",al={"后续任务","递送之后做什么","吸引风险投资公司的注意"}}},fp="26,177,17.330.0,20.321.1,41.181.0,21.154.0,55.232.0,45.120.0,43.197.1"}
P.entries["quest:1078"] = {n="完鳞归玛伦",s="在暴风城，科林·马伦请前往卡利姆多的旅人替他带回稀有的蜥蜴鳞片。他需要石爪山的焦炭谷中的鳞片，将其磨成粉末，用于施法。",h="在暴风城，科林·马伦请前往卡利姆多的旅人替他带回稀有的蜥蜴鳞片。他需要石爪山的焦炭谷中的鳞片，将其磨成粉末，用于施法。",kw={"蜥蜴鳞片","焦炭谷","科林·马伦","结晶鳞片","法师区","为马伦取回物品","石爪山脉","暴风城"},ang={["class:Mage"]="身为法师，你知道为其他法师收集稀有施法材料有助于奥术研究。奇异的魔法野生生物可以提供研制新咒语所需的材料。",["faction:Alliance"]="身为联盟旅人，你看到了暴风城的利益与补给线如何深入卡利姆多的荒野。"},sec={{t="法师的奇异施法材料",b="科林·马伦是暴风城法师区的一位法师，他常听四处游历的冒险者讲述见闻。他听说旅人们正深入卡利姆多，而石爪山吸引着那些寻找野生双足飞龙、狂暴元素生物，或与荆棘谷地精交易、交战的人。马伦并不追求财富或荣耀。他想了解，在这片地区最恶劣的角落里，还有哪些罕见的自然奇观留存。"},{t="谷中的晶莹野兽",b="焦炭谷位于石爪山深处，是一片灰烬弥漫的盆地，荆棘谷地精的破坏在此留下了累累伤痕。马伦的研究表明，这里曾栖息着一种奇特的蜥蜴。它们的鳞片磨成细粉后，能够催化他研制的特殊奥术法术。他不知道这些蜥蜴是否熬过了谷中剧烈的环境变化，因此请探险者带回新鲜的结晶鳞片，查明这个种群是否仍然存续。"}},faq={{q="科林·马伦是谁？",a="科林·马伦是暴风城法师区的一位法师，研究奥术法术，并寻找来自遥远之地的稀有施法材料。",al={"科林·马伦","谁发布马伦的材料","马伦 暴风城"}},{q="科林·马伦为什么需要蜥蜴鳞片？",a="马伦将蜥蜴的结晶鳞片磨成细粉，用作他所研制法术的催化剂。",al={"为什么需要鳞片","鳞片有什么用","结晶鳞片用途"}},{q="焦炭谷在哪里？",a="焦炭谷是卡利姆多石爪山脉西南部一片满目疮痍的盆地。",al={"焦炭谷在哪里","寻找焦炭谷","焦炭谷位置"}},{q="焦炭谷为什么会被烧焦？",a="荆棘谷地精的地精摧毁了焦炭谷。他们的破坏激怒了谷中的精魂，释放了元素生物，使大地焦黑，余烬未熄，顽强而扭曲的野兽在此游荡。",al={"焦炭谷发生了什么","焦炭谷大火","焦炭谷的毁坏"}},{q="哪些生物会掉落这项任务所需的鳞片？",a="石爪山脉焦炭谷中的蜥蜴身上有马伦寻找的鳞片。",al={"哪些蜥蜴","谁掉落结晶鳞片","掉落鳞片的怪物"}},{q="为什么要为此派冒险者远渡重洋？",a="马伦需要焦炭谷原生蜥蜴鳞片所具有的结晶特性。横渡无尽之海危机重重，因此他请那些本就要前往卡利姆多的老练旅人帮忙。",al={"为什么去卡利姆多","为什么去石爪山找鳞片"}}},fp="20,180,25.395.0,29.447.0,21.127.0,44.92.0,34.85.0,32.207.0,52.83.0,59.174.0"}
P.entries["quest:1079"] = {n="隐秘行动：A",s="联盟特工在石爪山脉听命于加克希姆·尘链。他们从山峰出发，潜入狂风峭壁的荆棘谷地精伐木场，取回工程图纸。",h="联盟特工在石爪山脉听命于加克希姆·尘链。他们从山峰出发，潜入狂风峭壁的荆棘谷地精伐木场，取回工程图纸。",kw={"阿尔法","隐秘行动","峭壁湖","工程设计图","加克希姆·尘链","伐木场","石爪山","风险投资公司","狂风峭壁"},ang={["faction:Alliance"]="作为联盟的一员，你协助巩固据点，遏制遍及卡利姆多的工业资源开采，在战术上与不断挺进争夺中荒野的敌对势力保持均势。",["profession:Engineering"]="图纸揭示了荆棘谷地精所用的粗犷、依靠强劲燃烧驱动的机械构造，让人得以了解工业动力机械的运作原理。",["race:Gnome"]="作为一名侏儒技师，你可以研究地精的设计图，找出设计中的缺陷，学到他们那些能带来丰厚利润的机械诀窍。",["race:NightElf"]="作为一名暗夜精灵，你目睹荆棘谷地精在狂风峭壁的伐木活动伤害着石爪山的古老森林。破坏其伐木设施刻不容缓。"},sec={{t="破坏与谍报",b="加克希姆·尘链在狂风峭壁指挥秘密行动，对抗荆棘谷地精的大肆伐木。地精伐木工在峭壁湖南面砍伐树木，但仅靠破坏无法阻止他们。阿尔法计划 派遣特工绕过伐木工和监工，夺取伐木场的技术图纸。"},{t="逆向工程",b="侏儒对荆棘谷地精图纸的兴趣，并不只关乎暗夜精灵的森林。这些图纸展示了地精伐木机、机械切割器和机械运输工具的运作原理。联盟工程师可以利用它们找出结构缺陷，瓦解今后的作业，同时改进地精的设计，用于他们在铁炉堡的项目。"}},faq={{q="隐秘行动 - 一号的主要目标是什么？",a="从峭壁湖南面、狂风峭壁的荆棘谷地精伐木场取回工程设计图。炸药是整个秘密行动的一部分，但成败取决于能否带回蓝图。",al={"隐秘行动阿尔法是什么","一号计划 任务目标","加克希姆 想要什么"}},{q="谁给予隐秘行动 - 一号任务？",a="加克希姆·尘链是石爪山脉的一名联盟侏儒技师，负责指挥针对地精工业的破坏行动。",al={"谁开启隐秘行动阿尔法","加克希姆·尘链任务","隐秘行动 任务给予者"}},{q="工程设计图在哪里？",a="荆棘谷地精工程图纸位于峭壁湖南面、狂风峭壁仍在运作的伐木场内，由地精伐木工看守。",al={"风险投资公司 设计图在哪里","工程设计图位置","狂风峭壁伐木场设计图"}},{q="加克希姆·尘链为什么想要风险投资公司. 的蓝图？",a="加克希姆想研究地精伐木机械的结构弱点。这些缺陷能帮助他们更有效地破坏今后的机械，而其中实用的设计则能改进联盟的装置。",al={"为什么窃取 风险投资公司 设计图","加克希姆 会用设计图做什么","隐秘行动阿尔法的原因"}},{q="任务的目的只是大肆破坏吗？",a="不是。加克希姆说，成败取决于能否完整地取回图纸，而非特工造成了多少破坏。",al={"是否要炸毁伐木场","是否应该摧毁机器","任务是否侧重破坏"}},{q="联盟为什么在这里对抗荆棘谷地精？",a="荆棘谷地精在石爪山砍伐森林，污染土地。联盟特工致力于扰乱其工业活动，保护卡利姆多的战略领地。",al={"为什么在 石爪山 对抗荆棘谷地精","联盟与 风险投资公司 的冲突","石爪山 伐木战争"}}},fp="18,185,22.296.0,19.326.0,47.212.0,39.113.0,40.146.0,58.196.0,46.113.0,54.151.0"}
P.entries["quest:1080"] = {n="隐秘行动：B",s="在石爪山脉，加克希姆·尘链派遣一名特工潜入荆棘谷地精的矿洞。炸药将引开地精，让特工趁机取走函件，揭露这家公司的计划，帮助保卫哨兵的领地。",h="在石爪山脉，加克希姆·尘链派遣一名特工潜入荆棘谷地精的矿洞。炸药将引开地精，让特工趁机取走函件，揭露这家公司的计划，帮助保卫哨兵的领地。",kw={"隐秘行动 - 贝塔","加克希姆·尘链","哨兵","石爪山脉","风险投资公司.","风险投资公司函件","狂风峭壁","狂风矿洞"},ang={["faction:Alliance"]="作为联盟的一员，你可以看到侏儒装置如何帮助暗夜精灵保卫他们在卡利姆多中部的领地。",["profession:Engineering"]="作为一名工程师，你可以看到加克希姆的隐秘行动工具包如何巧妙地利用爆炸转移注意力，在守卫森严的区域中开辟通路。",["race:Gnome"]="作为一名侏儒，你可以从加克希姆·尘链的爆炸装置和隐秘行动中，看到工程技艺和周密计划如何用于军事行动。",["race:NightElf"]="作为一名暗夜精灵，你知道荆棘谷地精正在砍伐古老的森林。加克希姆的行动为哨兵指挥官提供情报，帮助他们保卫这片山地。"},sec={{t="深入矿洞的破坏行动",b="在初步打击荆棘谷地精在狂风峭壁的伐木活动后，加克希姆·尘链将目标转向了这家公司的补给核心。计划沿用先前的方式：用爆炸制造混乱，驱散地精工人和雇佣兵，让一名特工趁机在矿洞中搜寻书面命令和记录。"},{t="紧盯狂风矿洞",b="狂风矿洞位于狂风峭壁的东部边缘，是荆棘谷地精设在山腹中的基地。这里的地精开采岩石、砍伐木材，并记录补给路线和首领的命令。一名特工潜入其中，布置加克希姆的炸药包，取走风险投资公司函件。爆炸扰乱了矿洞的守卫，而函件则进一步揭露了这家公司在卡利姆多的计划。"},{t="务实的合作",b="加克希姆热衷于精巧的装置和爆炸，但这些行动对暗夜精灵也意义重大。在石爪山，哨兵既要面对部落，也要应对那些在其领地上砍伐和挖掘的公司。矿洞中的函件为凯拉·影矛这样的指挥官提供了情报，帮助他们预判圣林面临的威胁。"}},faq={{q="隐秘行动 - 二号的目标是什么？",a="一名特工进入狂风峭壁东端的狂风矿洞，布置加克希姆·尘链的炸药包来转移注意力，并取走记载公司行动的风险投资公司函件。",al={"隐秘行动 二号计划目标","隐秘行动 二号计划要做什么","二号计划目标"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是石爪山脉的一名侏儒工程师。他运用工程技术和炸药，协助暗夜精灵哨兵对抗荆棘谷地精的伐木和采矿活动。",al={"加克希姆·尘链","谁发布隐秘行动二号计划"}},{q="狂风矿洞在哪里？",a="狂风矿洞位于狂风峭壁的东端，坐落在荆棘谷地精砍伐过的林地中。",al={"狂风矿洞位置","矿洞在哪里"}},{q="加克希姆为什么想要风险投资公司函件？",a="风险投资公司函件详细记载了补给路线、首领的命令以及在这一地区的计划。这些函件帮助联盟和哨兵预判这家公司的行动，并阻碍它在森林中的作业。",al={"为什么窃取函件","风险投资公司函件是什么"}},{q="这项任务对暗夜精灵有什么帮助？",a="哨兵兵力不足，无法监视整个石爪山。加克希姆制造的爆炸拖延了伐木进度，而函件则为凯拉·影矛这样的指挥官提供了有关敌人的实用情报。",al={"暗夜精灵为何关心","哨兵隐秘行动"}},{q="一号计划是什么？",a="一号计划是加克希姆先前在峭壁湖南面的荆棘谷地精伐木场开展的行动。一名特工用爆炸转移注意力，窃取了这家公司的工程图纸，而二号计划则在狂风矿洞采用了同样的手段。",al={"一号计划","隐秘行动阿尔法","前一个任务"}}},fp="17,202,22.255.0,22.409.0,23.318.0,38.193.0,24.183.0,32.102.0,44.201.0,46.193.0,20.234.0"}
P.entries["quest:1081"] = {n="泰兰德的接待",s="哨兵塞恩希尔派你从阿斯特兰纳前往达纳苏斯，觐见泰兰德·语风。在你帮助哨兵抵御石爪山的荆棘谷地精、守住阵地后，泰兰德在月神殿接见了你。",h="哨兵塞恩希尔派你从阿斯特兰纳前往达纳苏斯，觐见泰兰德·语风。在你帮助哨兵抵御石爪山的荆棘谷地精、守住阵地后，泰兰德在月神殿接见了你。",kw={"达纳苏斯","卡多雷","泰兰德的接见","哨兵塞恩希尔","石爪山脉","泰达希尔","月神殿","泰兰德·语风"},ang={["faction:Alliance"]="觐见泰兰德·语风将卡利姆多的暗夜精灵与联盟其他成员联系起来，让在荒野中的付出在达纳苏斯获得认可。",["race:NightElf"]="身为暗夜精灵，在月神殿向高阶女祭司泰兰德·语风复命，既是归乡，也表明了你守护祖地的决心。"},sec={{t="石爪山的据点",b="荆棘谷地精向石爪山脉各处的暗夜精灵哨站施压。哨兵塞恩希尔在阿斯特兰纳协调防御，但那些偏远基地难以维持。补给线和情报帮助哨兵维持联盟在卡利姆多腹地的势力，而你的援助巩固了他们的阵地。"},{t="觐见高阶女祭司",b="你帮助哨兵巩固了石爪山的阵地后，哨兵塞恩希尔派你返回泰达希尔。高阶女祭司泰兰德·语风在达纳苏斯的月神殿接见了你。她认可你在卡利姆多各地的功绩，并欢迎你成为与卡多雷并肩作战的盟友。"}},faq={{q="这个任务从哪里开始？",a="完成“向塞恩希尔报告”后，哨兵塞恩希尔会在灰谷的阿斯特兰纳交给你这项任务。",al={"哪里接泰兰德的接见","任务给予者","哨兵塞恩希尔位置"}},{q="在哪里能找到泰兰德·语风？",a="泰兰德·语风位于泰达希尔的达纳苏斯中央城区，就在月神殿内。",al={"泰兰德在哪里","寻找泰兰德","月神殿位置"}},{q="泰兰德为什么想见我？",a="你在石爪山的努力帮助卡多雷保住了这片争夺中的山地据点。哨兵塞恩希尔认为，你的付出值得得到暗夜精灵精神与军事领袖的嘉许。",al={"泰兰德为何想交谈","觐见的目的"}},{q="石爪山脉有什么战略价值？",a="石爪山是灰谷与卡利姆多南部平原之间一道崎岖的屏障。守住这里的哨站，有助于暗夜精灵监视来自贫瘠之地的部落动向，并保护神圣的土地。",al={"为何关注石爪山","石爪山背景故事"}},{q="其他联盟种族也能在这里获得认可吗？",a="可以。任何帮助哨兵塞恩希尔的联盟冒险者都能前往达纳苏斯，这也体现了暗夜精灵与联盟其他成员日益加强的共同防御。",al={"非暗夜精灵能否完成","人类能否接取"}},{q="见过泰兰德后还有后续任务吗？",a="与泰兰德会面后，你为哨兵塞恩希尔在石爪山承担的信使与支援工作便告结束。你可以在达纳苏斯寻求进一步的指示。",al={"接下来做什么","任务链的下一步"}}},fp="22,186,24.318.0,32.294.0,28.106.0,37.96.0,32.207.0,56.190.0,44.173.0,49.127.0"}
P.entries["quest:1082"] = {n="向塞恩希尔报告",s="令人安心的消息从石爪山传到了阿斯特兰纳。在帮助凯拉·影矛和加克希姆·尘链对抗荆棘谷地精后，你受命向哨兵塔拉·塞恩希尔报平安，告诉她那座前哨站依然坚守着。",h="令人安心的消息从石爪山传到了阿斯特兰纳。在帮助凯拉·影矛和加克希姆·尘链对抗荆棘谷地精后，你受命向哨兵塔拉·塞恩希尔报平安，告诉她那座前哨站依然坚守着。",kw={"灰谷","阿斯特兰纳","加克希姆·尘链","凯拉·影矛","哨兵塞恩希尔","石爪山","向哨兵塞恩希尔汇报近况","风险投资公司"},ang={["faction:Alliance"]="身为联盟的一员，你协助维持石爪山边境哨所与灰谷据点之间的联络，巩固联盟在卡利姆多中部的势力。",["race:Gnome"]="身为侏儒，你可以为此感到自豪：就连哨兵塞恩希尔也因加克希姆·尘链平安无事而松了一口气。侏儒的巧思也能赢得恪守传统的精灵的尊重。",["race:NightElf"]="身为暗夜精灵，你可以向Sentinels报平安，告诉她们凯拉幸存了下来，她们对卡利姆多边境的掌控也未在工业的压迫下瓦解。"},sec={{t="群峰来讯",b="石爪山险峻的山口让暗夜精灵的边境地带孤立无援，危机四伏。荆棘谷地精削平山岩，污染水道，威胁着凯拉·影矛与侏儒技师加克希姆·尘链驻守的前哨站。眼前的威胁暂时得到遏制后，凯拉派你向东北越过边界，前往灰谷，报告他们依然平安。"},{t="阿斯特兰纳的宽慰",b="在阿斯特兰纳，哨兵塔拉·塞恩希尔守望着灰谷腹地的道路，牵挂着那些被派往险恶之地的斥候。得知凯拉和她的工程师搭档仍然活着，并正努力修复这片土地，着实令人宽慰。这份报告表明，尽管兵力日渐减少，多条战线都面临威胁，与联盟盟友合作仍能减缓破坏。"}},faq={{q="哨兵塞恩希尔是谁？",a="塔拉·塞恩希尔是暗夜精灵哨兵的一名军官，驻守在阿斯特兰纳，这里是联盟在灰谷的主要据点。她关注着被派往周边荒野和邻近地区的斥候与巡逻队。",al={"哨兵塞恩希尔","塔拉·塞恩希尔","塞恩希尔 阿斯特兰纳"}},{q="凯拉·影矛为什么在石爪山脉？",a="凯拉·影矛奉命前往石爪山，阻止荆棘谷地精对这片土地的破坏性开采。她与侏儒加克希姆·尘链合作，破坏地精的机械，修复这片土地。",al={"凯拉·影矛","凯拉的任务","凯拉为什么在石爪山"}},{q="加克希姆是谁？",a="加克希姆·尘链是一名联盟侏儒工程师，与凯拉·影矛一同驻守石爪山。他那喧闹的行当与精灵的传统格格不入，但他的技艺有助于破坏地精的伐木机械。",al={"加克希姆","加克希姆·尘链","与凯拉一起的侏儒"}},{q="在哪里能找到哨兵塞恩希尔？",a="哨兵塞恩希尔位于阿斯特兰纳，就在灰谷中部的道路旁，石爪山脉下山小径的东北方。",al={"塞恩希尔在哪里","塞恩希尔的位置","阿斯特兰纳在哪里"}},{q="向哨兵塞恩希尔复命后会发生什么？",a="向哨兵塞恩希尔报告在石爪山取得的成果后，你将在暗夜精灵军中获得更多机会，并参与同达纳苏斯领袖之间更高层级的联络。",al={"塞恩希尔之后的任务","接下来去哪里","泰兰德的接见"}},{q="荆棘谷地精为什么会威胁石爪山？",a="荆棘谷地精将神圣的林地砍伐殆尽，运转着庞大的伐木机械，还毒害了石爪山的水道，威胁着暗夜精灵守护的自然平衡。",al={"风险投资公司石爪山","为什么对抗风险投资公司"}}},fp="28,194,25.376.0,19.342.0,25.197.0,49.203.0,13.201.0,34.124.0,55.178.0,50.180.0"}
P.entries["quest:1083"] = {n="怒灵",s="荆棘谷地精的破坏过后，火焰与岩石之灵在焦炭谷中肆虐。烈火与重型机械摧毁了这片盆地，挣脱束缚的元素生物占据了这里。联盟勇士受命平息它们的怒火，让这片受创的土地能在艾露恩的恩泽下恢复生机。",h="荆棘谷地精的破坏过后，火焰与岩石之灵在焦炭谷中肆虐。烈火与重型机械摧毁了这片盆地，挣脱束缚的元素生物占据了这里。联盟勇士受命平息它们的怒火，让这片受创的土地能在艾露恩的恩泽下恢复生机。",kw={"焦炭谷","艾露恩","怒灵","火元素","凯拉·影矛","闷烧余烬","石爪山脉","荆棘谷地精"},ang={["class:Druid"]="身为德鲁伊，你认为肆虐的火元素严重破坏了自然的平衡。唯有主动干预，生命才能重返这片土地。",["class:Shaman"]="身为萨满祭司，你知道元素生物的怒火是一种痛苦的回应，源于凡人的矿工和伐木工对大地肆无忌惮的掠夺。",["faction:Alliance"]="身为联盟的一员，你通过石爪山的暗夜精灵哨兵展开行动，遏制地精财阀引发的混乱，恢复山间通道的安全。",["race:NightElf"]="身为暗夜精灵，你认为焦炭谷的毁灭是卡利姆多神圣荒野上一道令人心痛的伤口，而这一切都源于毫无节制的工业贪欲。"},sec={{t="烈火中的悲剧",b="焦炭谷曾是石爪山一片草木繁茂的净土。荆棘谷地精贪婪地砍伐森林、掠夺资源，将这里化为灰烬。他们使用燃烧装置和重型机械，让林冠燃起熊熊大火。他们的行径毁掉了树木，也打破了地下脆弱的元素平衡。"},{t="释放的怒火",b="荆棘谷地精的作业惊动了深处古老的火焰、岩石与愤怒之灵。暴怒的元素生物转而攻击地精，将他们击退，占据了仍在闷烧的谷地。凯拉·影矛说，只要这些混乱的元素生物仍在，自然就无法开始复苏。"}},faq={{q="谁提供怒灵任务？",a="凯拉·影矛是石爪山脉的一名暗夜精灵哨兵，她将这项使命交给前来帮助这片土地的联盟冒险者。",al={"任务给予者","哪里接怒灵","谁提供怒灵"}},{q="为什么火元素会在焦炭谷肆虐？",a="荆棘谷地精用破坏性的机械将森林砍伐殆尽，并付之一炬。他们的手段扰乱了大地，释放出沉睡的火焰、岩石与愤怒之灵，这些元素之灵随即席卷了整个地区。",al={"这里为什么有元素生物","火元素出现的原因","焦炭谷火焰之灵"}},{q="荆棘谷地精在焦炭谷遭遇了什么？",a="地精点燃了森林，他们的行径释放出了远比预想中危险的元素生物。这些狂怒的生灵摧毁了他们的作业设施，只留下残破的营地和燃烧的残骸。",al={"荆棘谷地精的命运","地精是否死在焦炭谷","荆棘谷地精焦炭谷"}},{q="什么是闷烧余烬？",a="闷烧余烬是在焦炭谷消灭火元素后收集到的燃烧残余。它们被交给凯拉·影矛，作为元素生物已遭到清剿的证明。",al={"闷烧余烬背景","余烬的用途","怒灵的余烬"}},{q="焦炭谷还能恢复生机吗？",a="凯拉·影矛相信，只要敌对的元素生物还在灰烬间游荡，这片土地就无法复苏，也无法感受到艾露恩的祝福。清除它们是让土地恢复生机的第一步。",al={"焦炭谷会恢复吗","让焦炭谷恢复生机","谷地能否获救"}},{q="焦炭谷位于哪里？",a="焦炭谷位于石爪山脉西南部，那里遍布焦黑的土地、烧毁的树木，以及四处游荡的元素之灵。",al={"焦炭谷位置","如何找到焦炭谷","元素生物在哪里"}}},fp="15,247,18.321.0,14.297.0,36.136.0,58.187.0,57.200.0,27.184.0,34.166.0,34.131.0"}
P.entries["quest:1084"] = {n="受伤的古树",s="在石爪山脉，树人开始反过来侵害自己曾经守护的土地。凯拉·影矛怀疑这是地精军火造成的，请你从遭到腐化的守护者体内取回弹片，交给加克希姆·尘链检验。",h="在石爪山脉，树人开始反过来侵害自己曾经守护的土地。凯拉·影矛怀疑这是地精军火造成的，请你从遭到腐化的守护者体内取回弹片，交给加克希姆·尘链检验。",kw={"被腐蚀的弹片","腐化","加克希姆·尘链","凯拉·影矛","石爪山脉","树人","荆棘谷地精","受伤的古树"},ang={["class:Druid"]="树人体内蕴藏着自然的生命力。在面对荆棘谷地精造成的破坏时，清除那些毒害树人血肉的外来金属，是一项残酷却必要的工作。",["profession:Engineering"]="树人体内遭到腐蚀的金属，暴露了荆棘谷地精军火制造的粗制滥造，与侏儒工艺的精密形成鲜明对比。",["race:Gnome"]="加克希姆·尘链展示了机械技艺如何帮助人们发现并理解鲁莽的工程师造成的伤害。",["race:NightElf"]="对于一名立誓守护卡利姆多荒野的Kaldorei而言，看到古老的林地守护者被地精工业扭曲，实在令人愤慨。"},sec={{t="染疫的保护者",b="树人曾守护着石爪山脉的林地，性情温和却作战勇猛，与这片土地的安危息息相关。荆棘谷地精带着圆锯和炸药前来，大肆露天开采，森林随之奋起反抗。树人将入侵者逐出了山谷的部分地区，但这场胜利也付出了代价。它们没有恢复往日平静的守望。相反，它们变得狂乱而充满敌意。"},{t="侏儒的调查",b="凯拉·影矛是山中的一名联盟斥候，她认为树人患上的并非自然疾病。侏儒工程师加克希姆·尘链怀疑，荆棘谷地精仓皇撤退时使用的武器和化学药剂伤害了它们。他希望研究受伤树人体内被腐蚀的弹片，查明是否是荆棘谷地精的军火毒害了石爪山脉的古老守护者。"}},faq={{q="谁提供受伤的古树任务？",a="石爪山脉的联盟斥候凯拉·影矛会交给你这项工作。她一直关注着日益激烈的冲突，以及这片土地遭受的伤害。",al={"受伤的古树任务给予者","谁提供受伤的古树","凯拉·影矛任务"}},{q="树人为什么会遭到腐化？",a="加克希姆·尘链怀疑，地精仓皇撤退时，荆棘谷地精的弹药嵌入了树人体内。他认为这些武器正在毒害森林守护者，使它们陷入疯狂。",al={"树人为何发狂","石爪山脉树人遭到腐化","树人腐化源头"}},{q="这项任务需要取回什么物品？",a="你需要从在附近游荡的受伤树人的树皮和血肉中，取出一块被腐蚀的弹片。",al={"受伤的古树任务物品","被腐蚀的弹片任务"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一名与联盟结盟的侏儒工程师，协助凯拉·影矛开展工作。他运用自己的机械技艺，研究荆棘谷地精的武器及其对自然生灵造成的伤害。",al={"加克希姆","石爪山脉的侏儒","加克希姆·尘链的职责"}},{q="荆棘谷地精在石爪山脉从事什么活动？",a="荆棘谷地精是一个入侵石爪山脉的地精伐木采矿集团。它肆意砍伐神圣的林地，掠夺矿藏，全然不顾这片土地的平衡。",al={"荆棘谷地精石爪山脉","地精为何来到石爪山脉"}},{q="收集弹片能治愈树人吗？",a="不能。弹片是供加克希姆检验的样本，以便他查明毒素的性质和来源。它并不能立即治愈遭到腐化的守护者。",al={"树人能否治愈","树人会恢复吗"}}},fp="16,177,19.333.0,21.378.0,38.154.0,30.184.0,42.103.0,24.184.0,53.179.0,46.145.0"}
P.entries["quest:1085"] = {n="守卫石爪山",s="在狂风峭壁附近的营地里，凯拉·影矛派联盟旅者去找加克希姆·尘链，寻求对抗荆棘谷地精的帮助。谨慎的暗夜精灵哨兵与古怪的侏儒工匠联手守卫山口，抵御这家公司肆无忌惮的破坏。",h="在狂风峭壁附近的营地里，凯拉·影矛派联盟旅者去找加克希姆·尘链，寻求对抗荆棘谷地精的帮助。谨慎的暗夜精灵哨兵与古怪的侏儒工匠联手守卫山口，抵御这家公司肆无忌惮的破坏。",kw={"工程学","加克希姆·尘链","侏儒","凯拉·影矛","暗夜精灵","石爪山脉","石爪峰","荆棘谷地精"},ang={["faction:Alliance"]="作为联盟的一员，你见证了东部王国的专长如何与卡利姆多的哨兵携手，应对边疆各地共同面临的威胁。",["profession:Engineering"]="作为工程师，你能看到工程学如何帮助前线侦察和生态防卫。当齿轮被用来对抗无节制的掠夺时，它们也能助力自然保护。",["race:Gnome"]="作为侏儒，你能看到加克希姆·尘链在卡利姆多施展侏儒的才智，运用科学、工程学与魔法应对这片土地上的挑战。",["race:NightElf"]="作为暗夜精灵，当Kaldorei哨兵信任一位推崇工程学与魔法的侏儒工匠时，你或许会感到骄傲之心有所退让。荆棘谷地精的伐木已造成毁灭性的破坏。"},sec={{t="意想不到的盟友",b="在石爪山脉的峭壁之间，贪婪的荆棘谷地精侵入荒野，砍伐古树。暗夜精灵哨兵凯拉·影矛明白，单靠武力无法阻止这种工业化的掠夺。她转而寻求侏儒的才智，尽管暗夜精灵与侏儒对技术和自然的看法鲜有一致之处。他们出人意料的结盟，表明这场抗争的局势已岌岌可危。"},{t="侏儒的哲学",b="加克希姆·尘链带来了联盟中这些小个子盟友古怪而务实的作风。暗夜精灵社会早在数千年前就摒弃了对奥术的滥用，但加克希姆认为，拒绝魔法与技术革新会让暗夜精灵变得脆弱。他希望说服接纳他的卡多雷，让他们相信，实用科学也能像弓箭和飞刃一样保卫自然。"}},faq={{q="为什么一名暗夜精灵和一名侏儒会在这里联手？",a="荆棘谷地精在石爪山脉的滥伐和资源开采已严重到让凯拉·影矛接受外援的地步。加克希姆带来了暗夜精灵通常缺乏的工程学与炼金术知识，为对抗现代工业机械提供技术支持。",al={"加克希姆为何与凯拉联手","凯拉与加克希姆","侏儒与暗夜精灵结盟"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一名富有冒险精神的侏儒工程师兼工匠，驻扎在狂风峭壁附近的营地。他认为，拒绝奥术魔法会让暗夜精灵处于劣势，并试图证明，工程学、炼金术与受控的魔法相结合，足以应对严峻的威胁。",al={"加克希姆·尘链背景故事","加克希姆是谁","石爪峰的侏儒"}},{q="凯拉·影矛是谁？",a="凯拉·影矛是一名暗夜精灵哨兵，负责石爪山脉的警戒与防御。作为当地的指挥官，她协调着对抗荆棘谷地精的行动。",al={"凯拉·影矛","凯拉是谁"}},{q="荆棘谷地精在石爪山脉造成了什么威胁？",a="荆棘谷地精是一个不择手段的商业集团，为了迅速牟利而砍伐神圣的森林，运转破坏性极强的钻机，污染石爪山脉原本纯净的土地。",al={"石爪山脉的荆棘谷地精","为何对抗荆棘谷地精"}},{q="凯拉提到的塔拉是谁？",a="塔拉就是哨兵塔拉·塞恩希尔，她是凯拉在阿斯特兰纳的朋友，也是派你来探望凯拉的人。塔拉在哨兵部队中表现出色，已经能够派遣冒险者办事，凯拉为此感到自豪。",al={"塔拉与石爪山脉","派回塔拉身边"}},{q="这项任务接下来会通向哪里？",a="与加克希姆·尘链交谈后，他会交给你任务“侏儒学者”，请你协助阻挡狂风峭壁的荆棘谷地精伐木工，让他能筹划接下来的发明。",al={"石爪山的守卫后续任务","加克希姆之后的任务"}}},fp="22,265,20.379.0,18.339.0,54.287.0,24.265.0,25.189.0,56.187.0,32.188.0,31.183.0"}
P.entries["quest:1086"] = {n="地精空港",s="药剂师扎玛派你去让石爪山高处的 地精空港 归于沉寂。将她的剧毒粮草带入荆棘谷地精的伐木场，打击这个财团与外界的联系。",h="药剂师扎玛派你去让石爪山高处的 地精空港 归于沉寂。将她的剧毒粮草带入荆棘谷地精的伐木场，打击这个财团与外界的联系。",kw={"机场","药剂师扎玛","直升机起降台","峭壁湖","飞行器","石爪山","雷霆崖","剧毒粮草","荆棘谷地精"},ang={["faction:Horde"]="身为部落的一员，你协助切断荆棘谷地精的外援。打击其空中运输，会对它的补给线造成沉重打击。",["profession:Engineering"]="身为工程师，你看得出地精直升机起降台的设计粗糙而实用，是为荆棘谷地精快速穿越崎岖山地而建。",["race:Tauren"]="身为牛头人，你憎恶荆棘谷地精对石爪山的破坏。在一位被遗忘者药剂师的敦促下使用毒素，考验着你如何在敬畏 earth-mother 与战场上的务实抉择之间保持平衡。",["race:Undead"]="身为被遗忘者，使用剧毒粮草对你而言是熟悉的工作：幽暗城的炼金技艺能够解决蛮力无法解决的问题。"},sec={{t="无声的投送",b="药剂师扎玛为荆棘谷地精准备了药剂师林度恩的毒素。牛头人力图保护石爪山，阻止森林遭到砍伐、机械肆意破坏，而被遗忘者则采取了另一种手段。扎玛瞄准的是这个财团与山外的联系，而非它的步兵或伐木工。据传，一处直升机起降台负责在石爪山与远方的公司办事处之间运送轻型货物和信件。"},{t="峭壁湖的空港",b="荆棘谷地精的直升机起降台位于峭壁湖一带的高处，在巨型水车以南。这座小平台供轻型飞行器使用，而非庞大的飞艇。你奉命在那里施放剧毒粮草，让毒雾笼罩起降台，赶在飞行员、信使或机械师向公司指挥官报警之前下手。"},{t="被遗忘者的实用之道",b="药剂师扎玛毫不为对地精发动化学战感到歉疚。她认为，凭荆棘谷地精对这片土地的所作所为，他们理应承受更惨重的代价。她从幽暗城的信条中得到的教诲很明确：只要能通向胜利，部落就不该畏惧黑暗的道路。"}},faq={{q="飞行器机场在哪里？",a="荆棘谷地精的直升机起降台位于石爪山脉的峭壁湖一带，在巨型工业水车以南。高架木制平台俯瞰着湖泊南端的弯曲处。",al={"机场在哪里","直升机起降台位置","空港在哪里","荆棘谷地精起降台"}},{q="药剂师扎玛为什么要在这里投毒？",a="扎玛想切断荆棘谷地精在石爪山与遥远总部之间的通信和轻型物资补给线。她希望在起降台投毒，能使地精飞行人员丧失行动能力，并将毒素带回公司高层身边。",al={"为什么轰炸机场","为什么使用剧毒粮草","扎玛 的动机"}},{q="药剂师扎玛是谁？",a="药剂师扎玛是皇家药剂师学会的使者，驻扎在雷霆崖下方的预见之池。她研究卡利姆多的动植物，并为被遗忘者和部落研制炼金武器。",al={"扎玛 的身份","扎玛 是谁","雷霆崖的亡灵"}},{q="部落为什么在这里使用化学武器？",a="被遗忘者使用化学武器，奉行冷酷的实用主义。扎玛认为，荆棘谷地精贪婪成性、肆意破坏，理应受到毫不留情的打击，而她的牛头人盟友则倾向于用灵性力量治愈大地，并直接抵御来犯之敌。在她看来，胜利比克制更重要。",al={"部落使用瘟疫","为什么毒害地精","这是瘟疫吗"}},{q="荆棘谷地精在这里使用什么飞行器？",a="荆棘谷地精使用小型地精飞行器和旋翼机，而非全尺寸飞艇。这些灵巧的飞行器穿越石爪山崎岖的山口，运送紧急信件和货物。",al={"荆棘谷地精直升机","什么飞行器","石爪山 地精飞行器"}},{q="施放剧毒粮草后会发生什么？",a="在起降台上施放剧毒粮草后，你赶在毒雾吞没自己之前逃离。扎玛认为这次投放很成功，并期待毒素扰乱地精的后勤。",al={"剧毒粮草的效果","放置剧毒粮草之后"}}},fp="26,206,17.405.0,19.334.0,19.275.1,44.203.0,50.244.0,24.225.0,45.270.0,56.198.0,42.176.1"}
P.entries["quest:1087"] = {n="塞纳留斯的遗产",s="在烈日石居附近，塞纳留斯的遗产将布莱林·火拳的不满化作了战斗的号召。这位血精灵法师声称，暗夜精灵和塞纳留斯的子嗣压制了这片土地的魔法。她想要在石爪峰剿杀他们，让原始的奥术能量自由流动，同时借他们的败亡削弱联盟在群山中的势力。",h="在烈日石居附近，塞纳留斯的遗产将布莱林·火拳的不满化作了战斗的号召。这位血精灵法师声称，暗夜精灵和塞纳留斯的子嗣压制了这片土地的魔法。她想要在石爪峰剿杀他们，让原始的奥术能量自由流动，同时借他们的败亡削弱联盟在群山中的势...",kw={"布莱林·火拳","塞纳里奥植物学家","塞纳留斯的遗产","塞纳留斯的女儿","加德纳尔","奥达努斯","塞纳留斯之子","石爪峰","烈日石居"},ang={["class:Druid"]="身为一名Tauren德鲁伊，杀死塞纳留斯的子嗣和塞纳里奥议会的植物学家，意味着在阵营忠诚与神圣的自然之道之间痛苦地挣扎。",["class:Mage"]="身为一名法师，你或许能理解古老的kaldorei结界与自由流动的魔网能量之间的冲突。布莱林不顾后果的狂热已近乎痴迷。",["faction:Horde"]="身为部落的一员，你知道石爪峰是这片山脉中联盟与kaldorei势力最大的堡垒。清除那里的守军，有助于保障烈日石居和巨木谷的安全。"},sec={{t="受阻的涌流",b="布莱林·火拳住在烈日石居附近的山丘间，对石爪山的自然结界深感不满。她声称，塞纳里奥议会的德鲁伊和半神塞纳留斯的子嗣阻塞了这片土地的奥术涌流。在布莱林看来，在这里引导能量，就像用漏桶打水。她想要剥除这些防护，让原始的魔法能量再次自由奔涌。"},{t="突袭石爪峰",b="布莱林派遣部落勇士北上石爪峰，打破守护者的控制。塞纳里奥植物学家和骄傲的塞纳留斯的儿子和塞纳留斯的女儿在那里的古老卡多雷林地与神殿周围巡逻。击杀他们，就能削弱那些压制布莱林法术的结界。这也将重创那处威胁部落在群山中立足的暗夜精灵据点。"},{t="与暗影议会的牵连",b="布莱林·火拳渴望返回加德纳尔，那是暗影议会藏在北方费伍德森林中的一处腐化据点。她那位从未露面的主人禁止她返回，直到她完成在石爪山的工作。部落为了争夺领土而帮助她，却往往不知道她背后有一个邪恶教派在发号施令。"}},faq={{q="布莱林·火拳是谁？",a="布莱林·火拳是一名血精灵施法者，住在烈日石居附近的峭壁间。她接受部落的帮助，要将暗夜精灵从石爪山清除。",al={"布莱林·火拳背景故事","任务发布者是谁","布莱林"}},{q="布莱林为什么想杀死塞纳留斯的子嗣？",a="布莱林声称，卡多雷植物学家和塞纳留斯子嗣的德鲁伊魔法压制了群山中的原始奥术能量。她想要消灭他们，削弱林地的结界，让释放出的魔法流入她的掌握之中。",al={"为什么杀死塞纳留斯的儿子","为什么憎恨塞纳里奥植物学家","布莱林为什么憎恨他们"}},{q="目标位于何处？",a="塞纳留斯的儿子、塞纳留斯的女儿和塞纳里奥植物学家位于遥远北方的石爪峰。他们守护着祖先留下的遗迹、林地，以及暗夜精灵维护的月亮井。",al={"塞纳留斯的儿子在哪里","石爪峰怪物位置","哪里能找到塞纳里奥植物学家"}},{q="布莱林提到的加德纳尔是什么地方？",a="加德纳尔是费伍德森林中的一片深谷和洞穴群，遭到了燃烧军团的严重腐化。它是暗影议会在卡利姆多的行动中枢。",al={"加德纳尔是什么","布莱林主人加德纳尔","与加德纳尔的联系"}},{q="部落为什么愿意帮助布莱林攻击塞纳里奥守卫？",a="石爪峰的暗夜精灵隶属联盟，阻挠部落在群山中扩张。无论布莱林个人有何动机，削弱他们的林地都有助于部落控制这一地区。",al={"部落为什么杀死塞纳里奥议会成员","部落石爪峰冲突"}},{q="完成塞纳留斯的遗产后会发生什么？",a="此后，布莱林的下一个目标是奥达努斯，一位位于灰谷林中树居的丛林守护者。他就在那里的巨树顶端。",al={"塞纳留斯的遗产后续任务","任务链下一步是什么","奥达努斯任务线"}}},fx={["9bca5a54"]={q="在塞纳留斯的遗产中，你受命杀死谁？",a="布莱林派你去对付塞纳留斯之子与塞纳留斯之女，以及驻扎在石爪峰顶的塞纳里奥植物学家。这些守护者、树妖和暗夜精灵看护者照料着神圣的林地，辛勤培育土地，保护该地区免遭布莱林企图利用的混乱燃烧奥术魔法侵袭。",al={"塞纳留斯的遗产任务目标","塞纳留斯的遗产要杀谁","塞纳留斯之子与塞纳留斯之女是什么人"}}},fp="16,331,16.387.0,27.401.0,26.293.1,24.152.1,52.229.0,30.193.0,41.162.0,67.219.0,47.134.1"}
P.entries["quest:1088"] = {n="奥达努斯",s="在 Sunrock Retreat，布莱林·火拳借助奥术视野追猎从石爪峰逃走的守护者奥达努斯，他是塞纳留斯的年长子嗣之一。她认为他的族人亵渎了古老的上层精灵遗迹，因此派部落勇士越过边界，进入灰谷取下他的首级。",h="在 Sunrock Retreat，布莱林·火拳借助奥术视野追猎从石爪峰逃走的守护者奥达努斯，他是塞纳留斯的年长子嗣之一。她认为他的族人亵渎了古老的上层精灵遗迹，因此派部落勇士越过边界，进入灰谷取下他的首级。",kw={"灰谷","布莱林·火拳","塞纳留斯","上层精灵","奥达努斯","林中树居","石爪山","烈日石居"},ang={["class:Druid"]="身为部落的德鲁伊，你面临一个残酷的抉择：为了了结一名血精灵的远古宿怨，夺去塞纳留斯一位直系子嗣的生命。",["class:Mage"]="身为法师，你或许会在布莱林·火拳身上看到上层精灵对奥术不屈的骄傲，以及他们坚信奥术之道凌驾于塞纳里奥自然哲学之上的信念。",["faction:Horde"]="身为部落的一员，你击杀塞纳留斯的一位年长子嗣，削弱了暗夜精灵在灰谷与石爪山边界一带的权威，帮助部落向争夺中的林地扩张。"},sec={{t="远古宿怨驱使的追猎",b="布莱林·火拳奉主人之命来到石爪山脉，要夺回艾萨拉古代神殿的神圣遗迹。她发现暗夜精灵早已占据峰顶，将她的上层精灵先祖留下的遗物视为需要约束的荒野之物。她的首要目标守护者奥达努斯在被她逼入绝境前逃脱，越界进入了灰谷。布莱林借助奥术视野，发现他藏身于林中树居高处的一座木制庇护所，随后招募部落来完成这场追猎。"},{t="森林之神的子嗣",b="在塞纳留斯的众多子嗣中，守护者奥达努斯是最年长的几位之一，与卡利姆多的荒野魔法有着深厚联系。暗夜精灵守卫将他从石爪峰转移到林中树居，以保护他免受侵入神圣林地的奥术力量侵害。忠诚的塞纳里奥辩护者和召唤而来的林地树人守护着他。在布莱林眼中，这位守护者承载着森林半神的古老权威，也阻挡着她的复仇之路。"},{t="上层精灵的复仇",b="布莱林·火拳索要奥达努斯的首级，既是为了她的事业，也是为了私怨。她记得自己数百年前就认识他，那时塞纳留斯的子嗣蔑视上层精灵及其对奥术的掌控。取下他的首级，既能报复昔日的羞辱，也能为她的主人在卡利姆多荒野中的深层图谋扫清道路。"}},faq={{q="守护者奥达努斯是谁？",a="守护者奥达努斯是一位丛林守护者，也是塞纳留斯最年长的子嗣之一。他最初驻守在石爪峰附近，后来为躲避上层精灵的复仇而逃入灰谷。",al={"奥达努斯 背景故事","奥达努斯 是谁","守护者 奥达努斯 是谁"}},{q="在哪里能找到守护者奥达努斯？",a="守护者奥达努斯住在林中树居一座巨大空心树建筑的顶端，那里位于贯穿灰谷中部的道路沿线。",al={"奥达努斯 位置","奥达努斯 在哪里","林中树居 大树"}},{q="布莱林·火拳为何想要奥达努斯死？",a="布莱林认为，暗夜精灵占据石爪山是对古老上层精灵神殿遗迹的亵渎。她也憎恨奥达努斯，因为在她的记忆中，他在久远的过去傲慢自大，蔑视她的族人。",al={"为何杀死 奥达努斯","布莱林 的宿怨","布莱林 为何追杀 奥达努斯"}},{q="布莱林·火拳的主人是谁？",a="布莱林说，她的主人派她前往石爪峰，夺回艾萨拉的古代神殿遗迹，但她对主人的确切身份守口如瓶。",al={"布莱林 的主人","谁派来了 布莱林","布莱林的主人"}},{q="这场冲突与部落在石爪山的势力有何关联？",a="烈日石居 的部落军队经常为了石爪山和灰谷各地的领土与资源，同暗夜精灵哨兵和塞纳里奥守护者发生冲突。布莱林对一位塞纳里奥领袖的袭击，符合双方的目标。",al={"部落为何帮助 布莱林","石爪山 部落动机"}},{q="奥达努斯被杀后会发生什么？",a="奥达努斯死后，布莱林会给予你奖赏，并指引你前往大兽穴，石爪山群峰间的种种威胁正在那里等着你。",al={"击杀 奥达努斯 后续","奥达努斯 后续任务","大兽穴 后续"}}},fp="7,249,32.433.0,27.415.0,19.335.1,22.166.0,34.121.0,44.188.0,33.138.0,67.222.0,36.119.1"}
P.entries["quest:1089"] = {n="大兽穴",s="布莱林·火拳派遣部落勇士潜入猛禽洞穴隐秘的墓室，夺取德鲁伊的圣物。当他们面对石爪峰地下的层层防御时，这场潜入行动也迎来了高潮。",h="布莱林·火拳派遣部落勇士潜入猛禽洞穴隐秘的墓室，夺取德鲁伊的圣物。当他们面对石爪峰地下的层层防御时，这场潜入行动也迎来了高潮。",kw={"古墓钥匙","布莱林·火拳","塞纳留斯的遗产","利爪钥匙","守门人的钥匙","奥达努斯","沉睡者的钥匙","石爪峰","猛禽洞穴","猛禽洞穴储藏室"},ang={["class:Druid"]="身为部落的牛头人德鲁伊，你面对的是苦涩的讽刺：以沉睡者、利爪和古墓命名的钥匙，让墓穴的防御反过来危及同属塞纳里奥的守护者。",["class:Rogue"]="身为潜行者，你凭借敏锐的潜入技巧与诡计穿行于幽暗的厅堂，从隐蔽的提灯和火炬支架中取走钥匙。",["faction:Horde"]="突袭猛禽洞穴会削弱暗夜精灵在石爪峰顶的防御，控制通往山中的道路，并让强大的魔法圣物落入部落之手。",["race:NightElf"]="身为暗夜精灵，你目睹猛禽洞穴遭到亵渎：塞纳里奥守护者漫长的沉眠被打断，封存在结界中的圣物也遭到掠夺。"},sec={{t="地下的秘密",b="在石爪山脉的高处，猛禽洞穴的厅堂深凿于天然岩石之中，为暗夜精灵德鲁伊提供庇护。墓室保护着冥想中的守护者，也让神圣的宝藏远离窥探。布莱林·火拳深知其中藏品的价值，便审问一名被俘的德鲁伊，探明这些防御的运作方式。"},{t="层层锁钥",b="德鲁伊用环环相扣的锁保护着他们的圣物。墓穴入口处的一盏提灯里藏着守门人的钥匙，可以打开深处的三处储藏。这三处储藏中分别放着沉睡者的钥匙、利爪钥匙和古墓钥匙。转动中央宝库中的三块雕刻石头，就能破除德鲁伊的封印，让那些古老的物品落入部落之手。"}},faq={{q="猛禽洞穴是什么地方？",a="猛禽洞穴是一片开凿于石爪峰高处的暗夜精灵墓穴群。洞内的厅堂庇护着休眠的德鲁伊，守护着他们的神圣遗物。",al={"猛禽洞穴在哪","大兽穴是什么","石爪墓穴"}},{q="谁下令潜入猛禽洞穴？",a="布莱林·火拳是一名在石爪山脉与部落合作的辛多雷特工，由她指挥这次潜入行动。她审问一名被俘的德鲁伊，了解这处圣所的防御后，便派部落特工前往宝库。",al={"谁发布大兽穴任务","布莱林·火拳的目的","谁派我去大兽穴"}},{q="大兽穴里的钥匙有什么用？",a="最先需要的守门人的钥匙藏在入口附近的一盏提灯里。它能打开墓穴内的三处储藏，其中分别放着沉睡者的钥匙、利爪钥匙和古墓钥匙。转动宝库中的三块雕刻石头，就能解除防护结界。",al={"如何打开猛禽洞穴储藏室","守门人的钥匙用途","石爪三把钥匙"}},{q="为什么石爪峰的德鲁伊会成为目标？",a="布莱林·火拳想要恢复这一带的魔法流动，并指责石爪峰的德鲁伊和塞纳留斯的子嗣阻碍了它。她命人杀死这些德鲁伊，包括他们的首领守护者奥达努斯，她声称自己曾与他相识，随后又派你去夺走大兽穴中那些强大的物品。",al={"为何攻击石爪德鲁伊","部落杀死奥达努斯的原因","为何掠夺大兽穴"}},{q="猛禽洞穴储藏室里有什么？",a="猛禽洞穴储藏室中存放着暗夜精灵德鲁伊收集的强大圣物与宝藏。宝库的结界一直保护着它们，使其免遭外来者侵入，直到布莱林逼问出了破解防御的步骤。",al={"猛禽洞穴储藏室战利品背景","宝库里有什么","德鲁伊藏了什么"}},{q="这个任务之前发生了什么？",a="在你闯入大兽穴之前，部落冒险者受命调查塞纳留斯的遗产中的暗夜精灵势力，并刺杀守护者奥达努斯，削弱守卫的指挥力量。",al={"大兽穴任务链","大兽穴前置任务","大兽穴前置条件"}}},fp="7,192,20.301.0,17.352.1,22.151.0,45.229.0,36.224.0,53.292.0,35.182.0,38.184.0"}
P.entries["quest:109"] = {n="向格里安·斯托曼报到",s="在哨兵岭，格里安·斯托曼召集西部荒野的守卫者，抵御威胁农场的敌人。",h="在哨兵岭，格里安·斯托曼召集西部荒野的守卫者，抵御威胁农场的敌人。",kw={"迪菲亚","艾尔文","格里安·斯托曼","治安官杜汉","人民军","哨兵岭","暴风城","西部荒野"},ang={["class:Warrior"]="作为一名战士，你拥有格里安·斯托曼所看重的老练与纪律，是人数处于劣势的人民军中的重要战力。",["faction:Alliance"]="作为联盟的一员，你看到普通民众为了生存而组建民兵，而王室朝廷仍在暴风城为政事争论不休。",["race:Human"]="作为王国的一名人类，你看到了暴风城安全的大理石街道与城外环境恶劣、无人照管的农田之间的鸿沟。"},sec={{t="来自河对岸的求援",b="艾尔文边境的卫兵和被迫西迁的农夫，都将有能力的旅人引向哨兵岭。响应号召的人加入了由当地志愿者组成的防卫队伍。没有王国军队前来援助他们。"},{t="哨兵岭与民兵",b="格里安·斯托曼在哨兵岭顶端的石塔中，将农夫、退伍老兵和雇佣兵组织成人民军。你加入了他们艰苦的游击战，以免西部荒野的农田沦为无法无天之地。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位身经百战的战士，统领着人民军。他在哨兵岭顶端的石塔中组织西部荒野的防务，召集战士，保护当地农夫免受匪徒和野兽的侵害。",al={"格里安·斯托曼","斯托曼是谁","哨兵岭领袖"}},{q="为什么需要人民军？",a="之所以需要人民军，是因为暴风城的军队将注意力转向了首都，王室几乎不再支援西部荒野。居民们组建了民兵，抵御匪徒、失控的收割机器人和四处劫掠的河爪豺狼人。",al={"为何需要民兵","为何没有暴风城军队","西部荒野为何被遗弃"}},{q="哨兵岭位于何处？",a="哨兵岭位于西部荒野中部附近，坐落在主干道旁。那里坚固的石制哨塔和设有防御工事的营地，是人民军的集结之处。",al={"寻找哨兵岭","哨兵岭位置","哪里能找到斯托曼"}},{q="谁会派冒险者执行这项任务？",a="闪金镇的治安官杜汉、卫兵托马斯和瑞尼尔副队长这样的边境卫兵，以及农夫法布隆和农夫萨丁这样流离失所的农夫，都会将能征善战的人派往格里安那里。",al={"谁提供任务","任务给予者","向格里安报到任务给予者"}},{q="向格里安报到后会发生什么？",a="当你向斯托曼报到后，他会让你运用战斗本领，为人民军效力。你最初的任务是对付威胁西部荒野的迪菲亚匪徒和豺狼人。",al={"接下来做什么","斯托曼后续任务","民兵任务链"}},{q="西部荒野名义上仍属于联盟吗？",a="是的。西部荒野仍是联盟的领土，名义上由暴风城王国管辖。王室驻军疏于照管这片地区，只能由武装起来的平民保卫它。",al={"西部荒野属于联盟吗","西部荒野归暴风城管辖吗"}}},fx={a1beb42d={q="为什么要你向格里安·斯托曼报到？",a="暴风城将兵力集中于内部，基本任由西部荒野落入强盗和拾荒者之手，在当地坚守的人们已经捉襟见肘。格里安·斯托曼和他的人民军急需经验丰富的战士，保卫残存的农田。从艾尔文派你前来的人明白，邻近的西部荒野正彻底陷入混乱，让你在平静的果园里巡逻，实在埋没了你的战斗本领。",al={"为何向斯托曼报到","为何去西部荒野","杜汉 西部荒野 斯托曼 原因"}},e97846b7={q="格里安·斯托曼为什么需要独立冒险者，而不是暴风城卫兵？",a="暴风城王室拒绝向西部荒野派遣正规军增援，这片地区实际上已被王室遗弃。强盗、豺狼人和不法之徒大举侵占农场，当地卫兵和民兵已无力应付。格里安·斯托曼只能依靠像你这样能干的游历佣兵和冒险者，你们既有实战经验，也愿意为他们的事业拿起武器。",al={"西部荒野为何需要冒险者","为何找冒险者而非军队","人民军为何需要帮助"}}},fp="27,94,23.204.0,29.234.0,25.210.0,35.272.0,31.162.0,41.179.0,38.176.0,51.175.0"}
P.entries["quest:1090"] = {n="格雷苏的要求",s="在石爪山的荆棘谷地精挖掘场，匹兹尼克正暗中对抗他的新上司格雷苏。这个被夺去职位的地精希望挖出一份样本，揭露这场采矿行动，同时由一名盟友保护他，抵挡营地的巡逻队。",h="在石爪山的荆棘谷地精挖掘场，匹兹尼克正暗中对抗他的新上司格雷苏。这个被夺去职位的地精希望挖出一份样本，揭露这场采矿行动，同时由一名盟友保护他，抵挡营地的巡逻队。",kw={"格雷苏","金绿色矿石","神秘矿石","匹兹尼克","石爪山脉","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["faction:Horde"]="荆棘谷地精肆无忌惮地挖掘侵占，破坏了石爪山的自然景观。监视、干扰或利用公司的作业，都能帮助附近的部落军队。",["profession:Mining"]="荆棘谷地精的矿工在石爪山发现的奇怪金绿色矿石，既不属于铁矿脉，也不属于锡矿脉，引起了对稀有矿物充满好奇的勘探者的兴趣。"},sec={{t="峭壁间的公司背叛",b="在狂风峭壁，荆棘谷地精重视的是冷酷无情，而非忠诚。匹兹尼克曾是挖掘场的二把手，直到格雷苏夺权，解雇了主管菲兹克斯，又把匹兹尼克赶回矿井挥镐干活。匹兹尼克没有离开。他遵照菲兹克斯的指示留下充当眼线，监视格雷苏的一举一动，等待机会反击这位夺去他职位的主管。"},{t="挖掘金绿色矿脉",b="格雷苏夺权的起因，是他痴迷于石爪山岩层中一种奇怪的金绿色矿石。他相信这种矿物价值连城，便下令矿工大规模开采。菲兹克斯有了一位神秘的新雇主，对方或许愿意出高价购买这场采矿行动的消息。匹兹尼克冒着暴露的危险挖取样本，依靠一名盟友抵挡来势汹汹的挖掘工、歹徒，以及监管开采作业的监工。"}},faq={{q="匹兹尼克是谁？",a="匹兹尼克是在石爪山脉狂风峭壁采矿场干活的一名地精劳工。他曾是菲兹克斯手下的二把手，但格雷苏夺权后，将他贬为矿工。",al={"匹兹尼克","地精矿工是谁","匹兹尼克 石爪山"}},{q="匹兹尼克为什么要秘密开采这种矿石？",a="匹兹尼克正在秘密收集一种奇怪的金绿色矿石样本，格雷苏曾下令大量开采这种矿石。他的前任上司菲兹克斯说，一位新雇主愿意出高价，购买有关格雷苏这项高价值采矿作业的情报。",al={"为什么开采矿石","神秘矿石","金绿色矿石"}},{q="格雷苏是谁？",a="格雷苏是荆棘谷地精一名冷酷无情的主管，他解雇了菲兹克斯，夺取了石爪山挖掘场的控制权。他将公司的资源投入开采，挖掘遍布峭壁的一种陌生的金绿色矿石。",al={"格雷苏","格雷苏是谁","格雷苏 荆棘谷地精"}},{q="菲兹克斯现在为谁效力？",a="格雷苏解雇了菲兹克斯，后者随后与新的支持者结盟，他们有意监视荆棘谷地精在当地的活动。菲兹克斯付钱给行动人员和匹兹尼克这样的眼线，让他们破坏格雷苏的行动，并查明公司究竟在挖掘什么。",al={"菲兹克斯的新上司","谁雇用了菲兹克斯","菲兹克斯的雇主"}},{q="匹兹尼克挖矿时会遭到谁的攻击？",a="匹兹尼克挖矿时，荆棘谷地精的工人会攻击他，其中包括风剪坑道鼠、风剪歹徒、挖掘工、地卜师、石工和监工。",al={"匹兹尼克遇袭","谁攻击匹兹尼克","狂风巡逻队"}},{q="挖出样本后会发生什么？",a="匹兹尼克挖出矿石样本后，会把它交给保护他的人，直接送到菲兹克斯手中。他希望这份样本能让菲兹克斯有筹码挫败格雷苏的计划。",al={"矿石送往哪里","样本怎么处理"}}},fp="16,201,30.408.0,30.427.0,14.187.0,39.220.0,15.218.0,34.234.0,34.153.0,38.172.0"}
P.entries["quest:1091"] = {n="向凯拉回报",s="加克希姆·尘链让你带着从荆棘谷地精手中缴获的信件，回去找凯拉·影矛。信中的内容能帮助Sentinels追踪这个地精财团在石爪山脉的活动。",h="加克希姆·尘链让你带着从荆棘谷地精手中缴获的信件，回去找凯拉·影矛。信中的内容能帮助Sentinels追踪这个地精财团在石爪山脉的活动。",kw={"加克希姆·尘链","凯拉·影矛","凯拉的消息","信件","哨兵","石爪峰","荆棘谷地精"},ang={["faction:Alliance"]="对联盟而言，运送截获的荆棘谷地精信件，有助于巩固其在石爪山脉尚不稳固的立足点，抵御这个财团的掠夺。",["race:Gnome"]="身为侏儒，你可以为加克希姆·尘链的奥术造诣感到自豪，他正努力让暗夜精灵盟友看到侏儒魔法的价值。",["race:NightElf"]="身为暗夜精灵，每一份针对荆棘谷地精的情报，都能帮助Sentinels保护卡利姆多饱受创伤的荒野，使其免遭工业活动的侵害。"},sec={{t="山间信使",b="加克希姆·尘链让你带着缴获的信件，回去找凯拉·影矛。你帮助这位侏儒法师查明荆棘谷地精的动向后，他收集了详细记述这个财团行动的往来信件。凯拉是狂风峭壁附近的一位暗夜精灵哨兵协调官，正在等候这些信件。加克希姆还希望你提一提，他的魔法在调查中起了多大作用。"},{t="Eyes of the Sentinels",b="Sentinels忧心忡忡地注视着石爪山脉的峭壁。部落军队争夺着山脚的小径，荆棘谷地精则在这里伐木采矿。这些信件让凯拉得以了解这个财团的通信内容，并帮助联盟筹划山脊一带的防御。"}},faq={{q="凯拉·影矛是谁？",a="凯拉·影矛是一位暗夜精灵哨兵军官，驻扎在狂风峭壁附近的营地。她负责山中的侦察和防御，抵御部落与地精采矿公司。",al={"凯拉·影矛","凯拉是谁","凯拉 石爪山脉"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是石爪山脉的一位侏儒法师。他与当地的暗夜精灵哨兵合作，运用魔法调查并破坏荆棘谷地精的行动。",al={"加克希姆","加克希姆·尘链","侏儒法师 石爪山脉"}},{q="荆棘谷地精的信件里写了什么？",a="这些信件是针对荆棘谷地精营地采取行动时截获的往来通信。它们为凯拉·影矛和哨兵提供了有关这个财团在当地的后勤、挖掘和资源掠夺的情报。",al={"荆棘谷地精信件","信件是什么","给凯拉的信件"}},{q="哨兵为何担忧荆棘谷地精的活动？",a="荆棘谷地精砍伐神圣的森林，用重型机械开采大地。哨兵认为，这些工业活动威胁着自然，也玷污了石爪山脉的神圣。",al={"为何关注地精","哨兵 荆棘谷地精","荆棘谷地精 石爪山脉"}},{q="这个任务在哪里接取和交付？",a="你在山间小径旁的加克希姆·尘链处接取任务，再到狂风峭壁附近的营地向凯拉·影矛交付。",al={"任务地点","交付 凯拉的情报","凯拉在哪里"}},{q="这个任务会引出进一步的调查吗？",a="送达信件能让哨兵及时了解这个财团的活动。凯拉可以利用这些情报，筹划石爪山脉各处后续的军事应对和侦察行动。",al={"下一个任务","凯拉的情报 之后是什么","后续任务"}}},fp="14,177,28.368.0,21.253.0,25.179.0,24.174.0,39.218.0,58.168.0,36.126.0,47.176.0"}
P.entries["quest:1092"] = {n="格雷苏的要求",s="匹兹尼克将格雷苏的要求的矿石样本送往挖掘场外的联络人菲兹克斯手中。这次递送为狂风峭壁荆棘谷地精矿场内的一场危险间谍行动画上了句号。",h="匹兹尼克将格雷苏的要求的矿石样本送往挖掘场外的联络人菲兹克斯手中。这次递送为狂风峭壁荆棘谷地精矿场内的一场危险间谍行动画上了句号。",kw={"格雷苏的要求","匹兹尼克","石爪山","安德迈","未经化验的矿石","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["profession:Engineering"]="Undermine的地精工程师愿意高价收购未经提炼的奇异矿石，用来为不稳定的新型机械和原型机提供动力。",["profession:Mining"]="遵照格雷苏的命令开采出的未经化验的矿石表明，荆棘谷地精在狂风峭壁的活动不止于砍伐森林：他们还在群山中寻找未知的地下财富。"},sec={{t="脱身的门票",b="匹兹尼克在狂风峭壁的身份已经暴露，他知道自己不能再留在荆棘谷地精的队伍里。安德麦的管理层会惩罚内部的破坏行为，因此这个惴惴不安的地精打算悄悄离开，另寻雇主。临走前，他将遵照格雷苏的命令开采出的未经化验的矿石交给了一名外来者。这份样本必须送达目的地，同时不能让匹兹尼克受到怀疑。"},{t="公司的奇珍",b="菲兹克斯在狂风峭壁西缘的一处秘密哨站等候。他看中了这种矿物的价值，打算将它送往南方，交给安德麦的工程师，同时悄悄为自己留下一部分珍贵的矿石。他的计划映照出石爪山脉之下暗流涌动的激烈贸易与工程纷争。"}},faq={{q="匹兹尼克为什么需要逃离狂风峭壁？",a="匹兹尼克为菲兹克斯秘密开采矿石样本时，被矿场的监工当场抓住，身份就此暴露。他害怕荆棘谷地精的高层得知此事后会迅速报复，因此必须悄悄离开，另谋工作。",al={"匹兹尼克为何离开","匹兹尼克逃跑","匹兹尼克为何害怕"}},{q="菲兹克斯是谁？",a="菲兹克斯是一名在狂风峭壁西侧山脊扎营的地精掮客。他将匹兹尼克安插进荆棘谷地精，窃取公司情报和稀有矿物样本。",al={"菲兹克斯是谁","菲兹克斯的职责","菲兹克斯在哪里"}},{q="未经化验的矿石是什么？",a="未经化验的矿石是一份神秘的金绿色矿石样本，总工程师格雷苏曾下令大量开采这种矿石。菲兹克斯打算将它送给安德麦的工程师和研究人员，研究它的工业用途。",al={"未经化验的矿石背景","矿石是什么","格雷苏的矿石"}},{q="在哪里可以找到菲兹克斯？",a="菲兹克斯位于石爪山脉的一处小营地，那里坐落在狂风峭壁西缘，可以俯瞰峭壁。",al={"菲兹克斯的位置","寻找菲兹克斯","格雷苏的命令在哪里交付"}},{q="菲兹克斯收到矿石后会如何处置？",a="菲兹克斯打算将矿石样本的大部分送给安德麦的工程师，同时偷偷为自己留下一小块碎片。",al={"菲兹克斯如何处置矿石","菲兹克斯私留矿石"}},{q="匹兹尼克效忠于荆棘谷地精吗？",a="匹兹尼克为荆棘谷地精工作，只是为了替菲兹克斯谋利。他对辛迪加毫无忠诚可言，并且害怕其首领的报复。",al={"匹兹尼克的阵营","匹兹尼克属于荆棘谷地精吗","匹兹尼克为谁工作"}}},fp="16,176,12.394.0,21.309.1,44.228.0,19.176.0,29.210.0,31.112.0,45.114.0,39.146.0"}
P.entries["quest:1093"] = {n="超级收割机6000",s="在狂风峭壁，菲兹克斯想要赢得新老板斯布特瓦夫的赏识。他想拿到荆棘谷地精的大型伐木机设计图，这台机器出自他的对手格雷苏之手。",h="在狂风峭壁，菲兹克斯想要赢得新老板斯布特瓦夫的赏识。他想拿到荆棘谷地精的大型伐木机设计图，这台机器出自他的对手格雷苏之手。",kw={"蓝图","格雷苏","斯布特瓦夫","石爪山脉","超级收割机6000","荆棘谷地精","狂风峭壁","菲兹克斯"},ang={["profession:Engineering"]="地精工程学偏重速度和粗放的实用主义；侏儒设计则崇尚精密与复杂。双方的竞争由来已久。",["race:Gnome"]="身为侏儒，你或许能理解，为什么菲兹克斯不相信一个地精财团会放心让你的同族负责其最重要的机械。格雷苏的技术设计让他困惑不已。",["race:NightElf"]="身为暗夜精灵，你看到 Super Reaper 6000 在石爪山砍伐古树，为工业牟利，这鲜明地表明了凡人对自然的漠视。"},sec={{t="狂风峭壁的工业间谍",b="在狂风峭壁，风险投资公司 深入石爪山脉采伐，为其伐木业务提供木材。地精工程师菲兹克斯不久前被公司扫地出门，如今为斯布特瓦夫效力。他希望夺取公司巨型自动伐木机 超级收割机 6000 的设计图，向新老板证明自己的价值。"},{t="地精与侏儒的工程学之争",b="格雷苏被任命为荆棘谷地精的当地工程主管，这让菲兹克斯愤愤不平。这家公司大多由地精经营，却让一个侏儒掌管工程事务。当荆棘谷地精机械操作员携带的结构图送到菲兹克斯手中时，图纸上繁复的设计让他大为恼火。他习惯了蛮力、廉价零件和不稳定的燃烧方式，觉得格雷苏的精细设计难以理解。"}},faq={{q="菲兹克斯是谁？",a="菲兹克斯是石爪山脉的一名地精工程师。荆棘谷地精不久前解雇了他，斯布特瓦夫随即雇用了他。如今，菲兹克斯想向昔日的雇主报复。",al={"菲兹克斯","任务给予者是谁"}},{q="超级收割机 6000 是什么？",a="超级收割机 6000 是一台巨型机械伐木机，专为荆棘谷地精在狂风峭壁的伐木业务而设计。",al={"超级收割机 6000","超级收割机 是什么","这是什么机器"}},{q="谁设计了 超级收割机 6000？",a="超级收割机 6000 的设计者是格雷苏，一名受雇于荆棘谷地精的侏儒工匠。他的任命让曾经掌管这片工地的地精工程师深感受辱。",al={"谁制造了 超级收割机","谁制造了这台机器","格雷苏"}},{q="斯布特瓦夫为什么想要这些蓝图？",a="斯布特瓦夫想得到荆棘谷地精的重型伐木技术。菲兹克斯希望把设计图带给他，向新雇主证明自己的用处。",al={"为什么窃取设计图","斯布特瓦夫 蓝图"}},{q="在哪里能找到蓝图？",a="荆棘谷地精的机械操作员在狂风峭壁监管采伐机械时，随身携带着结构图。",al={"设计图在哪里","谁掉落蓝图"}},{q="为什么菲兹克斯拿到蓝图后却看不懂？",a="菲兹克斯难以看懂设计图，是因为地精和侏儒的工程学理念不同。格雷苏的图纸精细缜密，让菲兹克斯摸不着头脑，无法一眼看懂。",al={"为什么 菲兹克斯 看不懂设计图","侏儒 蓝图 地精"}}},fp="17,199,38.328.0,31.393.1,19.186.0,30.136.0,35.176.0,42.142.0,31.116.0,60.172.1"}
P.entries["quest:1094"] = {n="新的指示",s="菲兹克斯将从狂风峭壁窃取的荆棘谷地精图纸送往棘齿城。这些文件或许能让他的对手斯布特瓦夫占据优势。",h="菲兹克斯将从狂风峭壁窃取的荆棘谷地精图纸送往棘齿城。这些文件或许能让他的对手斯布特瓦夫占据优势。",kw={"贫瘠之地","进一步的指示","棘齿城","斯布特瓦夫","石爪山","超级收割机6000","荆棘谷地精","菲兹克斯"},ang={["faction:Horde"]="将窃取的荆棘谷地精图纸送往棘齿城，会加剧商业竞争，阻碍部落领地附近的工业扩张。",["profession:Engineering"]="信封承载着地精工业的印记：商业间谍活动、专利窃取，以及对复杂伐木机械的逆向工程。"},sec={{t="商业间谍",b="荆棘谷地精将菲兹克斯逐出其在狂风峭壁的伐木场后，他带走了机密文件、内部手册和技术图纸。他对遭到解雇心怀怨恨，将这些资料封进信封，寄往棘齿城。其中包括实验型超级收割机 6000的设计图。菲兹克斯希望找到愿意利用这些窃取资料的买家或盟友。"},{t="棘齿城的接头人",b="工程师斯布特瓦夫在贫瘠之地的中立港口棘齿城等待。他对菲兹克斯既无好感，也不信任，但与荆棘谷地精的竞争让他难以拒绝这份提议。这些隶属热砂的地精设法削弱这个冷酷无情的竞争对手，并热衷于对遇到的先进机械发明进行逆向工程。"}},faq={{q="密封的信封里有什么？",a="信封里装着荆棘谷地精的文件、技术手册和超级收割机 6000的设计图。菲兹克斯被逐出该公司的伐木场时，偷走了这些资料。",al={"信封内容","菲兹克斯寄送什么","被盗文件"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是贫瘠之地棘齿城的一名地精工程师。他不信任菲兹克斯，但想削弱荆棘谷地精，并研究其机械。",al={"斯布特瓦夫的身份","收件人是谁","棘齿城工程师"}},{q="菲兹克斯为什么要与荆棘谷地精作对？",a="荆棘谷地精将菲兹克斯逐出了其在石爪山的队伍。他心怀怨恨，一心复仇，开始向竞争对手泄露公司的商业机密。",al={"菲兹克斯为何背叛荆棘谷地精","菲兹克斯的动机"}},{q="在哪里可以找到斯布特瓦夫？",a="斯布特瓦夫位于棘齿城，那是贫瘠之地东部海岸的一座中立港口城镇。",al={"斯布特瓦夫在哪里","斯布特瓦夫的位置","寻找斯布特瓦夫"}},{q="斯布特瓦夫信任菲兹克斯吗？",a="不信任。斯布特瓦夫承认自己不信任菲兹克斯，但那些手册和设计图对他的价值，足以让他暂且放下对送信人的戒心。",al={"斯布特瓦夫信任菲兹克斯吗","菲兹克斯与斯布特瓦夫的关系"}},{q="超级收割机 6000是什么？",a="超级收割机 6000是荆棘谷地精研发的先进工业伐木机，用于快速清除森林和加工木材。它的设计图备受觊觎。",al={"超级收割机6000","这台机器是什么","荆棘谷地精收割机"}}},fp="20,124,19.413.0,22.336.0,35.184.0,20.151.0,55.137.0,32.84.0,36.121.0,30.166.0"}
P.entries["quest:1095"] = {n="新的指示",s="斯布特瓦夫带着来自安德麦的命令，要交给石爪山脉的菲兹克斯。大亨拉兹杜克雇用的侏儒工程师格雷苏必须被除掉。",h="斯布特瓦夫带着来自安德麦的命令，要交给石爪山脉的菲兹克斯。大亨拉兹杜克雇用的侏儒工程师格雷苏必须被除掉。",kw={"新的指示","格雷苏","诺莫瑞根","拉兹杜克","雷德沃克斯","斯布特瓦夫","石爪山","安德迈","荆棘谷地精","菲兹克斯"},ang={["profession:Engineering"]="身为工程师，你看到侏儒与地精工程学之间的竞争，从设计专利之争演变成了公司间的暗杀。",["race:Gnome"]="身为侏儒，你听说格雷苏曾是诺莫瑞根的一名高级工程师。他的秘密实验最终引发了一场灾难性的爆炸，波及了参与其中的工程师。"},sec={{t="公司不满",b="荆棘谷地精雇用格雷苏一事，在安德麦的统治者之间引起了风波。大亨拉兹杜克将这位侏儒工程师招入公司，消息传到了贸易亲王耳中。总监雷德沃克斯命令斯布特瓦夫悄悄介入。斯布特瓦夫认为命令来自最高贸易当局，于是将任务交给了离现场最近的特工菲兹克斯。"},{t="丹莫罗的秘密",b="菲兹克斯欣然接受了杀死格雷苏的命令。地精工程师鄙视他们的侏儒同行，而格雷苏的过往更让他成为一个极不稳定的危险人物。加入荆棘谷地精之前，他曾是诺莫瑞根的一名首席工程师，参与过一个绝密项目，连安德麦的间谍也未能完全查清内情。据说，那个项目最终酿成灾难，在工程师们面前炸开了。如今，格雷苏在卡利姆多向荆棘谷地精兜售他那些危险的专业技术。"}},faq={{q="斯布特瓦夫是谁？",a="斯布特瓦夫是总监雷德沃克斯手下的一名地精特工。他传达安德麦的指令，将委托交给菲兹克斯这样的外勤特工。",al={"斯布特瓦夫","谁提供任务","任务给予者斯布特瓦夫"}},{q="贸易亲王为什么在意格雷苏？",a="安德麦的贸易亲王不赞同莫古尔·拉兹杜克雇用一名外来的侏儒工程师。他们认为，这次雇用威胁到了地精在工业领域的主导地位，还会招来不必要的审视。",al={"贸易亲王为什么在意","安德麦的愤怒","格雷苏与贸易亲王"}},{q="格雷苏参与过什么秘密项目？",a="格雷苏曾在诺莫瑞根的一个机密项目中担任首席工程师。地精间谍未能查明项目的目的，而据说项目最终酿成灾难，在工程师们面前炸开了。",al={"格雷苏的秘密项目","诺莫瑞根爆炸","格雷苏的过去"}},{q="菲兹克斯在哪里？",a="菲兹克斯身在石爪山脉，一边监视荆棘谷地精在当地的伐木和采矿活动，一边执行公司的委托。",al={"菲兹克斯的位置","菲兹克斯在哪里","命令送到哪里"}},{q="菲兹克斯为什么急于杀死格雷苏？",a="菲兹克斯和其他地精一样，在专业领域仇视侏儒，并将格雷苏视为危险的对手。格雷苏在丹莫罗进行的实验最终酿成了灾难。",al={"菲兹克斯为什么憎恨格雷苏","菲兹克斯的反应","为什么杀死格雷苏"}},{q="莫古尔·拉兹杜克是谁？",a="莫古尔·拉兹杜克领导着荆棘谷地精。他雇用了格雷苏，违背了安德麦的贸易礼数，促使贸易亲王推动除掉格雷苏。",al={"商业大亨拉兹杜克","拉兹杜克是谁","荆棘谷地精首领"}}},fp="20,156,21.323.0,21.476.1,20.152.0,44.189.0,40.188.0,29.147.0,41.155.0,21.162.0"}
P.entries["quest:1096"] = {n="格雷苏",s="在石爪山脉的峭壁湖上方高处，格雷苏正遭到悬赏追捕。这个叛变的侏儒监工用齿轮、发条机械和人造肢体替换了大部分腐烂的血肉。菲兹克斯想要他的机械臂作为死亡证明，希望借此获得晋升。",h="在石爪山脉的峭壁湖上方高处，格雷苏正遭到悬赏追捕。这个叛变的侏儒监工用齿轮、发条机械和人造肢体替换了大部分腐烂的血肉。菲兹克斯想要他的机械臂作为死亡证明，希望借此获得晋升。",kw={"峭壁湖","半机械人","格雷苏","机械臂","斯布特瓦夫","石爪山","扳哨","菲兹克斯"},ang={["faction:Horde"]="作为部落的一员，你可以帮助石爪山的地精承包商夺取资源和领地，同时破坏峭壁间那些危险的叛变工程师的活动。",["profession:Engineering"]="格雷苏的机械臂展现了侏儒仿生工程学所能达到的程度，与地精注重实用的设计形成鲜明对比。",["race:Gnome"]="身为侏儒，格雷苏采取古怪而骇人的手段，通过激进的自我强化来维持日渐衰败的身体。"},sec={{t="骇人的混合体",b="格雷苏的身体上满是改造留下的痕迹。见过他的人说，在移植的齿轮、铁甲和嗡嗡运转的发条肢体之下，他原本的血肉正在腐烂。他在峭壁湖上方的大水车附近监督作业，丝毫不在意自己日渐衰败的血肉之躯。"},{t="地精的野心",b="菲兹克斯为斯布特瓦夫效力，希望格雷苏的覆灭能让自己离开石爪山。菲兹克斯无法亲自攀上悬崖，击败这个经过强化的监工，于是请你带回格雷苏的机械臂。他希望借此证明自己的价值，获准调往加基森或安德麦的工匠协会工坊。"},{t="理念的冲突",b="格雷苏的机械臂体现了侏儒与地精工程学之间的鲜明分歧。他切除衰败的血肉，为复杂的义肢腾出空间，这种选择让地精难以理解。在菲兹克斯看来，地精的聪明才智会让他们保留原有的手臂，再在旁边装上一条能引发爆炸的第三只手臂。"}},faq={{q="格雷苏是谁？",a="格雷苏是石爪山脉的一名叛变的侏儒监工。他用齿轮和机械肢体替换腐烂的身体部位，在峭壁湖上方高处监督作业。",al={"格雷苏","格雷苏是谁","格雷苏背景故事"}},{q="在哪里可以找到格雷苏？",a="格雷苏位于菲兹克斯的东北方，在峭壁湖上方高处的一座大型工业水车附近。",al={"格雷苏位置","寻找格雷苏","格雷苏在哪里"}},{q="菲兹克斯为什么想杀死格雷苏？",a="斯布特瓦夫命令菲兹克斯除掉格雷苏。菲兹克斯希望证明自己的能力，从而获准调往加基森或安德麦的一间工匠协会工坊。",al={"为什么杀格雷苏","菲兹克斯的动机","菲兹克斯的目标"}},{q="菲兹克斯需要什么证明？",a="菲兹克斯想要格雷苏的机械臂，以此证明这名监工已经死亡。",al={"什么证明","格雷苏的死亡证明","任务目标物品"}},{q="格雷苏为什么有一部分身体是机械？",a="格雷苏的血肉正在腐烂，于是他将齿轮、铁板和机械肢体移植到身上，维持生命并强化自身。",al={"格雷苏为什么是半机械人","格雷苏机器人","格雷苏的身体"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是一名地精主管，在卡利姆多的其他地方监督作业，并指挥菲兹克斯这样的下属。",al={"斯布特瓦夫","斯布特瓦夫是谁"}}},fp="21,302,18.289.0,16.345.0,21.284.0,29.201.0,41.98.0,39.171.0,28.72.0,33.131.0,20.127.0"}
P.entries["quest:1097"] = {n="艾尔默的任务",s="铁匠阿古斯派你从闪金镇前往暴风城，格瑞曼德·艾尔默正等人帮忙运送一批货物。这位武器匠需要有人将货物送到卡兹莫丹的亲族手中，而阿古斯相信你能走好接下来的路。",h="铁匠阿古斯派你从闪金镇前往暴风城，格瑞曼德·艾尔默正等人帮忙运送一批货物。这位武器匠需要有人将货物送到卡兹莫丹的亲族手中，而阿古斯相信你能走好接下来的路。",kw={"铁匠","送货","矮人区","艾尔默","闪金镇","格瑞曼德·艾尔默","铁匠阿古斯","暴风城"},ang={["faction:Alliance"]="身为联盟旅人，你帮助暴风城与卡兹莫丹的矮人氏族维系紧密的贸易往来与相互信任。",["profession:Blacksmithing"]="身为铁匠，你看到两位工匠因手艺而结缘：一位是闪金镇的铁匠阿古斯，另一位是暴风城的格瑞曼德·艾尔默。",["race:Dwarf"]="身为矮人，你或许能看出，人类铁匠如何尊重铁炉堡的工艺，并帮助将物资向北送往群山。"},sec={{t="来自熔炉的口信",b="铁匠阿古斯留意着值得信赖的旅人，好将对付野狼和狗头人之外的工作托付给他们。格瑞曼德·艾尔默从暴风城捎来口信，请人帮忙将一批货物送到卡兹莫丹的亲族手中。穿过城门，就能前去回应艾尔默的求助。"},{t="彼此的纽带",b="暴风城与铁炉堡依靠畅通的贸易和彼此的善意，维持两国的补给与团结。阿古斯说，艾尔文森林需要守卫，但对矮人的承诺也同样重要。在暴风城东北部，沿着矮人区的道路，你就能找到艾尔默的店铺。一段通往森林之外的旅程，就从那里开始。"}},faq={{q="艾尔默的任务任务由谁发布？",a="闪金镇的铁匠阿古斯派你去帮助格瑞曼德·艾尔默。",al={"哪里接 艾尔默的任务","谁发布 艾尔默的任务","艾尔默的任务发布者"}},{q="在哪里能找到格瑞曼德·艾尔默？",a="格瑞曼德·艾尔默在暴风城东北部矮人区的一家武器店里工作。",al={"格瑞曼德·艾尔默 位置","格瑞曼德·艾尔默 在哪里","暴风城寻找 艾尔默"}},{q="这项任务的目的是什么？",a="阿古斯派你去找艾尔默，他需要一位可靠的信使，将一批货物向北送往他的故乡。这段旅程将带你走出艾尔文，穿行于联盟的领土。",al={"为何派我去找 艾尔默","艾尔默的任务 目的","艾尔默 需要什么"}},{q="艾尔默的任务的后续任务是什么？",a="与格瑞曼德·艾尔默交谈即可完成这趟差事，并开启雷矛的包裹。你将受托把他的货物向北送往洛克莫丹。",al={"艾尔默的任务 下一任务","艾尔默的任务 后续","艾尔默的任务 之后的任务"}},{q="铁匠阿古斯为何关心送给矮人的货物？",a="阿古斯说，与卡兹莫丹的矮人保持紧密的贸易往来，有助于保卫暴风城并维持物资流通，即使艾尔文同样需要守卫。",al={"阿古斯 为何帮助矮人","铁匠阿古斯与矮人的联系"}},{q="必须是铁匠才能接受这项任务吗？",a="不必。任何准备前往暴风城的联盟旅人，无论是否懂得锻造，都可以运送这批货物。",al={"艾尔默的任务 是否仅限铁匠","艾尔默的任务是否需要锻造"}}},fx={["4799d1e0"]={q="铁匠阿古斯为什么派你去，而不亲自前往？",a="铁匠阿古斯必须守着闪金镇的熔炉，为艾尔文森林的守卫和旅人打造、修理装备。虽然他在当地也用得上更多帮手，但他看得出，你是个身强体健的旅人，足以承担往返艾尔文森林与暴风城的奔波。推荐一位冒险者，能让他帮助那位矮人同行，同时继续在闪金镇从事不可或缺的锻造工作。",al={"艾尔默的任务 为何派我","阿古斯 为何不亲自送去","铁匠阿古斯为何选我"}}},fp="13,201,21.237.0,18.297.0,35.75.0,34.83.0,33.161.0,33.138.0,51.140.0,50.114.0"}
P.entries["quest:1098"] = {n="影牙城堡里的亡灵哨兵",s="在影牙城堡，亡灵哨兵阿达曼特和文森特失踪了。高级执行官哈德瑞克派部落冒险者进入城堡，寻找这两名侦察密探。被遗忘者需要他们的情报，为进攻大法师阿鲁高及其麾下的狼群做好准备。",h="在影牙城堡，亡灵哨兵阿达曼特和文森特失踪了。高级执行官哈德瑞克派部落冒险者进入城堡，寻找这两名侦察密探。被遗忘者需要他们的情报，为进攻大法师阿鲁高及其麾下的狼群做好准备。",kw={"阿达曼特","阿鲁高","暗影之牙的亡灵哨兵","哈德瑞克","瑟伯切尔","影牙城堡","银松森林","文森特"},ang={["class:Rogue"]="亡灵哨兵的失踪表明，在敌人防御森严的阵线后方进行侦察充满风险。",["faction:Horde"]="当常规部队无法攻破阿鲁高那座被诅咒的要塞时，高级执行官哈德瑞克便依靠部落勇士支援被遗忘者的行动。",["race:Undead"]="对被遗忘者而言，从阿鲁高麾下的野兽手中夺回银松森林，是确保洛丹伦安全的关键。斥候的失踪表明了这场斗争的凶险。"},sec={{t="深入狼人巢穴",b="银松森林的争夺仍在继续，大法师阿鲁高麾下的狼人盘踞着影牙城堡。瑟伯切尔的被遗忘者试图打破他对南部边境的围困。高级执行官哈德瑞克派亡灵哨兵阿达曼特和文森特潜入要塞，查明其中的防御部署。数日过去，仍然杳无音信，哈德瑞克愈发急切地盼望着他们的报告。他派部落勇士进入要塞，寻找密探，挽救这次行动。"},{t="惨痛的发现",b="下层城墙揭示了这次潜入行动的代价。亡灵哨兵阿达曼特被囚禁于此，却仍然活着，并帮助打开了庭院大门。文森特惨遭杀害；他残破的尸体静静地躺在城堡内，他掌握的情报也遗失在黑暗的厅廊中。他的手指间仍紧攥着一件小饰物，这是这名为黑暗女王的征服大业献出生命的间谍留下的最后痕迹。"}},faq={{q="为什么要派亡灵哨兵前往影牙城堡？",a="高级执行官哈德瑞克下令潜入影牙城堡，搜集有关大法师阿鲁高麾下兵力和防御工事的战术情报，为被遗忘者出兵攻打城堡做好准备。",al={"为何派间谍前往 暗影之牙","哈德瑞克 任务目的","亡灵哨兵 在 暗影之牙 的目标"}},{q="亡灵哨兵阿达曼特和文森特是谁？",a="阿达曼特和文森特是被遗忘者的精锐特工兼先遣斥候。他们隶属于幽暗城负责间谍活动与暗杀的分支亡灵哨兵，奉命绘制影牙城堡的地图，并观察狼人守军的防御部署。",al={"阿达曼特 和 文森特 是谁","阿达曼特 和 文森特 的背景故事"}},{q="亡灵哨兵文森特遭遇了什么？",a="文森特尚未从影牙城堡传回消息。哈德瑞克需要有人进入要塞，查明他的遭遇。",al={"文森特 是否死亡","文森特 在哪里","文森特 的命运"}},{q="亡灵哨兵阿达曼特在城堡内起什么作用？",a="阿达曼特是奉命进入影牙城堡搜集情报后失踪的亡灵哨兵之一。他的处境会在搜寻过程中揭晓。",al={"阿达曼特 做什么","亡灵哨兵阿达曼特 的作用"}},{q="这项任务从哪里开始？",a="高级执行官哈德瑞克在银松森林的瑟伯切尔发布这项任务，他作为被遗忘者的军事指挥官驻守于此。",al={"在哪里接取 暗影之牙的亡灵哨兵","暗影之牙的亡灵哨兵 任务发布者"}},{q="被遗忘者的领袖为什么要肃清影牙城堡？",a="大法师阿鲁高从影牙城堡派出凶暴的狼群，肆虐银松森林各地。它们不断威胁着被遗忘者的领地、补给线以及洛丹伦的安全。",al={"为何进攻 暗影之牙","被遗忘者 与阿鲁高的恩怨"}}},fp="27,263,19.422.0,18.377.1,47.192.0,42.226.0,38.129.1,57.142.1,30.138.0,62.181.0"}
P.entries["quest:1099"] = {n="Goblins Win!",s="在千针石林，地精获胜时，地精优惠券就能派上用场。持有获胜票根的人会得到一个奖品箱。",h="在千针石林，地精获胜时，地精优惠券就能派上用场。持有获胜票根的人会得到一个奖品箱。",kw={"地精","地精奖品箱","赛票","千针石林"},sec={{t="地精优惠券",b="地精优惠券是地精获胜时生效的票根。保管好它，等结果揭晓，你就能得到一个地精奖品箱。侏儒赛票也有对应的比赛结果，代表参赛的另一方。"}},faq={{q="什么是地精优惠券？",a="这是千针石林竞赛中代表地精一方的票券。地精获胜时，它就能派上用场。",al={"赛票","什么是地精优惠券"}},{q="地精获胜后能得到什么？",a="地精获胜时，持有地精优惠券的人会得到一个地精奖品箱。",al={"地精奖品箱","地精获胜奖励"}},{q="如果获胜的是侏儒，会怎么样？",a="那时，派上用场的就是侏儒赛票。它对应的结果叫作侏儒获胜!，与这里的结果相对应。",al={"侏儒获胜","侏儒优惠券"}}},fp="12,141,17.165.0,31.128.0,37.86.0,39.111.0"}
P.entries["quest:11"] = {n="悬赏河爪豺狼人",s="在艾尔文西部，悬赏河爪豺狼人悬赏征求援手，对付威胁边境的豺狼人。瑞尼尔副队长在西泉要塞提供赏金，收取从林间和水边的河爪群落身上取来的彩绘臂章。",h="在艾尔文西部，悬赏河爪豺狼人悬赏征求援手，对付威胁边境的豺狼人。瑞尼尔副队长在西泉要塞提供赏金，收取从林间和水边的河爪群落身上取来的彩绘臂章。",kw={"悬赏","瑞尼尔副队长","艾尔文","豺狼人","彩色豺狼人臂章","河爪","石碑湖","西泉要塞"},ang={["faction:Alliance"]="作为联盟的一员，你通过接受边境悬赏提升自己在Stormwind Army中的声望，并协助保障穿越王国腹地的商路安全。",["race:Human"]="作为人类，你通过猎杀Riverpaws、支援疲于奔命的王国卫兵，协助保护艾尔文的边境。"},sec={{t="边境的威胁",b="西泉要塞守卫着艾尔文森林与西部荒野的边界。要塞兵力不足，难以遏制日益壮大的河爪势力。豺狼人在哨塔南面，以及更东边的石碑湖周围扎营。它们以这些营地为据点，威胁过往旅人和附近的农庄。"},{t="秩序的代价",b="瑞尼尔副队长抽调不出正规步兵清剿树林，因此悬赏征讨这些掠夺者。他要求交出被杀豺狼人的彩绘臂章，作为每次击杀的凭证。四处游历的冒险者和新兵受雇削减这个族群的数量，以免河爪豺狼人席卷西部边境。"}},faq={{q="在艾尔文森林的哪里可以找到河爪豺狼人？",a="河爪豺狼人聚集在艾尔文的两处地方。可以到西泉要塞南面靠近河岸的树林里，以及更东边的石碑湖周围寻找。",al={"豺狼人位置","豺狼人在哪里","河爪位置"}},{q="要塞为什么向冒险者求助，对付豺狼人？",a="西泉要塞人手不足，在艾尔文边境各处疲于应付。由于卫兵太少，无法兼顾巡逻和清剿树林，瑞尼尔副队长请独立行动的勇士猎杀豺狼人。",al={"瑞尼尔副队长为何需要帮助","要塞为何雇佣佣兵"}},{q="瑞尼尔副队长需要什么凭证？",a="瑞尼尔副队长需要八个彩色豺狼人臂章，作为豺狼人已被击杀的凭证。",al={"悬赏凭证","为瑞尼尔收集什么"}},{q="河爪豺狼人是什么？",a="河爪是一个凶残的部族，成员是形似鬣狗的人形生物，遍布人类领地的河谷和边境。它们袭击聚落、旅人和农田，抢夺食物与财物。",al={"河爪豺狼人是什么","河爪部族背景"}},{q="这个任务与艾尔文的其他威胁有关吗？",a="这项悬赏是西泉要塞简短警戒任务线的最后一环。瑞尼尔副队长和要塞驻军也在提防当地其他不法之徒的威胁，其中包括匪徒霍格。",al={"后续任务","河爪悬赏之后是什么"}},{q="谁为这些豺狼人支付赏金？",a="暴风城军队为这项悬赏提供支持并予以授权。这让当地驻军能够嘉奖和酬谢那些协助平定王国领地的人。",al={"谁出资悬赏","悬赏奖励来源"}}},fx={["139c22ee"]={q="为什么瑞尼尔副队长要剿灭豺狼人？",a="瑞尼尔副队长认为河爪豺狼人是一群粗野的入侵者，根本不该出现在艾尔文森林的边境。大群豺狼人盘踞在哨塔以南，以及石碑湖附近的东侧，直接威胁着西泉要塞的外围防线和周边居民。瑞尼尔想剿灭它们，遏止这场不断蔓延的侵袭，免得哨站彻底沦陷。",al={"为何剿灭豺狼人","瑞尼尔副队长的动机","瑞尼尔为何要杀河爪豺狼人"}}},fp="21,221,22.282.0,18.283.0,52.155.0,60.182.0,38.94.0,28.185.0,55.172.0,37.144.0"}
P.entries["quest:110"] = {n="昆虫研究",s="谢申克失踪后，高级勘探员菲兹杜瑟开始检查勘探设备，整理谢申克的私人物品，并请你前往加基森，向炼金师匹斯特苏格询问昆虫肢体的情况。",h="谢申克失踪后，高级勘探员菲兹杜瑟开始检查勘探设备，整理谢申克的私人物品，并请你前往加基森，向炼金师匹斯特苏格询问昆虫肢体的情况。",kw={"菲兹杜瑟","加基森","昆虫研究","匹斯特苏格","谢申克","塔纳利斯"},sec={{t="前往加基森询问",b="菲兹杜瑟打算花些时间检查谢申克的勘探设备和私人物品，并隐隐觉得这些虫子还会造成更多损失。你受托前往加基森拜访炼金师匹斯特苏格，了解勘探员送去的昆虫肢体是否已经处理完毕。如果已经处理好了，菲兹杜瑟希望你把它们带回来。"},{t="匹斯特苏格的发现",b="匹斯特苏格已经得出了结果，结果令人不安。最初的猜测认为有一股外来力量在控制这些虫子，如今看来确实如此。这意味着存在一股非常强大、充满恶意的未知力量。这些虫子已经变成了只知肆虐的生物，匹斯特苏格从未见过这样的情况。"}},faq={{q="是谁派你去向炼金师匹斯特苏格询问情况？",a="高级勘探员菲兹杜瑟，他正在检查谢申克的设备，整理谢申克的物品。",al={"任务给予者","谁提供昆虫研究","菲兹杜瑟的位置"}},{q="炼金师匹斯特苏格在哪里？",a="在加基森，你要去那里询问昆虫肢体的情况。",al={"匹斯特苏格在哪里","匹斯特苏格的位置","匹斯特苏格所在城镇"}},{q="这一步之前紧接着的是什么？",a="这一步接在谢申克的救赎之后。",al={"前置任务","先做哪个任务","上一步"}},{q="你受托去了解什么？",a="了解匹斯特苏格是否已经检查完勘探员送去的昆虫肢体。如果已经处理好了，就把它们带给菲兹杜瑟。",al={"匹斯特苏格有什么"}}},fp="20,181,23.331.0,21.273.1,46.110.0,38.86.0,36.58.0,30.153.0"}
P.entries["quest:1100"] = {n="亨里格·独眉的日记",s="亨里格·独眉的日记是一项联盟任务，找到千针石林升降梯底部一名矮人死者手中饱经风霜的书册即可触发。日记记载了他最后的旅程，并指引发现者将书册向西送给一位驻守菲拉斯边境的暗夜精灵德鲁伊。",h="亨里格·独眉的日记是一项联盟任务，找到千针石林升降梯底部一名矮人死者手中饱经风霜的书册即可触发。日记记载了他最后的旅程，并指引发现者将书册向西送给一位驻守菲拉斯边境的暗夜精灵德鲁伊。",kw={"法芬德尔","菲拉斯","升降梯","亨里格","日记","独眉","剃刀沼泽","萨兰纳尔","千针石林","维尔德"},ang={["class:Druid"]="萨兰纳尔的法芬德尔一直在监测当地生态系统的异常变化，因此独眉关于剃刀野猪人的笔记与塞纳里奥议会息息相关。",["faction:Alliance"]="塞拉摩与萨兰纳尔之间的哨站寥寥无几，找回独眉的日记，就能确保重要情报在失落于峡谷之前送达联盟的盟友手中。",["race:Dwarf"]="亨里格·独眉的死令人沉痛地想起，矮人探险者远离铁炉堡、深入卡利姆多荒野时，会面临怎样的危险。"},sec={{t="陨落的探险者",b="升降梯是一座连接贫瘠之地与千针石林谷底的巨型机械升降装置，亨里格·独眉的尸体就躺在其底部附近。他手中紧握着一本私人日记，详细记载了他穿越这片崎岖地域的旅程。他的遗体被遗弃在这片由半人马和牛头人占据的险恶荒漠中，无声地警告着孤身旅人：这片峡谷绝不会手下留情。"},{t="临终的请求",b="翻阅亨里格的日记，便能了解他原定的路线和最后的心愿。这位探险者不愿让自己的发现腐朽在峡谷中，希望这些记录能送到友善之人手里。沿着道路径直向西穿过千针石林，便能走出干涸的沟壑，抵达守卫菲拉斯边境的暗夜精灵哨站萨兰纳尔，德鲁伊法芬德尔正在那里等待这位旅人的消息。"},{t="探明沼泽",b="法芬德尔查阅独眉的笔记后，这位探险者的命运便与卡利姆多南部一个更大的威胁联系起来。亨里格的见闻将线索指向北方荆棘丛生的剃刀沼泽洞穴，揭示了一名危险的老妪正统领着居住其中的野猪人。"}},faq={{q="在哪里能找到亨里格·独眉的尸体？",a="他的尸体位于千针石林的升降梯脚下。从西侧升降梯坡道底部向前走大约二十五英尺，来到一处低矮的岩石台地，他的尸体就躺在那里，手中握着日记。",al={"亨里格·独眉位置","亨里格·独眉的日记在哪里","独眉尸体","寻找独眉"}},{q="日记要交给谁？",a="将日记交给驻守萨兰纳尔的暗夜精灵德鲁伊法芬德尔。萨兰纳尔位于向西延伸的主干道旁，就在千针石林与菲拉斯的交界处。",al={"亨里格·独眉的日记交给谁","独眉任务在哪里交","独眉任务交付","法芬德尔位置"}},{q="亨里格·独眉是谁？",a="亨里格·独眉是一名在卡利姆多中部旅行的矮人。他死于升降梯底部附近，留下一本饱经风霜的日记，详细记载了他对周边地域的观察，以及危险的野猪人的动向。",al={"亨里格·独眉是谁","独眉背景故事","独眉是谁"}},{q="这个任务会开启什么后续任务？",a="将日记交给法芬德尔后，会解锁任务“卡尔加·刺肋”，指引联盟冒险者进入剃刀沼泽地下城。",al={"独眉后续任务","亨里格·独眉的日记后续任务","独眉任务链"}},{q="部落玩家能拾取这本日记吗？",a="不能。这本日记及其后续任务链仅限联盟玩家，直接通往位于萨兰纳尔的联盟边境哨站。",al={"亨里格·独眉的日记是否仅限联盟","部落能否做亨里格·独眉的日记","部落独眉"}},{q="独眉为什么要前往萨兰纳尔？",a="萨兰纳尔是这一带最近的联盟哨站，为往来于千针石林和菲拉斯荒野之间的人提供庇护。独眉原本打算将自己对这片地域的观察分享给驻守那里的暗夜精灵。",al={"为什么去萨兰纳尔","为什么把书交给德鲁伊","独眉的目的"}}},fx={["0173d93a"]={q="为什么日记要求把它送到萨兰纳尔？",a="亨里格·孤眉知道自己的旅程将在升降梯下方以悲剧告终。他在泛黄的书页中留下最后的愿望：将自己的发现送到萨兰纳尔边境哨站的法芬德尔手中。把日记送达，就能确保无论是什么重要情报或发现让这名矮人丧命，都不会湮没在千针石林的沙海中。",al={"为何送日记","日记的用途","亨里格·孤眉日记的缘由"}}},fp="18,213,17.315.0,15.353.0,20.231.1,39.222.0,32.177.0,24.211.0,29.140.1,38.136.0,42.231.0"}
P.entries["quest:1101"] = {n="卡尔加·刺肋",s="在菲拉斯与千针石林交界处的萨兰纳尔，法芬德尔派遣冒险者前去对付卡尔加·刺肋。寻回的亨里格·独眉的日记揭示了剃刀沼泽内部日益加剧的危险。",h="在菲拉斯与千针石林交界处的萨兰纳尔，法芬德尔派遣冒险者前去对付卡尔加·刺肋。寻回的亨里格·独眉的日记揭示了剃刀沼泽内部日益加剧的危险。",kw={"阿迦玛甘","卡尔加·刺肋","老妪","法芬德尔","独眉","徽章","剃刀沼泽","萨兰纳尔"},ang={["class:Druid"]="身为德鲁伊，你敬重阿迦玛甘这位备受尊崇的自然荒野之神，并力求净化那股扭曲他荆棘遗泽的黑暗污秽。",["faction:Alliance"]="这是联盟从萨兰纳尔发起、对抗南贫瘠之地野猪人威胁的主要行动。",["race:Dwarf"]="为探险者亨里格·独眉复仇，让矮人有了攻入野猪人要塞的切身理由。",["race:NightElf"]="暗夜精灵为阿迦玛甘安息之地遭到亵渎而悲痛。这位野猪形态的荒野之神曾是暗夜精灵的盟友，在War of the Ancients期间陨落。"},sec={{t="边境的求援",b="在偏僻的暗夜精灵哨站萨兰纳尔，法芬德尔为德鲁伊赫尔拉斯和矮人亨里格·独眉的死而悲痛。独眉被野猪人俘虏前，曾与探险者协会一同行动。他逃出了剃刀沼泽，却死在路上，留下一本破旧的日记，记述了里面日益加剧的威胁。已经来不及派信使前往达纳苏斯请求军队增援。法芬德尔派遣路过的冒险者深入荆棘密布的巢穴，直面深处的危险。"},{t="直取酋长",b="卡尔加·刺肋是一位年迈的地卜师，也是冷酷无情的女族长，她以铁腕统治，将四分五裂的剃刀野猪人统一起来。她在剃刀沼泽深处集结了一支兵力强盛的大军，威胁着邻近的土地。茂密的荆棘迷宫、设有垛口的高墙和成群狂热的野猪人战士，守卫着通往卡尔加的道路。从她尸体上取下的徽章，将成为她败亡的凭证。"},{t="更深的腐化",b="卡尔加之死削弱了野猪人眼下的威胁，却让暗夜精灵有了更深的忧虑。野猪形态的荒野之神阿迦玛甘在上古之战期间陨落，剃刀沼泽那些活着的荆棘便从他的陨落之地生长出来。法芬德尔收到徽章时提到，除掉卡尔加后，暗夜精灵学者就能更深入地研究这一带的腐化。他察觉到，席卷阿迦玛甘神圣遗骸的突发枯萎，其根源可能隐藏着险恶的阴谋。"}},faq={{q="谁提供卡尔加·刺肋任务？",a="任务由驻守萨兰纳尔的暗夜精灵法芬德尔提供。萨兰纳尔是位于菲拉斯与千针石林之间高山隘口上的联盟哨站。",al={"卡尔加·刺肋任务提供者","卡尔加·刺肋领取地点","法芬德尔任务"}},{q="开始这个任务前，必须完成什么前置任务？",a="首先，你必须完成亨里格·独眉的日记。在千针石林升降梯附近，从亨里格·独眉的遗体上取回日记，然后交给萨兰纳尔的法芬德尔。",al={"卡尔加·刺肋前置任务","卡尔加·刺肋解锁方法","亨里格·独眉的日记前置任务"}},{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋是剃刀野猪人的最高女巫和女族长。作为一名强大的地卜师，她统一了剃刀沼泽内相互征战的部族，并指挥他们侵略邻近的领地。",al={"老妪是谁","卡尔加背景故事","卡尔加·刺肋"}},{q="在哪里能找到卡尔加·刺肋？",a="卡尔加·刺肋位于剃刀沼泽的最深处，这座地下城坐落在贫瘠之地最南端、靠近升降梯的地方。她就在地下城深处的一座祭坛上。",al={"卡尔加在哪里","卡尔加位置","剃刀沼泽老妪位置"}},{q="法芬德尔为什么需要冒险者，而不召集达纳苏斯的军队？",a="萨兰纳尔是一座偏远的边境哨站，远离卡利姆多北部。卡尔加正在积极集结兵力，向达纳苏斯传信，再等派出的军队赶来，已经来不及阻止日益加剧的危险。",al={"为何不向达纳苏斯求援","为何雇用冒险者"}},{q="法芬德尔要求用什么证明老妪已死？",a="法芬德尔要求带回卡尔加·刺肋的徽章，也就是卡尔加佩戴的护符，以此证明她已被杀死。",al={"掉落什么物品","死亡证明物品","卡尔加·刺肋的徽章"}}},fp="22,197,20.484.0,22.401.0,19.452.1,43.167.0,63.178.0,26.219.0,38.171.0,74.215.0,54.102.0"}
P.entries["quest:1103"] = {n="水之召唤",s="在银松森林的海岸边，提夫·摩杜恩正等候着，帮助那些灵视过早消退的萨满祭司。一份新的水之灵契能让他们重返神殿，与净化后的水之灵交谈。",h="在银松森林的海岸边，提夫·摩杜恩正等候着，帮助那些灵视过早消退的萨满祭司。一份新的水之灵契能让他们重返神殿，与净化后的水之灵交谈。",kw={"水之召唤","水之先知伊斯伦","水之魂","萨满祭司","银松森林","提夫·摩杜恩","水之灵契"},ang={["class:Shaman"]="身为萨满祭司，你要走过一段艰辛的道路，才能获得水之图腾。这项仪式展现了萨满祭司之间的互助，让每一位初学者都不至于因恍惚状态消退而掉队。",["faction:Horde"]="身为部落的一员，即使身处洛丹伦阴魂不散的土地，你也遵循着萨满祭司互相扶助、敬重自然之灵的传统。"},sec={{t="迷雾中的援“手”",b="萨满祭司饮下水之灵契，便能看见元素神殿附近的灵体。如果药效在他们与水之魂交谈之前消退，他们就无法再进入灵魂世界，完成试炼。在银松森林雾气笼罩的海岸上，同为萨满祭司的提夫·摩杜恩会帮助那些灵视过早消退的人。"},{t="重启仪式",b="提夫·摩杜恩已经击败了近海的堕落水之灵，正带着收集到的仪式遗物等候。要证明你已准备就绪，就从贫瘠之地的水之先知伊斯伦那里带来一份新的水之灵契。提夫·摩杜恩将收集到的护腕和水滴投入神殿的火盆。纯净的化身便会再次显现，让你能与它交谈，缔结与水元素的纽带。"}},faq={{q="提夫·摩杜恩是谁？",a="提夫·摩杜恩是银松森林海岸上的一位部落萨满祭司。他已经击败了那里的堕落水之灵，如今仍留在岸边，帮助那些尚未完成沟通、灵视便已消退的萨满祭司。",al={"提夫·摩杜恩","提夫是谁","提夫 银松森林"}},{q="为什么这个任务需要水之灵契？",a="水之灵契能让你的心神进入灵魂世界。提夫·摩杜恩需要一份水之先知伊斯伦提供的新药剂，这样当他再次召唤水元素时，你就能看见它。",al={"为何需要灵契","水之灵契 泰夫","哪里获取灵契"}},{q="如果错过了与水之灵交谈的机会，会怎样？",a="如果水之灵契的药效消退，或水之魂在你与它交谈之前消失，你就无法独自完成试炼。提夫·摩杜恩会用收集到的战利品重新点燃火盆，让你能与水之灵交流。",al={"错过水之灵","水之魂试炼失败","水之魂消失"}},{q="仪式在哪里举行？",a="试炼在银松森林西海岸举行，地点是一座面朝无尽之海的元素圣坛旁。",al={"水元素圣坛在哪","银松森林水元素圣坛位置"}},{q="是谁指引萨满祭司踏上这段朝圣之旅？",a="水之先知伊斯伦是一位牛头人萨满祭司，她指引初学者完成水之召唤的各项试炼，并调制所需的药剂。她住在贫瘠之地东海岸的一间渔屋旁。",al={"谁给予水之召唤","伊斯伦·水眼"}},{q="水之魂是什么？",a="水之魂是净化后的元素之灵，当地水域的腐化清除后，便可在圣坛将它召唤出来。与它沟通，就能完成萨满祭司元素试炼中的这一部分。",al={"水之灵是什么","水之魂"}}},fp="13,195,26.319.0,19.370.0,20.210.0,43.160.0,54.232.0,34.104.0,36.172.0,41.216.0"}
P.entries["quest:1104"] = {n="含盐的蝎毒",s="在闪光平原刺眼的辽阔盐滩上，侏儒工程师菲兹尔·铜栓正在寻找奇特的原料，为他的火箭赛车增强动力。他坚信，当地蝎子含盐量极高的毒液能够制成燃烧温度极高的推进剂，于是委托路过的冒险者去对付这些会蜇人的野兽。",h="在闪光平原刺眼的辽阔盐滩上，侏儒工程师菲兹尔·铜栓正在寻找奇特的原料，为他的火箭赛车增强动力。他坚信，当地蝎子含盐量极高的毒液能够制成燃烧温度极高的推进剂，于是委托路过的冒险者去对付这些会蜇人的野兽。",kw={"菲兹尔·铜栓","燃料","沙漠赛道","火箭赛车","含盐的蝎毒","闪光平原","千针石林"},ang={["profession:Engineering"]="使用skipper-otomers之类的催化剂处理有机毒素，体现了竞速载具工程中那些富有创意却又危险易爆的常见实验。",["race:Gnome"]="菲兹尔体现了典型的侏儒雄心：不停地修修改改、令人担忧的化学操作安全、放错地方的笔记，以及始终想要胜过地精机械师的冲劲。"},sec={{t="易爆的配方",b="沙漠赛道上，侏儒的精密技术与地精的大胆创意不断交锋，争夺高速竞赛的技术优势。对菲兹尔·铜栓来说，常规的碳氢燃料和发条零件根本不足以超越对手。他设想调配一种专用燃料，让它的燃烧温度远超常规推进剂，驱动他们的火箭赛车以惊人的速度冲过干涸的盐湖。"},{t="盐滩上的高盐毒液",b="菲兹尔的突破寄托在闪光平原危险的本土动物身上。当地的蝎子演化出了适应干旱盐碱荒地的能力，毒液的含盐量也因此异常之高。菲兹尔并不畏惧这种毒液的致命毒性，而是把它视为一种化学原料。他相信，经过熬煮、提炼，再用奇特的催化剂处理后，这种高盐毒液就能产生猛烈的爆燃，把地精维修组远远甩在身后。"}},faq={{q="菲兹尔·铜栓为什么需要蝎子毒液？",a="菲兹尔正在研制一种燃烧温度极高的新型火箭赛车燃料。他认为，闪光平原本土蝎子的毒液含盐量异常之高，其中的盐正是完成这种爆炸性混合物所需的关键化学成分。",al={"为什么需要蝎子毒液","毒液有什么用","菲兹尔燃料配方"}},{q="在哪里能找到所需的蝎子？",a="蝎子遍布闪光平原的开阔地带，尤其常在西部盐滩，以及远离中央赛道的沙地上游荡。",al={"蝎子位置","蝎子在哪里","盐滩毒液怪物"}},{q="毒液收集齐后，菲兹尔会怎么处理？",a="菲兹尔打算先把毒液熬浓，用高速分离器处理，再混入负催化剂，制成高辛烷值的火箭推进剂——前提是他能找到被自己放错地方的笔记。",al={"毒液如何变成燃料","燃料制作过程"}},{q="联盟和部落的成员都能帮助菲兹尔吗？",a="是的。侏儒与地精依照中立停战协议共同管理沙漠赛道，因此双方阵营的冒险者都能协助维修组，不受政治因素干扰。",al={"这个任务是否中立","部落还是联盟"}},{q="侏儒和地精为什么要在千针石林赛车？",a="闪光平原拥有辽阔、平整且毫无遮挡的坚硬盐层，是测试实验性高速火箭赛车和直线加速赛车的理想场地。",al={"赛道为何建在这里","为什么选择沙漠赛道"}},{q="这种燃料真的能让赛车飞起来吗？",a="虽然菲兹尔兴奋地宣称赛车会“飞起来”，但盐滩上的侏儒火箭赛车原本是为了贴地疾驰而设计的，当然，灾难性的腾空和撞车事故也随时可能发生。",al={"赛车能飞吗","菲兹尔火箭赛车结果"}}},fp="15,168,17.294.0,30.392.0,46.191.0,42.119.0,50.151.0,55.162.0,54.178.0,40.189.0"}
P.entries["quest:1105"] = {n="硬化龟壳",s="在闪光平原的沙漠赛道，侏儒工匠维兹尔·铜栓担心，兄弟新研制的强效火箭燃料会从内部溶穿他们的赛车。为了避免盐滩上发生灾难，维兹尔请路人收集当地陆龟的硬壳，用来制作不会被腐蚀的燃料箱。",h="在闪光平原的沙漠赛道，侏儒工匠维兹尔·铜栓担心，兄弟新研制的强效火箭燃料会从内部溶穿他们的赛车。为了避免盐滩上发生灾难，维兹尔请路人收集当地陆龟的硬壳，用来制作不会被腐蚀的燃料箱。",kw={"硬化龟壳","沙漠赛道","火箭赛车","闪光平原","千针石林","陆龟","维兹尔·铜栓"},ang={["profession:Engineering"]="用生物甲壳来盛装不稳定的化合物，是一种不同寻常的做法，凸显了侏儒工匠在压力下依赖的古怪试错方式。",["race:Gnome"]="兄弟间的巧思与不计后果的科学野心在此正面碰撞，展现出侏儒无论遇到怎样的实际困难，都要在创新上超越地精对手的执着。"},sec={{t="不稳定的新发明",b="在闪光平原刺眼的烈日下，侏儒与地精工程师之间的竞争，将机械技术的野心推向了不计后果的极端。维兹尔·铜栓和他的兄弟决心驾驶自行打造的火箭赛车，称霸沙漠赛道。然而，种种迹象表明，他兄弟调配的试验性燃料似乎效力过强。维兹尔担心这种腐蚀性混合物会直接熔穿赛车的普通底盘和燃料箱，急忙寻找足够坚固、能撑完整场比赛的容器。"},{t="沙漠中的天然护甲",b="精炼金属也可能经不住化学腐蚀而溶解，于是维兹尔将目光转向盐滩生物适应环境的天然本领。漫步于千针石林的本地陆龟，龟壳抵御恶劣环境和机械磨损的能力十分出众。维兹尔希望收集这些坚硬的甲壳，制成足够耐用的专用燃料箱，装住不稳定的混合燃料，免得火箭赛车被炸成碎片。"}},faq={{q="维兹尔为什么需要龟壳，而不用金属？",a="他的兄弟正在调配一种试验性火箭燃料，腐蚀性强到足以溶解金属。维兹尔相信，当地陆龟天然形成的超硬龟壳，比普通燃料箱更能抵抗化学腐蚀。",al={"为什么用龟壳","为什么用陆龟壳","燃料箱龟壳"}},{q="维兹尔·铜栓是谁？",a="维兹尔是一名驻扎在闪光平原沙漠赛道的侏儒工程师。他和兄弟一起制造并精心调校他们的高速火箭赛车，力求在竞速中击败地精对手。",al={"维兹尔","维兹尔是谁"}},{q="在哪里可以找到陆龟？",a="陆龟在闪光平原辽阔的盐滩上四处游荡，东北部的旧沉船附近尤其密集，许多陆龟聚在那里晒太阳。",al={"陆龟位置","乌龟在哪里","哪里获取硬壳"}},{q="这是联盟任务还是部落任务？",a="这是一个完全中立的任务。沙漠赛道置身于阵营战事之外，专注于工程竞赛，联盟和部落的冒险者都可以帮助维兹尔。",al={"硬化龟壳是否中立","联盟还是部落"}},{q="交付龟壳之后会发生什么？",a="维兹尔迫不及待地开始将龟壳加工成加固燃料箱，却很快发现，这些龟壳实在太坚硬，光是切削成形恐怕就要毁掉整整一箱工具。",al={"维兹尔龟壳结果","维兹尔用龟壳做什么"}},{q="为什么盐滩上的燃料箱故障如此令人担忧？",a="火箭赛车在盐滩上以惊人的速度飞驰。维兹尔担心兄弟的新燃料效力太强，会直接蚀穿赛车底盘，因此想在那之前先加固燃料箱。",al={"火箭赛车危险","为什么担心燃料"}}},fx={["201b3417"]={q="维兹尔·铜栓为什么想让你完成这件事？",a="维兹尔的兄弟正在沙漠赛道设计一种极不稳定的新燃料，用于他们的火箭车。维兹尔虽然钦佩兄弟的才华，却担心这种混合物腐蚀性太强，会在测试时直接熔穿车子现有的底盘。为了避免盐碱滩上发生灾难，维兹尔需要在兄弟完成配方前打造更坚固的替换燃料箱。",al={"维兹尔的动机","为什么帮维兹尔","维兹尔为什么要龟壳"}},["5a3ddfa8"]={q="闪光平原的陆龟是什么？",a="火壳龟在烈日炙烤的闪光平原上四处游荡。经过数代在这片严酷干旱盆地中的生存，它们的甲壳变得格外坚硬而坚韧。它们通常独自在盐壳间活动，因此成了侏儒工匠急需的天然耐用材料，可用来制作不易起反应、耐热的护板。",al={"盐碱滩陆龟","闪光平原陆龟","这里为什么有陆龟"}}},fp="15,143,20.346.0,24.315.0,54.174.0,25.172.0,33.108.0,35.139.0,43.146.1,53.177.0"}
P.entries["quest:1106"] = {n="流放者马特克",s="菲兹尔·铜栓正在为他的赛车打造一台新引擎，但他造出的活塞不够坚硬，承受不住压力。他让你带上一封信，去找一位名叫流放者马特克的锻造大师，此人远在荒芜之地的一处营地里。",h="菲兹尔·铜栓正在为他的赛车打造一台新引擎，但他造出的活塞不够坚硬，承受不住压力。他让你带上一封信，去找一位名叫流放者马特克的锻造大师，此人远在荒芜之地的一处营地里。",kw={"荒芜之地","菲兹尔·铜栓","加塞尔佐格","流放者马特克","沙漠赛道","活塞","千针石林"},sec={{t="给铁匠的信",b="完成含盐的蝎毒后，沙漠赛道的菲兹尔解释说，他的新引擎应该能让赛车快得飞起来。他的所有试验都失败了，因为他造出的活塞不够坚硬，承受不住巨大的压力。他知道有一个人也许有办法：流放者马特克，一位比任何人都了解金属的锻造大师。马特克远在荒芜之地，和一个地精一起扎营，你要把菲兹尔的信带给他。"},{t="营地之中",b="你找到营地时，马特克的态度并不友善。马特克问你是为了给加塞尔佐格打造的那把斧头而来，还是来挽回帕玛女公爵的名誉，并说如果你想打架，现在就可以动手。"},{t="马特克的答复",b="得知你是菲兹尔派来的，情况就完全不同了。马特克说，菲兹尔和他的兄弟是少数几个不想要他命的人，并答应帮忙打造足够结实的活塞，承受菲兹尔计划中的任何压力，因为在马特克听来，那辆新赛车简直就是一座装了轮子的火山。"}},faq={{q="菲兹尔·铜栓为什么需要马特克的帮助？",a="菲兹尔的新引擎应该能让赛车快得飞起来，但每次试验都失败了，因为他造出的活塞不够坚硬，承受不住压力。马特克是一位锻造大师，比任何人都了解金属。",al={"为什么拜访马特克","菲兹尔·铜栓的活塞问题","为什么找流放者马特克"}},{q="流放者马特克在哪里？",a="在荒芜之地的一处营地里，还有一个地精也住在那里。",al={"马特克在哪里","流放者马特克的位置","如何找到马特克"}},{q="这趟旅程之前是什么任务？",a="含盐的蝎毒，是任务链中它的前一个任务。后续任务是精铁矿石。",al={"流放者马特克的前置任务","流放者马特克之前是什么任务"}}},fp="17,198,22.364.0,11.206.1,14.268.1,46.214.0,35.47.0,30.80.0"}
P.entries["quest:1107"] = {n="坚硬的尾鳍",s="沙漠赛道的维兹尔·铜栓担心火箭赛车速度太快，摩擦会将它撕裂。为了保护赛车，他需要荆棘谷海岸外暗礁海中盐鳞鱼人的尾鳍。",h="沙漠赛道的维兹尔·铜栓担心火箭赛车速度太快，摩擦会将它撕裂。为了保护赛车，他需要荆棘谷海岸外暗礁海中盐鳞鱼人的尾鳍。",kw={"硬化尾鳍","沙漠赛道","火箭赛车","盐鳞鱼人","闪光平原","荆棘谷","暗礁海","维兹尔·铜栓"},sec={{t="赛车的涂层",b="维兹尔说，火箭赛车是闪光平原上速度最快的东西，他担心摩擦会将它撕裂。活动部件需要涂上一层坚硬却不脆、还能抵抗盐分腐蚀的复合材料，否则盐碱地会把赛车腐蚀殆尽。这种材料的关键原料是盐鳞鱼人的尾鳍，这些鱼人生活在荆棘谷海岸外的暗礁海。你需要给维兹尔带回十片尾鳍。"},{t="制成的复合材料",b="维兹尔会把你带来的尾鳍磨成粉末，再加入其他几种原料，制成的复合材料应该能保护赛车，让它免受自身高速的损害。维兹尔补充说，前提是赛车没有撞上任何东西。"}},faq={{q="维兹尔·铜栓为什么需要坚硬的尾鳍？",a="火箭赛车速度太快，维兹尔担心摩擦会将它撕裂。尾鳍是制作复合材料的关键原料，这种材料用于涂覆活动部件，坚硬却不脆，还能抵抗盐分腐蚀。",al={"为什么需要尾鳍","维兹尔尾鳍用途","为什么需要鱼人尾鳍"}},{q="在哪里能找到盐鳞鱼人？",a="在荆棘谷海岸外的暗礁海，几乎就在格罗姆高营地的正西方。",al={"暗礁海位置","盐鳞鱼人在哪里","哪里能找到硬化尾鳍"}},{q="维兹尔在这之前交付的是什么任务？",a="这条任务链中的前一个任务是硬化龟壳。",al={"先做哪个任务","维兹尔任务链前一个任务","硬化尾鳍前置任务"}},{q="维兹尔·铜栓是谁？",a="维兹尔·铜栓就在沙漠赛道，他担心火箭赛车的安危，也是请你收集尾鳍的人。",al={"维兹尔是谁","谁提供硬化尾鳍任务"}}},fp="19,176,21.351.0,22.180.1,52.199.0,41.119.0,33.62.0,25.132.0"}
P.entries["quest:1108"] = {n="精铁碎片",s="流放者马特克说，荒芜之地蕴藏着丰富的金属，只要有胆量，就能去取。据说indurium耐得住高温和重压，马特克想要些样本，测试它能否用于菲兹尔的赛车。荒芜之地的石窟穴居人身上就带着这种金属的碎片。",h="流放者马特克说，荒芜之地蕴藏着丰富的金属，只要有胆量，就能去取。据说indurium耐得住高温和重压，马特克想要些样本，测试它能否用于菲兹尔的赛车。荒芜之地的石窟穴居人身上就带着这种金属的碎片。",kw={"埃格蒙德的营地","荒芜之地","菲兹尔·铜栓","精铁","精铁碎片","流放者马特克","沙漠赛道","石窟穴居人","奥达曼"},sec={{t="值得一试的金属",b="流放者马特克告诉你，他待在荒芜之地，并不只是为了避开人群。这里蕴藏着indurium，据说这种金属耐得住高温和重压，或许能用于菲兹尔的赛车。马特克想要些样本来测试，熔炉已经烧热，就等着样本送来了。"},{t="穴居人身上的碎片",b="真正的矿石藏在奥达曼深处，不过荒芜之地的石窟穴居人偶尔也会带着一些碎片。马特克要十块。带着碎片的穴居人在埃格蒙德的营地一处岩石堆的东南坡游荡，就在巨牙谷南边。"},{t="熔炉试验",b="马特克把碎片放进熔炉，逐步升高温度。碎片经受住了考验，马特克以奥格瑞姆的名义起誓，这种indurium能耐受极高的温度。试验成功了，马特克称赞这种金属是了不起的好东西。"}},faq={{q="是谁派你去寻找精铁的？",a="身处荒芜之地中部的流放者马特克要你收集样本。通往他这里的任务线，始于千针石林沙漠赛道的菲兹尔·铜栓。",al={"谁提供精铁任务","哪里获取精铁"}},{q="马特克为什么需要精铁？",a="据说这种金属耐得住高温和重压，马特克认为它或许能用于菲兹尔的赛车，因此想要些样本，放进熔炉里试一试。",al={"精铁有什么用途","为什么需要精铁"}},{q="在哪里能找到精铁碎片？",a="荒芜之地的石窟穴居人偶尔会带着这些碎片，它们就在埃格蒙德的营地一处岩石堆的东南坡，位于巨牙谷南边。",al={"精铁碎片在哪里","如何获取碎片","谁掉落精铁碎片"}},{q="真正的精铁矿石来自哪里？",a="马特克说，真正的矿石藏在奥达曼深处。",al={"精铁矿石在哪里","哪里开采精铁"}},{q="前一个任务是什么？",a="前一个任务是流放者马特克，这是这条任务线的第一步，起点是沙漠赛道的菲兹尔·铜栓。",al={"精铁前置任务","如何开始精铁任务"}},{q="交付碎片之后是什么任务？",a="这条任务线接下来是回复菲兹尔。",al={"精铁后续任务","接下来会发生什么"}}},fp="8,162,21.203.0,22.228.0,14.204.1,33.160.0,30.131.0,39.166.0,39.51.0,23.102.0,42.41.0"}
P.entries["quest:1109"] = {n="蝙蝠的粪便",s="大药剂师法拉尼尔正在寻找剃刀沼泽中沼泽蝙蝠的粪便。皇家药剂师学会需要用它进行实验。",h="大药剂师法拉尼尔正在寻找剃刀沼泽中沼泽蝙蝠的粪便。皇家药剂师学会需要用它进行实验。",kw={"going going guano","沼泽蝙蝠","沼泽蝙蝠的粪便","大药剂师法拉尼尔","剃刀沼泽","皇家药剂师学会","幽暗城"},sec={{t="稀有的物质",b="大药剂师法拉尼尔在幽暗城主管皇家药剂师学会的炼金工作。他需要沼泽蝙蝠的粪便，这是一种栖息在剃刀沼泽的稀有蝙蝠。你受托为他带回一堆粪便，好让学会开始工作。"}},faq={{q="谁需要沼泽蝙蝠的粪便？",a="皇家药剂师学会的大药剂师法拉尼尔需要用它开展学会的工作。",al={"谁需要粪便","法拉尼尔 粪便","药剂师"}},{q="沼泽蝙蝠栖息在哪里？",a="沼泽蝙蝠栖息在剃刀沼泽。",al={"沼泽蝙蝠位置","蝙蝠在哪里","蝙蝠粪便"}},{q="沼泽蝙蝠的粪便有什么用途？",a="法拉尼尔需要它，好让皇家药剂师学会开始炼金工作。",al={"为什么需要粪便","粪便有什么用","药剂师实验"}},{q="我要把粪便送到哪里？",a="把这堆沼泽蝙蝠的粪便交给幽暗城的大药剂师法拉尼尔。",al={"粪便送到哪里","交付粪便","法拉尼尔位置"}}},fp="20,136,16.243.0,22.93.0,25.39.0,24.80.0,27.77.0"}
P.entries["quest:111"] = {n="托米的祖母",s="托米·乔·斯通菲尔德向米莱德·斯通菲尔德求助，想找个办法与梅贝尔·马科伦见面。两家人不让他们来往，他希望能见到她，又不让双方亲人起冲突。",h="托米·乔·斯通菲尔德向米莱德·斯通菲尔德求助，想找个办法与梅贝尔·马科伦见面。两家人不让他们来往，他希望能见到她，又不让双方亲人起冲突。",kw={"艾尔文森林","米莱德·斯通菲尔德","马科伦农场","梅贝尔·马科伦","与奶奶交谈","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻的恋人"},ang={["faction:Alliance"]="暴风城正面临迪菲亚引发的动乱和野兽的袭击，而你也可能要出面调解相邻农户之间的争吵。",["race:Human"]="身为艾尔文的一名人类，你会看到，即使整个王国麻烦不断，暴风城腹地的乡间积怨依然根深蒂固。"},sec={{t="世仇与禁忌之恋",b="托米·乔和梅贝尔向家人隐瞒着彼此的恋情。他向米莱德·斯通菲尔德求助，希望她能为他们找到秘密见面的机会。他们不能让亲人发现这段恋情，以免旧怨演变成流血冲突。"},{t="奶奶的妙计",b="米莱德·斯通菲尔德知道，只要积怨未消，两家人就无法真正和好。不过，她不会就此断送这对年轻恋人的希望。她开始寻找机会，让托米·乔和梅贝尔能够相聚。"}},faq={{q="托米·乔为什么要我去和他的奶奶谈谈？",a="托米·乔爱着梅贝尔·马科伦，但两家的世仇让他们无法相聚。他希望奶奶能安排他们秘密见面，又不闹出风波。",al={"为什么找奶奶","托米·乔的奶奶","与奶奶交谈的目的"}},{q="在哪里能找到米莱德·斯通菲尔德？",a="米莱德·斯通菲尔德待在斯通菲尔德农场的主屋里，就在闪金镇以南、托米·乔藏身的河岸以东。",al={"米莱德·斯通菲尔德的位置","奶奶在哪里","寻找米莱德·斯通菲尔德"}},{q="斯通菲尔德家族和马科伦家族之间有什么仇怨？",a="这两户相邻的农家因私怨和土地争端结下了长久的仇恨。他们互相指责对方偷窃，还为庄稼争斗不休，彼此的不信任让两家人随时可能大打出手。两家的孩子若有来往，都必须瞒着家人。",al={"斯通菲尔德与马科伦的世仇","他们为何争斗","艾尔文的家族世仇"}},{q="米莱德·斯通菲尔德反对托米·乔的恋情吗？",a="不反对。奶奶知道，两家的世仇让这段恋情难以长久，但她关心这对年轻恋人，会想办法让他们见面。",al={"奶奶是否反对梅贝尔","奶奶是否支持恋人"}},{q="和奶奶谈过之后会发生什么？",a="奶奶开始筹划，让托米·乔和梅贝尔秘密相聚。她让你去收集调制隐形水所需的材料，好让他们避开家人警惕的目光。",al={"与奶奶交谈之后","奶奶任务的后续"}},{q="梅贝尔·马科伦是谁？",a="梅贝尔·马科伦是仇家之女，与斯通菲尔德一家隔路而居。她正与托米·乔·斯通菲尔德秘密相恋。",al={"梅贝尔是谁","梅贝尔·马科伦"}}},fx={ba5df8a9={q="托米·乔 为什么需要一个外人去和祖母说话？",a="托米·乔 躲在斯通菲尔德农场附近的河岸上，准备与梅贝尔·马科伦秘密幽会。如果他亲自返回家中的农舍，就可能让这段不被允许的恋情引起注意，尤其是两个世仇家族之间的关系正十分紧张。你只是个路过的旅人，可以悄悄接近米莱德·斯通菲尔德，而不惊动家里的其他人。",al={"托米·乔 为何选我","为何派玩家去找 老奶奶","托米 为何不能和 老奶奶 说话"}}},fp="17,177,25.220.0,16.219.0,52.156.0,37.129.0,58.231.0,55.133.0,38.176.1,23.144.0"}
P.entries["quest:1110"] = {n="火箭车零件",s="火箭车零件是投机逐利的矮人商人克拉维尔·浓须在闪光平原刺眼的盐滩上交付的一项差事。高速赛车撞毁后，残骸四处飞散，浓须不愿任其浪费，便付钱雇游历者搜遍沙地，回收损坏的机械部件，再直接转卖给相互竞争的侏儒和地精维修组。",h="火箭车零件是投机逐利的矮人商人克拉维尔·浓须在闪光平原刺眼的盐滩上交付的一项差事。高速赛车撞毁后，残骸四处飞散，浓须不愿任其浪费，便付钱雇游历者搜遍沙地，回收损坏的机械部件，再直接转卖给相互竞争的侏儒和地精维修组。",kw={"撞车事故","侏儒","地精","克拉维尔·浓须","沙漠赛道","火箭车零件","回收","废料","闪光平原","千针石林"},ang={["profession:Engineering"]="搜遍盐滩，便能看出相互竞争的地精与侏儒设计中那份不计后果的巧思，不稳定的火箭推进器和临时拼凑的底盘，往往以惊人的车体崩解告终。",["race:Dwarf"]="许多铁炉堡矮人来到赛道，是为了机械革新或挖掘，克拉维尔·浓须却尽显唯利是图的本性，只对回收生意带来的钱币感兴趣。",["race:Gnome"]="回收这些零件，让人看到侏儒工程师不懈的干劲，尽管偶尔会酿成灾难，他们仍试图在开阔的赛道上以速度和创新超越地精对手。"},sec={{t="盐滩上的残骸",b="闪光平原是地精与侏儒工程师激烈较量技术的试验场。高速行驶的试验型火箭车经常发生灾难性故障，将扭曲的齿轮、汽缸和边缘锋利的金属片抛散在广阔的白色荒漠上。维修组一心只顾制造和调校下一辆赛车，沙地却已悄然变成了工程试验留下的废料场。"},{t="浓须的回收生意",b="矮人商人克拉维尔·浓须没有直接上赛道竞争，而是在沙漠赛道发现了利润丰厚的中间商生意。侏儒和地精技师消耗零件的速度惊人，总是急需备用机械部件，好装到车上。浓须雇用旅人收集三十捆破碎的残骸，把惨烈的撞车事故变成新货源，从车手的不幸中稳稳获利。"}},faq={{q="克拉维尔·浓须是谁？",a="克拉维尔·浓须是一名精明的矮人商人，驻留在闪光平原的沙漠赛道。他在赛道周围经营各类生意，主要靠拾荒、零工，以及利用侏儒和地精之间的竞争为自己牟利。",al={"克拉维尔·浓须","火箭车零件任务由谁交付","赛道矮人"}},{q="为什么地上散落着这么多火箭车零件？",a="沙漠赛道是一处繁忙的试车场和赛车场，地精与侏儒工程师在这里将试验型火箭车推向危险的极限。盐滩上经常发生猛烈的撞车事故和突如其来的爆炸，将车体碎片、齿轮和汽缸抛得到处都是。",al={"沙漠里为什么有赛车零件","闪光平原残骸","损坏的火箭车"}},{q="克拉维尔拿这些损坏的零件做什么？",a="浓须会清理收来的废料，再直接倒卖回侏儒和地精车队。维修组不断消耗材料，急于买回一切能用螺栓固定到下一辆原型车上的机械装置和金属废料。",al={"克拉维尔要零件做什么","为什么收集赛车零件"}},{q="这些零件在哪里？",a="这些零件散落在闪光平原开阔的沙地上，遍布中央赛车营地四周。它们看上去是被丢弃的机械废料堆、扭曲的齿轮、汽缸和压扁的金属板。",al={"哪里能找到火箭车零件","零件位置","闪光平原赛车零件"}},{q="这个任务与赛道周围的其他差事有关吗？",a="有。在广阔的盐滩上搜集废料时，正好也能替赛道上的其他雇主猎杀当地野兽，比如从蝎子的尾刺中采集毒液、收集龟壳，以及削减当地秃鹫和蜥蜴的数量。",al={"赛道任务","闪光平原狩猎任务","与火箭车零件一起做的任务"}},{q="遭遇这些撞车事故的车手会怎样？",a="火箭车竞速以极高的致死率闻名。浓须在整理回收的废料时，漫不经心地发现了一只被压在金属板之间的断耳，揭示了一个残酷的事实：许多驾驶员没能活着结束高速试车。",al={"车手能在撞车后生还吗","压扁的耳朵","赛道驾驶员死亡"}}},fx={["16d6be49"]={q="火箭车零件有什么用？",a="这些都是扭曲变形的回收物——齿轮、汽缸和金属碎片，都是高速碰撞时散落在盐碱滩上的。克拉维尔·浓须不愿让它们在盐水里锈掉，便收集起来，转手卖给焦急万分的侏儒和地精维修队。双方都急着修好撞得粉碎的赛车，并在发明上胜过对手，因此乐意买回这些废金属，焊到下一台鲁莽的玩意儿上。",al={"火箭车零件用途","火箭车零件有什么用","为什么收集火箭车零件"}}},fp="16,189,24.310.0,30.347.0,24.208.0,63.199.0,43.169.0,30.191.0,56.226.0,53.149.0"}
P.entries["quest:1111"] = {n="码头管理员迪兹维格",s="克拉维尔·浓须是沙漠赛道的一名矮人，专门替人弄到所需的东西。那里的侏儒正等着一批零件，这批零件一周前就到了棘齿城，但克拉维尔无法亲自前往。他让你带着他的零件订单，去棘齿城找码头管理员迪兹维格。",h="克拉维尔·浓须是沙漠赛道的一名矮人，专门替人弄到所需的东西。那里的侏儒正等着一批零件，这批零件一周前就到了棘齿城，但克拉维尔无法亲自前往。他让你带着他的零件订单，去棘齿城找码头管理员迪兹维格。",kw={"克拉维尔·浓须","沙漠赛道","零件订单","棘齿城","千针石林","码头管理员迪兹维格"},sec={{t="替克拉维尔跑腿",b="克拉维尔·浓须负责替人弄到所需的东西。沙漠赛道的侏儒正等着一批零件，这批零件一周前就到了棘齿城，但克拉维尔无法亲自前往。他请你替他跑腿，并承诺只要你肯帮忙，就会给你更多有望赚大钱的差事。"},{t="棘齿城的码头",b="棘齿城位于贫瘠之地。你要找的是地精码头管理员迪兹维格，克拉维尔说迪兹维格很可能就在码头。你带着克拉维尔的零件订单前往那里。"}},faq={{q="谁派你去找码头管理员迪兹维格？",a="克拉维尔·浓须是千针石林沙漠赛道的一名矮人，他把自己的零件订单交给你，派你前往棘齿城。",al={"谁提供码头管理员迪兹维格任务","克拉维尔·浓须任务"}},{q="在哪里可以找到码头管理员迪兹维格？",a="码头管理员迪兹维格是一名地精，克拉维尔估计能在贫瘠之地的棘齿城码头找到迪兹维格。",al={"迪兹维格位置","迪兹维格在哪里","哪里能找到迪兹维格"}},{q="克拉维尔的订单是做什么用的？",a="沙漠赛道的侏儒正等着一批零件，这批零件一周前就到了棘齿城。克拉维尔无法亲自前往，所以请你把他的订单送到那里的码头。",al={"零件有什么用","为什么去棘齿城"}},{q="码头管理员迪兹维格之后是什么任务？",a="任务链的下一步是给克拉维尔的零件。",al={"迪兹维格之后的任务","接下来做什么"}}},fp="20,97,18.273.0,20.167.0,38.120.0,40.88.0,38.167.0,38.47.0"}
P.entries["quest:1112"] = {n="给克拉维尔的零件",s="你已将克拉维尔·浓须的零件订单交给码头管理员迪兹维格，如今正带着克拉维尔的包裹，返回闪光平原的沙漠赛道交给他。迪兹维格还捎来一句话：如果克拉维尔还想下特殊订单，就得结清欠账。",h="你已将克拉维尔·浓须的零件订单交给码头管理员迪兹维格，如今正带着克拉维尔的包裹，返回闪光平原的沙漠赛道交给他。迪兹维格还捎来一句话：如果克拉维尔还想下特殊订单，就得结清欠账。",kw={"克拉维尔·浓须","沙漠赛道","给克拉维尔的零件","闪光平原","千针石林","码头管理员迪兹维格"},sec={{t="包裹与欠账",b="码头管理员迪兹维格交给你一个要送给克拉维尔·浓须的包裹，他正在千针石林闪光平原的沙漠赛道等候。迪兹维格请你随包裹捎去一句警告：如果克拉维尔还想下特殊订单，就必须先还清欠款。"},{t="克拉维尔的迎接",b="克拉维尔很高兴包裹送到了，并说还得把它交给侏儒。不过，他先放下箱子，从中取出一件小物品，悄悄塞进了口袋。"}},faq={{q="是谁把要送给克拉维尔的包裹交给你的？",a="棘齿城的码头管理员迪兹维格把包裹交给你，请你带回去交给克拉维尔·浓须。",al={"给克拉维尔的零件 由谁开启","零件来自哪里","给克拉维尔的零件 任务给予者"}},{q="克拉维尔·浓须在哪里等候送货？",a="克拉维尔在千针石林闪光平原的沙漠赛道。",al={"克拉维尔·浓须位置","克拉维尔 在哪里","给克拉维尔的零件 在哪里交任务"}},{q="迪兹维格想让你随零件捎去什么话？",a="迪兹维格让你转告克拉维尔，如果还想下特殊订单，就得结清欠账。",al={"迪兹维格 说了什么","迪兹维格 给 克拉维尔 的口信","克拉维尔 的欠账"}},{q="这次送货之前做了什么？",a="在这之前，你将克拉维尔的零件订单送到了棘齿城，交给码头管理员迪兹维格。",al={"给克拉维尔的零件 前置任务","给克拉维尔的零件 上一个任务"}}},fp="16,196,19.273.0,16.181.1,37.104.0,47.103.0,62.100.0,31.103.0"}
P.entries["quest:1113"] = {n="Hearts of Zeal",s="大药剂师法拉尼尔需要 Hearts of Zeal 来进行一项危险的实验。他让你从血色修道院的血色十字军教徒那里收集这些心脏。",h="大药剂师法拉尼尔需要 Hearts of Zeal 来进行一项危险的实验。他让你从血色修道院的血色十字军教徒那里收集这些心脏。",kw={"实验","hearts of zeal","大药剂师法拉尼尔","血色十字军","血色修道院","提瑞斯法林地","幽暗城"},sec={{t="法拉尼尔的实验",b="法拉尼尔在幽暗城进行实验，需要一种罕见的鸟粪。他计划将相互对立的化学物质与一种毒剂混合。在提瑞斯法林地东北部的血色修道院，你要为他带回血色十字军教徒充满狂热的心脏。"}},faq={{q="谁需要 Hearts of Zeal？",a="幽暗城的大药剂师法拉尼尔需要 Hearts of Zeal 来进行实验。",al={"谁需要心脏","法拉尼尔心脏"}},{q="血色十字军教徒在哪里？",a="这些教徒聚集在提瑞斯法林地东北部山峰上的血色修道院。",al={"哪里能找到教徒","血色修道院心脏"}},{q="法拉尼尔打算用这些心脏做什么？",a="法拉尼尔正在用相互对立的化学物质和一种毒剂进行实验，他需要充满狂热的心脏。",al={"狂热之心的用途","法拉尼尔在制作什么"}},{q="法拉尼尔需要多少 Hearts of Zeal？",a="法拉尼尔需要二十颗 Hearts of Zeal。",al={"需要多少心脏","心脏数量"}}},fp="14,159,21.275.0,29.87.0,40.91.0,46.119.0,43.40.0"}
P.entries["quest:1114"] = {n="侏儒的货物",s="克拉维尔·浓须如今已经拿到了所需的东西，想让你把精密赛车零件送给闪光平原的菲兹尔·铜栓，他已经等了很久。克拉维尔承认，他从菲兹尔订购的货物中拿走了一个小零件，并建议你别提这件事。",h="克拉维尔·浓须如今已经拿到了所需的东西，想让你把精密赛车零件送给闪光平原的菲兹尔·铜栓，他已经等了很久。克拉维尔承认，他从菲兹尔订购的货物中拿走了一个小零件，并建议你别提这件事。",kw={"精密赛车零件","侏儒的货物","菲兹尔·铜栓","液压棘轮","克拉维尔·浓须","沙漠赛道","连发螺栓","闪光平原","千针石林"},sec={{t="少了一个零件",b="克拉维尔·浓须告诉你，这些零件是给菲兹尔·铜栓的，他已经等了很久。克拉维尔坦白，他从菲兹尔订购的货物中拿走了一个小零件，但他确信没人会发现。他说那个零件又小又不值钱，劝你别提这件事，还要你相信他。"},{t="菲兹尔的评价",b="菲兹尔·铜栓高兴地收下了包裹：他的液压棘轮和连发螺栓终于到了，这些东西够用了。"}},faq={{q="谁让人把零件送给菲兹尔·铜栓？",a="沙漠赛道的克拉维尔·浓须。他请你把零件继续送到菲兹尔·铜栓那里。",al={"谁发布侏儒的货物","侏儒的货物任务发布者","谁让人送零件"}},{q="克拉维尔·浓须从包裹里拿走了什么？",a="克拉维尔说，他从菲兹尔订购的货物中拿走了一个小零件。他说那个零件又小又不值钱，希望你别向菲兹尔提起。",al={"克拉维尔拿走了什么","零件少了什么","克拉维尔偷零件"}},{q="这批货要送到哪里？",a="送给闪光平原的菲兹尔·铜栓。沙漠赛道也在这片平原上，克拉维尔·浓须就在那里。",al={"侏儒的货物地点","菲兹尔·铜栓在哪里","闪光平原送货"}},{q="这次送货之前是什么任务？",a="前一个任务是给克拉维尔的零件，你在那个任务中把克拉维尔的包裹从棘齿城带回来交给了他。",al={"侏儒的货物前置任务","什么任务接到侏儒的货物"}}},fp="22,219,16.279.0,16.124.1,41.105.0,48.136.0,28.134.0,31.89.0"}
P.entries["quest:1115"] = {n="车手的传闻",s="为侏儒办过一件事后，克拉维尔·浓须现在想帮地精一个忙。他听说地精赛车手纳兹·斯迪波尔曾用过另一个名字，想知道这是不是个值钱的秘密。他让你去找藏宝海湾的克拉兹克，此人应该知道内情。",h="为侏儒办过一件事后，克拉维尔·浓须现在想帮地精一个忙。他听说地精赛车手纳兹·斯迪波尔曾用过另一个名字，想知道这是不是个值钱的秘密。他让你去找藏宝海湾的克拉兹克，此人应该知道内情。",kw={"藏宝海湾","克拉维尔·浓须","克拉兹克","沙漠赛道","纳兹·斯迪波尔","水手之家旅店","闪光平原","荆棘谷","千针石林"},sec={{t="值得打听的名字",b="克拉维尔·浓须说，接下来该帮地精一个忙了。他听说地精赛车手纳兹·斯迪波尔曾用过另一个名字，便想知道改名的原因，背后是否藏着秘密，以及纳兹是否在意这个秘密被人知晓。克拉维尔说，知道真相的人是克拉兹克，就在荆棘谷最南端的藏宝海湾。有用的消息也许能换来一笔钱。去Salty Sailor Tavern找克拉兹克。"},{t="克拉兹克的答复",b="克拉兹克知道纳兹·斯迪波尔是闪光平原上的一名赛车手。克拉兹克说，也许能打听出些消息，但他提醒你，这事既不容易，也不快，更不便宜。"}},faq={{q="是谁让你去找克拉兹克的？",a="是克拉维尔·浓须，他是闪光平原沙漠赛道上的一名矮人。",al={"谁提供流言蜚语","流言蜚语任务给予者","谁开启任务"}},{q="克拉维尔为什么对纳兹·斯迪波尔感兴趣？",a="克拉维尔听说，这名地精赛车手并非一直使用这个名字。他想知道这是否是个秘密，以及纳兹是否足够看重这个秘密，让他能从中获利。",al={"为什么是纳兹·斯迪波尔","克拉维尔打听纳兹的动机","传闻是什么"}},{q="在哪里能找到克拉兹克？",a="克拉兹克在荆棘谷最南端的藏宝海湾，就在水手之家旅店里。",al={"克拉兹克位置","克拉兹克在哪里","如何找到克拉兹克"}},{q="这之前是什么任务？",a="前一个任务是侏儒的货物，也就是为侏儒办的那件事。",al={"流言蜚语前置任务","流言蜚语上一个任务","先做什么任务"}}},fp="15,236,25.370.0,15.147.1,24.93.0,43.179.0,26.88.0,23.80.0"}
P.entries["quest:1116"] = {n="梦境之尘",s="藏宝海湾的克拉兹克说，打听纳兹的消息可是个不小的人情。克拉兹克联络消息来源时，你受托从悲伤沼泽的雏龙身上收集十粒梦境之尘，装进他的鼻烟袋。带回来后，克拉兹克就会给你想要的消息。",h="藏宝海湾的克拉兹克说，打听纳兹的消息可是个不小的人情。克拉兹克联络消息来源时，你受托从悲伤沼泽的雏龙身上收集十粒梦境之尘，装进他的鼻烟袋。带回来后，克拉兹克就会给你想要的消息。",kw={"藏宝海湾","梦境之尘","克拉维尔·浓须","克拉兹克","沙漠赛道","纳兹","悲伤沼泽","雏龙"},sec={{t="人情换人情",b="克拉兹克告诉你，打听纳兹的消息可是个大人情，而你为此已经从闪光平原远道而来。克拉兹克联络消息来源时，你受托收集些东西。他要的是从悲伤沼泽的雏龙身上取得的十粒梦境之尘，好装进鼻烟袋。等你带着梦境之尘回来，就能得到消息。"},{t="尘埃的所在",b="悲伤沼泽的绿龙身上带有梦境之尘。年幼的雏龙和沉睡的雏龙身上都有，它们都栖息在沼泽的西南角。"}},faq={{q="谁在索要梦境之尘？",a="藏宝海湾的克拉兹克需要它，作为提供纳兹消息的交换条件。",al={"谁发布梦境之尘任务","谁派我去悲伤沼泽","梦境之尘任务发布者"}},{q="克拉兹克为什么想要梦境之尘？",a="克拉兹克说，这些尘埃要装进鼻烟袋，并在联络消息来源打听纳兹的同时，托你去收集。",al={"梦境之尘有什么用","克拉兹克为什么要尘埃","梦境之尘鼻烟"}},{q="哪里能找到梦境之尘？",a="梦境之尘取自悲伤沼泽西南角的雏龙，例如年幼的雏龙和沉睡的雏龙。",al={"哪里能找到梦境之尘","悲伤沼泽梦境之尘在哪","梦境之尘位置"}},{q="这与克拉维尔·浓须有什么关系？",a="沙漠赛道的克拉维尔·浓须派你去找克拉兹克，打听地精赛车手纳兹·斯迪波尔的消息，你为此从闪光平原赶来。",al={"为什么在藏宝海湾","这与克拉维尔有什么关系","闪光平原的关联"}},{q="接下来做什么？",a="下一步是地精的谣言。",al={"沼泽中的梦境之尘之后做什么","梦境之尘后续任务","下一步地精的谣言"}}},fp="23,217,19.345.0,23.145.0,33.83.0,32.93.0,30.142.0,47.163.0,16.29.0"}
P.entries["quest:1117"] = {n="地精的谣言",s="克拉兹克找到了你要的东西。动用了一些人情，做了大量推理，还舍出了一瓶珍贵的精灵葡萄酒后，克拉兹克写了一封关于纳兹·斯迪波尔的信。克拉兹克使用这封信太过危险，所以你把它带给闪光平原上的克拉维尔·浓须，并被叮嘱不要透露信的来源。",h="克拉兹克找到了你要的东西。动用了一些人情，做了大量推理，还舍出了一瓶珍贵的精灵葡萄酒后，克拉兹克写了一封关于纳兹·斯迪波尔的信。克拉兹克使用这封信太过危险，所以你把它带给闪光平原上的克拉维尔·浓须，并被叮嘱不要透露信的来...",kw={"藏宝海湾","地精传闻","克拉维尔·浓须","克拉兹克","沙漠赛道","纳兹·斯迪波尔","地精的谣言","闪光平原","千针石林"},sec={{t="克拉兹克的来信",b="克拉兹克告诉你，这番调查付出了什么代价：用掉了一些人情，舍出了一瓶珍贵的精灵葡萄酒，还做了大量推理。成果就是一封信，里面记载了关于纳兹·斯迪波尔的一些非常有趣的消息。克拉兹克觉得使用这封信太过危险，便交给你随意处置，只要没人知道信的来源就行。这封信要送回闪光平原上的克拉维尔·浓须手中。"},{t="克拉维尔的判断",b="克拉维尔觉得这封信非常有趣。他寻思着，下次见到那位地精驾驶员时，或许该向他鞠个躬，还料定纳兹会花上一大笔钱，让这个秘密永远埋藏下去。"}},faq={{q="这件事从哪里开始？",a="你带来梦境之尘后，克拉兹克会在藏宝海湾把信交给你。",al={"谁提供 地精的谣言","地精的谣言 起始任务","哪里获取传闻"}},{q="应该把信交给谁？",a="交给克拉维尔·浓须，他在千针石林闪光平原上的沙漠赛道。",al={"哪里交付 地精的谣言","地精传闻交给谁","克拉维尔·浓须在哪里"}},{q="克拉兹克调查的是谁？",a="纳兹·斯迪波尔，那位地精赛车驾驶员。克拉兹克在信里写下了关于纳兹的一些非常有趣的消息。",al={"纳兹·斯迪波尔 是谁","传闻说的是什么","传闻与谁有关"}},{q="克拉兹克是怎么查到这些消息的？",a="克拉兹克用掉了一些人情，做了一番缜密的推理，还舍出了一瓶珍贵的精灵葡萄酒。",al={"克拉兹克如何获得消息","克拉兹克的人情"}},{q="接下来是什么？",a="任务链的下一步是 返回藏宝海湾。",al={"地精的谣言 之后的任务","地精的谣言 后续"}}},fp="17,157,20.339.0,16.200.1,22.76.0,37.103.0,40.116.0,39.96.0,16.30.0"}
P.entries["quest:1118"] = {n="返回藏宝海湾",s="克拉维尔·浓须相信你能办好差事，也能守口如瓶。他有了一个新计划，虽然冒险，却有望让你们俩大赚一笔。你带着他的信，前往藏宝海湾交给克兰克·菲兹巴布。这是地精的谣言之后的任务。",h="克拉维尔·浓须相信你能办好差事，也能守口如瓶。他有了一个新计划，虽然冒险，却有望让你们俩大赚一笔。你带着他的信，前往藏宝海湾交给克兰克·菲兹巴布。这是地精的谣言之后的任务。",kw={"藏宝海湾","克兰克·菲兹巴布","克拉维尔·浓须","克拉维尔的设计图","沙漠赛道","水手之家旅店","闪光平原","千针石林"},sec={{t="送往藏宝海湾的信",b="沙漠赛道的矮人克拉维尔·浓须说，你值得信赖，既能办好差事，也能守口如瓶。他的新计划有些冒险，但若能成功，你们俩就能大赚一笔。他为再次派你去藏宝海湾而致歉，上次的差事已经让你跑过一趟，并请你在那里找到克兰克·菲兹巴布，把信交给他。如果克兰克需要帮助，克拉维尔希望你尽力相助，并说这番辛苦会有回报。"},{t="克兰克读信",b="克兰克·菲兹巴布读过信，发现克拉维尔正在筹划一个大计划。克兰克很欣赏克拉维尔那阴险的头脑。这个计划需要某种能让人神志不清的强效药剂，克兰克琢磨着，赞吉尔给僵尸喝的药剂或许能派上用场。"}},faq={{q="这趟旅程从哪里开始，到哪里结束？",a="旅程始于千针石林沙漠赛道的克拉维尔·浓须。你带着他的信，去找克兰克·菲兹巴布，他就在荆棘谷藏宝海湾的水手之家旅店。",al={"去哪里","谁提供返回藏宝海湾任务","克兰克·菲兹巴布在哪里"}},{q="此前是什么任务？",a="此前是地精的谣言，那个任务曾让你前往藏宝海湾。",al={"前置条件","上一个任务","先做哪个任务"}},{q="克拉维尔的设计图是什么？",a="那就是你要交给克兰克·菲兹巴布的信。克拉维尔说他的计划有些冒险，但若能成功，你们俩就能大赚一笔。",al={"克拉维尔的设计图是什么","克拉维尔计划的信"}},{q="如果克兰克·菲兹巴布需要帮助，你该怎么做？",a="克拉维尔请你尽力帮助他，并说这番辛苦会有回报。",al={"帮助克兰克","克兰克是否需要帮助"}},{q="接下来是什么任务？",a="任务链接下来是赞吉尔的药剂与蠢人酒。",al={"下一个任务","返回藏宝海湾后续任务"}}},fp="17,208,22.334.0,22.219.1,38.180.0,22.61.0,24.147.0,49.92.0,22.61.0"}
P.entries["quest:1119"] = {n="赞吉尔的药剂和蠢人酒",s="克兰克·菲兹巴布发现，将赞吉尔的药剂掺入烈性啤酒，就能调出一种名叫蠢人酒的烈酒。他觉得这正是克拉维尔需要的。你要把酒送到闪光平原的沙漠赛道，交给克拉维尔·浓须，而且动作要快，因为这酒放不久。",h="克兰克·菲兹巴布发现，将赞吉尔的药剂掺入烈性啤酒，就能调出一种名叫蠢人酒的烈酒。他觉得这正是克拉维尔需要的。你要把酒送到闪光平原的沙漠赛道，交给克拉维尔·浓须，而且动作要快，因为这酒放不久。",kw={"藏宝海湾","菲兹巴布","克拉维尔","药剂","赛道","闪光平原","烈性啤酒","赞吉尔"},sec={{t="给克拉维尔的酒",b="克兰克·菲兹巴布发现，将赞吉尔的药剂掺入烈性啤酒，就能调出一种烈酒，名叫蠢人酒。克兰克觉得这正是克拉维尔需要的，并想听听效果如何。你要把酒带回闪光平原的沙漠赛道，交给克拉维尔·浓须。"},{t="别放太久",b="克兰克提醒你，别把这烈性啤酒放得太久。药剂对酒里的酵母有一种奇怪的作用，会让酵母加速发酵，因此这酒无法一直保持新鲜。"}},faq={{q="谁派你送这趟酒？",a="藏宝海湾的克兰克·菲兹巴布把蠢人酒交给你送去。",al={"谁开启赞吉尔的药剂与蠢人酒","任务给予者"}},{q="蠢人酒要交给谁？",a="克拉维尔·浓须，他在千针石林闪光平原的沙漠赛道。",al={"烈性啤酒交给谁","在哪里交任务","克拉维尔的位置"}},{q="为什么这酒需要尽快送到？",a="因为混合后的药剂会让酵母加速发酵，烈性啤酒放得太久就会变质。",al={"蠢人酒会过期吗","为什么限时","发酵效果"}},{q="这之前是什么任务？",a="之前的任务是返回藏宝海湾和赞吉尔的秘密。",al={"前置任务","上一步"}},{q="送完酒之后是什么任务？",a="任务线接下来是蠢人酒、灌醉侏儒和灌醉地精。",al={"后续任务","接下来会怎样"}}},fp="35,218,21.251.0,17.131.0,31.61.0,30.105.0,48.72.0,22.49.0,38.86.0"}
P.entries["quest:112"] = {n="收集海藻",s="在闪金镇，梅贝尔·马科伦想悄悄去见托米·乔·斯通菲尔德。威廉·匹斯特需要稀有的水晶海藻，为她配制隐形水。",h="在闪金镇，梅贝尔·马科伦想悄悄去见托米·乔·斯通菲尔德。威廉·匹斯特需要稀有的水晶海藻，为她配制隐形水。",kw={"收集海藻","水晶海藻","水晶湖","闪金镇","隐形水","梅贝尔·马科伦","鱼人","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="对联盟而言，为匹斯特清剿水晶湖周围的鱼人营地，有助于平息闪金镇东侧道路附近的凶恶威胁。",["profession:Herbalism"]="对身为采集者的你来说，crystal kelp是一种奇特的收获：这种海洋草药取自淡水鱼人的袋子，而非土壤或海床。"},sec={{t="禁忌之恋的良方",b="斯通菲尔德家族与马科伦家族之间的世仇，让梅贝尔·马科伦和托米·乔·斯通菲尔德无法公开见面。梅贝尔想见自己的心上人，又不愿让双方亲族兵戎相见。于是，她寻找着悄然穿过山谷的办法。威廉·匹斯特是闪金镇狮王之傲旅店的一位草药师兼药剂师，他打算配制隐形水，但旅店的橱柜里没有所需的稀有材料。"},{t="水晶湖的拾荒者",b="威廉·匹斯特需要用水晶海藻作为药剂的催化剂。这种海藻的叶片通常生长在远海的咸水中，但鱼人部族把一些存货带到了内陆，藏在闪金镇东边水晶湖畔的简陋营地里。它们奇特的本能驱使着它们，将这些海洋植物搬到淡水湖岸。你需要从鱼人那里收集足够的叶片，再带回闪金镇。"}},faq={{q="威廉·匹斯特为什么需要水晶海藻？",a="威廉·匹斯特需要用水晶海藻为梅贝尔·马科伦配制隐形水。这种药水能帮助她悄悄离开自家的葡萄园，去见托米·乔·斯通菲尔德。",al={"为什么需要水晶海藻","海藻的用途","威廉·匹斯特的材料"}},{q="为什么淡水的水晶湖附近会有海藻？",a="水晶海藻生长在海洋中，但水晶湖周围的鱼人部族会搜集它的叶片，并将其带到内陆。它们把海藻囤积在湖畔的营地里，这是闪金镇附近唯一能找到这种海藻的地方。",al={"水晶湖为什么有海藻","淡水中的海藻","鱼人与海藻的故事"}},{q="梅贝尔·马科伦和托米·乔·斯通菲尔德是谁？",a="梅贝尔·马科伦和托米·乔·斯通菲尔德是一对年轻恋人，分别来自艾尔文森林南部两个敌对的农户家族。两家互相憎恨，因此这对恋人只能靠秘密行动和炼金术的小把戏来见面。",al={"梅贝尔是谁","托米·乔是谁","马科伦与斯通菲尔德的世仇"}},{q="水晶湖在哪里？",a="水晶湖位于艾尔文森林中部，就在闪金镇东边。充满敌意的鱼人盘踞在湖水中和岸边。",al={"水晶湖在哪里","水晶湖位置","寻找水晶湖"}},{q="收集海藻之后会发生什么？",a="你交付四片水晶海藻叶片后，威廉·匹斯特会将它们蒸馏制成隐形水。随后，他会请你把药水带给梅贝尔·马科伦，让她能悄悄溜走。",al={"收集海藻后的任务","匹斯特配制什么"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是闪金镇狮王之傲旅店的一位药剂师，也略通炼金术。他用民间偏方和奇异药水帮助当地人，也替他们处理一些私密的委托。",al={"威廉·匹斯特是谁","匹斯特 闪金镇"}}},fx={ff0f7883={q="威廉·匹斯特为什么愿意帮助梅贝尔和 托米·乔？",a="威廉·匹斯特是闪金镇当地的药剂师兼炼金师，他愿意用自己的手艺帮助这对年轻恋人。梅贝尔·马科伦和托米·乔·斯通菲尔德被两个家族长久而深重的仇怨隔在了对立的两边。一剂秘制隐形药水能让梅贝尔巧妙地避开马科伦农场里家人的严密看管，又不至于引发两个家族之间的进一步冲突。",al={"为何帮助 梅贝尔","威廉·匹斯特的动机","威廉 为何关心此事"}},cc419076={q="鱼人为什么聚集在水晶湖？",a="鱼人从海岸悄悄进入内陆，沿着水晶湖和 石碑湖 等艾尔文森林的淡水水域扎下营地。暴风城的军队忙于保卫其他地方的边境，兵力不足，这些好斗的两栖生物因此愈发大胆，开始侵扰当地聚居地，并四处搜集物资——其中就包括它们带到内陆的海藻。",al={"鱼人为何在水晶湖","水晶湖鱼人","艾尔文 的鱼人"}}},fp="15,148,27.431.0,30.406.0,42.183.0,53.191.0,49.206.0,30.112.0,39.178.0,22.170.0"}
P.entries["quest:1120"] = {n="灌醉侏儒",s="克拉维尔·浓须想在沙漠赛道的一支赛车维修队身上试试蠢人酒。如果选择侏儒，你就把烈酒送给侏儒车队老板。烈酒放久了会变质，所以克拉维尔·浓须说别耽搁太久。",h="克拉维尔·浓须想在沙漠赛道的一支赛车维修队身上试试蠢人酒。如果选择侏儒，你就把烈酒送给侏儒车队老板。烈酒放久了会变质，所以克拉维尔·浓须说别耽搁太久。",kw={"蠢人酒","侏儒车队老板","克拉维尔·浓须","沙漠赛道","千针石林","赞吉尔"},sec={{t="在维修队身上试酒",b="克拉维尔·浓须需要找一支赛车维修队试试蠢人酒。你可以选择侏儒：他把烈酒交给你，让你送到附近沙漠赛道的侏儒车队老板那里。选择侏儒会让地精在比赛中占据优势。克拉维尔·浓须警告你别磨蹭，因为烈酒放久了会变质。"},{t="赛前小酌",b="侏儒车队老板很喜欢这份礼物，称赞你想得周到。车队老板承认，比赛在即，喝酒并不明智，但队员们喝一点应该应付得来。毕竟，这酒不可能那么烈。"}},faq={{q="谁让你送烈酒？",a="千针石林沙漠赛道的矮人克拉维尔·浓须把烈酒交给你。",al={"谁提供灌醉侏儒","灌醉侏儒任务给予者","克拉维尔·浓须任务"}},{q="蠢人酒应该送给谁？",a="送给附近沙漠赛道的侏儒车队老板。",al={"烈酒送到哪里","蠢人酒送给谁","侏儒车队老板位置"}},{q="送酒耽搁太久会怎样？",a="烈酒放久了会变质，所以克拉维尔·浓须让你别耽搁太久。",al={"蠢人酒会变质吗","烈酒时限","蠢人酒变质"}},{q="可以改选地精作为目标吗？",a="可以。克拉维尔·浓须让你选择在哪支赛车维修队身上试酒，另一个选择是灌醉地精。",al={"灌醉地精选项","能否改选灌醉地精","沙漠赛道侏儒或地精"}},{q="前置任务是什么？",a="前置任务是赞吉尔的药剂与蠢人酒。",al={"前置任务","灌醉侏儒前置任务"}},{q="送完烈酒后是什么任务？",a="任务链接下来是向菲兹巴布报告。",al={"后续任务","灌醉侏儒后续任务"}}},fp="20,202,23.296.0,30.192.1,34.102.0,45.74.0,55.75.0,45.107.0,23.47.0,40.79.0"}
P.entries["quest:1121"] = {n="灌醉地精",s="克拉维尔·浓须想让沙漠赛道的一支维修队试试蠢人酒。如果选择地精，就把酒送给地精车队老板。这酒迟早会变质，所以克拉维尔说别等太久。",h="克拉维尔·浓须想让沙漠赛道的一支维修队试试蠢人酒。如果选择地精，就把酒送给地精车队老板。这酒迟早会变质，所以克拉维尔说别等太久。",kw={"蠢人酒","侏儒","地精","地精车队老板","克拉维尔·浓须","沙漠赛道","千针石林"},sec={{t="让维修队试酒",b="克拉维尔·浓须需要找一支维修队试试蠢人酒。可以找地精试酒：他把酒交给你，让你送给沙漠赛道附近的地精车队老板。选择地精会让比赛形势对侏儒更有利。克拉维尔警告你别磨蹭，因为这酒迟早会变质。"},{t="喝一点无妨",b="地精车队老板见有人送酒，并不介意喝上一点。"}},faq={{q="谁提供这个任务？",a="克拉维尔·浓须，就是千针石林沙漠赛道的那个矮人。",al={"任务给予者","谁提供灌醉地精","克拉维尔·浓须"}},{q="要把酒送到哪里？",a="送给沙漠赛道附近的地精车队老板。",al={"酒送到哪里","地精车队老板位置"}},{q="等得太久会怎样？",a="这酒迟早会变质，所以克拉维尔让你别等太久。",al={"酒会变质吗","蠢人酒持续时间","酒变质"}},{q="还有什么其他选择？",a="克拉维尔让你选择找哪支维修队试酒。另一个选择是灌醉侏儒，找侏儒维修队试酒。",al={"灌醉侏儒选择","赛道侏儒或地精"}},{q="前置任务是什么？",a="前置任务是赞吉尔的药剂蠢人酒。",al={"前置任务","灌醉地精前置条件"}},{q="送完酒之后是什么任务？",a="任务链接下来是向菲兹巴布报告。",al={"后续任务","灌醉地精后续任务"}}},fp="21,173,23.275.0,19.73.1,16.90.0,30.75.0,34.75.0,32.121.0,23.47.0,40.50.0"}
P.entries["quest:1122"] = {n="向菲兹巴布报告",s="克拉维尔·浓须说，蠢人酒的效果非常好。他已经为下一场比赛下了注，希望被你灌醉的车队成员已经弄坏了自己的赛车。你带着一张记录试验成功的便笺，前往藏宝海湾交给克兰克·菲兹巴布。这项任务接续你选择灌醉其中一支维修队的任务。",h="克拉维尔·浓须说，蠢人酒的效果非常好。他已经为下一场比赛下了注，希望被你灌醉的车队成员已经弄坏了自己的赛车。你带着一张记录试验成功的便笺，前往藏宝海湾交给克兰克·菲兹巴布。这项任务接续你选择灌醉其中一支维修队的任务。",kw={"藏宝海湾","克兰克·菲兹巴布","蠢人酒","克拉维尔·浓须","沙漠赛道","闪光平原","千针石林"},sec={{t="给克兰克的便笺",b="克拉维尔·浓须说，蠢人酒的效果非常好。他已经为下一场比赛下了注，希望被你灌醉的维修队已经弄坏了自己的赛车。还有一件事要做：把记录试验成功的便笺带给藏宝海湾的克兰克·菲兹巴布，他一定想听到这个消息。克拉维尔还希望能弄到更多这种烈酒，用在以后的比赛中。"},{t="克兰克的答复",b="克兰克·菲兹巴布读完便笺，宣布试验成功，并为这个消息感到高兴。克兰克说，如果你以后还想要这种烈酒，尽管开口，他会让你去收集更多赞吉尔的药剂。"}},faq={{q="谁提供这个任务？",a="克拉维尔·浓须会把便笺交给你，这个矮人就在千针石林闪光平原的沙漠赛道。",al={"任务给予者","谁提供向菲兹巴布报告"}},{q="克兰克·菲兹巴布在哪里？",a="在藏宝海湾。",al={"菲兹巴布位置","克兰克·菲兹巴布在哪","交任务地点"}},{q="前置任务是什么？",a="前置任务是灌醉侏儒，如果你选择了另一支维修队，则是灌醉地精。",al={"前置条件","前置任务"}},{q="克拉维尔·浓须想让菲兹巴布知道什么？",a="试验成功了。",al={"报告是什么","报告内容"}}},fp="24,253,16.290.0,14.186.1,16.114.0,33.32.0,23.103.0,50.60.0"}
P.entries["quest:1127"] = {n="蠢人酒",s="藏宝海湾的克兰克·菲兹巴布为打算返回闪光平原赛道的旅人酿制蠢人酒。要再酿一份，他需要十二瓶赞吉尔的药剂。",h="藏宝海湾的克兰克·菲兹巴布为打算返回闪光平原赛道的旅人酿制蠢人酒。要再酿一份，他需要十二瓶赞吉尔的药剂。",kw={"藏宝海湾","克兰克·菲兹巴布","蠢人酒","赛道","荆棘谷","赞吉尔的药剂"},sec={{t="再酿一批",b="如果旅人还没赶到赛道上的侏儒那里，最初带上的蠢人酒就已失效，克兰克·菲兹巴布可以再酿一份。藏宝海湾的地精克兰克·菲兹巴布需要十二瓶赞吉尔的药剂，才能再次调制这种烈性饮品，他会付酬给愿意收集原料的人，还会额外给一点钱，让对方对这笔交易保密。"}},faq={{q="谁可以酿制蠢人酒？",a="克兰克·菲兹巴布会酿制这种烈性啤酒，他就在荆棘谷南部的藏宝海湾里。",al={"谁提供蠢人酒","蠢人酒任务给予者","克兰克·菲兹巴布"}},{q="克兰克·菲兹巴布需要什么原料？",a="他需要十二瓶赞吉尔的药剂，才能再酿一批这种烈性啤酒。",al={"蠢人酒需要什么物品","蠢人酒原料","赞吉尔的药剂需求"}},{q="为什么会有人需要再酿一批蠢人酒？",a="这种饮品会在两小时后蒸发，因此错过这段时间的旅人必须重新收集原料，再酿一份。",al={"为什么重做蠢人酒","蠢人酒已失效","蠢人酒持续时间"}},{q="这种酒要送到哪里？",a="这种酒是要送给赛道上的侏儒的。",al={"蠢人酒送到哪里","谁喝蠢人酒","蠢人酒目的地"}}},fp="12,159,14.290.0,32.89.0,43.94.0,53.116.0,33.48.0"}
P.entries["quest:113"] = {n="昆虫研究",s="炼金师匹斯特苏格已经完成了昆虫肢体的分析报告，并表示高级勘探员菲兹杜瑟必须立刻过目。这一威胁危及塔纳利斯和加基森，如果任其发展，还将危及整个卡利姆多南部。",h="炼金师匹斯特苏格已经完成了昆虫肢体的分析报告，并表示高级勘探员菲兹杜瑟必须立刻过目。这一威胁危及塔纳利斯和加基森，如果任其发展，还将危及整个卡利姆多南部。",kw={"菲兹杜瑟","加基森","加基森水业公司","昆虫分析","匹斯特苏格","报告","塔纳利斯"},sec={{t="严峻的警告",b="匹斯特苏格坚持说，高级勘探员菲兹杜瑟必须立刻阅读这份报告，所有识字的人也都必须看看。这个威胁极其严重，危及塔纳利斯和加基森，如果任其发展，还将危及整个卡利姆多南部。它甚至可能波及整个艾泽拉斯，因为它丝毫没有减弱的迹象。你受托将报告送给加基森的菲兹杜瑟，并请他制作一份副本，以便在你所属的阵营中自由传阅。所有人都必须知道这一威胁。"},{t="钱的问题",b="菲兹杜瑟感谢你送来报告，也感谢你为 加基森水业公司 辛勤奔走。菲兹杜瑟并不喜欢把公司宝贵的情报分发给所有人，因为通常人们会花大价钱购买这些情报。不过，菲兹杜瑟与匹斯特苏格相识已久，既然匹斯特苏格建议让所有人都知道，那就照办吧。你得到了一份副本。"}},faq={{q="谁送出报告，谁接收报告？",a="炼金师匹斯特苏格将报告交给你，派你把它送给加基森的高级勘探员菲兹杜瑟。",al={"昆虫研究 由谁给予","昆虫研究 向谁交付","报告送到哪里"}},{q="炼金师匹斯特苏格为什么如此惊慌？",a="匹斯特苏格说，这是一个极其严重的威胁，危及塔纳利斯和加基森，如果任其发展，还将危及整个卡利姆多南部，甚至可能波及整个艾泽拉斯，而且丝毫没有减弱的迹象。",al={"匹斯特苏格 的警告","昆虫报告的内容","昆虫威胁为何严重"}},{q="为什么需要一份报告副本？",a="匹斯特苏格希望所有人都知道这一威胁，因此要让菲兹杜瑟制作一份副本，供你在自己人当中自由传阅。",al={"为何复制报告","菲兹杜瑟 报告副本","为何分享报告"}},{q="送交报告之前紧接着是哪一步？",a="此前的一步也叫昆虫研究。",al={"前置任务","此前是什么任务"}}},fp="20,146,15.392.0,16.395.1,41.95.0,39.163.0,37.133.0,41.57.0"}
P.entries["quest:1130"] = {n="梅洛的关注",s="乔恩·星眼为贫瘠之地中崭露头角的猎人带来了梅洛·石蹄的消息。那些在卡利姆多各地证明了自身勇气与毅力的人，受召前往雷霆崖的猎人高地，迎接更艰难的试炼。",h="乔恩·星眼为贫瘠之地中崭露头角的猎人带来了梅洛·石蹄的消息。那些在卡利姆多各地证明了自身勇气与毅力的人，受召前往雷霆崖的猎人高地，迎接更艰难的试炼。",kw={"贫瘠之地","陶拉祖营地","猎人高地","乔恩·星眼","梅洛的传话","梅洛·石蹄","钢齿土狼","雷霆崖"},ang={["class:Hunter"]="身为猎人，你从梅洛·石蹄身上看到了牛头人驾驭野兽的技艺。他要求精准、耐心，以及对危险猎物的尊重。",["faction:Horde"]="身为部落的一员，你知道陶拉祖营地和雷霆崖都依靠技艺娴熟的野外行动人员，应对补给路线与哨站附近的危险掠食者。",["race:Tauren"]="身为牛头人，响应梅洛的召唤，是象征成年与地位的传统仪式。你以此证明自己精通狩猎，并为猎人高地赢得荣耀。"},sec={{t="雷霆崖的召唤",b="乔恩·星眼在贫瘠之地各处守望着路口与营地。他为在周边地区展露潜力的猎人与战士，传达猎人高地长者们的消息。梅洛·石蹄是一位备受尊敬的牛头人导师，他已为这些人指明了道路。"},{t="狩猎之路",b="在雷霆崖的猎人高地，你见到了梅洛·石蹄。这位年迈的猎人问你，是否有决心深入遥远而危险的荒野。他的召唤开启了一系列试炼，让猎人远离莫高雷的庇护，面对这片大陆上最凶猛的掠食者。"}},faq={{q="梅洛·石蹄是谁？",a="梅洛·石蹄是一位经验丰富的牛头人猎人，居于雷霆崖的猎人高地。他考察部落中崭露头角的追踪者与战士，再派遣合格的人选前往卡利姆多各地，追踪并猎杀恶名昭彰的野兽。",al={"梅洛","梅洛是谁","梅洛·石蹄背景故事"}},{q="谁传达了这次召唤？",a="乔恩·星眼是贫瘠之地陶拉祖营地的一位牛头人驯兽师，由他传达这条消息。他照看往来的旅人，并让那些展现出勇气的人前往雷霆崖，与梅洛交谈。",al={"任务起始者","乔恩·星眼","谁召见了我"}},{q="在哪里能找到梅洛·石蹄？",a="梅洛位于猎人高地，那是雷霆崖南部的台地，专供牛头人猎人、追踪者与驯兽师使用。",al={"梅洛位置","梅洛在哪里","雷霆崖 猎人高地"}},{q="梅洛为我安排了怎样的道路？",a="梅洛通过艰难的追踪之旅，考验你的耐力与狩猎本能。第一次任务会派你穿越千针石林，猎杀凶残的鬣狗暴君钢齿土狼。",al={"梅洛想要什么","梅洛的关注 后续任务","梅洛任务链"}},{q="梅洛为何招募来自贫瘠之地的冒险者？",a="能在贫瘠之地凶猛的掠食者、野猪人和半人马的威胁下生存，说明你具备参与高难度狩猎的本能。梅洛寻找的是能在陌生土地上追踪隐秘而致命的猎物的人。",al={"为什么选我","梅洛为何在意"}},{q="这项试炼仅限猎人参加吗？",a="任何在荒野中证明过自身力量与机智的部落冒险者，都能参加梅洛的试炼。试炼始于猎人高地，考验追踪者应有的品质。",al={"这是猎人任务吗","其他职业能做吗"}}},fp="16,200,26.262.0,20.265.0,23.211.0,26.190.0,33.116.0,35.172.0,52.181.0,36.160.0"}
P.entries["quest:1131"] = {n="钢齿土狼",s="在千针石林，梅洛·石蹄派你猎杀一头土狼，它的族群令野生动物惶恐不安。猎杀钢齿土狼的理由，与牛头人通常夺取生命的缘由不同。",h="在千针石林，梅洛·石蹄派你猎杀一头土狼，它的族群令野生动物惶恐不安。猎杀钢齿土狼的理由，与牛头人通常夺取生命的缘由不同。",kw={"伊索克营地","大地母亲","猎人高地","土狼","梅洛·石蹄","钢齿土狼","千针石林","雷霆崖"},ang={["class:Hunter"]="猎杀钢齿土狼考验着你的追踪本领，看你能否从游荡在峡谷底部的土狼中找出这头凶残的族群首领。",["faction:Horde"]="在千针石林开辟一条更安全的道路，能保护补给线，以及从贫瘠之地前往闪光平原的旅人。",["race:Tauren"]="对Shu'halo而言，夺取野兽的生命有着灵性上的分量。猎杀钢齿土狼让你学会剔除这样一种生物：它的残暴已超出了Earthmother的恩典所及。"},sec={{t="祝福之外的狩猎",b="牛头人猎人夺取生命，是为了生计、荣誉，或是从大地母亲那里获得智慧。梅洛·石蹄请你猎杀钢齿土狼，却是出于另一个原因。这头土狼被视为自然平衡的威胁，它带来无谓的暴力与恐惧，而非维系生命的循环。"},{t="石林之祸",b="钢齿土狼游荡在千针石林北部的峡谷中，就在半人马聚居的伊索克营地以南。凶猛的土狼追随着它，一同袭击峡谷底部较为温顺的野生动物。杀死钢齿土狼并带回它的肋骨，就能终结它对这片石林的控制。"}},faq={{q="梅洛·石蹄为什么要杀死钢齿土狼？",a="梅洛·石蹄要杀死钢齿土狼，是因为它以无谓的暴力威胁着自然平衡。牛头人的狩猎通常是为了生计、荣誉，或是从大地母亲那里获得智慧；这次狩猎则是为了阻止它袭击野生动物。",al={"为何杀死钢齿土狼","梅洛·石蹄的理由","钢齿土狼狩猎动机"}},{q="在哪里能找到钢齿土狼？",a="钢齿土狼游荡在千针石林北部，就在半人马聚居的伊索克营地以南。",al={"钢齿土狼位置","钢齿土狼在哪里","寻找钢齿土狼"}},{q="必须带什么凭证回雷霆崖？",a="将钢齿土狼的肋骨带给雷霆崖猎人高地的梅洛·石蹄。",al={"钢齿土狼战利品","钢齿土狼任务目标","拾取什么"}},{q="钢齿土狼会独自作战吗？",a="不会。其他土狼追随着钢齿土狼，与它并肩作战。",al={"钢齿土狼是否独自作战","钢齿土狼的族群","钢齿土狼的随从"}},{q="这次狩猎与牛头人的传统狩猎有何不同？",a="牛头人的狩猎通常是为了生计、荣誉，或是从大地母亲那里获得智慧。这次狩猎则是为了阻止一头破坏自然平衡的捕食者。",al={"牛头人狩猎理念","大地母亲与狩猎","狩猎的教诲"}},{q="梅洛·石蹄住在哪里？",a="梅洛·石蹄住在雷霆崖的猎人高地，在那里指导猎人，并考验经验丰富的追踪者。",al={"梅洛·石蹄位置","梅洛在哪里","梅洛坐标"}}},fp="9,186,27.247.0,26.267.0,47.223.0,29.85.0,49.73.0,27.56.0,56.139.0,33.110.0"}
P.entries["quest:1132"] = {n="菲欧拉·长耳",s="这趟差事引领来自东部王国的联盟冒险者踏上卡利姆多这片荒野大陆。在米奈希尔港，热情的招募者红衣弗林特指引旅人乘船横渡无尽之海，前往塞拉摩的旅店，向他的高等精灵联络人菲欧拉·长耳报到。",h="这趟差事引领来自东部王国的联盟冒险者踏上卡利姆多这片荒野大陆。在米奈希尔港，热情的招募者红衣弗林特指引旅人乘船横渡无尽之海，前往塞拉摩的旅店，向他的高等精灵联络人菲欧拉·长耳报到。",kw={"塞拉摩","船","尘泥沼泽","菲欧拉·长耳","卡利姆多","米奈希尔港","红衣弗林特","湿地"},ang={["faction:Alliance"]="这段旅程是连接东部王国与卡利姆多暗夜精灵领地的桥梁，将联盟的东西两处边疆联结起来。",["race:NightElf"]="菲欧拉·长耳负责正式迎接抵达塞拉摩的东方盟友，帮助他们为踏入卡利姆多北部的古老荒野做好准备。"},sec={{t="西方的召唤",b="对许多人类、矮人和侏儒来说，东部王国充斥着积年的纷争，大地满目疮痍。在繁忙的米奈希尔港，水手红衣弗林特每天都在劝说富有冒险精神的旅人登船横渡无尽之海。弗林特将卡利姆多描绘成一片未经探索、充满财富与机遇的土地，并指引勇敢的旅人前往塞拉摩，去见他的伙伴，一位名叫菲欧拉·长耳的精灵。"},{t="抵达塞拉摩",b="旅人横渡大洋，抵达尘泥沼泽海岸上的联盟港口塞拉摩。菲欧拉·长耳在镇上的旅店里等候，接待经弗林特推荐而来的旅人。菲欧拉相信弗林特识人的眼光，欢迎初来乍到的联盟英雄，并准备指引他们深入内陆，前往灰谷的古老森林。"}},faq={{q="菲欧拉·长耳是谁？",a="菲欧拉·长耳是一位驻留在尘泥沼泽塞拉摩旅店中的高等精灵。她是红衣弗林特负责接待的伙伴和联络人，迎接从东部王国抵达的联盟旅人。",al={"菲欧拉·长耳","菲欧拉是谁"}},{q="这个任务由谁发起？",a="这个任务由红衣弗林特提供，他是一位精力充沛的人类水手，身在湿地海岸的米奈希尔港。",al={"任务给予者","菲欧拉·长耳任务在哪接","谁提供任务"}},{q="如何从米奈希尔港前去寻找菲欧拉·长耳？",a="登上停靠在米奈希尔港的客船，向西横渡无尽之海，便可直达尘泥沼泽的塞拉摩。",al={"如何前往塞拉摩","前往塞拉摩的船","从米奈希尔出发的船"}},{q="见到菲欧拉·长耳后会发生什么？",a="菲欧拉在塞拉摩迎接你时，会称赞弗林特的推荐，并交给你下一段旅程的任务，派你深入内陆，前往灰谷的阿斯特兰纳。",al={"后续任务","前往阿斯特兰纳任务"}},{q="红衣弗林特和菲欧拉·长耳是什么关系？",a="弗林特称菲欧拉为他在大洋彼岸的伙伴。弗林特在东部王国物色热切的冒险者，菲欧拉则在卡利姆多接待他们，为联盟的行动和深入内陆的旅程提供便利。",al={"弗林特和菲欧拉是伙伴吗","红衣弗林特与菲欧拉的关系"}},{q="联盟为何招募旅人前往卡利姆多？",a="对联盟而言，卡利姆多意味着广阔的新领土和资源，也是一处前线，暗夜精灵盟友需要援助，以保护祖传的土地，抵御部落和恶魔残余势力等威胁。",al={"为何前往卡利姆多","为何前往塞拉摩"}}},fx={["869cd7aa"]={q="红衣弗林特为什么想派你去卡利姆多？",a="红衣弗林特自视为机遇的引路人，负责鼓励米奈希尔港那些前途无量的冒险者横渡无尽之海。他自己被困在码头，满心渴望出海远航，因此肩负的职责便是寻找坚韧可靠的人，并指引他们去找高等精灵伙伴菲欧拉·长耳。她会帮助新来者站稳脚跟，投身联盟在卡利姆多日益扩大的行动。",al={"红衣弗林特的动机","为什么派我去找菲欧拉","弗林特为什么想让你完成这件事"}}},fp="14,159,18.349.0,20.321.0,22.174.0,22.117.0,51.112.0,42.149.0,67.190.0,53.182.0"}
P.entries["quest:1133"] = {n="通往阿斯特兰纳的旅途",s="菲欧拉·长耳指引联盟旅人从塞拉摩北上，前往阿斯特兰纳。他们将在那里向辛德瑞尔·速火报到，灰谷的暗夜精灵正面临战乱与动荡。",h="菲欧拉·长耳指引联盟旅人从塞拉摩北上，前往阿斯特兰纳。他们将在那里向辛德瑞尔·速火报到，灰谷的暗夜精灵正面临战乱与动荡。",kw={"灰谷","阿斯特兰纳","塞拉摩","尘泥沼泽","菲欧拉·长耳","前往阿斯特兰纳","米奈希尔港","辛德瑞尔·速火"},ang={["faction:Alliance"]="身为联盟新兵，你从尘泥沼泽相对安全的港口出发，进入灰谷战火纷争的荒野。",["race:Human"]="身为从米奈希尔港抵达的人类，你首次踏入卡利姆多内陆，履行联盟援助暗夜精灵的承诺。",["race:NightElf"]="身为暗夜精灵，你回到遭受围攻的故土，与异族盟友并肩守护灰谷的神圣林木。"},sec={{t="从海岸走入林间",b="联盟旅人乘坐来自米奈希尔港的渡船抵达尘泥沼泽，往往希望在卡利姆多北部找到自己的使命。在塞拉摩，菲欧拉·长耳指引有能力的人深入内陆，前往灰谷主要的暗夜精灵聚居地阿斯特兰纳。道路蜿蜒穿过古老幽暗的树冠下方，通向一片饱受战乱与动荡困扰的森林。"},{t="不留名的引荐",b="菲欧拉告诉旅人，到了阿斯特兰纳不要提起她的名字，因为辛德瑞尔·速火并不认识她。菲欧拉的职责是将联盟的新生力量引向需要他们的地方。辛德瑞尔欢迎前来效力的健壮守卫。灰谷依然美得令人屏息，却已不再是昔日那片宁静的庇护之地。"}},faq={{q="前往 阿斯特兰纳任务从哪里开始？",a="这段旅程始于尘泥沼泽海岸的塞拉摩，由菲欧拉·长耳指引。她将这项任务交给从东部王国而来、希望为卡利姆多出力的联盟旅人。",al={"谁提供 阿斯特兰纳之旅","阿斯特兰纳之旅起点","哪里接取 阿斯特兰纳之旅"}},{q="我需要在阿斯特兰纳与谁交谈？",a="与辛德瑞尔·速火交谈，她是一名暗夜精灵，身在灰谷的联盟中心城镇阿斯特兰纳。",al={"哪里交付 阿斯特兰纳之旅","阿斯特兰纳之旅交付 角色","辛德瑞尔·速火是谁"}},{q="菲欧拉为什么说不要提起她的名字？",a="菲欧拉说不要提起她的名字，因为辛德瑞尔并不认识她本人。她将热心的新来者指引到一处需要援助的前哨。",al={"为什么不能提起 菲欧拉","菲欧拉·长耳 与辛德瑞尔的关系"}},{q="这项任务的目的是什么？",a="这项任务引领联盟旅人从尘泥沼泽进入灰谷，让他们了解联盟在这片森林中的主要据点阿斯特兰纳。",al={"为什么做 阿斯特兰纳之旅","阿斯特兰纳之旅剧情目的"}},{q="灰谷正面临什么样的麻烦？",a="灰谷已不再安宁。部落的入侵、第三次大战遗留的恶魔腐化，以及因近期冲突而躁动的当地野生动物，都在困扰着这片森林。",al={"阿斯特兰纳为什么需要帮助","灰谷困境背景"}},{q="前往 阿斯特兰纳的前置任务是什么？",a="这段旅程承接一项名为菲欧拉·长耳的简短引导任务，指引抵达尘泥沼泽的旅人前往塞拉摩与她交谈。",al={"阿斯特兰纳之旅前置任务","菲欧拉·长耳 任务链"}}},fp="20,154,29.326.0,26.327.0,48.173.0,38.92.0,43.140.0,34.134.0,47.159.0,43.119.0"}
P.entries["quest:1134"] = {n="石爪山的双足飞龙",s="在石爪山脉，雄翼双足飞龙的毒液已威胁到岌岌可危的和平。辛德瑞尔转述了一则来自塞拉摩、尚未证实的消息，称兽人刺客正在收集这种毒液，用于秘密袭击。阿斯特兰纳的哨兵派出斥候南下，抢先夺取毒囊。",h="在石爪山脉，雄翼双足飞龙的毒液已威胁到岌岌可危的和平。辛德瑞尔转述了一则来自塞拉摩、尚未证实的消息，称兽人刺客正在收集这种毒液，用于秘密袭击。阿斯特兰纳的哨兵派出斥候南下，抢先夺取毒囊。",kw={"刺客","阿斯特兰纳","暗色湖","雄翼双足飞龙","辛德瑞尔·速火","石爪山脉","塞拉摩","毒液"},ang={["class:Druid"]="身为德鲁伊，你或许会为那些无辜的生灵感到悲伤，它们被杀，只为不让战争贩子得到它们的毒液。",["class:Rogue"]="身为潜行者，你知道在隐秘的伏击中，涂有pridewing毒液的刀刃会变得多么致命。",["faction:Alliance"]="身为联盟的盟友，你看到了塞拉摩隐秘的情报网如何支援灰谷的哨兵前哨，抵御部落的袭击。",["race:NightElf"]="身为暗夜精灵，尽管你爱护自然，却仍面临着艰难的抉择：杀死野生pridewings，以免它们的毒液落入敌人之手。"},sec={{t="脆弱的停战",b="联盟与部落尚未在卡利姆多北部公开宣战，但双方的和平十分脆弱。林冠之下，小规模冲突不断爆发，秘密袭击取代了大军交锋。阿斯特兰纳的哨兵指挥官密切关注敌人的动向，深知一时疏忽就可能让他们的庇护之地陷入险境。"},{t="峭壁间的毒液",b="辛德瑞尔转述了塞拉摩联络人传来的一则未经证实的消息，涉及石爪山峭壁间的活动。据说，兽人潜伏者正在暗色湖周围采集野生雄翼双足飞龙的毒液，将其涂在刀刃上，对联盟部队发动致命伏击。辛德瑞尔·速火派遣勇士前去杀死这些野兽，赶在部落密探之前夺取它们的毒囊。"},{t="痛苦的职责",b="辛德瑞尔·速火为下令杀死当地的野兽而痛心。暗夜精灵敬重卡利姆多的荒野，而这些生灵从未选择参与这场战争。然而，阿斯特兰纳的守卫不能任由敌人收集毒液、发动致命袭击，即使代价是这些野兽的生命。"}},faq={{q="双足飞龙是什么？",a="双足飞龙是与双足飞龙有亲缘关系的危险飞行野兽，身怀剧毒。它们在高耸的峭壁间筑巢，尤其常见于石爪山脉的暗色湖周围；它们的毒液使其成为致命的掠食者，也是一种备受追逐的毒药。",al={"雄翼双足飞龙是什么","雄翼双足飞龙背景故事","石爪山的雄翼双足飞龙"}},{q="联盟为什么要猎杀它们？",a="辛德瑞尔转述了一则未经证实的消息，称部落刺客正在收集双足飞龙的毒液，用来涂抹武器，秘密袭击联盟阵地。联盟猎杀这些野兽，是为了抢先夺取它们的毒囊，让部落无法得到这种毒药。",al={"为什么杀死雄翼双足飞龙","任务目的","联盟与雄翼双足飞龙毒液"}},{q="是谁提供了兽人刺客的情报？",a="警告来自潜伏在塞拉摩的联盟线人，他们监视着南贫瘠之地和石爪山各处的部落动向与补给线。",al={"谁警告了联盟","塞拉摩间谍情报","辛德瑞尔情报来源"}},{q="暗色湖在哪里？",a="暗色湖位于石爪山脉北部，就在从灰谷延伸而来的边境小径以南。",al={"暗色湖位置","雄翼双足飞龙在哪里","寻找雄翼双足飞龙"}},{q="联盟与部落在灰谷公开交战了吗？",a="联盟与部落尚未在灰谷公开宣战，但林冠之下，秘密暗杀、资源争夺和边境冲突仍在继续。",al={"部落与联盟开战了吗","灰谷战况","灰谷和平条约"}},{q="辛德瑞尔·速火如何看待杀死这些野兽？",a="辛德瑞尔·速火不得不下令杀死那些未曾在冲突中选择任何一方的野兽，这让她十分悲痛。作为守卫阿斯特兰纳的军官，她认为这场狩猎是保护族人所必需的痛苦抉择。",al={"辛德瑞尔的反应","德鲁伊的愧疚","暗夜精灵杀死野兽"}}},fp="24,261,15.312.0,21.387.0,14.290.0,20.223.0,33.234.0,54.153.0,33.105.0,52.159.0,59.203.0"}
P.entries["quest:1135"] = {n="风巢双足飞龙的毒囊",s="塞拉摩的菲欧拉·长耳委托联盟冒险者向西前往千针石林的峡谷。那里，风巢高耸的峭壁之上栖息着危险的双足飞龙，它们的毒液效力极强，备受追捧。",h="塞拉摩的菲欧拉·长耳委托联盟冒险者向西前往千针石林的峡谷。那里，风巢高耸的峭壁之上栖息着危险的双足飞龙，它们的毒液效力极强，备受追捧。",kw={"尘泥沼泽","菲欧拉","风巢","长耳","塞拉摩","千针石林","毒液","双足飞龙"},ang={["class:Rogue"]="潜行者自然懂得奇异毒素那阴暗的诱惑。采集纯净、未经提炼的双足飞龙毒液，能让他们切身领会卡利姆多最致命的生物毒素。",["faction:Alliance"]="踏入千针石林，联盟冒险者便深入了敌后，置身于部落牛头人和兽人巡逻队警惕的目光之下。",["race:NightElf"]="对 kaldorei 而言，派遣猎手深入千针石林干旱的荒野，足见贸易利益与奇异材料的影响远远超出了灰谷和黑海岸。"},sec={{t="利润丰厚的远征",b="旅人在海岛港口塞拉摩歇脚时，可能会遇见菲欧拉·长耳。兽人常常捕捉并驯养双足飞龙作为飞行坐骑，而菲欧拉则指出了另一桩隐秘得多的买卖：这些生物的致命毒液。在卡利姆多的某些买家眼中，新鲜毒囊的价值远胜于双足飞龙本身，因此菲欧拉开始招募愿意跋涉远路、攀登险峰的猎手。"},{t="风巢的峭壁",b="这些猎物在尘泥沼泽以西、千针石林高耸的砂岩台地间筑巢。在名为风巢的栖息地，当地双足飞龙的毒液异常浓烈。要抵达它们的巢穴，猎手必须穿过敌对的部落领地，攀越险峻的地形，杀死双足飞龙并取出完整的毒囊，再将战利品带回塞拉摩。"}},faq={{q="这个任务要找的双足飞龙在哪里？",a="双足飞龙栖息在风巢，那是一座位于千针石林西部的高耸台地，在塞拉摩以西。",al={"风巢位置","风巢在哪里","双足飞龙位置"}},{q="菲欧拉·长耳是谁？",a="菲欧拉·长耳是驻留在尘泥沼泽近海的塞拉摩的一名联盟联络人。她招募勇敢的冒险者，从卡利姆多各地收集稀有而珍贵的天然材料。",al={"菲欧拉·长耳","谁提供 风巢毒液 任务"}},{q="双足飞龙的毒液为何如此珍贵？",a="双足飞龙的毒液效力极强，在某些地下圈子、药剂师和贸易网络中备受追捧。部落主要看重双足飞龙作为飞行坐骑的用途，而它们的毒腺在炼金师和制毒者之间能卖出高价。",al={"为何需要双足飞龙毒液","双足飞龙毒液用途"}},{q="为什么塞拉摩的任务要让我去那么远的西边？",a="菲欧拉是个颇有生意头脑的商人，正在寻找塞拉摩周边沼泽中没有的奇异标本。千针石林的风巢栖息着一种独特的双足飞龙，其毒液浓烈，在尘泥沼泽无处可寻。",al={"为何前往千针石林","为何派往千针石林"}},{q="交回毒囊后会发生什么？",a="菲欧拉检查毒囊，发现里面装满了毒液，并表示这样上乘的毒囊通常只来自年轻的双足飞龙或具有繁殖能力的雌性，随后祝贺你狩猎成功。",al={"菲欧拉 的反应","风巢毒液 任务完成"}},{q="联盟旅人前往风巢安全吗？",a="不安全。千针石林有大量部落势力，主要集中在附近的乱风岗等定居点周围。攀登风巢意味着既要应对野生掠食者，也要提防敌对的部落斥候。",al={"风巢危险吗","千针石林的联盟"}}},fx={["9e43b6cb"]={q="菲欧拉·长耳为什么想让你完成这件事？",a="菲欧拉善于发现有利可图的交易和稀有试剂。大多数人只知道双足飞龙是部落驯养的坐骑，她却知道有些人愿意为强效毒液付出高价。采集风巢的毒囊能让她在这些专门的市场上大赚一笔。",al={"菲欧拉为什么要毒液","菲欧拉·长耳的动机","为什么采集双足飞龙毒液"}},ef763353={q="风巢双足飞龙的毒囊有什么用？",a="毒囊里装着栖息在千针石林高处的野生双足飞龙所拥有的致命强效毒液。精选的炼金师、施毒者和异域货商都极为看重这些毒囊，因此在经营稀有危险生物的市场上，它们能卖出天价。",al={"风巢双足飞龙毒囊有什么用","毒囊用途","为什么收集毒囊"}},f9186ab4={q="栖息在风巢的是什么生物？",a="风巢是千针石林中一座高耸的台地，也是当地双足飞龙野生栖息的巢穴。这些长着翅膀的掠食者桀骜不驯，领地意识极强，会在沙漠峡谷间滑翔，用带毒的尾刺击倒猎物，再把猎物拖回岩石巢穴。",al={"风巢双足飞龙是什么","在风巢要猎杀什么","风巢有什么生物"}}},fp="15,160,22.298.0,22.319.0,43.91.0,22.178.0,32.202.0,48.161.0,44.175.0,41.169.0"}
P.entries["quest:1136"] = {n="霜喉雪人",s="奥特兰克山脉中一只罕见的雪人，让你踏上远离家乡的狩猎之旅。梅洛·石蹄派你猎杀霜喉雪人，并在雷霆崖等你带回它的鬃毛。",h="奥特兰克山脉中一只罕见的雪人，让你踏上远离家乡的狩猎之旅。梅洛·石蹄派你猎杀霜喉雪人，并在雷霆崖等你带回它的鬃毛。",kw={"奥特兰克山脉","霜喉雪人","鬃毛","梅洛·石蹄","卷轴","雷霆崖","雪人"},sec={{t="远方的狩猎",b="梅洛·石蹄派你远离家乡，前往奥特兰克山脉猎杀霜喉雪人。这只雪人浑身雪白，与山间积雪融为一体，很少现身。梅洛给了你一份卷轴，上面说明了如何引出它。将霜喉雪人的鬃毛带回雷霆崖，交给梅洛，你的旅程便告完成。"}},faq={{q="霜喉雪人是谁？",a="霜喉雪人是奥特兰克山脉中的一只雪人。它浑身雪白，与积雪融为一体，很少现身。",al={"霜喉雪人是谁","霜喉雪人是什么"}},{q="在哪里能找到霜喉雪人？",a="你可以在奥特兰克山脉找到霜喉雪人，它雪白的皮毛与那里的积雪融为一体。",al={"霜喉雪人位置","霜喉雪人在哪里"}},{q="如何引出霜喉雪人？",a="梅洛·石蹄会给你一份卷轴，上面说明了如何引出霜喉雪人。",al={"引出霜喉雪人","霜喉雪人卷轴"}},{q="梅洛想从霜喉雪人身上得到什么？",a="梅洛·石蹄要你把霜喉雪人的鬃毛带到雷霆崖交给他。",al={"梅洛 霜喉雪人","霜喉雪人鬃毛"}}},fp="8,146,14.310.0,16.104.0,26.90.0,23.73.0,35.76.0"}
P.entries["quest:1137"] = {n="回复菲兹尔",s="荒芜之地的流放者马特克有关于 精铁 的消息要告诉菲兹尔·铜栓。你将马特克的口信带回千针石林的闪光平原。",h="荒芜之地的流放者马特克有关于 精铁 的消息要告诉菲兹尔·铜栓。你将马特克的口信带回千针石林的闪光平原。",kw={"荒芜之地","菲兹尔·铜栓","精铁","精铁矿石","流放者马特克","沙漠赛道","闪光平原","千针石林","奥达曼"},sec={{t="马特克关于 精铁 的消息",b="马特克说，精铁 的耐热性极佳，他认为这种材料适合用来制作菲兹尔·铜栓的活塞。不过，碎片可不行：菲兹尔·铜栓需要真正的 精铁矿石，必须从荒芜之地北部边缘的奥达曼深处开采，马特克说那里才是 精铁 的真正来源。马特克请你向菲兹尔·铜栓问好，并将这些消息全都转告给他。"},{t="菲兹尔·铜栓听到了消息",b="菲兹尔·铜栓急切地想知道马特克说了什么，以及马特克能否帮上忙。当你讲述在荒芜之地的经历时，菲兹尔·铜栓断言，精铁 就是关键。"}},faq={{q="这段旅程从哪里开始，又在哪里结束？",a="荒芜之地的流放者马特克交给你一份口信，你将它带给千针石林闪光平原沙漠赛道的菲兹尔·铜栓。",al={"回复菲兹尔 任务给予者","回复菲兹尔 交任务地点","马特克 到菲兹尔·铜栓"}},{q="马特克给菲兹尔·铜栓捎来了什么消息？",a="马特克说，精铁 的耐热性极佳，应该适合用来制作菲兹尔·铜栓的活塞。菲兹尔·铜栓需要的是真正的矿石，而非碎片，而且必须从奥达曼深处开采。",al={"马特克 说了什么","精铁 消息","马特克 的口信"}},{q="精铁矿石来自哪里？",a="马特克说，这种矿石开采自荒芜之地北部边缘的奥达曼深处，他称那里是 精铁 的真正来源。",al={"精铁矿石在哪里","精铁矿石来源"}},{q="这一步在任务线中处于什么位置？",a="这一步接在 精铁碎片 之后，属于菲兹尔·铜栓派你去找流放者马特克时开始的任务链。",al={"回复菲兹尔 任务链","回复菲兹尔 前置任务"}}},fp="15,170,25.333.0,21.164.1,38.142.0,37.150.0,34.135.0,42.99.0"}
P.entries["quest:1138"] = {n="海中的水果",s="在黑海岸，奥伯丁的渔夫古博·布拉普请你收集蟹肉。他守在码头上，满心想着用渔获做成各种菜肴。",h="在黑海岸，奥伯丁的渔夫古博·布拉普请你收集蟹肉。他守在码头上，满心想着用渔获做成各种菜肴。",kw={"奥伯丁","黑海岸","硬壳潮行蟹","优质蟹肉","海中的水果","古博·布拉普","暗礁蟹"},ang={["faction:Alliance"]="身为联盟旅人，你可以经由奥伯丁抵达卡利姆多。这座港口是联盟探险者的登陆枢纽，你也可以帮助当地渔夫安顿下来。",["profession:Cooking"]="古博兴致勃勃地列举着蟹肉菜肴，或许会让你也想充分利用当地海岸的渔获。",["race:Dwarf"]="身为矮人，当你听到卡利姆多北部的一位外乡人憧憬着铁炉堡 surprise crab 时，或许会感到一丝熟悉的家乡气息。你以卡兹莫丹巡山人的身份行走四方。"},sec={{t="对甲壳类的热爱",b="古博·布拉普在奥伯丁的长木栈桥上垂钓，心里惦记着蟹肉。他说螃蟹才是海洋真正的馈赠，想象着烘烤、烧烤或水煮的种种做法。他的食谱包括 鞭根蟹 和铁炉堡 惊喜蟹。"},{t="搜寻潮池",b="古博放不下鱼竿，便请你到黑海岸的沙滩上收集食材。暗礁蟹 和 硬壳潮行蟹 在碎浪间爬行，为海边的厨师提供蟹肉。收集优质蟹肉时，要小心它们的钳子。"}},faq={{q="谁提供海中的水果任务？",a="黑海岸奥伯丁码头上的联盟渔夫古博·布拉普会向你提出请求。",al={"海中的水果 任务提供者","谁提供 海中的水果","古博·布拉普任务"}},{q="哪些生物掉落优质蟹肉？",a="黑海岸沿岸和浅水浪区的 暗礁蟹 和 硬壳潮行蟹 会掉落优质蟹肉。",al={"优质蟹肉掉落地点","什么掉落蟹肉","哪些螃蟹掉落优质蟹肉"}},{q="古博为什么不自己收集蟹肉？",a="古博忙着在奥伯丁的栈桥上钓鱼，无法放下鱼线，到沙滩上捕蟹。",al={"古博为什么不自己捕蟹","古博为什么需要帮助"}},{q="古博想做哪些菜肴？",a="古博提到了蟹肉沙拉、蟹肉汤、炖蟹、胡椒蟹、柠檬蟹、鞭根蟹，还有一道他称为铁炉堡 惊喜蟹 的地方菜。",al={"古博的蟹肉食谱","古博提到哪些食谱","蟹肉菜肴"}},{q="古博·布拉普的话是否引用了什么典故？",a="是的。古博列举蟹肉菜肴的这番话，呼应了电影 阿甘正传 中 本杰明·布福德‘布巴’布鲁 的台词，据称与那段介绍虾的台词如出一辙。",al={"古博·布拉普流行文化典故","阿甘正传布巴 典故"}},{q="这个任务发生在哪里？",a="任务在港口村庄奥伯丁开始，也在那里结束，而你要沿着卡利姆多北部的黑海岸海滨捕蟹。",al={"海中的水果 在哪里","海中的水果 所在区域"}}},fx={cf4b2535={q="优质蟹肉有什么用？",a="古博·布拉普打算用它们制作种类繁多的菜肴。在他看来，螃蟹就是海中的珍果，适合烘烤、烧烤、水煮、焙烤、油炸，也可以加入汤、炖菜和沙拉。",al={"优质蟹肉用途","为什么要优质蟹肉","古博拿蟹肉做什么"}},["82492fa1"]={q="黑海岸沿岸的爬行者是什么？",a="礁石爬行者和硬壳潮汐爬行者是当地的甲壳类生物，在黑海岸漫长而雾气弥漫的海岸线和浅滩潮池中觅食。它们会伤害粗心的海滩漫步者，但渔夫和古博·布拉普这样的厨师很看重它们的肉，常用来烹制丰盛的海岸佳肴。",al={"礁石爬行者是什么","黑海岸硬壳潮汐爬行者","黑海岸螃蟹"}}},fp="16,137,25.231.0,21.253.0,37.80.0,41.107.0,48.99.0,37.134.0,47.150.0,33.115.0"}
P.entries["quest:114"] = {n="梅贝尔的隐形水",s="梅贝尔·马科伦想找个办法离开家人，去见托米·乔·斯通菲尔德。你为她带来了威廉·匹斯特用从这一带采集的水晶海藻酿制的隐形水。",h="梅贝尔·马科伦想找个办法离开家人，去见托米·乔·斯通菲尔德。你为她带来了威廉·匹斯特用从这一带采集的水晶海藻酿制的隐形水。",kw={"艾尔文森林","隐形水","马科伦农场","梅贝尔·马科伦","斯通菲尔德农场","逃跑","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="作为一名从艾尔文森林起步的联盟冒险者，帮助托米·乔和梅贝尔，能让你在对抗迪菲亚匪徒和豺狼人的战斗间隙轻松片刻。即使在暴风城附近，乡间的积怨也依然存在。",["race:Human"]="作为艾尔文的人类，你知道家族间的顽固积怨根深蒂固。邻里之间暗中施以小小的援手，有助于维持安宁。"},sec={{t="为真爱调制的药剂",b="马科伦家族和斯通菲尔德家族世代结怨，容不得儿女相恋。米莱德·斯通菲尔德向闪金镇狮王之傲旅店的炼金师威廉·匹斯特求助。附近湖中的水晶海藻为匹斯特提供了酿制隐形水所需的材料。这种药水能让梅贝尔悄悄逃离马科伦家的农庄。"},{t="隐入林间",b="梅贝尔·马科伦接过药瓶，悄悄走进树林，去找托米·乔。欺骗亲人的愧疚令她不安，但爱意压过了被发现的恐惧。她喝下隐形水，在你眼前消失了。如今，她终于能避开两家结怨长辈的监视，与托米·乔短暂相聚。"}},faq={{q="谁会给予梅贝尔的隐形水任务？",a="威廉·匹斯特是闪金镇狮王之傲旅店的药剂师兼炼金助手，你把水晶海藻交给他后，他会给你隐形水。",al={"逃跑任务给予者","谁开启逃跑","哪里接取逃跑"}},{q="隐形水有什么用途？",a="隐形水能让梅贝尔·马科伦隐身足够长的时间，离开自家的农场，去探望托米·乔·斯通菲尔德，而不至于激怒亲人。",al={"为什么用隐形水","药水有什么效果","隐形水用途"}},{q="为什么梅贝尔和托米·乔必须隐瞒恋情？",a="马科伦家族和斯通菲尔德家族是死对头，两家积怨极深，不容许儿女公开相恋。",al={"为什么要躲藏","斯通菲尔德与马科伦的仇怨","为什么梅贝尔和托米·乔不能在一起"}},{q="把药水交给梅贝尔后会发生什么？",a="梅贝尔向你道谢，心中既愧疚又激动，随后喝下药水。她在你眼前消失，悄悄离开，去找托米·乔。",al={"最后发生什么","梅贝尔会消失吗","逃跑任务完成"}},{q="哪个任务直接引出梅贝尔的隐形水？",a="梅贝尔的隐形水接续收集海藻。在那个任务中，你从水晶湖的鱼人身上收集水晶海藻，交给威廉·匹斯特酿制隐形药水。",al={"逃跑前置任务","逃跑之前的任务","什么任务引出逃跑"}},{q="这个任务会化解两家的仇怨吗？",a="不会。药水只能让这对恋人短暂地秘密相聚。米莱德·斯通菲尔德与马科伦家族之间的深仇依然未解。",al={"两家会和好吗","仇怨结束了吗","仇怨会结束吗"}}},fx={["245b9158"]={q="威廉·匹斯特为什么帮助 托米·乔 和梅贝尔？",a="威廉·匹斯特是一位药剂师，愿意出于同情向年轻恋人伸出援手。米莱德·斯通菲尔德给他送来一张便条，请他想办法绕过斯通菲尔德和马科伦两家的深仇，他便答应，只要拿到水晶海藻，就调制一批隐形水。他并无私利可图，只想帮助这对命途多舛的恋人秘密相会，免得他们彼此敌视的亲人又打上一架。",al={"威廉 为何帮忙","威廉·匹斯特的动机","为何帮助 梅贝尔 逃走"}},["53ceb805"]={q="威廉·匹斯特为什么派你去送隐形水，而不亲自送去？",a="威廉在闪金镇的狮王之傲旅店经营着一家生意繁忙的店铺，难以放下生意，穿过森林四处跑腿。更重要的是，如果他带着可疑的炼金药剂走进马科伦农场，立刻就会引起梅贝尔那些护着她的亲属的怀疑。你是个四处游历的冒险者，已经替这对恋人传过消息，也收集了材料，可以悄悄进入农场，把药剂交给她。",al={"威廉 为何派人前往","为何由我递送隐形水","威廉 为何不能送药水"}}},fp="10,183,26.338.0,24.305.1,31.151.0,41.162.0,61.129.0,52.139.1,42.147.0,54.144.1"}
P.entries["quest:1140"] = {n="奥萨拉克斯之塔",s="德尔格伦讨伐奥萨拉克斯之塔教徒的行动已进入第六章。他在迈斯特拉岗哨破译了从教派使者身上搜出的兽人文字，得知埃瑟里克斯·纳拉辛将两颗囚禁着上层精灵灵魂的宝石藏在灰谷深处的萨特据点。勇士们前往夜道谷和萨提纳尔，击碎这些容器，解放受尽折磨的灵魂，削弱埃瑟里克斯的力量。",h="德尔格伦讨伐奥萨拉克斯之塔教徒的行动已进入第六章。他在迈斯特拉岗哨破译了从教派使者身上搜出的兽人文字，得知埃瑟里克斯·纳拉辛将两颗囚禁着上层精灵灵魂的宝石藏在灰谷深处的萨特据点。勇士们前往夜道谷和萨提纳尔，击碎这些容器，...",kw={"奥萨拉克斯","灰谷","埃瑟里克斯","德尔格伦","上层精灵","迈斯特拉岗哨","夜道谷","萨提纳尔","灵魂宝石"},ang={["class:Paladin"]="净化者德尔格伦是一位务实的神圣讨伐者，他研习敌人的语言，以揭露恶魔腐化，净化受尽折磨的亡魂。",["class:Priest"]="摧毁禁锢法阵，能让遭受了数百年恶魔折磨的灵魂得到安宁。",["race:NightElf"]="身为暗夜精灵，将上层精灵先祖从萨特的亵渎中解救出来是一项庄严的职责，也让你直面族人远古历史留下的悲剧残迹。"},sec={{t="破译潦草的文字",b="兽人信使伊克鲁德·玛格苏尔被击杀后，净化者德尔格伦对兽人语的研习终于派上了用场。信奉圣光的同僚常常嘲笑他学习敌人的语言，但德尔格伦务实的远见让他得以破译从教派使者身上搜出的笔记。笔记揭示，埃瑟里克斯·纳拉辛将两颗蕴藏远古上层精灵精魄的强大灵魂宝石，藏在遥远东北方夜道谷和萨提纳尔遭到亵渎的林地中。"},{t="邪恶的同盟",b="萨特营地中的灵魂宝石揭露了埃瑟里克斯的密党与燃烧军团的恶魔后裔之间的邪恶同盟。远古灵魂被束缚在禁锢法阵上方，在无尽的折磨中为黑暗法术提供力量。浸透鲜血的萨特祭坛蕴藏着狂乱的恶魔腐化之力，而发誓守护这些奥术导体的萨特潜伏者则隐匿在暗影之中。"},{t="削弱埃瑟里克斯",b="击碎血红色的宝石，将上层精灵的灵魂从痛苦法阵中解放出来，沉重打击了埃瑟里克斯积蓄的神秘力量。德尔格伦说，失去灵魂宝石后，奥萨拉克斯教派首领的力量已大为削弱。此事过后，暗夜精灵对萨特流露出的沉默不安令这位神圣的讨伐者心神难宁，他决意向奥伯丁的领袖报告这股挥之不去的恶魔腐化。"}},faq={{q="德尔格伦为什么能读懂兽人语？",a="德尔格伦主动研习了兽人语，尽管他所属的神圣教团中有人为此嘲笑他。他相信，掌握敌人的语言能够带来战术上的洞见，而这份知识让他得以翻译从伊克鲁德·玛格苏尔身上搜出的笔记。",al={"德尔格伦 读懂兽人语","德尔格伦 为什么懂兽人语","德尔格伦 翻译"}},{q="灵魂宝石是什么，为什么由萨特保管？",a="灵魂宝石是血红色的聚焦石，束缚着远古上层精灵的灵魂，悬浮在禁锢仪式的法阵上方。埃瑟里克斯·纳拉辛通过交易将它们交给萨特，或将它们安置在夜道谷和萨提纳尔这样的庇护所，让灵魂的苦难为教派提供奥术力量。",al={"奥萨拉克斯 灵魂宝石","萨特为什么持有宝石","受困的 上层精灵 灵魂"}},{q="夜道谷和萨提纳尔在哪里？",a="夜道谷和萨提纳尔是灰谷东北部林木茂密的高地上的萨特据点，位于迈斯特拉岗哨以东。",al={"夜道谷在哪里","萨提纳尔在哪里","萨特营地位置"}},{q="暗夜精灵为什么不愿谈论萨特？",a="德尔格伦注意到，接待他的精灵们回避谈论萨特，因为萨特曾经也是暗夜精灵。在远古的 上古之战 期间，他们屈从于恶魔的腐化，扭曲成了长着羊腿的恶魔，成为 卡多雷 心中长久的悲痛与耻辱。",al={"为何对萨特讳莫如深","暗夜精灵与萨特的关系","萨特的精灵历史"}},{q="解放这些灵魂如何帮助阻止奥萨拉克斯之塔教派？",a="埃瑟里克斯·纳拉辛汲取上层精灵灵魂宝石中储存的灵魂能量，为自己的仪式提供力量。击碎宝石便能释放受困的灵魂，切断这些仪式的力量来源，使他在高塔遭到进攻时无力抵抗。",al={"为什么要击碎灵魂宝石","埃瑟里克斯 力量来源","削弱 埃瑟里克斯"}},{q="德尔格伦提到要去交谈的 艾莉萨 是谁？",a="艾莉萨·星风是一位驻守奥伯丁的重要暗夜精灵哨兵，负责协调黑海岸当地的防务。德尔格伦打算与她商议盘踞在卡利姆多北部的萨特威胁。",al={"艾丽莎 奥伯丁","艾丽莎 是谁","德尔格伦艾丽莎"}}},fp="22,362,27.448.0,16.354.1,18.407.1,41.227.0,54.268.0,42.115.0,59.276.0,67.226.0,48.215.0"}
P.entries["quest:1141"] = {n="钓鱼世家",s="古博·布拉普带着祖传的鱼竿，在奥伯丁的码头上静候鱼儿上钩。凶恶的鱼人让镇上的小渔船无法出海，因此古博寻求帮助，希望有人能从岸边钓来当地的黑海岸石斑鱼。",h="古博·布拉普带着祖传的鱼竿，在奥伯丁的码头上静候鱼儿上钩。凶恶的鱼人让镇上的小渔船无法出海，因此古博寻求帮助，希望有人能从岸边钓来当地的黑海岸石斑鱼。",kw={"奥伯丁","布拉普家族鱼竿","黑海岸石斑鱼","钓鱼","格劳恩·布拉普","古博·布拉普","鱼人","迷雾之海"},ang={["faction:Alliance"]="身为联盟的一员，你会发现，奥伯丁的港口将大陆各族与暗夜精灵聚在一起，共同应对鱼人等沿海威胁。",["profession:Cooking"]="在卡利姆多北部沿海，黑海岸石斑鱼是一种来源稳定、营养丰富的渔获，也是边境营地餐桌上的主食。",["race:Dwarf"]="身为矮人，遇见一位醉心垂钓，而非在地下打铁或酿酒的同胞，会让你想起矮人的志趣有多么丰富。"},sec={{t="远离铁炉堡的矮人",b="古博·布拉普的家族以精湛的垂钓技艺闻名，他引以为傲。奥伯丁的居民大多是暗夜精灵，不过也有矮人和侏儒在码头与港口一带定居。古博每天眺望迷雾之海，而非开凿岩石，盼着钓上当地的鱼。"},{t="鱼人肆虐与黑海岸石斑鱼",b="黑海岸石斑鱼在沿岸水域繁衍，能做成各种食物，但上钩后也会奋力挣扎。当地渔民通常划着小船，到更深的水域捕捞它们。如今，凶恶的鱼人在海岸游荡，小船也不再出海。古博担心这些生物正在吞食当地的鱼，于是请旅人从岸边垂钓。"},{t="布拉普的传承",b="谁能带回丰厚的渔获，古博就会送给谁一根布拉普家族鱼竿。他相信，能钓上一批活蹦乱跳的石斑鱼的人，足以与家族中的传奇钓手比肩，其中就包括他的表亲格劳恩·布拉普。对古博来说，赠出一根家传鱼竿，是表达敬意的最高方式。"}},faq={{q="古博·布拉普是谁？",a="古博·布拉普是黑海岸奥伯丁码头上的一名矮人渔夫。他出身于一个引以为傲的垂钓世家，传授基础钓鱼技巧，还会把家族特有的鱼竿送给有潜力的渔夫。",al={"古博是谁","古博·布拉普的故事","奥伯丁矮人渔夫"}},{q="奥伯丁的渔船为什么不出海捕鱼？",a="凶恶的鱼人在黑海岸的大片海岸线上游荡，小渔船出海太过危险。当地钓手只能留在码头和浅滩一带。",al={"为什么没有船出海","黑海岸渔船","奥伯丁船只困境"}},{q="黑海岸石斑鱼是什么？",a="黑海岸石斑鱼是黑海岸近海的一种本地咸水鱼。钓手看重它上钩后奋力挣扎的劲头，也珍视它在丰盛的海滨菜肴中的用途。",al={"黑海岸石斑鱼","石斑鱼 黑海岸"}},{q="格劳恩·布拉普是谁？",a="格劳恩·布拉普是古博的表亲，据他描述，她长着浓密的胡须，身上还有一股刺鼻的气味。他将她视为家族有史以来最出色的钓手之一。",al={"格劳恩·布拉普","古博的表亲"}},{q="奥伯丁这样的暗夜精灵城镇为什么会有矮人？",a="第三次战争结束、联盟建立后，来自铁炉堡的矮人和侏儒渡海抵达卡利姆多。他们前来开展贸易，建立海上联系，并帮助新的暗夜精灵盟友建设港口设施。",al={"奥伯丁为什么有矮人","黑海岸的矮人"}},{q="布拉普家族鱼竿是什么？",a="布拉普家族鱼竿是布拉普氏族使用的一种结实鱼竿。古博会把这些珍贵的鱼竿送给在黑海岸水域证明了垂钓本领的旅人。",al={"布拉普 鱼竿","布拉普 家族鱼竿","古博奖励的鱼竿"}}},fp="31,211,26.291.0,41.345.0,16.296.0,20.203.0,50.162.0,28.156.0,19.152.0,57.221.0,38.170.0"}
P.entries["quest:1142"] = {n="临终遗言",s="赫尔拉斯·静水在剃刀沼泽中奄奄一息，向生者提出了最后的恳求。他希望有人将妻子被夺走的坠饰带到达纳苏斯，同时捎去他的死讯。",h="赫尔拉斯·静水在剃刀沼泽中奄奄一息，向生者提出了最后的恳求。他希望有人将妻子被夺走的坠饰带到达纳苏斯，同时捎去他的死讯。",kw={"达纳苏斯","法芬德尔","赫尔拉斯·静水","独眉","生命的凋零","结合坠饰","剃刀沼泽","塔莎拉·静水"},ang={["faction:Alliance"]="身为置身于部落主导的贫瘠之地的联盟勇士，你肩负着庄严而沉重的荣誉之责，将赫尔拉斯最后的信物送回达纳苏斯。",["race:Dwarf"]="身为矮人，你听到赫尔拉斯赞颂独眉的勇气，他带着紧急的警讯离开了野猪人要塞。",["race:NightElf"]="身为暗夜精灵，看到一位同胞在南贫瘠之地孤独地死去，无人记挂，你感到阵阵刺痛。"},sec={{t="荆棘中的最后一息",b="在剃刀沼泽，赫尔拉斯·静水身负致命重伤，倒在荆棘丛中。这座要塞远离联盟领地，盘踞着野蛮的野猪人，黑暗魔法肆虐其间。赫尔拉斯的力气渐渐消散，只能断断续续地低声说话。他说，一位名叫独眉的勇敢矮人已被派往前方，向法芬德尔示警。赫尔拉斯知道，自己无法活着离开剃刀沼泽。"},{t="定情坠饰",b="赫尔拉斯最后的心愿，是找回象征他与塔莎拉·静水婚姻的坠饰。巢穴中的一名暴徒从他身上夺走了它。他请求每一位在他身旁停下的旅人，带着坠饰穿越卡利姆多，前往达纳苏斯，让塔莎拉得知他的死讯，不再徒劳地等待。"},{t="达纳苏斯的悲恸",b="塔莎拉·静水在达纳苏斯收到了寻回的丈夫的坠饰，也得知了他的死讯。悲痛欲绝的她发誓，赫尔拉斯的事业不会随他一同消逝。突如其来的悲痛中，她只能独自哀悼，继承他的遗志。"}},faq={{q="赫尔拉斯·静水是谁？",a="赫尔拉斯·静水是一名隶属联盟的暗夜精灵，人们在剃刀沼泽发现他时，他已身负致命重伤。随着力气渐渐消散，他托付过路的旅人找回妻子被夺走的结合坠饰，并将他的死讯带到达纳苏斯。",al={"赫尔拉斯·静水","赫尔拉斯是谁","剃刀沼泽垂死的精灵"}},{q="赫尔拉斯·静水在哪里？",a="赫尔拉斯·静水倒在剃刀沼泽内，那是南贫瘠之地一座荆棘密布的野猪人要塞。",al={"赫尔拉斯位置","赫尔拉斯在哪里","哪里能找到赫尔拉斯"}},{q="独眉是谁？",a="独眉是赫尔拉斯在临终时提到的一位勇敢的矮人。赫尔拉斯说，独眉被派出荆棘丛，向法芬德尔警告剃刀沼泽中的危险。",al={"矮人独眉","独眉是谁","独眉的警告"}},{q="塔莎拉·静水是谁？",a="塔莎拉·静水是赫尔拉斯的妻子，住在达纳苏斯。她收到了寻回的坠饰，也得知了丈夫的死讯。",al={"塔莎拉·静水","塔莎拉是谁","赫尔拉斯的妻子"}},{q="结合坠饰是什么？",a="结合坠饰是一件信物，象征着赫尔拉斯与塔莎拉·静水的婚姻。赫尔拉斯死于剃刀沼泽之前，野猪人暴徒从他身上夺走了它。",al={"塔莎拉的坠饰","坠饰是什么","联结坠饰"}},{q="塔莎拉得知消息后有何反应？",a="塔莎拉伤心欲绝，哀叹这个世界的残酷。悲痛之中，她决心由自己继续赫尔拉斯的事业，随后请求独自哀悼。",al={"塔莎拉的反应","送达坠饰后会发生什么"}}},fp="15,159,28.347.0,22.279.0,18.229.1,28.227.0,38.110.0,17.165.0,28.133.0,31.160.0,36.168.1"}
P.entries["quest:1143"] = {n="奥萨拉克斯之塔",s="奥萨拉克斯之塔中的恶魔仪式正威胁着黑海岸北部。巴苏尔·影击指挥联盟进攻埃瑟里克斯·纳拉辛，这位古老的巫师在塔顶统领着邪教。",h="奥萨拉克斯之塔中的恶魔仪式正威胁着黑海岸北部。巴苏尔·影击指挥联盟进攻埃瑟里克斯·纳拉辛，这位古老的巫师在塔顶统领着邪教。",kw={"奥萨拉克斯","埃瑟里克斯","巴苏尔","黑海岸","恶魔","纳拉辛","暗影之击","术士"},ang={["class:Warlock"]="身为术士，埃瑟里克斯在奥萨拉克斯顶端施展的强大恶魔魔法，让你看到了肆意崇拜邪能的危险。",["faction:Alliance"]="身为联盟的一员，协助稳固黑海岸北部的安全，能够保障奥伯丁与更远地区之间的通行。",["race:NightElf"]="身为暗夜精灵，与埃瑟里克斯·纳拉辛对抗，让你想起了曾摧残你族人的奥术与恶魔腐化。"},sec={{t="攻入塔顶",b="在黑海岸北部，破败的奥萨拉克斯之塔掩藏着召唤恶魔的仪式。巴苏尔·影击在附近监视着高塔，意识到必须立即应对这一威胁。埃瑟里克斯·纳拉辛栖身于塔顶，这位古老的暗夜精灵术士在残破的塔顶之下主持着黑暗仪式。"},{t="决胜一击",b="埃瑟里克斯·纳拉辛受到忠诚术士的保护，他的黑暗魔法比山坡上的邪教徒更为危险。要接近他，你必须杀穿他的亲信队伍，并斩下他的头颅作为凭证。巴苏尔警告说，恶魔势力可能会重整旗鼓，但埃瑟里克斯的死让邪教失去了统领，也为黑海岸带来了宝贵的安宁。"}},faq={{q="埃瑟里克斯·纳拉辛是谁？",a="埃瑟里克斯·纳拉辛是一名古老的暗夜精灵术士，统领着奥萨拉克斯之塔中的邪教徒。他在黑海岸北部的废墟中主持黑暗召唤和恶魔仪式。",al={"埃瑟里克斯","埃瑟里克斯 是谁","奥萨拉克斯 的首领"}},{q="在哪里能找到埃瑟里克斯·纳拉辛？",a="埃瑟里克斯·纳拉辛栖身于奥萨拉克斯之塔的塔顶，由老练的术士和召唤出的仆从守卫着。",al={"埃瑟里克斯 在哪里","埃瑟里克斯 位置","奥萨拉克斯 顶端"}},{q="谁发布这个任务？",a="巴苏尔·影击是一名在奥萨拉克斯之塔脚下附近扎营的联盟斥候，他要求你杀死埃瑟里克斯。",al={"任务发布者","巴苏尔","巴苏尔·影击"}},{q="任务中提到的德尔格伦是谁？",a="净化者德尔格伦是附近的一位联盟盟友。他派你前去与巴苏尔协同行动，对抗那个恶魔教团。",al={"德尔格伦","净化者德尔格伦"}},{q="击败埃瑟里克斯后会发生什么？",a="埃瑟里克斯·纳拉辛的死重创了恶魔在这一地区的活动，不过巴苏尔警告说，黑暗势力可能会重整旗鼓。",al={"击败 埃瑟里克斯 之后","奥萨拉克斯之塔结局"}},{q="奥萨拉克斯之塔为何会威胁黑海岸？",a="塔内的邪教徒和术士施展邪能法术，将恶魔召唤到暗夜精灵的土地上，威胁着荒野和附近的定居点。",al={"为何清剿高塔","奥萨拉克斯 的威胁"}}},fp="22,203,20.285.0,17.341.1,25.186.0,37.115.0,21.115.0,38.114.0,40.138.1,53.150.0"}
P.entries["quest:1147"] = {n="疯狂的虫群",s="铁石营地的摩克塔·克林说，贝尔戈洛姆要把异种蝎赶回它们爬出来的地底深处。摩克塔自己的作战小队已是半死不活，无法完成任务，所以他请你去对付南边挖掘场的异种蝎。",h="铁石营地的摩克塔·克林说，贝尔戈洛姆要把异种蝎赶回它们爬出来的地底深处。摩克塔自己的作战小队已是半死不活，无法完成任务，所以他请你去对付南边挖掘场的异种蝎。",kw={"贝尔戈洛姆","探险者协会","铁石营地","摩克塔·克林","锈锤挖掘场","闪光平原","异种蝎","千针石林"},sec={{t="半死不活的作战小队",b="完成疯狂的虫群 (2)后，摩克塔·克林说，贝尔戈洛姆认为异种蝎是个威胁，要把它们赶回来的时候所在的地底深处。摩克塔的作战小队已经杀死了探险者协会派来的矮人，如今无力再战，没有援助就无法完成任务。挖掘场在南边，摩克塔认为那里应该没有矮人了。需要杀死的异种蝎包括搜寻者、工蝎和入侵者，任务完成前，摩克塔的小队不能离开。"},{t="摩克塔的谢意",b="摩克塔打趣说，虽然你浑身散发着恶臭，但覆在你身上的脓液倒让你更好看了。摩克塔警告你离科多兽远一点，还说光凭这股气味，就能证明你已经尽力对付过异种蝎了。"}},faq={{q="异种蝎虫害发生在哪里？",a="在铁石营地南边的锈锤挖掘场。",al={"异种蝎位置","虫子在哪里","挖掘场在哪里"}},{q="摩克塔·克林的小队为什么不能自己对付这些虫子？",a="摩克塔的作战小队杀死了探险者协会派来的矮人后，已经半死不活，以这样的状态无法再打一仗。",al={"为什么帮助摩克塔","作战小队为什么受伤","摩克塔小队状况"}},{q="谁想把异种蝎赶回去？",a="贝尔戈洛姆认为异种蝎是个威胁，要把它们赶回它们爬出来的地底深处。",al={"谁要杀死异种蝎","贝尔戈洛姆的异种蝎命令"}},{q="必须击败哪些种类的异种蝎？",a="异种搜寻者、异种筑巢蝎和异种侵略者，每种五只。",al={"要杀哪些异种蝎","异种蝎目标"}},{q="挖掘场还有矮人吗？",a="摩克塔说，那里应该已经没有需要对付的矮人了。",al={"锈锤有矮人吗","挖掘场的探险者协会"}}},fp="15,187,21.453.0,15.194.1,42.69.0,60.139.0,35.101.0,40.93.0,40.47.0"}
P.entries["quest:1148"] = {n="虫群的样本",s="你在千针石林翻看一块破裂的异种虫甲壳，发现甲片交织得极为紧密，异常坚固，而这种生物似乎力量强大，进化程度也很高。十字路口的科兰大概会想多研究一些。",h="你在千针石林翻看一块破裂的异种虫甲壳，发现甲片交织得极为紧密，异常坚固，而这种生物似乎力量强大，进化程度也很高。十字路口的科兰大概会想多研究一些。",kw={"甲壳","十字路口","巨人旷野","心脏","科兰","异种虫","爪子","千针石林"},ang={["faction:Horde"]="这是部落的事务：样本要交给十字路口的科兰。"},sec={{t="奇特的甲壳",b="仔细查看后，你发现几丁质交织得极为紧密，与以往见过的任何东西都不同。身体的其余部分也表明，这种生物力量强大，进化程度很高。你想到，十字路口的科兰一定很乐意多检查一些这种生物，了解它们的本性和起源。需要的样本是一颗异种虫的心脏、五只异种虫的爪子和三块完整的异种虫甲壳。"},{t="科兰需要的样本",b="科兰很高兴，说这些样本加上在巨人旷野发现的虫卵，是个良好的开端，有助于了解这些虫子究竟是什么生物，又在寻求什么。"}},faq={{q="谁需要这些异种虫的身体部位？",a="十字路口的科兰，他想多研究一些这种生物。",al={"科兰是谁","交付虫群的样本","谁研究异种虫"}},{q="这件事从哪里开始？",a="从你在千针石林检查一块破裂的异种虫甲壳开始。",al={"如何开始虫群的样本","破裂的异种虫甲壳起始","哪里能找到甲壳"}},{q="科兰需要哪些样本？",a="一颗异种虫的心脏、五只异种虫的爪子和三块完整的异种虫甲壳。",al={"需要哪些物品","异种虫身体部位清单","需要收集什么"}},{q="科兰为什么想研究异种虫？",a="多研究一些异种虫，或许能揭示它们的本性和起源。",al={"为什么研究异种虫","科兰能了解什么"}}},fp="18,164,18.308.0,20.179.1,31.90.0,22.75.0,32.90.0,40.70.0"}
P.entries["quest:1149"] = {n="信仰的试炼",s="信仰的试炼是一项精神仪式，由隐士多恩·平原行者在千针石林谷底上方的高处主持。它要求部落冒险者从摇摇欲坠的木板上迈步，跃入下方的深渊，以此证明自己的决心。",h="信仰的试炼是一项精神仪式，由隐士多恩·平原行者在千针石林谷底上方的高处主持。它要求部落冒险者从摇摇欲坠的木板上迈步，跃入下方的深渊，以此证明自己的决心。",kw={"多恩·平原行者","部落","信仰之跃","木板","耐力的试炼","信仰的试炼","千针石林"},ang={["class:Priest"]="终日培养对更高力量之信仰的牧师，在这里必须接受挑战，将观念中的信念化为切实的身体行动。",["faction:Horde"]="这些试炼体现了将卡利姆多初生的部落凝聚在一起的核心价值：绝对的信念、抵御恶劣环境的韧性，以及不屈的意志。",["race:Tauren"]="对Shu'halo而言，在卡利姆多各处圣地接受成人仪式是一项古老的传统，而多恩的试炼要求他们以切身行动，展现对无形之物的信任。"},sec={{t="心灵的衡量",b="多恩·平原行者隐居在一处僻静的高地，俯瞰千针石林那些被风侵蚀的石柱，思索着构成生命的各个方面：心智、肉体与精神。多恩并不单纯依循部族传统，而是通过自己设下的试炼，衡量冒险者真正的内在。他认为，信念虽然形式多样，但其根本在于拥有足够的勇气，坚定地相信某种事物，甚至愿意为之冒生命危险。"},{t="纵身跃入虚空",b="这场试炼看似简单直接。受试者被传送到一根高耸石柱的陡峭顶端，站在悬于半空、饱经风霜的木板上。要通过试炼，就必须克服求生的本能，在没有任何切实生还保证的情况下，迈步跃入深渊。跃下的人会被奥术或灵性力量止住坠势，迅速送回安全之处，证明自己的精神已经足够坚韧，能够面对前方未知的考验。"}},faq={{q="多恩·平原行者是谁？",a="多恩·平原行者是一位牛头人隐士，住在千针石林上方一处偏远的崖边营地。他担任精神试炼的考官，寻找部落冒险者，考验他们作为凡人的各项素质：信仰、耐力与力量。",al={"多恩·平原行者背景故事","信仰的试炼任务发布者","千针石林任务发布者"}},{q="从木板上跳下去会死吗？",a="不会。虽然从石柱顶端坠落看起来必死无疑，但这场试炼考验的是信任。你一迈出木板，魔法结界就会在坠落途中接住你，将你毫发无伤地直接传送回多恩·平原行者的洞穴。",al={"跳下去是否会死","信仰的试炼坠落伤害是否致命","信仰的试炼是否危险"}},{q="通过信仰的试炼之后会发生什么？",a="证明你的信仰，只是多恩这一系列试炼的开端。一旦认定你的精神能够接受考验，多恩就会立即以耐力的试炼挑战你身体的耐受力。",al={"信仰的试炼后续","信仰的试炼任务链","多恩·平原行者下一个任务"}},{q="为什么多恩说失败就意味着领悟虚空的浩瀚？",a="这是多恩以冷峻的哲思提醒人们，凡人终有一死。在他看来，那些内心缺乏热忱、无法全心投入挑战的人，可能会将生命与灵魂一同葬送在生者世界之外的无尽虚空中。",al={"虚空的浩瀚含义","多恩·平原行者虚空台词"}},{q="联盟冒险者能参加这场试炼吗？",a="不能。多恩·平原行者只向那些效忠部落、穿行于卡利姆多南部险恶峡谷的勇士传授智慧，给予精神指引。",al={"信仰的试炼是否仅限部落","联盟能否做信仰的试炼"}},{q="信仰的试炼在哪里进行？",a="试炼始于多恩位于千针石林峡谷崖壁上的营地，那里通过魔法与一根孤立石柱上令人目眩的悬崖相连，石柱高高耸立在峡谷底部之上。",al={"信仰的试炼位置","千针石林木板位置"}}},fx={f9bf32d9={q="多恩·平原行者为什么要考验你的信念？",a="多恩·平原行者认为，每个生命都由精神、身体和心智塑造。有些品质受文化传统影响，有些则只能从内心深处发掘。多恩设下这些试炼，旨在衡量你的内在力量，并让你的精神为艰难险阻做好准备。他要求你盲目跃入峡谷的狂风之中，以证明你拥有信念与信任，即使无法保证生还也敢于一跃，从而确保你的心智已准备好迎接更大的挑战。",al={"多恩为什么要你完成这件事","多恩·平原行者的动机","为什么要进行信念飞跃试炼"}}},fp="13,180,23.284.0,22.250.1,25.149.0,35.138.1,45.104.1,69.182.0,40.144.0,40.143.0"}
P.entries["quest:115"] = {n="暗影魔法",s="治安官马瑞斯呼吁采取行动，应对赤脊山的暗影魔法。黑石暗影施法者携带着被恶魔污染的午夜宝珠，将黑暗能量倾泻在湖畔镇的守军身上。必须夺走并摧毁这些宝珠，才能保护镇子的防线。",h="治安官马瑞斯呼吁采取行动，应对赤脊山的暗影魔法。黑石暗影施法者携带着被恶魔污染的午夜宝珠，将黑暗能量倾泻在湖畔镇的守军身上。必须夺走并摧毁这些宝珠，才能保护镇子的防线。",kw={"黑石兽人","被恶魔污染","湖畔镇","治安官马瑞斯","午夜宝珠","赤脊山","暗影魔法","暗影施法者"},ang={["class:Paladin"]="身为圣骑士，对抗暗影施法者并收缴被恶魔污染的圣物，正是在履行你净化凡人世界中恶魔腐化的神圣职责。",["class:Warlock"]="身为术士，你能从midnight orbs和兽人施法者对原始恶魔力量的引导中，看出黑石氏族根深蒂固的邪能渊源。",["faction:Alliance"]="湖畔镇已濒临沦陷，几乎得不到暴风城的任何增援。夺去黑石氏族的黑暗火力，对这片地区的存亡至关重要。"},sec={{t="邪恶的军械",b="黑石的力量一向依靠蛮力，但如今，这个氏族在赤脊山的劫掠带来了更黑暗的威胁。暗影施法者操纵黑暗力量，通过被恶魔污染的午夜宝珠引导邪能与暗影能量。这些神器已使当地民兵损失惨重，让本就对守军不利的战局雪上加霜。"},{t="遏制污染",b="治安官马瑞斯在镇中心指挥湖畔镇捉襟见肘的防御，他深知普通的刀剑难以对抗黑暗圣物。如果黑石兽人继续持有午夜宝珠，赤脊山的东部边境就可能失守。马瑞斯下令杀死暗影施法者，夺取宝珠，以便摧毁这些恶魔圣物，而非加以利用。"}},faq={{q="午夜宝珠是什么？",a="午夜宝珠是黑石暗影施法者携带的、被恶魔污染的能量媒介。它们汇聚黑暗魔法，向赤脊山的凡人守军发动毁灭性的打击。",al={"午夜宝珠","午夜宝珠是什么","午夜宝珠有什么作用"}},{q="治安官马瑞斯为什么要这些宝珠？",a="治安官马瑞斯希望将宝珠从战场上收缴，削弱黑石暗影施法者的进攻能力。他计划妥善处置并摧毁这些恶魔圣物。",al={"为什么收集午夜宝珠","马瑞斯的宝珠","马瑞斯如何处置宝珠"}},{q="黑石暗影施法者是谁？",a="黑石暗影施法者是操纵暗影魔法和受邪能污染的魔法的兽人施法者。他们以魔法轰击和诅咒支援氏族中依靠蛮力作战的战士。",al={"黑石暗影施法者","谁使用暗影魔法","黑石施法者"}},{q="在哪里能找到暗影施法者？",a="黑石暗影施法者盘踞在赤脊山东北部各处的营地和防御据点中。",al={"暗影施法者在哪里","暗影施法者位置","黑石暗影施法者营地"}},{q="湖畔镇会研究或使用这些宝珠吗？",a="不会。治安官马瑞斯认为这些宝珠危险且受到了恶魔污染，并表示没有它们，世界会更好。他希望立即将它们摧毁。",al={"湖畔镇会使用宝珠吗","联盟能使用宝珠吗","宝珠有用吗"}},{q="为什么赤脊山会出现恶魔魔法？",a="早在旧部落时期，黑石氏族就与黑暗生物和邪能生物勾结。氏族的施法者至今仍在使用恶魔圣物和暗影魔法，助长氏族的征伐。",al={"赤脊山为什么有恶魔","黑石的恶魔污染","赤脊山的邪能"}}},fp="12,156,18.326.0,20.339.0,23.158.0,40.183.0,36.161.0,34.106.0,37.152.0,43.184.0"}
P.entries["quest:1150"] = {n="耐力的试炼",s="耐力的试炼是多恩·平原行者在千针石林主持的一系列精神试炼中的第二项仪式。部落冒险者已经证明了自己精神上的勇气，如今需要潜入飞羽洞穴，引出凶悍的鹰身人首领格林卡·血啸，将身体的耐力推向极限。",h="耐力的试炼是多恩·平原行者在千针石林主持的一系列精神试炼中的第二项仪式。部落冒险者已经证明了自己精神上的勇气，如今需要潜入飞羽洞穴，引出凶悍的鹰身人首领格林卡·血啸，将身体的耐力推向极限。",kw={"多恩·平原行者","乱风岗","格林卡·血啸","飞羽洞穴","尖啸峡谷","耐力的试炼","千针石林","老屋"},ang={["faction:Horde"]="多恩向部落的所有种族提供这些挑战，因为他相信，各个部族的年轻战士都必须先经受苦难的磨炼，才能面对卡利姆多的重重险境。",["race:Tauren"]="对牛头人旅者而言，多恩·平原行者的试炼体现了传统的成年仪式，考验受试者的身体耐力能否与 Earth Mother 的精神指引相契合。"},sec={{t="肉体的考验",b="居住在老屋的多恩·平原行者自愿承担起磨炼年轻战士的职责，让他们为踏入更广阔、更严酷的世界做好准备。最初的仪式证明了旅者拥有坚定的信仰和沉着的胆识，而这场试炼考验的是肉体的坚韧。在多恩看来，唯有让虔诚的信仰、严明的心志，以及承受持续摧残所需的充沛耐力达到协调，才算真正做好了准备。"},{t="深入飞羽洞穴",b="这场试炼选在飞羽洞穴进行，那是一处藏在乱风岗以西 尖啸峡谷 中的险恶洞窟。洞内到处都是充满敌意的鹰身人，对独行的旅者构成了极大的威胁。要完成试炼，挑战者必须一路杀入地下巢穴深处，破坏鹰身人囤积的补给，并抵挡她们凶猛的反扑，直到族群的女首领格林卡·血啸亲自出战。"}},faq={{q="谁提供耐力的试炼？",a="这项任务由牛头人长者多恩·平原行者提供，他驻留在千针石林峡谷峭壁间的老屋。",al={"耐力的试炼 任务给予者","谁开启 耐力的试炼","多恩·平原行者任务"}},{q="飞羽洞穴在哪里？",a="飞羽洞穴位于千针石林南侧峡谷壁的高处，在乱风岗以西。旅者必须沿着蜿蜒的小径穿过 尖啸峡谷，才能抵达通往洞口的坡道。",al={"飞羽洞穴位置","鹰身人洞穴在哪","尖啸峡谷 坡道"}},{q="如何召出格林卡·血啸？",a="你需要一路杀入飞羽洞穴最深处的洞室，破坏鹰身人在那里储藏的食物和补给，激怒格林卡·血啸，让她现身保卫巢穴。",al={"召唤 格林卡","如何让 格林卡·血啸 出现","寻找 格林卡"}},{q="耐力的试炼之后是什么？",a="将格林卡被斩下的爪子带回给多恩·平原行者，就能证明你的身体耐力，他便会派你迎接这一系列试炼中的下一项挑战：力量试炼。",al={"耐力之后的任务","耐力的试炼 后续","多恩·平原行者下一项试炼"}},{q="多恩为什么要考验并非牛头人的冒险者？",a="多恩相信，指引部落所有的年轻人是自己的使命，无论他们属于哪个种族或部族。在他看来，未经考验的傲气在更广阔的世界中无异于死刑，因此他坚持要求每一位战士都证明自己在身体、心智和精神上做好了准备。",al={"多恩 为何帮助部落","多恩·平原行者的理念","其他种族的牛头人试炼"}},{q="在此之前的试炼是什么？",a="在考验身体的耐力之前，多恩要求挑战者先完成信仰的试炼，以纵身跃入险境来表明虔诚，考验冒险者的精神是否会在恐惧面前动摇。",al={"前置任务","耐力之前的试炼","第一项试炼"}}},fx={["8999be4f"]={q="多恩·平原行者为什么想要你完成这件事？",a="多恩·平原行者认为，让年轻的冒险者为广阔世界中的致命危险做好准备，是他的神圣职责。在确认你的精神与信念无虞后，他坚持要考验你的肉体。让你深入鹰身人的领地，顶住一波又一波狂暴的鹰身人，是为了确认你拥有离开家园庇护后生存所需的耐力和毅力。",al={"多恩为什么要考验耐力","多恩·平原行者的动机","耐力试炼的目的"}},b2efd71b={q="格林卡的爪子有什么用？",a="这只爪子是确凿的证据，证明你曾在飞羽洞穴的中心坚守阵地，挺过鹰身人持续不断的猛攻，并击倒了它们凶悍的族母格林卡·血啸。多恩需要它来确认你在无情的攻击下仍坚持了下来，然后才会交给你下一项试炼。",al={"格林卡的爪子有什么用","为什么我需要格林卡的爪子","格林卡的爪子有什么用处"}},["28ecd26a"]={q="格林卡·血啸是谁？",a="格林卡·血啸是盘踞在乱风岗以西峡谷洞窟中的飞羽鹰身人首领之一。她凶残且极具领地意识，统治着鹰身人巢群的内层圣所。当你闯入飞羽洞穴深处，砸毁它们囤积的补给时，她会怒不可遏地从栖身处飞下，亲自将你杀死。",al={"格林卡是谁","格林卡·血啸的背景","飞羽鹰身人首领"}}},fp="17,247,16.250.0,31.336.0,32.123.0,34.186.0,38.171.0,39.146.0,49.216.0,35.162.0"}
P.entries["quest:1151"] = {n="力量试炼",s="力量试炼是牛头人秘术师多恩·平原行者在千针石林主持的第三项试炼。为了证明自身的力量，部落勇士必须猎杀罗卡里姆，这个古老的岩石元素四处游荡，不受束缚，而勇士们需要带回它破碎躯体的残骸。",h="力量试炼是牛头人秘术师多恩·平原行者在千针石林主持的第三项试炼。为了证明自身的力量，部落勇士必须猎杀罗卡里姆，这个古老的岩石元素四处游荡，不受束缚，而勇士们需要带回它破碎躯体的残骸。",kw={"多恩·平原行者","上古之神","岩石元素","罗卡里姆","力量试炼","重锤","千针石林","老屋"},ang={["class:Shaman"]="在萨满祭司眼中，罗卡里姆不仅是一个障碍，更是危险而不受束缚的大地化身，它拒绝屈服，扰乱了当地的灵魂平衡。",["faction:Horde"]="完成老屋的仪式，便能赢得雷霆崖长者的尊重，并巩固冒险者在卡利姆多各地的声望。",["race:Tauren"]="对牛头人朝圣者而言，直面未经驯服的岩石之灵，是考验和谐之道与身体意志的传统方式，展现猎人承受并战胜 Earth Mother 最严酷力量的能力。"},sec={{t="上古之神时代的遗存",b="很久以前，在上古之神统治的时代，原始元素遍布世界表面，侍奉着它们的黑暗主人。当那些古老的存在被推翻并封印在地下后，元素之灵失去了与这个世界的联系，大多不再拥有实体，除非被后世的法术束缚并召唤。然而，少数存在足够顽强而强大，无需魔法维系，也能长久留在艾泽拉斯。罗卡里姆就是这样的遗存，它游荡在千针石林干旱的峡谷中，宛如那个原始时代留存至今的回响。"},{t="千针石林的重锤",b="罗卡里姆的石拳砸向峡谷地面时，会发出如同地震般震耳欲聋的轰鸣，当地半人马氏族因此给它起了这个称号。任何愚蠢或大胆到闯入它游荡路线的人，都会被捶成尘土。罗卡里姆代表着纯粹而不受束缚的躯体力量，因此多恩·平原行者命令接受试炼者击碎这头巨物，以此直接衡量他们的战士精神，并要求他们带回元素石心的碎片，作为获胜的证明。"}},faq={{q="这个任务在哪里接取和交还？",a="这个任务由牛头人长者多恩·平原行者给予，也由他验收。他驻守在老屋，那是一处隐蔽的峡谷营地，坐落在千针石林高耸的石柱之间。",al={"任务给予者","在哪里交任务","多恩 的位置"}},{q="罗卡里姆是什么？",a="罗卡里姆是一个古老的岩石元素，自上古之神的时代起便一直留存在卡利姆多。与如今通过召唤而来的元素不同，它拥有足够强大的先天力量，完全凭借自身就能在艾泽拉斯维持实体。",al={"罗卡里姆 是谁","罗卡里姆 是什么类型的怪物","元素背景故事"}},{q="半人马为什么称它为“重锤”？",a="峡谷中的半人马部族称它为重锤，因为它用石拳砸碎沿途的一切时，会释放出雷鸣般滚滚扩散的冲击波。",al={"重锤 的绰号","半人马对 罗卡里姆 的称呼"}},{q="在峡谷的什么地方能找到罗卡里姆？",a="罗卡里姆游荡在千针石林的西北部，通常在贯穿谷底的主路以南的开阔地带巡逻。",al={"罗卡里姆 刷新","罗卡里姆 在哪里"}},{q="这个任务在整个试炼任务链中处于什么位置？",a="力量试炼是任务链中的第三项试炼。它接在信仰的试炼和耐力的试炼之后，完成后便是最后一项试炼知识试炼。",al={"任务链顺序","后续任务","前置任务是什么"}},{q="多恩为什么要求杀死一个元素，而不是野兽或敌人？",a="多恩选择罗卡里姆，是因为这个元素是活体岩石与不屈原始力量的纯粹化身。征服这样的对手，便证明了自身的力量足以战胜原始而坚不可摧的大地本身。",al={"为什么要杀元素","力量试炼 的目的"}}},fx={d3b1c16f={q="多恩·平原行者为什么想要你完成这件事？",a="多恩·平原行者要让你接受古老的牛头人仪式，以证明你的实力，然后才能进入最后的试炼。对付普通野兽或士兵无法真正衡量你的力量，因此他要求你挑战古老原始石灵的残存力量。击败罗卡里姆，才能证明你的内在与肉体力量足以战胜古老的元素之力。",al={"多恩·平原行者的动机","多恩为什么要杀死罗卡里姆","为什么要进行力量试炼"}},["67dd1d0a"]={q="罗卡里姆的碎片有什么用？",a="这些碎片是无可辩驳的证据，证明你曾直面重锤者罗卡里姆，并将这位古老元素生物打成碎石。多恩·平原行者需要你胜利的实物证据，才能认可你完成了力量试炼，并获准进入下一项试炼。",al={"罗卡里姆的碎片有什么用","这些碎片有什么用","为什么收集罗卡里姆的碎片"}}},fp="16,194,29.440.0,31.340.0,36.133.0,29.183.0,42.136.0,42.143.0,59.139.0,75.182.0"}
P.entries["quest:1152"] = {n="知识试炼",s="在千针石林完成信仰、耐力和力量的试炼后，多恩·平原行者指引部落勇士北上，前往石爪山脉。在那里，一位名叫布劳格·幽魂的睿智萨满祭司正等候着他们，主持知识试炼。这场试炼将重点从肉体的坚韧转向对世界悠久历史与各地苦难的理解。",h="在千针石林完成信仰、耐力和力量的试炼后，多恩·平原行者指引部落勇士北上，前往石爪山脉。在那里，一位名叫布劳格·幽魂的睿智萨满祭司正等候着他们，主持知识试炼。这场试炼将重点从肉体的坚韧转向对世界悠久历史与各地苦难的理解。",kw={"布劳格·幽魂","多恩·平原行者","石爪山脉","石爪小径","知识试炼","千针石林","老屋","狂风峭壁"},ang={["class:Shaman"]="布劳格·幽魂体现了萨满祭司的世界观：从地精的掠夺到古老精灵的自我封闭，凡人的鲁莽行径揭示了大地苦难的根源。",["faction:Horde"]="布劳格的试炼迫使部落勇士坦诚审视自身盟友的名声，提醒他们，这片土地的困境并非全由兽人或被遗忘者造成。",["race:Tauren"]="这些试炼体现了牛头人的传统思想，将精神和谐与对历史的理解置于纯粹的嗜血欲望之上。"},sec={{t="从信仰到学识",b="在老屋这处隐蔽的庇护所中，多恩·平原行者让初学者接受严苛的试炼，考验他们的精神信念、身体耐力和战斗技艺。然而，仅凭蛮力和盲目的信仰，还不足以成为真正的部落勇士。多恩深知自己作为导师的局限，因此将那些证明了自身能力的人送往石爪山脉，让一位年长的萨满祭司考验他们的才智与见识。"},{t="通往石爪山脉之路",b="旅人一路向北，穿过贫瘠之地干燥的灌木荒原，进入石爪山脉的峭壁之间。在高山之上，靠近石爪小径入口的地方，坐落着布劳格·幽魂的隐居之所，那条洞穴通道穿过山岩，通向灰谷。他守望着一片饱受战火侵扰的边境，地精的伐木生意在这里摧残森林，而怀有敌意的暗夜精灵则奋力捍卫祖辈的疆界。"},{t="更广阔的视野",b="见到布劳格后，这场试炼的真正目的便显现出来。布劳格并不要求盲目的阵营自豪感，而是反思艾泽拉斯的悲惨处境。他指出，尽管兽人和被遗忘者不断因战争与腐化受到指责，几乎每个文明都对这片土地的困境负有责任。地精砍伐古老的树木，而暗夜精灵对年轻种族怀有深深的不信任。知识试炼要求勇士超越眼前的仇怨，理解这个伤痕累累的世界更广阔的历史。"}},faq={{q="知识试炼是什么？",a="这是一场旨在传授知识的试炼，属于牛头人长者设计的一整套成人仪式。初学者必须证明自己不仅拥有力量与信仰，还了解历史，理解艾泽拉斯共同的过去。",al={"知识试炼含义","这是什么任务"}},{q="在哪里可以找到布劳格·幽魂？",a="布劳格·幽魂住在石爪山脉，位于狂风峭壁附近，就在连接石爪山脉与灰谷的石爪小径洞穴入口旁。",al={"布劳格·幽魂位置","布劳格在哪里"}},{q="多恩·平原行者为什么让你离开？",a="多恩在千针石林主持信仰、耐力和力量的试炼，但他承认，传授世界的历史知识并非自己的专长。他指引合格的初学者前去寻找布劳格，这位萨满祭司拥有考验心智所需的智慧。",al={"为什么去石爪山脉","多恩为什么派人前往"}},{q="旅途中需要提防哪些威胁？",a="多恩特别警告说，暗夜精灵在灰谷与石爪山脉附近的边境地区巡游，将部落的出现视为入侵。狂风峭壁周边也遍布地精的伐木作业，局势动荡不安。",al={"前往布劳格处的危险","石爪小径危险"}},{q="布劳格·幽魂如何看待世界上的冲突？",a="布劳格认为，所有凡人种族都对世界的苦难负有责任。尽管兽人和被遗忘者经常被对手妖魔化，他指出，地精的贪婪和暗夜精灵的傲慢也在卡利姆多与洛丹伦各地造成了同样的伤害。",al={"布劳格·幽魂的理念","布劳格相信什么"}},{q="石爪小径是什么？",a="石爪小径是一条重要的山间隧道，连接着石爪山脉的狂风峭壁与灰谷南部古老林地的边缘。",al={"石爪小径是什么","石爪小径洞穴"}}},fp="12,212,18.340.0,22.389.0,21.423.1,25.175.0,33.151.0,41.221.0,54.198.0,56.220.0,27.143.0"}
P.entries["quest:1153"] = {n="新的矿石样本",s="塔特纳克·钢炉正在千针石林寻找新矿石，以增强部落的武备。这位陶拉祖营地的铁匠派你南下，带回样本供他测试。",h="塔特纳克·钢炉正在千针石林寻找新矿石，以增强部落的武备。这位陶拉祖营地的铁匠派你南下，带回样本供他测试。",kw={"陶拉祖营地","狗头人","塔特纳克·钢炉","千针石林","萨尔","未精炼的矿石样本","野猪人的武器"},ang={["faction:Horde"]="在陶拉祖营地这座部落南方堡垒，你可以贡献物资，支持大酋长的备战工作。",["profession:Blacksmithing"]="身为部落铁匠，你协助获取新的金属矿藏，让边疆守军拥有足够的武器，应对周围的威胁。",["profession:Mining"]="身为勘探者，你深知那些穴居生物在未经探索的南方峡谷中挖出的原始矿脉有何价值。"},sec={{t="铁匠的雄心",b="塔特纳克·钢炉是陶拉祖营地的铁匠，直接受到奥格瑞玛的监督。他已经利用当地半人马的兵器打造并供应了一批武器，但仍想向大酋长萨尔证明自己的手艺。路过的旅人给他看了一块奇怪的矿石，是从南方的一个狗头人身上取得的。他们拒绝出售矿石，塔特纳克认为这是对他的手艺和部落的侮辱。"},{t="深入千针石林",b="你离开贫瘠之地南部平坦的原野，进入千针石林高耸如迷宫的峡谷。狗头人矿工在那里的峭壁与悬崖间挖掘坑道。直接从它们身上取得未经提炼的矿石块并带回来，塔特纳克就能判断，这种原矿能否锻造成足以为萨尔的战事效力的武器。"}},faq={{q="塔特纳克·钢炉是谁？",a="塔特纳克·钢炉是一名兽人武器匠，驻扎在贫瘠之地南部的陶拉祖营地。他为部落的边疆防御打造武器，并寻找新材料，希望得到大酋长萨尔的赏识。",al={"塔特纳克","陶拉祖营地铁匠","塔特纳克是谁"}},{q="这份矿石样本来自哪里？",a="在贫瘠之地边界的升降梯以南，狗头人携带着未经提炼的矿石，穿行于千针石林蜿蜒的峡谷。",al={"矿石在哪里","矿石位置","千针石林矿石"}},{q="塔特纳克为什么对路过的旅人发怒？",a="来自南方的旅人给塔特纳克看了一块奇怪的矿石，那是从一个被杀死的狗头人身上取得的，随后却拒绝出售。他认为，他们囤积重要物资的行为毫无忠诚可言，是对大酋长的侮辱，还咒骂他们是懦夫。",al={"塔特纳克为何发怒","旅人的矿石","塔特纳克与旅人"}},{q="塔特纳克会如何处理矿石？",a="塔特纳克打算分析矿石的冶金特性，并测试它的强度。如果它足够坚固，他就打算锻造一件武器原型，亲自前往奥格瑞玛，将其献给大酋长萨尔。",al={"矿石有何用途","他为何需要矿石"}},{q="开始这项任务前必须完成什么前置任务？",a="你要先完成野猪人的武器，从威胁陶拉祖营地的各个半人马部族那里收集指定的武器，证明当地的兵器可以改作他用。",al={"前置任务","前一个任务","野猪人的武器"}},{q="千针石林的狗头人为什么带着这种矿石？",a="狗头人热衷于掘洞采矿，在峭壁与地下矿脉间挖掘坑道。在千针石林，它们挖出了地表居民鲜少触及的奇特矿藏。",al={"狗头人采矿","千针石林狗头人"}}},fp="16,143,18.374.0,29.312.0,29.189.0,37.126.0,49.233.0,37.182.0,53.169.0,54.184.0"}
P.entries["quest:1154"] = {n="知识试炼",s="知识试炼是布劳格·幽魂在石爪小径入口设下的试炼，考验部落冒险者的头脑，而非体力。要通过试炼，求知者必须深入灰谷阴魂不散的兽穴，取回一本记载巨龙历史的古书，并在接受问答考验前研读其中的内容。",h="知识试炼是布劳格·幽魂在石爪小径入口设下的试炼，考验部落冒险者的头脑，而非体力。要通过试炼，求知者必须深入灰谷阴魂不散的兽穴，取回一本记载巨龙历史的古书，并在接受问答考验前研读其中的内容。",kw={"灰谷","布劳格·幽魂","陶拉祖营地","死亡之翼","朵丹尼尔兽穴","多恩·平原行者","巨龙的遗产","石爪小径","知识试炼"},ang={["class:Druid"]="踏入朵丹尼尔兽穴，德鲁伊旅者便会直面暗夜精灵同胞遭到腐化与杀戮的悲剧；这些同胞曾在沉睡中与翡翠梦境相通。",["faction:Horde"]="这场试炼体现了部落对战士的要求：他们必须理解卡利姆多悠久的历史，并能穿行于灰谷危机四伏的精灵废墟，不因无知而丧命。"},sec={{t="试炼的转变",b="在千针石林的盐滩与高地证明了自己的耐力和坚定信念后，参加多恩·平原行者系列试炼的人会被派往北方，前去拜访石爪山脉的布劳格·幽魂。布劳格·幽魂驻守在石爪小径入口附近，对先前的挑战不以为然，认为那不过是简单的体能锻炼。要为部落立下卓越功勋，冒险者就必须拥有敏锐而严谨的头脑，随时准备理解古老的历史，而非仅仅击倒野兽。"},{t="朵丹尼尔的阴影",b="布劳格·幽魂指引求知者穿过石爪小径，进入灰谷南部的林地。朵丹尼尔兽穴就藏在碎木岗哨以南的树冠之下。这座地下庇护所如今已是危机四伏的废墟，死去的暗夜精灵德鲁伊和屠杀他们的凶恶生物盘踞其中。在下层洞室深处的一座石台上，放着此行的目标：《巨龙的遗产》，这份珍稀手稿详述了强大的守护巨龙在远古时期的诞生与堕落。"},{t="研读或受罚",b="取得古书只完成了布劳格·幽魂试炼的一半。交出书之前，求知者必须牢记其中的教诲。布劳格·幽魂会在交付时立刻收走书，考查求知者是否记得那些获泰坦赐予力量的守护者，以及催生死亡之翼的那场灾难性背叛。没有认真研读或猜错答案的人，会被骤然放逐到卡利姆多另一头、贫瘠之地南部的陶拉祖营地，不得不蒙羞跋涉，返回石爪山。"}},faq={{q="布劳格·幽魂是谁？",a="布劳格·幽魂是一位年迈的牛头人萨满祭司，驻守在石爪山脉的石爪小径入口附近。在多恩·平原行者的前几项试炼之后，他担任考官，检验部落勇士是否拥有足以与自身武力相称的才智与学识。",al={"布劳格·幽魂","谁提供知识试炼","石爪山脉任务给予者"}},{q="《巨龙的遗产》在哪里？",a="这本书位于灰谷南部的朵丹尼尔兽穴内，那里几乎就在碎木岗哨的正南方。它放在兽穴地下深处中央平台的一座石台上。",al={"巨龙的遗产位置","书在哪里","朵丹尼尔兽穴书的位置"}},{q="朵丹尼尔兽穴里潜伏着什么？",a="这座兽穴曾是暗夜精灵德鲁伊的庇护所，但悲剧降临了这些洞窟。如今，死去德鲁伊不得安息的灵魂，以及屠杀他们的致命入侵者占据了这里，让这片洞穴成为任何闯入者的死亡迷宫。",al={"朵丹尼尔兽穴敌人","谁守着书","灰谷兽穴"}},{q="为什么布劳格·幽魂要我先读完书再交还？",a="你交还书时，布劳格·幽魂会将其收走，并考查你记住了多少内容。他希望你事先认真研读，因为这场试炼衡量的是学识，而不仅仅是取回一件物品。",al={"为什么读巨龙的遗产","知识试炼问答","答错问题会怎样"}},{q="这场试炼在整个系列试炼中处于什么位置？",a="这场试炼承接多恩·平原行者在千针石林老屋发起的信仰的试炼。多恩·平原行者考验的是你面对致命险境时的胆识与生存能力，而布劳格·幽魂考查的是你对传说的掌握和对历史的了解。",al={"信仰的试炼任务链","知识试炼的前置任务","多恩·平原行者的试炼"}},{q="《巨龙的遗产》讲述什么？",a="这份手稿记载了一段神话般的历史：泰坦赋予五大守护巨龙力量，让它们守护艾泽拉斯。其中至关重要的内容，是大地守护者奈萨里安的堕落，以及他如何化为名叫死亡之翼的可怕毁灭者。",al={"巨龙的遗产故事","书中传说","书讲什么"}}},fx={["0efda427"]={q="布劳格·幽魂为什么要我寻找巨龙的遗产？",a="布劳格·幽魂考验的是你的头脑，而不是力量。你已经经受了多恩·平原行者的体能试炼，现在要接受对智力、应变能力和求知意愿的考验。布劳格派你独自前往危险之地，取回并领悟古老知识，以此判断你是否具备完成这一系列试炼所需的智慧。",al={"布劳格为什么考验我","为什么要找巨龙的遗产","布劳格·幽魂为什么要考验我"}}},fp="12,160,21.367.0,24.400.0,15.353.1,23.232.0,48.201.0,39.199.0,58.171.1,54.213.0,56.212.0"}
P.entries["quest:1159"] = {n="知识试炼",s="知识试炼的这一环将部落冒险者派往大洋彼岸，穿过无尽之海，前往洛丹伦废墟。在石爪山脉解答了布劳格·幽魂的第一道谜题后，你被指引前往幽暗城，在被遗忘者之中寻找一位生前是人类的学者。",h="知识试炼的这一环将部落冒险者派往大洋彼岸，穿过无尽之海，前往洛丹伦废墟。在石爪山脉解答了布劳格·幽魂的第一道谜题后，你被指引前往幽暗城，在被遗忘者之中寻找一位生前是人类的学者。",kw={"炼金房","布劳格·幽魂","多恩·平原行者","洛丹伦","帕科瓦·芬塔拉斯","知识试炼","千针石林","幽暗城","老屋"},ang={["faction:Horde"]="这个任务展现了维系新近组建的部落的跨大陆协作，让追寻智慧的牛头人与洛丹伦阴郁的档案学者携手合作。",["race:Tauren"]="对一名牛头人受试者而言，离开卡利姆多开阔的平原和高耸的台地，转而穿行于幽暗城充满毒气、狭窄压抑的下水道，让这段旅途既是历史的考验，也是文化的考验。",["race:Undead"]="与帕科瓦的会面表明，尽管身躯腐朽、化为亡灵，像他这样的被遗忘者学者仍保留着洛丹伦这个覆灭王国深厚的学术传统与浩繁的文献记录。"},sec={{t="学者的联盟",b="在你证明了自己的实力，并解开《巨龙的遗产》中记载的守护巨龙历史之谜后，布劳格·幽魂承认，自己的知识也有局限。布劳格没有将试炼局限于卡利姆多，而是指引你前往洛丹伦废墟之下的亡灵都城，展现出部落各方之间广泛而出人意料的联系。"},{t="多疑的历史学家",b="帕科瓦·芬塔拉斯居住在炼金房潮湿的走廊中。帕科瓦曾是北方诸王国备受尊敬的人类史官，历经天灾军团之灾并变成被遗忘者之后，他依然追求着知识。面对一个声称完成了千针石林精神与肉体试炼的外来者，帕科瓦认定你不过是个投机取巧的雇佣兵，除非你亲自在他面前证明自己的价值。"}},faq={{q="为什么牛头人的试炼要让我远赴幽暗城？",a="布劳格·幽魂承认，真正精通学识，不能只了解卡利姆多的历史。他指引你去找帕科瓦·芬塔拉斯，一位在洛丹伦沦为亡灵之地后仍保有学识的著名人类学者，考验你对更广泛的世界历史的了解。",al={"为何前往幽暗城","为何前往洛丹伦","布劳格派人寻找亡灵"}},{q="帕科瓦·芬塔拉斯的确切位置在哪里？",a="帕科瓦·芬塔拉斯住在幽暗城，具体位置在炼金房区南侧的桥上。",al={"帕科瓦在哪里","帕科瓦位置","寻找芬塔拉斯"}},{q="帕科瓦·芬塔拉斯生前是什么人？",a="帕科瓦·芬塔拉斯生前是洛丹伦王国一位成就斐然的人类历史学家。在死于亡灵瘟疫并加入希尔瓦娜斯麾下的被遗忘者之后，他仍继续钻研学问，将才智投入到其他更为黑暗的研究之中。",al={"帕科瓦·芬塔拉斯背景故事","帕科瓦是谁","芬塔拉斯身世"}},{q="为什么帕科瓦不相信我是布劳格派来的？",a="帕科瓦对外来者深怀疑虑。他难以相信，一个普通冒险者竟能从千针石林的峰顶跃下，击败原始元素生物，还能取回古代遗物，反倒认定你只是在酒馆里听到了些传闻。",al={"帕科瓦为何无礼","帕科瓦的反应","帕科瓦不相信我"}},{q="这个任务属于哪一系列试炼？",a="这个任务位于知识试炼任务链的中段，而这条任务链又源自多恩·平原行者在老屋发起的试炼。它考验的是受试者是否不仅拥有战斗本领和勇气，还具备足以成为部落勇士的才智与历史见识。",al={"属于哪条任务链","信仰的试炼任务链","什么是知识试炼"}},{q="找到帕科瓦之后，接下来要做什么？",a="在帕科瓦肯向你提出自己的历史谜题之前，他要求你先替他在东部王国办一件差事，以确认你确实是布劳格口中那位能干的英雄。",al={"找到帕科瓦之后做什么","幽暗城之后的任务","与芬塔拉斯交谈之后"}}},fx={["670eb265"]={q="布劳格·幽魂为什么派你去幽暗城？",a="布劳格·幽魂已经考验了你的初步知识，但他的职责只是引导你通过知识试炼的第一阶段。为了真正考验你对世界的理解，他明白下一个问题需要更广阔的视角。于是他派你去找帕科瓦·芬塔拉斯——这位洛丹伦的著名历史学家如今已加入被遗忘者——让一位追求不同形式启迪的学者来评判你对历史与真相的求索。",al={"布劳格为什么派我去","布劳格·幽魂的动机","布劳格为什么让我去幽暗城"}}},fp="12,243,20.300.0,23.435.0,57.275.0,43.89.0,34.222.0,42.214.0,40.207.0,39.179.0"}
P.entries["quest:116"] = {n="旱季",s="黑石兽人持续围困湖畔镇，酒吧老板丹尼尔需要为镇上的旅店补充酒水。道路危机四伏，平日的补给已经中断。",h="黑石兽人持续围困湖畔镇，酒吧老板丹尼尔需要为镇上的旅店补充酒水。道路危机四伏，平日的补给已经中断。",kw={"酒吧老板丹尼尔","旱季","葛瑞姆·雷酒","湖畔镇","葡萄酒","月光酒","赤脊山","蜂蜜酒","雷霆啤酒"},ang={["faction:Alliance"]="作为联盟信使，你见到了赤脊山道路上的危险如何扰乱日常生活。你帮助恢复暴风城、艾尔文、西部荒野、暮色森林和赤脊山之间的贸易往来。",["race:Dwarf"]="身为矮人，你知道即便兽人入侵，人类酒馆仍然离不开矮人酿造的酒。信使们前往西部荒野，只为取得葛瑞姆·雷酒闻名遐迩的麦芽酒。"},sec={{t="围困中的小镇",b="黑石兽人从石堡要塞出击，步步紧逼湖畔镇。补给线被切断，道路危机四伏，旅店的酒水也所剩无几。酒吧老板丹尼尔向能穿过封锁道路的旅行者求助，请他们为惊恐的村民和镇上的守卫带回补给。"},{t="王国巡游",b="丹尼尔需要来自暴风城各地的酒水。你可以在首都找到葡萄酒，在闪金镇的狮王之傲旅店找到蜂蜜酒，在暮色森林的夜色镇找到月光酒，还能从西部荒野丘陵中的葛瑞姆·雷酒那里弄到雷霆啤酒。"}},faq={{q="湖畔镇为什么快没酒了？",a="黑石兽人扰乱了赤脊山的贸易，阻断了补给商队。丹尼尔平日订购的货物迟迟未到，湖畔镇承受着战事的压力，他的旅店也快没酒了。",al={"旱季缘由","湖畔镇为何没酒","酒吧老板丹尼尔的难题"}},{q="在哪里能找到酒吧老板丹尼尔需要的所有酒水？",a="你可以在暴风城找到葡萄酒，在艾尔文森林的闪金镇找到蜂蜜酒，在暮色森林的夜色镇找到月光酒，还能从西部荒野丘陵中的葛瑞姆·雷酒那里弄到雷霆啤酒。",al={"旱季酒水位置","哪里买葡萄酒、月光酒和朗姆酒","哪里找丹尼尔需要的酒水"}},{q="葛瑞姆·雷酒是谁？",a="葛瑞姆·雷酒是西部荒野丘陵中的一位矮人酿酒师。丹尼尔想要他的麦芽酒，而你得先为葛瑞姆弄到一桶新酒。",al={"葛瑞姆位置","葛瑞姆·雷酒在哪里","西部荒野雷酒"}},{q="酒吧老板丹尼尔是谁？",a="酒吧老板丹尼尔经营着湖畔镇的旅店。黑石兽人威胁着小镇，他便雇用旅行者沿着危险的道路运来补给。",al={"酒吧老板丹尼尔","湖畔镇旅店老板","谁发布旱季"}},{q="丹尼尔为什么需要这么多不同地区的酒水？",a="丹尼尔为难民、当地民兵和过往的冒险者供应酒水。他需要矮人麦芽酒、首都的佳酿，以及来自暮色森林和艾尔文的烈酒。",al={"为何需要这么多酒","为何前往暮色森林和西部荒野"}},{q="跑完这一趟，酒吧老板丹尼尔会给什么奖励？",a="丹尼尔会用钱币报销你的旅费，还会送你一件他妻子亲手缝制的披风，酬谢你冒险穿越战火纷飞的道路。",al={"旱季奖励","丹尼尔给什么"}}},fp="9,152,18.279.0,27.257.0,40.183.0,53.202.0,29.148.0,23.148.0,60.157.0,57.135.0"}
P.entries["quest:1164"] = {n="科娜塔一家",s="幽暗城的吉纳维·卡隆请你前往阿拉希的农庄，找达比雷一家算账。她心中的怨恨，让一场关于失窃财物的纠纷变成了复仇的要求。",h="幽暗城的吉纳维·卡隆请你前往阿拉希的农庄，找达比雷一家算账。她心中的怨恨，让一场关于失窃财物的纠纷变成了复仇的要求。",kw={"阿拉希","达比雷农场","法迪尔","吉纳维·卡隆","科娜塔","马塞尔·达比雷","避难谷地","偷取盗贼的东西"},sec={{t="深重的怨恨",b="吉纳维·卡隆说，瘟疫夺走了她的家人，战乱让她的庄园遭到洗劫，付之一炬。她指控科娜塔和她的孩子偷走了她仍然珍视的寥寥几件财物。如今，她请你前往阿拉希的达比雷农场，带回科娜塔、法迪尔和马塞尔·达比雷的首级。"}},faq={{q="是谁在寻求帮助？",a="幽暗城的吉纳维·卡隆请你带回科娜塔、法迪尔和马塞尔·达比雷的首级。",al={"谁给的任务","谁提出的要求","吉纳维"}},{q="吉纳维为何怨恨达比雷一家？",a="吉纳维说，瘟疫夺走了她的家人，战乱让她失去了庄园，而达比雷一家偷走了她剩下的财物。",al={"为何怨恨他们","吉纳维 的怨恨","达比雷 的纠纷"}},{q="达比雷农场在哪里？",a="达比雷农场位于阿拉希，在避难谷地的东北方。",al={"达比雷 农庄位置","农庄在哪里","农庄"}},{q="科娜塔、法迪尔和马塞尔·达比雷是谁？",a="他们就是吉纳维在要求中点名的三个人：科娜塔、法迪尔和马塞尔·达比雷。",al={"达比雷 一家是谁","科娜塔 一家","达比雷 一家的名字"}}},fp="21,179,18.295.0,23.98.0,37.117.0,31.62.0,43.90.0"}
P.entries["quest:1166"] = {n="莫格穆洛克的任务",s="石槌氏族的莫格穆洛克大王身在蕨墙村，想找回他的烈酒、鼻烟和保险箱。他匆忙离开氏族的旧家园时，把这些东西落在了那里，于是派你南下寻找。",h="石槌氏族的莫格穆洛克大王身在蕨墙村，想找回他的烈酒、鼻烟和保险箱。他匆忙离开氏族的旧家园时，把这些东西落在了那里，于是派你南下寻找。",kw={"蕨墙村","火焰洞穴","尘泥","烈酒","莫格穆洛克","雷克萨","鼻烟","石槌","保险箱"},sec={{t="大王的故事",b="莫格穆洛克说，是雷克萨让他成为石槌氏族强大的领袖，而他一直保护着族人的安全。据他说，巨龙来到旧家园，带来了烈火，于是他在尘泥这里为氏族找到了新家园。"},{t="遗落的物品",b="他离开旧家园时太过匆忙，忘了带上自己的东西：烈酒、鼻烟和保险箱。他指引你南下，前往火焰洞穴和石槌废墟，确信东西就在那里。他说自己忙着领导食人魔，没空亲自去。"}},faq={{q="莫格穆洛克大王是谁？",a="莫格穆洛克大王在蕨墙村领导着石槌氏族。据他自己说，是雷克萨让他成为氏族强大的领袖。",al={"莫格穆洛克","食人魔领袖","大王是谁"}},{q="石槌氏族的旧家园发生了什么？",a="莫格穆洛克说，巨龙来到旧家园，带来了烈火，于是他在蕨墙村为氏族找到了新家园。",al={"食人魔为何离开","石槌被毁","巨龙袭击食人魔"}},{q="莫格穆洛克想找回什么？",a="他想找回自己的烈酒、鼻烟和保险箱，这些都是他匆忙离开旧家园时忘了带走的。",al={"莫格穆洛克的物品","他想要什么东西","烈酒 鼻烟 保险箱"}},{q="莫格穆洛克的物品在哪里？",a="他派你南下，确信那些物品就在火焰洞穴和石槌废墟。",al={"物品在哪里","物品位置","寻找烈酒和鼻烟"}},{q="莫格穆洛克为什么不亲自去取东西？",a="他说自己忙着领导食人魔，没空去取那些东西。",al={"莫格穆洛克为什么不去","为什么派我去"}}},fp="29,163,20.214.0,18.241.0,27.113.0,47.139.0,31.105.0,34.99.0,48.77.0"}
P.entries["quest:1167"] = {n="奥萨拉克斯之塔",s="德尔格伦派你北上，在进攻埃瑟里克斯·纳拉辛之前与巴苏尔·影击会面。这位斥候一直监视着奥萨拉克斯之塔，能报告那里发生的变化。",h="德尔格伦派你北上，在进攻埃瑟里克斯·纳拉辛之前与巴苏尔·影击会面。这位斥候一直监视着奥萨拉克斯之塔，能报告那里发生的变化。",kw={"奥萨拉克斯","埃瑟里克斯","巴苏尔","邪教徒","黑海岸","德尔格伦","高塔"},ang={["class:Paladin"]="德尔格伦在行动前先查明危险，展现出圣光战士应有的自律。",["faction:Alliance"]="德尔格伦和巴苏尔携手保卫卡利姆多北部，让人类圣骑士与暗夜精灵斥候并肩作战。",["race:NightElf"]="巴苏尔·影击守护着祖先的土地，抵御巫术的侵害，正如一万年前毁灭暗夜精灵文明的那种肆无忌惮的奥术滥用。"},sec={{t="斥候的报告",b="净化者德尔格伦派你北上，与他的哨兵搭档巴苏尔·影击交谈。你已经净化了被腐化的遗物，削弱了邪教在黑海岸边境一带的势力。在你迎战巫师埃瑟里克斯之前，德尔格伦希望从巴苏尔那里得到最新情报，他一直在俯瞰高塔的废墟中监视。"},{t="高塔异动",b="巴苏尔·影击报告说，高塔上层的密室出现了诡异的异动。如今，刺眼的闪光、痛苦的尖叫和狂乱的闪电撼动着这座古老的精灵高塔。塔内发生的事情，恐怕会让接近埃瑟里克斯的道路更加危险。"}},faq={{q="德尔格伦为什么派我回去找巴苏尔？",a="德尔格伦派你去找巴苏尔，是因为他想在你迎战埃瑟里克斯之前获得最新情报。巴苏尔一直监视着奥萨拉克斯之塔，能报告他在那里看到的情况。",al={"为何去见巴苏尔","与巴苏尔交谈","德尔格伦的命令"}},{q="巴苏尔·影击在哪里？",a="巴苏尔·影击在奥萨拉克斯之塔西边不远的山丘上设有观察营地，监视着黑海岸北部的废墟。",al={"巴苏尔的位置","寻找巴苏尔","巴苏尔在哪里"}},{q="巴苏尔最近在高塔目睹了什么？",a="巴苏尔看到高塔最高处的房间中迸发出刺眼的闪光，随后听见凄惨的尖叫声传遍海岸，还看到狂乱的闪电劈向地面。",al={"高塔发生了什么","巴苏尔 尖叫声","高塔闪光"}},{q="埃瑟里克斯是谁？",a="埃瑟里克斯·纳拉辛是统领奥萨拉克斯之塔邪教徒的黑暗巫师。德尔格伦和巴苏尔决心阻止他的邪恶仪式。",al={"埃瑟里克斯是谁","埃瑟里克斯·纳拉辛","高塔首领"}},{q="净化者德尔格伦是当地的暗夜精灵吗？",a="不是。德尔格伦是一名人类圣骑士，也是圣光的战士，驻守在黑海岸与灰谷的交界处。他与暗夜精灵斥候联手，清除恶魔的腐化。",al={"德尔格伦是谁","德尔格伦的种族","德尔格伦是精灵吗"}},{q="奥萨拉克斯之塔是什么样的遗迹？",a="奥萨拉克斯之塔是一座古老的暗夜精灵高塔，坐落在黑海岸北部崎岖的峭壁旁。它早已被遗弃，后来堕落的奥术师和恶魔教徒占据了这里，用来举行禁忌仪式。",al={"奥萨拉克斯背景","高塔是什么","高塔的历史"}}},fp="22,181,16.323.0,25.275.1,42.164.0,39.157.0,53.168.0,16.148.0,42.178.0,44.188.0"}
P.entries["quest:1168"] = {n="黑龙军团",s="在蕨墙村，食人魔萨尔格想向黑龙大军复仇。萨尔格怨恨莫格穆洛克大王让食人魔逃跑而不是战斗，并请你出手对付火鬃。",h="在蕨墙村，食人魔萨尔格想向黑龙大军复仇。萨尔格怨恨莫格穆洛克大王让食人魔逃跑而不是战斗，并请你出手对付火鬃。",kw={"蕨墙村","尘泥","火鬃","莫格穆洛克","雷克萨","石槌","萨尔格"},sec={{t="血仇",b="黑龙杀死了许多食人魔，萨尔格的妻子也在死者之中。莫格穆洛克是雷克萨任命的大王，他让幸存者逃跑，他们就这样来到了蕨墙村。萨尔格说，食人魔不擅长逃跑，就该战斗，他还认为莫格穆洛克只在乎自己。萨尔格还说，莫格穆洛克让所有食人魔留在原地，守好这个地方。"},{t="南方的家园",b="萨尔格把石槌废墟视为自己的家，他喜欢住在南方。对他来说，蕨墙村不是家。他想向黑龙大军复仇，夺回昔日的家园，因此请你杀死大军中的火鬃斥候和火鬃灰尾龙人。"}},faq={{q="萨尔格是谁？",a="萨尔格是住在蕨墙村的食人魔。他的妻子被黑龙杀害，他想要复仇，回到石槌废墟。",al={"萨尔格的故事","萨尔格是谁","萨尔格 尘泥"}},{q="萨尔格为什么不喜欢莫格穆洛克大王？",a="雷克萨任命莫格穆洛克为大王，但萨尔格说，他在乎权力胜过食人魔。黑龙杀死了许多食人魔，莫格穆洛克让其余的食人魔逃跑，而萨尔格认为食人魔应该战斗。",al={"萨尔格为什么恨莫格穆洛克","莫格穆洛克 胆小鬼","萨尔格与莫格穆洛克"}},{q="萨尔格的妻子遭遇了什么？",a="黑龙杀死了她，也杀死了许多其他食人魔。这是萨尔格想要复仇的根源。",al={"萨尔格的妻子","萨尔格的妻子遭遇了什么","萨尔格的妻子之死"}},{q="食人魔昔日的家园在哪里？",a="萨尔格把石槌废墟视为家园，他喜欢住在南方。他说蕨墙村不是家，他想回去。",al={"石槌 食人魔家园","食人魔从哪里来","石槌废墟的历史"}},{q="黑龙大军由哪些敌人组成？",a="萨尔格让你对付火鬃，其中包括火鬃斥候和火鬃灰尾龙人。",al={"火鬃 龙人","黑龙大军要杀哪些敌人","火鬃 敌人"}}},fp="24,167,20.374.0,17.252.0,13.136.0,43.211.0,30.100.0,29.138.0,51.87.0"}
P.entries["quest:1169"] = {n="群龙之首",s="在蕨墙村，德拉兹辛比称莫格穆洛克是个沉溺于权势的懦弱蠢货，还说萨尔格一边与悲痛和复仇之念抗争，一边争夺氏族的领导权。德拉兹辛比认为，除了自己，没有人在意究竟是谁袭击了故土，因此请你带来十五条 灼热之舌 和十五颗 灼热之心。",h="在蕨墙村，德拉兹辛比称莫格穆洛克是个沉溺于权势的懦弱蠢货，还说萨尔格一边与悲痛和复仇之念抗争，一边争夺氏族的领导权。德拉兹辛比认为，除了自己，没有人在意究竟是谁袭击了故土，因此请你带来十五条 灼热之舌 和十五颗...",kw={"黑龙","蕨墙村","德拉兹辛比","尘泥沼泽","莫格穆洛克","灼热之心","灼热之舌","石槌","萨尔格"},sec={{t="理性的声音",b="德拉兹辛比说，莫格穆洛克沉溺于权势，而萨尔格则在悲痛和复仇的渴望中挣扎，所以在他看来，除了自己，没有人在意究竟是谁在幕后指使了对故土的袭击。德拉兹辛比提到，你或许原以为食人魔说话都会粗鲁不堪。"},{t="心脏与舌头",b="德拉兹辛比需要从雏龙和幼龙身上取来的舌头和心脏，各十五份，以追查这股邪恶的源头。德拉兹辛比希望从黑龙军团那些被烧焦的幼龙身上，查明究竟是哪头可憎的母兽将幼崽放进了食人魔的家园。对敌人了解得更多，食人魔或许就能将它们彻底消灭，让石槌村从废墟中重生。德拉兹辛比补充道，要让莫格穆洛克离开这片沼泽，本身就是一项艰巨的任务。"}},faq={{q="德拉兹辛比是谁？",a="德拉兹辛比是蕨墙村的一名食人魔，谈吐文雅，毫无粗野之气，他想查明究竟是谁在幕后指使了对氏族故土的袭击。",al={"德拉兹辛比","蕨墙村食人魔法师","聪明的食人魔"}},{q="德拉兹辛比想从雏龙和幼龙身上取得什么？",a="德拉兹辛比需要十五条 灼热之舌 和十五颗 灼热之心。这些东西将帮助他追查究竟是哪头母兽将幼崽放进了故土。",al={"灼热之心 用途","为何需要舌头和心脏","群龙之首 目的"}},{q="德拉兹辛比如何看待氏族的领袖？",a="德拉兹辛比对莫格穆洛克没多少敬意，称那个食人魔是个被权力冲昏头脑的懦弱蠢货，而在他口中，萨尔格则深陷悲痛与复仇的渴望。",al={"莫格穆洛克 的问题","萨尔格和 莫格穆洛克","石槌 领袖"}}},fp="21,244,17.268.0,18.454.0,17.148.0,56.172.0,48.164.0"}
P.entries["quest:117"] = {n="雷酒",s="在西部荒野，葛瑞姆·雷酒正在收集新鲜的啤酒花，准备酿造下一批酒。没有啤酒花，他的麦酒可能会变得像炖汤一样浓稠，因此他会送出成桶的酒，回报那些带来所需材料的人。",h="在西部荒野，葛瑞姆·雷酒正在收集新鲜的啤酒花，准备酿造下一批酒。没有啤酒花，他的麦酒可能会变得像炖汤一样浓稠，因此他会送出成桶的酒，回报那些带来所需材料的人。",kw={"啤酒","酿酒","矮人","葛瑞姆","啤酒花","酒桶","贮藏啤酒","雷酒","西部荒野"},ang={["profession:Cooking"]="身为厨师，你知道大麦、麦芽和啤酒花的用量必须平衡，正如传统矮人酿酒工艺中的各种原料一样。",["race:Dwarf"]="身为矮人，看到一位同胞在西部荒野崎岖的边疆延续卡拉诺斯的酿酒传统，你或许会感到欣喜，尤其是还有成桶的酒。"},sec={{t="西部荒野的矮人热忱",b="远离丹莫罗，葛瑞姆依然延续着家族的酿酒传统。他坚持为眼下这批酒选用合适的啤酒花，否则酿出来的可能是浓稠的炖汤，而非清爽的麦酒。"},{t="酒桶中的技艺",b="葛瑞姆用欢快的韵文赞颂啤酒花、大麦、酵母和麦芽。有了新鲜的啤酒花，他就能当场完成发酵。作为回报，他会送出整桶的雷霆啤酒，这种酒以浓烈的口感闻名。"}},faq={{q="葛瑞姆·雷酒是谁？",a="葛瑞姆·雷酒是一位游历西部荒野的矮人酿酒师。无论在哪里扎营，他都延续着氏族的酿酒传统，吟唱欢快的韵文。",al={"葛瑞姆","葛瑞姆是谁","葛瑞姆的故事"}},{q="葛瑞姆为什么需要啤酒花？",a="没有新鲜的啤酒花，葛瑞姆最新酿造的这批酒可能会像炖汤一样浓稠厚重，而非清爽的贮藏啤酒。啤酒花能为酒增添苦味，平衡口感。",al={"为什么需要啤酒花","葛瑞姆啤酒花","啤酒花有什么用"}},{q="雷霆啤酒是什么？",a="雷霆啤酒是雷酒家族酿造的一种烈性矮人酒。葛瑞姆会成桶地送出这种酒，它浓烈的滋味直冲味蕾。",al={"雷酒 啤酒","一桶 雷酒","雷酒 是什么"}},{q="可以多次给葛瑞姆带啤酒花吗？",a="可以。葛瑞姆欢迎更多的啤酒花，也会拿出更多桶自己酿的酒作为回报。",al={"可重复任务","雷酒 可以重复吗","更多酒桶"}},{q="这项任务在哪里进行？",a="这项工作在西部荒野进行，葛瑞姆在那里扎营，在农田间收集物资。",al={"雷酒 位置","葛瑞姆在哪里","任务区域"}},{q="葛瑞姆与丹莫罗的雷酒家族有亲属关系吗？",a="有。葛瑞姆与丹莫罗卡拉诺斯的雷酒家族同姓，也同样以酿酒为业。",al={"雷酒酿制厂","葛瑞姆的氏族","雷酒 家族"}}},fp="11,173,29.178.0,18.203.0,29.155.0,29.150.0,26.150.0,44.77.0,32.97.0,55.106.0"}
P.entries["quest:1170"] = {n="奥妮克希亚的血脉",s="德拉兹辛比讲述了奥妮克希亚的子嗣入侵石槌村的事，并疑惑死亡之翼的女儿为何会来到这片土地。你受命前往蕨墙村，将消息带给莫格穆洛克大王。",h="德拉兹辛比讲述了奥妮克希亚的子嗣入侵石槌村的事，并疑惑死亡之翼的女儿为何会来到这片土地。你受命前往蕨墙村，将消息带给莫格穆洛克大王。",kw={"蕨墙村","死亡之翼","德拉兹辛比","尘泥沼泽","莫格穆洛克","奥妮克希亚","石槌"},sec={{t="令人不安的来客",b="石槌村遭到了奥妮克希亚子嗣的入侵，死亡之翼的女儿竟会降临这片土地，这让德拉兹辛比感到不安。德拉兹辛比确信，奥妮克希亚来到这里，绝不只是为了围攻几个食人魔。他希望立即将消息告诉蕨墙村的莫格穆洛克大王，以便采取行动。"},{t="传信蕨墙村",b="莫格穆洛克并不欢迎这个消息。大王讨厌巨龙，喜欢待在蕨墙村，还说这里没有巨龙。"}},faq={{q="是谁派你去与莫格穆洛克大王交谈的？",a="奥妮克希亚的子嗣入侵石槌村后，德拉兹辛比派你前去。",al={"谁开启奥妮克希亚的子嗣任务","奥妮克希亚的子嗣任务给予者"}},{q="在哪里可以找到莫格穆洛克大王？",a="你可以在蕨墙村找到莫格穆洛克大王。",al={"莫格穆洛克位置","莫格穆洛克在哪里","莫格穆洛克大王 尘泥"}},{q="德拉兹辛比为何担忧奥妮克希亚的子嗣？",a="德拉兹辛比疑惑死亡之翼的女儿为何会来到这片土地，并确信她绝不只是为了围攻一小群食人魔。",al={"德拉兹辛比为何在意巨龙","德拉兹辛比对奥妮克希亚的担忧"}}},fp="19,82,20.290.0,19.170.1,48.90.0,39.56.0,48.139.0"}
P.entries["quest:1171"] = {n="奥妮克希亚的血脉",s="莫格穆洛克大王不想听任何关于巨龙的事。他说这里没有黑龙，并让你回蕨墙村告诉德拉兹辛比，食人魔会留在原地。",h="莫格穆洛克大王不想听任何关于巨龙的事。他说这里没有黑龙，并让你回蕨墙村告诉德拉兹辛比，食人魔会留在原地。",kw={"蕨墙村","奥妮克希亚的子嗣","德拉兹辛比","尘泥沼泽","莫格穆洛克","雷克萨"},sec={{t="别来烦我",b="德拉兹辛比传来奥妮克希亚子嗣的消息后，莫格穆洛克大王只想清静清静。莫格穆洛克说食人魔会留在原地，这里没有黑龙，还让你去蕨墙村把这话告诉德拉兹辛比。"},{t="德拉兹辛比的说法",b="德拉兹辛比对这个答复很不满，骂大王是个懒惰的胆小鬼。德拉兹辛比说，雷克萨带领他们时，莫格穆洛克曾表现得很强大，但雷克萨离开后，他便受到了权力的诱惑。如今，莫格穆洛克只会要求食人魔为他效劳，却不再领导他们，德拉兹辛比说必须采取行动。"}},faq={{q="莫格穆洛克大王为什么拒绝采取行动？",a="莫格穆洛克说这里没有黑龙，只想清静清静。他让你给德拉兹辛比带话，说食人魔会留在原地。",al={"莫格穆洛克为什么不帮忙","莫格穆洛克的反应","为什么没有黑龙"}},{q="这段剧情之前发生了什么？",a="此前是奥妮克希亚的血脉，德拉兹辛比在其中派你把奥妮克希亚子嗣的消息带给莫格穆洛克。",al={"这个任务的前置任务","任务链顺序"}},{q="这发生在哪里？",a="莫格穆洛克和德拉兹辛比都在蕨墙村。",al={"这个任务在哪里","位置"}}},fp="19,181,14.226.0,19.250.1,43.167.0,40.122.0,27.66.0"}
P.entries["quest:1172"] = {n="奥妮克希亚的血脉",s="蕨墙村的德拉兹辛比不愿再有一只奥妮克希亚的雏龙孵化。你受命前往沼泽南部的巨龙沼泽附近，寻找并摧毁这条黑龙的龙蛋。",h="蕨墙村的德拉兹辛比不愿再有一只奥妮克希亚的雏龙孵化。你受命前往沼泽南部的巨龙沼泽附近，寻找并摧毁这条黑龙的龙蛋。",kw={"蕨墙村","奥妮克希亚的子嗣","黑龙谷","德拉兹辛比","莫格穆洛克","奥妮克希亚","石槌","巨龙沼泽"},sec={{t="巨龙沼泽的龙蛋",b="奥妮克希亚的子嗣散布在黑龙谷各处。德拉兹辛比催促你尽快行动：巨龙沼泽位于沼泽南部，他确信这条巨龙已在那里筑巢，龙蛋遍布巢穴四周。只要石槌村周围的土地还是巨龙的筑巢之地，食人魔就永远无法夺回家园，因此你受命去寻找并摧毁那些龙蛋。"},{t="最后一个请求",b="龙蛋被摧毁后，德拉兹辛比说，奥妮克希亚还要过一段时间才能再次产卵，并代表石槌氏族向你致谢。随后，德拉兹辛比又请你帮最后一个忙。德拉兹辛比认为莫格穆洛克不配担任领袖，而萨尔格虽是出色的领袖人选，却受伤病和年老所累。他请你用武力赶走莫格穆洛克，让一位新领袖带领氏族重返南方本属于他们的家园。"}},faq={{q="谁会给予这个任务？",a="蕨墙村的德拉兹辛比派你去摧毁奥妮克希亚的龙蛋。",al={"奥妮克希亚的子嗣任务由谁给予","奥妮克希亚的子嗣任务给予者","德拉兹辛比任务"}},{q="为什么必须摧毁龙蛋？",a="德拉兹辛比不愿再有奥妮克希亚的雏龙孵化。只要石槌村周围的土地还是巨龙的筑巢之地，食人魔就永远无法夺回家园。",al={"为什么摧毁奥妮克希亚的龙蛋","为什么砸碎龙蛋","石槌村 龙蛋"}},{q="龙蛋在哪里？",a="在沼泽南部的巨龙沼泽周围。德拉兹辛比确信奥妮克希亚已在那里筑巢。",al={"奥妮克希亚的龙蛋在哪里","奥妮克希亚的龙蛋位置","巨龙沼泽在哪里"}},{q="这一步在整个任务链中处于什么位置？",a="此前，莫格穆洛克得知龙族子嗣的消息后拒绝采取行动，你将他的答复带回给德拉兹辛比，随后便接到这一步任务。",al={"奥妮克希亚的子嗣任务链","奥妮克希亚的子嗣前置任务","奥妮克希亚的子嗣第三步之前是什么"}}},fp="19,100,23.299.0,16.401.1,21.68.0,38.140.0,27.99.0,46.104.0"}
P.entries["quest:1173"] = {n="挑战莫格穆洛克",s="莫格穆洛克大王对你的挑战嗤之以鼻，扬言要碾碎你，还让你准备好挨揍时就开口。蕨墙村的德拉兹辛比原本希望看到莫格穆洛克被赶出村子。",h="莫格穆洛克大王对你的挑战嗤之以鼻，扬言要碾碎你，还让你准备好挨揍时就开口。蕨墙村的德拉兹辛比原本希望看到莫格穆洛克被赶出村子。",kw={"蕨墙村","挑战莫格穆洛克大王","德拉兹辛比","尘泥沼泽","莫格穆洛克","石槌"},sec={{t="挑战大王",b="你走到莫格穆洛克大王面前，他嘲笑你的胆量，扬言要碾碎你，还让你准备好挨揍时就开口。这发生在奥妮克希亚的血脉之后。蕨墙村的德拉兹辛比盼着看到莫格穆洛克被赶出村子，不明白你为什么回来只是为了说话。"},{t="向德拉兹辛比回报",b="战斗获胜后，德拉兹辛比说莫格穆洛克像个懦夫一样逃走了，并感谢你帮了大忙。莫格穆洛克离开后，食人魔就能选出一位新首领，帮助他们彻底夺回昔日的家园。"}},faq={{q="你要挑战谁？",a="你在蕨墙村挑战莫格穆洛克大王。大王大笑着回应，吹嘘自己会碾碎你。",al={"与谁战斗","挑战目标","莫格穆洛克是谁"}},{q="这次挑战之前是什么任务？",a="前一个任务是奥妮克希亚的血脉。",al={"前一个任务是什么","前置任务","上一个任务"}},{q="战斗结束后向谁回报？",a="你要向蕨墙村的德拉兹辛比回报。",al={"向谁交任务","交任务的非玩家角色","击败莫格穆洛克后去哪里"}},{q="德拉兹辛比对你有什么期望？",a="德拉兹辛比盼着看到莫格穆洛克被赶出村子，不明白你为什么回来只是为了说话。",al={"为什么与莫格穆洛克战斗","为什么挑战大王","战斗的原因"}}},fp="29,145,27.288.0,18.208.1,21.102.0,33.48.0,37.64.0,34.101.0"}
P.entries["quest:1174"] = {n="Gnomes Win!",s="在千针石林，侏儒获胜时，侏儒优惠券就能兑现奖励。持有获胜票根的人会得到一个奖品盒。",h="在千针石林，侏儒获胜时，侏儒优惠券就能兑现奖励。持有获胜票根的人会得到一个奖品盒。",kw={"侏儒优惠券","侏儒的奖品盒","侏儒获胜","竞赛","千针石林"},sec={{t="侏儒优惠券",b="侏儒优惠券是侏儒获胜时用来兑奖的票根。保管好它，结果一出，你就能获得一个侏儒获胜者宝箱。地精优惠券也有对应的结果，代表比赛的另一方。"}},faq={{q="侏儒优惠券是什么？",a="这是千针石林竞赛中支持侏儒一方的票券。侏儒获胜时，它就派上用场了。",al={"侏儒优惠券","侏儒优惠券是什么","竞赛票券用途"}},{q="侏儒获胜后能得到什么？",a="侏儒获胜时，持有侏儒优惠券的人会得到一个侏儒礼品盒。",al={"侏儒奖品箱","侏儒获胜奖励"}},{q="谁能参与这场赌局？",a="它不属于任何阵营，因此联盟和部落的旅者都能平等参与。",al={"部落能否下注","联盟能否下注","中立票券"}},{q="如果获胜的是地精呢？",a="那就轮到地精优惠券派上用场了。它对应的结果叫作地精获胜!，与这里的结果相对。",al={"地精获胜","地精优惠券"}}},fp="11,122,16.133.0,30.107.0,36.79.0,32.90.0,40.111.0"}
P.entries["quest:1175"] = {n="安全隐患",s="赛道管理员泽尔林负责照看沙漠赛道，而闪光平原上的野兽已经长得十分庞大，必须控制它们的数量，以免它们闯入赛道。你受托去削减盐石蜥蜴、水晶蜥蜴和凝视者的数量。",h="赛道管理员泽尔林负责照看沙漠赛道，而闪光平原上的野兽已经长得十分庞大，必须控制它们的数量，以免它们闯入赛道。你受托去削减盐石蜥蜴、水晶蜥蜴和凝视者的数量。",kw={"水晶之皮","凝视者","沙漠赛道","红雷","盐石蜥蜴","闪光平原","塔霍达废墟","赛道管理员泽尔林","维吉尔之坑"},sec={{t="保持赛道畅通",b="一只蜥蜴曾与地精的赛车红雷相撞，事后科鲁克莱德便雇用了泽尔林来照看赛道。泽尔林说不清闪光平原上的野兽究竟吃了什么，才长得如此庞大，只知道必须控制它们的数量，否则就会有野兽在比赛中途闯入赛道。清理残骸已经够麻烦了，泽尔林可不想还得从烧焦的野兽残肢中把残骸捡出来。"}},faq={{q="赛道管理员泽尔林是谁？",a="闪光平原上沙漠赛道的管理员，受科鲁克莱德雇用，负责照看赛道。",al={"泽尔林是谁","赛道管理员泽尔林","泽尔林的故事"}},{q="为什么要猎杀蜥蜴？",a="平原上的野兽已经长得十分庞大，若有一只在比赛期间闯入赛道，就可能引发撞车事故，地精的红雷就曾与一只蜥蜴相撞。",al={"为什么杀蜥蜴","为什么蜥蜴必须死","蜥蜴问题"}},{q="红雷是什么？",a="地精的一辆赛车，在与一只蜥蜴相撞后损毁。",al={"红雷","红雷撞车","地精的红雷"}},{q="平原上的蜥蜴通常在哪里出没？",a="它们在闪光平原各处游荡，但在维吉尔之坑附近和塔霍达废墟中更为密集。",al={"蜥蜴位置","蜥蜴在哪里","哪里能找到盐石"}}},fp="18,186,23.439.0,26.115.0,35.165.0,24.85.0,51.119.0"}
P.entries["quest:1176"] = {n="减轻负重",s="普兹克是沙漠赛道的地精首席工程师，他需要一些材料，为火箭赛车的底盘减去至关重要的几盎司重量。地精们没有完全依赖沉重的金属板，而是收集当地沙漠秃鹫的中空骨骼，用来制造坚固而极其轻巧的转向机构和支撑结构。",h="普兹克是沙漠赛道的地精首席工程师，他需要一些材料，为火箭赛车的底盘减去至关重要的几盎司重量。地精们没有完全依赖沉重的金属板，而是收集当地沙漠秃鹫的中空骨骼，用来制造坚固而极其轻巧的转向机构和支撑结构。",kw={"骨骼","减轻负重","沙漠赛道","普兹克","火箭赛车","闪光平原","千针石林","秃鹫"},ang={["profession:Engineering"]="普兹克依靠鸟骨搭建框架，展现了典型的地精才智：实用、因陋就简，而且在减轻赛车自重方面出奇地有效。",["race:Gnome"]="看着地精真的把捡来的鸟尸绑进机械转向机构里，任何受过正统训练的侏儒区工程师都难免大惊失色。"},sec={{t="每一盎司都重要",b="闪光平原一片白茫茫，令人目眩，地精与侏儒工程师之间的胜负就在几分之一秒间决定。要是赛车过于笨重，光有强大的引擎推力也无济于事。侏儒车队痴迷于精巧的齿轮和黄铜配件，而普兹克带领的地精团队则一味追求实用与效率：只要车架结构允许，就拆掉沉重的铁制框架，换上更轻的中空构件。"},{t="荒漠拾荒，竞逐速度",b="普兹克没有把昂贵的特制复合材料运到千针石林，而是将目光投向了周围的盐碱荒地。闪光平原的秃鹫数量众多，飞行的需要让它们的骨骼内部形成了中空的蜂窝结构，几乎不增加重量，却能承受很大的拉力。普兹克的机械师将加工过的秃鹫骨骼装入赛车的转向机构和小型支架，希望让赛车足够灵活，能够在操控上胜过侏儒，同时又不至于在全速行驶时震散架。"}},faq={{q="普兹克为什么要用秃鹫骨骼制造赛车？",a="地精工程学讲究奇思妙想，也善于就地取材。秃鹫骨骼内部中空，天生轻巧，强度与重量的比例十分理想，既能加固转向机构之类的精细部件，又不会加重赛车的负担。",al={"秃鹫骨骼用途","为什么用骨骼","普兹克骨骼"}},{q="普兹克是谁？",a="普兹克是驻扎在闪光平原沙漠赛道的地精首席赛车机械师兼车队领队。他指挥地精维修区，与他们的死对头侏儒一较高下。",al={"普兹克","普兹克背景","地精工程师是谁"}},{q="这些秃鹫在哪里出没？",a="食腐鸟和秃鹫在闪光平原的开阔地带盘旋，尤其常见于盐盆地东北部散落的巨大骸骨周围。",al={"秃鹫位置","哪里有中空骨骼","闪光平原食腐鸟"}},{q="沙漠赛道是什么地方？",a="沙漠赛道是一处中立的竞速场地，建在千针石林辽阔的干涸盐湖上。地精和侏儒在那里驾驶试验性火箭赛车，展开高速而危险的竞赛。",al={"赛道背景","沙漠赛道是什么","闪光平原赛道"}},{q="侏儒也在采用同样的办法吗？",a="侏儒也在设法精简赛车，但他们的工程传统更偏向精密的发条机构和复杂的金属工艺，而地精则擅长用回收材料拼凑改装。",al={"侏儒赛车手","侏儒与地精","侏儒也用骨骼吗"}},{q="这项工作对普兹克更长远的赛车计划有帮助吗？",a="有。帮助赛车减重，证明你办事可靠，就能赢得普兹克的信任，随后便会有更多工作，涉及平原上的赛道竞争和地精的正式赞助。",al={"后续任务","地精赞助"}}},fx={a8fc0189={q="普兹克为什么如此执着于减轻赛车的重量？",a="在沙漠赛道，速度决定一切，比赛往往只差微乎其微的优势。普兹克正与侏儒工程师直接较量，任何多余的重量都可能让他在盐滩上痛失胜利。尽可能减轻车架和转向装置的重量，可以让他的火箭赛车达到最大加速度，同时不牺牲结构强度。",al={"普兹克的动机","为什么要减轻赛车重量","普兹克为什么需要轻型零件"}},["8208273d"]={q="闪光平原为什么有这么多秃鹫？",a="闪光平原是一片严酷、被烈日炙烤的荒地，遍布巨型古兽和倒下的旅人留下的遗骸。以盐滩为生的食腐动物在这里繁衍，它们盘旋在空中，啄食恶劣沙漠气候以及平原上凶猛的石化蜥蜴和蝎子留下的腐肉。",al={"闪光平原为什么有秃鹫","盐滩秃鹫的背景","千针石林的秃鹫"}}},fp="15,168,18.323.0,27.366.0,50.173.0,14.137.0,31.130.0,27.149.0,36.163.0,55.127.0"}
P.entries["quest:1177"] = {n="饿！",s="马德克拉什是尘泥沼泽北部的一个食人魔，他饿了。马德要你去痛打那些满身鱼腥味的泥鳍鱼人，把他们的脑袋带回来，否则马德就吃了你。",h="马德克拉什是尘泥沼泽北部的一个食人魔，他饿了。马德要你去痛打那些满身鱼腥味的泥鳍鱼人，把他们的脑袋带回来，否则马德就吃了你。",kw={"尘泥沼泽","鱼腥味","饿了！","泥鳍的脑袋","马德克拉什","食人魔"},sec={{t="饥饿的食人魔",b="马德克拉什是个大块头食人魔，他自己也直言不讳。马德饿了，提出了一笔简单的交易：去痛打那些满身鱼腥味的泥鳍鱼人，把他们的脑袋带回来给马德当食物。喂饱马德，否则马德就吃了你。"}},faq={{q="马德克拉什是谁？",a="马德克拉什是尘泥沼泽北部的一个大块头食人魔，叫作马德。马德饿了，想要吃的。",al={"马德克拉什","马德克拉什是谁","尘泥沼泽的食人魔"}},{q="马德克拉什想吃什么？",a="马德想要泥鳍鱼人的脑袋，要你去痛打那些满身鱼腥味的泥鳍鱼人，再把脑袋带回来。",al={"马德克拉什的食物","食人魔想要什么","饥饿任务食物"}},{q="如果你不肯喂饱他，会怎么样？",a="马德说得很明白：喂饱马德，否则马德就吃了你。",al={"马德克拉什的威胁","马德克拉什会吃我吗"}}},fp="7,153,13.150.0,25.110.0,40.60.0,39.57.0"}
P.entries["quest:1178"] = {n="地精赞助商",s="地精赛车队的普兹克正在等加兹鲁维几周前答应送来的燃料调节器原型，可东西一直没到。加兹鲁维通常办事很及时，所以普兹克请你去棘齿城问问出了什么事，因为侏儒正在追赶他们的车队。",h="地精赛车队的普兹克正在等加兹鲁维几周前答应送来的燃料调节器原型，可东西一直没到。加兹鲁维通常办事很及时，所以普兹克请你去棘齿城问问出了什么事，因为侏儒正在追赶他们的车队。",kw={"燃料调节器","加兹鲁维","沙漠赛道","普兹克","棘齿城","闪光平原","工匠协会","安德迈"},sec={{t="承诺的零件",b="普兹克称赛车队是地精的骄傲，还说许多人都在以各种方式帮助车队。加兹鲁维为车队四处搜罗世界各地的零件，有一次甚至亲自来修整他们的一辆赛车。几周前，加兹鲁维说会送来一个新的燃料调节器原型，可东西至今没有送到，这可不像他的作风。眼看侏儒正在赶上来，普兹克请你去棘齿城找加兹鲁维问问。"},{t="谈起普兹克",b="加兹鲁维听说你是普兹克派来的，便提到普兹克在退休、转而钻研赛车之前，曾是安德麦最受尊敬的工匠之一。普兹克加入车队后做的第一件事，就是设计双引擎型号的赛车。加兹鲁维承认，少了普兹克为技工协会效力，生意也许会受影响，但他说，没有什么比赛车更精彩。"}},faq={{q="普兹克为什么需要你去棘齿城？",a="加兹鲁维几周前说会送来一个燃料调节器原型，可东西一直没到。普兹克请你去棘齿城找他问问。",al={"为什么去棘齿城","普兹克的差事","地精赞助商任务目标"}},{q="加兹鲁维为赛车队做些什么？",a="他为车队四处搜罗世界各地的零件，有一次甚至亲自来修整他们的一辆赛车。",al={"加兹鲁维的参与","加兹鲁维赛道赞助","加兹鲁维是赞助者吗"}},{q="前一个任务是什么？",a="前一个任务是减轻负重，同样由普兹克交付。",al={"地精赞助商前置任务","地精赞助商之前是什么任务"}},{q="地精车队为什么这么着急？",a="普兹克说侏儒正在赶上他们。",al={"为什么急需燃料调节器","地精与侏儒的赛车较量"}}},fp="18,133,15.364.0,18.292.1,42.135.0,41.91.0,23.49.0,34.54.0"}
P.entries["quest:1179"] = {n="防撞头盔",s="身处铁炉堡的飞行员比罗·长须需要一名信使将一箱加固过的攻城机头盔送过大海，运往卡利姆多。他的朋友——铜栓兄弟，正在闪光平原测试高速火箭车，他们那些经常出事故的试车手急需头部防护。",h="身处铁炉堡的飞行员比罗·长须需要一名信使将一箱加固过的攻城机头盔送过大海，运往卡利姆多。他的朋友——铜栓兄弟，正在闪光平原测试高速火箭车，他们那些经常出事故的试车手急需头部防护。",kw={"铜栓","铁炉堡","沙漠赛道","飞行员比罗·长须","火箭车","闪光平原","千针石林","维兹尔·铜栓"},ang={["profession:Engineering"]="这是一次典型的工程补给任务，连接了矮人重甲工艺与侏儒高速推进实验。",["race:Dwarf"]="只有坚固的矮人攻城机护甲才能厚实到足以在盐碱滩上发生的侏儒火箭全速碰撞中幸存下来。",["race:Gnome"]="铜栓兄弟对极致速度的追求展现了典型的侏儒野心，在这种野心中，机械创新被置于绝对优先地位，而刹车和驾驶员寿命等细枝末节则被忽略不计。"},sec={{t="远距离的援手",b="当矮人飞行员比罗·长须驻扎在铁炉堡的飞行机械旁时，收到了来自卡利姆多南部闪光平原的紧急请求。他的朋友，一对名为铜栓兄弟的侏儒发明家，在那片广袤的盐碱地上定居下来，以测试实验性机械。长须因军事和飞行任务脱不开身，无法亲自运送补给。"},{t="高速下的安全",b="铜栓兄弟的火箭车速度快得惊人，快到他们的试车手不断在盐碱地上翻车，并遭受严重的脑震荡。长须弄到了一箱重型矮人攻城机头盔来保护他们的颅骨。运送这箱头盔为这些侏儒提供了急需的筹码，能说服那些不情愿的飞行员重新坐回他们那不稳定的高速机器驾驶座上。"}},faq={{q="谁是飞行员比罗·长须？",a="飞行员比罗·长须是一位位于铁炉堡的矮人飞行员。作为铜栓兄弟的熟人，他充当了他们在东部王国的补给联系人，为他们采购在野外难以制造的重型矮人装备。",al={"飞行员比罗·长须","任务发布者","谁发布任务"}},{q="谁是铜栓兄弟？",a="铜栓兄弟，包括维兹尔·铜栓在内，都是雄心勃勃的侏儒工程师，他们在闪光平原的沙漠赛道建立了基地。他们终日致力于设计和调试尖端的火箭车，以在竞速中击败地精竞争对手。",al={"铜栓兄弟","维兹尔·铜栓","侏儒兄弟"}},{q="闪光平原在哪里？",a="闪光平原是一片位于卡利姆多南部、穿过千针石林高耸峡谷柱后的广阔盐碱平原。其平坦且无障碍的广袤地形，使其成为测试实验性高速载具的理想试验场。",al={"闪光平原位置","送往何处","赛道在哪里"}},{q="为什么侏儒需要攻城机头盔？",a="铜栓兄弟的火箭车能达到极高的速度，但其转向和稳定性却令人不敢恭维。驾驶员撞车和脑震荡的频率太高，以至于没有试飞员愿意在没有厚实矮人头部防护的情况下坐进驾驶座。",al={"为什么需要头盔","防撞头盔","火箭车撞车"}},{q="为什么长须不亲自运送？",a="飞行员比罗·长须受限于他在铁炉堡的军事义务和职责。因为跨越无尽之海前往卡利姆多南部的长途旅行意味着擅离职守，所以他只能依靠来往的冒险者来运送这箱沉重的货物。",al={"为什么不是长须","长须的职责"}},{q="部落玩家能完成这个任务吗？",a="不能。这个任务由联盟主城铁炉堡的飞行员比罗·长须发布，仅限联盟信使完成，尽管沙漠赛道本身欢迎两个阵营的玩家。",al={"这是联盟专属吗","部落版本","阵营"}}},fp="23,196,21.337.0,23.377.0,23.214.0,32.195.0,30.208.0,44.245.0,43.204.0,37.161.0"}
P.entries["quest:118"] = {n="马掌",s="弗纳·奥斯古在湖畔镇的铁料已经用尽，而守卫的装备仍需不断修补。他派你向西穿过艾尔文森林，去向闪金镇的铁匠阿古斯求取马蹄铁。",h="弗纳·奥斯古在湖畔镇的铁料已经用尽，而守卫的装备仍需不断修补。他派你向西穿过艾尔文森林，去向闪金镇的铁匠阿古斯求取马蹄铁。",kw={"艾尔文","闪金镇","马蹄铁","铁","湖畔镇","赤脊山","铁匠阿古斯","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇依赖闪金镇供应物资，可见暴风城摄政期间，王国的后勤补给已捉襟见肘。",["profession:Blacksmithing"]="边境的铁匠必须把稀缺的材料用来保住士兵的性命，留给普通农庄的所剩无几。"},sec={{t="不堪重负的边境",b="湖畔镇面临豺狼人、兽人和鱼人的威胁，暴风城却鲜有援助。驻军每天都在奋战，竭力守住城镇，而战斗很快就让他们的装备破损不堪。弗纳·奥斯古几乎把所有醒着的时间都用来修补凹陷的胸甲、重新锻打变钝的剑，让守卫始终有铁甲护身。这些工作已经耗尽了他的原料储备。"},{t="通往艾尔文的补给线",b="没有铁料，边境城镇就连日常劳作也可能停摆。马匹没有马蹄铁，就无法载着信使疾驰，也无法沿着赤脊山崎岖的山路运送物资。弗纳放下自尊，派你沿三角路口的道路向西前往闪金镇。那里的铁匠阿古斯仍能定期从王国的矿产储备中获得原料。"}},faq={{q="弗纳为什么没有铁料了？",a="湖畔镇的守卫不断遭到凶猛野兽、豺狼人和黑石兽人的袭击。弗纳把铁料都用来修补他们破损的护甲和武器，已无余料供平民使用。",al={"为什么没有铁料","弗纳金属耗尽","湖畔镇缺铁"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是艾尔文森林闪金镇的铁匠。与湖畔镇这样的边境城镇相比，他的铁匠铺更容易获得金属锭和物资。",al={"阿古斯闪金镇","阿古斯是谁","闪金镇的铁匠"}},{q="湖畔镇为什么得不到暴风城的物资？",a="瓦里安·乌瑞恩国王失踪期间，暴风城的统治者陷入了政务停滞。贵族扣住兵力和资金，让湖畔镇这样的边境城镇只能依靠尽力维持的地区贸易自谋生路。",al={"暴风城为什么不援助","湖畔镇被忽视","暴风城疏于照顾"}},{q="马蹄铁为什么在赤脊山如此重要？",a="赤脊山多岩石的地形会迅速磨损没有钉铁的马蹄。没有马蹄铁，信使的坐骑、拉补给车的马匹和巡逻坐骑都可能跛足，使湖畔镇与王国其他地方断绝联系。",al={"为什么需要马蹄铁","马蹄铁为何重要"}},{q="找到铁匠阿古斯之后会发生什么？",a="阿古斯收下弗纳的便笺，给你马蹄铁，让你带回湖畔镇。镇上的人们仍在苦苦坚守。",al={"下一个任务","找完阿古斯之后"}},{q="铁匠阿古斯在闪金镇的什么地方？",a="铁匠阿古斯在闪金镇狮王之傲旅店附近的露天熔炉旁工作，就在艾尔文森林主路边。",al={"阿古斯在哪里","阿古斯位置"}}},fp="18,170,32.336.0,22.319.0,26.195.0,19.155.0,48.244.0,43.186.0,40.123.0,42.114.0"}
P.entries["quest:1180"] = {n="地精赞助商",s="加兹鲁维又谈起了你的来意：答应给普兹克的燃油调节器还没运到棘齿城。藏宝海湾的里维加兹说过会安排运来，但这件事可能被遗漏了。加兹鲁维让你去那里找码头管理员罗兹基尔，他可以查阅货运记录。",h="加兹鲁维又谈起了你的来意：答应给普兹克的燃油调节器还没运到棘齿城。藏宝海湾的里维加兹说过会安排运来，但这件事可能被遗漏了。加兹鲁维让你去那里找码头管理员罗兹基尔，他可以查阅货运记录。",kw={"藏宝海湾","燃油调节器","加兹鲁维","地精赞助商","沙漠赛道","普兹克","棘齿城","里维加兹","码头管理员罗兹基尔"},sec={{t="迟迟未到的零件",b="加兹鲁维承认，他答应给普兹克一个新的燃油调节器，可至今还没收到。藏宝海湾的里维加兹说过会安排运来，但这件事可能被遗漏了。如果真是这样，也没什么办法，不过你至少可以查明它是否已经从藏宝海湾发出。码头管理员罗兹基尔就在藏宝海湾码头最西北端，他可以查阅货运记录。"},{t="码头管理员的记录",b="罗兹基尔查阅了运往棘齿城的货运日志。最近一批是崔斯里克发来的靴子，除此之外，运来的都只有建筑材料和工具。没有赛车零件。"}},faq={{q="缺的是哪个零件？",a="加兹鲁维答应给普兹克一个新的燃油调节器，但加兹鲁维至今还没收到。",al={"普兹克的零件","为什么需要燃油调节器","普兹克的货物"}},{q="谁说过会把调节器运到棘齿城？",a="藏宝海湾的里维加兹说过会安排把它运给棘齿城的加兹鲁维。",al={"谁运送零件","里维加兹的零件","燃油调节器在谁手里"}},{q="谁保管藏宝海湾的货运记录？",a="码头管理员罗兹基尔，他可以查阅货运记录。他就在藏宝海湾码头最西北端。",al={"藏宝海湾货运管理员","码头管理员罗兹基尔是谁","罗兹基尔在哪里"}},{q="这一步在任务链中处于什么位置？",a="这一步接在第一个地精赞助商之后，在那个任务中，普兹克派你去找加兹鲁维，下一步则是地精赞助商 (3)。",al={"地精赞助商任务链","任务进度","前一个任务是什么"}}},fp="18,264,22.364.0,25.197.1,21.88.0,50.77.0,44.117.0,38.114.0"}
P.entries["quest:1181"] = {n="地精赞助商",s="在沙漠赛道，地精赛车手们仍在等待失踪的燃油调节器。码头管理员罗兹基尔让你去藏宝海湾，向大财主里维加兹求助。",h="在沙漠赛道，地精赛车手们仍在等待失踪的燃油调节器。码头管理员罗兹基尔让你去藏宝海湾，向大财主里维加兹求助。",kw={"大财主里维加兹","藏宝海湾","燃油调节器","地精赞助商","沙漠赛道","棘齿城","码头管理员罗兹基尔"},sec={{t="向大财主求助",b="对于追查那批运往棘齿城的失踪货物，码头管理员罗兹基尔已经无能为力。他让你去找大财主里维加兹，因为大财主最了解自己的生意。你可以在藏宝海湾港口对面的旅店顶层找到他。"},{t="大财主的答复",b="大财主里维加兹知道燃油调节器失踪的事，却帮不上忙。他派了一些手下去寻找调节器的设计图，但他们空手而归。"}},faq={{q="在哪里可以找到大财主里维加兹？",a="大财主里维加兹就在藏宝海湾港口对面的旅店顶层。",al={"大财主里维加兹位置","里维加兹 在哪里","藏宝海湾寻找 里维加兹"}},{q="码头管理员罗兹基尔为什么让你去找里维加兹？",a="码头管理员罗兹基尔已经帮不上什么忙了，并说大财主最了解自己的生意。",al={"为什么与 里维加兹 交谈","罗兹基尔 派去找大财主","为什么找大财主里维加兹"}},{q="正在追查的是什么货物？",a="这批货物是一个运往棘齿城的新燃油调节器，供沙漠赛道的地精赛车手使用。",al={"什么货物失踪了","正在寻找什么","棘齿城失踪货物"}},{q="这一步在任务链中处于什么位置？",a="这一步接在你于 地精赞助商 二 中与码头管理员罗兹基尔交谈之后。下一步是 地精赞助商 四。",al={"地精赞助商 3 之前是什么","地精赞助商 任务链进度"}}},fp="18,151,16.244.0,18.141.1,32.80.0,49.94.0,36.100.0,38.115.0"}
P.entries["quest:1182"] = {n="地精赞助商",s="大财主里维加兹告诉你，荆棘谷北部纳菲瑞提湖一带的荆棘谷地精伐木机装有新型燃料调节器，普兹克能用得上。工头考兹尔比大财主预想的更精明，因此大财主里维加兹派你去寻找蓝图。",h="大财主里维加兹告诉你，荆棘谷北部纳菲瑞提湖一带的荆棘谷地精伐木机装有新型燃料调节器，普兹克能用得上。工头考兹尔比大财主预想的更精明，因此大财主里维加兹派你去寻找蓝图。",kw={"大财主里维加兹","蓝图","工头考兹尔","燃料调节器","地精赞助商","纳菲瑞提湖","沙漠赛道","普兹克","荆棘谷地精"},ang={["class:Rogue"]="潜行者可以撬开存放蓝图的箱子，无需工头的钥匙。"},sec={{t="工头的蓝图",b="大财主里维加兹解释说，荆棘谷北部纳菲瑞提湖一带的荆棘谷地精伐木机装有新型燃料调节器。只要掌握详细资料，普兹克就能加以利用，但那里的工头 考兹尔 比大财主里维加兹原先以为的更精明。你也许会有更好的运气。大财主里维加兹知道，蓝图就放在 考兹尔 的房子里，几乎可以肯定是锁着的。荆棘谷地精的基地就在山谷东北角的纳菲瑞提湖周围。钥匙在油塔顶部小屋里的工头考兹尔身上，装着蓝图的箱子则在塔底附近的小房子里。大财主里维加兹承认，那里的侏儒车队相当出色，还说己方车队需要争取一切能得到的优势。"},{t="给大财主的副本",b="拿到蓝图后，大财主里维加兹想留一份副本作记录，然后派你去找普兹克，免得普兹克以为有位赞助人抛弃了他。"}},faq={{q="大财主里维加兹为什么想要燃料调节器的蓝图？",a="纳菲瑞提湖一带的荆棘谷地精伐木机装有新型燃料调节器，大财主里维加兹认为，只要掌握详细资料，普兹克就能加以利用。",al={"为什么偷蓝图","为什么要燃料调节器","大财主里维加兹的动机"}},{q="蓝图放在哪里？",a="在荆棘谷北部纳菲瑞提湖的荆棘谷地精基地里，油塔脚下有一间小房子，蓝图就在屋内的箱子里。",al={"蓝图在哪里","燃料调节器的蓝图位置","考兹尔 的房子"}},{q="钥匙在谁手里？",a="工头考兹尔随身带着钥匙，他在油塔顶部的小屋里工作。",al={"考兹尔 的钥匙","钥匙在哪里","如何打开箱子"}},{q="这一步在任务链中处于什么位置？",a="这一步接在地精赞助商 (3) 之后，在那个任务中，码头管理员罗兹基尔派你去见大财主。下一步是地精赞助商 (5)。",al={"前置任务是什么","下一个任务是什么","地精赞助商 任务链"}}},fp="18,184,24.688.0,20.155.1,55.136.0,30.155.0,18.73.0,38.143.0"}
P.entries["quest:1183"] = {n="地精赞助商",s="大财主里维加兹已备好燃料调节器的蓝图，并将其送往闪光平原的普兹克那里。他向普兹克致意，还说普兹克若有任何需要，尽管开口。",h="大财主里维加兹已备好燃料调节器的蓝图，并将其送往闪光平原的普兹克那里。他向普兹克致意，还说普兹克若有任何需要，尽管开口。",kw={"大财主里维加兹","燃料调节器的蓝图","地精赞助商","沙漠赛道","普兹克","闪光平原","千针石林"},sec={{t="向普兹克致意",b="大财主里维加兹说，你已经准备就绪了。你带着蓝图前往闪光平原，交给那里的普兹克，同时转达大财主的问候和一句话：普兹克若有任何需要，尽管开口。里维加兹说，他会等着普兹克打破赛道纪录的消息。"},{t="改进设计",b="普兹克原本希望调节器已经组装好了。不过，他也看到了从头改进设计的机会。他打算绘制改良后的设计图，造出这个部件，并尽快将它安装好。"}},faq={{q="是谁派你送来蓝图的？",a="大财主里维加兹派你从藏宝海湾出发，向普兹克转达他的问候。",al={"地精赞助商 5由谁提供","任务给予者","里维加兹任务"}},{q="燃料调节器的蓝图要交给谁？",a="闪光平原的普兹克。",al={"蓝图送到哪里","设计图交给谁","普兹克位置"}},{q="大财主里维加兹希望听到什么消息？",a="他说，他会等着普兹克打破赛道纪录的消息。",al={"里维加兹的动机","大财主里维加兹赞助"}},{q="这次送货之前是什么任务？",a="前一个任务是地精赞助商（4），你在那个任务中为里维加兹取回了蓝图。下一步是第十八个驾驶员。",al={"前置任务","此前发生了什么","地精赞助商任务链"}}},fp="18,153,18.231.0,20.204.1,34.68.0,43.70.0,38.66.0,32.101.0"}
P.entries["quest:1184"] = {n="虫群的消息",s="科兰有话要带给奥格瑞玛的贝尔戈洛姆·石槌。你要回去告诉他，摩克塔在千针石林办事得力，科兰的研究也在推进。",h="科兰有话要带给奥格瑞玛的贝尔戈洛姆·石槌。你要回去告诉他，摩克塔在千针石林办事得力，科兰的研究也在推进。",kw={"贝尔戈洛姆·石槌","科兰","摩克塔","奥格瑞玛","虫群的样本","锈锤挖掘场","异种蝎","千针石林"},sec={{t="给奥格瑞玛的口信",b="从铁锈挖掘场的异种蝎身上取得破裂的甲壳后，科兰派你回到奥格瑞玛，去见贝尔戈洛姆·石槌。告诉贝尔戈洛姆，摩克塔在千针石林很好地执行着他的命令。还要告诉他，科兰的研究正在取得进展，希望很快能有更多发现。"},{t="贝尔戈洛姆的答复",b="贝尔戈洛姆·石槌感谢你的努力，并说大酋长听到你如此坚韧不拔，一定会很高兴。他承诺会提起你的名字，说萨尔经常与他交谈，也很重视他的意见。如果科兰有关于异种蝎的消息，贝尔戈洛姆希望能听到，因为他认为这些生物是个严重的威胁。"}},faq={{q="谁派你去奥格瑞玛？",a="一直在研究异种蝎的科兰，请你给奥格瑞玛的贝尔戈洛姆·石槌带个口信。",al={"任务给予者","谁给的任务","谁给予疯狂的虫群"}},{q="你要把口信带给谁？",a="奥格瑞玛的贝尔戈洛姆·石槌。",al={"找谁","送到哪里","贝尔戈洛姆·石槌的位置"}},{q="科兰想让你传达什么消息？",a="摩克塔在千针石林很好地执行着贝尔戈洛姆的命令，科兰的研究也在取得进展，很快就会有更多发现。",al={"口信内容","科兰的报告"}},{q="科兰研究的是什么生物？",a="是异种蝎。这项研究起初用到的破裂甲壳，来自千针石林锈锤挖掘场的异种蝎。",al={"是什么生物","为何研究虫群"}}},fp="18,83,18.275.0,15.280.1,27.90.0,47.31.0,40.146.0,42.125.0"}
P.entries["quest:1186"] = {n="第十八个驾驶员",s="普兹克将忙着把新的燃料调节器整合进赛车设计中，但他建议你去闪光平原找拉泽瑞克谈谈，继续帮助车队。拉泽瑞克是车队的第十八位驾驶员，喜欢对赛车进行改装。",h="普兹克将忙着把新的燃料调节器整合进赛车设计中，但他建议你去闪光平原找拉泽瑞克谈谈，继续帮助车队。拉泽瑞克是车队的第十八位驾驶员，喜欢对赛车进行改装。",kw={"地精","驾驶员","普兹克","赛道","拉泽瑞克","闪光平原","千针石林"},sec={{t="会见驾驶员",b="普兹克说，燃料调节器让他忙得不可开交，不过你可以去闪光平原找拉泽瑞克谈谈，继续帮车队的忙。拉泽瑞克是车队的驾驶员，确切地说是第十八位，喜欢按自己的想法给赛车做些小改装。普兹克还说，拉泽瑞克有点疯疯癫癫的，所以你最好尽量别显得太惊讶。"},{t="驾驶员的回忆",b="拉泽瑞克知道你一直在帮助普兹克。他说自己也曾像你一样，在维修区里四处奔忙，只要机械师肯让他插手，什么活他都帮着干。如今，他已是地精车队的王牌驾驶员。"}},faq={{q="拉泽瑞克是谁？",a="拉泽瑞克是一名地精，也是闪光平原上地精车队的驾驶员。普兹克说他是车队的第十八位驾驶员。",al={"第十八位驾驶员是谁","拉泽瑞克的故事","地精驾驶员"}},{q="普兹克为什么派你去找拉泽瑞克？",a="普兹克正忙着把新的燃料调节器整合进赛车设计中，便建议你去找拉泽瑞克谈谈，继续帮助车队。",al={"为什么找拉泽瑞克谈话","普兹克 第十八位驾驶员"}},{q="拉泽瑞克是个什么样的人？",a="普兹克说，拉泽瑞克喜欢按自己的想法给赛车做些小改装，而且有点疯疯癫癫的。",al={"拉泽瑞克的性格","拉泽瑞克疯了吗"}},{q="此前发生了什么？",a="这接续了地精赞助商 (5)，你在那个任务中将燃料调节器的蓝图交给了普兹克。",al={"第十八位驾驶员前置任务","拉泽瑞克之前的任务链"}}},fp="20,165,14.255.0,17.197.1,16.125.0,37.128.0,22.94.0,22.89.0"}
P.entries["quest:1187"] = {n="拉泽瑞克的调整",s="在闪光平原，拉泽瑞克会在普兹克完工后，按自己的想法进一步改装赛车。拉泽瑞克听说，运送那台从加基森的史瑞夫处订购的爆盐增压器的飞艇坠毁在了尘泥沼泽，他想让人把它找回来。",h="在闪光平原，拉泽瑞克会在普兹克完工后，按自己的想法进一步改装赛车。拉泽瑞克听说，运送那台从加基森的史瑞夫处订购的爆盐增压器的飞艇坠毁在了尘泥沼泽，他想让人把它找回来。",kw={"尘泥沼泽","加基森","吉兹莫瑞姆","普兹克","拉泽瑞克","爆盐增压器","闪光平原","史瑞夫","千针石林"},sec={{t="更强的动力",b="拉泽瑞克承认普兹克是个出色的机械师，但觉得他太过谨慎，不敢装上强劲火力，再抓紧赛车尽情飞驰。每当普兹克完成一辆赛车，拉泽瑞克就会花时间按自己的想法改装：调松操纵装置，拆掉部分车架，再不断增强动力。他从加基森机械工坊的史瑞夫那里订购了一台爆盐增压器，但据拉泽瑞克所说，运送它的飞艇坠毁在了尘泥沼泽。这台助推器得运回闪光平原，因为少了这股额外的冲劲就上赛道，简直太不像话了。"},{t="绑上赛车",b="拉泽瑞克对这台助推器赞不绝口：里面装着足足十五磅爆盐。把它绑在赛车侧面，应该就能让拉泽瑞克以惊人的速度跑完赛道，把侏儒们甩在身后两回。"}},faq={{q="拉泽瑞克是谁？",a="拉泽瑞克是闪光平原的一名赛车手，会在普兹克完工后，按自己的想法进一步改装赛车。",al={"拉泽瑞克","拉泽瑞克的调节由谁提供","拉泽瑞克 闪光平原"}},{q="助推器是从哪里来的？",a="拉泽瑞克从加基森机械大厅的史瑞夫那里订购了它。",al={"助推器从哪里来","谁制造了爆盐增压器","加基森 机械研究所"}},{q="爆盐增压器现在在哪里？",a="拉泽瑞克说，运送它的飞艇坠毁在了尘泥沼泽。",al={"爆盐增压器在哪里","助推器位置","坠毁飞艇位置"}},{q="拉泽瑞克为什么想要这台助推器？",a="拉泽瑞克想要比普兹克肯装上的更强的动力，还觉得少了这股额外的冲劲就上赛道，简直太不像话了。",al={"他为什么想要爆盐","为什么需要爆盐增压器"}},{q="这一步之前是什么？",a="之前是第十八个驾驶员。",al={"上一个任务","前置任务","拉泽瑞克的调节的前置任务"}}},fp="19,258,10.465.0,21.188.1,16.98.0,32.71.0,35.76.0,35.130.0,27.32.0"}
P.entries["quest:1188"] = {n="安全第一",s="拉泽瑞克发现，史瑞夫没有拆掉爆盐增压器上的保险装置。它限制了拉泽瑞克能从增压器中获得的动力，而拉泽瑞克早已要求将它拆除。你被派去塔纳利斯的加基森找史瑞夫。",h="拉泽瑞克发现，史瑞夫没有拆掉爆盐增压器上的保险装置。它限制了拉泽瑞克能从增压器中获得的动力，而拉泽瑞克早已要求将它拆除。你被派去塔纳利斯的加基森找史瑞夫。",kw={"加基森机械工坊","拉泽瑞克","安全第一","爆盐增压器","闪光平原","史瑞夫","塔纳利斯"},sec={{t="没人想要的保险装置",b="拉泽瑞克检查了爆盐增压器，发现保险装置还在。它限制了增压器能提供的动力，而拉泽瑞克早已告诉史瑞夫，应该把它拆掉。拉泽瑞克把增压器交给你，派你前往闪光平原以南的塔纳利斯沙漠，到加基森的机械工坊找史瑞夫拆除保险装置。"},{t="史瑞夫的答复",b="机械工坊声称能满足你所有的修理改装需求。你交出增压器时，史瑞夫否认自己在上面装过任何保险锁。按史瑞夫的说法，这台增压器几乎完全由爆盐炸药构成，而且已经改装过，使用时能释放更多装药的威力。史瑞夫说，拉泽瑞克非得把它一路调到十一档才肯罢休。"}},faq={{q="谁派你去加基森？",a="地精飞行员拉泽瑞克派你带着他的爆盐增压器前往加基森。",al={"任务给予者","谁提供安全第一","拉泽瑞克任务"}},{q="拉泽瑞克为什么对增压器不满？",a="史瑞夫没有拆掉保险装置。它限制了拉泽瑞克能从增压器中获得的动力，而拉泽瑞克早已要求将它拆除。",al={"拉泽瑞克为什么抱怨","增压器问题","增压器出了什么问题"}},{q="在哪里能找到史瑞夫？",a="史瑞夫在加基森的机械商店，位于闪光平原以南的塔纳利斯沙漠中。",al={"史瑞夫位置","史瑞夫在哪里","加基森器械店位置"}},{q="你要把什么物品带到加基森？",a="你带着拉泽瑞克的爆盐增压器，这是拉泽瑞克交给你，让你带给史瑞夫的。",al={"什么物品","增压器物品","带给史瑞夫什么"}},{q="这次送货之后还有什么？",a="这条任务线接下来还有第二部分，也叫安全第一。",al={"下一个任务","安全第一之后是什么","安全第一后续"}}},fp="12,149,22.298.0,15.256.1,27.78.0,41.99.0,26.93.0,40.78.0,31.61.0"}
P.entries["quest:1189"] = {n="安全第一",s="史瑞夫已按拉泽瑞克的要求改装了爆盐增压器，你带着改装后的推进器返回闪光平原，交给拉泽瑞克。史瑞夫还捎来一句警告：启动时务必小心，因为稍有差池，拉泽瑞克就会变成赛道上的一块焦痕。这是第一个安全第一的后续任务。",h="史瑞夫已按拉泽瑞克的要求改装了爆盐增压器，你带着改装后的推进器返回闪光平原，交给拉泽瑞克。史瑞夫还捎来一句警告：启动时务必小心，因为稍有差池，拉泽瑞克就会变成赛道上的一块焦痕。这是第一个安全第一的后续任务。",kw={"加基森","普兹克","拉泽瑞克","安全第一","爆盐增压器","闪光平原","史瑞夫","千针石林"},sec={{t="史瑞夫的警告",b="史瑞夫交出了按拉泽瑞克的要求改装好的推进器。史瑞夫还捎来一句警告：拉泽瑞克启动它时务必小心。稍有差池，他就没法在赛道上疾驰，只会变成赛道上的一块焦痕。史瑞夫又说，那就太可惜了，他还想知道第十九位车手的本事究竟如何。"},{t="座位下的沙子",b="闪光平原上，拉泽瑞克正在抱怨普兹克往赛车上倒了一桶沙子。拉泽瑞克问，座位底下堆着沙子，他还怎么跑出最高速度？"},{t="送回推进器",b="拉泽瑞克对改装后的推进器很满意。他真希望能看到启动它时那些侏儒脸上的表情，不过他估计自己到时候会忙着刷新赛道纪录，根本顾不上看。"}},faq={{q="谁让你把改装后的推进器送回闪光平原？",a="史瑞夫在加基森完成了爆盐增压器的改装，把它交给你，让你带回闪光平原，交给拉泽瑞克。",al={"谁提供安全第一第二步任务","史瑞夫任务提供者","谁改装推进器"}},{q="史瑞夫警告了什么？",a="史瑞夫说，拉泽瑞克启动推进器时应该小心。稍有差池，他就没法在赛道上疾驰，只会变成赛道上的一块焦痕。",al={"推进器有危险吗","史瑞夫的警告","推进器风险"}},{q="拉泽瑞克为什么对自己的赛车不满？",a="普兹克往赛车上倒了一桶沙子，拉泽瑞克问，座位底下堆着沙子，他还怎么跑出最高速度。",al={"拉泽瑞克为何生气","普兹克一桶沙子","拉泽瑞克的抱怨"}}},fp="12,187,21.315.0,19.154.0,20.169.1,49.156.0,28.147.0,40.127.0"}
P.entries["quest:119"] = {n="回复弗纳",s="铁匠阿古斯已经打好了五十副马掌，你要把它们从闪金镇送到湖畔镇的弗纳·奥斯古手中。赤脊山的坐骑疲于奔命，急需这些马掌。",h="铁匠阿古斯已经打好了五十副马掌，你要把它们从闪金镇送到湖畔镇的弗纳·奥斯古手中。赤脊山的坐骑疲于奔命，急需这些马掌。",kw={"一箱马掌","艾尔文森林","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","马掌的价格","弗纳·奥斯古"},ang={["faction:Alliance"]="身为联盟的一员，你通过艾尔文森林与赤脊山之间的补给线，帮助湖畔镇这样的边远定居点与王国腹地保持联系。",["profession:Blacksmithing"]="身为铁匠，你知道，当当地的锻造作坊因战事而不堪重负时，边境的坐骑仍需要源源不断的马掌供应。"},sec={{t="越过边界的信使",b="你带着箱子向东越过边界，进入赤脊山。在那里，物资短缺和豺狼人的袭击威胁着城镇。这五十副铁马掌能让马匹和役畜继续在崎岖的山路上劳作，帮助赤脊山应对这些危险。"},{t="箱上的字条",b="马掌送到时，弗纳·奥斯古松了一口气。随后，他发现了铁匠阿古斯附在箱子上的账单。弗纳很不高兴，闪金镇的铁匠竟然还要收钱。赤脊山四面受敌，实在没多少时间为这笔费用争执。"}},faq={{q="一箱马掌要送到哪里？",a="把箱子送给赤脊山湖畔镇的弗纳·奥斯古，他就在桥和湖边码头的东面。",al={"弗纳在哪","交任务地点","马掌交给谁"}},{q="是谁把这批货送回赤脊山的？",a="铁匠阿古斯在闪金镇的狮王之傲旅店外打铁，他打好马掌后便托人送出了箱子。",al={"谁给的任务","铁匠阿古斯","任务给予者"}},{q="为什么弗纳收到箱子后很不高兴？",a="铁匠阿古斯附了一张账单，要求支付全部五十副马掌的费用，这让弗纳很恼火。他显然原本指望对方免费帮个忙，或者在付款条件上宽容一些。",al={"弗纳为何生气","阿古斯的字条","弗纳的反应"}},{q="完成这次送货后会开启哪些任务？",a="送完这批货后，弗纳会交给你应对当地威胁的任务：在“豺狼人的乱吠”中猎杀赤脊山的豺狼人，以及取回“雏龙的鳞片”。",al={"下一个任务","后续任务","解锁什么"}},{q="为什么湖畔镇需要从闪金镇运入物资？",a="豺狼人和黑石兽人围攻湖畔镇，让当地工匠疲于应付。镇上经常需要从闪金镇这样较为安宁的地方运来日常用品，比如大批铁马掌。",al={"为何用艾尔文的马掌","为何运入马掌","赤脊山补给"}},{q="铁匠阿古斯会陪你一起返回赤脊山吗？",a="不会。铁匠阿古斯留在闪金镇的熔炉旁，由你把箱子送到赤脊山。",al={"阿古斯是否同行","护送铁匠阿古斯"}}},fx={a0846e84={q="铁匠阿古斯为什么要把这箱货送给弗纳？",a="铁匠阿古斯正在满足弗纳·奥斯古急需五十副马蹄铁的请求，但这并非全凭好心。他已将马蹄铁装箱，并附上一张措辞直白的账单，要求支付工钱和材料费。将送货的差事交给你，既能确保赤脊山得到补给，也能让弗纳明白，闪金镇的铁器可不是白送的。",al={"阿古斯 为什么要送马蹄铁","铁匠阿古斯的动机","阿古斯 为什么给 弗纳 马蹄铁"}},f67540ab={q="铁匠阿古斯为什么让你搬运马蹄铁，而不亲自送去？",a="阿古斯是闪金镇的常驻铁匠，必须守着铁砧和熔炉，为旅人及当地卫兵供应装备。扛着装有五十副铁马蹄铁的沉重木箱，翻越赤脊山的山口跨过边界，既会耽误他的工作，也会让这位独行工匠暴露在沿途豺狼人和强盗的威胁之下。而你是一位能干的冒险者，正好要往东去。",al={"阿古斯 为什么不亲自送马蹄铁","回复弗纳 为什么需要冒险者","为什么派玩家去湖畔镇"}}},fp="16,156,27.247.0,21.257.0,40.115.0,40.118.0,47.154.0,51.142.0,57.178.0,48.86.0"}
P.entries["quest:1190"] = {n="跟上节奏",s="普兹克确信，铜栓兄弟找到了一种新的制造材料。他们的赛车比以前跑得更快，但设计和试跑所得的其余数据都没有变化。瑞兹尔·铜栓几乎一直埋头研究与这项发现有关的图纸，而扎米克可以引开他的注意，让你趁机偷走图纸。这一步接在回复菲兹尔之后。",h="普兹克确信，铜栓兄弟找到了一种新的制造材料。他们的赛车比以前跑得更快，但设计和试跑所得的其余数据都没有变化。瑞兹尔·铜栓几乎一直埋头研究与这项发现有关的图纸，而扎米克可以引开他的注意，让你趁机偷走图纸。这一步接在回复菲兹...",kw={"铜栓","引开注意","普兹克","赛车","瑞兹尔·铜栓","设计图","闪光平原","千针石林","扎米克"},sec={{t="比数据所示更快",b="对于铜栓兄弟的赛车为何变得如此之快，普兹克只能想到一种解释：一种新的制造材料。他们的设计和试跑收集的一切数据看起来都和以前一样。目前可以确定的是，瑞兹尔·铜栓几乎一直埋头研究与这项发现有关的图纸。"},{t="扎米克的佯动",b="扎米克可以引开注意，你便趁机偷走瑞兹尔的图纸。闪光平原的普兹克想要这些图纸。"},{t="偷来的卷轴",b="这些图纸原来是一份卷轴，上面潦草地记着提炼某种原材料的笔记和设计。"}},faq={{q="普兹克为什么想要瑞兹尔的图纸？",a="铜栓兄弟的赛车跑得更快了，设计和数据却没有变化。普兹克由此断定，他们找到了一种新的制造材料，因此想要拿到瑞兹尔一直专心研究的图纸。",al={"普兹克的动机","为何偷取铜栓的图纸","跟上节奏的原因"}},{q="谁帮忙引开瑞兹尔·铜栓的注意？",a="扎米克可以引开注意，让你有机会偷走瑞兹尔的图纸。",al={"谁引开注意","扎米克的作用","如何引开瑞兹尔的注意"}},{q="偷来的图纸要交给谁？",a="交给普兹克，他在千针石林的闪光平原。",al={"跟上节奏在哪里","跟上节奏的位置"}},{q="这一步之前是什么？",a="这一步接在回复菲兹尔之后。",al={"跟上节奏的前置任务","跟上节奏之前是什么任务"}},{q="拿到图纸之后是什么？",a="任务线接下来是瑞兹尔的图表。",al={"下一个任务是什么","跟上节奏之后"}}},fp="12,270,27.259.0,22.103.0,17.105.1,36.193.0,37.76.0,29.74.0,28.47.0,38.45.0"}
P.entries["quest:1191"] = {n="扎米克的困扰",s="在千针石林，扎米克的 困扰 可以在你进行跟上节奏时引开瑞兹尔。不完成这个任务，就无法完成跟上节奏。",h="在千针石林，扎米克的 困扰 可以在你进行跟上节奏时引开瑞兹尔。不完成这个任务，就无法完成跟上节奏。",kw={"引开","跟上节奏","千针石林","扎米克"},sec={{t="及时引开",b="在你进行跟上节奏时，扎米克会把瑞兹尔从他的小屋里引开。精铁 设计图则留在屋内。"}},faq={{q="扎米克的干扰由谁提供？",a="千针石林的扎米克提供这个任务。",al={"谁提供扎米克的 困扰","扎米克任务提供者","扎米克的 困扰 在哪接"}},{q="这与跟上节奏有什么关系？",a="这个任务会在你进行跟上节奏的过程中出现，不完成它，就无法完成那一步。",al={"跟上节奏 是否需要此任务","跟上节奏 扎米克","与 跟上节奏 的关系"}},{q="引开他有什么作用？",a="瑞兹尔会离开他的小屋，他的设计图则留在屋内。",al={"扎米克引开后会发生什么","瑞兹尔 离开小屋"}},{q="联盟和部落的冒险者都能与扎米克合作吗？",a="是的。扎米克保持中立，与双方阵营都合作。",al={"扎米克是否中立","联盟或部落 扎米克","谁能做扎米克的 困扰"}}},fp="19,141,18.103.0,30.35.0,37.97.0,27.53.0,56.52.0"}
P.entries["quest:1192"] = {n="精铁矿石",s="普兹克打算将精铁用于赛车的多个部件，这需要大量未经加工的矿石。矿石可以在海对岸卡兹莫丹的荒芜之地，奥达曼挖掘场找到。侏儒们已经在收集自己的矿石，普兹克也想跟上他们的进度。",h="普兹克打算将精铁用于赛车的多个部件，这需要大量未经加工的矿石。矿石可以在海对岸卡兹莫丹的荒芜之地，奥达曼挖掘场找到。侏儒们已经在收集自己的矿石，普兹克也想跟上他们的进度。",kw={"荒芜之地","精铁","精铁矿石","普兹克","赛车","千针石林","奥达曼"},sec={{t="奥达曼的矿石",b="普兹克需要四块未经加工的精铁矿石。矿石可以在海对岸卡兹莫丹的荒芜之地，奥达曼挖掘场找到。侏儒们已经在收集自己的矿石，所以普兹克也想备上一批。这项任务接在瑞兹尔的图表之后。"}},faq={{q="普兹克为什么需要精铁矿石？",a="他想将精铁用于赛车的多个部件，这需要大量未经加工的矿石。",al={"精铁的用途","为什么需要精铁矿石","普兹克精铁用途"}},{q="哪里能找到精铁矿石？",a="在海对岸卡兹莫丹的荒芜之地，奥达曼挖掘场。",al={"哪里能找到精铁矿石","精铁位置","哪里能获取精铁矿石"}},{q="为什么获取矿石很重要？",a="侏儒们已经在收集自己的精铁矿石，普兹克想跟上他们的进度。",al={"为什么急需精铁","侏儒竞争对手精铁"}},{q="这之前是什么任务？",a="前一个任务是瑞兹尔的图表，而它的前一个任务是跟上节奏。",al={"精铁矿石前置任务","精铁任务链前一个任务"}}},fp="12,221,16.255.0,34.78.0,32.89.0,34.83.0,22.89.0"}
P.entries["quest:1194"] = {n="瑞兹尔的图表",s="瑞兹尔无人看管的图纸记述了精铁矿石的提炼方法。潦草的字迹指出，矿石来自荒芜之地奥达曼的矮人挖掘场，其他许多笔记则与耐热性有关。一块未经提炼的矿石压在图纸上，充当镇纸，你将这块样本带给了闪光平原的普兹克。这是跟上节奏的后续。",h="瑞兹尔无人看管的图纸记述了精铁矿石的提炼方法。潦草的字迹指出，矿石来自荒芜之地奥达曼的矮人挖掘场，其他许多笔记则与耐热性有关。一块未经提炼的矿石压在图纸上，充当镇纸，你将这块样本带给了闪光平原的普兹克。这是跟上节奏的后续...",kw={"荒芜之地","精铁","普兹克","瑞兹尔","设计图","闪光平原","奥达曼"},sec={{t="精铁笔记",b="瑞兹尔的设计图记述了精铁矿石的提炼方法。瑞兹尔潦草的字迹指出，矿石来自荒芜之地奥达曼的矮人挖掘场。其他许多笔记都在谈它的耐热程度。一块未经提炼的精铁矿石压在图纸上，充当镇纸，而你带给普兹克的正是这块样本。"},{t="普兹克的判断",b="普兹克对精铁很感兴趣。如果它的耐热程度真如你所说，那就能解释侏儒近来为何进步如此之大。这块样本对试验来说无比珍贵，不过普兹克还需要更多矿石，才能真正派上用场。"}},faq={{q="瑞兹尔的精铁矿石从哪里来？",a="瑞兹尔潦草的字迹指向了荒芜之地奥达曼的矮人挖掘场。",al={"精铁来自哪里","精铁矿石来源","瑞兹尔的精铁位置"}},{q="瑞兹尔的笔记里写了精铁的哪些特性？",a="瑞兹尔的笔记记述了矿石的提炼方法，其他许多笔记则与它的耐热性有关。",al={"精铁有什么用","为什么用精铁","精铁特性"}},{q="精铁样本交给了谁？",a="你将样本带给了闪光平原的普兹克。",al={"交给谁","谁要精铁样本","普兹克交任务"}},{q="这块样本是从哪里来的？",a="一块未经提炼的精铁矿石原本压在瑞兹尔的图纸上，充当镇纸。",al={"样本在哪里找到","瑞兹尔的镇纸"}}},fp="19,244,17.261.0,16.229.1,39.104.0,42.95.0,33.55.0,32.69.0"}
P.entries["quest:1195"] = {n="神圣之火",s="赞金·石蹄派部落去寻找一团神圣之火和一件古老圣物。为了帮助千针石林的劳恩·峭壁行者，你前往灰谷，寻找一瓶月亮井水。",h="赞金·石蹄派部落去寻找一团神圣之火和一件古老圣物。为了帮助千针石林的劳恩·峭壁行者，你前往灰谷，寻找一瓶月亮井水。",kw={"灰谷","蚀刻瓶","弗伦河","加拉克半人马","欢笑姐妹","月亮井","劳恩·峭壁行者","林中树居","神圣之火","千针石林","赞金·石蹄"},ang={["class:Druid"]="牛头人德鲁伊面临着令人不安的抉择：杀死自然之女树妖，收集圣水，用来扑灭半人马的神圣火焰。",["faction:Horde"]="林中树居周围的冲突可能加剧灰谷暗夜精灵的紧张局势。千针石林的半人马圣物能巩固部落的南部边疆。",["race:Tauren"]="半人马的敌意已经困扰了牛头人世世代代。一件来自半人马种族诞生之初的圣物，能让莫高雷的部族深入了解敌人，并获得对付他们的筹码。"},sec={{t="半人马的圣物与精灵的井水",b="加拉克半人马在千针石林守护着一件古老的圣物。这件圣物可追溯到他们种族诞生之时，他们用神圣的火焰保护着它。赞金·石蹄需要蕴含月神神力的水来熄灭这些火焰。他派你北上灰谷，那片古老的森林中有他所需的月亮井水。"},{t="擅闯灰谷",b="纯净的月亮井水需要用不会污染它的容器盛装。你要从林中树居附近的树妖欢笑姐妹身上取得一个蚀刻瓶。然后，你将瓶子浸入弗伦河西岸一带的月亮井中，再把它带回莫高雷。"}},faq={{q="赞金·石蹄为什么需要月亮井水？",a="赞金需要月亮井水来帮助他在千针石林的同伴劳恩·峭壁行者。劳恩打算用井水强大的魔力熄灭敌对的加拉克半人马守护的神圣之火，让部落得以取回一件古老圣物。",al={"为什么需要月亮井水","月亮井水的用途","为什么去灰谷取水"}},{q="在哪里可以找到蚀刻瓶？",a="蚀刻瓶由欢笑姐妹携带，这些树妖游荡在灰谷中部林中树居周围的树林里，就在从碎木岗哨向西延伸的北侧道路旁。",al={"蚀刻瓶在哪里","如何获得蚀刻瓶","蚀刻瓶位置"}},{q="应该用哪一口月亮井的水灌满瓶子？",a="这口月亮井位于弗伦河西岸附近，在横贯灰谷中部的大路以南。",al={"哪口月亮井","月亮井位置","在哪里灌满瓶子"}},{q="加拉克半人马是谁？",a="加拉克是一个好战的半人马氏族，生活在千针石林尘土飞扬的旷野中。他们守护着一件来自种族诞生之初的古老圣物，圣物周围环绕着神圣的篝火，赞金和劳恩打算将其浇灭。",al={"加拉克部族","加拉克半人马","加拉克是谁"}},{q="赞金之后，谁会接收装满井水的瓶子？",a="赞金在雷霆崖检查装满井水的瓶子后，会派你南下千针石林，将它交给提出这一请求的劳恩·峭壁行者。",al={"劳恩是谁","井水接下来送往哪里","赞金之后的下一步"}},{q="为什么要杀死树妖来获取她们的瓶子？",a="树妖的容器经过特殊制作，可以盛装纯净的魔法液体而不使其受到污染。普通瓶子无法安全盛装蕴含暗夜精灵月亮井天体能量的井水。",al={"为什么攻击树妖","为什么找欢笑姐妹","树妖的容器"}}},fp="16,153,31.304.0,24.259.0,46.235.0,36.185.0,48.111.0,26.206.0,43.155.0,33.177.0"}
P.entries["quest:1196"] = {n="神圣之火",s="一瓶月亮井水从灰谷一路南下，送往乱风岗。劳恩·峭壁行者需要用它来熄灭千针石林中守护一件古老半人马圣物的永恒烈焰。",h="一瓶月亮井水从灰谷一路南下，送往乱风岗。劳恩·峭壁行者需要用它来熄灭千针石林中守护一件古老半人马圣物的永恒烈焰。",kw={"半人马圣物","蚀刻瓶","乱风岗","升降梯","劳恩·峭壁行者","神圣之火","千针石林","赞金·石蹄"},ang={["class:Druid"]="劳恩·峭壁行者凭借对塞纳里奥血脉的深厚了解，洞悉树妖与半人马之间的魔法共鸣。",["faction:Horde"]="送达这瓶井水，便能增强乱风岗的力量。这座部落哨站高踞于千针石林险峻的山道之间。",["race:Tauren"]="对半人马的每一次打击，都有助于保护莫高雷，以及你家园刚刚稳固的边疆。"},sec={{t="漫漫南行路",b="赞金·石蹄让你带着盛有净化月亮井水的蚀刻瓶，穿过卡利姆多中部，一路向南。你穿越烈日炙烤的贫瘠之地，乘着高耸的升降梯下行，前往乱风岗。劳恩·峭壁行者在峡谷上方的高耸台地上等候，监视着下方的半人马氏族。"},{t="共同的血脉与古老结界",b="劳恩·峭壁行者解释了月亮井水为何对他对抗半人马如此重要。树妖与半人马的血脉都源自塞纳留斯，半人马便是其子扎尔塔的后代。这种血缘联系赋予了神圣的月亮井水一种奥术共鸣，唯有这股力量能穿透永恒烈焰，触及那件受到严密守护的半人马神器。"}},faq={{q="劳恩·峭壁行者在哪里？",a="劳恩·峭壁行者住在千针石林的乱风岗顶端。向南穿过贫瘠之地，乘升降梯下到谷底，再沿东南方的小路前行，前往陡峭石柱高处的升降机。",al={"劳恩在哪里","劳恩·峭壁行者位置","寻找劳恩·峭壁行者","乱风岗交任务"}},{q="劳恩为什么需要月亮井水来对抗半人马？",a="半人马与树妖的血脉都源自塞纳留斯。这种血缘联系让暗夜精灵的月亮井水产生魔法共鸣，足以熄灭保护半人马圣物的永恒烈焰。",al={"为何需要月亮井水","月亮井与半人马的联系","树妖与半人马的关系"}},{q="是谁派我带着瓶子来的？",a="你从灰谷那座有人守卫的月亮井中取水后，赞金·石蹄便派你带着装满水的蚀刻瓶前来。",al={"谁给的任务","赞金·石蹄","神圣之火第二部分任务给予者"}},{q="把瓶子交给劳恩之后会怎样？",a="劳恩确认井水完好无损后，会让你用瓶中的水熄灭火焰，从附近的峡谷中取回半人马圣物。",al={"下一个任务","劳恩之后的任务","神圣之火第三部分"}},{q="如何下到千针石林？",a="沿贫瘠之地向南的主路走到悬崖边。升降梯就在那里：两座由牛头人滑轮装置驱动的木制升降机，将旅人送往谷底。",al={"如何前往千针石林","如何通过贫瘠之地悬崖","升降梯路线"}},{q="牛头人为什么要寻找半人马圣物？",a="世世代代以来，牛头人与半人马在卡利姆多各地展开了残酷的战争。牛头人破坏半人马的仪式，夺取神圣的器物，以削弱盘踞在千针石林峡谷各处的好战氏族。",al={"牛头人与半人马的战争","为何夺取半人马圣物"}}},fp="16,179,20.304.0,30.327.1,33.221.0,51.181.0,27.119.0,43.145.1,40.196.0,43.215.0"}
P.entries["quest:1197"] = {n="神圣之火",s="在裂蹄堡，劳恩·峭壁行者想要熄灭加拉克半人马的圣火。你带着受过祝福的水，进入他们的据点，熄灭火盆中的火焰，取走裂开的蹄子。",h="在裂蹄堡，劳恩·峭壁行者想要熄灭加拉克半人马的圣火。你带着受过祝福的水，进入他们的据点，熄灭火盆中的火焰，取走裂开的蹄子。",kw={"半人马","裂开的蹄子","乱风岗","加拉克","劳恩·峭壁行者","圣火","裂蹄峭壁","裂蹄堡","千针石林"},ang={["class:Shaman"]="身为萨满祭司，你能感知到裂开的蹄子散发出的奇异能量。这些能量表明，半人马除了野蛮的蛮力，还借助着神秘力量。",["race:Tauren"]="身为牛头人，攻入半人马巢穴、夺走他们的神圣象征，是对世代劫掠的回击。这件圣物对乱风岗的学者而言，也是珍贵的战利品。"},sec={{t="直捣火塘",b="乱风岗以北的裂蹄峭壁，是加拉克半人马在千针石林领地的核心。在名为裂蹄堡的洞穴深处，燃烧着半人马奉为神圣的火焰。劳恩·峭壁行者为盟友准备了一瓶装着净化之水的蚀刻瓶。你进入堡内，用水暂时熄灭火焰，取走守卫看护的圣物——裂开的蹄子。"},{t="蹄子的秘密",b="劳恩·峭壁行者看到裂开的蹄子时，其中奇异的力量触动了他的灵觉。牛头人学者长期以来一直在卡利姆多各地与四处劫掠的半人马部族抗争。这件圣物暗示，半人马的狂热与部族团结背后，还有更深层、尚不为人所知的力量在支撑。"}},faq={{q="圣火位于何处？",a="圣火燃烧在裂蹄堡深处，这座洞穴位于千针石林乱风岗以北、裂蹄峭壁的半人马营地中。",al={"裂蹄堡位置","圣火在哪里","千针石林火焰洞穴"}},{q="是谁让你熄灭圣火？",a="驻守在乱风岗高处的长者劳恩·峭壁行者，在调查加拉克半人马之后，请你熄灭圣火。",al={"圣火任务给予者","劳恩·峭壁行者位置","谁给予任务"}},{q="如何熄灭圣火？",a="使用劳恩·峭壁行者提供的装满水的蚀刻瓶。瓶中装着此前在任务链中收集的水，能暂时熄灭火盆中的火焰。",al={"如何获得裂开的蹄子","熄灭火焰的物品","熄灭圣火"}},{q="裂开的蹄子是什么？",a="裂开的蹄子是加拉克半人马供奉在火焰中的部族圣物。劳恩·峭壁行者感知到其中异乎寻常的魔法能量，希望借此了解半人马的文化与力量。",al={"裂开的蹄子背景故事","半人马圣物","偷走了什么"}},{q="牛头人为什么想要这件圣物？",a="世世代代以来，半人马部族不断将牛头人赶出祖传的猎场。夺走神圣的传承之物，可以扰乱加拉克的行动，同时牛头人也在设法了解敌人凶残天性背后的奥术或灵魂力量。",al={"为什么偷走裂开的蹄子","牛头人与半人马的战争"}},{q="哪个半人马氏族守卫着裂蹄堡？",a="加拉克部族控制着裂蹄峭壁及其洞穴据点。他们是千针石林峡谷谷底最主要的半人马氏族。",al={"千针石林半人马部族","加拉克半人马"}}},fp="16,177,19.370.0,19.272.1,34.133.0,32.129.0,29.132.0,24.191.0,34.237.0,41.133.0"}
P.entries["quest:1198"] = {n="寻找塞尔瑞德",s="哨兵山德拉斯派你前往黑暗深渊，寻找在那里失踪的斥候。银色黎明担心，纳迦与暮光之锤教徒已在被水淹没的废墟中联手。",h="哨兵山德拉斯派你前往黑暗深渊，寻找在那里失踪的斥候。银色黎明担心，纳迦与暮光之锤教徒已在被水淹没的废墟中联手。",kw={"银色黎明","灰谷","黑暗深渊","达纳苏斯","纳迦","山德拉斯","塞尔瑞德","暮光之锤"},ang={["class:Paladin"]="作为一名与银色黎明并肩作战的圣骑士，你明白塞尔瑞德的孤独守望是一份庄严的职责，旨在守护世界，抵御暗影与腐化。",["faction:Alliance"]="作为联盟冒险者，你可以开始与银色黎明并肩效力，赢得他们的好感。",["race:NightElf"]="作为暗夜精灵，你知道黑暗深渊中古老的Temple of Elune已遭玷污。帮助银色黎明，意味着夺回暗夜精灵的神圣遗产。"},sec={{t="达纳苏斯的耳目",b="银色黎明既监视着洛丹伦的天灾军团，也留意卡利姆多各地的威胁。哨兵山德拉斯在达纳苏斯收集有关异常威胁的报告。他得到消息，纳迦与暮光之锤的末日狂热者已在黑暗深渊缔结盟约，那是灰谷海岸边被水淹没的废墟。银色黎明担心这场结盟会带来灾祸。"},{t="失踪的斥候",b="银月守卫塞尔瑞德进入洞穴，调查沿海流传的传闻。数周过去，他依然音信全无，而山德拉斯麾下的其他斥候都在别处执行任务。他担心塞尔瑞德已被海面下的黑暗势力杀害或俘虏。如今，他请你进入黑暗深渊，将失踪的斥候活着带回来。"}},faq={{q="银色黎明为何关注黑暗深渊？",a="银色黎明监视着艾泽拉斯各地的威胁，关注的危险并不限于东部王国的亡灵。卡利姆多的纳迦与暮光之锤教徒联手，令银色黎明必须予以关注。",al={"银色黎明为何在此","银色黎明 黑暗深渊","银色黎明 纳迦"}},{q="哨兵山德拉斯是谁？",a="哨兵山德拉斯是银色黎明驻暗夜精灵首都达纳苏斯的一名特工。他收集情报，查明何处需要银色黎明的援助，并派遣调查人员评估各地的危机。",al={"山德拉斯是谁","任务发布者山德拉斯","哨兵山德拉斯的职责"}},{q="银月守卫塞尔瑞德是谁？",a="银月守卫塞尔瑞德是奉命调查黑暗深渊的银色黎明特工。他的任务是查明被水淹没的洞穴中，纳迦与教徒的实力和意图。",al={"塞尔瑞德是谁","塞尔瑞德的故事","失踪的斥候塞尔瑞德"}},{q="在哪里能找到塞尔瑞德？",a="银月守卫塞尔瑞德身处灰谷佐拉姆海岸的黑暗深渊深处。他已潜入洞穴，独自在那里等待援军。",al={"塞尔瑞德的位置","塞尔瑞德在哪里","寻找塞尔瑞德 黑暗深渊"}},{q="找到塞尔瑞德之后会发生什么？",a="找到塞尔瑞德后，他会揭示废墟中仪式的真相，并在黑暗深渊中的邪恶任务中指引你去寻找教派的首领。",al={"后续任务","塞尔瑞德的后续任务","塞尔瑞德之后的任务"}},{q="部落玩家能接受这项任务吗？",a="哨兵山德拉斯在达纳苏斯发布这项任务，招募的对象是联盟冒险者。部落冒险者只要能抵达他身边，也可以接受任务。",al={"部落 寻找塞尔瑞德","部落能否接此任务","部落 塞尔瑞德"}}},fp="21,178,17.390.0,17.332.0,55.207.0,29.200.0,29.178.0,28.165.0,36.143.1,36.148.0"}
P.entries["quest:1199"] = {n="暮光之锤的末日",s="在黑暗深渊，暮光之锤的邪教徒与娜迦在灰谷海岸下方联手。达纳苏斯的银月守卫玛纳杜斯号召联盟勇士从被击杀的邪教徒身上收集坠饰，阻挠他们唤醒远古邪恶的计划。",h="在黑暗深渊，暮光之锤的邪教徒与娜迦在灰谷海岸下方联手。达纳苏斯的银月守卫玛纳杜斯号召联盟勇士从被击杀的邪教徒身上收集坠饰，阻挠他们唤醒远古邪恶的计划。",kw={"银色黎明","银月守卫玛纳杜斯","灰谷","黑暗深渊","达纳苏斯","玛纳杜斯","娜迦","上古之神","暮光之锤的末日","暮光坠饰","暮光之锤"},ang={["class:Paladin"]="作为一名与银色黎明这类组织并肩作战的圣骑士，你认为暮光之锤对上古之神的崇拜是令人憎恶的行径，必须以正义之力加以净化。",["class:Priest"]="作为一名牧师，你能感受到神殿中那口曾经神圣的月亮井已遭腐化，也能感受到那些令人发狂的暗影低语，正驱使邪教徒陷入更深的疯狂。",["faction:Alliance"]="对联盟而言，暮光之锤的威胁就在黑海岸以南不远处，肃清黑暗深渊有助于保障卡利姆多北部的安全。",["race:NightElf"]="对暗夜精灵而言，上古之神的邪教徒与娜迦亵渎神圣的神殿和月亮井，是对Elune和灰谷祖地的冒犯。"},sec={{t="遭亵渎的圣所",b="在灰谷的佐拉姆海岸下方，黑暗深渊已沦为废墟。这座暗夜精灵神殿曾是供奉艾露恩的圣地，拥有一口力量强大的月亮井，直到天崩地裂将其摧毁，使之沉入海底。如今，娜迦和邪教徒占据了神殿的厅堂。井水已被污染，邪教徒崇拜着比深海更黑暗的力量。"},{t="上古之神的低语",b="暮光之锤崇拜混乱的上古之神，企图让它们归来，希望将疯狂与毁灭散播到整个世界。达纳苏斯收到的报告称，邪教徒已与黑暗深渊的娜迦联手。在淹没的厅堂中，他们举行仪式，利用神殿中被污染的水，助长黑暗主人复苏的力量。"},{t="银色黎明的守望",b="银月守卫玛纳杜斯代表银色黎明，在达纳苏斯监视着威胁艾泽拉斯的势力。他看到了黑暗深渊的危险：其中的恐怖可能波及每一个文明种族。银色黎明为深入这座被水淹没的迷宫、铲除邪教徒，并从他们颈上取回暮光坠饰作为击败证明的英雄提供援助与嘉许。"}},faq={{q="银月守卫玛纳杜斯是谁？",a="银月守卫玛纳杜斯是驻守达纳苏斯的银色黎明使者。他监视着威胁卡利姆多的邪教与黑暗势力，并招募冒险者将其消灭。",al={"玛纳杜斯","暮光之锤的末日任务由谁发布","银月守卫玛纳杜斯位置"}},{q="银色黎明为何关注黑暗深渊？",a="银色黎明在洛丹伦对抗天灾军团，但其章程也涵盖了威胁世界的非自然邪恶。卡利姆多的上古之神崇拜，以及邪教徒与娜迦的结盟，若不加以遏制，可能酿成灾难。",al={"银色黎明为何在达纳苏斯","银色黎明 黑暗深渊"}},{q="暮光之锤是什么？",a="暮光之锤是一个末日邪教，效忠于混乱的上古之神，这些原始存在很久以前就被囚禁在大地之下。它的追随者追求末日降临，让他们的主人得以崛起，在恐惧与疯狂中重塑世界。",al={"暮光之锤邪教","暮光之锤是谁","暮光之锤"}},{q="暮光坠饰有什么用途？",a="暮光坠饰是暮光之锤成员佩戴的黑暗护符，用来表明他们对所崇拜存在的效忠。银色黎明收集这些坠饰，作为邪教徒已被击杀、威胁已被消除的证明。",al={"暮光坠饰背景","暮光坠饰是什么"}},{q="黑暗深渊原本是什么地方？",a="黑暗深渊原本是一座供奉艾露恩的暗夜精灵神殿，以其力量强大的月亮井闻名。大灾变撕裂了大地，使神殿的厅堂沉入海底。",al={"黑暗深渊历史","黑暗深渊神殿历史","黑暗深渊月亮井"}},{q="暮光之锤为何与娜迦合作？",a="双方联手的原因尚不完全清楚。两方都受到沉没的神庙中涌动的黑暗力量吸引。邪教徒得以安全进入沉没的古老密室，而娜迦则从他们的邪术和献祭仪式中获益。",al={"娜迦与邪教徒结盟","黑暗深渊娜迦结盟"}}},fp="14,248,17.322.0,24.342.0,28.355.0,28.170.0,57.231.0,30.242.0,41.210.0,38.170.0,52.245.0"}
P.entries["quest:12"] = {n="人民军",s="在哨兵岭，格里安·斯托曼让人民军迎战西部荒野北部田野和矿洞中的匪徒，以此考验他们。本地志愿者保卫这片土地，抵御迪菲亚潜行者，而暴风城王室却无暇顾及此地，军队也不见踪影。",h="在哨兵岭，格里安·斯托曼让人民军迎战西部荒野北部田野和矿洞中的匪徒，以此考验他们。本地志愿者保卫这片土地，抵御迪菲亚潜行者，而暴风城王室却无暇顾及此地，军队也不见踪影。",kw={"迪菲亚走私者","迪菲亚捕兽者","法布隆","格里安·斯托曼","詹戈洛德","摩尔森农场","人民军","哨兵岭","西部荒野"},ang={["class:Paladin"]="身为圣骑士，你保护无力自卫的人，审判那些欺凌弱者的匪徒。",["faction:Alliance"]="身为联盟冒险者，你看到了王国内部的裂痕：暴风城的贵族安居在都城高墙之内，而普通定居者却在奋力保卫西部荒野，阻止它走向毁灭。",["race:Human"]="身为王国的人类子民，你看到劳作度日的家庭和世代务农的人们饱受匪徒侵袭，王国当权者却视而不见。"},sec={{t="和平的代价",b="格里安·斯托曼建立了人民军，但他并非来者不拒。想要获得这支队伍的徽章，就必须证明自己能够战斗，能够保护无辜的定居者。他号召众人果断行动，从横行各地的匪徒、流浪者和盗贼手中夺回西部荒野。"},{t="肃清粮仓",b="格里安·斯托曼在放心让新兵执行更深入的行动之前，会先派他们迎战北部农庄附近的迪菲亚势力。迪菲亚捕兽者和走私者在詹戈洛德矿洞、摩尔森农场和法布隆南瓜农场附近公然活动。他们劫掠物资，伏击旅人。赶走他们能够打乱他们搜掠补给的行动，也能让斯托曼的斥候看到，你有毅力与这些罪犯长期周旋。"}},faq={{q="人民军是什么？",a="人民军是格里安·斯托曼在哨兵岭组织的一支志愿军。本地农夫、老兵和平民加入其中，保卫西部荒野，抵御迪菲亚潜行者，而暴风城的皇家军队却拒绝或未能在此驻防。",al={"人民军","民兵是谁","人民军 是什么"}},{q="暴风城为什么不派遣皇家军队？",a="瓦里安·乌瑞恩国王失踪后，暴风城的贵族机构贵族和议会领袖将王国的资源投入了其他地方。西部荒野这样的偏远乡野只能自谋生路，抵御日益猖獗的匪帮。",al={"军队在哪里","西部荒野为什么没有卫兵","暴风城驻军"}},{q="在哪里能找到迪菲亚捕兽者和走私者？",a="迪菲亚捕兽者和走私者遍布西部荒野北部，尤其常见于法布隆南瓜农场、摩尔森农场和詹戈洛德矿洞入口一带。",al={"捕猎者位置","走私者位置","捕猎者在哪里"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位身经百战的老兵，在哨兵岭指挥人民军。他召集志愿者，保护西部荒野的定居者，驱逐迪菲亚潜行者，恢复乡野的秩序。",al={"斯托曼 是谁","格里安·斯托曼的故事","民兵领袖"}},{q="这个任务之后还有更多民兵任务吗？",a="有。通过这场初步考验的志愿者将承担更多职责，在西部荒野的平原上迎战迪菲亚潜行者中越来越危险的成员。",al={"这是系列任务吗","下一个任务","民兵任务进程"}},{q="法布隆南瓜农场发生了什么？",a="迪菲亚潜行者将法布隆一家赶出了家园，占据了他们的农田。如今，匪徒和拾荒者劫掠田地，在北部道路上肆意恐吓行人。",al={"法布隆 农场","法布隆 一家怎么了","南瓜农场"}}},fx={b0313ac5={q="格里安·斯托曼为什么要做这件事？",a="格里安·斯托曼领导人民军，只有一个目标：保卫西部荒野，从横行农田的犯罪团伙手中夺回安宁。成群的迪菲亚匪徒正在劫掠摩尔森和法布隆等农场。格里安希望通过清除他们的捕兽者和走私者，遏制他们的侵占，同时考验你是否有决心为西部荒野的人民而战。",al={"为何杀捕兽者和走私者","格里安·斯托曼的动机","人民军任务目的"}},["1cf2b131"]={q="迪菲亚捕兽者和走私者是什么人？",a="他们是迪菲亚潜行者早期的基层成员，这个由盗贼和匪徒组成的团伙心狠手辣，已经将农民赶出了自己的土地。这些捕兽者和走私者潜伏在摩尔森农场、詹戈洛德矿洞等被占据的产业附近，巩固地盘，囤积非法货物，帮助兄弟会牢牢控制乡间。",al={"迪菲亚捕兽者","迪菲亚走私者","迪菲亚匪徒是谁"}},b416da40={q="格里安·斯托曼为什么需要你对抗迪菲亚？",a="人民军是一支志愿军，兵力已被逼到极限，暴风城的皇家军队也完全抛弃了他们。格里安若派仅存的少数守卫进行危险的遭遇战，就会削弱哨兵岭的防守。他只能依靠有能力的志愿者和雇佣兵，要求你先证明自己的实力与决心，再正式接纳你加入民兵的队伍。",al={"民兵为何不对付他们","格里安为何选我","为何招募外人"}}},fp="20,253,18.276.0,24.404.0,29.267.0,43.238.0,47.152.0,25.216.0,49.167.0,45.179.0"}
P.entries["quest:120"] = {n="送往暴风城的信",s="在湖畔镇，所罗门镇长向暴风城发出了紧急求援。豺狼人和黑石兽人步步紧逼，他却抽不出驻军前去送信。他将《湖畔镇的现状》托付给一名旅人，送交暴风城的马库斯·乔纳森将军。",h="在湖畔镇，所罗门镇长向暴风城发出了紧急求援。豺狼人和黑石兽人步步紧逼，他却抽不出驻军前去送信。他将《湖畔镇的现状》托付给一名旅人，送交暴风城的马库斯·乔纳森将军。",kw={"马库斯·乔纳森将军","湖畔镇","所罗门镇长","送往暴风城的信使","赤脊山","援军","暴风城军队","湖畔镇的现状"},ang={["class:Paladin"]="身为圣骑士，你将绝望者的求援带给那些受宫廷政治牵制的领袖，考验着你履行职责、守护他人和践行正义的决心。",["faction:Alliance"]="对联盟而言，湖畔镇的求援揭示了繁荣的王都与王国边缘挣扎求生的边境聚落之间的紧张关系。",["race:Human"]="身为人类，你知道赤脊山世代都是暴风城的领土。看到同胞因官僚繁文缛节而遭到遗弃，你的爱国之心难免受到刺痛。"},sec={{t="群山彼端的呼救",b="豺狼人争夺着湖畔镇通往外界的每条道路，黑石兽人则从北方不断袭来。镇上的卫兵早已不堪重负。所罗门镇长无法抽调战士，踏上前往王都、耗时数日的骑行旅程，只能由一名旅人将请求派遣正规军的正式求援信送到城门。"},{t="官僚与王座厅",b="马库斯·乔纳森将军负责暴风城的防务。所罗门的报告送到了他手中，他敬重这位镇长的领导才能，也明白事态紧迫。然而，军规禁止乔纳森在没有王室命令的情况下调动部队。赤脊山的防务必须等他与年轻的安度因国王及摄政议会商议后，才能得到支援。"}},faq={{q="所罗门镇长为什么需要信使？",a="豺狼人和黑石兽人威胁着湖畔镇，当地每一名卫兵都必须留下来保卫城镇、守住桥梁。所罗门镇长只能将紧急求援信托付给旅人。",al={"为何派我送信","为何需要信使","所罗门的信使"}},{q="《湖畔镇的现状》报告里写了什么？",a="《湖畔镇的现状》是一份关于赤脊山危机的正式报告。报告详述了不断增加的敌军数量、人员伤亡，以及若无王都正规军支援，城镇即将陷落的处境。",al={"湖畔镇的现状","所罗门的报告","信中写了什么"}},{q="马库斯·乔纳森将军是谁？",a="马库斯·乔纳森将军统率暴风城卫兵，也是暴风城军队的高级将领。他负责巡视城门，直接向伯瓦尔·弗塔根公爵和王室汇报。",al={"马库斯·乔纳森","将军是谁","暴风城的将军"}},{q="乔纳森将军为什么不立即派兵？",a="乔纳森将军无权自行调动军队。他必须将所罗门的报告呈交国王和摄政议会，取得正式的王室命令后，部队才能出发。",al={"为何不派兵","援军在哪里","乔纳森的回应"}},{q="湖畔镇与暴风城之间的道路安全吗？",a="不安全。凶悍的豺狼人团伙和迪菲亚拦路强盗在穿过赤脊山、通往艾尔文的道路上横行，让孤身信使的旅途危机四伏。",al={"通往暴风城的道路","旅途安全","赤脊山的道路"}},{q="暴风城最后派出援军了吗？",a="王都的政治动荡与拖延，阻碍了军队采取任何实质行动。湖畔镇和所罗门镇长几乎只能依靠雇佣兵与志愿者。",al={"援军是否抵达","湖畔镇的援助"}}},fp="22,260,26.277.0,29.320.0,45.192.0,43.203.0,31.200.0,54.190.0,49.148.0,35.173.1"}
P.entries["quest:1200"] = {n="黑暗深渊中的恶魔",s="在黑暗深渊，银月守卫塞尔瑞德呼吁联盟阻止梦游者克尔里斯。这名邪教首领将俘虏献祭给阿库麦尔，塞尔瑞德要求将克尔里斯的首级带到达纳苏斯，交给银色黎明作为凭证。",h="在黑暗深渊，银月守卫塞尔瑞德呼吁联盟阻止梦游者克尔里斯。这名邪教首领将俘虏献祭给阿库麦尔，塞尔瑞德要求将克尔里斯的首级带到达纳苏斯，交给银色黎明作为凭证。",kw={"阿库麦尔","银色黎明","黑暗深渊","达纳苏斯","深渊","艾露恩","克尔里斯","月亮井","塞尔高姆","塞尔瑞德","暮光之锤"},ang={["class:Paladin"]="身为圣骑士，响应银色黎明的号召，诛杀将无辜者献祭给远古恐怖存在的邪教徒，便是施行神圣的惩戒。",["class:Priest"]="身为牧师，阻止克尔里斯就能终结这场亵渎，让那片曾因供奉神明而被奉为圣地的水域免遭玷污。",["faction:Alliance"]="身为联盟的一员，你协助银色黎明对抗克尔里斯，便是在帮助他们守护灰谷脆弱的边境，抵御邪教渗透。",["race:NightElf"]="对于暗夜精灵而言，为遭到亵渎的古老 Elune 神殿复仇，净化其中被污染的月亮井，关乎 kaldorei 传承的根本。"},sec={{t="遭到亵渎的圣所",b="黑暗深渊曾是一座供奉 艾露恩 的暗夜精灵神殿。一位古老的上古之神的腐化之力从岩石中涌出，污染了月亮井，并释放了阿库麦尔，这头贪婪的巨兽是那股黑暗力量的仆从。神殿遭到亵渎后，暮光之锤与当地的纳迦联手，将神圣的殿堂变成了举行杀戮仪式的场所。"},{t="倒下守卫的恳求",b="银月守卫塞尔瑞德代表所属组织进入黑暗深渊，却身受重伤，耗尽了力量。身陷敌群的他知道，自己已无法独力完成使命。他恳求来到他身边的勇敢联盟旅人杀死梦游者克尔里斯，这名邪教徒主导着将无辜者献祭给阿库麦尔的仪式，以换取黑暗力量。"},{t="达纳苏斯的正义",b="在达纳苏斯的工匠区，克尔里斯的首级被交给哨兵塞尔高姆，为这场漫长而令人不安的追捕画上了句号。银色黎明曾担心克尔里斯已经死去，或是消失在暗影之中，因为每当黑暗势力在卡利姆多蠢动，他都曾屡次卷入其中。他的死为挫败邪教在灰谷的图谋带来了一场至关重要的胜利。"}},faq={{q="银月守卫塞尔瑞德是谁？",a="塞尔瑞德是银色黎明的一名特工，受命调查黑暗深渊中日益滋长的暗影。他在深处身受重伤，力量耗尽，于是招募途经的冒险者去阻止克尔里斯。",al={"塞尔瑞德 是谁","塞尔瑞德 的故事","银色卫士"}},{q="为何要对付梦游者克尔里斯？",a="克尔里斯率领着黑暗深渊中的暮光之锤邪教徒。他将无辜的俘虏献祭给阿库麦尔，一头与上古之神有关的邪恶巨兽，以换取邪恶力量。",al={"克尔里斯 是谁","为何杀死 克尔里斯","梦游者克尔里斯"}},{q="哨兵塞尔高姆是谁？",a="哨兵塞尔高姆是驻守在达纳苏斯工匠区的银色黎明代表。他负责监督银色黎明在卡利姆多北部抵御腐化侵蚀的行动。",al={"塞尔高姆 达纳苏斯","塞尔高姆 是谁","银色黎明 达纳苏斯"}},{q="黑暗深渊有怎样的历史？",a="黑暗深渊在成为沉没的巢穴之前，其洞穴中曾坐落着一座供奉艾露恩的宏伟暗夜精灵神殿。一位上古之神的恶意从地下涌出，污染了神圣的月亮井，神殿也随之沦为废墟。",al={"黑暗深渊 历史","黑暗深渊曾是什么","艾露恩 神殿 黑暗深渊"}},{q="阿库麦尔是谁？",a="阿库麦尔是一位上古之神的仆从，形似多头蛇，庞大可怖，从黑暗深渊下方遭到污染的水中爬出。暮光之锤崇拜阿库麦尔，并用俘虏喂养它，以求获得黑暗的赐福。",al={"阿库麦尔是什么","阿库麦尔的故事","阿库麦尔 巨兽"}},{q="暮光之锤为何与纳迦联手？",a="暮光之锤与纳迦缔结盟约的原因尚不完全清楚。在黑暗深渊，他们联手占据了神殿废墟，而邪教徒则将俘虏献祭给阿库麦尔。",al={"纳迦 邪教徒 联手","纳迦为何在 黑暗深渊","暮光之锤与纳迦"}}},fp="20,235,19.384.0,23.362.0,20.369.1,29.203.0,43.180.0,27.192.0,41.201.0,15.200.0,56.215.0"}
P.entries["quest:1201"] = {n="塞拉摩间谍",s="部落与联盟之间的停战并不安稳，双方仍有小规模冲突和秘密行动。蕨墙村的纳泽尔·血矛要人追杀村子东边的联盟渗透者。",h="部落与联盟之间的停战并不安稳，双方仍有小规模冲突和秘密行动。蕨墙村的纳泽尔·血矛要人追杀村子东边的联盟渗透者。",kw={"蕨墙村","尘泥","渗透者","纳泽尔·血矛","间谍","塞拉摩"},sec={{t="村东的间谍",b="联盟渗透者已在蕨墙村东边落脚，监视村子，并将部落的动向传回塞拉摩。当地的间谍首领纳泽尔·血矛绝不会容忍这种事。你受命找到并杀死这些渗透者，让他们的上级知道，这里不欢迎这样的间谍。"}},faq={{q="是谁下令杀死塞拉摩的渗透者？",a="蕨墙村当地的间谍首领，纳泽尔·血矛。",al={"谁发布塞拉摩间谍任务","纳泽尔·血矛间谍任务","谁开启塞拉摩间谍"}},{q="渗透者藏在哪里？",a="在蕨墙村东边的岛屿上。",al={"塞拉摩渗透者位置","塞拉摩间谍在哪里","尘泥渗透者位置"}},{q="间谍为什么监视蕨墙村？",a="他们监视村子，并将部落的动向传回塞拉摩。",al={"人类为什么监视蕨墙村","蕨墙村间谍动机"}},{q="处理完间谍之后会发生什么？",a="故事的下一步是塞拉摩码头。",al={"塞拉摩间谍后续","塞拉摩间谍之后是什么任务"}}},fp="15,196,25.250.0,51.87.0,34.65.0,47.87.0,40.37.0"}
P.entries["quest:1202"] = {n="塞拉摩码头",s="两名间谍奉命从塞拉摩的一艘船上窃取文件，却被人发现，不得不将文件抛入海中。如今，纳泽尔·血矛要你找回这些文件。",h="两名间谍奉命从塞拉摩的一艘船上窃取文件，却被人发现，不得不将文件抛入海中。如今，纳泽尔·血矛要你找回这些文件。",kw={"蕨墙村","指挥官的文件","码头","尘泥沼泽","储物箱","纳泽尔·血矛","间谍","塞拉摩"},sec={{t="水中的文件",b="你处理了塞拉摩的间谍之后，纳泽尔·血矛又有一件事要交给你。两名间谍奉命从塞拉摩码头旁的一艘船上窃取文件。他们得手后被人发现，不得不将窃取的文件抛入海中。其中一人逃脱了，却没能取回文件，只好回来报告任务失败。"},{t="码头之下",b="文件装在一只储物箱里，沉在塞拉摩码头附近的某处水下。你受命找到指挥官的文件，并将它们带给蕨墙村的纳泽尔·血矛。纳泽尔说，这些文件对联盟的稳定至关重要，因此也关乎部落的安全。"}},faq={{q="谁派你前往塞拉摩岛？",a="蕨墙村的纳泽尔·血矛。",al={"谁发布任务","任务在哪里开始","任务发布者"}},{q="你要在码头下面寻找什么？",a="塞拉摩码头下方水域里的一只储物箱，里面装着指挥官的文件。",al={"需要寻找什么","水里有什么物品","码头任务目标"}},{q="文件为什么会被扔进水里？",a="两名间谍从码头的一艘船上偷走了文件，却被人发现，不得不将文件抛入海中。其中一人逃脱了，但没能带走文件。",al={"文件为什么在海里","储物箱怎么到那里的","间谍为什么扔掉它"}},{q="部落为什么想要这些文件？",a="纳泽尔·血矛说，这些文件对联盟的稳定至关重要，因此也关乎部落的安全。",al={"文件为什么重要","文件里有什么","血矛为什么想要文件"}},{q="这段故事之前发生了什么？",a="此前的任务是塞拉摩间谍，你在那个任务中追捕了蕨墙村以东的渗透者。",al={"前置任务","上一个任务","什么任务引出此任务"}}},fp="19,170,19.288.0,17.292.0,32.52.0,43.95.0,45.136.0,40.118.0,40.90.0"}
P.entries["quest:1203"] = {n="加尔的剑",s="尘泥沼泽的“沼泽之眼”加尔有东西要切，却不肯说是什么。加尔想要一把特定的剑，叫作月钢宽剑，而且不希望你拖拖拉拉。",h="尘泥沼泽的“沼泽之眼”加尔有东西要切，却不肯说是什么。加尔想要一把特定的剑，叫作月钢宽剑，而且不希望你拖拖拉拉。",kw={"尘泥沼泽","加尔","月钢宽剑","“沼泽之眼”加尔","挥刃"},sec={{t="一把特定的剑",b="“沼泽之眼”加尔有东西要切，却不能说要切的是什么。加尔需要一把特定的剑，有人叫它月钢宽剑，加尔则叫它大砍刀。你也许能在镇上找到一把，或者找个铁匠专门打造一把。加尔提醒你别耽搁，因为要切的东西可放不了太久。"}},faq={{q="谁在求一把剑？",a="“沼泽之眼”加尔，他就在尘泥沼泽。",al={"加尔的剑任务由谁发布","加尔是谁","“沼泽之眼”加尔"}},{q="加尔需要什么武器？",a="一把月钢宽剑，加尔叫它挥砍之刃。",al={"加尔想要什么剑","加尔的武器","加尔需要哪把剑"}},{q="加尔为什么急需一把剑？",a="加尔有东西要切，却不能说要切的是什么，还提醒你那东西放不了太久。",al={"加尔为什么需要剑","加尔要切什么","加尔的目的"}},{q="加尔建议去哪里找这把剑？",a="加尔说，你也许能在镇上找到一把，或者找个能专门打造这把剑的铁匠谈谈。",al={"如何为加尔获取月钢宽剑","在哪里找到加尔要的剑"}}},fp="18,138,15.320.0,28.65.0,30.69.0,39.101.0,42.77.0"}
P.entries["quest:1204"] = {n="泥石龟蟹汤",s="在塞拉摩，摩根·斯特恩正在研制一道名为泥石龟蟹汤的菜肴，或许能让它成为暴风城各家旅店的新宠。摩根·斯特恩觉得自己无法活着走完穿越尘泥沼泽的漫长路途，于是请你去收集泥石海龟的舌头。",h="在塞拉摩，摩根·斯特恩正在研制一道名为泥石龟蟹汤的菜肴，或许能让它成为暴风城各家旅店的新宠。摩根·斯特恩觉得自己无法活着走完穿越尘泥沼泽的漫长路途，于是请你去收集泥石海龟的舌头。",kw={"蓝色隐士","虫子","尘泥沼泽","分叉的舌头","摩根·斯特恩","泥石","汤","塞拉摩"},sec={{t="研制新菜",b="摩根·斯特恩正在研制一道名为泥石龟蟹汤的菜肴，还缺少主要食材。摩根·斯特恩觉得自己无法活着走完穿越尘泥沼泽的漫长路途，因此请你去猎取食材。首先要收集的是泥石海龟的舌头。"},{t="分叉的舌头",b="泥石龟在海岸一带游荡，大多聚集在海湾附近。摩根·斯特恩要的可不是普通的舌头。摩根·斯特恩听说，有些泥石龟的舌头是分叉的，带有这道菜所需的独特风味。"},{t="端上餐桌",b="摩根·斯特恩会尝试用不同的方法烹制这些舌头，寻找最能激发其滋味的做法。希望能做出一道足以端上暴风城蓝色隐士餐桌的菜肴。"}},faq={{q="谁在收集海龟的舌头？",a="塞拉摩的摩根·斯特恩，正在研制一道名为泥石龟蟹汤的菜肴。",al={"谁提供 泥石龟蟹汤 任务","摩根·斯特恩 塞拉摩"}},{q="在哪里能找到泥石海龟？",a="在尘泥沼泽的海岸一带，大多聚集在海湾附近。",al={"泥石 海龟位置","泥石龟 在哪里"}},{q="为什么摩根·斯特恩特别想要分叉的舌头？",a="摩根·斯特恩听说这些舌头带有独特的风味，想把这种风味融入菜肴。",al={"为什么要分叉的舌头","收集 泥石 分叉舌头的原因"}},{q="为什么摩根·斯特恩不亲自收集食材？",a="摩根·斯特恩觉得自己无法活着走完穿越尘泥沼泽的漫长路途。",al={"摩根·斯特恩 为什么不去狩猎","摩根·斯特恩 沼泽"}},{q="这个任务之后是什么任务？",a="下一步的任务叫做 ... 还有螃蟹。",al={"泥石龟蟹汤之后的任务","泥石龟蟹汤后续任务"}}},fp="21,197,20.210.0,14.178.0,16.174.1,37.74.0,39.80.0,55.81.0,56.76.0,28.37.0"}
P.entries["quest:1205"] = {n="死沼巨鳄",s="在尘泥沼泽，死沼巨鳄在石槌废墟以北的水道中饱受痛苦折磨。梅洛·石蹄从雷霆崖的猎人高地派出猎人，追踪这头年迈的鳄鱼，并带回一颗牙齿作为证明。这场狩猎教会猎人追踪与仁慈。",h="在尘泥沼泽，死沼巨鳄在石槌废墟以北的水道中饱受痛苦折磨。梅洛·石蹄从雷霆崖的猎人高地派出猎人，追踪这头年迈的鳄鱼，并带回一颗牙齿作为证明。这场狩猎教会猎人追踪与仁慈。",kw={"鳄鱼","死沼巨鳄","尘泥沼泽","猎人高地","梅洛·石蹄","石槌废墟","雷霆崖"},ang={["class:Hunter"]="身为猎人，你要在狩猎技艺与精神责任之间取得平衡。一次光荣的击杀也可以是仁慈之举。",["faction:Horde"]="身为部落的旅者，你为雷霆崖的长者参与狩猎，了解牛头人盟友的土地与传统。",["race:Tauren"]="身为牛头人，你敬重Earth Mother的生灵，尊重生死的自然轮回。"},sec={{t="仁慈的狩猎",b="在雷霆崖的猎人高地，梅洛·石蹄向有潜力的追踪者传授狩猎的精神传统。牛头人猎人追求的是敬畏自然、与自然世界建立联系，而非杀戮或战利品。梅洛·石蹄派你向东前往尘泥沼泽，寻找死沼巨鳄，这头年迈鳄鱼的漫长生命已成为负担。"},{t="沼泽中的年迈生灵",b="在石槌废墟以北，死沼巨鳄以庞大而苍白的鳄鱼之躯游荡在水道中。他仍会骤然爆发出力量与怒火，但衰老已让他的身体不堪重负，骨骼相互磨损，疼痛永无止境。梅洛·石蹄请你让他迅速而光荣地死去，并带回一颗牙齿，作为他获得解脱的信物。"}},faq={{q="死沼巨鳄是谁？",a="死沼巨鳄是尘泥沼泽湿地中一头庞大而年迈的白色鳄鱼。他依然危险，却因衰老衰弱的身体而饱受疼痛折磨。",al={"死沼巨鳄是什么","死沼巨鳄的故事","这头鳄鱼是谁"}},{q="梅洛·石蹄为什么想要杀死死沼巨鳄？",a="梅洛·石蹄请你出于仁慈杀死死沼巨鳄。这头鳄鱼老化的骨骼让他痛得发狂，而梅洛·石蹄认为，让他的灵魂获得解脱是一项神圣的职责。",al={"为什么杀死死沼巨鳄","梅洛·石蹄的动机","狩猎死沼巨鳄的目的"}},{q="在哪里能找到死沼巨鳄？",a="死沼巨鳄游荡在尘泥沼泽石槌废墟以北的水道中。",al={"死沼巨鳄在哪里","死沼巨鳄的位置","寻找死沼巨鳄"}},{q="梅洛·石蹄要求带回什么狩猎证明？",a="梅洛·石蹄请你带回死沼巨鳄的一颗牙齿，作为狩猎的证明。",al={"死沼巨鳄任务物品","梅洛·石蹄想要什么","死沼巨鳄狩猎证明"}},{q="这场狩猎能教会有志成为猎人的人什么？",a="这场狩猎教会你，猎人的使命不止于杀戮。它意味着尊重自然，也意味着懂得何时一个生灵的生命已只剩痛苦。",al={"猎人的理念","牛头人的狩猎教诲","狩猎的意义"}},{q="谁会给予这个任务？",a="牛头人猎人梅洛·石蹄在雷霆崖的猎人高地交付这项狩猎任务。",al={"死沼巨鳄任务给予者","谁给予死沼巨鳄任务","梅洛·石蹄的位置"}}},fp="8,201,15.337.0,24.315.0,16.156.0,46.173.0,28.79.0,44.74.0,43.155.0,21.82.0"}
P.entries["quest:1206"] = {n="加尔和蜘蛛眼",s="水光庄园的“沼泽之眼”加尔想要四十颗完整的黑雾眼球，因为黑雾眼球汁口感顺滑，带着咸味。这些蜘蛛生活在庄园西边的黑雾洞穴。",h="水光庄园的“沼泽之眼”加尔想要四十颗完整的黑雾眼球，因为黑雾眼球汁口感顺滑，带着咸味。这些蜘蛛生活在庄园西边的黑雾洞穴。",kw={"黑雾","黑雾洞穴","尘泥沼泽","加尔","蜘蛛眼","沼泽之眼加尔","水光庄园"},sec={{t="爱吃蜘蛛眼",b="在舒心草之后，加尔转而想要眼球汁，这东西很适合喝。大多数小动物只有一双眼睛，蜘蛛却有许多眼睛，而加尔觉得黑雾眼球汁很美味。黑雾蜘蛛生活在庄园西边的黑雾洞穴，加尔琢磨着，究竟是蜘蛛因洞穴而得名，还是洞穴因蜘蛛而得名。"},{t="加尔的盛宴",b="眼球送到时，加尔欢呼起来，称赞它们很美味。加尔建议，盯着看时会回瞪的眼球要留到最后吃，因为它们能在沼泽里给人作伴。随后，加尔向这些小眼球打招呼，尝了尝，宣称它们吃起来像黏糊糊、咸滋滋的鸡肉。"}},faq={{q="谁想要蜘蛛眼？",a="尘泥沼泽水光庄园的“沼泽之眼”加尔想要这些眼球。",al={"谁提供这个任务","加尔任务给予者","沼泽之眼加尔"}},{q="加尔为什么想要蜘蛛眼？",a="加尔喜欢喝眼球汁，觉得黑雾眼球汁口感顺滑，带着咸味。大多数小动物只有两只眼睛，蜘蛛却有许多眼睛。",al={"为什么要蜘蛛眼","加尔拿眼球做什么","眼球汁"}},{q="黑雾蜘蛛在哪里？",a="加尔说，黑雾蜘蛛就在水光庄园西边的黑雾洞穴里。",al={"黑雾洞穴位置","黑雾蜘蛛在哪里","哪里能找到眼球"}},{q="加尔想要多少颗眼球？",a="加尔想要四十颗完整的黑雾眼球。",al={"多少颗眼球","眼球数量"}},{q="这之前是什么任务？",a="前一个任务是舒心草。",al={"上一个任务","前置任务","什么任务引出这个任务"}}},fp="15,147,23.326.0,16.254.1,29.79.0,31.148.0,31.71.0,29.40.0,23.27.0"}
P.entries["quest:121"] = {n="送往暴风城的信",s="你从暴风城带着马库斯·乔纳森将军的回信前往湖畔镇，那里正受到黑石兽人和豺狼人的威胁。首都的领袖们迟迟没有决断，也未派出援军，让这座城镇孤立无援。",h="你从暴风城带着马库斯·乔纳森将军的回信前往湖畔镇，那里正受到黑石兽人和豺狼人的威胁。首都的领袖们迟迟没有决断，也未派出援军，让这座城镇孤立无援。",kw={"黑石兽人","伯瓦尔","湖畔镇","所罗门镇长","马库斯·乔纳森","送往暴风城的信","赤脊山","暴风城"},ang={["faction:Alliance"]="身为联盟的一员，你看到了政治僵局如何让王国的人类领地无力抵御各地的威胁。",["race:Human"]="身为王国的人类子民，你往返于戒备森严的暴风城与毗邻它的艾尔文地区日渐崩溃的边境之间，传递这些信件。"},sec={{t="送往湖畔镇的公文",b="你已将所罗门镇长请求增援的求援信送到了暴风城的马库斯·乔纳森将军手中。如今，你带着他的第一封回信返回赤脊山，而他仍在等待王室批准。没有王室的许可，将军无法调动军队。湖畔镇的居民依然没有城市卫兵保护，每过一天，这座城镇就离落入黑石氏族之手更近一步。"},{t="王国的不安",b="所罗门镇长在乔纳森的回信中，没有看到任何关于部队将沿艾尔文边境向东进军的承诺。信中只有办事程序，没有援军，所罗门察觉到王廷出了问题。瓦里安·乌瑞恩国王下落不明，摄政局面陷入僵局。湖畔镇这样的边远城镇只能自行防守。"}},faq={{q="马库斯·乔纳森将军的回信说了什么？",a="马库斯·乔纳森将军在信中表示，没有国王或王廷的正式授权，他无法派出暴风城的军队。他已将此事呈报王室，湖畔镇只能继续等待。",al={"信中说了什么","将军的回信","马库斯·乔纳森的信"}},{q="暴风城为什么不能直接派兵前往赤脊山？",a="瓦里安·乌瑞恩国王失踪后，政务决策由年幼的安度因国王、摄政王伯瓦尔·弗塔根和贵族共同掌管。首都内部的分歧与拖延，使乔纳森将军无法在未经王室批准的情况下出兵。",al={"暴风城为何不援助","暴风城为何不援助湖畔镇","暴风城军队赤脊山"}},{q="所罗门镇长是谁？",a="所罗门镇长治理着湖畔镇和赤脊山。他领导这座城镇，协调其有限的防御力量，抵御黑石兽人、豺狼人和当地匪徒。",al={"所罗门镇长","所罗门是谁","湖畔镇镇长"}},{q="马库斯·乔纳森将军是谁？",a="马库斯·乔纳森将军统率暴风城卫兵和首都的常备军。他驻守在英雄谷，就在暴风城正门内侧。",al={"马库斯·乔纳森是谁","乔纳森将军","暴风城将军"}},{q="所罗门读完信后会做什么？",a="读完信后，所罗门向邻近地区寻求援助，并派你去了解西部荒野的情况。",al={"接下来发生什么","送往暴风城的信后续任务","接下来去哪里"}},{q="所罗门为什么说“我们的王国出了问题”？",a="在所罗门看来，拒绝或拖延援助一座正遭受攻击的边境城镇，在军事上毫无道理。这种拖延让他警觉，暴风城的政治领袖正受到内部势力的操纵，或已因此无法决策。",al={"出了问题","所罗门为何担忧","暴风城阴谋"}}},fx={["53d96341"]={q="马库斯·乔纳森将军为什么派你返回湖畔镇？",a="所罗门镇长紧急请求暴风城派遣援军，抵御包围湖畔镇的豺狼人和兽人。乔纳森将军虽然已向王室请求援助，但没有王室的授权，他就不能调动皇家军队。他让你带回正式答复，以免王室在首都迟迟未能作出决定时，湖畔镇的领导者仍对情况一无所知。",al={"马库斯·乔纳森为何送信","马库斯·乔纳森给湖畔镇的回信","乔纳森将军为何要做这件事"}},["64d074bd"]={q="乔纳森将军为什么把这封信交给你，而不是皇家信使？",a="正是你将所罗门最初的求援信从赤脊山送到了英雄谷。暴风城的驻军既要维持秩序，又要守卫首都城门，早已人手紧张，因此乔纳森将军认为，让熟悉返回湖畔镇道路的能干冒险者送信，远比抽调一名驻守的卫兵更为可行。",al={"马库斯·乔纳森为何派我","为何不让皇家卫兵送信","为何让冒险者送信到湖畔镇"}}},fp="22,205,23.372.0,21.320.1,46.198.0,51.229.0,26.175.0,31.180.0,51.112.1,57.192.0"}
P.entries["quest:1218"] = {n="舒心草",s="“沼泽之眼”加尔喜欢沼泽风味的烹饪，需要些温和的香料来炖汤。尘泥沼泽的加尔请你带来三份舒心草。",h="“沼泽之眼”加尔喜欢沼泽风味的烹饪，需要些温和的香料来炖汤。尘泥沼泽的加尔请你带来三份舒心草。",kw={"尘泥沼泽","蛙腿","舒心草","炖汤","“沼泽之眼”加尔"},sec={{t="锅里的香料",b="“沼泽之眼”加尔喜欢沼泽风味的烹饪，油炸绿蛙腿就是其中一道菜。他打算炖汤，需要些温和的香料。谁带来香料，就能分到一份。加尔想要三份舒心草，还想知道你喜不喜欢炖汤。"}},faq={{q="谁需要温和的香料？",a="“沼泽之眼”加尔，他在尘泥沼泽。",al={"谁提供舒心草任务","舒心草任务给予者","“沼泽之眼”加尔 香料"}},{q="“沼泽之眼”加尔打算用香料做什么？",a="炖汤。加尔喜欢沼泽风味的烹饪，比如油炸绿蛙腿，还打算和你分享炖汤。",al={"加尔做什么","加尔炖什么汤","加尔的食物"}},{q="加尔需要多少份香料？",a="加尔需要三份舒心草。",al={"多少份舒心草","舒心草数量","舒心草需求"}}},fp="15,77,17.225.0,30.78.0,56.124.0,31.33.0"}
P.entries["quest:1219"] = {n="兽人的报告",s="你在尘泥沼泽翻检松软的泥土时，发现了一只兽人的断手，紧握着一个用骨头雕成的筒子。筒子里装着一张沾满泥土的羊皮纸，上面写着兽人语，看起来很重要。这张羊皮纸是要交给一位塞拉摩海军上尉的。",h="你在尘泥沼泽翻检松软的泥土时，发现了一只兽人的断手，紧握着一个用骨头雕成的筒子。筒子里装着一张沾满泥土的羊皮纸，上面写着兽人语，看起来很重要。这张羊皮纸是要交给一位塞拉摩海军上尉的。",kw={"骨筒","尘泥沼泽","松软的泥土","兽人报告","塞拉摩海军上尉"},sec={{t="泥土中的断手",b="松软的泥土里埋着一只兽人的断手，紧握着一个用骨头雕成的筒子。里面装着一张沾满泥土的羊皮纸，上面写着兽人语，似乎颇有意义。应该把它拿给一位塞拉摩海军上尉看看。"},{t="上尉的判断",b="上尉承认自己不太懂兽人语，却认定这张羊皮纸是一名兽人间谍的报告。"}},faq={{q="松软的泥土里藏着什么？",a="翻检泥土后，你发现了一只兽人的断手，紧握着一个用骨头雕成的筒子，里面装着一张沾满泥土的羊皮纸。",al={"松软的泥土里有什么","松软的泥土物品","尘泥沼泽的兽人断手"}},{q="应该把羊皮纸交给谁？",a="一位塞拉摩海军上尉。",al={"报告交到哪里","间谍报告交给谁","塞拉摩海军上尉位置"}},{q="羊皮纸上写的是什么语言？",a="上面写的是兽人语，似乎颇有意义。",al={"羊皮纸上的语言","能否读懂羊皮纸"}}},fp="14,152,18.209.0,24.124.1,33.117.0,29.52.0,42.70.0"}
P.entries["quest:122"] = {n="雏龙的鳞片",s="弗纳·奥斯古需要黑色雏龙的腹鳞，来偿还欠闪金镇铁匠阿古斯的货款。你从湖畔镇南部峭壁间游荡的幼龙身上收集这些鳞片。这些鳞片能还清弗纳的欠款，还能余下足够的生皮制作一件装备。",h="弗纳·奥斯古需要黑色雏龙的腹鳞，来偿还欠闪金镇铁匠阿古斯的货款。你从湖畔镇南部峭壁间游荡的幼龙身上收集这些鳞片。这些鳞片能还清弗纳的欠款，还能余下足够的生皮制作一件装备。",kw={"黑色雏龙","龙族","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","腹鳞","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇南部日益加剧的黑龙威胁，让赤脊山本已疲于应付的驻军负担更重。",["profession:Blacksmithing"]="铁匠阿古斯的要求表明，在钱币短缺时，铁匠会用龙鳞这样的稀有材料进行以物易物的交易。",["race:Human"]="身为人类，你知道艾尔文森林与赤脊山之间的商路为湖畔镇这样的城镇供应物资，不过边境工匠往往要向城里的商人支付高昂的价钱。"},sec={{t="边境的欠款",b="弗纳·奥斯古在湖畔镇郊外经营着一间铁匠铺，经常与赤脊山以外的工匠交易。闪金镇的铁匠阿古斯给他送来了一批马蹄铁，但弗纳手头缺钱。阿古斯要求用珍贵的龙皮抵账：当地筑巢的黑色雏龙身上备受珍视、较为柔软的腹鳞。若交不出这些鳞片，讨债人就可能从艾尔文森林前来追讨欠款。"},{t="黑龙的子嗣",b="赤脊山的黑色雏龙让当地守军深感不安。豺狼人和兽人争夺道路的控制权，而黑龙在高峰上筑巢，其子嗣在止水湖南面的天空中游荡。这些年幼掠食者的腹鳞坚韧而柔韧。王国各地的铸甲师、铁匠和制皮匠都十分看重这些鳞片，前提是他们敢去采集。"}},faq={{q="弗纳·奥斯古为什么需要龙鳞？",a="弗纳欠着闪金镇铁匠阿古斯一批马蹄铁的货款。阿古斯要求用黑色雏龙的腹鳞代替钱币支付。弗纳需要尽快收到这些鳞片，赶在阿古斯派人前来讨债之前。",al={"为什么需要龙鳞","弗纳的欠款","阿古斯的鳞片"}},{q="赤脊山的黑色雏龙在哪里？",a="黑色雏龙常在湖畔镇南部的岩石峭壁和山谷间出没。它们在南部山麓四处游荡，因此猎人常沿着小径和山脊巡查，寻找它们飞行的身影。",al={"雏龙位置","雏龙在哪里","赤脊山雏龙位置"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是艾尔文森林闪金镇的铁匠。他为附近的城镇供应金属制品和锻造物品，其中就包括给赤脊山的弗纳·奥斯古打造的马蹄铁。",al={"闪金镇阿古斯","阿古斯是谁","铁匠阿古斯"}},{q="赤脊山为什么会有黑色雏龙？",a="黑龙盘踞在燃烧平原各处，以及赤脊山周围的群峰之中。它的雏龙穿过山口向南游荡，进入赤脊山的山麓猎食。",al={"赤脊山为什么有龙","赤脊山黑龙"}},{q="腹鳞有什么特别之处？",a="腹鳞柔软而富有弹性，与幼龙背部厚重坚硬的鳞片不同。它们仍能很好地抵御高温和穿刺，因此可用于特殊的制皮工艺、量身定制的加固处理，也可作为珍奇货物交易。",al={"为什么需要腹鳞","鳞片价值","龙皮品质"}},{q="还清这笔欠款后，弗纳还会交付其他任务吗？",a="你将那批马蹄铁交给弗纳·奥斯古后，他便会提出这个请求。随着赤脊山的威胁日益加剧，除了这项可选的收集任务，弗纳还会派冒险者去猎杀豺狼人斥候和首领。",al={"后续任务","弗纳任务线","奥斯古后续任务"}}},fp="17,238,15.359.0,25.366.0,42.209.0,52.172.0,19.186.0,50.191.0,37.228.0,55.201.0"}
P.entries["quest:1220"] = {n="维米斯队长",s="艾登中尉 派你把找到的兽人报告交给盖兰·维米斯队长，他比大多数人都精通兽人语。还要一并带去部落间谍在塞拉摩附近活动的消息。",h="艾登中尉 派你把找到的兽人报告交给盖兰·维米斯队长，他比大多数人都精通兽人语。还要一并带去部落间谍在塞拉摩附近活动的消息。",kw={"维米斯队长","尘泥沼泽","加兰·维米斯","阿登中尉","兽人报告","间谍的报告","塞拉摩","塞拉摩岛"},sec={{t="给队长的报告",b="艾登中尉 认为，你找到的兽人报告应该交给盖兰·维米斯队长，他比大多数人都精通兽人语。艾登 还希望你告诉队长，部落间谍正潜伏在塞拉摩附近。你可以在塞拉摩岛东北侧的兵营找到维米斯。"}},faq={{q="谁派你去找维米斯队长？",a="艾登中尉，他希望队长看看你找到的兽人报告。",al={"维米斯队长 任务起始人","维米斯队长 任务在哪里接"}},{q="盖兰·维米斯队长在哪里？",a="在塞拉摩岛东北侧的兵营里。",al={"维米斯队长 在哪里","维米斯队长 位置","维米斯 兵营"}},{q="为什么维米斯队长需要看这份报告？",a="艾登说，维米斯比大多数人都精通兽人语，也应该听听部落间谍在塞拉摩附近活动的消息。",al={"为什么找 维米斯队长","维米斯 为什么需要报告"}}},fp="13,109,24.264.0,31.83.0,38.80.0,46.110.0"}
P.entries["quest:1221"] = {n="蓝叶薯",s="麦伯克·米希瑞克斯正在寻找剃刀沼泽根须下的蓝叶薯。这位棘齿城的地精商人派出训练有素的地鼠，寻找并挖出蓝叶薯，用于贸易。",h="麦伯克·米希瑞克斯正在寻找剃刀沼泽根须下的蓝叶薯。这位棘齿城的地精商人派出训练有素的地鼠，寻找并挖出蓝叶薯，用于贸易。",kw={"蓝叶薯","指挥棒","美味佳肴","麦伯克·米希瑞克斯","野猪人","棘齿城","剃刀沼泽","地鼠","贫瘠之地"},ang={["faction:Alliance"]="作为联盟旅者，你可以凭借米希瑞克斯在中立的棘齿城提供的贸易契约，进入部落领地附近的区域。",["faction:Horde"]="作为抵御野猪人入侵、保卫贫瘠之地的部落勇士，你可以引导米希瑞克斯训练的地鼠穿过沼泽，以此赚取报酬。",["profession:Cooking"]="作为厨师，你知道蓝叶薯是艾泽拉斯最稀有的美味之一。上流社会的买家格外珍视它们带有泥土气息的风味。",["profession:Herbalism"]="作为草药师，你知道蓝叶薯生长在剃刀的荆棘根须之间，深藏地下，不见阳光。"},sec={{t="珍贵的地下美味",b="蓝叶薯是世界各地备受珍视的稀有美味。它们很难采集，因为它们不生长在开阔的田野或普通的野生林地里。采集者在南贫瘠之地的地下深处找到它们，它们就藏在剃刀沼泽盘结的根须之间。"},{t="米希瑞克斯的巧思",b="棘齿城的商人麦伯克·米希瑞克斯想出了寻找地下蓝叶薯的办法。他训练的地鼠能在五十步外嗅到蓝叶薯的气味。他为采集者提供指挥棒、通风的箱子和训练手册，让他们能引导这些生物穿过野猪人的领地。"},{t="荆棘中的采集",b="采集蓝叶薯意味着要进入充满敌意的亡首野猪人部族的领地。采集者必须保护训练有素的地鼠，避开沼泽中的野兽和荆棘，再命令这些啮齿动物挖出埋藏的块茎。蓝叶薯随后被运回棘齿城，米希瑞克斯的海外买家正在那里等候。"}},faq={{q="蓝叶薯有什么用途？",a="蓝叶薯是世界各地备受珍视的稀有美味。富有的买家愿意出高价购买新鲜的蓝叶薯，让麦伯克·米希瑞克斯这样的地精能从这门生意中获利。",al={"蓝叶薯用途","蓝叶薯是什么","为什么采集蓝叶薯"}},{q="哪里能找到蓝叶薯？",a="蓝叶薯藏在南贫瘠之地的泥土和荆棘根须之下，位于野猪人的要塞剃刀沼泽之中。",al={"哪里能找到蓝叶薯","蓝叶薯位置","它们生长在哪里"}},{q="为什么需要地鼠来寻找蓝叶薯？",a="蓝叶薯埋在地下，肉眼无法看见。地鼠能在最远五十步外嗅到它们，并将它们挖出来。",al={"为什么使用地鼠","地鼠用途","地鼠如何找到蓝叶薯"}},{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是一位在棘齿城经营生意的地精商人，棘齿城是贫瘠之地的一座中立港口城镇。他训练当地的野生动物，并收购奇珍异货用于海外贸易。",al={"谁提供蓝叶薯任务","麦伯克·米希瑞克斯的故事","棘齿城地精任务给予者"}},{q="米希瑞克斯为这项工作提供什么装备？",a="米希瑞克斯提供一个装有受训地鼠的开孔的箱子、一根用来指挥地鼠挖掘的地鼠指挥棒，以及一本讲解如何驾驭这只野兽的地鼠训练手册。",al={"蓝叶薯任务物品","地鼠指挥棒","开孔的箱子"}},{q="为什么麦伯克不亲自采集蓝叶薯？",a="剃刀沼泽有凶悍的野猪人部族、带刺的藤蔓和地下的危险生物守卫。米希瑞克斯派其他人进入洞穴，免得自己冒险。",al={"为什么麦伯克不亲自采集","为什么雇用冒险者"}}},fp="15,139,30.240.0,20.288.0,24.273.0,34.179.0,32.129.0,50.132.0,22.160.0,49.182.0,42.184.0"}
P.entries["quest:1222"] = {n="伊格纳兹的逃亡",s="伊格纳兹正在沼泽里，塞拉摩的厨师摩根·斯特恩派他到那里采集沼泽豆叶。周围的野兽把他团团围住，他请你帮他脱困，并在他寻找沼泽豆植株时保护他。之后，你该去塞拉摩找摩根·斯特恩。",h="伊格纳兹正在沼泽里，塞拉摩的厨师摩根·斯特恩派他到那里采集沼泽豆叶。周围的野兽把他团团围住，他请你帮他脱困，并在他寻找沼泽豆植株时保护他。之后，你该去塞拉摩找摩根·斯特恩。",kw={"蓝色隐士","博格比恩","尘泥沼泽","摩根·斯特恩","伊格纳兹","塞拉摩"},sec={{t="身陷重围",b="遇到一个不把自己当作盘中餐的人，伊格纳兹松了一口气。他说，厨师摩根·斯特恩正在研究一道新菜，派他出来采集沼泽豆叶，伊格纳兹猜想斯特恩觉得这些叶子很好吃。伊格纳兹在寻找植株时被围住了，他请你帮他脱困，并在他搜寻时保护他。"},{t="厨师的等待",b="塞拉摩的摩根·斯特恩很着急：伊格纳兹前往沼泽已经有一阵子了，却仍未归来。"},{t="厨师的谢意",b="斯特恩说，伊格纳兹已经带着沼泽豆叶来过了，还讲述了你如何帮他渡过难关。为了表示感谢，斯特恩会请一位叔叔在你下次光临暴风城的蓝色隐士时，用一顿盛宴招待你。"}},faq={{q="伊格纳兹是谁？",a="厨师摩根·斯特恩派伊格纳兹前往沼泽采集沼泽豆叶。",al={"伊格纳兹","伊格纳兹是谁","伊格纳兹 尘泥"}},{q="伊格纳兹为什么遇到了麻烦？",a="他在寻找沼泽豆植株时，周围的野兽逐渐逼近，把他团团围住。",al={"伊格纳兹为什么被困","伊格纳兹被困","伊格纳兹为什么在尘泥"}},{q="沼泽豆叶有什么用？",a="摩根·斯特恩正在研究一道新菜，派伊格纳兹去采集这些叶子。伊格纳兹猜想斯特恩觉得这些叶子很好吃。",al={"沼泽豆叶","沼泽豆是什么","沼泽豆植株"}},{q="摩根·斯特恩是谁？",a="摩根·斯特恩是塞拉摩的一名厨师，正在研究一道新菜。",al={"摩根·斯特恩 塞拉摩","摩根·斯特恩是谁","厨师摩根·斯特恩"}}},fp="15,228,10.304.0,14.107.0,20.209.1,23.83.0,25.65.0,28.120.0,20.71.0"}
P.entries["quest:123"] = {n="收货人",s="在艾尔文森林，黄金在豺狼人袭击的掩护下，从废弃矿井中被运走。一份截获的公文称，负责监管这些货物的人叫作“收货人”，并指向暴风城驻军附近的一场有组织的行动。",h="在艾尔文森林，黄金在豺狼人袭击的掩护下，从废弃矿井中被运走。一份截获的公文称，负责监管这些货物的人叫作“收货人”，并指向暴风城驻军附近的一场有组织的行动。",kw={"布莱克威尔南瓜田","艾尔文森林","采金日程表","闪金镇","搜捕行动","治安官杜汉","矿井","收货人"},ang={["class:Rogue"]="身为潜行者，你可以阅读截获的日程表，循着艾尔文森林荒野中的犯罪网络追查走私货物。",["faction:Alliance"]="王国正艰难地保卫边境，而从艾尔文森林走私出去的每一盎司黄金，都让王室损失了税收和原材料。",["profession:Mining"]="身为矿工，你知道艾尔文森林那些关闭的矿井中仍有铜和贵金属。有人正在非法开采这些矿脉，而诚实的矿工却因恐惧而留在家中。"},sec={{t="豺狼人爪中的书面线索",b="艾尔文森林西部的河爪豺狼人身上带着一张名为采金日程表的羊皮纸。上面列出了收取当地矿井所产黄金的日期和时间。这份截获的字条要求将每批黄金交给一名监管者，此人只以“收货人”之名为人所知。"},{t="闪金镇的不安消息",b="在狮王之傲旅店，治安官杜汉得知，仍有人在开采和运送黄金。由于豺狼人的袭击、狗头人的侵扰和四处游荡的强盗，艾尔文森林各处的官方矿井已经关闭了数月。豺狼人身上携带的运输日程表，指向一个正在窃取王国财富的有组织犯罪网络。"},{t="目光投向布莱克威尔南瓜田",b="日程表显示，疑似收货人的人就在艾尔文森林东部的布莱克威尔南瓜田附近。治安官杜汉听说过这个名字，但没有确凿证据能说明谁在领导这个团伙，或黄金被运往何处。这份公文为驻军追查黄金运输的幕后指挥者提供了第一条可靠线索。"}},faq={{q="采金日程表是什么？",a="采金日程表是一份从艾尔文森林的豺狼人身上截获的字条。上面列出了将开采出的黄金交给一名叫作“收货人”的人物的日期和时间。",al={"采金日程表","收货人字条","艾尔文森林采金日程表"}},{q="“收货人”是谁？",a="“收货人”是一名犯罪人物，据信就在艾尔文森林东部的布莱克威尔南瓜田附近，协调非法黄金交易。",al={"收货人身份","收货人是谁","布莱克威尔南瓜田收货人"}},{q="治安官杜汉为何对这份日程表感到震惊？",a="治安官杜汉感到震惊，是因为官方矿井已经关闭数月，却仍有人在开采和运送黄金。豺狼人的袭击、狗头人的侵扰和四处游荡的强盗迫使矿井关闭，因此这份日程表揭露了一场窃取王室财富的秘密行动。",al={"治安官杜汉为何惊讶","治安官杜汉的反应","艾尔文森林矿井关闭"}},{q="豺狼人为什么会有这张字条？",a="艾尔文森林西部的河爪豺狼人似乎在黄金走私中充当信使、守卫或同伙，携带着日程表，传递收取黄金的指令。",al={"豺狼人黄金","豺狼人为何掉落日程表","豺狼人的参与"}},{q="这项调查接下来会指向哪里？",a="将日程表交给治安官杜汉后，就会接到猎杀收货人任务，派你前往布莱克威尔南瓜田附近寻找并除掉收货人。",al={"收货人后续","猎杀收货人任务","收货人之后"}},{q="布莱克威尔南瓜田位于何处？",a="布莱克威尔南瓜田位于艾尔文森林东部，河流以北，马科伦和斯通菲尔德的葡萄园以东。",al={"布莱克威尔南瓜田位置","布莱克威尔南瓜田在哪里","艾尔文森林南瓜田"}}},fp="13,214,35.237.0,29.314.0,27.320.1,33.177.0,23.146.0,46.268.0,29.159.0,40.141.0,45.127.0"}
P.entries["quest:1238"] = {n="遗失的报告",s="在尘泥沼泽，你发现了一份准备送往蕨墙村的间谍报告。一只兽人的断手紧握着一根骨管，里面装着一份沾满泥土的记录，记述了数周来监视塞拉摩的情况。",h="在尘泥沼泽，你发现了一份准备送往蕨墙村的间谍报告。一只兽人的断手紧握着一根骨管，里面装着一份沾满泥土的记录，记述了数周来监视塞拉摩的情况。",kw={"蕨墙村","尘泥沼泽","松软的泥土","纳泽尔·血矛","间谍报告","遗失的报告","塞拉摩"},sec={{t="泥土中的断手",b="你在松软的泥土中发现了一只兽人的断手，手指紧握着一根用骨头雕成的管子。里面装着一张沾满泥土的羊皮纸。这份报告记述了数周来刺探塞拉摩的情况，原本要交给蕨墙村的兽人间谍首领纳泽尔·血矛。"},{t="间谍首领的消息",b="纳泽尔·血矛说，报告的作者是玛格·夜眼。玛格是一名驻扎在塞拉摩城外、负责监视这座城市的密探。这是玛格最新的报告，也可能是最后一份。听了你的讲述，血矛担心玛格已经在沼泽中丧命。"}},faq={{q="报告在哪里找到？",a="你在尘泥沼泽松软的泥土中找到了报告，它被一只兽人的断手紧紧攥着。",al={"报告在哪里","遗失的报告位置","如何开始遗失的报告"}},{q="报告写了什么？",a="一名兽人在监视塞拉摩数周后写下了这份报告。",al={"报告内容","间谍报告写了什么","羊皮纸内容"}},{q="报告要交给谁？",a="报告要交给蕨墙村的兽人间谍首领纳泽尔·血矛。",al={"报告交给谁","遗失的报告交付","间谍报告交到哪里"}}},fp="15,184,18.259.0,23.247.1,26.86.0,25.60.0,20.80.0"}
P.entries["quest:1239"] = {n="被斩下的头颅",s="你在尘泥沼泽挖出了一颗男性兽人的断头。把它带给蕨墙村的纳泽尔·血矛。",h="你在尘泥沼泽挖出了一颗男性兽人的断头。把它带给蕨墙村的纳泽尔·血矛。",kw={"蕨墙村","不屈的兽人头颅","尘泥沼泽","松软的泥土","玛格·夜眼","纳泽尔·血矛","断头"},sec={{t="骇人的发现",b="你挖出了一颗男性兽人的头颅，颈部的断口参差不齐。他龇牙咧嘴，漆黑的双眼怒视前方，透着不屈。把这颗头颅带给蕨墙村的纳泽尔·血矛。"},{t="纳泽尔细察",b="纳泽尔·血矛一眼就认出了玛格·夜眼的头颅，尽管他此前就担心玛格已经死了。参差不齐的伤口让他无法确定，这名密探究竟是被武器斩首，还是死于野兽之口。纳泽尔想解开这个谜团，查明玛格的死是否是联盟所为。"}},faq={{q="该把断头带到哪里？",a="把断头带给蕨墙村的纳泽尔·血矛。",al={"断头在哪里交","断头交付","谁收头颅"}},{q="这颗头颅是什么样的？",a="这是一颗男性兽人的头颅，颈部的断口参差不齐，龇牙咧嘴，漆黑的双眼怒视前方，透着不屈。",al={"松软的泥土里有什么","不屈的兽人头颅","断头描述"}},{q="断头之后是什么？",a="下一步是巨魔巫医。",al={"断头之后的任务","断头后续"}}},fp="16,112,11.195.0,19.280.1,36.66.0,29.123.0,34.39.0"}
P.entries["quest:124"] = {n="豺狼人的乱吠",s="豺狼人从赤脊山山麓出发，袭击弗纳·奥斯古在湖畔镇的马厩。黑石兽人已在威胁这一带，弗纳请求旅人赶走危及他马匹的蛮兵和秘法师。",h="豺狼人从赤脊山山麓出发，袭击弗纳·奥斯古在湖畔镇的马厩。黑石兽人已在威胁这一带，弗纳请求旅人赶走危及他马匹的蛮兵和秘法师。",kw={"豺狼人","马匹","湖畔镇","赤脊山蛮兵","赤脊山","赤脊山秘法师","马厩","弗纳·奥斯古"},ang={["class:Hunter"]="身为猎人，你在赤脊山面对的野兽和凶猛兽群，因缺乏有组织的清剿而日益猖獗。它们威胁着家畜和旅人。",["faction:Alliance"]="暴风城的忽视让王国南部各处的小型聚落承受着重压。像弗纳这样的商人必须自掏腰包雇人，保护重要的补给线。"},sec={{t="山脊上的马匹",b="弗纳·奥斯古在湖畔镇经营马厩，如今已是危机四伏。黑石兽人占据着高地，成群的豺狼人在镇子周围的山脊上游荡。豺狼人掠夺者已经抵达弗纳牧马场的北缘，捕食那些游荡到峭壁附近的马匹。"},{t="协同而来的威胁",b="湖畔镇北面的豺狼人群既有蛮力，也会施展原始的法术。蛮兵以力量压倒猎物，秘法师则挥使狂野的魔法。削减它们的数量能让镇子获得短暂的喘息，但它们的凶猛攻势表明，山丘更高处还有一股更强大的势力。"}},faq={{q="弗纳·奥斯古为什么需要有人帮忙对付豺狼人？",a="北面山脊上的豺狼人已经开始逼近弗纳的马厩，掳走那些离开牧马场的马匹。黑石兽人也在威胁这一带，他独自一人无法保护自己的牲畜。",al={"弗纳的难题","弗纳为何要杀豺狼人","湖畔镇马厩豺狼人"}},{q="这些豺狼人在哪里？",a="赤脊山蛮兵和赤脊山秘法师在湖畔镇正北面和东面的高处山脊与山麓游荡，从那里可以俯瞰镇子和通往止水湖上的桥的道路。",al={"赤脊山 蛮兵在哪里","赤脊山 秘法师位置","马厩北面的豺狼人"}},{q="为什么除了黑石兽人，还要应付豺狼人？",a="黑石兽人是赤脊山面临的主要军事威胁，当地的豺狼人群趁机作乱。湖畔镇的守军已捉襟见肘，暴风城派来的援军又寥寥无几，这些捕食者因此可以肆意游荡，直逼村镇边缘。",al={"赤脊山兽人与豺狼人","为何既有豺狼人又有兽人"}},{q="处理这些豺狼人之后，还有什么事？",a="蛮兵和秘法师的数量减少后，山丘间的嚎叫仍未停歇。这表明周围的高地上，还有更具威胁的首领。",al={"豺狼人的乱吠后续","豺狼人的乱吠之后做什么"}},{q="为什么秘法师格外危险？",a="赤脊山秘法师使用粗浅的自然与元素魔法，以变幻无常、充满野性的咒语攻击闯入者。它们与蛮兵一同出现，说明这是一支有组织的氏族，而非独来独往的食腐者。",al={"赤脊山 秘法师背景","赤脊山豺狼人萨满祭司"}},{q="暴风城会派士兵保护湖畔镇的马厩吗？",a="不会。政治动荡与兵力短缺之下，暴风城王廷基本上已让赤脊山自行防卫。所罗门镇长和弗纳·奥斯古这样的居民必须招募四处游历的冒险者。",al={"暴风城卫兵赤脊山","为何没有卫兵帮助弗纳"}}},fp="18,187,19.275.0,20.298.1,45.204.0,31.182.0,53.252.0,43.147.1,39.208.0,61.203.0"}
P.entries["quest:1240"] = {n="巨魔巫医",s="纳泽尔·血矛想查明玛格·夜眼死亡前后发生的事，并说只有巨魔的巫术才能揭晓。你带着玛格的头颅，前往荆棘谷的格罗姆高营地，交给肯维雷。",h="纳泽尔·血矛想查明玛格·夜眼死亡前后发生的事，并说只有巨魔的巫术才能揭晓。你带着玛格的头颅，前往荆棘谷的格罗姆高营地，交给肯维雷。",kw={"暗矛巫医","不屈的兽人头颅","格罗姆高营地","肯维雷","玛格·夜眼","纳泽尔·血矛","荆棘谷"},sec={{t="巨魔的巫术",b="那颗被砍下的头颅出现后，纳泽尔·血矛坚持要查明玛格死亡前后发生的事，而只有巨魔的巫术才能揭晓。玛格的头颅要送到荆棘谷的格罗姆高营地，交给肯维雷。在暗矛巨魔中，没有哪个巫医比肯维雷更强大，纳泽尔认为，如果有人能与玛格的灵魂沟通，那一定是肯维雷。"},{t="在格罗姆高交谈",b="你抵达时，肯维雷察觉到你身边有一个愤怒的灵魂。看着这颗头颅，巫医发现这个兽人的灵魂被束缚在世间，因职责未尽而怒火沸腾，于是提议与它交谈。"}},faq={{q="为什么必须把玛格·夜眼的头颅送到荆棘谷？",a="纳泽尔·血矛说，只有巨魔的巫术才能查明玛格死亡前后发生的事，而肯维雷就在格罗姆高营地。",al={"为什么去荆棘谷","为什么去格罗姆高","为什么找肯维雷"}},{q="肯维雷是谁？",a="暗矛巨魔中最强大的巫医，就在荆棘谷的格罗姆高营地。",al={"巫医是谁","巫医肯维雷"}},{q="这一步之后是什么？",a="下一步是玛尔格的嘱托。",al={"下一个任务是什么","巨魔巫医之后"}}},fp="21,168,25.324.0,17.212.1,61.158.0,18.136.0,27.23.0"}
P.entries["quest:1241"] = {n="失踪的使节",s="一名外交官未能抵达塞拉摩岛，暴风城随即展开紧急调查。德拉维主教怀疑是迪菲亚暗中作祟，便派出信任的密探，去找英雄谷中行事低调的联络人乔贞。",h="一名外交官未能抵达塞拉摩岛，暴风城随即展开紧急调查。德拉维主教怀疑是迪菲亚暗中作祟，便派出信任的密探，去找英雄谷中行事低调的联络人乔贞。",kw={"迪菲亚","德拉维","吉安娜","乔贞","失踪的外交官","暴风城","塞拉摩","英雄谷"},ang={["class:Priest"]="当王室的常规渠道可能已被渗透时，德拉维主教便利用教会的人脉，秘密调查危及王国的罪行。",["class:Rogue"]="乔贞是一名资深联络人，他行事低调，有助于通过暴风城整洁街道之下的地下谍报活动，追查失踪使节的下落。",["faction:Alliance"]="这名王室外交官的失踪，使暴风城与吉安娜·普罗德摩尔在塞拉摩的据点之间的微妙谈判陷入危机。",["race:Human"]="迪菲亚潜行者的威胁已越过西部荒野，伸入王都，危及人类王国的稳定。"},sec={{t="暗影中的失踪",b="一名高级外交官从东部王国启航，前往塞拉摩岛与吉安娜·普罗德摩尔会面，进行敏感的会谈。这名外交官始终没有抵达。王室调查员正在暴风城搜寻线索。失踪的消息仍被严密封锁，以免引发恐慌，也防止阴谋者察觉王室已在监视他们。"},{t="秘密查访",b="德拉维主教认为，是迪菲亚潜行者绑架了这名外交官，但他并不只依靠国王的卫兵。他转而求助于行事隐秘的联络人，并找到了旧识乔贞，后者平日低调地在英雄谷钓鱼。乔贞就在城门内侧。"},{t="不情愿的线人",b="乔贞态度粗鲁，在城中水边守着一个不起眼的位置，却仍信守对德拉维的旧日承诺。他警告说，追查这名外交官的行踪可能招来杀身之祸。任何卷入调查的人都必须保持沉默。"}},faq={{q="失踪的外交官是谁？",a="圣光教会和暴风城王室严守这名外交官的身份。他们只说，这是一名奉命横渡无尽之海、前往塞拉摩的重要外交官。",al={"失踪外交官的身份","谁失踪了","谁消失了","外交官的身份"}},{q="这名外交官为何前往塞拉摩？",a="这名外交官奉命与吉安娜·普罗德摩尔会面，就联盟在东部王国与卡利姆多之间的安全与局势进行重要会谈。",al={"为何前往塞拉摩","外交官的目的","外交官在做什么"}},{q="德拉维主教怀疑谁？",a="德拉维主教怀疑迪菲亚潜行者绑架了这名外交官。他们使用的手段，以及城中的同谋，目前都还不清楚。",al={"谁带走了外交官","德拉维怀疑谁","谁绑架了外交官"}},{q="乔贞是谁？",a="乔贞是一名密探，也是德拉维主教多年的私人联络人。他在暴风城英雄谷钓鱼，就在城门内侧。",al={"乔贞在哪里","乔贞的身份","渔夫是谁"}},{q="为何要向公众隐瞒此事？",a="当局封锁了消息，因为一名重要使节在王室眼皮底下遭到绑架，一旦传开，可能引发混乱。这也可能让阴谋者警觉，知道王室密探正在追捕他们。",al={"为何保密","为何隐瞒此事","为何不告知城中居民"}},{q="调查将指向何处？",a="乔贞将调查引向暴风城的地下势力与秘密网络，以查明这名外交官在何处遭到拦截。",al={"接下来会发生什么","找过乔贞后去哪里"}}},fx={["02dad4d3"]={q="德拉维主教为什么需要冒险者，而不是皇家卫兵？",a="国王的密探已经在暴风城四处搜寻，但德拉维主教更愿意避开王室的正式监管，通过自己的隐秘渠道展开调查。将信件托付给私人信使，就能让乔贞这样的独立联系人参与其中，既不引起公众注意，也不惊动城内的阴谋者。",al={"失踪的使节为何选我","失踪的使节为何不派城内卫兵","德拉维主教为何选我"}}},fp="20,213,26.310.0,17.285.0,21.223.1,28.163.0,44.158.0,32.127.0,14.144.0,46.205.0,35.125.0"}
P.entries["quest:1242"] = {n="失踪的使节",s="乔贞派遣信得过的干员穿过暴风城，将一封密信送给埃林·提亚斯。从英雄谷到贸易区的提亚斯奶酪坊，这次送信让寻找失踪使节的行动得以继续。",h="乔贞派遣信得过的干员穿过暴风城，将一封密信送给埃林·提亚斯。从英雄谷到贸易区的提亚斯奶酪坊，这次送信让寻找失踪使节的行动得以继续。",kw={"埃林·提亚斯","乔贞","失踪的使节","密信","暴风城","贸易区","提亚斯奶酪坊"},ang={["class:Rogue"]="身为潜行者，你也许会怀疑提亚斯奶酪坊并非只是一家乳制品商店。店主暗中维系的人脉，远远超出了贸易区。",["faction:Alliance"]="身为联盟的一员，你能看到，秘密寻找失踪使节的行动如何揭示出暴风城领导层不易察觉的弱点。"},sec={{t="秘密送信",b="在对使节失踪一事进行初步调查后，乔贞要求信得过的干员保持沉默，带着一封密信穿过暴风城。信要送往贸易区的提亚斯奶酪坊，而非兵营或地方官的办公室。随着忧虑蔓延到王宫之外，这次交接避开了常规的卫兵渠道。"},{t="店面背后",b="埃林·提亚斯是提亚斯奶酪坊一位开朗勤劳的奶酪商，也是备受尊敬的商人。他与乔贞的关系以及他自己的人脉，都不局限于这家店铺。乔贞的信一到，提亚斯便悄悄接手了寻找失踪使节的事。"}},faq={{q="埃林·提亚斯是谁？",a="埃林·提亚斯是一位备受尊敬的商人，在暴风城的贸易区经营提亚斯奶酪坊。他与乔贞有旧交，也有人脉可以处理敏感事务。",al={"提亚斯是谁","奶酪商人","埃林·提亚斯的身份"}},{q="乔贞为什么让我保持沉默？",a="乔贞要求保持沉默，因为使节失踪一事属于国家机密。消息一旦传开，可能引发恐慌，也可能惊动策划绑架的人，让他们知道调查已经展开。",al={"为何保持沉默","乔贞的警告","闭紧嘴巴"}},{q="在哪里能找到提亚斯奶酪坊？",a="提亚斯奶酪坊位于暴风城的贸易区，坐落在商人与工匠聚集的主干道旁。",al={"提亚斯的位置","奶酪店位置","埃林·提亚斯在哪里"}},{q="给埃林的密信里写了什么？",a="乔贞的密信向埃林·提亚斯说明了使节失踪一事，请他动用人脉和地下耳目，寻找常规当局无法追查的线索。",al={"密信内容","信里写了什么","给埃林的密信"}},{q="任务中提到的失踪使节是谁？",a="王室在这个阶段仍对使节的身份保密。这种保密与忧虑表明，此人对暴风城王国具有极其重要的政治意义。",al={"谁失踪了","使节是谁","失踪者身份"}},{q="为什么调查要找一位奶酪商，而不是城里的卫兵？",a="城里的卫兵受到规章、管辖权限和政治关系的约束。埃林·提亚斯却能探听街头传言，联络那些士兵接触不到的秘密线人。",al={"为何找奶酪商","为何找提亚斯而非卫兵","卫兵与提亚斯的区别"}}},fx={c433039c={q="乔贞为什么要将这封信送给埃林·提亚斯？",a="乔贞知道，寻找失踪的外交官是一件敏感而隐秘的事，远远超出了一名普通外勤人员的能力范围。埃林·提亚斯看起来只是贸易区的一名普通奶酪商，却掌握着调查所必需的地下人脉与情报。乔贞需要将调查结果安全地交到提亚斯手中，同时不惊动任何暗中监视的人。",al={"为何送信给埃林·提亚斯","乔贞在失踪的使节中的动机","为何送密封的便笺"}}},fp="20,209,19.323.0,20.260.1,20.161.0,38.190.0,31.106.0,37.171.0,51.169.0,73.156.0"}
P.entries["quest:1243"] = {n="失踪的使节",s="埃林·提亚斯派你从暴风城南下，打听失踪使节的消息。他的线索指向暮色森林和守夜人巴库斯，后者是夜色镇附近的一名联络人，或许了解迪菲亚的动向。",h="埃林·提亚斯派你从暴风城南下，打听失踪使节的消息。他的线索指向暮色森林和守夜人巴库斯，后者是夜色镇附近的一名联络人，或许了解迪菲亚的动向。",kw={"夜色镇","迪菲亚","暮色森林","埃林·提亚斯","乔贞","失踪的使节","守夜人","守夜人巴库斯"},ang={["class:Rogue"]="身为潜行者，你看得出埃林·提亚斯如何借助人脉行事。他依靠独立行动的底层人手搜集情报，同时让自己置身事外。",["faction:Alliance"]="身为联盟的英雄，你协助追查一桩牵涉暴风城王室利益的失踪案。这场搜寻将王室间谍首领、独立行事的恶棍和各地民兵联系到了一起。"},sec={{t="幽暗中的奔走",b="与乔贞的一番交涉令人沮丧，奶酪商埃林·提亚斯于是转向他更广泛的线人网络。为了省下自己的钱，他没有雇用密探，而是派你前去实地调查。你带着一封密封信函越过边界，进入暮色森林，那里的野兽和亡灵让旅途危机四伏。"},{t="守夜人中的知心人",b="守夜人巴库斯是守夜人的一员，在夜色镇北面的入口一带巡逻。提亚斯信任他，靠他通报暮色森林中的非法动向。向巴库斯出示密封公函，他就能分享卫兵的记录和当地有关迪菲亚潜行者在南方活动的传闻。"}},faq={{q="埃林·提亚斯为什么派我去暮色森林？",a="埃林·提亚斯正在追查失踪使节的线索，以及疑似迪菲亚潜行者的活动。为了利用自己的人脉，又不花钱雇用密探，他派你去向守夜人巴库斯打听暮色森林的情况。",al={"为什么去暮色森林","提亚斯暮色森林差事","为什么去夜色镇"}},{q="在哪里能找到守夜人巴库斯？",a="守夜人巴库斯在暮色森林夜色镇外的北面土路上巡逻，那条路通往赤脊山和艾尔文森林。",al={"守夜人巴库斯位置","巴库斯在哪里","寻找巴库斯"}},{q="守夜人巴库斯是谁？",a="守夜人巴库斯是夜色镇民兵组织守夜人的一名士兵。他与埃林·提亚斯私交甚笃，会向他透露自己目睹的可疑旅人和罪犯的动向。",al={"巴库斯背景故事","巴库斯是谁"}},{q="交给巴库斯的密封信里写了什么？",a="埃林·提亚斯在密封信中请守夜人巴库斯提供情报，了解当地是否有人目击迪菲亚潜行者，以及他们穿行暮色森林的动向。",al={"密封信内容","信里写了什么","给守夜人巴库斯的密信"}},{q="暮色森林与迪菲亚潜行者有什么关系？",a="迪菲亚潜行者以西部荒野为中心，藏身于死亡矿井之下。他们的小股势力、信使和藏身处也遍布人类南方诸省，包括暮色森林阴暗的边缘地带。",al={"暮色森林的迪菲亚","暮色森林有迪菲亚吗"}},{q="提亚斯为什么抱怨乔贞？",a="调查期间，乔贞要么对提亚斯百般推诿，要么在交涉中寸步不让。提亚斯恼怒至极，咒骂乔贞滚到扭曲虚空去，随后才转向其他在外活动的联络人。",al={"乔贞是谁","提亚斯与乔贞"}}},fx={["8b2965b1"]={q="埃林·提亚斯为什么想办成这件事？",a="埃林·提亚斯看似只是个不起眼的奶酪大师，却拥有广泛的人脉，也答应调查那位外交官的失踪案。任何迪菲亚潜行者涉案的迹象，都可能成为破案的关键，所以他让你前往暮色森林追查，自己则在城里向线人打探消息。",al={"提亚斯为何关心此事","提亚斯的动机","埃林·提亚斯的动机"}},c3fdc8e2={q="埃林·提亚斯为什么让你四处奔走，而不亲自出马？",a="提亚斯毫不掩饰自己的务实打算：派一名冒险者办事，既能省下一大笔钱，也能让他腾出手来，联络暴风城中那些隐秘的人脉。一位声名显赫的商人走进阴森的暮色森林，会引来不必要的注意，而四处行走的调查者却能悄悄向守夜人巴库斯这样的当地卫兵追问，不惊动迪菲亚的眼线。",al={"为何派我去","提亚斯为何需要我","为何不亲自去"}}},fp="20,191,21.306.0,33.283.0,43.217.0,32.131.0,22.179.0,43.142.0,58.201.0,37.189.0"}
P.entries["quest:1244"] = {n="失踪的使节",s="守夜人巴库斯将寻找暴风城失踪使节的调查带到了暮色森林。一群迪菲亚匪徒曾在腐草农场聚集，或许能从中找到线索。",h="守夜人巴库斯将寻找暴风城失踪使节的调查带到了暮色森林。一群迪菲亚匪徒曾在腐草农场聚集，或许能从中找到线索。",kw={"腐草农场","迪菲亚记事本","暮色森林","小箱子","守夜人","失踪的使节","守夜人巴库斯"},ang={["class:Rogue"]="身为潜行者，你必须周旋于犯罪网络之中，分辨真正的情报与迪菲亚的误导。",["faction:Alliance"]="暴风城使节的失踪危及王国的安全。迪菲亚的阴谋远不止在西部荒野拦路抢劫。"},sec={{t="幽暗中的线索",b="守夜人的守夜人巴库斯指引你来到暮色森林。几周前，一群人数异常众多的迪菲亚匪徒来到了腐草农场。他们通常只在边境另一侧的西部荒野活动，因此他们出现在幽暗的森林中，是个令人不安的变化。现在，你要搜查这座废弃的农场，寻找他们留下的文件。"},{t="迪菲亚记事本",b="在被占据的农场里，你找到了一只上锁的小箱子，里面放着迪菲亚记事本。这些文件表明，兄弟会参与了此事。然而，守夜人巴库斯提醒你，这些文件可能是迪菲亚为误导调查者而伪造的。"}},faq={{q="腐草农场在哪里？",a="腐草农场位于暮色森林西部，就在从西部荒野通来的大路南侧。敌对的迪菲亚成员占据着破败的农舍。",al={"腐草农场位置","腐草农场在哪里","寻找腐草农场"}},{q="迪菲亚记事本是什么？",a="迪菲亚记事本是一批看似正式的文件，存放在腐草农场的一只小箱子里。其中详细记载了兄弟会近期在这一带开展的一些秘密行动。",al={"迪菲亚记事本","记事本是什么","腐草农场文件"}},{q="守夜人巴库斯是谁？",a="守夜人巴库斯隶属于驻守暮色森林的守夜人。他在镇上的人脉，以及对边境威胁的监视，帮助他追踪西部荒野边境沿线迪菲亚的异常动向。",al={"守夜人巴库斯","巴库斯是谁","巴库斯 暮色森林"}},{q="迪菲亚为什么在暮色森林境内活动？",a="迪菲亚的据点虽然位于边境另一侧的西部荒野，其成员却悄悄潜入暮色森林西部。腐草农场是一处偏僻的中转点，远离暴风城巡逻队的巡逻范围。",al={"迪菲亚为什么在暮色森林","腐草农场的迪菲亚"}},{q="迪菲亚记事本的内容可信吗？",a="守夜人巴库斯提醒你，迪菲亚可能故意留下了假线索，让调查者偏离追踪方向。记事本看起来是真的，但其中的内容可能会误导调查。",al={"记事本是真的吗","记事本伪造","是骗局吗"}},{q="最初是谁指引调查者去找守夜人巴库斯的？",a="守夜人巴库斯说，是埃林·提亚斯将调查引向了暮色森林的守夜人。提亚斯是暴风城的一名奶酪商人，也在暗中从事情报交易。",al={"谁派我去找巴库斯","提亚斯的关联"}}},fx={["860270d2"]={q="守夜人巴库斯为什么派你去腐草农场？",a="守夜人巴库斯认为，只要迪菲亚出现在暮色森林，就会威胁夜色镇的边境，即使他们暂时没有动静也是如此。大约两周前，他们的密探在腐草农场举行了一次不同寻常的集会，引起了守夜人的注意。巴库斯怀疑那里发生过大事，因此，要调查这个组织的秘密行动，那里就是最有希望找到线索的地方。",al={"巴库斯为何想办成此事","守夜人巴库斯的动机","为何调查腐草农场"}}},fp="20,151,19.342.0,17.221.1,31.137.0,26.172.0,22.179.0,41.191.0,49.163.0,59.162.0"}
P.entries["quest:1245"] = {n="失踪的使节",s="你将找回的迪菲亚记事本带到暴风城，而寻找失踪使节的行动也变得更加危险。",h="你将找回的迪菲亚记事本带到暴风城，而寻找失踪使节的行动也变得更加危险。",kw={"迪菲亚记事本","暮色森林","埃林·提亚斯","铁拳","失踪的使节","暴风城","守夜人巴库斯"},ang={["class:Rogue"]="埃林·提亚斯展示了潜行者如何以情报网取代匕首来施展本领。身为潜行者，你亲眼见证一位间谍首领在王室的暗战中破解迪菲亚潜行者的密文。",["faction:Alliance"]="身为联盟的一员，你看到了自第三次大战以来，暴风城的安防已被侵蚀到何种地步。迪菲亚潜行者的计划正从内部威胁着王国。"},sec={{t="守夜人难以承受之重",b="暮色森林的守夜人巴库斯不想与你找回的迪菲亚记事本有任何牵连。其中的文件详述了一系列计划，其复杂程度远非普通劫掠或佯攻可比。巴库斯害怕受到王室惩处，也对守夜人的上司心存戒备，因此请你不要透露他曾参与此事。这些阴谋可能断送前程，甚至夺人性命，于是你带着文件前往暴风城。"},{t="奶酪商的真正行当",b="在暴风城的贸易区，奶酪大师埃林·提亚斯见你归来，便卸下了店主的伪装。他以王国秘密情报网联络人的身份，仔细研究这本记事本。文件揭示了迪菲亚潜行者的周密部署，还提到了一个不祥的代号：“拳头”。失踪的使节遭到了一个关系盘根错节的组织的针对，其势力深入王国内部。"}},faq={{q="迪菲亚记事本是什么？",a="迪菲亚记事本是你在暮色森林找回的一批机密文件。它记载了迪菲亚潜行者的计划，其复杂程度令当地守夜人胆寒，也为提亚斯大师寻找失踪使节提供了新的线索。",al={"迪菲亚记事本","文件是什么","记事本内容"}},{q="守夜人巴库斯为何如此害怕保管记事本？",a="守夜人巴库斯担心，记事本中的情报超出了暮色森林一名守夜人成员的职权范围。他害怕自己的指挥官或暴风城的上级得知他经手或扣留了这类情报，可能会以叛国罪将他绞死。",al={"巴库斯为何害怕","守夜人巴库斯的恐惧"}},{q="为什么要把文件交给暴风城的奶酪店老板？",a="埃林·提亚斯表面上是个奶酪商，实际上却是暴风城的间谍首领，也是王国秘密情报网中的关键人物。他的见识和人脉有助于他解读迪菲亚潜行者的计划。",al={"为何找埃林·提亚斯","提亚斯为何卖奶酪"}},{q="记事本中提到的“铁拳”是谁？",a="埃林·提亚斯认出“铁拳”是一个代号，此人与迪菲亚潜行者协调绑架阴谋的行动有关。",al={"石拳是谁","石拳与迪菲亚潜行者","石拳代号"}},{q="调查接下来会通向何处？",a="记事本中的细节让提亚斯得以继续追查这些密谋者。他派你去询问线人，并追查“铁拳”，以查明使节被带到了哪里。",al={"下一步","拿到记事本之后","接下来去哪里"}},{q="这与瓦里安·乌瑞恩国王有什么关系？",a="记事本没有提到瓦里安·乌瑞恩国王。你正在寻找一位姓名不详、始终未能抵达塞拉摩的使节，而提亚斯对文件的解读也没有揭示目标的身份。",al={"瓦里安是使节吗","与瓦里安国王的关联"}}},fx={["74ee0470"]={q="守夜人巴库斯为什么需要你帮忙，而不亲自送去记事本？",a="守夜人巴库斯对迪菲亚记事本里的内容惶恐不已。身为守夜人的一员，他有义务向指挥官报告涉及国家的事务，但他知道，绕过官方渠道处理叛国阴谋的文件，可能会让自己丧命。他担心，如果上级发现他掌握这些情报却隐瞒不报，他就会被送上绞刑架。你是一名已经在与提亚斯合作的独立调查者，既能让巴库斯摆脱这场致命的阴谋，又能确保文件送到有能力解读它们的人手中。",al={"为何找我","巴库斯为何不送记事本","为何派我去找提亚斯"}}},fp="20,113,29.338.0,27.390.1,26.232.0,51.225.0,56.198.0,38.125.0,40.153.0,49.190.1"}
P.entries["quest:1246"] = {n="失踪的使节",s="在旧城区，埃林·提亚斯派你追查一个与使节失踪案有关的人。达舍尔·石拳或许知道那些可疑文件的更多内情，而调查将深入暴风城险恶的街巷。",h="在旧城区，埃林·提亚斯派你追查一个与使节失踪案有关的人。达舍尔·石拳或许知道那些可疑文件的更多内情，而调查将深入暴风城险恶的街巷。",kw={"达舍尔·石拳","埃林·提亚斯","铁拳","失踪的使节","旧城区","暴风城"},ang={["class:Rogue"]="身为潜行者，你在旧城区如鱼得水，周围有提亚斯这样的线人，也有石拳这样的凶恶打手。",["faction:Alliance"]="身为联盟的一员，你知道，揭开使节失踪背后的阴谋，关系到联盟的稳定，也关系到作为其核心的王国。",["race:Human"]="身为暴风城的人类，你看到了令人不安的证据：当地的街头败类正在协助针对王国统治者的叛国阴谋。"},sec={{t="旧城区的线索",b="埃林·提亚斯想起，绰号拳头的达舍尔·石拳也在那些与密文便笺和线索有关的人名之中。石拳是个粗暴的街头打手，常在旧城区狭窄的巷子里活动。为了找到他，调查从暴风要塞的宏伟厅堂转向了城中的犯罪圈子。"},{t="用拳头说话",b="埃林·提亚斯提醒你，达舍尔·石拳不会轻易向好奇的陌生人开口，尤其当事情涉及叛国和绑架时。提亚斯说，如果问话不管用，就得靠武力让他开口。石拳把那些小巷视作自己的地盘。他厌恶外人打探那些可能让他丢掉生计甚至性命的事。"}},faq={{q="达舍尔·石拳是谁？",a="达舍尔·石拳是个臭名昭著的打手，经常出没于暴风城旧城区中央的巷子。提亚斯认为，他与追查失踪使节时发现的罪证文件有关。",al={"达舍尔·石拳","石拳是谁","达舍尔"}},{q="在哪里能找到达舍尔·石拳？",a="达舍尔·石拳在旧城区中心附近的露天小巷中徘徊，远离主要街道。",al={"达舍尔·石拳位置","达舍尔在哪","石拳在哪"}},{q="埃林·提亚斯为什么派我去找他？",a="提亚斯认为，达舍尔的名字与那些涉及国王使节失踪的文件有关。达舍尔或许知道与绑架主谋有关的人名、地点或命令。",al={"为什么要打达舍尔","提亚斯的理由"}},{q="达舍尔会主动配合吗？",a="不会。石拳对插手自己事务的陌生人充满敌意。提亚斯料到他会反抗，建议你用武器或拳头让他开口。",al={"达舍尔会开口吗","石拳是否友善"}},{q="找到达舍尔之后会发生什么？",a="与达舍尔对质会引发一场斗殴。被制服后，他会向你提供使节绑架案背后关系网的线索，并指出王国内其他同谋的追查方向。",al={"失踪使节下一步","达舍尔之后做什么"}},{q="任务中提到的失踪使节是谁？",a="暴风城当局只说，一名未透露姓名的使节在前往塞拉摩会见吉安娜·普罗德摩尔的途中失踪。在调查的这一阶段，这名使节的身份仍是严守的秘密。",al={"失踪的使节是谁","哪位使节"}}},fx={["8d360f6b"]={q="埃林·提亚斯为什么派你去，而不派城里的卫兵？",a="埃林办事依靠秘密、传闻和微妙的政治关系，而不是公开行使权力。一位重要外交官失踪，足以引发轩然大波，若让暴风城的卫兵介入，就会引起民众恐慌，也会让密谋者察觉到有人正在追查他们。提亚斯需要一名独立调查者，能悄悄穿行于旧城区的后巷，打听危险的消息，必要时动用拳头，又不会招来执法者的强硬干预和大张旗鼓的关注。",al={"为何派我去","为何不派暴风城卫兵","为何不派城里的卫兵"}}},fp="20,198,18.280.0,22.325.1,24.189.0,34.104.0,41.163.0,32.155.0,34.175.1,51.215.2"}
P.entries["quest:1247"] = {n="失踪的使节",s="在旧城区，达舍尔·石拳供出了一条要转告埃林·提亚斯的警讯。他的供词提到了一项备用绑架计划，以及米奈希尔港的一名接头人。",h="在旧城区，达舍尔·石拳供出了一条要转告埃林·提亚斯的警讯。他的供词提到了一项备用绑架计划，以及米奈希尔港的一名接头人。",kw={"腐草农场","达舍尔·石拳","埃林·提亚斯","米奈希尔港","失踪的外交官","干柴","暴风城"},ang={["class:Rogue"]="身为潜行者，你知道街头犯罪与国家机密之间的联系能有多紧密。达舍尔在暗巷中充当打手，提亚斯则在暗中从事情报工作。",["faction:Alliance"]="身为联盟的一员，你知道失踪的使节关系到联盟的稳定。破坏行动威胁着暴风城的统治。",["race:Human"]="身为人类，你看到年幼的国王端坐王座之时，一场阴谋正在暴风城境内展开。"},sec={{t="墙上的裂隙",b="达舍尔·石拳担心自己皮肉受苦，终于屈服了。在旧城区的一条小巷里，他承认，密谋者绑架使节的最初计划失败了，他负责的那一环也出了岔子。为了推卸责任，他告诉你，几周前有人在暮色森林的腐草农场秘密碰面。他还供出了备用计划的一条线索：米奈希尔港的一名内应，只知道名叫干柴。"},{t="向奶酪师汇报",b="埃林·提亚斯在贸易区的提亚斯奶酪坊柜台后，为王室搜集情报。你盘问达舍尔的时候，提亚斯研究了截获的、与这场阴谋有关的信件。达舍尔的供词与信件透露的情况相符：密谋者盯上了一名身份不明的外交官，第一次伏击失败后，他们又开始经由湿地实施备用计划。有了干柴这个名字，调查便从暴风城转向北方的沼泽。"}},faq={{q="达舍尔·石拳是谁？",a="达舍尔·石拳是暴风城旧城区的一名掮客兼打手。他与迪菲亚的地下势力有牵连，曾参与执行最初抓捕暴风城使节的计划。受到逼问后，他供出了情报。",al={"达舍尔·石拳","达舍尔是谁","石拳 暴风城"}},{q="埃林·提亚斯为什么参与这项调查？",a="埃林·提亚斯以精通上等奶酪的大师身份为掩护，为暴风城搜集情报。他在贸易区的店铺，让他得以暗中协调调查，触及城市卫兵无从查探的地方。",al={"为什么是埃林·提亚斯","奶酪商人 间谍","提亚斯 情报"}},{q="腐草农场发生了什么？",a="几周前，密谋者在暮色森林西部的废弃农场腐草农场碰面，筹划第一次行动受挫后的绑架事宜。",al={"腐草农场 密会","腐草农场","西部荒野 密会"}},{q="他们企图绑架的外交官是谁？",a="密谋者的文件和街头打手只透露，目标是一名准备前往塞拉摩的外交官，并未提及姓名。在调查的这个阶段，使节的身份仍被严密保守。",al={"失踪的外交官是谁","谁被绑架了","外交官的身份"}},{q="干柴是谁？",a="达舍尔·石拳供称，干柴是负责从湿地的米奈希尔港安排备用计划的接头人。这名接头人负责密谋者运送人员和物资的第二条路线。",al={"干柴是谁","干柴 米奈希尔港","米奈希尔港 接头人"}},{q="接下来的线索指向哪里？",a="线索指向北方湿地的米奈希尔港，据说干柴就在那里。埃林·提亚斯证实了达舍尔提供的情报。",al={"失踪的外交官 下一步","达舍尔之后去哪里","接下来做什么"}}},fx={a7b1abaf={q="达舍尔·石拳为什么现在肯开口了？",a="达舍尔肯开口，只是因为你刚刚把他打得屈服了。意识到手下的打手护不住自己后，他便急着保命，供出自己对这场阴谋的备用计划所知的那点消息，好把你的注意力从自己身上引开。",al={"达舍尔为何开口","达舍尔·石拳的动机","达舍尔为何招供"}}},fp="20,145,19.357.0,25.433.1,24.206.0,51.185.0,31.155.0,47.196.2,12.204.0,37.127.0"}
P.entries["quest:1248"] = {n="失踪的使节",s="你循着一名遭绑架的暴风城外交官留下的线索，来到米奈希尔港。一份截获的公文证实了绑架一事，却没有透露外交官的身份，也未说明密谋者的目的地。",h="你循着一名遭绑架的暴风城外交官留下的线索，来到米奈希尔港。一份截获的公文证实了绑架一事，却没有透露外交官的身份，也未说明密谋者的目的地。",kw={"公文","米奈希尔港","米克哈尔","干柴","暴风城","失踪的使节","提亚斯","湿地"},ang={["class:Rogue"]="身为潜行者，你可以运用隐秘的技巧，解读秘密公文，寻找退休的接头人，并在拥挤的酒馆里悄悄盘问嫌疑人。",["faction:Alliance"]="这名外交官遭绑架一事，牵涉暴风城的高层安全，也牵涉遍布联盟领地的密谋者势力。"},sec={{t="通往湿地的线索",b="你手中有一份公文，证实一名外交官从暴风城遭人劫走。公文既未提及外交官的姓名，也未说明密谋者的目的地。于是，线索引你走出暴风城的大门，前往湿地的米奈希尔港，在港口的人群和暗中交易里寻找头绪。"},{t="米奈希尔的秘密接头",b="米克哈尔曾是埃林·提亚斯的伙伴，几年前离开暴风城退休，如今在米奈希尔的酒馆工作。你找他是为了找到干柴，此人或许知道俘虏被带去了哪里，或是谁安排了这场绑架。\n\n在拥挤的酒馆里，行事必须谨慎。你一提起提亚斯的名字，米克哈尔就催促你立刻噤声，以免密谋者注意到你的打探。"}},faq={{q="米克哈尔是谁？",a="米克哈尔曾是埃林·提亚斯的伙伴，几年前离开暴风城，到米奈希尔港退休。他如今在那里担任酒保，提亚斯指引你去找他，说他是值得信赖的接头人，能帮忙找到干柴。",al={"米克哈尔是谁","米克哈尔 湿地","米奈希尔 酒保"}},{q="干柴是谁，为什么要找他？",a="干柴是米奈希尔港的一个人物，据说知道一些外交官遭绑架的内情。米克哈尔能帮你找到干柴，打听此人知道些什么。",al={"干柴是谁","寻找干柴","失踪的使节 干柴"}},{q="遭绑架的外交官是谁？",a="遭绑架的外交官身份仍不明确，就连调查者也不知情。截获的公文证实了绑架一事，却没有提及外交官的身份，也未说明密谋者得手后的计划。",al={"谁遭到绑架","遭绑架的外交官身份","失踪的外交官是谁"}},{q="为什么线索指向米奈希尔港？",a="线索指向米奈希尔港，是因为埃林·提亚斯已经退休的接头人米克哈尔在那里担任酒保。这座港口城镇坐落在湿地海岸，有关绑架案的线索在此流转。",al={"米奈希尔港在哪里","为什么是湿地","为什么去米奈希尔"}},{q="公文透露了哪些阴谋内情？",a="截获的公文证实了外交官遭绑架一事，却没有说明俘虏被带去了哪里，也未提及绑架者接下来打算做什么。",al={"什么公文","提亚斯 公文","公文写了什么"}},{q="提亚斯在这项任务中扮演什么角色？",a="埃林·提亚斯在暴风城指挥调查。他派你去找他的老伙伴米克哈尔，此人承诺，只凭提亚斯的一句话就会提供帮助，而且不会引起公众注意。",al={"谁派我们去找米克哈尔","提亚斯的关联","为什么提起提亚斯"}}},fp="20,197,23.285.0,29.369.1,15.225.0,45.149.0,30.211.0,43.201.0,43.141.0,44.179.0"}
P.entries["quest:1249"] = {n="失踪的使节",s="暴风城的使者失踪了，你循着线索，从首都一路追查到米奈希尔港。在那里，调查牵涉到了地下势力中的人物，以及与暴风城情报网有关的密探。",h="暴风城的使者失踪了，你循着线索，从首都一路追查到米奈希尔港。在那里，调查牵涉到了地下势力中的人物，以及与暴风城情报网有关的密探。",kw={"埃林·提亚斯","米奈希尔港","失踪的外交官","干柴","暴风城","失踪的使节","湿地"},ang={["class:Rogue"]="身为盗贼，你知道，像埃林·提亚斯这样的密探和情报负责人，要靠暗中走访和街头的人脉，才能找到那些漏网之人。",["faction:Alliance"]="身为联盟的冒险者，你循着失踪外交官的踪迹，踏入了一个将暴风城政界与湿地码头联系起来的地下世界。"},sec={{t="米奈希尔港的暗流",b="你循着暴风城失踪使者的踪迹，向北来到湿地的米奈希尔港。这里的码头和酒馆藏着可疑的交易者和秘密信使，就在当地守卫的眼皮底下活动。要在这座港口追查线索，你必须与熟悉联盟领地阴暗面的人打交道。"},{t="熟悉的盗贼",b="抓住干柴，让搜寻突然有了答案。当地的线人得知他卷入此事，都感到意外。他的落网为你带来了关键的答案，也勾起了湿地一些退休密探的旧日回忆。他们必须权衡，是帮助王室，还是冒着被重新卷入暴风城地下阴谋的风险。"}},faq={{q="干柴是谁？",a="干柴是米奈希尔港一个行踪可疑的接头人，你在寻找失踪外交官时抓住了他。当地的接头人得知他也参与其中，都感到意外。",al={"干柴是谁","干柴 失踪的使节","抓住干柴"}},{q="埃林是谁？",a="埃林·提亚斯是暴风城一位颇有影响力的人物，他维系着一个遍布联盟领地的地下网络，成员包括昔日的盗贼和线人。",al={"埃林·提亚斯","埃林是谁","埃林 暴风城"}},{q="这部分调查在哪里进行？",a="这部分调查在米奈希尔港进行，这座湿地港口将铁炉堡与遥远的海岸及暴风城的贸易航线连接起来。",al={"发生地点","米奈希尔港 失踪的使节","湿地 外交官"}},{q="失踪的使节系列任务讲述了什么？",a="你调查一位暴风城重要使者失踪的事件，追查秘密特工、阴谋策划者和地下接头人，足迹遍及王国境内外。",al={"失踪的使节是什么","失踪的使节任务","谁失踪了"}},{q="为什么接头人警告不要向埃林提起这件事？",a="米奈希尔港的一位接头人，曾在暴风城的地下圈子里与埃林·提亚斯共事。他不愿告诉埃林自己怀念过去的生活，生怕埃林会把他召回首都。",al={"为何提到埃林","提亚斯 奶酪","埃林·提亚斯的关联"}},{q="米奈希尔港的调查有了什么进展？",a="你循着线索来到湿地的米奈希尔港，抓住了干柴。这次遭遇证实了当地人对镇内地下非法活动的怀疑。",al={"米奈希尔港发生了什么","米奈希尔 线索","干柴被抓"}}},fp="20,205,32.304.0,16.330.1,12.156.0,14.143.0,53.144.0,47.164.0,60.198.0,56.151.0"}
P.entries["quest:125"] = {n="丢失的工具",s="黑石的炮火将工头奥斯洛的工具送入了止水湖底。湖畔镇面临重压，当地人必须维护防御工事，而重建断桥需要用到从闪金镇运来的工具。",h="黑石的炮火将工头奥斯洛的工具送入了止水湖底。湖畔镇面临重压，当地人必须维护防御工事，而重建断桥需要用到从闪金镇运来的工具。",kw={"投石车","工头奥斯洛","闪金镇","止水湖","湖畔镇","鱼人","赤脊山","蛇颈龙","工具箱"},ang={["faction:Alliance"]="身为联盟的旅人，你帮助湖畔镇抵御黑石氏族，守住东部边境。平民建筑工人需要他们的装备，才能维护暴风城王国的防御工事。",["profession:Blacksmithing"]="身为铁匠，你知道在围城之中很难锻造出优质工具。找回从闪金镇运来的专用锻造和建筑工具，对镇子至关重要。"},sec={{t="受挫的运输",b="大桥已无法连接湖畔镇与艾尔文森林。一批补充用的石工和木工工具从闪金镇经陆路运来，但货车无法抵达镇上。运输队将物资装上一艘划艇，准备横渡止水湖。黑石兽人的投石车击中了划艇，将船摧毁，奥斯洛那只沉重的包铁工具箱也落入了湖底。"},{t="深水中的危险",b="止水湖的水面之下潜藏着危险。凶悍的鱼人部族在浅水区游荡，捕食猎物的蛇颈龙则在浑浊的深水中狩猎。工头奥斯洛需要取回工具，才能继续修复桥梁，避免湖畔镇进一步陷入破败。"}},faq={{q="为什么最初要用船运送工具？",a="黑石兽人摧毁了止水湖上石桥的一大段桥身，因此闪金镇来的补给货车无法抵达湖畔镇。运输队卸下工具，试图用船将它们运过湖去。",al={"为何用船","工具如何沉没","为何经湖运输"}},{q="船是怎么沉的？",a="运输船横渡止水湖时，黑石兽人从周围的高地用投石车发射石弹，击中了船只。船连同货物一起沉入了湖底。",al={"谁摧毁了船","船如何被击中"}},{q="工头奥斯洛是谁？",a="工头奥斯洛是湖畔镇的首席建造师和监工，负责公共工程与市政维护。他眼下最紧迫的工作是重建断桥。",al={"工头奥斯洛","奥斯洛的职责"}},{q="止水湖里有哪些威胁？",a="敌对的鱼人部族在湖岸和废墟间巡逻，凶残的食肉蛇颈龙则在开阔水域和更深的水下捕猎。",al={"湖里有什么","湖中怪物","止水湖的危险"}},{q="湖畔镇为什么如此急需这些工具？",a="湖畔镇正遭到围攻，既无法及时获得援军，也收不到定期运来的补给。没有重型工具，奥斯洛就无法重建桥梁，也无法修复抵御兽人和豺狼人进攻所需的防御工事。",al={"工具为何重要","修桥工具"}},{q="接下来会接到什么任务？",a="找回工具箱后，工头奥斯洛会在任务止水湖上的桥中，请冒险者收集修复大桥所需的建筑原料。",al={"后续任务","丢失的工具之后"}}},fp="14,171,20.373.0,19.263.0,51.212.0,22.162.0,21.170.0,35.128.0,45.207.0,31.156.1"}
P.entries["quest:1250"] = {n="失踪的使节",s="贾恩说，迪菲亚趁国王的船停泊时，将他从船上劫走。在继续搜寻亨德尔的同时，你被派往湿地与米克哈尔交谈。",h="贾恩说，迪菲亚趁国王的船停泊时，将他从船上劫走。在继续搜寻亨德尔的同时，你被派往湿地与米克哈尔交谈。",kw={"迪菲亚","亨德尔","贾恩","吉安娜·普罗德摩尔","米克哈尔","暴风城国王","失踪的使节","塞拉摩","湿地"},sec={{t="证人的供述",b="贾恩说，迪菲亚趁国王的船停泊时，将一个名叫亨德尔的人安插到了船上。国王当时正要前往塞拉摩，会见吉安娜·普罗德摩尔。贾恩认为迪菲亚还有同伙，因此在开始搜寻亨德尔的同时，你被要求前往湿地与米克哈尔交谈。"},{t="米克哈尔的回应",b="米克哈尔得知国王失踪后大为震惊，随即向埃林传去了消息。他说，他从未想过贾恩会为了钱财背叛暴风城。尽管如此，米克哈尔仍愿意帮忙寻找亨德尔。"}},faq={{q="贾恩是谁？",a="贾恩是迪菲亚的一名共谋者，曾协助将亨德尔安插到国王的船上。",al={"贾恩 是谁","谁是 贾恩","迪菲亚 贾恩"}},{q="亨德尔是谁？",a="亨德尔就是贾恩所说的那个被他安插到国王船上的人。",al={"亨德尔 这个人","亨德尔 是谁","国王船上的人"}},{q="国王出了什么事？",a="贾恩说，迪菲亚趁国王的船停泊时，将他从船上劫走。",al={"国王在哪","暴风城国王失踪","国王被绑架"}},{q="国王为什么要去塞拉摩？",a="国王当时正在前往塞拉摩的途中，准备会见 吉安娜·普罗德摩尔。",al={"国王 塞拉摩","会见 吉安娜","为什么去塞拉摩"}},{q="贾恩说除了迪菲亚，还有谁参与其中？",a="贾恩认为迪菲亚还有同伙，但他说自己不知道对方是谁。",al={"谁与 迪菲亚 合作","迪菲亚 的同伙","还有谁参与"}},{q="米克哈尔是谁？",a="米克哈尔就是你被要求前往湿地交谈的人。他愿意帮忙寻找亨德尔。",al={"米克哈尔 湿地","米克哈尔 是谁","与 米克哈尔 交谈"}}},fp="20,145,16.285.0,18.191.1,12.74.0,14.61.0,26.69.0,36.62.0,49.81.0,15.97.0"}
P.entries["quest:1251"] = {n="黑色盾牌",s="树荫旅店已被烧成废墟，一座摇摇欲坠的烟囱是仅存的几处残迹之一。一面被火焰熏黑的盾牌固定在烟囱的砖墙上。该拿给蕨墙村的克罗格看看。",h="树荫旅店已被烧成废墟，一座摇摇欲坠的烟囱是仅存的几处残迹之一。一面被火焰熏黑的盾牌固定在烟囱的砖墙上。该拿给蕨墙村的克罗格看看。",kw={"黑色盾牌","被熏黑的铁盾牌","蕨墙村","尘泥沼泽","克罗格","树荫旅店"},sec={{t="烟囱上的盾牌",b="大火吞噬了树荫旅店，如今几乎只剩废墟。一面烧得焦黑的铁盾固定在摇摇欲坠的烟囱上，可以从砖墙上松动取下。该把它带给蕨墙村的克罗格，他会问这是否算是旅店废墟中的证据。"},{t="克罗格的看法",b="克罗格承认人类在装饰上的品味古怪，却不相信会有人把一面普通的铁盾挂在壁炉上方。克罗格怀疑是放火烧毁旅店的人把盾牌留在了那里，或许是为了警告或威胁。"}},faq={{q="黑色盾牌在哪里？",a="它固定在被烧毁的树荫旅店的烟囱上，那是这座建筑仅存的几处残迹之一。",al={"黑色盾牌位置","盾牌在哪","树荫旅店盾牌"}},{q="盾牌要交给谁？",a="该把它带给蕨墙村的克罗格。",al={"谁要黑色盾牌","盾牌交到哪里","克罗格位置"}},{q="能把盾牌从烟囱上取下来吗？",a="能，可以将它从烟囱的砖墙上松动取下。",al={"能否取下盾牌","从烟囱上取下盾牌"}}},fp="16,122,23.274.0,21.203.1,32.111.0,20.48.0,41.62.0"}
P.entries["quest:1252"] = {n="帕瓦尔·雷瑟上尉",s="瓦砾下有什么东西在闪光：那是一枚带有塞拉摩标志的徽章，白色珐琅上镶着金色船锚，船锚下压印着帕瓦尔·雷瑟上尉的名字。应该把它带给塞拉摩的盖兰·维米斯队长。",h="瓦砾下有什么东西在闪光：那是一枚带有塞拉摩标志的徽章，白色珐琅上镶着金色船锚，船锚下压印着帕瓦尔·雷瑟上尉的名字。应该把它带给塞拉摩的盖兰·维米斯队长。",kw={"尘泥沼泽","加瑞安·维米斯","帕瓦尔·雷瑟","树荫旅店","塞拉摩卫兵徽章"},sec={{t="瓦砾中的微光",b="瓦砾下有什么东西在闪光。拂去灰烬和碎屑，一枚带有塞拉摩标志的徽章显露出来，标志下方压印着帕瓦尔·雷瑟上尉的名字。应该让塞拉摩的盖兰·维米斯队长看看它，他会问起树荫旅店的废墟里发现了什么。"},{t="队长的答复",b="维米斯说，有人送来卫兵的徽章，从来都不是什么好消息。有些卫兵战死沙场，维米斯必须将噩耗带给他们悲痛的家人。还有些卫兵，始终无人知晓他们的下落，而有时真相甚至更加残酷。"}},faq={{q="徽章在哪里找到？",a="它埋在瓦砾下，沾满灰烬和碎屑。盖兰·维米斯队长会问起树荫旅店的废墟里发现了什么。",al={"徽章位置","雷瑟徽章在哪","树荫旅店徽章"}},{q="徽章上是谁的名字？",a="船锚下方压印的名字是帕瓦尔·雷瑟上尉。",al={"帕瓦尔·雷瑟是谁","徽章上的名字","谁丢了徽章"}},{q="徽章该交给谁？",a="应该让塞拉摩的盖兰·维米斯队长看看它。",al={"徽章交给谁","徽章在哪交","盖兰·维米斯队长位置"}},{q="徽章是什么样的？",a="白色珐琅上镶着金色船锚，那是塞拉摩的标志。",al={"塞拉摩标志","卫兵徽章外观","徽章是什么样的"}}},fp="23,156,21.219.0,19.217.1,25.123.0,27.62.0,19.55.0,30.66.0"}
P.entries["quest:1253"] = {n="黑色盾牌",s="一面被火熏黑的铁盾牌固定在被焚毁的树荫旅店那摇摇欲坠的烟囱上。塞拉摩的盖兰·维米斯队长正等待来自旅店现场的证据。",h="一面被火熏黑的铁盾牌固定在被焚毁的树荫旅店那摇摇欲坠的烟囱上。塞拉摩的盖兰·维米斯队长正等待来自旅店现场的证据。",kw={"黑色盾牌","烟囱","尘泥沼泽","加瑞安·维米斯","铁盾牌","树荫旅店","塞拉摩"},sec={{t="烟囱上的盾牌",b="树荫旅店被大火焚毁，一座摇摇欲坠的烟囱是少数仍然矗立的部分之一。一面被火熏黑的铁盾牌固定在烟囱的砖上，可以取下来。塞拉摩的盖兰·维米斯队长想要旅店现场的证据。"},{t="队长的判断",b="维米斯说，他不懂武器和护甲的制作，只懂如何使用它们。在队长看来，除了大火留下的损伤，这面盾牌和其他普通盾牌没什么两样。"}},faq={{q="黑色盾牌在哪里？",a="固定在摇摇欲坠的烟囱砖上，那座烟囱是被焚毁的树荫旅店中少数仍然矗立的部分之一。",al={"盾牌在哪","黑色盾牌位置","寻找黑色盾牌"}},{q="谁想要树荫旅店的证据？",a="塞拉摩的盖兰·维米斯队长，他正等待来自旅店废墟的证据。",al={"谁想要盾牌","树荫旅店调查员","盖兰·维米斯是谁"}}},fp="16,153,23.220.0,21.179.1,34.130.0,43.79.0"}
P.entries["quest:1258"] = {n="还有螃蟹！",s="摩根·斯特恩正在塞拉摩研究一道新菜，它或许会成为暴风城下一道风靡一时的美食。泥石的舌头已经到手，接下来，这道菜还需要巨蟹带壳的腿，而且必须完好无损，没有伤痕。",h="摩根·斯特恩正在塞拉摩研究一道新菜，它或许会成为暴风城下一道风靡一时的美食。泥石的舌头已经到手，接下来，这道菜还需要巨蟹带壳的腿，而且必须完好无损，没有伤痕。",kw={"蟹腿","尘泥沼泽","摩根·斯特恩","泥石龟蟹汤","完好无损的蟹腿","暴风城","塞拉摩","悲伤沼泽"},sec={{t="毫发无损的蟹腿",b="摩根·斯特恩希望把蟹腿的外壳作为这道菜摆盘的关键，因此每条腿都必须完好无损，没有伤痕。一只成年螃蟹可能只有一两条这样的腿，而研究需要大量这样的蟹腿。尘泥沼泽的污壳螃蟹不合要求。只有遥远的悲伤沼泽里的螃蟹才合适，因此还得远行一趟。"}},faq={{q="摩根·斯特恩是谁？",a="摩根·斯特恩正在塞拉摩研究一道新菜，它或许会成为暴风城下一道风靡一时的美食。",al={"摩根·斯特恩 是谁","摩根·斯特恩 塞拉摩","还有螃蟹 任务提供者"}},{q="蟹腿从哪里来？",a="不是尘泥沼泽，那里的污壳螃蟹不适合做这道菜。摩根·斯特恩指向了遥远的悲伤沼泽，那里才有合适的螃蟹。",al={"哪里能找到蟹腿","刺脊岩蟹 在哪里","蟹腿位置"}},{q="为什么蟹腿必须完好无损？",a="外壳是这道菜摆盘的关键，因此摩根·斯特恩要求蟹腿上不能有伤痕。",al={"为什么蟹腿必须完好无损","为什么蟹腿不能有伤痕","蟹腿摆盘"}},{q="这个任务的前置任务是什么？",a="它接续泥石龟蟹汤，那是你为摩根·斯特恩研究新菜所做的第一部分工作。",al={"还有螃蟹 前置任务","泥石龟蟹汤 前置条件"}}},fp="12,178,22.341.0,20.91.0,33.134.0,41.90.0,29.92.0"}
P.entries["quest:1259"] = {n="帕瓦尔·雷瑟上尉",s="盖兰·维米斯队长不认识帕瓦尔·雷瑟上尉这个名字，便派你去找塞拉摩的泰索兰副官，他负责保管塞拉摩卫兵的档案。",h="盖兰·维米斯队长不认识帕瓦尔·雷瑟上尉这个名字，便派你去找塞拉摩的泰索兰副官，他负责保管塞拉摩卫兵的档案。",kw={"泰索兰副官","盖兰·维米斯队长","尘泥沼泽","帕瓦尔·雷瑟","塞拉摩"},sec={{t="雷瑟是谁？",b="盖兰·维米斯队长想不起帕瓦尔·雷瑟上尉是谁。泰索兰副官保管着塞拉摩卫兵的档案，其中记录了卫兵的人员和装备情况，维米斯指望查阅这些档案能弄清雷瑟的身份。"}},faq={{q="谁派你去查明雷瑟的身份？",a="盖兰·维米斯队长，他不认识帕瓦尔·雷瑟上尉这个名字。",al={"谁提供帕瓦尔·雷瑟上尉任务","雷瑟任务给予者","谁提供雷瑟任务"}},{q="谁保管着塞拉摩卫兵的档案？",a="塞拉摩的泰索兰副官保管着这些档案，其中记录了卫兵的人员和装备情况。",al={"泰索兰副官在哪里","塞拉摩档案保管者","谁保管卫兵档案"}},{q="泰索兰副官能告诉你什么？",a="维米斯指望泰索兰保管的档案能揭示雷瑟的身份。",al={"泰索兰知道什么","泰索兰的档案"}}},fp="23,84,14.233.0,39.103.0,40.90.0,35.73.0"}
P.entries["quest:126"] = {n="群山中的嚎叫",s="豺狼人的嚎叫回荡在湖畔镇周围的山丘间，弗纳·奥斯古正在悬赏猎杀犹勒。暴风城的兵力因黑石兽人而捉襟见肘，镇民只能依靠外来的冒险者对付豺狼人。",h="豺狼人的嚎叫回荡在湖畔镇周围的山丘间，弗纳·奥斯古正在悬赏猎杀犹勒。暴风城的兵力因黑石兽人而捉襟见肘，镇民只能依靠外来的冒险者对付豺狼人。",kw={"黑石","豺狼人","湖畔镇","爪子","赤脊山","暴风城军队","弗纳·奥斯古","犹勒"},ang={["class:Hunter"]="身为猎人，你可以留意领地标记和群体活动的迹象，在犹勒的山中巢穴追踪他。",["class:Warrior"]="身为战士，你面对的犹勒凭借蛮力统治同类，必须以力量与他正面对抗。",["faction:Alliance"]="身为联盟冒险者，你能从湖畔镇对雇佣兵的依赖中，看出暴风城王国承受的压力正如何削弱它。"},sec={{t="高地上的嚎声",b="即使湖畔镇周围道路上的普通豺狼人已被赶走，豺狼人的嚎叫仍在赤脊山的山丘间回荡。镇上的蹄铁匠弗纳·奥斯古知道，只要首领还活着，这群豺狼人就会继续劫掠。犹勒是个体型庞大、狡猾的豺狼人，用嚎叫指挥山丘间的同类。弗纳要求带回犹勒的爪子，证明这个首领已被杀死，嚎叫也已平息。"},{t="被军队遗弃的城镇",b="暴风城东部边境的城镇面临危险，却几乎得不到王国军队的帮助。瓦里安·乌瑞恩国王失踪，围绕摄政权的争执使最高统帅部陷入瘫痪。王国士兵正全力应对北方的黑石兽人氏族，湖畔镇无人抵御豺狼人。弗纳·奥斯古这样的镇民只好自行设立悬赏，以免家园被攻占。"}},faq={{q="犹勒是谁？",a="犹勒统领着湖畔镇外山丘中的赤脊山豺狼人。弗纳说，他比普通豺狼人更强壮，也更危险，还指挥同类袭击旅人和农庄。",al={"犹勒","豺狼人首领是谁","犹勒背景故事","犹勒豺狼人"}},{q="为什么是弗纳·奥斯古发布这份悬赏，而不是镇上的卫兵？",a="弗纳·奥斯古发布悬赏，是因为湖畔镇的官员和民兵已被黑石兽人弄得焦头烂额。他是当地的工匠兼马厩管理员，生计有赖于道路畅通，因此雇用四处游历的雇佣兵应对眼前的危险。",al={"为什么是弗纳","为什么不是所罗门镇长","奥斯古为什么雇人"}},{q="本该保护湖畔镇的暴风城士兵在哪里？",a="暴风城的士兵正忙于别处的事务。军队驻扎在赤脊山，监视并牵制更深山中的黑石兽人氏族，湖畔镇因此得不到支援，只能自行应对当地的野兽、鱼人和豺狼人。",al={"军队在哪里","为什么没有暴风城卫兵","暴风城军队湖畔镇"}},{q="犹勒死后，赤脊山的豺狼人会怎样？",a="犹勒的死使豺狼人的指挥体系陷入混乱，削弱了它们对城镇边缘地带发动的协同袭击。豺狼人仍盘踞在赤脊山崎岖的高地上，是难以根除的祸患。",al={"豺狼人离开了吗","犹勒死后会怎样"}},{q="接到这份委托前，需要完成哪些前置任务？",a="弗纳先让你在“马掌”和“回复弗纳”中备齐马具。等你处理好腹部鳞片的事，并在“豺狼人的乱吠”中削减豺狼人的数量后，他就会发布猎杀犹勒的悬赏。",al={"犹勒任务前置","解锁豺狼人的嚎叫","豺狼人的嚎叫任务链"}},{q="为什么弗纳需要犹勒的爪子作为证据？",a="弗纳需要犹勒被砍下的爪子作为实物证据，才会支付赏金。这能让他和湖畔镇惴惴不安的居民知道，那头嚎声回荡在山丘间的野兽已经倒下。",al={"为什么要犹勒的爪子","犹勒的爪子证据"}}},fp="20,204,24.368.0,28.391.0,14.185.0,67.253.0,68.222.0,56.168.0,50.204.0,43.185.0"}
P.entries["quest:1260"] = {n="摩根·斯特恩",s="暴风城蓝色隐士的安古斯·斯特恩正在筹备一份以河汊风味为主题的乡村菜肴新菜单。安古斯有个侄子叫摩根，被派往塞拉摩向当地人搜集食谱，安古斯想知道摩根目前有了什么收获。",h="暴风城蓝色隐士的安古斯·斯特恩正在筹备一份以河汊风味为主题的乡村菜肴新菜单。安古斯有个侄子叫摩根，被派往塞拉摩向当地人搜集食谱，安古斯想知道摩根目前有了什么收获。",kw={"安古斯·斯特恩","河汊","蓝色隐士","尘泥沼泽","摩根·斯特恩","暴风城","塞拉摩"},sec={{t="河汊风味菜单",b="安古斯·斯特恩相信，蓝色隐士的顾客会喜欢一份河汊风味的乡村菜肴菜单。为了筹备这份菜单，安古斯派侄子摩根前往尘泥沼泽旁的城市塞拉摩，搜集当地人的食谱。路途太过遥远，安古斯无法亲自前往，因此需要一位像你这样的年轻旅行者去和摩根谈谈。"},{t="摩根要说的话",b="当你在塞拉摩找到摩根·斯特恩时，你得知食谱调查已经有了一些线索，但还需要人帮忙追查。帮忙的人得愿意下水才行。"}},faq={{q="摩根·斯特恩是谁？",a="摩根·斯特恩是蓝色隐士的安古斯·斯特恩的侄子。摩根被派往塞拉摩，向当地人搜集食谱。",al={"摩根·斯特恩是谁","摩根·斯特恩的故事","安古斯·斯特恩的侄子"}},{q="安古斯·斯特恩为什么想联系摩根？",a="安古斯正在为蓝色隐士筹备一份以河汊风味为主题的乡村菜肴新菜单，想知道摩根目前有了什么收获。",al={"为什么派往塞拉摩","蓝色隐士菜单","安古斯·斯特恩的任务"}},{q="在哪里可以找到摩根·斯特恩？",a="摩根在尘泥沼泽旁的城市塞拉摩。",al={"摩根·斯特恩在哪里","摩根·斯特恩的位置","塞拉摩厨师的位置"}}},fp="12,100,12.289.0,22.175.1,20.100.0,42.134.0,32.57.0"}
P.entries["quest:1261"] = {n="玛尔格的嘱托",s="玛格从死亡彼岸讲述了杀死自己的泥壳蟹人，以及尚未完成的职责。玛格请你找到那个泥壳蟹人，取回从联盟士兵那里偷来的宝石坠饰，并将它交给蕨墙村的纳泽尔·血矛。",h="玛格从死亡彼岸讲述了杀死自己的泥壳蟹人，以及尚未完成的职责。玛格请你找到那个泥壳蟹人，取回从联盟士兵那里偷来的宝石坠饰，并将它交给蕨墙村的纳泽尔·血矛。",kw={"血矛","蕨墙村","玛格","泥壳","纳泽尔","坠饰","暴风城","塞拉摩"},sec={{t="玛格在塞拉摩附近的见闻",b="在塞拉摩附近，玛格发现了一群在海滩上扎营的联盟士兵。其中一人戴着一条坠饰，上面镶嵌的宝石多得根本不是一个士兵能买得起的。那天夜里，玛格潜入营地偷走了坠饰，却在返回基地的途中被一个泥壳蟹人杀死。现在，玛格请你找到那个泥壳蟹人，取回坠饰，并将它交给蕨墙村的纳泽尔。"},{t="纳泽尔的看法",b="得知一名暴风城士兵竟然戴着这条坠饰，纳泽尔大吃一惊。你已经揭开了玛格的死因，但坠饰又带来了新的谜团，纳泽尔警告说，它可能会给联盟和部落双方带来严重的后果。"}},faq={{q="玛格是谁，又是怎么死的？",a="玛格从在塞拉摩附近扎营的联盟士兵那里偷走了一条宝石坠饰，随后在返回基地的途中被一个泥壳蟹人杀死。",al={"玛格的死因","玛格是谁","玛格的故事"}},{q="宝石坠饰从何而来？",a="它原本戴在塞拉摩附近海滩上一处联盟营地的一名士兵身上，上面镶嵌的宝石多得远非一个士兵所能负担。玛格在那天夜里潜入营地，偷走了它。",al={"坠饰从何而来","谁持有坠饰","玛格坠饰的来历"}},{q="找回的坠饰要交给谁？",a="蕨墙村的纳泽尔·血矛。",al={"坠饰交给谁","坠饰送到哪里","纳泽尔·血矛的坠饰"}},{q="这个任务的前置任务是什么？",a="它的前置任务是巨魔巫医。",al={"前置任务","玛尔格的嘱托的前置任务"}}},fp="11,247,28.348.0,23.212.1,33.132.0,40.146.0,35.71.0,38.33.0"}
P.entries["quest:1262"] = {n="向佐尔报告",s="纳泽尔·血矛觉得奇怪，普通士兵竟然带着玛格偷走的那条宝石坠饰。纳泽尔认为这是贵族的饰物，便让你带着它前往奥格瑞玛，交给精通联盟政治的佐尔·孤树。",h="纳泽尔·血矛觉得奇怪，普通士兵竟然带着玛格偷走的那条宝石坠饰。纳泽尔认为这是贵族的饰物，便让你带着它前往奥格瑞玛，交给精通联盟政治的佐尔·孤树。",kw={"蕨墙村","宝石坠饰","玛尔格的嘱托","纳泽尔·血矛","奥格瑞玛","向佐尔报告","暴风城","佐尔·孤树"},sec={{t="贵族的坠饰",b="纳泽尔·血矛觉得奇怪，普通士兵手中竟然有这样的坠饰。它的主人可能乔装打扮过，也可能是士兵们自己偷来的。无论如何，纳泽尔认定这是一条贵族的坠饰，要解开谜团，就必须找到它真正的主人。奥格瑞玛的佐尔·孤树对联盟政治十分了解，能够判断这条坠饰是否属于暴风城的贵族。"},{t="佐尔的判断",b="佐尔·孤树赞叹这条坠饰的精湛工艺。佐尔说，兽人用不上这样的珠宝，但许多人类会用得上。佐尔会派人研究它，希望假以时日，能揭开它的秘密。"}},faq={{q="为什么要把坠饰送到奥格瑞玛？",a="纳泽尔·血矛认定这是一条贵族的坠饰。奥格瑞玛的佐尔·孤树对联盟政治十分了解，能够判断它在暴风城贵族之中是否有过什么来历。",al={"为何把坠饰送到奥格瑞玛","为何去奥格瑞玛","为何找佐尔·孤树"}},{q="这条宝石坠饰之前在谁手中？",a="玛格从塞拉摩附近一处联盟营地的士兵手中偷走了它。纳泽尔觉得奇怪，普通士兵手中竟然有这条坠饰，猜想它的主人是否乔装打扮过，或者是士兵们偷来的。",al={"坠饰原来在谁手中","坠饰从哪里来"}},{q="这个任务的前置任务是什么？",a="它接在《玛尔格的嘱托》之后，在那个任务中，玛格讲述了自己从塞拉摩附近扎营的士兵手中偷走坠饰的经过。",al={"前置任务","前一个任务是什么"}},{q="佐尔·孤树在哪里？",a="佐尔·孤树在奥格瑞玛。",al={"佐尔·孤树的位置","佐尔·孤树在哪里"}}},fp="13,197,17.379.0,13.204.1,44.167.0,39.200.0,28.104.0,22.29.0"}
P.entries["quest:1264"] = {n="失踪的使节",s="一位酒馆老板让你去塞拉摩找萨穆尔指挥官，亨德尔可能仍驻扎在那里。",h="一位酒馆老板让你去塞拉摩找萨穆尔指挥官，亨德尔可能仍驻扎在那里。",kw={"黑龙","指挥官萨穆尔","尘泥沼泽","埃林","亨德尔","库尔提拉斯海军陆战队","普罗德摩尔小姐","塞拉摩"},sec={{t="塞拉摩的线索",b="酒馆老板认为，亨德尔是那些经常光顾酒馆的库尔提拉斯海军陆战队员之一。他们每月月初领饷，之后通常就会离开塞拉摩。萨穆尔指挥官或许知道亨德尔是否仍驻扎在那里。提起埃林的名字，萨穆尔或许会暗中相助。"},{t="萨穆尔的警告",b="萨穆尔指挥官负责统领普罗德摩尔小姐在塞拉摩的部队。他事务繁忙，但愿意回答你的问题。城外的沼泽里有食人魔、兽人和鱼人。黑龙栖息在沼泽南部。"}},faq={{q="亨德尔是谁？",a="亨德尔是一名库尔提拉斯海军陆战队员，可能是某家酒馆的常客之一。酒馆老板认为，塞拉摩的萨穆尔指挥官或许知道亨德尔是否仍驻扎在那里。",al={"亨德尔","海军陆战队员亨德尔","亨德尔是谁"}},{q="萨穆尔指挥官是谁？",a="萨穆尔指挥官负责统领普罗德摩尔小姐在塞拉摩的部队。",al={"萨穆尔","那个指挥官","塞拉摩指挥官"}},{q="我为什么要找萨穆尔？",a="酒馆老板认为，如果亨德尔仍驻扎在塞拉摩，萨穆尔或许能帮你找到他。",al={"寻找萨穆尔","为什么找萨穆尔","失踪的使节任务"}},{q="埃林是谁？",a="酒馆老板建议你向萨穆尔指挥官打听亨德尔时，提起埃林的名字。",al={"埃林","提起埃林的名字","埃林的名字"}},{q="库尔提拉斯海军陆战队员什么时候离开塞拉摩？",a="库尔提拉斯海军陆战队员每月月初领饷，之后通常就会离开塞拉摩。",al={"海军陆战队员离开","发饷日","他们什么时候走"}},{q="萨穆尔提到了哪些危险？",a="萨穆尔警告说，城外的沼泽里有食人魔、兽人和鱼人，沼泽南部还有黑龙。",al={"塞拉摩的危险","沼泽里有什么","沼泽的威胁"}}},fp="20,96,19.286.0,16.234.0,14.179.0,24.71.0,28.101.0,14.98.0,46.100.0,33.112.0"}
P.entries["quest:1265"] = {n="失踪的使节",s="埃林派你去寻找列兵亨德尔，一位当地军官担心这背后的缘由可能令人不安。亨德尔曾驻守在警戒哨岗，那是塞拉摩外的第一座哨塔，你被要求到那里寻找他的踪迹。",h="埃林派你去寻找列兵亨德尔，一位当地军官担心这背后的缘由可能令人不安。亨德尔曾驻守在警戒哨岗，那是塞拉摩外的第一座哨塔，你被要求到那里寻找他的踪迹。",kw={"埃林","亨德尔","军官","列兵 亨德尔","警戒哨岗","塞拉摩","哨塔"},sec={{t="哨塔之下",b="一位当地军官认识列兵亨德尔，并说他曾驻守在警戒哨岗，那是塞拉摩外的第一座哨塔。这位军官担心，埃林先派你到那里，是因为你要办的事可能令人不安。把你能透露的情况告诉这位军官。守卫必须保护这片土地，因此任何骚动都不容忽视。"}},faq={{q="列兵亨德尔是谁？",a="列兵亨德尔就是埃林派你寻找的人。一位当地军官说，亨德尔曾驻守在塞拉摩外的第一座哨塔。",al={"列兵 亨德尔","亨德尔 是谁","亨德尔 的背景"}},{q="该去哪里寻找亨德尔？",a="去警戒哨岗寻找列兵亨德尔的踪迹，那是塞拉摩外的第一座哨塔。",al={"亨德尔 的位置","亨德尔 在哪里","警戒哨岗 亨德尔"}},{q="是谁派我寻找亨德尔的？",a="埃林派你去寻找列兵亨德尔。",al={"谁派我来的","埃林 亨德尔","寻找 亨德尔"}},{q="军官为什么担忧？",a="这位军官担心，埃林先派你到那里，是因为你要办的事可能令人不安。为了保护这片土地，军官想知道你能透露哪些情况。",al={"为何担忧","军官担忧","什么令人不安"}}},fp="20,210,12.301.0,22.130.0,31.84.0,27.39.0,29.152.0"}
P.entries["quest:1266"] = {n="失踪的使节",s="塞拉摩的人们正密切留意布莱肯沃尔及边境附近的其他威胁。你奉命向西穿过尘泥沼泽，寻找亨德尔下士。",h="塞拉摩的人们正密切留意布莱肯沃尔及边境附近的其他威胁。你奉命向西穿过尘泥沼泽，寻找亨德尔下士。",kw={"布莱肯沃尔","尘泥沼泽","部落据点","潜伏者","亨德尔下士","失踪的使节","塞拉摩"},ang={["faction:Alliance"]="作为一名联盟旅人，你奉命寻找一名塞拉摩卫兵，他正在监视部落据点布莱肯沃尔以及其他威胁边境的敌情。"},sec={{t="沿路向西",b="一队卫兵在你西边的尘泥沼泽等候，亨德尔下士在那里看护塞拉摩的潜伏者。他们一直在监视布莱肯沃尔，并搜寻边境附近的其他威胁。沿路寻找帐篷，就能找到亨德尔。"}},faq={{q="亨德尔下士是谁？",a="亨德尔下士正在站岗，保护塞拉摩的潜伏者，让他们安心休息。",al={"亨德尔下士","亨德尔是谁","亨德尔是什么人"}},{q="这些潜伏者在监视什么？",a="他们一直在盯着部落据点布莱肯沃尔，并寻找威胁塞拉摩边境的其他敌情。",al={"他们在监视什么","布莱肯沃尔监视","潜伏者"}},{q="我在哪里能找到亨德尔下士？",a="亨德尔下士在你西边，尘泥沼泽路旁的帐篷附近。",al={"亨德尔在哪里","寻找亨德尔","亨德尔的位置"}},{q="这些潜伏者为什么在那里？",a="他们在那里监视布莱肯沃尔，并搜寻塞拉摩边境附近的其他威胁。",al={"潜伏者为何在此","塞拉摩间谍","他们在做什么"}}},fp="20,148,19.250.0,22.85.0,35.113.0,32.79.0,31.85.0"}
P.entries["quest:1268"] = {n="可疑的蹄印",s="蹄印从树荫旅店向外延伸，旅店只剩下空架子，还在冒烟。有几处清晰可见，更多成排的蹄印则几乎隐没在沼泽松软的泥地里。该把这些蹄印的情况报告给蕨墙村的克罗格。",h="蹄印从树荫旅店向外延伸，旅店只剩下空架子，还在冒烟。有几处清晰可见，更多成排的蹄印则几乎隐没在沼泽松软的泥地里。该把这些蹄印的情况报告给蕨墙村的克罗格。",kw={"蕨墙村","半人马","尘泥沼泽","蹄印","卡古隆","克罗格","野猪人","树荫旅店","可疑的蹄印"},sec={{t="泥中的蹄印",b="树荫旅店如今只剩下空架子，还在冒烟，一道道蹄印从旅店向外延伸。有些印痕清晰可见；另一些在松软的泥地里几乎无法辨认。应该让蕨墙村的克罗格知道这些蹄印的情况。"},{t="克罗格的答复",b="克罗格承认，这可能是野猪人干的，甚至可能是半人马，因为两者在贫瘠之地都有相当大的势力，做出这种事也不足为奇。克罗格补充说，旅店不只是被烧毁了：旅店老板还失去了一个女人和一只小狗，两者都被杀了。克罗格会派卡古隆去查明这些蹄印通向哪里。"}},faq={{q="蹄印在哪里？",a="蹄印从树荫旅店向外延伸，穿过沼泽松软的泥地，旅店只剩下空架子，还在冒烟。",al={"蹄印位置","足迹在哪","树荫旅店蹄印"}},{q="该把蹄印的情况告诉谁？",a="该报告给蕨墙村的克罗格。",al={"向谁报告","克罗格位置","到哪报告蹄印"}},{q="有多少蹄印？",a="有几处清晰可见，更远处成排的蹄印在泥中几乎无法看清。",al={"多少蹄印","多少足迹"}}},fp="21,176,17.227.0,12.254.1,25.115.0,37.64.0,26.74.0"}
P.entries["quest:1269"] = {n="帕瓦尔·雷瑟上尉",s="瓦砾下埋着一枚徽章，上面是塞拉摩的标志：白色珐琅底上的金色船锚，船锚下方凸印着帕瓦尔·雷瑟中尉的名字。应当把它交给蕨墙村的克罗格。",h="瓦砾下埋着一枚徽章，上面是塞拉摩的标志：白色珐琅底上的金色船锚，船锚下方凸印着帕瓦尔·雷瑟中尉的名字。应当把它交给蕨墙村的克罗格。",kw={"徽章","蕨墙村","徽记","克罗格","奥格隆","帕瓦尔","雷瑟","塞拉摩"},sec={{t="瓦砾中的微光",b="瓦砾下有什么东西在闪光。拂去灰烬和碎屑，便露出一枚带有塞拉摩标志的徽章，标志下方凸印着帕瓦尔·雷瑟中尉的名字。蕨墙村的克罗格正等着这枚徽章，他会问你是否掌握了树荫旅店遭遇变故的线索。"},{t="克罗格所知之事",b="克罗格认识帕瓦尔·雷瑟这个人类，还称他是个可怜虫。据克罗格所说，雷瑟抛下了与他并肩服役的士兵，如今躲在树林里。克罗格派奥格隆去追查他的下落，因为有人怀疑雷瑟偷窃补给。克罗格觉得有人看见奥格隆往东南方向去了。"}},faq={{q="徽章上有什么？",a="塞拉摩的标志：白色珐琅底上的金色船锚，下方凸印着帕瓦尔·雷瑟中尉的名字。",al={"徽章上写着什么","塞拉摩卫兵徽章标记","徽章是谁的"}},{q="徽章该交给谁？",a="应当把它拿给蕨墙村的克罗格看。",al={"徽章该交给谁","雷瑟的徽章交到哪里","交还徽章"}},{q="徽章是在哪里找到的？",a="在瓦砾下，表面结满了灰烬和碎屑。克罗格会问你是否掌握了树荫旅店遭遇变故的线索。",al={"徽章位置","雷瑟的徽章在哪里找到"}}},fp="23,99,21.269.0,15.265.1,21.123.0,19.47.0,26.127.0"}
P.entries["quest:127"] = {n="卖鱼",s="码头管理员巴伦付钱请旅行者从止水湖带回斑点太阳鱼。这种鱼是湖畔镇的日常食物，但岸边的鱼人让捕捞变得危险。",h="码头管理员巴伦付钱请旅行者从止水湖带回斑点太阳鱼。这种鱼是湖畔镇的日常食物，但岸边的鱼人让捕捞变得危险。",kw={"码头管理员巴伦","止水湖","湖畔镇","鱼人","赤脊山","卖鱼","斑点太阳鱼"},ang={["faction:Alliance"]="作为联盟的旅行者，你可以帮助维持赤脊山的食物供应，因为暴风城王国几乎没有向这一地区提供军事援助。",["profession:Cooking"]="作为厨师，你可以到湖畔镇的水域寻找斑点太阳鱼，这是镇上备受青睐的淡水美味。"},sec={{t="止水湖的日常食物",b="斑点太阳鱼肉质鲜美，深受止水湖周边各地的人们喜爱。镇民和过往商人的需求居高不下，然而，尽管湖中有鱼，湖畔镇的供应却时常短缺。当地的威胁让镇上的人手捉襟见肘，就连基本物资的贸易也要依靠旅行者。"},{t="浅滩上的麻烦",b="附近的垂钓者原本通常能轻松满足码头管理员巴伦的需求。如今，凶悍的鱼人部族出没于浅滩和湖岸，让普通镇民不敢靠近水边。你可以一边钓鱼，一边提防危险，也可以从在岸边滋事觅食的鱼人手中夺取太阳鱼。"}},faq={{q="码头管理员巴伦是谁？",a="码头管理员巴伦负责管理湖畔镇止水湖上的码头和往来船只。他掌管镇上的水路贸易，并依靠能干的旅行者带来鲜鱼，处理湖泊周围的威胁。",al={"巴伦","码头管理员是谁","码头管理员巴伦"}},{q="为什么斑点太阳鱼的需求如此之高？",a="斑点太阳鱼在止水湖周边各地颇有名气，是湖畔镇的日常食物，也是重要的贸易货物。敌对生物在湖边滋事，普通垂钓者无法安全捕鱼，因此镇上的存货日渐短缺。",al={"为什么需要太阳鱼","斑点太阳鱼背景故事","湖畔镇为什么需要鱼"}},{q="鱼人是怎么得到太阳鱼的？",a="止水湖沿岸的鱼人部族在浅滩觅食和狩猎。它们杀死或赶走当地渔夫，再为营地捕捞鱼类，旅行者可以去那里夺取渔获，省去垂钓的工夫。",al={"鱼人的鱼","鱼人为什么掉落鱼","鱼人偷鱼"}},{q="哪里能找到斑点太阳鱼？",a="斑点太阳鱼生活在赤脊山的止水湖中。你可以用鱼竿钓到它们，也可以从湖岸和浅滩上的鱼人手中夺取。",al={"太阳鱼在哪里","止水湖鱼类位置","如何获得斑点太阳鱼"}},{q="这个任务与鱼人偷猎者有什么关联？",a="码头管理员巴伦同时就鱼人偷猎者和太阳鱼的事寻求帮助。鱼人在湖边游荡，捕捞湖中的鱼，因此对付它们也能取回它们收集的太阳鱼。",al={"鱼人偷猎者 关联","巴伦 的其他任务","码头管理员的任务"}},{q="帮助码头管理员巴伦必须钓鱼吗？",a="帮助码头管理员巴伦不需要渔具或钓鱼技能。你可以垂钓太阳鱼，也可以像巴伦直言建议的那样，从在湖中狩猎的鱼人部族手中强行夺取。",al={"是否需要钓鱼","没有鱼竿能否完成","是否必须钓鱼"}}},fp="12,143,26.271.0,23.275.0,24.207.0,44.220.0,39.204.0,35.155.0,45.192.0,45.181.0"}
P.entries["quest:1270"] = {n="伊格纳兹的逃亡",s="伊格纳兹被沼泽里的野兽团团围住，还没找到他要的沼泽豆。棘齿城的地精麦伯克·米希瑞克斯需要沼泽豆叶来调制药水，伊格纳兹请你帮他脱困，并在他寻找时保护他。事后，可以在棘齿城找到麦伯克·米希瑞克斯。",h="伊格纳兹被沼泽里的野兽团团围住，还没找到他要的沼泽豆。棘齿城的地精麦伯克·米希瑞克斯需要沼泽豆叶来调制药水，伊格纳兹请你帮他脱困，并在他寻找时保护他。事后，可以在棘齿城找到麦伯克·米希瑞克斯。",kw={"博格比恩","尘泥沼泽","护送","麦伯克·米希瑞克斯","棘齿城","伊格纳兹"},sec={{t="沼泽中的重围",b="伊格纳兹见到一个不想吃掉他的人，总算松了口气。他说，来自棘齿城的地精麦伯克·米希瑞克斯需要沼泽豆叶，来调制某种药水。伊格纳兹声称自己不在乎原因，因为报酬丰厚，而且他熟悉这片沼泽。他还没找到这种植物就被包围了，请你帮他脱困，并在他寻找时保护他。"},{t="麦伯克的消息",b="麦伯克说，伊格纳兹带着草药来过，还讲了你如何帮他脱困。麦伯克说，伊格纳兹的朋友就是麦伯克的朋友。伊格纳兹再次向南前往沼泽之前，托麦伯克在遇到你时交给你一样东西。"}},faq={{q="伊格纳兹是谁？",a="伊格纳兹正在沼泽里为麦伯克·米希瑞克斯寻找沼泽豆叶。他说自己熟悉这里，却还没找到这种植物就被野兽包围了。",al={"伊格纳兹是谁","伊格纳兹","护送的那个人是谁"}},{q="伊格纳兹为什么要采集沼泽豆叶？",a="来自棘齿城的地精麦伯克·米希瑞克斯需要用它们调制药水。伊格纳兹说自己不在乎原因，因为报酬丰厚。",al={"为什么要沼泽豆","沼泽豆有什么用","麦伯克 沼泽豆"}},{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是来自棘齿城的地精，他需要沼泽豆叶来调制药水。",al={"麦伯克","麦伯克·米希瑞克斯是谁","棘齿城的地精"}},{q="事后该和谁交谈？",a="护送伊格纳兹脱险后，去棘齿城找麦伯克·米希瑞克斯。",al={"伊格纳兹去哪了","伊格纳兹的逃亡在哪里交任务"}}},fp="15,223,23.341.0,15.212.1,23.164.0,39.131.0,22.82.0,34.53.0"}
P.entries["quest:1271"] = {n="盛筵",s="你在尘泥沼泽为摩根·斯特恩所做的工作以《... 还有螃蟹！》告一段落，如今你要回到蓝色隐士，去找安古斯·斯特恩。",h="你在尘泥沼泽为摩根·斯特恩所做的工作以《...",kw={"安古斯·斯特恩","尘泥沼泽","蓝色隐士的盛宴","斯特恩 家族","蓝色隐士","摩根·斯特恩"},sec={{t="重返蓝色隐士",b="安古斯·斯特恩是摩根·斯特恩的叔叔，你曾在尘泥沼泽协助摩根·斯特恩研究食谱。如今，你的旅途将带你回到蓝色隐士，去找安古斯。"},{t="安古斯听到的消息",b="安古斯已经从侄子那里听说，你协助了他的研究，还帮助他的一位同伴摆脱了困境。斯特恩 一家很照顾自己的朋友，一场为你举办的宴会即将开始。"}},faq={{q="安古斯·斯特恩是谁？",a="安古斯·斯特恩是摩根·斯特恩的叔叔，后者在塞拉摩收集食谱，而他本人则与蓝色隐士有联系。",al={"安古斯·斯特恩","蓝色隐士 主人","谁举办宴会"}},{q="安古斯·斯特恩与摩根·斯特恩是什么关系？",a="安古斯是摩根的叔叔。安古斯派摩根前往塞拉摩收集食谱，为蓝色隐士的沼泽风味新菜单做准备。",al={"安古斯 与 摩根 的关系","斯特恩 家族","摩根 是 安古斯 的侄子吗"}},{q="这个任务的前置任务是什么？",a="它接续《还有螃蟹！》，那是你在塞拉摩为摩根·斯特恩完成的最后一项工作。",al={"前置任务","宴会的前置任务"}}},fp="25,125,24.135.0,20.191.1,19.73.0,45.116.0,29.77.0"}
P.entries["quest:1273"] = {n="盘问雷瑟",s="奥格隆受克罗格派遣，追踪人类雷瑟，经过漫长的搜寻终于找到了他，还说他作为一个人类，藏得算是不错。奥格隆担心，在沼泽里待了这么久，雷瑟可能已经疯了，便请你一同前去，从他口中问出些答案。之后，你要回到蕨墙村的克罗格那里。",h="奥格隆受克罗格派遣，追踪人类雷瑟，经过漫长的搜寻终于找到了他，还说他作为一个人类，藏得算是不错。奥格隆担心，在沼泽里待了这么久，雷瑟可能已经疯了，便请你一同前去，从他口中问出些答案。之后，你要回到蕨墙村的克罗格那里。",kw={"蕨墙村","尘泥","审问","克罗格","沼泽","奥格隆","雷瑟"},sec={{t="奥格隆的搜寻",b="经过漫长的搜寻，奥格隆找到了雷瑟，在奥格隆看来，他作为一个人类，藏得算是不错。奥格隆担心，在沼泽里待了这么多天，雷瑟可能已经疯了，便想让你一同前去，从他口中问出些答案。之后，蕨墙村的克罗格正等着你回去。"},{t="回到克罗格身边",b="克罗格很高兴雷瑟已经不在沼泽里了，还鄙夷地说，人类的身体太脆弱，连小小的箭伤都无法痊愈。克罗格认定，这条线索没能解开谜团，必须从别处继续查找。"}},faq={{q="谁找到了雷瑟？",a="奥格隆经过漫长的搜寻找到了雷瑟，想让你一同前去，从他口中问出些答案。",al={"谁提供盘问 雷瑟","盘问雷瑟任务给予者","奥格隆 雷瑟"}},{q="奥格隆为什么想找人同行？",a="奥格隆担心，雷瑟在沼泽里待了这么久，可能已经疯了。",al={"为什么帮助奥格隆","雷瑟疯了吗","为什么质问雷瑟"}},{q="之后要向谁汇报？",a="蕨墙村的克罗格。",al={"盘问雷瑟在哪里交任务","找过雷瑟后和谁交谈","雷瑟交任务"}}},fp="18,210,14.273.0,14.208.1,17.79.0,28.64.0,31.42.0"}
P.entries["quest:1274"] = {n="失踪的使节",s="暴风城的一项秘密请求，指引你前往暴风要塞会见德拉维主教。教会与王室需要有人协助处理一件要事，此事过于凶险，无法通过公开渠道求助。",h="暴风城的一项秘密请求，指引你前往暴风要塞会见德拉维主教。教会与王室需要有人协助处理一件要事，此事过于凶险，无法通过公开渠道求助。",kw={"德拉维主教","外交官","调查","暴风要塞","失踪的使节","托马斯"},ang={["faction:Alliance"]="找到失踪的外交官，关系到联盟的团结与防御。调查或许会揭露暴风城宫廷内部的威胁。",["race:Human"]="身为暴风城的人类，你面对的这件事，关系到脆弱的摄政时期家园的稳定。"},sec={{t="秘密召见",b="你在暴风城行走时，辅祭童托马斯上前，悄声向你提出请求。德拉维主教是圣光教会中备受尊敬的神职人员，他需要一位外来者前往暴风要塞提供帮助。他说此事敏感而紧迫。你必须谨慎保密，以免民众陷入恐慌。"},{t="要塞中的低语",b="在暴风要塞，德拉维主教向你说明了此事必须保密的原因：王国的一位高官离奇失踪了。国内动荡正在酝酿，瓦里安·乌瑞恩国王也下落不明。王国高层若出现任何遭人暗算的迹象，都可能危及这脆弱的和平。"}},faq={{q="托马斯是谁？",a="托马斯是光明大教堂的一名辅祭童，为德拉维主教跑腿办事。他在暴风城的街道上留意有能力的冒险者，当教会或国家事务需要秘密援助时，便指引他们前往要塞。",al={"托马斯是谁","托马斯 暴风城","托马斯 任务给予者"}},{q="德拉维主教是谁？",a="德拉维主教是圣光教会驻暴风要塞的一位资深神职人员。他与王室宫廷合作，秘密处理安全隐患，以及城市卫兵无法公开追查的敏感案件。",al={"德拉维主教是谁","德拉维","德拉维主教"}},{q="为什么要秘密处理此事？",a="暴风城早已人心不安：瓦里安·乌瑞恩国王下落不明，迪菲亚潜行者又在西部荒野各地煽动叛乱。若再传出一位显赫的外交官或官员失踪的消息，可能引发恐慌，或暴露宫廷的弱点。",al={"为何谨慎行事","为何保密","为何秘密处理"}},{q="这场调查会通向何方？",a="调查从暴风要塞的德拉维主教那里开始。线索将引你走遍暴风城及周边的人类领地，随后前往大洋彼岸的险恶之地。",al={"失踪的外交官前往何处","失踪的外交官 后续"}},{q="失踪的外交官是谁？",a="调查开始时，德拉维主教对这位外交官的身份守口如瓶。泄露其身份可能妨碍调查，并危及这位失踪官员与整个王国。",al={"外交官是谁","失踪外交官的身份"}}},fx={["46e2b0bf"]={q="托马斯为什么要你去见德拉维主教？",a="年轻的托马斯是在直接执行德拉维主教的命令。德拉维让他在暴风城各处悄悄物色有能力的冒险者，为王国处理一件棘手而紧迫的事务。托马斯并无私心，只想尽职为主教效力，确保你前往要塞时不会惊动旁人。",al={"托马斯为何派人前往","托马斯在失踪的使节中的动机","为何拜见德拉维主教"}},["227c4a3f"]={q="德拉维主教为什么招募冒险者，而不找城里的卫兵？",a="这项任务涉及一件极为重大的事务，必须严格保密。调动暴风城的卫兵，或是引起军方的正式关注，都可能让敏感消息在城中泄露。让托马斯悄悄接触你这样的独立冒险者，主教就能暗中调查，而不惊动潜在的敌人，也不扰乱民心。",al={"为何不找城里的卫兵","失踪的使节为何招募冒险者","德拉维主教为何需要帮忙"}}},fp="20,154,15.290.0,20.306.1,14.221.0,22.207.0,37.236.0,35.165.0,28.177.0"}
P.entries["quest:1275"] = {n="研究堕落",s="在奥伯丁，戈沙拉·夜语正在寻求来自黑暗深渊的腐化脑干。据传，海那边的血精灵正转向恶魔魔法，他希望在历史重演之前，从纳迦和萨特身上找到答案。",h="在奥伯丁，戈沙拉·夜语正在寻求来自黑暗深渊的腐化脑干。据传，海那边的血精灵正转向恶魔魔法，他希望在历史重演之前，从纳迦和萨特身上找到答案。",kw={"灰谷","奥伯丁","黑暗深渊","血精灵","堕落者的脑干","异乡的腐化","戈沙拉·夜语","纳迦","萨特"},ang={["class:Druid"]="身为德鲁伊，你对萨特深感厌恶，它们的邪能腐化玷污了自然的梦境，也扭曲了大地。",["class:Mage"]="身为法师，你看到了肆意依赖魔法给肉体和灵魂带来的代价。",["faction:Alliance"]="身为联盟的一员，你听闻海那边的血精灵转向黑暗法术，担心新的恶魔威胁即将出现。",["race:NightElf"]="身为暗夜精灵，你面对的是族人记忆中尚未愈合的创伤：你的同胞变成了肆虐卡利姆多的萨特和纳迦。"},sec={{t="历史的警示",b="对卡利姆多各地的暗夜精灵而言，远古同胞的毁灭至今仍历历在目。一万年前，上层精灵屈从于恶魔能量，变成了头生双角的萨特或形似蛇类的纳迦。如今，高等精灵自称血精灵，开始拥抱黑暗魔法。戈沙拉·夜语看到了昔日灾难重演的征兆。"},{t="深入深渊",b="黑暗深渊为戈沙拉提供了研究腐化的场所。神殿废墟位于灰谷的佐拉姆海岸之下，萨特教徒和纳迦盘踞其中。他请你收集这两者的脑干，希望查明奥术成瘾、恶魔腐化与肉体毁坏之间的联系。"},{t="绝望中的救治",b="戈沙拉说，他研究肉体，是为了找到防止又一次堕落的方法。他相信，萨特和纳迦共有的变异或许能揭示如何将血精灵从毁灭的深渊中拉回来。黑海岸的研究能否影响奎尔萨拉斯那些绝望的精灵？这一点仍无定论。"}},faq={{q="戈沙拉·夜语为什么关心血精灵？",a="戈沙拉担心，血精灵转向恶魔力量，可能会催生出又一个扭曲的怪物种族，就像精灵的傲慢曾经造就了萨特和纳迦一样。",al={"为什么帮助血精灵","戈沙拉与血精灵的联系","奥伯丁血精灵"}},{q="在哪里收集腐化脑干？",a="从黑暗深渊的萨特和纳迦身上收集脑干，那里是位于灰谷西北海岸的佐拉姆海岸之下的一片古老神殿建筑群。",al={"脑干在哪里","脑干位置","腐化脑干掉落"}},{q="他为什么专门要萨特和纳迦的样本？",a="萨特和纳迦原本都是被非自然力量扭曲的精灵：萨特源于与恶魔的交易，纳迦则源于大分裂。戈沙拉对比它们脑部的变异，以了解黑暗力量如何伤害精灵的肉体。",al={"为什么是萨特和纳迦","萨特与纳迦的联系"}},{q="谁会指引你接下这项任务？",a="名为遥远的旅途的前置任务可以指引你去奥伯丁寻找戈沙拉·夜语。他也可以直接交给你这项调查任务。",al={"前置任务","异乡的污染的关联"}},{q="戈沙拉打算如何处理这些样本？",a="戈沙拉打算对比这两种腐化对肉体的影响，希望研究所得能减缓血精灵沦为怪物的进程。",al={"脑干研究","戈沙拉的研究目标"}},{q="奥伯丁是否直接受到黑暗深渊的威胁？",a="黑暗深渊就在灰谷南部边界的另一侧。奥伯丁的暗夜精灵密切注视着海岸，留意恶魔和暮光腐化加剧的迹象。",al={"奥伯丁为什么关心","黑暗深渊对黑海岸的威胁"}}},fp="26,240,22.301.0,14.301.0,16.261.1,58.153.0,46.150.0,53.223.0,27.148.0,49.144.0,54.164.0"}
P.entries["quest:1276"] = {n="黑色盾牌",s="克罗格如今想起了莫萨恩这个名字的来历：那是雷霆崖一位备受推崇的铁匠，大地之环曾将他打造的一套护甲赠给克罗格。克罗格希望莫萨恩能说出更多关于被熏黑的铁盾牌的事，因为从雷瑟那里没得到什么有用的消息。莫萨恩就在雷霆崖。",h="克罗格如今想起了莫萨恩这个名字的来历：那是雷霆崖一位备受推崇的铁匠，大地之环曾将他打造的一套护甲赠给克罗格。克罗格希望莫萨恩能说出更多关于被熏黑的铁盾牌的事，因为从雷瑟那里没得到什么有用的消息。莫萨恩就在雷霆崖。",kw={"被熏黑的铁盾牌","铁匠","尘泥","大地之环","克罗格","莫萨恩","雷瑟","雷霆崖"},sec={{t="铁匠之名",b="克罗格想起了以前在哪里听过莫萨恩这个名字：他是雷霆崖一位备受推崇的铁匠。大地之环曾将莫萨恩打造的一套护甲赠给克罗格以表谢意，克罗格对他的手艺赞不绝口。克罗格说，这面盾牌也是莫萨恩打造的，他或许能说出更多相关的事。克罗格承认，这条线索希望渺茫，但从雷瑟那里没得到什么有用的消息，因此也只有这一条线索了。被熏黑的铁盾牌要交给身在雷霆崖的莫萨恩。"},{t="莫萨恩的答复",b="莫萨恩确认这面盾牌出自自己之手，但除此之外也说不出多少。他打造过的盾牌和成套护甲太多，无法一一记住。"}},faq={{q="莫萨恩是谁？",a="莫萨恩是雷霆崖一位备受推崇的铁匠，大地之环赠给克罗格的那套护甲就是他打造的。",al={"莫萨恩是谁","莫萨恩在哪","莫萨恩 雷霆崖"}},{q="为什么要把盾牌带给莫萨恩？",a="克罗格说，这面盾牌是莫萨恩打造的，他或许能说出更多相关的事。克罗格说这条线索希望不大，但从雷瑟那里没得到什么有用的消息，因此也只有这一条线索了。",al={"为什么给莫萨恩看盾牌","被熏黑的盾牌线索","莫萨恩知道什么"}},{q="克罗格是怎么知道莫萨恩的？",a="大地之环曾将莫萨恩打造的一套护甲赠给克罗格，以表谢意。",al={"克罗格与莫萨恩的关系","克罗格怎么知道这位铁匠的"}}},fp="16,142,14.349.0,13.150.1,14.105.0,30.130.0,26.59.0"}
P.entries["quest:128"] = {n="悬赏：黑石氏族",s="在湖畔镇，悬赏：黑石氏族吸引着战士前来，而黑石部队正在赤脊山北部集结。暴风城没有派出王国士兵，因此所罗门镇长和卫兵豪维悬赏招募独立作战的战士，打击黑石勇士，扰乱该氏族的攻势。",h="在湖畔镇，悬赏：黑石氏族吸引着战士前来，而黑石部队正在赤脊山北部集结。暴风城没有派出王国士兵，因此所罗门镇长和卫兵豪维悬赏招募独立作战的战士，打击黑石勇士，扰乱该氏族的攻势。",kw={"黑石","悬赏","燃烧平原","勇士","卫兵豪维","湖畔镇","所罗门镇长","赤脊山","暴风城"},ang={["class:Warrior"]="身为战士，你要面对的是身披重甲、久经战阵且擅长近身搏斗的黑石勇士。他们的战斗技艺将考验你的纪律与耐力。",["faction:Alliance"]="湖畔镇是暴风城东部的盾牌。如果黑石兽人突破山区营地一线，联盟腹地的农田就会暴露在入侵者面前。",["race:Human"]="身为人类，你面对的是那个曾在第一次兽人战争中摧毁最初的暴风城王国的氏族。阻止黑石再次南下，是祖辈的血仇赋予你的沉重责任。"},sec={{t="守卫王国边境",b="赤脊山属于暴风城王国，但黑石氏族无视人类的疆界。兽人从燃烧平原穿过山口，源源不断地涌来，并在赤脊山北部各处加固营地。瓦里安·乌瑞恩国王下落不明，暴风城的摄政当局拒绝派遣王国士兵。随着湖畔镇的金库日渐空虚，所罗门镇长和其他地方领袖发布悬赏，保卫城镇。"},{t="猎杀勇士",b="卫兵豪维指出，黑石勇士是入侵先锋的骨干。这些小队首领都是身经百战的老兵，负责协调各自的战团，驱使地位较低的步兵向前推进。湖畔镇的守军希望通过悬赏猎杀这些勇士，瓦解该氏族的战术指挥，拖延其全面南下的攻势。城镇的外围防线可能很快就会崩溃。"}},faq={{q="卫兵豪维为什么发布悬赏，而不派出镇上的卫兵？",a="湖畔镇的驻军已疲于应付。卫兵既要巡逻止水湖、保护桥梁，又要抵御豺狼人和兽人袭击者。他们无法抽调足够的战士去进攻戒备森严的兽人营地，否则城镇就会失去防卫。",al={"为何悬赏","城镇卫兵在哪","卫兵豪维悬赏"}},{q="黑石勇士驻扎在哪里？",a="黑石勇士驻扎在赤脊山北部连绵的黑石营地中，就在通往燃烧平原的上山大道西侧。",al={"勇士在哪","勇士位置","黑石 勇士营地"}},{q="黑石兽人为什么入侵赤脊山？",a="黑石氏族以北方的黑石山为据点，企图征服并劫掠周围的丘陵。暴风城的防线四分五裂，兽人打算趁机摧毁人类定居点，占据各处山口。",al={"黑石为何在赤脊山","兽人为何进攻湖畔镇","黑石入侵"}},{q="暴风城为什么不派王国士兵清剿他们？",a="瓦里安·乌瑞恩国王下落不明，而由摄政王伯瓦尔·弗塔根和普瑞斯托女士掌权的王廷声称，王国的军队无法抽身。湖畔镇曾多次向首都求援，但请求都遭到拒绝。镇上只能雇用途经此地的佣兵。",al={"为何没有暴风城军队","暴风城援军在哪","所罗门镇长援军"}},{q="这些勇士在黑石氏族中担任什么职责？",a="黑石勇士是前线的战术指挥者。他们指挥进攻，以残酷的手段维持纪律，并率军冲入联盟领土。",al={"黑石 勇士是什么","勇士军阶","黑石首领单位"}},{q="这份悬赏契约是谁批准的？",a="湖畔镇的行政领袖所罗门镇长批准了这项悬赏，并指派卫兵豪维招募有能力的战士，执行清剿任务。",al={"谁支付赏金","谁要杀死勇士","所罗门镇长悬赏"}}},fp="16,272,26.389.0,23.375.0,70.240.0,42.169.0,45.234.0,60.275.0,55.141.0,36.150.0"}
P.entries["quest:1282"] = {n="微笑的吉姆",s="卫兵拜伦很同情一个名叫微笑的吉姆的人，并暗示他并非一直是如今这副模样。拜伦不愿多谈，便让你去塞拉摩找盖兰·维米斯队长。",h="卫兵拜伦很同情一个名叫微笑的吉姆的人，并暗示他并非一直是如今这副模样。拜伦不愿多谈，便让你去塞拉摩找盖兰·维米斯队长。",kw={"盖兰·维米斯队长","尘泥沼泽","卫兵拜伦","詹姆斯·海厄尔","树荫旅店","微笑的吉姆","塞拉摩"},sec={{t="悲伤的往事",b="拜伦很同情吉姆，说他过去并非如此：吉姆曾在沼泽里经营一家旅店，而且那是家很棒的旅店。拜伦不愿细说。谁若真想知道这段往事，他就会让谁去塞拉摩找盖兰·维米斯队长问问。"},{t="维米斯的讲述",b="维米斯说，这个人名叫詹姆斯·海厄尔。海厄尔在贫瘠之地边缘开了一家旅店，希望为旅人提供一处舒适的歇脚之地，旅店也曾兴旺过一段时间。后来，塞拉摩失去了对沼泽道路的控制，食人魔随之而来。可海厄尔十分固执，不肯放弃梦想，躲进塞拉摩的城墙寻求庇护，最终大火吞噬了树荫旅店。维米斯说，调查至今进展甚微，想帮忙的人可以去废墟里搜寻一番。"}},faq={{q="微笑的吉姆是谁？",a="卫兵拜伦很同情他，说他过去并非如此。拜伦记得，吉姆曾在沼泽里经营一家旅店，而且那是家很棒的旅店。",al={"吉姆是谁","微笑的吉姆的身份","那个微笑的男人是谁"}},{q="卫兵拜伦为什么让你去找维米斯队长？",a="拜伦不愿谈论吉姆的过去，便指引你去找盖兰·维米斯队长。",al={"为什么要找维米斯谈话","拜伦的任务","卫兵拜伦的原因"}},{q="在哪里能找到盖兰·维米斯队长？",a="盖兰·维米斯队长在塞拉摩。",al={"维米斯队长是谁","维米斯队长 尘泥"}}},fp="25,128,11.188.0,15.439.1,19.112.0,47.96.0,37.37.0"}
P.entries["quest:1284"] = {n="可疑的蹄印",s="蹄印从仍在冒烟的树荫旅店废墟向外延伸。有些清晰可见，另一些则几乎隐没在沼泽松软的泥地里。这些发现应当报告给塞拉摩的盖兰·维米斯队长。",h="蹄印从仍在冒烟的树荫旅店废墟向外延伸。有些清晰可见，另一些则几乎隐没在沼泽松软的泥地里。这些发现应当报告给塞拉摩的盖兰·维米斯队长。",kw={"贫瘠之地","盖兰·维米斯队长","半人马","尘泥沼泽","法格兰·哈斯迪尔","蹄印","树荫旅店","塞拉摩"},sec={{t="泥中的蹄印",b="一行行蹄印从树荫旅店向外延伸，旅店的废墟仍在冒烟。其中少数印痕清晰可见，更远处的一行行蹄印则在沼泽松软的泥地里几乎无迹可寻。应该把这些发现告诉塞拉摩的盖兰·维米斯队长。"},{t="维米斯的看法",b="维米斯提到，尘泥沼泽附近一带有大量半人马活动的踪迹。几次深入贫瘠之地的短途探查发现，他们的营地和据点散布在各处。维米斯会派追踪者之一法格兰·哈斯迪尔去查明这些蹄印通往何处。"}},faq={{q="蹄印在哪里？",a="蹄印从仍在冒烟的树荫旅店向外延伸，穿过沼泽松软的泥地。",al={"踪迹在哪","蹄印位置","树荫旅店蹄印"}},{q="应该向谁报告这些蹄印？",a="塞拉摩的盖兰·维米斯队长。",al={"蹄印该告诉谁","蹄印报告交给谁","盖兰·维米斯蹄印"}},{q="这些蹄印容易追踪吗？",a="少数蹄印很清晰，但更多成行的蹄印在泥地里几乎看不见。",al={"蹄印难以辨认吗","沼泽模糊踪迹"}}},fp="21,183,17.201.0,22.229.1,31.84.0,41.54.0,34.57.0"}
P.entries["quest:1285"] = {n="戴林的下属",s="泰索兰副官在卫兵档案中找到了帕瓦尔·雷瑟中尉的记录。档案记载，他十六岁时加入库尔提拉斯海军陆战队，因表现出色而获得晋升，后来随普罗德摩尔女士渡海而来，与其他新兵一同加入了塞拉摩卫队。最后一条记录将雷瑟列为失踪，盖兰·维米斯队长需要得知此事。",h="泰索兰副官在卫兵档案中找到了帕瓦尔·雷瑟中尉的记录。档案记载，他十六岁时加入库尔提拉斯海军陆战队，因表现出色而获得晋升，后来随普罗德摩尔女士渡海而来，与其他新兵一同加入了塞拉摩卫队。最后一条记录将雷瑟列为失踪，盖兰·维米...",kw={"泰索兰副官","戴林的手下","逃兵","尘泥沼泽","加瑞安·维米斯","库尔提拉斯","帕瓦尔·雷瑟","塞拉摩"},sec={{t="档案中的记载",b="盖兰·维米斯队长派你去找泰索兰副官，副官如今已查阅档案，找到了帕瓦尔·雷瑟中尉的记录。雷瑟十六岁时加入库尔提拉斯海军陆战队，因表现出色而获得晋升。此后，雷瑟加入了塞拉摩卫队，和大多数随普罗德摩尔女士渡海而来的新兵一样。档案的最后一条记录将雷瑟列为失踪。这个消息要带给塞拉摩的维米斯。"},{t="队长的反应",b="维米斯认为，“失踪”只是泰索兰对叛徒的委婉说法。维米斯确信，雷瑟也是那些愚蠢之徒中的一员，他们盲目效忠戴林海军上将，甚至不惜为此叛变，而逃兵们却指责塞拉摩背叛了联盟，这让他觉得格外讽刺。"}},faq={{q="泰索兰副官是谁？",a="泰索兰副官在卫兵档案中查找了帕瓦尔·雷瑟中尉的记录，并宣读了其中的记载。",al={"泰索兰","戴林的手下任务由谁提供"}},{q="档案中关于帕瓦尔·雷瑟有哪些记载？",a="雷瑟十六岁时加入库尔提拉斯海军陆战队，凭借出色的表现获得晋升，后来随普罗德摩尔女士渡海而来，与其他新兵一同加入了塞拉摩卫队。档案的最后一条记录将雷瑟列为失踪。",al={"雷瑟的背景","雷瑟的档案","帕瓦尔·雷瑟的经历"}},{q="关于雷瑟的消息要带给谁？",a="塞拉摩的盖兰·维米斯队长。",al={"为何返回维米斯处","加瑞安·维米斯 雷瑟"}}},fp="12,341,20.397.0,22.274.1,24.101.0,43.257.0,31.48.0"}
P.entries["quest:1286"] = {n="背叛者",s="盖兰·维米斯队长说，逃兵占据了塞拉摩废弃的一座哨塔。那座哨塔位于旅店东南方的废弃哨塔。一名叫加科因的人率领着这些逃兵，维米斯想从他那里得到有关雷瑟的消息。",h="盖兰·维米斯队长说，逃兵占据了塞拉摩废弃的一座哨塔。那座哨塔位于旅店东南方的废弃哨塔。一名叫加科因的人率领着这些逃兵，维米斯想从他那里得到有关雷瑟的消息。",kw={"巴鲁斯·加科因","盖兰·维米斯队长","逃兵","尘泥沼泽","废弃哨塔","雷瑟","哨塔"},sec={{t="被占据的哨塔",b="维米斯承认，在沼泽中坚守一直很艰难，但他手下的人意志坚定，让几座防御哨塔至今仍屹立不倒。侦察报告称，逃兵已经占据了旅店东南方废弃哨塔的一座废弃哨塔。一名叫加科因的人率领着他们。维米斯请你去看看能从加科因那里问出什么有关雷瑟的消息，并提醒你，加科因可能不会轻易开口。"}},faq={{q="谁派你去对付逃兵？",a="盖兰·维米斯队长，他收到的侦察报告称，逃兵已经占据了塞拉摩废弃的一座哨塔。",al={"叛逃者任务起始人","谁提供叛逃者任务"}},{q="逃兵藏在哪里？",a="在旅店东南方的废弃哨塔，藏身于尘泥沼泽的一座废弃哨塔中。",al={"逃兵位置","废弃哨塔在哪里"}},{q="谁率领着废弃哨塔的逃兵？",a="一名叫加科因，也就是巴鲁斯·加科因的人率领着他们。维米斯提醒你，加科因可能不会轻易透露消息。",al={"巴鲁斯·加科因是谁","逃兵首领"}},{q="维米斯队长想从巴鲁斯·加科因那里得到什么？",a="从加科因和逃兵那里得到有关雷瑟的消息。",al={"为什么找加科因","维米斯想要什么"}}},fp="13,95,13.328.0,41.104.0,31.104.0,38.129.0,47.81.0"}
P.entries["quest:1287"] = {n="背叛者",s="被问及雷瑟时，废弃哨塔逃兵的首领巴鲁斯·加科因称他是个懦夫，说逃兵们把他赶出了营地。加科因随后请你忘记曾经遇见过他们。关于雷瑟的消息，该去告诉塞拉摩的盖兰·维米斯队长。",h="被问及雷瑟时，废弃哨塔逃兵的首领巴鲁斯·加科因称他是个懦夫，说逃兵们把他赶出了营地。加科因随后请你忘记曾经遇见过他们。关于雷瑟的消息，该去告诉塞拉摩的盖兰·维米斯队长。",kw={"巴鲁斯·加科因","蕨墙村","卡德维尔","逃兵","盖兰·维米斯","废弃哨塔","雷瑟","塞拉摩"},sec={{t="被逐出营地",b="加科因说，逃兵们赶走雷瑟，是因为他一再劫掠蕨墙村食人魔的储备物资。按加科因的说法，逃兵人数太少，无力对抗那些食人魔，而雷瑟屡次越界，终于让他们忍无可忍，于是这伙人让他独自应付。作为回答问题的回报，加科因请你忘记这次会面。"},{t="回到塞拉摩",b="维米斯说，将派卡德维尔中尉去对付废弃哨塔的逃兵，也会命他寻找雷瑟。维米斯认为，这片沼泽既不够辽阔，也不至于无迹可寻，卡德维尔总能找到雷瑟。"}},faq={{q="雷瑟为什么被赶出逃兵营地？",a="加科因说，雷瑟不断劫掠蕨墙村食人魔的储备物资。逃兵人数太少，无力对抗他们，所以让雷瑟独自应付。",al={"逃兵为什么放逐雷瑟","雷瑟 蕨墙村","巴鲁斯为什么赶走雷瑟"}},{q="巴鲁斯·加科因是谁？",a="加科因是废弃哨塔逃兵的首领。被问及雷瑟时，他称雷瑟是个懦夫。",al={"巴鲁斯·加科因是谁","巴鲁斯·加科因的故事","巴鲁斯·加科因 尘泥"}},{q="谁想听到关于雷瑟的消息？",a="塞拉摩的盖兰·维米斯队长，不过加科因本人希望你忘记曾经遇见过那些逃兵。",al={"叛逃者在哪里交任务","谁想要雷瑟的消息"}}},fp="13,189,10.313.0,17.228.1,47.155.0,20.92.0,31.118.0"}
P.entries["quest:1288"] = {n="维米斯的报告*",s="盖兰·维米斯队长认为，你的表现是维米斯见过的业余人士中最出色的。吉安娜·普罗德摩尔曾请维米斯随时向她汇报一件微妙之事的进展，如今维米斯将报告交给你，让你带到塞拉摩交给她。",h="盖兰·维米斯队长认为，你的表现是维米斯见过的业余人士中最出色的。吉安娜·普罗德摩尔曾请维米斯随时向她汇报一件微妙之事的进展，如今维米斯将报告交给你，让你带到塞拉摩交给她。",kw={"尘泥","加瑞安·维米斯","吉安娜·普罗德摩尔","报告","塞拉摩","维米斯"},sec={{t="给普罗德摩尔女士的报告",b="普罗德摩尔女士曾请维米斯队长随时向她汇报一件微妙之事的进展，而维米斯已有一段时间没和她交谈了。维米斯原本打算晚些时候送去报告，但现在认为由你去和她谈谈此事更合适，因为面对她的问题，你很可能比维米斯更能给出满意的答案。"}},faq={{q="是谁将报告交给你，让你带给吉安娜·普罗德摩尔？",a="盖兰·维米斯队长将维米斯的报告交给你，让你带到塞拉摩，交给吉安娜·普罗德摩尔。",al={"谁提供维米斯的报告任务","谁交付报告","谁写了维米斯的报告"}},{q="维米斯队长为什么派你去，而不亲自前往？",a="维米斯已有一段时间没和普罗德摩尔女士交谈了，觉得由你代为前往更合适。维米斯相信，面对她的问题，你或许能给出更好的答案。",al={"为什么派我去","为什么不由维米斯送报告","为什么向吉安娜汇报"}},{q="报告需要送到哪里？",a="送到塞拉摩，交给吉安娜·普罗德摩尔。",al={"在哪里交维米斯的报告","吉安娜·普罗德摩尔在哪里","报告送往何处"}}},fp="14,146,28.263.0,53.81.0,57.142.0,33.54.0"}
P.entries["quest:1289"] = {n="维米斯的报告*",s="吉安娜·普罗德摩尔已经读过盖兰·维米斯队长的报告，并感谢你协助调查。她请你回到维米斯身边，帮助查明谜团的真相。",h="吉安娜·普罗德摩尔已经读过盖兰·维米斯队长的报告，并感谢你协助调查。她请你回到维米斯身边，帮助查明谜团的真相。",kw={"盖兰·维米斯队长","尘泥沼泽","调查","吉安娜·普罗德摩尔","塞拉摩","维米斯的报告"},sec={{t="回到队长身边",b="从维米斯队长的报告中，普罗德摩尔女士看出你为他的调查提供了很大帮助，并为此向你致谢。知道此事交给了如此能干的人，她也安心了许多。她请你回到塞拉摩的维米斯队长身边，帮助他查明这个谜团的真相。"}},faq={{q="谁让你回到维米斯队长身边？",a="吉安娜·普罗德摩尔，她在塞拉摩读过维米斯的报告后，便请你回去。",al={"谁提供维米斯的报告","吉安娜任务给予者","谁让我去找维米斯"}},{q="吉安娜女士对这份报告有何看法？",a="她说你为调查提供了很大帮助，并为此向你致谢。知道此事交给了能干的人，她也安心了许多。",al={"吉安娜的反应","吉安娜如何评价维米斯的报告"}},{q="在哪里能找到盖兰·维米斯队长？",a="盖兰·维米斯队长在塞拉摩。",al={"维米斯队长在哪里","维米斯队长位置","在哪里交维米斯的报告"}}},fp="14,179,19.209.0,36.74.0,41.129.0,39.37.0"}
P.entries["quest:129"] = {n="免费的午餐",s="达希请你把备好的饭菜从湖畔镇送给南边道路上的卫兵帕克。豺狼人和黑石兽人威胁着通往镇子的道路，镇上的卫兵已是人手不足。",h="达希请你把备好的饭菜从湖畔镇送给南边道路上的卫兵帕克。豺狼人和黑石兽人威胁着通往镇子的道路，镇上的卫兵已是人手不足。",kw={"黑石兽人","达希","夜色镇","免费午餐","豺狼人","卫兵帕克","湖畔镇","帕克的午餐","赤脊山"},ang={["faction:Alliance"]="为达希捎送饭菜，让人看到偏远联盟聚居地中普通民众与哨兵承受的压力，他们大多只能依靠自己。",["profession:Cooking"]="一顿热饭，能支撑独自在危机四伏的野外站岗的哨兵。"},sec={{t="路上的一顿饭",b="湖畔镇的厨师达希为卫兵帕克打包了一份饭菜，却无法亲自出镇送去。赤脊山的豺狼人和四处游荡的兽人战团让镇门外的道路变得太过危险，平民难以通行。她请过路的旅人沿着通往夜色镇的道路捎去饭菜，帕克就在那里守望。"},{t="守卫边境",b="卫兵帕克守望着湖畔镇以南、通往暮色森林的道路。暴风城军队派来的援兵太少，赤脊山的卫兵无力应对日益壮大的豺狼人群和盘踞山中的黑石氏族。像帕克这样的哨兵独自在危机四伏的野外站岗，镇上送来的一顿热饭能让他们振作精神。"}},faq={{q="在哪里能找到卫兵帕克？",a="卫兵帕克在湖畔镇南边通往暮色森林和夜色镇的土路上巡逻。",al={"卫兵帕克位置","帕克在哪里","寻找卫兵帕克"}},{q="达希为什么不亲自送午餐？",a="达希是个平民，她认为湖畔镇郊外太过危险，不宜独自出行。豺狼人和黑石兽人在镇外的道路上游荡。",al={"达希为什么不能去","达希 赤脊山"}},{q="卫兵帕克正在应对哪些威胁？",a="帕克在南边的道路上面对着赤脊山的豺狼人群和黑石兽人战队。",al={"帕克的敌人","赤脊山的威胁"}},{q="卫兵帕克拿到午餐后会发生什么？",a="达希送来的饭菜让帕克心怀感激。随后，他会请你继续在卫兵和镇民之间跑腿，先去拜访当地的草药师。",al={"免费的午餐后续任务","帕克后续任务"}},{q="暴风城的卫兵为何难以保障赤脊山的安全？",a="暴风城派往湖畔镇这类偏远聚居地的援兵太少，镇上的卫兵只能在支援寥寥的情况下应对威胁。",al={"湖畔镇为何缺乏防守","暴风城疏于照顾赤脊山"}},{q="达希承诺的奖励是什么？",a="达希承诺，等你带着帕克的饭菜回到镇上时，她会为你准备并端上一顿免费的午餐。",al={"免费午餐是什么","达希的奖励"}}},fp="12,171,19.302.0,19.306.0,32.89.0,44.147.0,42.85.0,47.158.1,58.135.0,32.96.0"}
P.entries["quest:13"] = {n="人民军",s="西部荒野的志愿者正面对日益加剧的迪菲亚威胁。在格里安·斯托曼的带领下，人民军如今对抗的盗匪已不再满足于拦路抢劫，开始洗劫月溪镇和金海岸矿洞。民兵呼吁采取更严厉的反击。",h="西部荒野的志愿者正面对日益加剧的迪菲亚威胁。在格里安·斯托曼的带领下，人民军如今对抗的盗匪已不再满足于拦路抢劫，开始洗劫月溪镇和金海岸矿洞。民兵呼吁采取更严厉的反击。",kw={"阿历克斯顿农场","迪菲亚抢劫者","迪菲亚掠夺者","金海岸矿洞","格里安·斯托曼","月溪镇","人民军","哨兵岭","西部荒野"},ang={["class:Paladin"]="身为圣骑士，你听见格里安·斯托曼呼唤圣光，净化西部荒野的罪恶。对你而言，这场战役正是践行正义的使命。",["faction:Alliance"]="身为联盟战士，你看到暴风城安逸的城墙之内，与饥民遍地、完全被迫自生自灭的边疆之间，那道令人痛心的鸿沟。",["race:Human"]="身为人类，你面对的是一场悲剧般的斗争，对手曾是石匠和邻居，如今却以暴力向自己的同胞相向。"},sec={{t="愈演愈烈的暴行",b="迪菲亚的袭击已从道路蔓延至西部荒野的经济重地。迪菲亚强夺者和投掷火焰的抢劫者占据了月溪镇和金海岸矿洞。他们也将阿历克斯顿农场洗劫一空。格里安·斯托曼看到了这些地方被他们控制的后果：没有正规的王国军队，西部荒野恐怕再也无法收复。"},{t="民兵的信念",b="暴风城既没有给格里安·斯托曼派遣士兵，也没有送来补给。因此，他只能依靠圣光，以及西部荒野留下的农民们的决心。志愿者攻入迪菲亚的据点，不断削弱兄弟会的力量。赶走掠夺者就能切断他们的资源，也能让惶恐的居民看到，仍有守卫者在为西部荒野的和平与繁荣而战。"}},faq={{q="什么是人民军？",a="格里安·斯托曼组织了人民军，这支志愿武装负责保卫西部荒野。其成员大多是流离失所的西部荒野农民，以及心怀同情的旅人。暴风城王廷拒绝派遣城市卫兵后，他们便集结起来，抵抗迪菲亚潜行者。",al={"人民军","民兵是谁","西部荒野民兵"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位身经百战的人类指挥官，在哨兵岭顶端的堡垒中指挥西部荒野的防御。他忠于圣光，心系家园，带领人民军拼死抵抗匪徒的统治。",al={"格里安","斯托曼是谁","斯托曼的故事"}},{q="迪菲亚为什么要洗劫农场和采石场？",a="迪菲亚潜行者企图瘫痪西部荒野的粮食供应，并夺取原材料。占领金海岸矿洞后，他们便控制了石料和矿产。夺取月溪镇和各处农场，既能赶走安分守己的居民，也能为他们的犯罪活动提供据点。",al={"迪菲亚为何劫掠","月溪镇的迪菲亚","抢劫者为何在采石场"}},{q="暴风城为什么没有向西部荒野派兵？",a="暴风城没有派兵，是因为国王瓦里安·乌瑞恩神秘失踪了。年幼的国王安度因坐上王位，由伯瓦尔·弗塔根公爵摄政。贵族议会贵族中的僵局令王室资源捉襟见肘，西部荒野这样的边远领地只能依靠当地守卫者。",al={"暴风城卫兵在哪里","暴风城为何不援助","国王瓦里安与西部荒野"}},{q="哪里能找到迪菲亚抢劫者和掠夺者？",a="迪菲亚抢劫者和掠夺者聚集在西部荒野南部和西部被占领的定居点周围。废弃的月溪镇、西部峭壁沿线的金海岸矿洞，以及破败的阿历克斯顿农场，都能找到他们。",al={"抢劫者位置","强夺者在哪里","迪菲亚位置"}}},fx={["3f9873c1"]={q="格里安·斯托曼为什么想杀死迪菲亚抢劫者和掠夺者？",a="迪菲亚抢劫者和掠夺者正在劫掠西部荒野仅存的农庄和重要资源产地，包括月溪镇、金海岸矿洞和阿历克斯顿农场。格里安·斯托曼不愿让这些盗贼夺走当地家庭仅剩的一点安宁和生计。他希望通过消灭这些劫掠队伍，遏制他们的势头，保护幸存的定居者，并明确表明，任何不法与腐败行径都会遭到武力反击。",al={"为何杀死迪菲亚 抢劫者","格里安·斯托曼的动机","格里安为何想杀死抢劫者"}},["599e05d4"]={q="这项任务要对付的迪菲亚抢劫者和掠夺者是什么人？",a="他们是迪菲亚潜行者麾下的普通劫掠者和巫师，受命将西部荒野洗劫一空。普通扒手在旷野游荡，而这些劫掠者则直接袭击月溪镇和金海岸矿洞这样的既有聚居地。他们使用武器和破坏力强大的火焰魔法，搜集补给，掠夺废弃的产业，并用暴力驱赶任何试图阻拦他们的农户。",al={"迪菲亚 抢劫者是谁","迪菲亚强夺者是谁","西部荒野的迪菲亚目标"}},["7d97eb03"]={q="格里安·斯托曼为什么需要你的帮助，而不依靠人民军？",a="人民军已经支撑到了极限。暴风城拒绝提供军事援助，哨兵岭只有少数志愿者、农民和退伍老兵，负责守卫道路和山上设防的据点。他们无法抽调士兵在整个地区展开大规模反攻，否则基地就会无人防守。你这样有本事的冒险者，能提供人民军急缺的进攻力量。",al={"格里安为何需要我","为何不动用人民军","为何找冒险者"}}},fp="20,249,19.343.0,24.368.0,29.282.0,25.223.0,46.263.0,47.298.0,45.231.0"}
P.entries["quest:130"] = {n="寻访草药师",s="卫兵帕克让你在返回湖畔镇的旅店前，为达希买些花。他希望这份礼物能保密。",h="卫兵帕克让你在返回湖畔镇的旅店前，为达希买些花。他希望这份礼物能保密。",kw={"水仙花","达希","鲜花","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山","寻访草药师"},ang={["faction:Alliance"]="成群的豺狼人和blackrock兽人威胁着赤脊山，而湖畔镇的守卫们心中仍有浪漫的一席之地。",["profession:Herbalism"]="玛蒂·詹罗斯是湖畔镇的草药学与炼金术商人，位于镇子西边。"},sec={{t="卫兵的秘密请求",b="卫兵帕克驻守在湖畔镇南面的入口，警戒着黑石兽人和豺狼人。你为他送来了达希在湖畔镇旅店准备的热饭。帕克感激她的好意，请你顺路去镇子西头的草药店，为她买些花。"},{t="镇上的闲话与秘密求爱",b="帕克请你去找草药师玛蒂·詹罗斯时，对买花的事保密。湖畔镇是个小镇，他不想让玛蒂知道是谁送花，也不想让她知道花要送给谁。在店里，玛蒂打趣你，猜你已经在镇上找到了心上人。兽人的入侵和强盗的滋扰让赤脊山不得安宁，一点浪漫的心意也能带来些许难得的宽慰。"}},faq={{q="谁让你去拜访草药师？",a="卫兵帕克派你去找草药师，他驻守在暮色森林以北、通往赤脊山的南面道路上。",al={"谁提供这个任务","任务给予者","卫兵帕克"}},{q="湖畔镇的草药师是谁？",a="玛蒂·詹罗斯是湖畔镇的草药师，也兼营鲜花。她的店在镇子西头。",al={"玛蒂·詹罗斯是谁","草药师在哪","湖畔镇草药师"}},{q="卫兵帕克为什么想要鲜花？",a="帕克想感谢在湖畔镇旅店当女侍的达希送来免费午餐，也想用鲜花表达爱慕之情。",al={"为什么买花","花送给谁","帕克的动机"}},{q="帕克为什么要对买花的事保密？",a="帕克对追求达希这件事感到害羞，想瞒着玛蒂·詹罗斯和其他镇民买花。",al={"为什么保密","为什么隐瞒收花的人","别告诉玛蒂"}},{q="与玛蒂·詹罗斯交谈后会发生什么？",a="玛蒂为你准备了一束水仙花，让你带给湖畔镇旅店的达希。",al={"接下来做什么","水仙诉衷情","拜访草药师之后"}},{q="这次拜访在任务链中处于什么位置？",a="这次拜访在为卫兵帕克送午餐的任务“免费的午餐”之后，在把花带回给达希的任务“水仙诉衷情”之前。",al={"任务链","前置任务","免费的午餐任务链"}}},fp="19,120,24.249.0,31.383.0,37.124.0,34.93.0,35.127.0,46.118.0,46.85.1,39.155.1"}
P.entries["quest:1302"] = {n="詹姆斯·海厄尔",s="“詹姆斯·海厄尔”是一项联盟任务，讲述了一位随吉安娜·普罗德摩尔的远征队渡海前往卡利姆多的人类移民的故事。他动身前往边疆开设旅店后，留在东部王国的家人便与他失去了联系，如今正通过塞拉摩的行政档案打听他的下落。",h="“詹姆斯·海厄尔”是一项联盟任务，讲述了一位随吉安娜·普罗德摩尔的远征队渡海前往卡利姆多的人类移民的故事。他动身前往边疆开设旅店后，留在东部王国的家人便与他失去了联系，如今正通过塞拉摩的行政档案打听他的下落。",kw={"书记员伦德瑞","厨师","旅店老板","吉安娜·普罗德摩尔","詹姆斯·海厄尔","卡利姆多","塞拉摩"},ang={["faction:Alliance"]="第三次大战期间，詹姆斯随吉安娜·普罗德摩尔一同乘船西行，这段经历体现了许多联盟家庭跨越无尽之海、与塞拉摩岛紧密相连的亲情纽带。",["profession:Cooking"]="詹姆斯在故乡以精湛的厨艺闻名，他远赴卡利姆多，希望靠经营旅店、为旅人供应饭食谋生。"},sec={{t="横渡无尽之海",b="第三次大战期间，无数人离开了东部王国的故土，追随吉安娜·普罗德摩尔横渡无尽之海。詹姆斯·海厄尔也在其中，在亲人的记忆中，他是一位厨艺出众的好厨师。战事平息、塞拉摩岛建立后，詹姆斯决定在卡利姆多这片险峻的大陆上谋生，开设自己的旅店，招待旅人与其他移民。"},{t="寻找兄弟",b="远在东部王国，詹姆斯的兄弟近来一直收不到海那边的来信，渐渐担忧起来。他希望詹姆斯只是忙于经营一家生意兴隆的路边酒馆，于是请过往的旅人帮忙寻找。要找到他，得先去塞拉摩，书记员伦德瑞在那里管理当地的档案，记录那些已深入荒野的远征队成员的去向。"}},faq={{q="詹姆斯·海厄尔是谁？",a="詹姆斯·海厄尔是一位人类移民，也是一位技艺出众的厨师，曾随吉安娜·普罗德摩尔的舰队横渡无尽之海。战事平息后，他想在卡利姆多另谋生计，于是动身去大陆上开设旅店。",al={"詹姆斯·海厄尔是谁","詹姆斯·海厄尔的故事","詹姆斯是谁"}},{q="在哪里能找到詹姆斯·海厄尔？",a="詹姆斯随普罗德摩尔女士的远征队抵达卡利姆多后，便动身去大陆上的某处开设旅店。他的家人近来一直没有收到他的消息，但塞拉摩岛的书记员伦德瑞掌管着相关档案，或许知道他的确切下落。",al={"詹姆斯·海厄尔在哪里","寻找詹姆斯·海厄尔","詹姆斯·海厄尔的位置"}},{q="书记员伦德瑞是谁？",a="书记员伦德瑞是驻扎在塞拉摩岛的一位联盟官员，负责当地的城镇行政事务和居民问询。想要寻找詹姆斯·海厄尔这类移民的旅人，都会被指引去找伦德瑞，查阅塞拉摩的档案。",al={"书记员伦德瑞是谁","书记员伦德瑞的位置","塞拉摩书记员"}},{q="詹姆斯为什么前往卡利姆多？",a="第三次大战期间，人类大举迁离东部王国，詹姆斯也随吉安娜·普罗德摩尔的舰队渡海而去。主要战事平息后，他选择留下来，为旅人与移民开设一家旅店。",al={"詹姆斯为什么去卡利姆多","詹姆斯·海厄尔远征队"}},{q="谁在寻找詹姆斯·海厄尔？",a="打听消息的是詹姆斯留在东部王国的兄弟，他已经有一段时间没有收到詹姆斯的音讯了。在他的记忆中，詹姆斯是一位出色的厨师，因此他猜想詹姆斯只是忙于筹办新旅店。",al={"谁发布詹姆斯·海厄尔任务","詹姆斯的兄弟是谁"}},{q="詹姆斯·海厄尔有危险吗？",a="他的兄弟相信，他只是忙于经营新生意，并认为大陆上的和平让他得以生意兴隆。然而，他的家人已经有一段时间没有收到他本人的消息了。",al={"詹姆斯·海厄尔安全吗","詹姆斯·海厄尔发生了什么事"}}},fp="10,225,20.341.0,22.329.0,18.197.0,28.232.0,20.138.0,33.215.0,30.179.0,28.127.0"}
P.entries["quest:131"] = {n="水仙诉衷情",s="在湖畔镇，你将玛蒂·詹罗斯的鲜花送给达希，一段令人尴尬的争风吃醋也随之浮出水面。起初，你为卫兵帕克送去午餐，他请你取一束花，送给湖畔镇旅店的达希。",h="在湖畔镇，你将玛蒂·詹罗斯的鲜花送给达希，一段令人尴尬的争风吃醋也随之浮出水面。起初，你为卫兵帕克送去午餐，他请你取一束花，送给湖畔镇旅店的达希。",kw={"水仙花","达希","水仙诉衷情","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山","煎太阳鱼"},ang={["faction:Alliance"]="湖畔镇面临黑石和豺狼人的侵袭，帮助镇上的卫兵和旅店老板能鼓舞平民的士气。",["profession:Cooking"]="达希用调味煎太阳鱼作为酬谢，让你尝到赤脊山湖畔朴素的家常风味。",["profession:Herbalism"]="玛蒂·詹罗斯运用对植物的了解，以及挑选湖畔鲜花的眼光，展现了采集草药时恬静的一面。"},sec={{t="芬芳的差事",b="卫兵帕克感谢你送来午餐，并请你去玛蒂·詹罗斯那里取些花，送给为他准备饭菜的厨师达希。玛蒂扎好了一束自己最喜欢的水仙花，却不知道收花的人是谁。"},{t="镇上的情敌",b="在湖畔镇旅店，达希看到水仙花后，喜悦变成了疑心。她知道这是玛蒂最喜欢的花，也认定玛蒂是个嫉妒心重的情敌。达希担心，倘若玛蒂知道收花的人是谁，可能会在花茎上下毒，但她并不怪你。她给了你热腾腾的煎太阳鱼，酬谢你的辛劳。"}},faq={{q="达希是谁？",a="达希在赤脊山的湖畔镇旅店工作，为当地居民和镇上的卫兵准备饭菜。她给卫兵帕克送去午餐，卫兵帕克便请你送花给她，以表谢意。",al={"达希","湖畔镇的达希是谁","湖畔镇厨师达希"}},{q="玛蒂·詹罗斯是谁？",a="玛蒂·詹罗斯是湖畔镇的草药师，也是一位爱花之人。卫兵帕克派你去她那里取一束花，她选了自己最喜欢的水仙花。",al={"玛蒂·詹罗斯","湖畔镇草药师","谁送的花"}},{q="达希为什么对水仙花感到不快？",a="达希认出水仙花是玛蒂最喜欢的花，也认定玛蒂是个嫉妒心重的情敌。她担心，倘若玛蒂知道这束花是要送给达希的，就会在花茎上下毒。",al={"达希为什么生气","达希与玛蒂的争执","为什么在花上下毒"}},{q="玛蒂真的在花束上下毒了吗？",a="没有。玛蒂不知道这些花是送给达希的；帕克只让你去取一束花，所以玛蒂选了自己最喜欢的花。",al={"水仙花有毒吗","花束有毒吗"}},{q="这次送花之前有哪些任务？",a="任务链从免费的午餐开始，你要把达希做的饭菜送给卫兵帕克。随后，帕克在寻访草药师中派你去玛蒂·詹罗斯那里买一份礼物，之后便是水仙诉衷情。",al={"任务链","水仙花前置任务","水仙诉衷情任务链"}},{q="送花能获得什么奖励？",a="达希会给你一大份煎太阳鱼、一些铜币和经验值，还会提升你在暴风城王国的声望。",al={"任务奖励","水仙花奖励"}}},fp="20,189,17.265.0,14.341.1,13.186.0,23.163.0,39.194.1,39.130.1,37.199.0,50.123.0"}
P.entries["quest:1319"] = {n="黑色盾牌",s="盖兰·维米斯队长很抱歉，自己对被熏黑的铁盾牌所知甚少，但他知道谁能帮上更多忙：卡兹·双链是这一带最好的铁匠之一，在塞拉摩的铁匠铺照看熔炉。",h="盖兰·维米斯队长很抱歉，自己对被熏黑的铁盾牌所知甚少，但他知道谁能帮上更多忙：卡兹·双链是这一带最好的铁匠之一，在塞拉摩的铁匠铺照看熔炉。",kw={"被熏黑的铁盾牌","盖兰·维米斯队长","卡兹·双链","尘泥沼泽","黑色盾牌","塞拉摩"},sec={{t="能解惑的铁匠",b="维米斯为自己无法在盾牌的事上帮上多少忙而致歉，但他指出了一个能帮忙的人。你受命带着盾牌去找卡兹·双链，他是最好的铁匠之一，在塞拉摩的铁匠铺照看熔炉。也许卡兹能告诉你一些关于这面盾牌的事。"},{t="铁匠的看法",b="卡兹仔细查看了这块铁，觉得它很有意思。这不是卡兹自己的作品，也绝不是他所知的任何一位海这边的铁匠打造的。"}},faq={{q="谁派你去查验盾牌？",a="塞拉摩的盖兰·维米斯队长，他很抱歉自己帮不上多少忙，便指引你去找更合适的人。",al={"谁给予黑色盾牌","黑色盾牌任务起始者","谁开启黑色盾牌"}},{q="卡兹·双链是谁？",a="一位在塞拉摩的铁匠铺照看熔炉的铁匠。维米斯认为他是最好的铁匠之一。",al={"卡兹·双链","塞拉摩的铁匠是谁"}},{q="拿给卡兹看的是哪面盾牌？",a="被熏黑的铁盾牌。",al={"被熏黑的铁盾牌","给 卡兹 看什么盾牌"}}},fp="16,93,19.199.0,19.162.1,36.90.0,23.106.0,28.26.0"}
P.entries["quest:132"] = {n="迪菲亚兄弟会",s="在赤脊山与西部荒野的边缘，黑衣威利向格里安·斯托曼发出警告。他的情报表明，迪菲亚的威胁远不止劫掠，格里安需要查明这股势力究竟延伸到了何处。",h="在赤脊山与西部荒野的边缘，黑衣威利向格里安·斯托曼发出警告。他的情报表明，迪菲亚的威胁远不止劫掠，格里安需要查明这股势力究竟延伸到了何处。",kw={"迪菲亚潜行者","豺狼人","地精","格里安·斯托曼","狗头人","哨兵岭","西部荒野","黑衣威利","威利的便笺"},ang={["class:Rogue"]="身为潜行者，你能看出黑衣威利如何周旋于亡命之徒与有用线人的身份之间，也能看出地下犯罪势力中的人脉如何传递战时情报。",["faction:Alliance"]="对联盟而言，人类亡命之徒、豺狼人和地精之间的协作，暴露了暴风城西部边境严重的防务空缺。",["race:Human"]="身为人类，你明白这封便笺证实了一件事：那些劫掠西部荒野与赤脊山农家的匪徒，正在执行一场蓄谋已久、统一协调的行动。"},sec={{t="危险的密信",b="黑衣威利说，透露自己知道的事情可能让他丢掉性命。他的密封便笺描述了兄弟会如何协调乡间各处的团伙，尽管这些团伙通常彼此敌对。"},{t="意想不到的盟友",b="威利警告说，迪菲亚已经在周围建立起一个令人不安的关系网。这些蒙着红色面罩的亡命之徒招募了成群的豺狼人、挖矿的狗头人和地精工程师，不再单独行动。他们凶蛮的武力、挖掘的劳力和机械方面的巧思，表明这项图谋超出了人民军最初的预料。"},{t="斯托曼的不安与倚重",b="格里安·斯托曼对威利毫无好感。他毫不掩饰自己的懊悔，当初有机会时，竟没有让那个无赖自生自灭。然而，西部荒野容不得意气用事。人民军必须利用一切能找到的有用情报。"}},faq={{q="威利的便笺讲了什么？",a="黑衣威利的便笺警告说，迪菲亚潜行者正在与豺狼人、狗头人和地精工程师协同行动。它告诉人民军，这些亡命之徒正在筹备一场远非小打小闹的劫掠所能比拟的行动。",al={"威利的便笺","便笺里写了什么","黑衣威利的便笺"}},{q="黑衣威利是谁？",a="黑衣威利是驻留在赤脊山湖畔镇的一名可疑线人。格里安·斯托曼认为他是个不可信的恶棍，但威利在地下犯罪势力中人脉广泛，掌握着有关迪菲亚活动的关键情报。",al={"威利是谁","黑衣威利的背景故事","威利与湖畔镇"}},{q="迪菲亚为什么要与豺狼人和狗头人结盟？",a="迪菲亚利用当地生物控制地盘，并获取廉价劳力。豺狼人充当凶蛮的散兵，牵制守卫，狗头人在当地矿井中挖掘隧道，地精技师则提供重型机械和爆破工具。",al={"迪菲亚为什么利用豺狼人","狗头人与迪菲亚","迪菲亚的盟友"}},{q="格里安·斯托曼为什么不喜欢威利？",a="格里安·斯托曼曾是一名纪律严明的士兵，在他眼中，威利不过是个寻常的扒手和罪犯。他后悔当初没有把威利送进监狱，尽管威利在地下犯罪势力中的消息渠道不可或缺。",al={"斯托曼与威利","为什么讨厌威利"}},{q="这封信在民兵的调查中起到了什么作用？",a="威利的信让民兵的调查从当地侦察转向了更深层的迪菲亚阴谋。信件送回后，斯托曼开始追查这场阴谋的首脑与集结地点。",al={"迪菲亚任务链阶段","这是什么任务"}},{q="暴风城为什么不处理这场威胁？",a="国王瓦里安·乌瑞恩失踪后，暴风城的贵族拒绝调拨王室士兵或资金来保卫西部荒野。守卫这片地区的重担，落在了斯托曼那支拼凑起来的人民军肩上。",al={"暴风城援助西部荒野","卫兵在哪里"}}},fx={["3bfb9fad"]={q="黑衣威利为什么派你去找格里安·斯托曼？",a="威利从各种传闻中拼凑出线索，得知迪菲亚潜行者正在与豺狼人、狗头人和地精联手，酝酿一场可怕的阴谋。他很清楚，掌握这些危险的秘密会让自己性命难保。威利把知道的事情写进给格里安·斯托曼的密信，将采取行动的重担交给人民军，既为挫败阴谋尽了一份力，也让自己安全地置身险境之外。",al={"威利为什么帮忙","黑衣威利的动机","为什么送威利的信"}},["6813809b"]={q="威利为什么要依靠你，而不亲自送信？",a="威利是个身负罪行的盗贼，正藏身湖畔镇的旅店，避开当局和迪菲亚的耳目。穿越敌人出没的地域，一路步行前往西部荒野，会让他陷入极大的危险，而他与格里安·斯托曼的过往也使他成为一个遭人厌恶的家伙，而非受欢迎的客人。你是个能干的信使，可以悄然穿过荒野，将警讯直接送到哨兵岭。",al={"威利为什么需要帮忙","威利为什么不能去西部荒野","威利的信为什么要代送"}}},fp="22,190,20.216.0,18.318.0,29.235.0,27.217.0,23.229.0,50.238.0,41.187.0,61.203.0,41.193.0"}
P.entries["quest:1320"] = {n="黑色盾牌",s="卡兹·双链正在研究那面与树荫旅店谜案有关的黑色盾牌。一个细节险些被忽略，卡兹让你带着发现前往塞拉摩，向盖兰·维米斯队长报告。",h="卡兹·双链正在研究那面与树荫旅店谜案有关的黑色盾牌。一个细节险些被忽略，卡兹让你带着发现前往塞拉摩，向盖兰·维米斯队长报告。",kw={"黑色盾牌","卡兹·双链","尘泥沼泽","加瑞安·维米斯","树荫旅店","牛头人","塞拉摩"},sec={{t="烧毁的皮带",b="卡兹·双链检查黑色盾牌时，险些漏掉了最后一个细节。盾牌背面的皮带已经烧毁，但看起来原本是为体型高大的人制作的。卡兹猜测是牛头人。卡兹能看出的只有这些，于是让你前往塞拉摩，将发现报告给盖兰·维米斯队长，并转达歉意，因为自己没能帮上更多忙。"},{t="维米斯的看法",b="盖兰·维米斯队长觉得卡兹的发现提供不了多少线索。不过，他表示会记在心上。他希望谜案的其他线索能逐渐拼凑起来，让事情的经过更加清楚。"}},faq={{q="卡兹·双链从盾牌上发现了什么？",a="盾牌背面的皮带已经烧毁，但看起来原本是为体型高大的人制作的。卡兹猜测是牛头人。",al={"卡兹 的发现","盾牌线索","黑色盾牌线索"}},{q="应该向谁报告卡兹的发现？",a="塞拉摩的盖兰·维米斯队长。",al={"盾牌的事向谁报告","交还黑色盾牌","盾牌的事去哪里报告"}}},fp="16,186,19.337.0,22.202.1,52.128.0,31.34.0"}
P.entries["quest:1321"] = {n="黑色盾牌",s="克罗格查看了被熏黑的铁盾牌，没发现什么异常。克罗格建议让铁匠杜高尔检查一下，虽然不抱太大希望，还是派你前往蕨墙村。",h="克罗格查看了被熏黑的铁盾牌，没发现什么异常。克罗格建议让铁匠杜高尔检查一下，虽然不抱太大希望，还是派你前往蕨墙村。",kw={"黑色盾牌","被熏黑的铁盾牌","蕨墙村","杜高尔","尘泥沼泽","克罗格"},sec={{t="再请人看看",b="克罗格没看出这面盾牌有什么异常。克罗格说，铁匠杜高尔也许能看出更多名堂，但提醒你别抱太大希望。杜高尔就在蕨墙村。"},{t="杜高尔的答复",b="杜高尔说这是一面好盾牌，结实又厚重。不过，杜高尔不需要它，因为他是打造盾牌的，不是收购盾牌的，还说你应该知道这一点。"}},faq={{q="是谁让你带着盾牌去找杜高尔的？",a="克罗格，他查看了被熏黑的铁盾牌，没发现什么异常。",al={"谁提供黑色盾牌任务","在哪里接黑色盾牌任务","黑色盾牌任务提供者"}},{q="在哪里能找到杜高尔？",a="杜高尔是蕨墙村的铁匠。",al={"杜高尔位置","杜高尔在哪里","寻找杜高尔"}},{q="克罗格为什么让你去找杜高尔？",a="克罗格希望铁匠能看出这面盾牌的更多名堂，不过他并不指望能有什么收获。",al={"为什么拜访杜高尔","为什么把盾牌给铁匠看"}}},fp="16,84,16.180.0,15.150.1,40.87.0,26.48.0,33.99.0"}
P.entries["quest:1322"] = {n="黑色盾牌",s="在蕨墙村，杜高尔发现盾牌边缘刻着文字，但烧焦的残渣遮住了字迹。清除残渣需要酸液，杜高尔请你从沼泽里的暗牙蜘蛛身上收集六个毒囊。",h="在蕨墙村，杜高尔发现盾牌边缘刻着文字，但烧焦的残渣遮住了字迹。清除残渣需要酸液，杜高尔请你从沼泽里的暗牙蜘蛛身上收集六个毒囊。",kw={"酸性毒囊","蕨墙村","暗牙","杜高尔","尘泥沼泽","黑色盾牌"},sec={{t="清理盾牌边缘",b="杜高尔能看出盾牌边缘刻着文字，但烧结在上面的污垢让字迹难以辨认。酸液可以清除污垢，而沼泽里的暗牙蜘蛛携带的毒液正好能派上用场。杜高尔需要六个这种蜘蛛的酸性毒囊来清理盾牌。"},{t="毒囊送达之后",b="杜高尔讨厌那些大得没法一屁股坐死的蜘蛛，随后向你道谢，感谢你带来了毒囊。杜高尔撕开毒囊，把里面的毒液倒在盾牌上。"}},faq={{q="谁需要蜘蛛毒液？",a="蕨墙村的杜高尔。",al={"谁提供黑色盾牌","杜高尔任务","谁开启黑色盾牌"}},{q="杜高尔为什么需要毒囊？",a="杜高尔想用酸液清除遮住盾牌边缘字迹的烧焦残渣，暗牙蜘蛛的毒液就能胜任。",al={"为什么需要蜘蛛酸液","酸性毒囊的用途","为什么清理盾牌"}},{q="酸性毒囊从哪里来？",a="来自生活在蕨墙村附近沼泽里的暗牙蜘蛛。",al={"哪些蜘蛛有毒囊","暗牙蜘蛛位置","哪里获取酸性毒液"}},{q="杜高尔需要多少个毒囊？",a="六个酸性毒囊。",al={"需要多少个毒囊"}}},fp="16,175,16.251.0,20.150.1,30.52.0,32.116.0,41.94.0,31.35.0"}
P.entries["quest:1323"] = {n="黑色盾牌",s="杜高尔把盾牌擦拭得足够干净，能看出上面的字似乎是莫萨恩，但杜高尔对这个名字一无所知。蕨墙村的克罗格认识很多人，所以杜高尔让你去那里问问。",h="杜高尔把盾牌擦拭得足够干净，能看出上面的字似乎是莫萨恩，但杜高尔对这个名字一无所知。蕨墙村的克罗格认识很多人，所以杜高尔让你去那里问问。",kw={"酸液","黑色盾牌","蕨墙村","杜高尔","尘泥沼泽","克罗格","莫萨恩"},sec={{t="盾牌边缘的名字",b="杜高尔倒的酸液有点太多了，不过稍加擦拭，便显露出一些仍难以辨认的文字，似乎写着莫萨恩。杜高尔对这个名字一无所知。蕨墙村的克罗格认识很多人，所以杜高尔让你去找克罗格谈谈。"},{t="克罗格的答复",b="克罗格觉得莫萨恩这个名字很耳熟，却想不起在哪里听过，希望过一阵子能想起来。克罗格还说，这大概无关紧要，因为盾牌可能来自各种地方，本身并没有什么含义。"}},faq={{q="杜高尔是谁？",a="就是蕨墙村那个一直用酸液清洗盾牌，想辨认上面文字的人。",al={"杜高尔","谁提供黑色盾牌"}},{q="盾牌上是什么名字？",a="杜高尔认为上面的字是莫萨恩，虽然很难辨认，而且他从未听说过叫这个名字的人。",al={"盾牌上是什么名字","莫萨恩是谁","盾牌铭文名字"}},{q="为什么要找克罗格谈论盾牌？",a="杜高尔不知道莫萨恩是谁，但他说克罗格认识很多人。",al={"为什么找克罗格交谈","克罗格是谁"}},{q="克罗格在哪里？",a="克罗格在蕨墙村。",al={"克罗格位置","在哪里找到克罗格"}}},fp="16,147,17.231.0,13.196.1,14.67.0,27.96.0,34.68.0,22.31.0"}
P.entries["quest:133"] = {n="食尸鬼假人",s="亚伯克隆比说，亡者正围逼他在暮色森林的小屋。他请你收集食尸鬼的肋骨，做成一个骇人的稻草人，守护他的家。",h="亚伯克隆比说，亡者正围逼他在暮色森林的小屋。他请你收集食尸鬼的肋骨，做成一个骇人的稻草人，守护他的家。",kw={"亚伯克隆比","噬骨者","夜色镇","暮色森林","塑像","食腐者","食尸鬼的肋骨","隐士"},ang={["class:Paladin"]="身为圣骑士，你可以猎杀食腐者和噬骨者，净化暮色森林的土地，但把它们的残骸交给一个隐士，总让人感到不安。",["class:Priest"]="身为牧师，你可以帮助一位身处幽暗鬼魂之间、惊恐不安的隐士。用收集来的残骸制作塑像，可能会让你胃里翻腾。",["faction:Alliance"]="守夜人竭力保护道路，因此，像亚伯克隆比这样孤居林中的居民，只能依靠途经的联盟旅人，保护自己免受躁动亡者的侵扰。"},sec={{t="隐士的困境",b="亚伯克隆比住在夜色镇的守卫范围之外，独自栖身于暮色森林幽暗的林木间。食腐者和噬骨者等食尸鬼在荒野中肆意游荡。他说，饥肠辘辘的行尸最近撞塌了他的屋墙，因此请你收集它们的肋骨。他希望用一具骇人的塑像，让饥饿的亡者远离他的家。"},{t="古怪的防御",b="比起守夜人或为木屋加固墙壁，亚伯克隆比更相信一个阴森的计划。他认为，用食尸鬼残骸制成的塑像能吓跑其他四处觅食的亡者。用被杀死的亡灵搭成稻草人令人不安，但为了挣些急需的钱币，暮色森林的旅人往往还是会照这位隐士的要求去做。"}},faq={{q="亚伯克隆比住在哪里？",a="亚伯克隆比住在暮色森林西部的一间孤零零的小屋里，就在乌鸦岭墓地的东北方向，远离夜色镇的庇护。",al={"亚伯克隆比位置","亚伯克隆比的小屋在哪","暮色森林隐士小屋"}},{q="亚伯克隆比为什么需要食尸鬼的肋骨？",a="亚伯克隆比说，成群的食尸鬼正在猛撞他小屋的墙壁。他打算用它们的骨头做成一个可怕的稻草人，吓跑四处觅食的亡灵。",al={"食尸鬼的肋骨用途","为什么要食尸鬼的肋骨","塑像有什么用"}},{q="哪些生物会掉落食尸鬼的肋骨？",a="你可以从游荡在暮色森林道路和墓地中的亡灵身上收集肋骨：食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼。",al={"哪里获取肋骨","食尸鬼的肋骨掉落","哪些食尸鬼掉落肋骨"}},{q="用亡灵做成的稻草人真的能驱赶食尸鬼吗？",a="亡灵很少畏惧什么，因此经验丰富的怪物猎人对亚伯克隆比的计划心存疑虑。这位隐士却坚持己见，而在这片令人绝望的森林里，很少有人会质疑一个愿意付钱的人。",al={"塑像对食尸鬼有效吗","食尸鬼稻草人的原理"}},{q="亚伯克隆比为什么不干脆搬到夜色镇？",a="亚伯克隆比选择独居，远离守夜人和镇上的管辖。尽管暮色森林危机四伏，他还是宁愿照料自己的小屋，依靠那些古怪的防御手段。",al={"为什么住在森林里","亚伯克隆比为什么不搬走","夜色镇安全"}},{q="收集完肋骨之后要做什么？",a="亚伯克隆比拿到食尸鬼的肋骨后，又提出了另一个古怪的难题：当地的食人魔偷走了他的财物，他派你前往荒野对付它们。",al={"后续任务","食尸鬼假人之后做什么"}}},fp="15,130,17.313.0,17.305.0,28.135.0,37.160.0,36.155.0,56.165.0,53.182.0,41.166.0"}
P.entries["quest:1338"] = {n="卡尔·雷矛的订单",s="在洛克莫丹，巡山人卡尔·雷矛要将一份盾牌订单送往南方的暴风城。他请你把订单交给他信赖的护甲锻造师弗伦·长须。",h="在洛克莫丹，巡山人卡尔·雷矛要将一份盾牌订单送往南方的暴风城。他请你把订单交给他信赖的护甲锻造师弗伦·长须。",kw={"护甲锻造师","矮人区","弗伦·长须","铁炉堡","洛克莫丹","盾牌","雷矛","暴风城"},ang={["faction:Alliance"]="作为联盟旅人，你可以看到卡兹莫丹的矮人堡垒与暴风城之间的贸易和文化联系，矿道地铁将两地连在一起。",["profession:Blacksmithing"]="作为铁匠，你途经暴风城时，或许会留意弗伦·长须，这位出色的护甲锻造师甚至在其他王国也享有盛名。",["race:Dwarf"]="作为矮人，你能看到一个氏族的声誉可以传得多远。雷矛的订单也引出了一个疑问：一位护甲锻造大师为何会选择人类的石墙，而非铁炉堡。"},sec={{t="值得远行的盾牌",b="雷矛只信任这位铁匠来锻造他的盾牌。他愿意付出丰厚的报酬，请人将这份委托送到弗伦·长须手中，尽管暴风城远在洛克莫丹以南。"},{t="从铁炉堡到矮人区",b="雷矛不明白，弗伦为何要远离铁炉堡和大锻炉，到那么远的地方工作，许多矮人都在那里安家。他猜想，暴风城的人类一定付给这位铁匠一笔巨款。\n\n订单送到铁砧旁的弗伦手中时，得知声名显赫的雷矛氏族前来委托，他感到十分自豪。他迫不及待地准备锻造这面盾牌。"}},faq={{q="巡山人卡尔·雷矛是谁？",a="巡山人卡尔·雷矛是驻守洛克莫丹的联盟哨兵。他出身于骄傲而有影响力的雷矛氏族，是守卫山口与谷地的矮人巡山人之一。",al={"巡山人卡尔·雷矛","谁提供任务","任务给予者"}},{q="弗伦·长须是谁？",a="弗伦·长须是一位技艺精湛的矮人护甲锻造师，住在暴风城的矮人区。他以锻造精良盾牌和护甲闻名，声誉远播至北方的卡兹莫丹。",al={"弗伦·长须","弗伦 是谁","那位护甲锻造师"}},{q="弗伦为何住在暴风城，而不是铁炉堡？",a="弗伦·长须在暴风城的矮人区工作，为人类贵族、城市卫兵和往来的冒险者提供服务。巡山人卡尔·雷矛不明白，一位矮人大师为何会离开铁炉堡，不过弗伦很可能从人类那里赚到了丰厚的报酬。",al={"弗伦 为何在暴风城","为何选择 矮人区","弗伦 离开铁炉堡"}},{q="矿道地铁在递送这份订单时起什么作用？",a="携带雷矛信件的旅人通常从洛克莫丹向西前往铁炉堡，再乘坐矿道地铁，沿地下线路抵达暴风城的矮人区，弗伦的铁匠铺就在那里。",al={"前往暴风城","如何前往暴风城","矿道地铁"}},{q="这个任务的前置任务是什么？",a="在委托你前往暴风城送信之前，巡山人卡尔·雷矛会在洛克莫丹通过“巡山人卡尔·雷矛的任务”考验你的勇气与可靠程度。",al={"前置条件","前置任务","巡山人卡尔·雷矛的任务"}},{q="弗伦·长须会立刻锻造盾牌吗？",a="弗伦·长须收到信件，得知委托来自声名显赫的雷矛氏族后，便接受了委托。他承诺会在当天结束之前动锤打造这面盾牌。",al={"接下来会发生什么","后续任务","弗伦 的反应"}}},fx={["317873dc"]={q="巡山人卡尔·雷矛为什么想办成这件事？",a="巡山人卡尔·雷矛需要一面新盾牌，对弗伦·长须的手艺推崇备至，认为这位护甲锻造师的技艺无人能及。雷矛虽然不明白，一位矮人锻造大师为何要远离铁炉堡，住到暴风城的人类中间，但他不愿接受品质较差的防具，坚持要一面由弗伦亲手锻造的盾牌。",al={"雷矛为什么需要盾牌","巡山人卡尔·雷矛的动机","为什么找弗伦订做"}},["02c191af"]={q="巡山人卡尔·雷矛为什么请你帮忙，而不亲自前往？",a="雷矛是驻守洛克莫丹高山隘口的现役巡山人，不能随意放弃守卫矮人边境的职责，长途跋涉南下前往人类的领地。把委托送到暴风城的矮人区需要走很远的路，因此他只能求助于有闲暇的冒险者，请他们收取一份应得的报酬，替他捎去信件。",al={"为什么派冒险者去找弗伦","雷矛为什么不能送订单","雷矛的订单为什么要代送"}}},fp="17,152,26.173.0,38.326.0,29.208.0,23.180.0,54.242.0,57.195.0,29.160.0,50.191.0"}
P.entries["quest:1339"] = {n="巡山人卡尔·雷矛的任务",s="驻守洛克莫丹的巡山人卡尔·雷矛急需一名信使，替他处理山谷之外的事务。巡山人卡德雷尔让你去找他，因为巡山人卡尔·雷矛无法擅离职守。",h="驻守洛克莫丹的巡山人卡尔·雷矛急需一名信使，替他处理山谷之外的事务。巡山人卡德雷尔让你去找他，因为巡山人卡尔·雷矛无法擅离职守。",kw={"哨塔","铁炉堡","洛克莫丹","巡山人卡德雷尔","巡山人卡尔·雷矛","信使","卡尔·雷矛的订单","塞尔萨玛"},ang={["faction:Alliance"]="身为联盟旅者，你帮助当地巡山人传递公文，让铁炉堡在东部各地的驻军保持补给畅通、行动协调。",["race:Dwarf"]="身为矮人，你或许会自然而然地感到，有责任帮助这位出身著名雷矛家族的同胞，维护遍及卡兹莫丹的氏族情谊。"},sec={{t="急需信使的守卫",b="北部哨塔是巡山人卡尔·雷矛的岗位，守卫职责让他无法离开洛克莫丹。穴居人和四处游荡的野兽让巡山人们疲于应付。因此，巡山人卡德雷尔会指引有能力的旅者，去帮助那些无法擅离职守的卫兵。巡山人卡尔·雷矛需要一名信使，替他处理远在这片地区之外的事务。"},{t="从哨塔通往远方",b="你在北部哨塔顶上找到了巡山人卡尔·雷矛，他正眺望着山谷。他出身于显赫的雷矛氏族，在塞尔萨玛的边境防务之外，还有事务需要处理。你替他携带信件和物资，跨越地区边界。你的道路从洛克湖畔延伸至卡兹莫丹的大道。"}},faq={{q="在哪里能找到巡山人卡尔·雷矛？",a="巡山人卡尔·雷矛在洛克莫丹北部的哨塔顶上值守，俯瞰周围的小径。",al={"巡山人卡尔·雷矛位置","巡山人卡尔·雷矛在哪里","寻找巡山人卡尔·雷矛的哨塔"}},{q="这个任务由谁发起？",a="巡山人卡德雷尔在洛克莫丹的塞尔萨玛附近巡逻，他会指引你前往巡山人卡尔·雷矛的哨塔。",al={"谁给予巡山人卡尔·雷矛的任务","任务给予者","巡山人卡德雷尔位置"}},{q="巡山人卡尔·雷矛为什么需要冒险者？",a="巡山人卡尔·雷矛无法离开哨塔的岗位。他的私事远在洛克莫丹之外，因此需要一位旅者替他送信。",al={"为什么需要信使","巡山人卡尔·雷矛的难题","巡山人卡尔·雷矛需要什么"}},{q="向巡山人卡尔·雷矛报到后会怎样？",a="向巡山人卡尔·雷矛报到便完成了第一步，并开启他的后续递送任务“卡尔·雷矛的订单”，带你前往另一片地区。",al={"下一个任务","巡山人卡尔·雷矛的任务之后的任务","巡山人卡尔·雷矛后续任务"}},{q="这与奥特兰克的雷矛卫队有关吗？",a="巡山人卡尔·雷矛继承了雷矛氏族的姓氏与血脉，这个氏族以雷矛卫队及其采矿远征而闻名。他在这里的事务只是一桩当地的小差事。",al={"与雷矛氏族的联系","奥特兰克山谷的雷矛","是否为奥特兰克山谷的雷矛氏族"}},{q="部落玩家在这里有对应的任务吗？",a="没有。洛克莫丹是隶属联盟的矮人领地，这里的巡山人一见到部落旅者就会发动攻击。",al={"部落版本","部落能否完成"}}},fx={d38a276d={q="巡山人卡德雷尔为什么想办成这件事？",a="巡山人卡德雷尔只是在替同僚留意路人、传递消息。他驻守在道路旁，知道巡山人卡尔·雷矛需要一个能干的跑腿人，去办一件远方的差事，而值勤的卫兵无法擅离职守。卡德雷尔发现了一位有能力的旅人，便把消息转告出去，好让雷矛找到所需的帮手。",al={"卡德雷尔为什么让人去找雷矛","巡山人卡德雷尔的动机","为什么找雷矛谈话"}}},fp="28,185,30.320.0,27.323.0,38.115.0,22.96.0,38.140.0,42.141.0,50.168.0,47.116.0"}
P.entries["quest:134"] = {n="食人魔潜行者",s="在暮色森林西部，亚伯克隆比派旅人前往沃古尔食人魔山的食人魔据点。他说，食人魔在他采集时伏击了他，抢走了一箱无法替代的草药和工具。",h="在暮色森林西部，亚伯克隆比派旅人前往沃古尔食人魔山的食人魔据点。他说，食人魔在他采集时伏击了他，抢走了一箱无法替代的草药和工具。",kw={"亚伯克隆比","箱子","暮色森林","隐士","食人魔","沃古尔"},ang={["class:Paladin"]="身为圣骑士，看到亚伯克隆比取回箱子时那急切而隐秘的喜悦，你或许会心生警惕，不愿盲目帮助这位离群索居的隐士。",["class:Warlock"]="身为术士，你或许能听出，亚伯克隆比失言时赞颂的是黑暗法术，而非仅仅出于对植物的喜爱。",["profession:Herbalism"]="身为草药师，你或许会好奇，究竟是什么奇异的植物，能让亚伯克隆比如此急于从食人魔山找回箱子。"},sec={{t="隐士遗失的物品",b="亚伯克隆比是一位年迈的隐士，住在暮色森林西部潮湿的道路旁，他说自己在收集物资时遭到了袭击。南方食人魔山的蛮徒赶走了他，他落下了一个结实的木箱，里面装满珍贵的草药和精密的仪器。"},{t="沃古尔的威胁",b="沃古尔食人魔山位于暮色森林南部，那里的食人魔充满敌意，时常袭扰毫无戒备的旅人。亚伯克隆比的箱子就放在入口附近，周围尽是咆哮的蛮徒和施法的食人魔法师。"},{t="一时失言",b="亚伯克隆比取回物品后，古怪的举止变成了近乎癫狂的兴奋。他差点高声赞颂“亡——”，却及时收住了话头，转而向你道谢。随后，他迫不及待地闭门独处，要在黑暗中用上这些失而复得的物资。"}},faq={{q="亚伯克隆比是谁？",a="亚伯克隆比是一位古怪的隐士，住在暮色森林西部一间破旧的小屋里。他表现得虚弱无助，似乎需要帮助，但他狂乱的举止和奇怪的要求暗示着更阴暗的动机。",al={"亚伯克隆比的故事","谁给了这个任务","隐士是谁"}},{q="食人魔把亚伯克隆比的箱子带到哪里去了？",a="食人魔把亚伯克隆比的箱子带到了暮色森林南部的沃古尔食人魔山。它就露天放在食人魔山入口外的泥地上。",al={"箱子在哪里","箱子位置","沃古尔的箱子"}},{q="暮色森林为什么会有食人魔？",a="沃古尔氏族的食人魔在暮色森林南部崎岖的丘陵中占据了一席之地。他们生性凶狠，伺机劫掠，抢劫过路者，伏击独行的旅人，并把赃物囤积在食人魔山周围。",al={"暮色森林的食人魔","沃古尔食人魔的来历","这里为什么有食人魔"}},{q="箱子里究竟装着什么？",a="亚伯克隆比声称，箱子里装着他遇袭时丢下的稀有草药和专用采集工具。能找回这些东西，他欣喜若狂。",al={"亚伯克隆比丢了什么","箱中物品"}},{q="亚伯克隆比收到箱子时差点说了什么？",a="亚伯克隆比取回箱子时，开口想要感谢另一个人，却突然收住话头，转而向你道谢。他满心欢喜地期待着接下来的夜晚。",al={"感谢亡","亚伯克隆比刚才在说什么","亚伯克隆比的台词"}},{q="这个任务与食人魔山的其他任务有关吗？",a="前往沃古尔食人魔山的旅人，也可能正在为维克托·安特拉斯收集食人魔的单片眼镜。",al={"食人魔山任务","沃古尔附近的任务"}}},fp="12,192,21.250.0,18.204.0,20.264.1,19.201.0,45.143.0,32.210.0,34.145.1,57.170.1,57.100.0"}
P.entries["quest:135"] = {n="迪菲亚兄弟会",s="在西部荒野，格里安·斯托曼怀疑迪菲亚潜行者与暴风城昔日的石匠行会有关。他派你带着威利的便笺前往暴风城。",h="在西部荒野，格里安·斯托曼怀疑迪菲亚潜行者与暴风城昔日的石匠行会有关。他派你带着威利的便笺前往暴风城。",kw={"兄弟会","迪菲亚","格里安·斯托曼","马迪亚斯·肖尔","旧城区","si:7","石匠","西部荒野","威利的便笺"},ang={["class:Rogue"]="在SI:7总部，你见到了马迪亚斯·肖尔，这位暴风城盗贼与间谍的大师。他的工作将西部荒野的地方动乱与更广泛的谍报活动联系起来。",["faction:Alliance"]="身为联盟的一员，你看到了联盟主要王国内部的裂痕。有些威胁来自遭到背叛的民众，而非外来的怪物。",["race:Human"]="身为暴风城的人类，你看到西部荒野无法无天的边疆乱局，与首都重建后悬而未决、令人怨愤的政治丑闻交织在一起。"},sec={{t="无意间的透露",b="威利提到的石匠兄弟会引起了格里安的注意。这个公会在第一次兽人战争之后重建了暴风城，但许多人相信它早已四散或解散。如果迪菲亚与这个公会有关，那么西部荒野乡间的叛乱或许就不只是一伙匪徒作乱。"},{t="旧城区的秘密",b="格里安无法在哨兵岭验证自己的怀疑，于是派你去见马迪亚斯·肖尔，他是暴风城秘密情报机构军情七处的首领。肖尔在旧城区的兵营办公，搜集来自王国各地的传闻与秘密。他或许能查清迪菲亚潜行者的来历。"},{t="王冠之上的阴影",b="当你把威利的便笺交给马迪亚斯·肖尔时，他看出西部荒野的叛乱比格里安所了解的更为深远。其中的政治纠葛也更加复杂。这场叛乱的根源可以追溯到暴风城动荡的过去。"}},faq={{q="格里安·斯托曼为什么派你去暴风城？",a="威利的便笺提到了石匠协会，让格里安·斯托曼怀疑匪患背后藏着政治阴谋。他派你去见马迪亚斯·肖尔，以确认其中的联系。",al={"为什么去暴风城","为什么接暴风城任务","斯托曼暴风城差事"}},{q="马迪亚斯·肖尔是谁？",a="马迪亚斯·肖尔领导着军情七处，这是暴风城负责秘密情报与间谍活动的机构。他在旧城区的兵营办公。",al={"肖尔是谁","马迪亚斯·肖尔的职责","si7首领"}},{q="在哪里能找到马迪亚斯·肖尔？",a="你可以在暴风城旧城区的兵营内，军情七处总部的二楼找到马迪亚斯·肖尔。",al={"肖尔在哪里","肖尔的位置","寻找马迪亚斯·肖尔"}},{q="迪菲亚与石匠协会有什么联系？",a="暴风城在第一次兽人战争中被毁后，石匠行会重建了这座城市。格里安·斯托曼怀疑威利提到这个公会，意味着它与迪菲亚有关，而马迪亚斯·肖尔或许能证实或否定这一联系。",al={"迪菲亚与石匠","迪菲亚是石匠吗","石匠的联系"}},{q="威利的便笺是什么？",a="威利的便笺出自黑衣威利之手，格里安·斯托曼以前曾与这个无赖打过交道。便笺警告说，迪菲亚正与豺狼人、狗头人和地精密谋。威利提到的石匠协会，或许能将迪菲亚潜行者与昔日的公会联系起来。",al={"威利的便笺","便笺是什么","交给肖尔的便笺"}},{q="伯瓦尔·弗塔根公爵或那位年幼的国王知道这件事吗？",a="国家机密事务会先经由马迪亚斯·肖尔和SI:7处理，之后才呈报伯瓦尔·弗塔根公爵与王室。肖尔说，这件事可能比斯托曼所了解的更加复杂。",al={"国王知道吗","伯瓦尔知道吗","暴风城政府是否知情"}}},fx={f764ce01={q="格里安·斯托曼为什么派你去，而不派一名人民军士兵？",a="人民军光是保卫哨兵岭和西部荒野各处零散的农场，就已疲于应付。格里安·斯托曼抽不出能战斗的守军，让他们离开前线，往返都城传递消息。况且，你这个外来者已经拼凑出了威利提供的线索，因此成了值得信任的信使，可以把涉及机密的问询直接带给暴风城的间谍首领。",al={"为什么派人送信","为什么不派民兵","斯托曼为什么需要帮忙"}}},fp="22,147,20.262.0,16.290.0,25.216.1,49.178.0,20.125.0,29.118.0,62.212.1,21.254.0,53.181.0"}
P.entries["quest:1358"] = {n="给赫布瑞姆的样本",s="在十字路口，药剂师赫布瑞姆正等待一颗从海那边送来的狼心。药剂师金格从幽暗城寄出这颗狼心，以支持被遗忘者在卡利姆多中部的研究。",h="在十字路口，药剂师赫布瑞姆正等待一颗从海那边送来的狼心。药剂师金格从幽暗城寄出这颗狼心，以支持被遗忘者在卡利姆多中部的研究。",kw={"药剂师赫布瑞姆","药剂师金格","十字路口","皇家药剂师学会","给赫布瑞姆的样本","贫瘠之地","幽暗城","狼心样本"},ang={["faction:Horde"]="身为部落的一员，你看到兽人和牛头人欢迎被遗忘者协助保卫十字路口。药剂师们悄然研究染疫遗骸，为宁静的贫瘠之地带来了一丝不安。",["race:Undead"]="身为Undead，你将皇家药剂师学会受污染的样本运往世界各地，参与他们凭借化学优势确立被遗忘者霸权的长远计划。"},sec={{t="跨海而来的疫病",b="药剂师金格从幽暗城寄出一份狼心样本，送往贫瘠之地的药剂师赫布瑞姆手中。皇家药剂师学会的实验已延伸至洛丹伦废墟之外。药剂师伦弗利尔从银松森林送来受污染的器官后，金格便试图将他们的研究扩展到世界各地。如今，一名信使正带着样本漂洋过海，前往赫布瑞姆那里。这位炼金师驻扎在贫瘠之地干燥的稀树草原上。"},{t="赫布瑞姆的野心",b="在十字路口，药剂师赫布瑞姆研究卡利姆多的本土野兽对来自瘟疫之地的化合物有何反应。这颗狼心或许能揭示那些毒素如何影响当地生物。赫布瑞姆相信，将它与当地生物一同解剖、试验，将有助于被遗忘者掌握毒药与非自然疾病。"}},faq={{q="送给赫布瑞姆的包裹里是什么？",a="包裹里装着一份狼心样本，由药剂师伦弗利尔从银松森林受腐化的狼身上取得，并由幽暗城的药剂师金格分析。",al={"样本是什么","狼心包裹","金格给了我什么"}},{q="药剂师赫布瑞姆为什么想要一颗受污染的狼心？",a="赫布瑞姆研究来自洛丹伦的毒素如何影响卡利姆多的野生动物。他希望借助这颗狼心的剧毒，为皇家药剂师学会研制更强效的药剂与毒药。",al={"赫布瑞姆为何需要狼心","赫布瑞姆的研究","赫布瑞姆的目的"}},{q="药剂师赫布瑞姆在哪里？",a="药剂师赫布瑞姆驻扎在贫瘠之地的十字路口，就在中央瞭望塔上层的外部平台上，那里可以俯瞰整个聚落。",al={"赫布瑞姆在哪里","赫布瑞姆的位置","寻找赫布瑞姆"}},{q="旅人如何从幽暗城前往十字路口？",a="从幽暗城外的飞艇塔搭乘飞艇，前往杜隆塔尔的奥格瑞玛。向南穿过杜隆塔尔，渡过怒水河进入贫瘠之地，再沿主路向西前往十字路口。",al={"前往十字路口","如何前往赫布瑞姆处","幽暗城到贫瘠之地"}},{q="药剂师伦弗利尔和药剂师金格是谁？",a="药剂师伦弗利尔和药剂师金格都是皇家药剂师学会的研究人员。伦弗利尔在银松森林的瑟伯切尔开展工作，而金格则在幽暗城的炼金房从事研究。",al={"伦弗利尔是谁","金格是谁","金格和伦弗利尔的故事"}},{q="这项研究为哪个阵营服务？",a="这项研究为希尔瓦娜斯·风行者女士麾下的被遗忘者和皇家药剂师学会服务。它推动了他们研制致命化学武器和生物武器的计划。",al={"谁会受益","这是为了希尔瓦娜斯吗","药剂师的目标"}}},fp="18,190,26.403.0,18.308.0,47.166.0,54.192.0,36.146.0,57.202.0,50.205.0,38.172.0"}
P.entries["quest:1359"] = {n="给金格的货物",s="药剂师伦弗利尔将给金格的货物从瑟伯切尔送往幽暗城。他从银松森林送来的狼心含有本应致这些野兽于死地的毒素，药剂师金格接收了这些狼心，供皇家药剂师学会研究。",h="药剂师伦弗利尔将给金格的货物从瑟伯切尔送往幽暗城。他从银松森林送来的狼心含有本应致这些野兽于死地的毒素，药剂师金格接收了这些狼心，供皇家药剂师学会研究。",kw={"炼金房","药剂师伦弗利尔","药剂师金格","瑟伯切尔","银松森林","幽暗城","狼心样本","给金格的货物"},ang={["faction:Horde"]="身为部落的一员，你知道，携带生物试剂的信使将瑟伯切尔这样的偏远前哨与幽暗城的领袖和研究殿堂联系在一起。",["race:Undead"]="身为Undead，你知道，来自洛丹伦的野外样本被送往首都废墟下的炼金实验室，推动着被遗忘者的科学发展。"},sec={{t="毒素异象",b="药剂师伦弗利尔在银松森林残破林地中游荡的狼身上发现了一种奇怪的特征。它们的心脏含有剧毒，本应足以致这些野兽于死地。伦弗利尔保存了几份组织样本，将其打包，准备送给幽暗城炼金房的同僚。"},{t="炼金房的目光",b="药剂师金格在皇家药剂师学会位于幽暗城的地下总部接收了这些保存下来的器官。这个组织致力于寻找强效瘟疫和新的炼金化合物，因此，能让宿主存活的毒素引起了他们的注意。金格欣然接收了这些样本，以此开启被遗忘者炼金研究网络中的后续实验。"}},faq={{q="狼心样本是什么？",a="这些样本是取自银松森林的狼并保存下来的组织。药剂师伦弗利尔在它们的心脏中发现了天然毒素，其毒性之强，本应让这些动物无法存活。",al={"狼心","狼心样本是什么","伦弗利尔的样本"}},{q="药剂师伦弗利尔是谁？",a="药剂师伦弗利尔是皇家药剂师学会的成员，驻扎在银松森林的瑟伯切尔。他主持对当地动植物的实地研究，为被遗忘者的炼金术收集原料与知识。",al={"伦弗利尔是谁","伦弗利尔与银松森林"}},{q="药剂师金格是谁？",a="药剂师金格是幽暗城炼金房区的一名炼金研究员。她研究送来的生物标本，为被遗忘者寻找新的毒素和炼金药剂。",al={"金格是谁","金格与幽暗城","药剂师金格的故事"}},{q="这批货物接下来会送往哪里？",a="药剂师金格接收并检查这些奇异的心脏组织，随后样本会被送往其他炼金前哨。其中一处便是药剂师赫布瑞姆的驻地，位于大洋彼岸的贫瘠之地。",al={"下一个任务","金格的货物之后发生什么","后续任务"}},{q="皇家药剂师学会为什么对狼心感兴趣？",a="皇家药剂师学会致力于寻找异常的毒物、疾病和生物异象。一头心脏含有致命毒素却仍能存活的野兽，或许能揭示研制新瘟疫和化合物的化学途径。",al={"药剂师为什么需要狼心","皇家药剂师学会狼心"}},{q="炼金房位于幽暗城的哪里？",a="炼金房位于幽暗城的西南翼。这里是皇家药剂师学会的主要实验室群和总部。",al={"幽暗城药剂师位置","金格在哪里","炼金房地图"}}},fp="16,206,15.270.0,28.346.0,32.186.0,28.227.0,24.187.0,35.190.1,62.192.0,39.144.0"}
P.entries["quest:136"] = {n="杉德尔船长的宝藏",s="在西部荒野的海岸边，杉德尔船长的宝藏始于一张破旧的羊皮纸地图。它指引你寻找他的私人储物箱，再循着线索穿过这片土地，寻找他藏匿的赃物。",h="在西部荒野的海岸边，杉德尔船长的宝藏始于一张破旧的羊皮纸地图。它指引你寻找他的私人储物箱，再循着线索穿过这片土地，寻找他藏匿的赃物。",kw={"杉德尔船长","储物箱","隐藏的宝藏","生锈的船锚","沉船","藏宝图","西部荒野海岸"},ang={["class:Rogue"]="身为潜行者，你知道沿着一片无法无天的海岸，循着亡故水手的地图寻宝有何价值。海盗的寻宝之旅，正适合无赖与私掠者。",["faction:Alliance"]="身为联盟冒险者，从西部荒野遍布沉船残骸的海岸寻回一笔财富，是王国边疆动荡中的一次小小胜利。沿海的鱼人威胁着这片海岸。"},sec={{t="水手最后的遗赠",b="杉德尔船长是一名老水手，葬身于西部荒野西海岸外的海中。他留下了隐晦的指引，免得自己辛苦积攒的财富沉入无尽之海，或被拾荒者夺走。你可以沿着他留下的线索追寻下去。西边的海岸上，沉船残骸随处可见，溺亡水手的亡魂徘徊不息。"},{t="生锈的船锚",b="在西部荒野西海岸，一只孤零零的生锈船锚浸在海浪中，标示着第一条线索的位置。一艘沉船附近，杉德尔船长的旧储物箱半埋在沙中，饱受海浪侵蚀。箱子里有海水、沙子，还有一只四处爬动的螃蟹，钳着杉德尔谜题的下一条线索。"}},faq={{q="杉德尔船长是谁？",a="杉德尔船长是一位老船长，他的地图上写着，他已葬身海底。他留下了地图和一连串线索，指向他藏匿的赃物。",al={"杉德尔船长背景故事","杉德尔是谁","杉德尔身世"}},{q="储物箱在哪里？",a="储物箱半埋在西部荒野西海岸的沙中，就在岸边一只孤零零的生锈船锚附近。",al={"储物箱位置","生锈的船锚在哪","寻找杉德尔的储物箱"}},{q="储物箱里装着船长的宝藏吗？",a="地图指向一只储物箱，箱子里藏着下一条线索，这场寻宝还要继续。",al={"宝藏在箱子里吗","储物箱里有什么","金币在哪"}},{q="杉德尔船长的寻宝之旅有多少条线索？",a="寻宝之旅分为四步，横跨西部荒野的海岸与乡野。它从地图开始，最终在近海的一座岛屿上找到杉德尔船长真正的宝箱。",al={"杉德尔任务要多久","有多少步","杉德尔任务链"}},{q="杉德尔船长为什么把宝藏埋在西部荒野？",a="杉德尔船长的地图从未说明他为何选择西部荒野。上面写着，他预料自己会葬身海底，希望循着线索而来的人能找到他的宝藏。这些线索散布在海岸及其上方的峭壁间。",al={"为什么藏起宝藏","为什么选西部荒野海岸"}},{q="部落玩家也能循着这张藏宝图寻宝吗？",a="可以。杉德尔船长的地图和线索不分阵营，任何抵达西部荒野海岸的冒险者都能循着他的踪迹寻宝。",al={"部落能做吗","部落杉德尔任务","阵营中立宝藏"}}},fx={["1a1a7b8a"]={q="杉德尔船长为什么留下这张藏宝图？",a="杉德尔船长知道自己即将葬身大海，却不愿让积攒的财富在海底腐朽，被世人遗忘。他布下了一连串隐晦的线索，留给那些有智慧、有胆识发现这张羊皮纸的人。他以此挑战满怀雄心的旅人，让他们寻找自己的旧衣箱，确保自己的名字和遗产在死后很久仍能流传。",al={"杉德尔为什么留下地图","杉德尔留下藏宝图的动机","为什么留下藏宝图"}}},fp="32,203,23.321.0,16.274.1,24.149.0,32.122.0,51.78.1,53.168.0,54.220.0,43.117.0"}
P.entries["quest:1360"] = {n="Reclaimed Treasures",s="克罗姆·粗臂请你从奥达曼取回一件珍贵的物品。他在铁炉堡等着你带回物品。",h="克罗姆·粗臂请你从奥达曼取回一件珍贵的物品。他在铁炉堡等着你带回物品。",kw={"箱子","铁炉堡","克罗姆·粗臂","north common hall","寻回珍宝","珍贵的物品","奥达曼"},ang={["faction:Alliance"]="作为联盟的一员，你受托将克罗姆·粗臂珍爱的物品从奥达曼带回铁炉堡交给他。",["race:Dwarf"]="作为一名矮人，你将帮助克罗姆·粗臂取回一件珍贵的物品，并将它送回铁炉堡交给他。"},sec={{t="遗失的物品",b="克罗姆·粗臂在奥达曼的 North Common Hall 有一个箱子。请你从箱中取出他珍爱的物品，带到铁炉堡交给他。"}},faq={{q="谁在寻求帮助？",a="克罗姆·粗臂请你从奥达曼的一个箱子里取回他珍爱的物品。",al={"谁想要这个","克罗姆·粗臂的请求"}},{q="克罗姆的箱子在哪里？",a="克罗姆·粗臂的箱子位于奥达曼的 North Common Hall。",al={"箱子在哪里","箱子位置"}},{q="克罗姆想取回什么？",a="克罗姆想取回奥达曼箱子里的珍爱之物。",al={"克罗姆的宝物","什么物品"}},{q="我该把它送到哪里？",a="把克罗姆·粗臂珍爱的物品带到铁炉堡交给他。",al={"送到哪里","把它交给克罗姆"}}},fp="19,100,17.134.0,23.83.0,22.61.0,25.62.0,20.63.0"}
P.entries["quest:1361"] = {n="雷戈萨·死门",s="在贫瘠之地，雷戈萨·死门号召身经百战的部落勇士向西进发。这位老练的战士正在召集志愿者，准备翻越群山，进军凄凉之地，那里有半人马氏族肆虐边境。",h="在贫瘠之地，雷戈萨·死门号召身经百战的部落勇士向西进发。这位老练的战士正在召集志愿者，准备翻越群山，进军凄凉之地，那里有半人马氏族肆虐边境。",kw={"贝尔戈洛姆·石槌","十字路口","凄凉之地","科卡尔","克鲁斯克","纳兹格雷尔","雷戈萨·死门","贫瘠之地","沃金"},ang={["class:Warrior"]="身为战士，你可以凭借正面作战的技艺和严明的纪律，在凄凉之地危机四伏的荒地上响应雷戈萨的号召。",["faction:Horde"]="部落正试图制服邻近凄凉之地的半人马，确保边境安全，以免他们深入贫瘠之地发动袭击。",["race:Tauren"]="身为牛头人，你的族人与半人马在卡利姆多中部的冲突已延续数代，因此协助雷戈萨打击科卡尔也与你切身相关。"},sec={{t="大酋长麾下副官的召唤",b="部落领袖密切关注边境的威胁。在贫瘠之地，雷戈萨·死门建起了一座防御哨站，守卫西部山口。部落军官派遣久经考验的冒险者前往十字路口以西，响应他征召精锐战士的号召。"},{t="通往凄凉之地的道路",b="雷戈萨·死门在十字路口以西山脊上的一处坚固据点等候。他从那里监视通往凄凉之地的山间小径。他正在集结一支先锋部队，准备穿越敌境，打击科卡尔和其他好战的半人马氏族，以免他们的扩张威胁部落领土。"}},faq={{q="雷戈萨·死门是谁？",a="雷戈萨·死门是一名驻守贫瘠之地的兽人战士，也是部落指挥官。他指挥斥候深入凄凉之地，并组织对那里的军事打击。",al={"雷戈萨 是谁","雷戈萨·死门 背景故事","任务给予者是谁"}},{q="雷戈萨·死门在哪里？",a="雷戈萨·死门位于贫瘠之地，在十字路口以西山路旁的部落地堡中，俯瞰西部山口。",al={"雷戈萨 在哪里","雷戈萨 位置","寻找 雷戈萨·死门"}},{q="谁会给予寻找雷戈萨的任务？",a="暗影猎手沃金、纳兹格雷尔、贝尔戈洛姆·石槌和克鲁斯克都会发出寻找雷戈萨的号召。沃金、纳兹格雷尔和贝尔戈洛姆·石槌位于奥格瑞玛；克鲁斯克位于塔伦米尔。",al={"谁提供 雷戈萨·死门 起始任务","哪里接 雷戈萨 任务"}},{q="雷戈萨的任务主要目标是什么？",a="雷戈萨正在召集战士，准备翻越群山进入凄凉之地，攻击敌对的半人马氏族，尤其是科卡尔。",al={"雷戈萨 想要什么","雷戈萨·死门 的目的"}},{q="部落为何关注凄凉之地？",a="凶悍的半人马氏族在凄凉之地横行。如果不加以遏制，他们可能会翻越群山，袭击贫瘠之地和附近的部落定居点。",al={"为何前往凄凉之地","部落为何关注凄凉之地"}},{q="与雷戈萨·死门交谈后，接下来要做什么？",a="向雷戈萨报到后，他会向你介绍西部群山另一侧的土地，并派你越过边境，首次出击对抗科卡尔。",al={"雷戈萨 之后的任务","雷戈萨 后续任务"}}},fp="17,191,34.219.0,20.300.0,25.135.0,35.154.0,40.167.0,51.127.0,41.146.0,54.162.0"}
P.entries["quest:1362"] = {n="凄凉之地的科卡尔部族",s="科卡尔以凄凉之地的据点为依托，威胁着部落的领土。雷戈萨·死门派遣部落勇士向西翻越群山，支援幽灵岗哨的斥候费古尔·双刃。",h="科卡尔以凄凉之地的据点为依托，威胁着部落的领土。雷戈萨·死门派遣部落勇士向西翻越群山，支援幽灵岗哨的斥候费古尔·双刃。",kw={"半人马","凄凉之地","费古尔·双刃","幽灵岗哨","部落","科卡尔","雷戈萨·死门","贫瘠之地"},ang={["faction:Horde"]="对部落而言，这标志着战事从守卫杜隆塔尔和贫瘠之地新建的定居点，转向将战火带入敌境。",["race:Orc"]="身为兽人，你已在卡利姆多东部站稳脚跟。桀骜不驯的半人马氏族仍在威胁部落的补给线。",["race:Tauren"]="身为牛头人，你知道，在你们与萨尔结盟之前，半人马的侵略曾让你们的游牧部族濒临灭绝。深入他们在凄凉之地的家园作战，也意味着你个人要付出代价。"},sec={{t="群山彼端的威胁",b="半人马劫掠者不断侵入贫瘠之地，雷戈萨·死门深知，仅在当地迎战无法消除威胁。科卡尔氏族的力量源自卡利姆多西海岸的崎岖土地。只要他们的祖传据点仍在部落的控制之外，劫掠者就会不断涌过山口。要阻止他们，部落就必须进攻他们的家园。"},{t="幽灵岗哨",b="幽灵岗哨让部落在凄凉之地深处有了立足之地。斥候费古尔·双刃在岗哨监视着相互敌对的半人马氏族。雷戈萨从贫瘠之地派遣久经沙场的战士，听候费古尔调遣，让部落的战事向西推进，从防御转为主动出击。"}},faq={{q="是谁派我执行这项任务？",a="雷戈萨·死门是一名兽人战士，驻守在贫瘠之地十字路口以西的地堡中，他指派你将战火带入科卡尔的祖地。",al={"任务给予者","谁提供任务","雷戈萨"}},{q="幽灵岗哨在哪里？",a="幽灵岗哨是部落的一处孤立营地，位于卡利姆多山脊以西、凄凉之地的崎岖小径旁。",al={"幽灵岗哨在哪","费古尔·双刃位置","凄凉之地营地"}},{q="部落为何将注意力转向凄凉之地？",a="袭击贫瘠之地的科卡尔来自扎根于凄凉之地的更大规模的半人马氏族。雷戈萨知道，只要科卡尔的据点完好无损，单靠防御就无法阻止入侵。",al={"为何前往凄凉之地","为何在凄凉之地对抗科卡尔","半人马关联"}},{q="费古尔·双刃是谁？",a="费古尔·双刃是驻守幽灵岗哨的部落斥候。他监视着凄凉之地相互敌对的半人马氏族，并组织对他们的袭击。",al={"费古尔·双刃","费古尔是谁"}},{q="这项任务需要战斗吗？",a="不需要。你将一封信从贫瘠之地送往凄凉之地，那里有更艰难的挑战等待着部落冒险者。",al={"任务中的战斗","战斗任务"}},{q="这项任务针对哪个半人马氏族？",a="目标是科卡尔氏族。他们的半人马劫掠者来自凄凉之地，已经侵入贫瘠之地和杜隆塔尔。",al={"哪个半人马","哪个氏族","科卡尔氏族"}}},fp="22,175,29.328.0,17.289.0,29.150.0,35.111.0,38.179.0,22.136.0,31.104.0,42.115.0"}
P.entries["quest:1365"] = {n="戴兹帕可汗",s="完成“凄凉之地的科卡尔”后，费古尔·双刃让你对付科卡尔的首领戴兹帕可汗。凄凉之地的许多半人马氏族相互征战，费古尔·双刃想在这些氏族联合之前，先打乱科卡尔的阵脚。",h="完成“凄凉之地的科卡尔”后，费古尔·双刃让你对付科卡尔的首领戴兹帕可汗。凄凉之地的许多半人马氏族相互征战，费古尔·双刃想在这些氏族联合之前，先打乱科卡尔的阵脚。",kw={"半人马","凄凉之地","戴兹帕","费古尔·双刃","戴兹帕可汗","科卡尔","科尔卡村"},sec={{t="分裂的氏族",b="科卡尔只是凄凉之地的半人马氏族之一。许多半人马游荡在干旱的平原上，彼此厮杀，死在对方手中。费古尔·双刃对此并不介意，因为半人马强壮而残暴，一旦联合起来，就会成为部落的强敌。必须在那之前对付他们。"},{t="科卡尔的首领",b="费古尔·双刃的第一步，是杀死科卡尔的首领戴兹帕可汗，打乱他们的阵脚。科尔卡村位于费古尔·双刃所在位置的东北方，他要你把这位可汗的头颅带回来。"}},faq={{q="费古尔·双刃为什么想要杀死戴兹帕可汗？",a="费古尔·双刃担心半人马氏族会联合起来对抗部落。杀死戴兹帕可汗，是为了先打乱科卡尔氏族的阵脚。",al={"为什么杀戴兹帕","戴兹帕可汗目的","杀死戴兹帕的原因"}},{q="戴兹帕可汗在哪里？",a="在凄凉之地的科尔卡村，位于费古尔·双刃的东北方。",al={"戴兹帕可汗位置","戴兹帕在哪里","科尔卡村位置"}},{q="费古尔·双刃要你带回什么？",a="把戴兹帕可汗的头颅带回给费古尔·双刃。",al={"戴兹帕可汗凭证","带什么给费古尔·双刃"}},{q="戴兹帕可汗的前置任务是什么？",a="“凄凉之地的科卡尔”。完成后，费古尔·双刃会派你去对付科卡尔的首领戴兹帕可汗。",al={"戴兹帕前置任务","戴兹帕可汗前置条件"}}},fp="14,172,13.308.0,17.149.0,49.135.0,32.81.0,35.56.0,33.114.0"}
P.entries["quest:1366"] = {n="悬赏半人马",s="在戴兹帕可汗之后，费古尔·双刃说，半人马各氏族如今已经受了惊吓，该让他们流血了。在凄凉之地各处猎杀任何氏族的半人马，带十五只耳朵交给费古尔。",h="在戴兹帕可汗之后，费古尔·双刃说，半人马各氏族如今已经受了惊吓，该让他们流血了。在凄凉之地各处猎杀任何氏族的半人马，带十五只耳朵交给费古尔。",kw={"半人马","半人马悬赏","半人马的耳朵","凄凉之地","费古尔·双刃","戴兹帕可汗"},sec={{t="该让他们流血了",b="费古尔·双刃说，既然半人马各氏族已经受了惊吓，现在就该让他们流血了。每当你行经凄凉之地，都要猎杀半人马。费古尔不在乎你猎杀哪个氏族的半人马，只要你收集十五只耳朵。削减他们的数量，就能动摇他们的意志，打消他们扩张的念头。"},{t="费古尔的评断",b="你回来时，费古尔说，半人马现在一定已经知道你的名字，对它既敬畏又恐惧。他们也知道你在为哪面旗帜效力：部落的旗帜。"}},faq={{q="是谁下令悬赏猎杀半人马？",a="凄凉之地的费古尔·双刃。需要带回十五只半人马的耳朵交给费古尔。",al={"谁发布半人马悬赏","半人马悬赏任务发布者"}},{q="需要猎杀哪些半人马氏族？",a="任何氏族都可以。费古尔不在乎你猎杀哪个氏族的半人马，只要你收集耳朵。",al={"要杀哪些半人马","半人马悬赏要杀哪个氏族"}},{q="费古尔为什么要这么多半人马的耳朵？",a="为了削减半人马的数量。半人马越少，意志就越薄弱，扩张的念头也会随之被打消。",al={"为什么猎杀凄凉之地的半人马","半人马悬赏的原因"}},{q="这次悬赏之前是什么任务？",a="前一个任务是戴兹帕可汗。费古尔说，半人马各氏族已经受了惊吓，现在该让他们流血了。",al={"半人马悬赏前置任务","半人马悬赏的前一个任务"}}},fp="14,113,18.282.0,16.165.1,38.96.0,38.74.0,42.130.0,29.116.0"}
P.entries["quest:1367"] = {n="玛格拉姆部族",s="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族交好，从中了解如何击败所有氏族。选择站在玛格拉姆一边，就要杀死他们的敌人吉尔吉斯，然后前往凄凉之地东南部的玛格拉姆村边缘，与玛格拉姆的代言人瓦鲁格交谈。",h="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族交好，从中了解如何击败所有氏族。选择站在玛格拉姆一边，就要杀死他们的敌人吉尔吉斯，然后前往凄凉之地东南部的玛格拉姆村边缘，与玛格拉姆的代言人瓦鲁格交谈。",kw={"半人马","凄凉之地","吉尔吉斯","古尔达·蛮鬃","玛格拉姆","玛格拉姆村","瓦鲁格"},sec={{t="以仇恨为武器",b="古尔达·蛮鬃的计划是利用半人马之间的相互仇恨。选定一个氏族作为盟友，从他们那里学到的东西便能揭示如何击败每一个氏族。选择玛格拉姆，就要斩杀他们的敌人吉尔吉斯，以此赢得玛格拉姆的尊重。"},{t="代言人",b="赢得足够的尊重后，玛格拉姆的代言人瓦鲁格就在凄凉之地东南部的玛格拉姆村外围等着你。在那之前，他对你无话可说。玛格拉姆不会与弱者交谈，只会杀死他们，所以他派你去迎战众多吉尔吉斯，证明自己的力量。"},{t="瓦鲁格的评判",b="瓦鲁格告诉你，吉尔吉斯一听到你的名字就哭泣，他们惧怕你，也像憎恨玛格拉姆一样憎恨你。他承认，也许你和玛格拉姆一样强大。他会拭目以待。"}},faq={{q="谁提议与玛格拉姆结盟？",a="古尔达·蛮鬃，她想利用半人马氏族之间的仇恨来对付他们，与一个氏族结盟，从中了解如何击败所有氏族。",al={"谁提供 玛格拉姆 联盟任务","玛格拉姆 任务给予者","古尔达·蛮鬃任务"}},{q="如何赢得玛格拉姆的尊重？",a="杀死他们的敌人吉尔吉斯。",al={"如何与 玛格拉姆 达到友善","玛格拉姆 声望","让 玛格拉姆 变为友善"}},{q="瓦鲁格在哪里？",a="在凄凉之地东南部的玛格拉姆村外围。他是玛格拉姆的代言人。",al={"瓦鲁格在哪里","寻找瓦鲁格","瓦鲁格位置"}},{q="瓦鲁格为什么起初拒绝交谈？",a="他说玛格拉姆不会与弱者交谈，只会杀死他们。先杀死众多吉尔吉斯，证明你的力量。",al={"瓦鲁格为什么不交谈","瓦鲁格生气","瓦鲁格对话"}}},fp="15,256,18.222.0,13.295.0,16.179.1,41.124.0,42.58.0,15.92.0,40.115.0"}
P.entries["quest:1368"] = {n="吉尔吉斯部族",s="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族交好，从中摸清击败所有氏族的方法。选择站在吉尔吉斯一边，就要杀死他们最痛恨的敌人玛格拉姆，然后前往凄凉之地西南部的吉尔吉斯村边缘，会见吉尔吉斯的萨满祭司智者乌泰克。",h="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族交好，从中摸清击败所有氏族的方法。选择站在吉尔吉斯一边，就要杀死他们最痛恨的敌人玛格拉姆，然后前往凄凉之地西南部的吉尔吉斯村边缘，会见吉尔吉斯的萨满祭司智者乌...",kw={"半人马","凄凉之地","吉尔吉斯","吉尔吉斯村","古尔达·蛮鬃","玛格拉姆","智者乌泰克"},sec={{t="以仇恨为武器",b="古尔达·蛮鬃的计划是利用半人马之间的仇恨。选定一个氏族作为盟友，再从这个氏族那里学会如何击败所有氏族。选择吉尔吉斯，就要杀死他们最痛恨的玛格拉姆，以此赢得他们的尊重。"},{t="萨满祭司",b="赢得他们的尊重后，你就该前往凄凉之地西南部的吉尔吉斯村外围，会见吉尔吉斯的萨满祭司智者乌泰克。在那之前，那里并不欢迎你：乌泰克说，你脚下是吉尔吉斯的土地，必须杀死玛格拉姆半人马来证明你的友谊。等玛格拉姆的鲜血浸透大地后再回来。"},{t="乌泰克的话",b="乌泰克说，大地告诉了他你杀死了多少玛格拉姆，这是件好事。对于吉尔吉斯的朋友，乌泰克还有更多事情要交给你做。"}},faq={{q="谁提议与吉尔吉斯结盟？",a="古尔达·蛮鬃，她想利用半人马氏族之间的仇恨来对付他们，与一个氏族结盟，从中学会如何击败所有氏族。",al={"谁提供 吉尔吉斯 联盟任务","吉尔吉斯 联盟任务给予者"}},{q="如何赢得吉尔吉斯的好感？",a="杀死吉尔吉斯最痛恨的玛格拉姆。",al={"如何与 吉尔吉斯 达到友善","吉尔吉斯 声望"}},{q="你要与吉尔吉斯中的谁交谈？",a="智者乌泰克，一位吉尔吉斯萨满祭司，位于凄凉之地西南部的吉尔吉斯村外围。",al={"乌泰克 在哪里","智者乌泰克位置"}},{q="乌泰克要你先做什么才会欢迎你？",a="乌泰克说，只有杀死玛格拉姆半人马来证明你的友谊，吉尔吉斯的土地才会欢迎你。",al={"乌泰克 为什么拒绝我","吉尔吉斯村敌对"}}},fp="15,262,18.223.0,10.299.0,12.155.1,41.133.0,40.68.0,37.99.0,45.105.0"}
P.entries["quest:1369"] = {n="破碎之泪",s="瓦鲁格说，吉尔吉斯愚蠢地相信半人马之母瑟莱德丝会保护他们。他派你进入他们村中的洞穴，摧毁他们囤积在那里的水晶——瑟拉达丝之泪，并带回三块碎片给他。",h="瓦鲁格说，吉尔吉斯愚蠢地相信半人马之母瑟莱德丝会保护他们。他派你进入他们村中的洞穴，摧毁他们囤积在那里的水晶——瑟拉达丝之泪，并带回三块碎片给他。",kw={"破碎之泪","半人马","凄凉之地","吉尔吉斯","玛格拉姆","瑟莱德丝","瓦鲁格"},sec={{t="洞中的水晶",b="瓦鲁格鄙视吉尔吉斯，因为他们相信半人马之母瑟莱德丝会保护他们。在他看来，没有谁会保护半人马，而玛格拉姆最为强大，无需保护。他派你前往吉尔吉斯村中的洞穴，那里囤积着被称为瑟拉达丝之泪的水晶。砸碎它们，给瓦鲁格带回三块碎片。只有当你不是玛格拉姆的敌人时，他才会放心把这件事交给你。"},{t="瓦鲁格的夸口",b="瓦鲁格喜出望外：眼泪既已破碎，吉尔吉斯就会明白瑟莱德丝帮不了他们，而当玛格拉姆碾碎他们时，她也不会为他们落泪。他宣称玛格拉姆将成为统治者，还称赞你选择站在最强者一边十分明智。"}},faq={{q="瓦鲁格是谁？",a="他是凄凉之地玛格拉姆村的一名玛格拉姆半人马。他要你摧毁吉尔吉斯洞穴中的瑟拉达丝之泪。",al={"瓦鲁格","谁提供 破碎之泪","破碎之泪 任务给予者"}},{q="瑟拉达丝之泪是什么？",a="是吉尔吉斯囤积在他们村中洞穴里的水晶。",al={"瑟拉达丝之泪","破碎之泪 背景故事","吉尔吉斯 水晶"}},{q="瓦鲁格为何要摧毁这些眼泪？",a="吉尔吉斯认为半人马之母瑟莱德丝会保护他们。瓦鲁格骂他们愚蠢，说玛格拉姆无需保护，并想让吉尔吉斯看清自己错了。",al={"为何摧毁眼泪","玛格拉姆 的动机","为何打碎水晶"}},{q="在哪里能找到这些水晶？",a="在吉尔吉斯村中的洞穴里。瓦鲁格要你给他带回三块碎片。",al={"破碎之泪 在哪里","吉尔吉斯 洞穴位置","眼泪在哪里"}}},fp="12,181,20.397.0,13.228.1,13.122.0,32.80.0,40.173.0,29.98.0"}
P.entries["quest:1370"] = {n="偷取物资",s="智者乌泰克说肉食给予了吉尔吉斯人力量，而玛格拉姆人储存了多余的食物，好让他们在狩猎间隙也能维持战斗。你被派往东部的玛格拉姆村进行袭击，并带回六袋风干肉。",h="智者乌泰克说肉食给予了吉尔吉斯人力量，而玛格拉姆人储存了多余的食物，好让他们在狩猎间隙也能维持战斗。你被派往东部的玛格拉姆村进行袭击，并带回六袋风干肉。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","肉","补给品","乌泰克"},sec={{t="肉食与力量",b="在战争间隙，吉尔吉斯人会进行狩猎，因为肉食意味着力量，而饱腹之人比饥饿之人更能战斗。智者乌泰克说，玛格拉姆人储存了备用粮，以维持他们在两次狩猎之间的消耗。去袭击东部的村庄，夺走这些物资，他们的力量就会枯竭。你需要收集六袋粗糙的风干肉，并将其带给吉尔吉斯村的乌泰克。"}},faq={{q="是谁派你去夺取这些补给品的？",a="凄凉之地的吉尔吉斯人的智者乌泰克。",al={"任务发布者","谁发布了窃取补给任务","智者乌泰克"}},{q="乌泰克为什么要夺取玛格拉姆人的肉食？",a="对吉尔吉斯人来说，肉食就是力量。玛格拉姆人留有储备，好在狩猎间隙也能继续战斗，乌泰克认为夺走这些食物能削弱他们。",al={"为什么要偷肉","玛格拉姆食物","抢夺肉食的原因"}},{q="玛格拉姆人的补给品存放在哪里？",a="在东部的玛格拉姆村里。",al={"玛格拉姆村在哪里","补给品在哪里","玛格拉姆位置"}},{q="乌泰克想要多少肉？",a="六袋粗糙的风干肉，由智者乌泰克在吉尔吉斯村收集。",al={"需要多少肉","我需要带什么给乌泰克"}}},fp="17,175,17.285.0,37.53.0,42.132.0,35.60.0,30.90.0"}
P.entries["quest:1371"] = {n="瓦鲁格的玩具",s="玛格拉姆村的瓦鲁格还记得一个侏儒，他曾带着一车奇怪的东西来到凄凉之地。瓦鲁格留下了车上的一个木头人，后来却把它打坏了，如今他想要一个新的：高级假人。",h="玛格拉姆村的瓦鲁格还记得一个侏儒，他曾带着一车奇怪的东西来到凄凉之地。瓦鲁格留下了车上的一个木头人，后来却把它打坏了，如今他想要一个新的：高级假人。",kw={"半人马","凄凉之地","侏儒","玛格拉姆","假人","瓦鲁格"},sec={{t="侏儒的货车",b="很久以前，一个小侏儒带着马匹和一辆货车来到凄凉之地。车上装着稀奇古怪的东西：有些燃烧时会发出不同颜色的火焰，有些明明没有生命，却能活动。瓦鲁格杀了那个侏儒，不过在那之前，侏儒曾逗得他发笑。瓦鲁格留下了车上他最喜欢的东西，一个木头做的人，它一直向他挥手，直到被他打坏。如今他想要一个新的，高级假人，并指望任何不与玛格拉姆为敌的人给他送来。"}},faq={{q="瓦鲁格是谁？",a="瓦鲁格是一个玛格拉姆半人马，就在玛格拉姆村。他要求与他打交道的人始终与玛格拉姆保持良好关系。",al={"瓦鲁格","瓦鲁格的玩具任务给予者"}},{q="瓦鲁格想要什么？",a="一个高级假人，用来替换他打坏的那个木头人，那是从侏儒的货车上拿来的。",al={"瓦鲁格需要什么物品","瓦鲁格装置物品"}},{q="瓦鲁格为什么想要一个假人？",a="很久以前，他杀了一个来到凄凉之地的侏儒，那个侏儒带着一车古怪又有趣的东西。侏儒逗得他发笑，而瓦鲁格最喜欢的是一个人形木偶，它一直向他挥手，直到被他打坏。他想要一个新的。",al={"瓦鲁格为什么想要假人","瓦鲁格想要假人的原因"}},{q="玛格拉姆故事中，在这之前发生了什么？",a="在此之前是破碎之泪，那是你与玛格拉姆打交道时更早的事。",al={"瓦鲁格的玩具任务链","瓦鲁格的玩具前置任务"}}},fp="15,91,16.470.0,13.116.0,21.101.0,35.228.0,43.64.0"}
P.entries["quest:1373"] = {n="盎格库尔",s="吉尔吉斯氏族的智者乌泰克说你还有更多需要证明的地方，目前吉尔吉斯氏族将会在没有你帮助的情况下对抗玛格拉姆氏族。大地向智者乌泰克低语了德莱尼水晶的事，你被派往遥远的悲伤沼泽去寻找迷失者翁格库手中掌握的一块碎片。",h="吉尔吉斯氏族的智者乌泰克说你还有更多需要证明的地方，目前吉尔吉斯氏族将会在没有你帮助的情况下对抗玛格拉姆氏族。大地向智者乌泰克低语了德莱尼水晶的事，你被派往遥远的悲伤沼泽去寻找迷失者翁格库手中掌握的一块碎片。",kw={"凄凉之地","德莱尼水晶","吉尔吉斯","迷失者","玛格拉姆","翁格库","悲伤沼泽","智者乌泰克"},sec={{t="远方的水晶",b="在窃取补给任务之后，智者乌泰克告诉你，你的下一个任务在很远的地方。那些倾听大地的人会听到许多秘密，乌泰克听到的秘密之一就是关于一种叫做德莱尼水晶的红色晶体，它刚刚来到这片土地，是从一个有着浮空山脉和恶魔统治的地方带来的。乌泰克说，它的一块碎片会让魔法变得强大。迷失者翁格库在东部王国的悲伤沼泽中持有这种碎片。当你回来时，乌泰克会寻找证据来证明吉尔吉斯氏族仍然可以称你为朋友。"}},faq={{q="智者乌泰克是谁？",a="位于凄凉之地吉尔吉斯村的一位吉尔吉斯半人马，他说大地会向那些倾听它的人低语秘密。",al={"乌泰克","吉尔吉斯长老","半人马任务发放者"}},{q="什么是德莱尼水晶？",a="一块红色水晶，尤塞克称它是新近来到我们世界的。尤塞克说，它来自一片飞翔山脉遍布、由恶魔统治的土地。",al={"德莱尼水晶碎片","红色水晶","什么是德莱尼水晶"}},{q="翁格库是谁？",a="一位迷失者，在东部王国的悲伤沼泽中部持有一块德莱尼水晶碎片。",al={"翁格库在哪里","翁格库位置","寻找翁格库"}},{q="为什么乌泰克想要德莱尼水晶碎片？",a="乌泰克说一块碎片会让魔法变得强大。",al={"为什么要获取德莱尼水晶","乌泰克魔法"}},{q="在此之前发生了什么？",a="之前乌泰克交给你的任务：窃取补给。",al={"前置任务","前置条件"}}},fp="6,162,23.483.0,22.125.0,20.148.0,14.107.0,40.58.0,22.65.0"}
P.entries["quest:1374"] = {n="杰恩可汗",s="继昂格库之后，智者乌泰克告诉你大地在低语，玛格拉姆半人马正在变得虚弱，是时候除掉他们的可汗了。乌泰克希望你将汗·杰恩的头颅带到吉尔吉斯村。",h="继昂格库之后，智者乌泰克告诉你大地在低语，玛格拉姆半人马正在变得虚弱，是时候除掉他们的可汗了。乌泰克希望你将汗·杰恩的头颅带到吉尔吉斯村。",kw={"半人马","凄凉之地","吉尔吉斯","吉尔吉斯村","杰恩的头颅","汗·杰恩","玛格拉姆","智者乌泰克"},sec={{t="玛格拉姆可汗",b="位于吉尔吉斯村的智者乌泰克说大地对他倾诉，预示着玛格拉姆正日渐虚弱。乌泰克指名要你除掉他们的可汗——杰恩，并带回玛格拉姆可汗的头颅。乌泰克希望你回来时仍是吉尔吉斯的朋友。"}},faq={{q="汗·杰恩是谁？",a="玛格拉姆半人马的可汗。",al={"汗·杰恩","杰恩是谁","玛格拉姆领袖"}},{q="为什么智者乌泰克要置汗·杰恩于死地？",a="乌泰克说大地告诉他玛格拉姆人正在变弱，所以现在是除掉他们可汗的时机。",al={"为什么要杀杰恩","乌泰克的动机","为什么要杀玛格拉姆可汗"}},{q="这之前发生了什么？",a="这发生在昂格库任务之后。",al={"汗·杰恩任务的前置","任务链顺序","前置任务"}},{q="智者乌泰克在哪里？",a="在凄凉之地的吉尔吉斯村。",al={"乌泰克位置","乌泰克在哪"}}},fp="9,126,15.253.0,17.35.0,44.112.0,22.20.0,24.48.0"}
P.entries["quest:1375"] = {n="沙卡可汗",s="在你完成瓦鲁格的玩具后，玛格拉姆的瓦鲁格对你的帮助很满意，现在想要吉尔吉斯可汗沙卡可汗的脑袋。他打算盯着那颗脑袋，嘲笑自己的敌人。",h="在你完成瓦鲁格的玩具后，玛格拉姆的瓦鲁格对你的帮助很满意，现在想要吉尔吉斯可汗沙卡可汗的脑袋。他打算盯着那颗脑袋，嘲笑自己的敌人。",kw={"半人马","凄凉之地","吉尔吉斯","沙卡可汗的脑袋","沙卡可汗","玛格拉姆","瓦鲁格"},sec={{t="敌对的可汗",b="在玛格拉姆村，瓦鲁格告诉你，你帮助了玛格拉姆，他很喜欢你。现在，他要你杀死吉尔吉斯可汗沙卡可汗，把脑袋带给他。他说，他想盯着那颗脑袋，嘲笑这个家伙。他希望你继续与玛格拉姆保持良好的关系。"}},faq={{q="沙卡可汗是谁？",a="凄凉之地吉尔吉斯半人马氏族的可汗，玛格拉姆的瓦鲁格想要他的脑袋。",al={"沙卡可汗的故事","沙卡是谁","沙卡半人马"}},{q="瓦鲁格为什么想要沙卡可汗死？",a="他想要沙卡的脑袋，好盯着那颗脑袋嘲笑他。",al={"为什么要杀沙卡","瓦鲁格与沙卡的恩怨"}},{q="瓦鲁格在哪里？",a="在凄凉之地的玛格拉姆村。",al={"沙卡可汗的位置","瓦鲁格在哪里"}},{q="此前发生了什么？",a="瓦鲁格的玩具，完成后，瓦鲁格说你帮助了玛格拉姆，所以他很喜欢你。",al={"沙卡可汗前置条件","沙卡前置任务"}}},fp="10,139,12.265.0,18.89.0,36.77.0,15.39.0,20.70.0"}
P.entries["quest:138"] = {n="杉德尔船长的宝藏",s="在西部荒野的海岸边，杉德尔船长的宝藏 将你引向内陆。你离开海岸，沿着他四散的线索寻找下一个标记。",h="在西部荒野的海岸边，杉德尔船长的宝藏 将你引向内陆。你离开海岸，沿着他四散的线索寻找下一个标记。",kw={"破木桶","杉德尔船长","烟囱","海盗","杉德尔 的宝藏","寻宝","西部荒野"},ang={["class:Rogue"]="身为潜行者，你可以运用潜行与智谋破译海盗的密码，搜寻废弃的遗迹，寻找被遗忘的财物。",["faction:Alliance"]="身为联盟旅人，你可以沿着杉德尔的踪迹，走过西部荒野无法无天的海岸和无人维护的内陆道路。当地民兵正艰难地对抗有组织的匪徒。"},sec={{t="通往内陆的谜题",b="杉德尔船长在乡野各处留下谜题，而没有在海滩边标出一处藏宝地。破译后的密码指向岩石峭壁之外，通往西部荒野的主要道路。"},{t="路旁的废墟",b="路旁的废墟中，一座古老的烟囱标出了下一站。附近一只被丢弃的木桶饱经风雨，里面藏着另一条信息，而这座破败的农庄也成了杉德尔线索途中的地标。"}},faq={{q="杉德尔船长是谁？",a="杉德尔船长是一名海盗船长，曾沿着西部荒野的海岸航行。他在这片地区各处留下线索和谜题，供寻找他所藏宝物的人追寻。",al={"杉德尔船长 背景故事","杉德尔 是谁","杉德尔 海盗"}},{q="这条线索指向哪里？",a="这条线索从西边的大海向东延伸，越过峭壁，通往道路。废墟中一座古老的石砌烟囱旁，一只破木桶里藏着解开谜题的下一条线索。",al={"去哪里","线索位置","烟囱位置"}},{q="杉德尔为什么把宝藏分开藏匿？",a="杉德尔将寻宝路线分散在几个谜题中，以免对手和官府找到他藏匿的财富。只有坚持不懈、足智多谋的寻宝者，才能沿着线索找到最终的藏宝地。",al={"为何留下线索","为何要四处寻宝"}},{q="沿着线索寻宝危险吗？",a="线索不过是羊皮纸和旧容器，但西部荒野的道路与田野却危机四伏。游荡的野兽、四处潜行的豺狼人，以及充满敌意的迪菲亚潜行者成员，都威胁着废弃农庄附近的旅人。",al={"是否安全","西部荒野的危险"}},{q="木桶藏在什么样的废墟附近？",a="木桶就在路边一座废弃建筑摇摇欲坠的石砌烟囱旁。近些年的动荡中，西部荒野的许多农庄都已被遗弃或摧毁。",al={"烟囱废墟","哪座建筑"}},{q="这个任务会揭示宝藏本身吗？",a="不会。这一步只会揭示另一条线索。杉德尔在这片地区设下了数个寻宝环节，走完这些环节才能找到真正的宝藏。",al={"这是最后的宝箱吗","现在能获得战利品吗"}}},fp="32,143,25.169.0,20.186.0,24.159.0,30.174.0,44.198.0,41.216.0,45.177.0,43.126.0"}
P.entries["quest:1380"] = {n="赫鲁萨可汗",s="智者乌泰克回想起你曾如何帮助吉尔吉斯半人马对抗玛格拉姆，现在他请求你击杀玛洛迪部族的首领可汗赫拉萨，以此来打击玛洛迪。赫拉萨持有一块钥匙碎片，乌泰克要你把它带回来。",h="智者乌泰克回想起你曾如何帮助吉尔吉斯半人马对抗玛格拉姆，现在他请求你击杀玛洛迪部族的首领可汗赫拉萨，以此来打击玛洛迪。赫拉萨持有一块钥匙碎片，乌泰克要你把它带回来。",kw={"半人马","凄凉之地","吉尔吉斯村","可汗赫拉萨","玛洛迪","玛洛迪战号","智者乌泰克","长矛谷"},sec={{t="挑战玛洛迪",b="智者乌泰克说，吉尔吉斯现在需要帮助来对抗玛洛迪。玛洛迪战号矗立在长矛谷的一处高地上，吹响它就能引出可汗赫拉萨。然而没有战号吹嘴的话，战号就毫无用处，这种吹嘴非常稀有，只有受信任的玛洛迪半人马才会携带。当战号吹响时，更多的半人马会赶来，而赫拉萨会最后出现。"},{t="钥匙碎片",b="可汗赫拉萨持有一块钥匙碎片，乌泰克要你把它带回吉尔吉斯村。"},{t="当你归来时",b="当你归来时，乌泰克欢呼雀跃，庆祝赫拉萨已死，玛洛迪末日将至。他发誓说，当吉尔吉斯统治这片土地时，他们会永远铭记你，大地的灵魂也会永远传唱你的名字。"}},faq={{q="是谁派你去对抗可汗赫拉萨的？",a="凄凉之地的吉尔吉斯村的智者乌泰克，他会向那些曾经帮助过吉尔吉斯的人提出请求。",al={"谁给予可汗赫拉萨任务","可汗赫拉萨任务发布者","如何获得可汗赫拉萨任务"}},{q="如何引出可汗赫拉萨进行战斗？",a="乌泰克指引你去长矛谷的玛洛迪战号那里，你需要吹响它。半人马会回应号角，赫拉萨随后就会出现。",al={"可汗赫拉萨位置","可汗赫拉萨在哪里","寻找可汗赫拉萨"}},{q="如何吹响玛洛迪战号？",a="没有战号吹嘴，战号就毫无用处，而只有受信任的玛洛迪半人马才可能携带这种稀有物品。",al={"战号吹嘴","如何使用玛洛迪战号","吹响玛洛迪战号"}},{q="在此之前发生了什么？",a="这是可汗杰恩任务的后续。乌泰克提醒你，你曾帮助过吉尔吉斯对抗玛格拉姆。",al={"可汗赫拉萨前置条件","可汗赫拉萨之前的任务","可汗赫拉萨任务链"}},{q="可汗赫拉萨持有什么？",a="可汗赫拉萨持有一块钥匙碎片，乌泰克让你把它带到吉尔吉斯村给他。",al={"可汗赫拉萨任务物品","玛洛迪钥匙碎片","赫拉萨掉落什么"}}},fp="11,182,25.340.0,16.82.0,14.206.1,35.119.0,40.116.0,39.88.0,23.88.0,27.88.0"}
P.entries["quest:1381"] = {n="赫鲁萨可汗",s="瓦鲁格宣布吉尔吉斯可汗已死，并说接下来就轮到玛洛迪了。瓦鲁格派你去对付他们的可汗赫兰萨，并要你取回赫兰萨携带的一块钥匙碎片。",h="瓦鲁格宣布吉尔吉斯可汗已死，并说接下来就轮到玛洛迪了。瓦鲁格派你去对付他们的可汗赫兰萨，并要你取回赫兰萨携带的一块钥匙碎片。",kw={"凄凉之地","钥匙碎片","赫鲁萨可汗","玛格拉姆","玛洛迪","长矛谷","战争号角","瓦鲁格"},sec={{t="峭壁上的号角",b="瓦鲁格要玛洛迪可汗赫兰萨死。长矛谷峭壁上的一只号角能将他引出来，但没有吹嘴就无法吹响，而吹嘴可以通过击杀玛洛迪半人马获得。号角吹响后，玛洛迪半人马会聚集到高塔处，赫兰萨最后才会现身。"},{t="一块钥匙碎片",b="赫兰萨持有一块钥匙碎片，瓦鲁格要你把它带到玛格拉姆村，交给瓦鲁格。瓦鲁格期待你证明自己是玛格拉姆的盟友。"},{t="半人马的霸主",b="赫兰萨死后，瓦鲁格宣称玛格拉姆是最强大的半人马，注定要碾碎对手，统治凄凉之地。瓦鲁格说，当其他人都被铁蹄践踏时，你会因功绩被铭记而获赦免。"}},faq={{q="谁派你去击败赫兰萨可汗？",a="吉尔吉斯可汗死后，凄凉之地玛格拉姆村的瓦鲁格派你前去。",al={"谁发布赫鲁萨可汗任务","赫鲁萨可汗任务发布者"}},{q="怎样才能见到赫兰萨可汗？",a="瓦鲁格说，要面对赫兰萨，就得吹响长矛谷峭壁上的号角。号角需要一个吹嘴，可以通过击杀玛洛迪半人马获得，随后半人马会聚集到高塔处，赫兰萨之后才会出现。",al={"如何召唤赫兰萨","寻找赫鲁萨可汗","长矛谷吹号角"}},{q="赫兰萨可汗会在哪里出现？",a="吹响号角并击杀聚集而来的玛洛迪半人马后，赫兰萨就会在长矛谷的高塔处出现。",al={"赫鲁萨可汗位置","赫兰萨在哪里"}},{q="赫兰萨可汗持有什么？",a="赫兰萨持有一块钥匙碎片，瓦鲁格要你把那块碎片带给瓦鲁格。",al={"赫兰萨掉落什么","玛洛迪钥匙碎片"}}},fp="11,167,19.256.0,16.148.0,22.222.1,36.78.0,29.185.0,30.113.0,27.67.0"}
P.entries["quest:1382"] = {n="奇怪的联盟",s="本迪加斯上尉认为，凄凉之地的半人马氏族相互争斗是件幸事，因为一旦它们联合起来，就无人能够阻挡。吉尔吉斯正与玛格拉姆进行残酷的战争，因此本迪加斯派你前往凄凉之地西南部，向智者乌泰克寻求结盟。",h="本迪加斯上尉认为，凄凉之地的半人马氏族相互争斗是件幸事，因为一旦它们联合起来，就无人能够阻挡。吉尔吉斯正与玛格拉姆进行残酷的战争，因此本迪加斯派你前往凄凉之地西南部，向智者乌泰克寻求结盟。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","潘迪加斯特","奇怪的联盟","乌泰克"},sec={{t="分裂的氏族",b="本迪加斯上尉认为，半人马氏族彼此交战是件幸事，因为一旦它们联合起来，就无人能够阻挡。本迪加斯想进一步利用这一优势。吉尔吉斯与玛格拉姆正进行着残酷的战争，因此打击玛格拉姆或许能争取到吉尔吉斯的支持。"},{t="寻找乌泰克",b="智者乌泰克就在凄凉之地西南部、吉尔吉斯营地的入口处，通过她或许能促成结盟。起初她拒绝与你交谈，叫你离开，杀死足够多的玛格拉姆后再回来。"},{t="乌泰克的答复",b="当足够多的玛格拉姆倒在你手下后，乌泰克说，吉尔吉斯如今已在低声谈论你的名字，她对此颇为赞许。她愿意谈谈你能为氏族带来什么，以及氏族能为你提供什么。"}},faq={{q="谁派你去联系吉尔吉斯？",a="本迪加斯上尉，他希望能与吉尔吉斯氏族结盟。",al={"谁给予奇怪的联盟任务","奇怪的联盟任务给予者","谁开启奇怪的联盟任务"}},{q="智者乌泰克在哪里？",a="在凄凉之地西南部，吉尔吉斯营地的入口处。",al={"乌泰克位置","寻找智者乌泰克","乌泰克在哪里"}},{q="智者乌泰克为什么不肯立刻与初来者交谈？",a="她叫你离开，杀死足够多的玛格拉姆后再回来。",al={"乌泰克为何敌对","乌泰克不肯交谈","如何与乌泰克交谈"}},{q="联盟为什么想与吉尔吉斯缔结盟约？",a="本迪加斯上尉认为，半人马氏族一旦联合起来，就无人能够阻挡，因此它们之间的争斗是件幸事。吉尔吉斯正与玛格拉姆交战，因此攻击玛格拉姆或许能赢得吉尔吉斯的友谊。",al={"为何与吉尔吉斯结盟","联盟与半人马结盟的原因","为何选择吉尔吉斯氏族"}}},fp="16,143,13.282.0,13.202.0,14.187.1,36.92.0,32.67.0,57.71.0,50.210.0"}
P.entries["quest:1384"] = {n="突袭科卡尔",s="在“奇怪的联盟”任务之后，智者乌泰克派你去对付东北方的库卡隆半人马。击败他们，拿走他们的护身符，并将十个护身符带回给乌泰克。",h="在“奇怪的联盟”任务之后，智者乌泰克派你去对付东北方的库卡隆半人马。击败他们，拿走他们的护身符，并将十个护身符带回给乌泰克。",kw={"半人马","粗糙的护身符","凄凉之地","吉尔吉斯","库卡隆","乌泰克"},sec={{t="对库卡隆魔法的蔑视",b="乌泰克嘲笑库卡隆半人马认为自己的魔法很强大；在乌泰克看来，他们对魔法一窍不通。你需要向东北方进发，消灭库卡隆人，并夺取他们的护身符。乌泰克想要十个粗糙的护身符丢进火里，看着它们燃烧并以此取乐。"},{t="乌泰克的判决",b="乌泰克称赞这一行为对吉尔吉斯部族来说是件好事。乌泰克说，库卡隆人虚弱且注定灭亡，他们的魔法救不了他们。见过你的手段后，他们会更加恐惧，而恐惧只会让他们变得更虚弱。在吉尔吉斯领地，弱者很快就会死去。"}},faq={{q="智者乌泰克是谁？",a="智者乌泰克在凄凉之地的吉尔吉斯村等待着。乌泰克想要库卡隆人的护身符。",al={"突袭库卡隆的发起者","乌泰克","智者乌泰克背景故事"}},{q="库卡隆人在哪里？",a="根据乌泰克所说，在东北方。",al={"哪里可以找到库卡隆","凄凉之地库卡隆位置"}},{q="什么是粗糙的护身符？",a="从库卡隆人身上获得的护身符。乌泰克想要十个来丢进火里，并以此取乐。",al={"粗糙的护身符","库卡隆护身符"}},{q="这如何融入吉尔吉斯任务线？",a="它是“奇怪的联盟”的后续任务。",al={"吉尔吉斯任务线","突袭库卡隆的前置任务"}}},fp="18,143,25.237.0,15.243.1,22.81.0,29.36.0,26.104.0,40.44.0"}
P.entries["quest:1385"] = {n="野蛮外交",s="本迪加斯上尉认为，无论哪个半人马氏族赢得凄凉之地的战争，都会向外扩张，威胁联盟的据点。为了弄清如何击败他们，本迪加斯上尉 希望与其中一个氏族结盟：对抗吉尔吉斯，争取玛格拉姆，并与瓦鲁格交谈。",h="本迪加斯上尉认为，无论哪个半人马氏族赢得凄凉之地的战争，都会向外扩张，威胁联盟的据点。为了弄清如何击败他们，本迪加斯上尉 希望与其中一个氏族结盟：对抗吉尔吉斯，争取玛格拉姆，并与瓦鲁格交谈。",kw={"野蛮外交","半人马","凄凉之地","吉尔吉斯","玛格拉姆","潘迪加斯特","瓦鲁格"},sec={{t="战火中的土地",b="凄凉之地战火纷飞，半人马氏族彼此征战，联盟认为胜者将向外扩张，进攻联盟的据点。绝不能让这种事发生。本迪加斯上尉说，要弄清如何击败半人马，联盟就需要与其中一个氏族交好。"},{t="玛格拉姆氏族",b="玛格拉姆与吉尔吉斯交战，因此打击吉尔吉斯或许能让玛格拉姆考虑结盟。赢得他们的好感，然后前往凄凉之地东南部的玛格拉姆村，找到瓦鲁格。瓦鲁格警告说，要成为玛格拉姆的朋友，就必须杀死吉尔吉斯。"}},faq={{q="联盟为什么想与半人马氏族结盟？",a="本迪加斯上尉认为，半人马战争的胜者将向外扩张，威胁联盟的据点。要弄清如何击败他们，联盟就需要与其中一个氏族交好。",al={"为何与 玛格拉姆 结盟","潘迪加斯 的计划","与半人马结盟的原因"}},{q="如何赢得玛格拉姆的好感？",a="玛格拉姆正与吉尔吉斯交战，对抗吉尔吉斯或许能让他们考虑结盟。瓦鲁格说，要成为玛格拉姆的朋友，就必须杀死吉尔吉斯。",al={"如何提升 玛格拉姆 声望","玛格拉姆 友善","击杀 吉尔吉斯"}},{q="瓦鲁格在哪里？",a="在凄凉之地东南部的玛格拉姆村。",al={"瓦鲁格的位置","瓦鲁格在哪里","玛格拉姆 联系人"}}},fp="15,181,13.237.0,10.231.0,59.169.0,40.163.0,15.56.0"}
P.entries["quest:1386"] = {n="突袭科卡尔部族",s="完成野蛮外交后，玛格拉姆村的瓦鲁格要你证明，你也能像玛格拉姆一样杀死科卡尔。向北进发，杀死科卡尔半人马、斥候和虐待者。",h="完成野蛮外交后，玛格拉姆村的瓦鲁格要你证明，你也能像玛格拉姆一样杀死科卡尔。向北进发，杀死科卡尔半人马、斥候和虐待者。",kw={"野蛮外交","半人马","凄凉之地","科卡尔","玛格拉姆","玛格拉姆村","瓦鲁格"},sec={{t="我们大笑，我们杀戮",b="瓦鲁格讥讽道，科卡尔自以为强大，玛格拉姆却一边杀死他们，一边嘲笑他们。瓦鲁格要你证明，你也能像玛格拉姆一样杀死科卡尔，于是你向北进发：十二名科卡尔半人马、十二名斥候和六名虐待者必须倒下。"},{t="瓦鲁格的认可",b="你回来时，瓦鲁格说科卡尔如今已经怕了你。瓦鲁格希望你杀死他们时放声大笑，因为在杀戮时大笑，能让敌人看清自己的软弱。"}},faq={{q="谁派你去攻击科卡尔？",a="凄凉之地玛格拉姆村的瓦鲁格，他是玛格拉姆的一员。",al={"谁发布进攻科卡尔","突袭科卡尔任务给予者","哪里接进攻科卡尔"}},{q="这一步之前是什么任务？",a="前一个任务是野蛮外交。",al={"前一个任务","突袭科卡尔前置任务","突袭科卡尔前置条件"}},{q="科卡尔在哪里？",a="瓦鲁格让你向北去找他们。",al={"科卡尔位置","科卡尔半人马在哪里","哪里能找到科卡尔"}},{q="瓦鲁格为什么要杀死科卡尔？",a="瓦鲁格嘲笑科卡尔自以为强大，要你证明自己也能像玛格拉姆一样杀死他们。",al={"为什么杀科卡尔","玛格拉姆与科卡尔的敌对关系","瓦鲁格为什么憎恨科卡尔"}}},fp="21,164,20.222.0,16.134.1,35.62.0,27.29.0,29.49.0,38.111.0"}
P.entries["quest:1387"] = {n="悬赏半人马",s="尼耶尔前哨站的麦尔金斯下士说，凄凉之地的所有半人马氏族都有一个共同点，那就是残忍，只要半人马还在，和平就不会到来。麦尔金斯要你在这片土地上猎杀半人马，带回十五只耳朵。",h="尼耶尔前哨站的麦尔金斯下士说，凄凉之地的所有半人马氏族都有一个共同点，那就是残忍，只要半人马还在，和平就不会到来。麦尔金斯要你在这片土地上猎杀半人马，带回十五只耳朵。",kw={"联盟","悬赏","半人马","半人马耳朵","麦尔金斯下士","凄凉之地","耳朵","尼耶尔前哨站"},sec={{t="共同之处",b="在尼耶尔前哨站，麦尔金斯下士说，半人马分为许多氏族，各有自己的首领和计划，却同样残忍。麦尔金斯说，只有除掉半人马，和平才会到来。"},{t="为联盟收集耳朵",b="你游历凄凉之地，猎杀半人马，割下他们的耳朵。麦尔金斯要的数量不少，总共十五只，还说这是在为联盟效力，让战争离结束更近一步。"}},faq={{q="是谁悬赏猎杀半人马？",a="驻守在凄凉之地尼耶尔前哨站的麦尔金斯下士。",al={"半人马悬赏任务发布者","谁发布半人马悬赏","麦尔金斯悬赏"}},{q="麦尔金斯下士为什么要杀死半人马？",a="麦尔金斯说，各个氏族的首领和目标虽然不同，却都一样残忍，只要半人马还在，就不可能有和平。",al={"为什么杀半人马","麦尔金斯的动机","为什么要半人马耳朵"}},{q="麦尔金斯下士要你带回什么？",a="十五只半人马耳朵，从你游历凄凉之地时猎杀的半人马身上取得。",al={"收集什么","半人马悬赏物品","半人马悬赏战利品"}},{q="需要猎杀哪些半人马氏族？",a="麦尔金斯没有指定某个氏族，而是说所有氏族都一样残忍，只要求你在凄凉之地猎杀半人马。",al={"哪些半人马","半人马氏族目标","收集哪个氏族的耳朵"}}},fp="14,149,19.197.0,21.166.0,37.66.0,50.133.0,44.99.0,38.107.0"}
P.entries["quest:1389"] = {n="德莱尼水晶",s="避难营的玛格图尔请求你带回六块德莱尼水晶，这些水晶是玛格图尔族人的圣物，被农田避难所的失落者偷走了。没有这些水晶，玛格图尔的族人担心自己也会迷失方向。",h="避难营的玛格图尔请求你带回六块德莱尼水晶，这些水晶是玛格图尔族人的圣物，被农田避难所的失落者偷走了。没有这些水晶，玛格图尔的族人担心自己也会迷失方向。",kw={"德莱尼水晶","农田避难所","避难营","失落者","玛格图尔","悲伤沼泽"},sec={{t="失落者",b="农田避难所的失落者与玛格图尔的族人外貌相同，但前往艾泽拉斯的艰辛旅程让他们陷入了疯狂。他们曾是同胞，如今住在东边的避难所里，任何误入附近的人都会被他们抓走或杀死。他们还偷走了一种圣物：德莱尼水晶。"},{t="失去水晶",b="玛格图尔的族人没有足够的力量进入农田避难所，从棚屋和营火之间夺回德莱尼水晶。没有这些水晶，他们担心自己也会迷失方向。玛格图尔请求你带回六块。"}},faq={{q="谁在请求带回德莱尼水晶？",a="玛格图尔，他在避难营。",al={"谁给予德莱尼水晶","玛格图尔任务","谁需要德莱尼水晶"}},{q="德莱尼水晶为什么对玛格图尔如此重要？",a="它们是玛格图尔族人的圣物。没有这些水晶，玛格图尔担心他们也会迷失方向。",al={"为什么需要德莱尼水晶","德莱尼水晶有什么作用","德莱尼水晶用途"}},{q="谁拿走了水晶？",a="东边农田避难所的失落者。他们曾是玛格图尔的同胞，直到前往艾泽拉斯的艰辛旅程让他们陷入疯狂。",al={"谁偷走了德莱尼水晶","水晶在谁手里","农田避难所敌人"}},{q="在哪里能找到水晶？",a="在东边农田避难所的棚屋和营火之间。",al={"德莱尼水晶位置","德莱尼水晶在哪里","寻找德莱尼水晶"}},{q="玛格图尔的族人为什么不能自己取回水晶？",a="他们没有足够的力量进入避难所，夺回水晶。",al={"玛格图尔为什么不战斗","为什么帮助玛格图尔"}}},fp="20,184,13.285.0,20.222.0,43.49.0,54.113.0,22.150.0,32.92.0,52.85.0"}
P.entries["quest:139"] = {n="杉德尔船长的宝藏",s="西部荒野西海岸的一只破木桶，是 杉德尔船长的宝藏 寻宝之旅的起点。桶里的线索指向北面海边风车旁的一只旧壶，让你离这位已故海盗的财宝又近了一步。",h="西部荒野西海岸的一只破木桶，是 杉德尔船长的宝藏 寻宝之旅的起点。桶里的线索指向北面海边风车旁的一只旧壶，让你离这位已故海盗的财宝又近了一步。",kw={"峭壁","破木桶","杉德尔船长","隐藏的宝藏","旧壶","海盗线索","西部荒野","风车"},ang={["class:Rogue"]="身为潜行者，你或许会觉得，这名无赖沿峭壁留下的隐秘留言和暗藏标记似曾相识。",["faction:Alliance"]="西部荒野饱受饥荒和迪菲亚匪徒的困扰，而杉德尔遗失的海盗赃物能为你带来一笔可喜的意外之财。"},sec={{t="海盗留下的线索",b="杉德尔船长留下的每条线索都只指向下一个藏匿地点。没有哪张羊皮纸会直接标出赃物的所在，只有找到每一条留言，你才能解开这条线索链。"},{t="向北前往峭壁",b="羊皮纸指引你从木桶处向正北方的海边峭壁进发。一座孤零零的风车矗立在峭壁上，旁边一只废弃的壶里藏着另一条线索。鱼人和迪菲亚拾荒者在海岸游荡，让这段路危机四伏。"}},faq={{q="杉德尔船长的隐藏宝藏 是什么？",a="杉德尔船长是一名海盗，将自己的财宝藏在了西部荒野沿岸。他没有留下地图，而是将写下的谜语藏进散布乡野的木桶、箱子和壶中。",al={"杉德尔 的宝藏","这是什么任务","杉德尔 是谁"}},{q="这第三条线索指向哪里？",a="羊皮纸指引你从破木桶处向正北方的海边峭壁进发。一座孤零零的风车附近，有只旧壶藏着下一条线索。",al={"去哪里","壶的位置","风车在哪里"}},{q="杉德尔为什么把寻宝指引分开藏匿？",a="杉德尔将寻宝指引拆分开来，以免宝藏落入叛变的船员和敌对掠夺者手中。单凭一条线索，无法得知完整的路线。",al={"为什么留下线索","为什么没有完整地图"}},{q="部落玩家能完成这趟寻宝之旅吗？",a="能。任何冒险者都能追寻杉德尔船长留下的线索，并使用与他藏匿的财宝有关的物件，尽管西部荒野位于联盟领地深处。",al={"仅限联盟吗","部落 杉德尔 的宝藏"}},{q="这条线索会直接揭示宝箱的位置吗？",a="不会。海边风车附近的壶里藏着另一条线索，指向杉德尔的宝箱。这是寻宝过程中的倒数第二步。",al={"宝藏在壶里吗","最后一步"}},{q="前往风车的路上有哪些危险？",a="河爪豺狼人、沿海的鱼人和四处游荡的迪菲亚强盗，出没于西部荒野西部的峭壁与海滩。径直向北走，可能会遭遇险情。",al={"峭壁上的危险","有哪些怪物"}}},fx={["03354d32"]={q="为什么线索藏在一个破桶里？",a="木桶本身没有生命意志，也没有切身利害——它只是留在西部荒野海岸上的一处死物藏信点。杉德尔船长刻意把谜语藏在不起眼的漂流物和废弃杂物中，以免随手搜刮的掠夺者和与他争利的恶棍拼凑出通往宝箱的完整路线。",al={"为什么用破桶","为什么纸条在桶里","杉德尔的破桶"}}},fp="32,198,27.177.0,23.231.0,41.171.0,32.128.0,46.146.0,38.144.0,41.126.0,48.147.0"}
P.entries["quest:1392"] = {n="木棒诺博鲁",s="几个月来，诺博鲁一直在折磨避难营的德莱尼。诺博鲁的棍棒象征着失落者对他们施加的暴行，你受托将它带给避难营的领袖。",h="几个月来，诺博鲁一直在折磨避难营的德莱尼。诺博鲁的棍棒象征着失落者对他们施加的暴行，你受托将它带给避难营的领袖。",kw={"棍棒","德莱尼","避难营","失落者","玛格图尔","诺博鲁","悲伤沼泽"},sec={{t="暴行的象征",b="诺博鲁已经折磨避难营的德莱尼好几个月了。这根棍棒已成为失落者对他们施加暴行的象征。你拿着它，将它带给避难营的领袖。"},{t="玛格图尔的迎接",b="玛格图尔问，这件武器是否意味着诺博鲁已经死了，并称这对避难营来说是个值得欢庆的日子。诺博鲁和他的团伙在沼泽中游荡，杀死所有与他们相遇的人，让德莱尼惶惶不可终日。诺博鲁威胁着他们的生存，而他们却没有力量与他抗衡。"}},faq={{q="诺博鲁是谁？",a="他是一名失落者，已经折磨避难营的德莱尼好几个月了。",al={"诺博鲁是谁","诺博鲁的故事","拿棍棒的诺博鲁"}},{q="避难营为什么想要诺博鲁的棍棒？",a="这根棍棒象征着失落者对避难营的德莱尼施加的暴行。",al={"为什么要上交棍棒","诺博鲁的棍棒用途","为什么把棍棒带给玛格图尔"}},{q="棍棒要交给谁？",a="避难营的领袖玛格图尔。",al={"玛格图尔是谁","棍棒交到哪里"}},{q="避难营在哪里？",a="在悲伤沼泽，避难营的德莱尼就生活在那里。",al={"避难营在哪里","避难营位置"}}},fp="17,176,21.163.0,17.289.1,14.86.0,44.85.0,24.58.0,31.65.0"}
P.entries["quest:1393"] = {n="加林的逃亡",s="加林·古瓦德身在农田避难所，恳求有人救他脱离那里的生物，并承诺给救他出去的人一大笔财宝。财宝锁在一个保险箱里，就在他位于斯通纳德以北的营地中。",h="加林·古瓦德身在农田避难所，恳求有人救他脱离那里的生物，并承诺给救他出去的人一大笔财宝。财宝锁在一个保险箱里，就在他位于斯通纳德以北的营地中。",kw={"黑色树脂","农田避难所","加林·古瓦德","加林的逃亡","斯通纳德","保险箱","悲伤沼泽"},sec={{t="求救的呼声",b="加林·古瓦德大声呼救，说周围的生物就要吃掉他了。他承诺，谁能帮他脱险，就能得到一大笔财宝。财宝就在他位于斯通纳德以北沼泽中的营地里，锁在一个保险箱中，只有用加林独自掌握的诀窍才能打开。如果你帮助他逃脱，他就会把这个诀窍教给你。"},{t="保险箱前",b="到了营地，你发现保险箱的锁孔被黑色树脂堵住了，无法用钥匙打开。不过，加林告诉过你，箱子底部藏着一个搭扣。稍加搜寻，你便找到了它，扳动搭扣就打开了保险箱。"}},faq={{q="加林·古瓦德是谁？",a="他被困在农田避难所，害怕那里的生物会吃掉自己，并承诺给帮助他逃脱的人一大笔财宝。",al={"加林是谁","加林·古瓦德的故事","加林的逃亡相关人物"}},{q="加林的营地在哪里？",a="在悲伤沼泽境内，斯通纳德以北的沼泽中。",al={"加林的营地在哪","加林的保险箱位置","保险箱在哪"}},{q="为什么无法用通常的方法打开保险箱？",a="加林的财宝锁在一个保险箱里，只有用他独自掌握的诀窍才能打开，谁帮助他逃脱，他就会把诀窍教给谁。",al={"如何打开保险箱","加林的箱子钥匙"}}},fp="14,144,17.304.0,16.180.1,22.149.0,30.73.0,51.149.0"}
P.entries["quest:1394"] = {n="通过试炼",s="帕科瓦·芬塔拉斯告诉你，你已经通过了这次考验，以及此前的所有考验。你被派回千针石林的多恩·平原行者那里，他会察觉到你的变化，看看你的心智、身体与灵魂是否已足够强大，值得因付出的努力而获得嘉奖。",h="帕科瓦·芬塔拉斯告诉你，你已经通过了这次考验，以及此前的所有考验。你被派回千针石林的多恩·平原行者那里，他会察觉到你的变化，看看你的心智、身体与灵魂是否已足够强大，值得因付出的努力而获得嘉奖。",kw={"多恩·平原行者","最后的旅程","乱风岗","帕科瓦·芬塔拉斯","信仰的试炼","知识试炼","千针石林","老屋"},ang={["faction:Horde"]="这一系列试炼为部落而设，最终在多恩·平原行者那里结束。"},sec={{t="返回老屋",b="这是信仰的试炼的最后一步，这一连串试炼由多恩·平原行者发起。多恩在老屋等候，那里位于乱风岗北面，是一处沿斜坡可达的洞穴。帕科瓦·芬塔拉斯叮嘱你，要坚守你在这些试炼中始终展现的平衡。"},{t="多恩的迎接",b="多恩说，你离开他的住处已经很久，自你纵身一跃、踏上这条道路以来，已过去了许多个月。他发现你比从前更强大，也更有智慧，对此十分欣慰，并说你将他的考验坚持到了最后，理应获得嘉奖。"}},faq={{q="谁派你踏上这最后一步？",a="帕科瓦·芬塔拉斯，他告诉你，你已经通过了他的考验，以及此前的所有考验。",al={"任务给予者","谁给予最后的旅程","帕科瓦·芬塔拉斯"}},{q="接下来我该去哪里？",a="回到千针石林的多恩·平原行者那里。他在老屋等候，那里位于乱风岗北面，是一处沿斜坡可达的洞穴。",al={"多恩在哪里","在哪里交任务","多恩·平原行者位置","老屋位置"}},{q="在这之前是什么任务？",a="前一个任务是知识试炼，也是这一系列中较早的一场试炼。",al={"前一个任务","前置任务","最后的旅程的前置任务"}},{q="这段旅程的第一步是什么？",a="信仰的试炼，由老屋的多恩·平原行者交付。这是该系列任务的最后一步。",al={"第一个任务","从哪里开始","信仰的试炼任务链"}},{q="帕科瓦为什么派你回到多恩那里？",a="帕科瓦说，多恩会察觉到你的变化，发现你的心智、身体与灵魂已足够强大，值得获得嘉奖。",al={"为什么找多恩","帕科瓦的理由"}}},fp="13,219,26.252.0,14.282.1,33.86.0,19.132.0,23.69.0,45.95.0,39.125.0"}
P.entries["quest:1396"] = {n="逼近的野兽",s="卫兵比格斯随商队前往东部海岸，途中遭到了失落者的袭击。只有比格斯活了下来，如今又有野兽在营地附近潜行。比格斯请求你帮助守卫营地。此任务接续帮助卫兵比格斯。",h="卫兵比格斯随商队前往东部海岸，途中遭到了失落者的袭击。只有比格斯活了下来，如今又有野兽在营地附近潜行。比格斯请求你帮助守卫营地。此任务接续帮助卫兵比格斯。",kw={"商队","失落者","锯齿鳄鱼","悲伤纺丝者","物资","沼泽虎","悲伤沼泽","卫兵比格斯"},sec={{t="戒备中的营地",b="卫兵比格斯的商队原本要前往东部海岸，却始终未能抵达。失落者发动袭击，杀死了守卫，毁坏了物资，只有比格斯活了下来。比格斯发誓要保护剩下的物资，然而野兽正在营地附近潜行。比格斯希望你帮助守卫营地。"},{t="附近的野兽",b="比格斯指出，有三种野兽正在逼近营地：小盐齿鳄鱼、悲伤纺丝蛛和沼泽虎。需要杀死八只鳄鱼、十只蜘蛛和十只美洲豹。"}},faq={{q="卫兵比格斯的商队原本要去哪里？",a="东部海岸，但商队始终未能抵达目的地。",al={"比格斯要去哪里","商队目的地","比格斯商队路线"}},{q="谁袭击了卫兵比格斯的商队？",a="失落者。他们杀死了守卫，毁坏了物资，只有比格斯活了下来。",al={"谁袭击了比格斯","谁摧毁了商队","商队遇袭"}},{q="哪些野兽威胁着营地？",a="小锯齿鳄鱼、沼泽纺丝蛛和沼泽虎在营地附近潜行。",al={"哪些野兽正在逼近","什么动物袭击比格斯","沼泽野兽"}},{q="卫兵比格斯为什么留在营地？",a="比格斯发誓要保护商队剩下的物资。",al={"比格斯为何留下","为何不逃走","比格斯的物资"}}},fp="20,190,18.281.0,20.157.0,44.78.0,37.107.0,30.81.0,42.77.0"}
P.entries["quest:1398"] = {n="晒干的流木",s="完成失落的商队后，卫兵比格斯还得修好马车，才能抵达守望堡。比格斯需要结实干燥的木材，便派你向东前往海岸，寻找被太阳晒干的浮木。",h="完成失落的商队后，卫兵比格斯还得修好马车，才能抵达守望堡。比格斯需要结实干燥的木材，便派你向东前往海岸，寻找被太阳晒干的浮木。",kw={"浮木","守望堡","晒干的浮木","悲伤沼泽","马车","卫兵比格斯"},sec={{t="修理马车的木材",b="卫兵比格斯说，他十分感激你，并再次请你帮忙。比格斯要想抵达守望堡，就必须修好马车，而这需要结实干燥的木材。沼泽里的树木松软多节，派不上用场。"},{t="海岸上的浮木",b="比格斯派你向东前往海岸，寻找被太阳晒干的浮木。你需要将八块浮木带回悲伤沼泽，交给比格斯。"}},faq={{q="卫兵比格斯为什么需要木材？",a="比格斯要想抵达守望堡，就必须修好马车，而沼泽里的树木太过松软多节。",al={"浮木用途","比格斯为什么需要浮木","为什么要浮木"}},{q="卫兵比格斯派你去哪里寻找木材？",a="向东前往海岸，寻找被太阳晒干的浮木。",al={"浮木位置","哪里能找到浮木","木材在哪里"}},{q="在这之前是什么任务？",a="先完成丢失的货物，随后比格斯会再次请求帮助。",al={"浮木前置任务","浮木的前置是什么","浮木之前是什么任务"}},{q="需要多少浮木？",a="八块晒干的浮木。",al={"浮木数量","需要多少浮木"}},{q="收集浮木之后是什么任务？",a="接下来是运送货物。",al={"浮木后续","浮木之后是什么","浮木下一个任务"}}},fp="9,123,18.187.0,24.129.0,33.109.0,47.62.0,22.64.0,29.43.0,41.29.0"}
P.entries["quest:14"] = {n="人民军",s="在西部荒野南部，人民军的志愿者继续与迪菲亚作战。这些老练的匪徒盘踞在匕首岭，格里安·斯托曼正率军清剿道路和农场上的敌人。完成巡逻，你就能在哨兵岭正式加入民兵队伍。",h="在西部荒野南部，人民军的志愿者继续与迪菲亚作战。这些老练的匪徒盘踞在匕首岭，格里安·斯托曼正率军清剿道路和农场上的敌人。完成巡逻，你就能在哨兵岭正式加入民兵队伍。",kw={"匕首岭","迪菲亚路霸","迪菲亚拳匪","迪菲亚巡路者","格里安·斯托曼","人民军","哨兵岭","西部荒野"},ang={["class:Paladin"]="身为圣骑士，你听到斯托曼祈求Light赐福新加入的成员。他的话语体现了伸张正义、保护无力自卫者免遭凶恶匪徒侵害的神圣理想。",["faction:Alliance"]="身为联盟的一员，你看到暴风城未能保护西部荒野，迫使平民百姓用自己的鲜血维持家园的秩序。",["race:Human"]="身为暴风城的人类，你挺身而出，帮助那些被遗忘的同胞，王都的权贵已经弃他们的生计于不顾。"},sec={{t="清剿匕首岭",b="迪菲亚潜行者给西部荒野北部的农田带来了深重的苦难。那些逃过格里安·斯托曼首轮清剿的匪徒向南逃窜，躲进了岩石嶙峋的匕首岭。迪菲亚路霸、迪菲亚巡路者和迪菲亚拳匪仍从那里出动，劫掠农庄，伏击旅人。你加入了久经战阵的新兵队伍，奉命深入山岭，打破匪徒对西部荒野南部的控制。"},{t="斯托曼的征讨",b="格里安·斯托曼从洛丹伦对抗天灾军团的战场归来后，发现暴风城的皇家驻军已经抛弃了西部荒野。犯罪集团肆虐，饥饿迫使农民背井离乡。于是，他召集当地志愿者拿起武器。完成这最后一次巡逻，斯托曼便会以圣光之名祝福你，正式接纳你加入民兵队伍。与兄弟会的战斗愈发深入。"}},faq={{q="匕首岭在哪里？",a="匕首岭位于西部荒野南部、哨兵岭西南方。崎岖的山脊和废弃的矿井入口，为迪菲亚潜行者中更强悍的战士提供了集结和据守之地。",al={"匕首岭位置","哪里能找到匕首岭","拦路贼在哪里"}},{q="人民军为何独自对抗迪菲亚？",a="由于瓦里安·乌瑞恩国王失踪，资源又捉襟见肘，暴风城的贵族拒绝派遣皇家军队保护西部荒野的乡间。格里安·斯托曼和当地农民组建了自己的志愿军，保卫家园。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","西部荒野为何被抛弃"}},{q="完成这项任务能达成什么？",a="清除路霸、巡路者和拳匪，就能打破迪菲亚对西部荒野南部道路的控制。你将正式加入格里安·斯托曼指挥的人民军。",al={"人民军完成","正式加入民兵","完成后有什么奖励"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一名老兵，曾在第三次大战期间于洛丹伦对抗天灾军团。他回到西部荒野后，发现暴风城王国已经抛弃了乡间的农民。他在哨兵岭建立了人民军，对抗迪菲亚。",al={"格里安的背景","斯托曼是谁","哨兵岭领袖"}},{q="哪些迪菲亚藏在匕首岭？",a="匕首岭藏匿着经验丰富的迪菲亚路霸、致命的巡路者和残暴的拳匪。他们率众劫掠西部荒野南部各地，并守卫着兄弟会更深处的据点。",al={"西部荒野南部迪菲亚怪物","巡路者和拳匪是什么","匕首岭有哪些人"}},{q="这与洛丹伦有什么联系？",a="格里安·斯托曼说，他最近才从洛丹伦那片遭到污染的土地归来，联盟曾在那里与天灾军团作战。从那场惨烈的战斗中幸存下来，让他下定决心，在地方当局失职后组织西部荒野的防御。",al={"斯托曼与洛丹伦","洛丹伦遭到污染的土地","格里安的战争经历"}}},fx={["12e61ece"]={q="格里安·斯托曼为什么想杀掉这些迪菲亚潜行者？",a="迪菲亚劫掠者已经深入西部荒野南部，洗劫农场并躲避民兵巡逻。格里安的侦察兵追踪他们到了匕首岭，发现他们正在那里集结，谋划下一次袭击。如果现在不把他们连根拔起并击溃，南部剩余的农庄就会彻底落入他们掌控。",al={"为什么在匕首岭杀迪菲亚潜行者","格里安的动机","格里安为什么要杀掉他们"}}},fp="20,276,24.379.0,21.422.0,27.188.0,54.236.0,39.201.0,25.264.0,45.192.0,35.225.0"}
P.entries["quest:140"] = {n="杉德尔船长的宝藏",s="一条浸透威士忌的线索指引你从西部荒野海岸向西，游向无尽之海。杉德尔船长留下的踪迹止于一座偏僻的小岛，他藏起的财宝就在那里等着。",h="一条浸透威士忌的线索指引你从西部荒野海岸向西，游向无尽之海。杉德尔船长留下的踪迹止于一座偏僻的小岛，他藏起的财宝就在那里等着。",kw={"杉德尔船长","最后的线索","隐藏的宝藏","小岛","上锁的箱子","旧罐子","寻宝","西部荒野"},ang={["class:Rogue"]="对看重海盗走私货的潜行者而言，追寻一个恶棍的踪迹，穿过荒凉的海滩并游向大海，自然是驾轻就熟。",["race:Human"]="身为一名抵御迪菲亚匪徒和豺狼人、保卫西部荒野的人类，你或许会乐于暂歇农场巡逻，去追寻一名被遗忘的当地海盗留下的宝藏。"},sec={{t="水手的踪迹",b="杉德尔船长在西部荒野沿岸留下了线索，等你逐一拼凑。最后一张羊皮纸来自他最心爱的威士忌酒壶底部的残渣中。上面给出了最后的方向：向西走到水边，然后迎着海浪游去。"},{t="孤寂的小岛",b="西部荒野外的无尽之海中，几处小小的礁岩露出水面。朝正西游去，就能抵达杉德尔船长藏匿财宝的孤岛。那里有一只上锁的箱子，多年的咸涩海浪已让铰链锈蚀。撬开它，这名海盗留下的踪迹便到了尽头。"}},faq={{q="最后的线索指向哪里？",a="旧罐子里的纸条指引你向西走到西部荒野海岸，再游向大海。箱子就在一座小岛上。",al={"箱子在哪里","杉德尔宝藏位置","最后线索的目的地"}},{q="杉德尔船长是谁？",a="杉德尔船长是一名曾在西部荒野沿岸航行的海盗。他沿着海岸留下了一连串充满谜语的线索，终点是一座偏僻岛屿上的箱子，而非银行或堡垒。",al={"杉德尔船长是谁","杉德尔的故事","杉德尔船长的背景"}},{q="为什么最后的线索带着威士忌的气味？",a="杉德尔船长把最后的指示塞进了他丢弃在海岸附近的威士忌酒壶里。潮气与烈酒让墨迹日渐晕开，但上面的指示仍然清晰可辨。",al={"威士忌纸条","旧罐子线索"}},{q="这次寻宝有几个步骤？",a="这次寻宝分为四个阶段。它从海岸上一张饱经海浪侵蚀的地图开始，接着依次经过一个储物箱、一个桶和一个威士忌酒壶，最后抵达岛上的宝箱。",al={"杉德尔任务链有多长","杉德尔任务阶段","杉德尔船长任务线"}},{q="前往小岛的路上危险吗？",a="最大的挑战是要长途游泳，深入无尽之海。西部荒野近海常有凶猛的鱼人和海兽出没，而那座小岛就是杉德尔藏匿财宝的地方。",al={"游向杉德尔的宝箱","小岛危险","宝箱附近的鱼人"}},{q="宝箱的状况如何？",a="海风和拍岸的浪涛已让箱子饱受侵蚀。它的铰链锈蚀严重，但借力撬开，仍能取出里面的财物。",al={"箱子状况","箱子是否上锁","生锈的箱子"}}},fp="32,165,16.229.0,16.257.1,31.123.0,24.189.0,44.178.0,41.169.0,33.176.0,36.139.0"}
P.entries["quest:141"] = {n="迪菲亚兄弟会",s="马迪亚斯·肖尔从暴风城向身在哨兵岭的格里安·斯托曼送去一份机密报告。肖尔调查了昔日的石匠行会，帮助斯托曼查明迪菲亚潜行者的起源。",h="马迪亚斯·肖尔从暴风城向身在哨兵岭的格里安·斯托曼送去一份机密报告。肖尔调查了昔日的石匠行会，帮助斯托曼查明迪菲亚潜行者的起源。",kw={"迪菲亚","哨兵岭","肖尔","石匠","暴风城","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="身为潜行者，你能看到暴风城昔日工匠之间的争端如何殃及远方的定居点。",["faction:Alliance"]="对联盟而言，Stonemasons的叛乱暴露了王国内部的深刻裂痕。那些重建暴风城石砌城墙的工人，如今却威胁着要将城墙拆毁。",["race:Human"]="身为暴风城的人类，这一真相与你的家园息息相关。你家中的墙壁，乃至大教堂本身，都是如今劫掠西部荒野乡间的那群人建造的。"},sec={{t="从工匠到匪徒",b="数月来，格里安·斯托曼和人民军一直在应对席卷西部荒野的叛乱，却始终不清楚幕后主使是谁。拦路强盗、窃贼和杀手在道路沿线与乡间四处袭击。SI:7的马迪亚斯·肖尔研究了威利的便笺，逐渐拼凑出真相。那个由建筑师和石匠组成、重建了暴风城白色城墙的公会，从未解散。他们的首领艾德温·范克里夫带着他们转入了地下。"},{t="怨恨与背叛",b="第一次兽人战争让暴风城化为灰烬之后，范克里夫的石匠公会开始重建王国的首都。他们的辛劳让暴风城再次成为人类的明珠。工程结束后，一场围绕报酬的激烈争执爆发了。范克里夫和他的工匠们不满王室与贵族给予他们的待遇。于是，他们拿起匕首，系上红色面罩，放下营建城池的手艺，以暴力反抗王权。"},{t="斯托曼的疑虑",b="肖尔的报告送到了哨兵岭，格里安·斯托曼却难以接受其中的内容。在他的记忆中，范克里夫是个勤勉而有天赋的工匠，而非藏身乡间阴影中的杀手。范克里夫建造的房屋曾为数千名归来的市民遮风挡雨。对于暴风城的首席建筑师正在策划毁掉西部荒野这一骇人指控，这位民兵指挥官要求拿出确凿证据，才肯完全相信。"}},faq={{q="肖尔的报告是什么？",a="马迪亚斯·肖尔的机密报告记载了他对昔日的石匠行会和迪菲亚的调查结果。你将它送给格里安·斯托曼。",al={"肖尔的报告","马迪亚斯·肖尔的文件","送给斯托曼的报告"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫曾领导重建暴风城的石匠行会。肖尔的报告调查了这个公会后来的经历。",al={"范克里夫的身份","艾德温·范克里夫是谁","艾德温·范克里夫的故事"}},{q="格里安·斯托曼为何怀疑这份报告？",a="格里安·斯托曼难以接受肖尔的指控。他要求拿出确凿证据，才肯完全相信，而具体内情会在他阅读报告时揭晓。",al={"格里安为何不信","斯托曼的反应","格里安为何需要证据"}},{q="石匠协会为何反抗暴风城？",a="石匠协会重建了暴风城，随后却陷入了一场围绕报酬的激烈争执。他们不满王室与贵族给予他们的待遇。",al={"迪菲亚为何愤怒","石匠的争端","范克里夫的动机"}},{q="SI:7在这个任务中扮演什么角色？",a="SI:7的马迪亚斯·肖尔调查了昔日的公会与匪徒之间可能存在的联系，随后将调查结果送给斯托曼。",al={"为何是马迪亚斯·肖尔","si7的介入","潜行者公会暴风城"}},{q="这项调查接下来会走向何处？",a="你送达报告后，会帮助斯托曼继续寻找证据，推进对迪菲亚的调查。",al={"接下来做什么","迪菲亚后续任务","肖尔的报告之后"}}},fx={b90c31ae={q="马迪亚斯·肖尔为什么想把这份报告送出去？",a="马迪亚斯·肖尔把调查结果送给格里安·斯托曼，好让人民军继续调查迪菲亚。这份机密报告依据的是肖尔对昔日石匠行会的研究。",al={"为什么送报告","肖尔的动机","肖尔为什么给格里安送报告"}},d51cfbac={q="马迪亚斯·肖尔为什么依靠你运送报告？",a="你凭着格里安·斯托曼的直接推荐来到暴风城，而且已经在实地行动中证明了自己的能力。考虑到迪菲亚的渗透者可能正在监视，肖尔不愿冒险派出SI:7的正式信使或城中卫兵，而是信任你，让你把他的机密调查结果直接带回人民军。",al={"为什么不派卫兵","为什么用冒险者","肖尔为什么找人代送"}}},fp="22,201,23.426.1,23.458.1,23.423.1,22.139.0,22.118.0,49.171.0,47.167.0,39.129.0,40.106.1"}
P.entries["quest:1418"] = {n="尼卡·血痕",s="赫格拉姆派你从斯通纳德前往荒芜之地的卡加斯哨站，与那里的斥候队长尼卡·血痕交谈。斯通纳德和卡加斯之间的通信经常中断。",h="赫格拉姆派你从斯通纳德前往荒芜之地的卡加斯哨站，与那里的斥候队长尼卡·血痕交谈。斯通纳德和卡加斯之间的通信经常中断。",kw={"荒芜之地","斥候队长","赫格拉姆","卡加斯","洛克莫丹","尼卡·血痕","斯通纳德","悲伤沼泽"},sec={{t="中断的通信",b="荒芜之地环境恶劣，又紧邻联盟控制的洛克莫丹。因此，斯通纳德和卡加斯之间的通信经常中断。赫格拉姆要你前往荒芜之地，与那里的斥候队长尼卡·血痕交谈，以此证明自己。随后，你要将尼卡的报告送回给赫格拉姆。"},{t="尼卡的答复",b="尼卡告诉你，就在三天前，一名信使被派往斯通纳德。如果斯通纳德没有收到尼卡的消息，那名信使一定是未能完成任务。尼卡希望下一名信使能更有本事，或者运气更好。"}},faq={{q="赫格拉姆派你去哪里？",a="从斯通纳德前往荒芜之地的卡加斯哨站，与尼卡·血痕交谈。",al={"去哪里","尼卡·血痕位置","尼卡在哪里"}},{q="斯通纳德和卡加斯之间的通信为什么会中断？",a="荒芜之地环境恶劣，又紧邻联盟控制的洛克莫丹，斯通纳德和卡加斯之间的通信经常中断。",al={"通信为何中断","荒芜之地通信问题","为何从斯通纳德前往卡加斯"}},{q="尼卡·血痕是谁？",a="尼卡·血痕是荒芜之地卡加斯哨站的斥候队长。",al={"尼卡是谁","尼卡的职责","尼卡·血痕的故事"}},{q="与尼卡·血痕交谈之后要做什么？",a="接下来要向赫格拉姆报告。",al={"接下来做什么","后续任务","与尼卡·血痕交谈之后"}}},fp="15,92,10.267.0,14.202.1,38.127.0,57.122.0,23.73.0,47.64.0"}
P.entries["quest:1419"] = {n="捕猎山狗",s="在卡加斯哨站，尼卡·血痕要你猎杀荒芜之地的 峭壁山狗，这些凶悍的野兽竟敢潜入卡加斯偷吃粮食。尼卡要求你带回三十块颚骨。",h="在卡加斯哨站，尼卡·血痕要你猎杀荒芜之地的 峭壁山狗，这些凶悍的野兽竟敢潜入卡加斯偷吃粮食。尼卡要求你带回三十块颚骨。",kw={"荒芜之地","郊狼窃贼","峭壁山狗","颚骨","卡加斯","尼卡·血痕"},sec={{t="卡加斯的窃贼",b="尼卡·血痕问你是否在荒芜之地待过许多天，感受过那里的酷热，遇见过尘土飞扬的平原上的野兽。峭壁山狗 是一种凶悍的野兽，它们潜入卡加斯，偷吃哨站的粮食。尼卡要你猎杀它们，带回它们的颚骨。带回足够的颚骨，尼卡或许就会相信你了解荒芜之地。"}},faq={{q="尼卡·血痕为什么要郊狼颚骨？",a="峭壁山狗 潜入卡加斯，偷吃了那里的储粮。尼卡要你猎杀它们，并用颚骨证明你了解荒芜之地。",al={"为什么要郊狼颚骨","尼卡·血痕 的动机","为什么收集颚骨"}},{q="郊狼在哪里惹出了麻烦？",a="峭壁山狗 游荡在荒芜之地尘土飞扬的平原上，还潜入卡加斯哨站偷吃粮食。",al={"郊狼位置","哪里能找到 山地狗头狼","郊狼在哪里"}},{q="尼卡·血痕要多少块颚骨？",a="三十块郊狼颚骨，交给卡加斯的尼卡·血痕。",al={"多少块颚骨","郊狼颚骨数量"}},{q="尼卡·血痕是谁？",a="尼卡·血痕位于荒芜之地的卡加斯哨站，在那里交付这项狩猎任务。",al={"尼卡 是谁","尼卡·血痕"}}},fp="14,125,18.331.0,46.152.0,38.89.0,44.73.0,23.93.0"}
P.entries["quest:142"] = {n="迪菲亚兄弟会",s="格里安·斯托曼派你追捕一名行踪不定的迪菲亚信使，希望查明兄弟会如何调遣兵力。",h="格里安·斯托曼派你追捕一名行踪不定的迪菲亚信使，希望查明兄弟会如何调遣兵力。",kw={"迪菲亚","詹戈洛德","信使","月溪镇","采石场","萨丁","斯托曼","西部荒野"},ang={["class:Rogue"]="身为潜行者，你能看出那些技艺娴熟的斥候和扒手，如何在民兵眼皮底下协调一个庞大的地下网络。",["faction:Alliance"]="没有暴风城皇家驻军的支援，人民军只能独自承担西部荒野的情报工作，沿着荒凉的土路追踪信使。",["race:Human"]="身为人类，你可以循着这些公文追查到艾德温·范克里夫，看到暴风城的政治纷争和劳资纠纷留下的苦果，至今仍未消散。"},sec={{t="截住信使",b="格里安·斯托曼的斥候发现，一名行踪不定的迪菲亚信使往来于月溪镇、金海岸矿洞和詹戈洛德矿洞之间。与那些盘踞乡野的暴徒不同，这名信使负责在各地传递书面命令。斯托曼希望将他擒获或击杀，让人民军能够查看他挎包中的信件，查明兄弟会将兵力派往何处。"},{t="墨迹中的线索",b="截获的信件证实，石匠行会那位颇具传奇色彩的前任领袖艾德温·范克里夫，正在亲自指挥迪菲亚的叛乱。信件证实了他对当地各个分支的指挥权，却没有透露他将秘密基地设在了哪里。"},{t="意外的转机",b="信件证实了范克里夫的领导地位，而人民军也迎来了转机。一名走投无路的强盗在企图偷走农夫萨丁的货车时被抓，为了保命，他答应背叛同伙。有了书面证据，斯托曼将注意力转向这名叛徒，希望他能带领一支护送队伍深入迪菲亚藏身处。"}},faq={{q="迪菲亚信使往来于哪些地方？",a="迪菲亚信使从月溪镇铁匠铺外开始巡逻。他向北走到金海岸矿洞和詹戈洛德矿洞，进入这两处地下矿场，然后沿原路返回月溪镇。",al={"信使路线","迪菲亚信使在哪","寻找信使"}},{q="截获的信件透露了什么？",a="斯托曼希望信使携带的命令能够揭示兄弟会的指挥体系，并帮助找到其藏身处。拿到信件后，才能知道其中的内容。",al={"信件内容","神秘信件原文","范克里夫的便条"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼在哨兵岭的总部指挥人民军。由于暴风城的皇家卫兵人数不足，他组织志愿者和冒险者，抵御迪菲亚劫掠者，保卫西部荒野。",al={"斯托曼的职责","任务发布者"}},{q="信使为什么要前往矿洞？",a="兄弟会已经夺取了西部荒野的矿产资源，将詹戈洛德矿洞和金海岸矿洞用作原料来源、藏身处和集结地。信使负责在这些据点与兄弟会的领导层之间传递消息。",al={"为什么是金海岸矿洞","为什么是詹戈洛德矿洞"}},{q="抓住信使就能找到迪菲亚藏身处吗？",a="斯托曼打算利用截获的命令，继续寻找藏身处。回去见他时，你就会得知下一条线索。",al={"是否找到藏身处","藏身处在哪"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫曾是石匠行会的首席石匠，这个公会重建了暴风城。斯托曼正在调查范克里夫与兄弟会之间可能存在的联系。",al={"范克里夫是谁","迪菲亚首领"}}},fx={["885172ef"]={q="格里安·斯托曼为什么希望完成这件事？",a="格里安·斯托曼和人民军正在进行一场艰苦的战斗，试图从迪菲亚潜行者手中夺回西部荒野。民兵知道这些盗贼在全境的农场和矿洞活动，却仍不清楚他们的主要藏身处在哪里。截住这名信使，是斯托曼找到他们的据点、直接打击其首领的最佳线索。",al={"格里安·斯托曼的动机","为何拦截信使","为何抓捕迪菲亚信使"}},fc5d2b39={q="迪菲亚信使是谁？",a="这名信使是迪菲亚的一名成员，负责在他们位于西部荒野的主要据点之间传递公文：被占据的月溪镇、金海岸矿洞和詹戈洛德矿洞。他协调这些分散哨站之间的行动，因此，抓住他或夺取他携带的命令，就能让人民军获得难得的机会，窥见这些阴谋者的指挥体系。",al={"迪菲亚信使","信使是谁","信使目标"}},a4c1678d={q="格里安·斯托曼为什么需要你来完成这项任务？",a="人民军的人手已经捉襟见肘，既要维持哨兵岭周围薄弱的防线，又要保护逃难的农民免受猖獗的强盗和豺狼人侵害。暴风城拒绝向西部荒野派遣援军或王国军队，斯托曼因此没有多余的士兵，无法派人在敌人盘踞的地域追捕信使。",al={"为何派我去","格里安为何不亲自去","民兵为何需要帮手"}}},fp="22,116,24.376.0,14.251.1,17.347.1,39.213.0,41.173.1,25.204.0,40.235.0,54.134.0,22.171.1"}
P.entries["quest:1420"] = {n="向赫格拉姆报到",s="尼卡·血痕为斯通纳德的赫格拉姆写好了一份新报告，请你送过去。这是在你前往卡加斯拜访尼卡之后的事。",h="尼卡·血痕为斯通纳德的赫格拉姆写好了一份新报告，请你送过去。这是在你前往卡加斯拜访尼卡之后的事。",kw={"荒芜之地","赫格拉姆","部落情报","尼卡·血痕","先驱","报告","斯通纳德"},sec={{t="送往斯通纳德的报告",b="尼卡·血痕为斯通纳德的赫格拉姆写好了一份新报告，并交到你手中。尼卡还说，任何自称先驱的人都不能迷路，也不能倒在敌人手下。"},{t="赫格拉姆阅读报告",b="读过尼卡的报告后，赫格拉姆发现联盟也有自己的麻烦。赫格拉姆还认为，部落和联盟或许有一些共同的敌人。"}},faq={{q="谁派你送这份报告？",a="尼卡·血痕，她为赫格拉姆写好了一份新报告。",al={"谁让人给赫格拉姆送报告","给赫格拉姆送报告的任务给予者","谁提供这个任务"}},{q="这份报告需要送到哪里？",a="送给斯通纳德的赫格拉姆。",al={"给赫格拉姆的报告在哪里交","赫格拉姆的位置","赫格拉姆在哪里"}},{q="在这之前要做什么？",a="此前，赫格拉姆派你前往卡加斯，与尼卡·血痕交谈。",al={"前置任务","给赫格拉姆送报告的前置任务","先做哪个任务"}}},fp="17,123,20.169.0,24.149.1,30.80.0,43.51.0,23.62.0"}
P.entries["quest:1421"] = {n="丢失的货物",s="完成逼近的野兽后，卫兵比格斯还有一件事要交给你。失落者袭击商队时，比格斯被打得神志不清，但仍看见一辆货车被拖往北方的失落者村落——农田避难所。车上装着一箱贵重的试剂，比格斯希望你把那些试剂带回来。",h="完成逼近的野兽后，卫兵比格斯还有一件事要交给你。失落者袭击商队时，比格斯被打得神志不清，但仍看见一辆货车被拖往北方的失落者村落——农田避难所。车上装着一箱贵重的试剂，比格斯希望你把那些试剂带回来。",kw={"黑暗之门","农田避难所","失落者","守望堡","悲伤沼泽","卫兵比格斯","法师的试剂"},sec={{t="被盗的货车",b="比格斯在袭击中被打得失去了知觉，却瞥见商队的一辆货车被拖往北方的失落者村落——农田避难所。那辆货车上有一箱试剂，守望堡的法师十分看重这些研究用的材料。比格斯希望你找到箱子，把里面的东西带回来。"},{t="比格斯的话",b="你带着试剂回来时，比格斯很高兴，因为守望堡的法师终于能继续开展工作了。比格斯不知道他们究竟在做什么，只知道这项工作与诅咒之地的黑暗之门有关，对保障联盟的安全至关重要。"}},faq={{q="卫兵比格斯是谁？",a="卫兵比格斯所在商队的一辆货车被失落者抢走了，他希望找回车上装载的试剂。",al={"卫兵比格斯","谁提供 丢失的货物"}},{q="失落者把商队的箱子带到哪里去了？",a="比格斯看见装着箱子的货车被拖往北方的失落者村落——农田避难所。",al={"商队箱子位置","农田避难所在哪里","试剂在哪里"}},{q="这些试剂为什么重要？",a="守望堡的法师需要用这些试剂开展研究。",al={"试剂为什么重要","守望堡试剂用途"}},{q="找回箱子后，接下来是什么？",a="把试剂交给比格斯后，接下来就是 晒干的流木。",al={"丢失的货物 后续任务","丢失的货物 任务链"}}},fp="16,179,16.328.0,15.263.1,21.97.0,47.112.0,31.73.0,38.54.0"}
P.entries["quest:1422"] = {n="海中的威胁",s="完成缺乏补给后，托克卡尔开始为你打造武器，并让你去悲伤沼泽找卡塔尔谈谈。卡塔尔说过，海滩上的巡逻队需要一些帮助。",h="完成缺乏补给后，托克卡尔开始为你打造武器，并让你去悲伤沼泽找卡塔尔谈谈。卡塔尔说过，海滩上的巡逻队需要一些帮助。",kw={"海滩","卡塔尔","巡逻","海岸","悲伤沼泽","海中的威胁","托克卡尔"},sec={{t="与卡塔尔交谈",b="托克卡尔在为你打造武器时，建议你去找卡塔尔谈谈，卡塔尔曾说海滩上的巡逻队需要一些帮助。托克卡尔和几个喝酒的无赖共用营地，他宁愿你保持头脑清醒、武器随时可用，也不愿你加入他们。"},{t="盖过海浪的轰鸣",b="卡塔尔请你安静片刻。在大海低沉的轰鸣声中，依然能听见鱼人那令人作呕的咕噜声。"}},faq={{q="托克卡尔为什么让你去找卡塔尔？",a="托克卡尔正忙着为你打造武器，他宁愿你保持头脑清醒、武器随时可用，也不愿你和同住营地的无赖们一起喝得酩酊大醉。",al={"为什么与卡塔尔交谈","托克卡尔的理由","为什么拜访卡塔尔"}},{q="卡塔尔需要什么帮助？",a="卡塔尔提到过，海滩上的巡逻队需要一些帮助，这正是卡塔尔所求的。",al={"卡塔尔的问题","卡塔尔想要什么","卡塔尔巡逻"}},{q="这一步之前是什么？",a="这一步接在缺乏补给之后，完成后托克卡尔便开始为你打造武器。",al={"上一个任务","前置任务","海中的威胁任务链"}}},fp="19,82,17.213.0,24.114.1,35.153.0,37.59.0,27.58.0"}
P.entries["quest:1423"] = {n="遗失的补给品",s="一只小巧结实的木桶，接缝处用气味刺鼻的黄色蜡封住。桶底的印记标着军需官朗格尔斯和守望堡，那里才是它的归处。",h="一只小巧结实的木桶，接缝处用气味刺鼻的黄色蜡封住。桶底的印记标着军需官朗格尔斯和守望堡，那里才是它的归处。",kw={"木桶","夜色镇","遗失的货物","守望堡","军需官朗格尔斯","悲伤沼泽"},sec={{t="带印记的木桶",b="这只小巧厚实的木桶，接缝处封着气味刺鼻的黄色蜡。桶底的印记写着军需官朗格尔斯、守望堡，说明这只木桶是要送给那里的军需官的。"},{t="军需官的回话",b="军需官朗格尔斯向你致谢。从夜色镇到守望堡，沿途总有补给物资遗失，能找回一些实在是件好事。"}},faq={{q="遗失的货物应该交给谁？",a="木桶上的标记表明，它是要送给守望堡的军需官朗格尔斯的。",al={"木桶交给谁","遗失的货物收件人","木桶送到哪里"}},{q="怎么知道木桶属于谁？",a="木桶底部有一道印记，标着军需官朗格尔斯和守望堡。",al={"木桶标记","如何解读木桶标记","军需官朗格尔斯印记"}},{q="木桶是什么样的？",a="这是一只小巧结实的木桶，接缝处封着气味刺鼻的黄色蜡。",al={"遗失的货物木桶","木桶外观"}}},fp="17,74,16.164.0,27.151.1,42.68.0,37.81.0,31.71.0"}
P.entries["quest:1424"] = {n="泪水之池",s="在斯通纳德，费泽鲁尔请你到泪水之池一带搜寻阿塔莱的文物。大酋长派费泽鲁尔一行人调查阿塔哈卡神庙的怪事，他们抵达时却发现神庙已经沉没。",h="在斯通纳德，费泽鲁尔请你到泪水之池一带搜寻阿塔莱的文物。大酋长派费泽鲁尔一行人调查阿塔哈卡神庙的怪事，他们抵达时却发现神庙已经沉没。",kw={"文物","阿塔莱","费泽鲁尔","绿龙","泪水之池","斯通纳德","悲伤沼泽","阿塔哈卡神庙","大酋长"},sec={{t="沉没的神庙",b="阿塔莱巨魔是黑暗施法者，这个部族因使用禁忌魔法而臭名昭著。费泽鲁尔一行人抵达阿塔哈卡神庙时，惊讶地发现神庙已经沉没。如今，绿龙守卫着这里，并自称艾泽拉斯的保护者。"},{t="谜团的碎片",b="费泽鲁尔想弄清发生了什么，请你到泪水之池一带收集阿塔莱的文物，从中逐步拼凑出真相。没人知道神庙里曾举行过什么黑暗仪式，只知道那里曾动用过强大的魔法力量。费泽鲁尔希望阿塔莱的法术能为部落所用，也想弄明白这些巨魔究竟想达成什么目的，又是什么出了如此可怕的差错。"}},faq={{q="费泽鲁尔是谁？",a="费泽鲁尔身在斯通纳德，是大酋长派去调查阿塔哈卡神庙怪事的成员之一。",al={"费泽鲁尔","泪水之池任务由谁提供","泪水之池由谁给予"}},{q="部落为什么对阿塔莱巨魔感兴趣？",a="费泽鲁尔指出，那里曾动用过强大的魔法力量，他认为阿塔莱的法术或许能为部落所用。",al={"部落为何关注 阿塔莱","阿塔莱 魔法 部落"}},{q="阿塔莱的文物在哪里？",a="它们散落在神庙附近的泪水之池池底。",al={"阿塔莱 文物位置","文物在哪里","泪水之池文物"}},{q="如今是谁守卫着沉没的神庙？",a="绿龙守卫着这里，并自称艾泽拉斯的保护者。",al={"绿龙为何在这里","绿龙 阿塔哈卡神庙","绿龙 悲伤沼泽"}},{q="交付文物后，接下来是什么？",a="接下来是阿塔莱流放者。",al={"泪水之池之后的任务","泪水之池后续任务","泪水之池之后是什么"}}},fp="13,187,17.227.0,18.384.0,17.114.0,50.121.0,40.75.0,33.85.0,50.26.0"}
P.entries["quest:1425"] = {n="运送货物",s="完成晒干的流木后，卫兵比格斯还有最后一件差事，要你在修理货车期间完成。比格斯已将从食人魔袭击中抢救出的重要物资打包，想让你送到守望堡的军需官朗格尔斯手中。",h="完成晒干的流木后，卫兵比格斯还有最后一件差事，要你在修理货车期间完成。比格斯已将从食人魔袭击中抢救出的重要物资打包，想让你送到守望堡的军需官朗格尔斯手中。",kw={"阿祖拉水晶","诅咒之地","黑暗之门","守望堡","军需官朗格尔斯","货物","悲伤沼泽","卫兵比格斯"},sec={{t="比格斯的最后一趟送货",b="比格斯修理货车时，从食人魔袭击中抢救出的重要物资已经打包，等你送往守望堡。守望堡坐落在诅咒之地北部的群山中，监视着黑暗之门。比格斯指明了路线：沿路向东，在岔路口向南进入诅咒之地，再在下一个岔路口向左转，并叮嘱你务必小心。"},{t="抵达守望堡",b="收到比格斯商队送来的包裹，军需官朗格尔斯十分惊讶，因为守望堡的人早已认定商队和比格斯都已遇难。朗格尔斯向你道谢，并希望物资中有阿祖拉水晶，这种急需的施法材料在守望堡已所剩无几。"}},faq={{q="是谁将这批货物送往守望堡？",a="是留下修理货车的卫兵比格斯，他将从食人魔袭击中抢救出的重要物资打好了包。",al={"谁提供运送货物","运送货物任务给予者","卫兵比格斯送货"}},{q="这批货物要送到哪里？",a="要送到诅咒之地北部群山中的守望堡，交给军需官朗格尔斯。",al={"守望堡在哪里","如何前往守望堡","军需官朗格尔斯位置"}},{q="这趟送货之前紧接着是什么任务？",a="前一个任务是晒干的流木。",al={"运送货物前置任务","运送货物之前是什么任务"}},{q="从沼泽到守望堡该走哪条路？",a="沿路向东，在岔路口向南进入诅咒之地，再在下一个岔路口向左转。",al={"前往守望堡的路线","前往诅咒之地的道路"}},{q="守望堡监视着什么？",a="守望堡监视着黑暗之门。",al={"守望堡的作用","守望堡为何位于诅咒之地"}}},fp="20,132,25.356.0,14.262.1,38.110.0,36.106.0,41.32.0,44.117.0,39.46.0"}
P.entries["quest:1426"] = {n="海中的威胁",s="托克卡尔派你去找卡塔尔谈话，卡塔尔直言自己对大海的憎恨。看着那些鱼人死在为部落效力的人手中，卡塔尔便感到几分畅快，并问你能杀死多少鱼人，是否愿意挑战其中最强悍的种类，考验自己的实力。",h="托克卡尔派你去找卡塔尔谈话，卡塔尔直言自己对大海的憎恨。看着那些鱼人死在为部落效力的人手中，卡塔尔便感到几分畅快，并问你能杀死多少鱼人，是否愿意挑战其中最强悍的种类，考验自己的实力。",kw={"卡塔尔","沼泽食腐鱼人","沼泽喷墨鱼人","沼泽鱼人","鱼人","悲伤沼泽","海中的威胁"},sec={{t="对大海的怨恨",b="卡塔尔对大海以及从海中爬出的任何生物都毫无好感，称大海是一位强大却盲目、冷酷而残暴的女主人。倘若能成百上千地杀死那些鱼人，卡塔尔会十分高兴，而看着它们倒在为部落效力的人手中，也能得到些许慰藉。身在悲伤沼泽的卡塔尔要你杀死沼泽鱼人、沼泽喷墨鱼人和沼泽食腐鱼人。"},{t="卡塔尔的评判",b="你回来后，卡塔尔说，大海或许看似浩瀚而无情，但她自己的子嗣如今已被你留下了血淋淋的印记。那些鱼人如今尝到了痛苦，必须重新壮大队伍，卡塔尔对此很满意，每当一只鱼人再也发不出声音，卡塔尔都会露出微笑。卡塔尔邀你回来继续杀戮。"}},faq={{q="卡塔尔为什么要消灭鱼人？",a="卡塔尔对大海以及从海中爬出的生物毫无好感，很乐意见到鱼人成百上千地被杀死。看着它们死在为部落效力的人手中，便能得到几分畅快。",al={"为什么杀鱼人","卡塔尔 鱼人","为什么憎恨大海"}},{q="这场猎杀在何处进行？",a="在悲伤沼泽，猎物是沼泽鱼人、沼泽喷墨鱼人和沼泽食腐鱼人。",al={"沼泽鱼人在哪里","海中的威胁地点"}},{q="谁交付这场猎杀任务？",a="卡塔尔，也就是托克卡尔派你到悲伤沼泽去交谈的人。",al={"谁交付海中的威胁","海中的威胁任务给予者"}},{q="这场猎杀之前是什么任务？",a="前一个任务是最初的海中的威胁，托克卡尔在那个任务中派你去找卡塔尔谈话。",al={"海中的威胁前置任务","海中的威胁上一个任务"}}},fp="19,228,24.383.0,15.257.1,42.187.0,32.87.0,20.90.0,28.84.0"}
P.entries["quest:1427"] = {n="海中的威胁",s="完成卡塔尔交代的事后，你被告知在休息前再去见一次托克卡尔。卡塔尔认为，你不在的时候，托克卡尔已经打造好了几件武器，会送你一件，答谢你的帮助。",h="完成卡塔尔交代的事后，你被告知在休息前再去见一次托克卡尔。卡塔尔认为，你不在的时候，托克卡尔已经打造好了几件武器，会送你一件，答谢你的帮助。",kw={"卡塔尔","鱼人","锯齿鳄鱼肉","悲伤沼泽","海中的威胁","托克卡尔"},sec={{t="再访托克卡尔",b="卡塔尔认为，你不在的时候，托克卡尔已经打造好了几件武器，会送你一件，答谢你的帮助。卡塔尔还说，等你准备好了，不妨拿鱼人试试武器的威力，哪怕只是为了让卡塔尔更高兴些。"},{t="托克卡尔的谢意",b="托克卡尔很高兴看到你回来，说又打造了一些武器，用来对付鱼人。为了感谢你带来新鲜的盐齿鳄鱼肉，还让卡塔尔脸上露出了一丝笑容，他送了你一件武器。"}},faq={{q="是谁让你去找托克卡尔谈谈？",a="是卡塔尔，他让你在悲伤沼泽休息前再去见一次托克卡尔。",al={"谁提供这个任务","哪里接取海中的威胁","谁发起这个任务"}},{q="托克卡尔为什么要送你武器？",a="卡塔尔认为，你不在的时候，托克卡尔已经打造好了几件武器，会送你一件，答谢你的帮助。",al={"托克卡尔为什么送武器","托克卡尔打造了什么","托克卡尔给予奖励的原因"}},{q="和托克卡尔交谈后，接下来是什么？",a="接下来是海中的威胁。",al={"下一个任务是什么","之后去哪里","海中的威胁后续任务"}}},fp="19,158,15.258.0,16.194.1,36.88.0,33.114.0,44.25.0"}
P.entries["quest:1428"] = {n="海中的威胁",s="卡塔尔很高兴，你对鱼人的仇恨正和卡塔尔自己的一同增长，于是派你前往悲伤沼泽的海滩，继续猎杀鱼人。",h="卡塔尔很高兴，你对鱼人的仇恨正和卡塔尔自己的一同增长，于是派你前往悲伤沼泽的海滩，继续猎杀鱼人。",kw={"海中的威胁","鱼人","卡塔尔","沼泽食腐鱼人","沼泽喷墨鱼人","沼泽神谕者","悲伤沼泽"},sec={{t="海滩上的更多鱼人",b="卡塔尔让你沿着海滩寻找更多鱼人，等打够了再回来。要猎杀的是沼泽喷墨鱼人、沼泽食腐鱼人和沼泽智者。在大海和她的每一个子嗣都归于沉寂之前，卡塔尔绝不会感到快意，尤其是那些令人作呕的鱼人。"}},faq={{q="谁发布这个任务？",a="悲伤沼泽的卡塔尔。",al={"谁发布海中的威胁","海中的威胁任务发布者","卡塔尔 悲伤沼泽"}},{q="需要猎杀哪些生物？",a="卡塔尔要你猎杀海滩上的沼泽喷墨鱼人、沼泽食腐鱼人和沼泽智者。",al={"海中的威胁要杀什么","海中的威胁目标","哪些鱼人"}},{q="卡塔尔为什么要清剿鱼人？",a="在大海和她的子嗣都归于沉寂之前，卡塔尔绝不会感到快意，尤其是那些鱼人。",al={"为什么杀鱼人","卡塔尔的动机","为什么仇恨鱼人"}},{q="这一步之前是什么任务？",a="这一步接在之前的海中的威胁之后，完成那个任务后，托克卡尔给了你一件武器。",al={"海中的威胁前置任务","海中的威胁上一个任务"}}},fp="16,94,20.277.0,21.56.0,33.94.0,39.94.0,27.75.0"}
P.entries["quest:1429"] = {n="阿塔莱流放者",s="你在泪水之池时，费泽鲁尔的一名斥候带回了一张以鲜血写在干肉皮上的卷轴。如今，费泽鲁尔将你收集的文物打成一包，派你远赴北方的辛特兰，寻找一位被流放的阿塔莱祭司。",h="你在泪水之池时，费泽鲁尔的一名斥候带回了一张以鲜血写在干肉皮上的卷轴。如今，费泽鲁尔将你收集的文物打成一包，派你远赴北方的辛特兰，寻找一位被流放的阿塔莱祭司。",kw={"阿塔莱流放者","费泽鲁尔","哈卡","辛特兰","迦玛兰","泪水之池","沙德拉洛","悲伤沼泽","枯木"},sec={{t="鲜血写就的判决",b="卷轴上写着对一位阿塔莱祭司的判决，在他的族人看来，那是比死亡更可怕的命运。他被流放到遥远的北方，在辛特兰与枯木巨魔一同生活。费泽鲁尔会将文物打成一包，派你去找到流放者，查明这些文物的真正用途后回来。"},{t="流放者的话语",b="看到这包文物后，流放者指出，它们是阿塔莱的召唤工具。他说，鲜血之厅的门徒正由预言者迦玛兰带领，走向他们选定的命运，并猜想哈卡是否已经重返神庙。"}},faq={{q="谁派你去寻找阿塔莱流放者？",a="斯通纳德的费泽鲁尔，他将你收集的文物打成一包，派你北上前往辛特兰。",al={"谁给予阿塔莱流放者任务","阿塔莱流放者任务给予者","谁开启任务"}},{q="阿塔莱流放者在哪里？",a="在辛特兰，与枯木巨魔一同住在沙德拉洛的神庙中。",al={"流放者在哪里","阿塔莱流放者位置","哪里能找到阿塔莱流放者"}},{q="那位祭司受到了什么判决？",a="一张以鲜血写在干肉皮上的卷轴，判处那位祭司承受阿塔莱眼中比死亡更可怕的命运：流放到辛特兰，与枯木巨魔为伍。",al={"他为何被流放","判决是什么","阿塔莱流放者背景故事"}},{q="你要带什么去见流放者？",a="一包在泪水之池收集的阿塔莱文物，费泽鲁尔希望流放者能揭示它们的真正用途。",al={"带去的包裹是什么","文物是什么","阿塔莱文物用途"}},{q="这趟旅程紧接着什么任务？",a="前一个任务是泪水之池，费泽鲁尔在那个任务中让你收集阿塔莱文物。",al={"上一个任务","前置任务","阿塔莱流放者的前置任务"}}},fp="17,167,19.274.0,17.249.1,40.69.0,35.99.0,39.142.0,35.110.0,40.85.0"}
P.entries["quest:143"] = {n="送往西部荒野的信",s="所罗门镇长从湖畔镇向西部荒野求援，以抵御黑石兽人和豺狼人。暴风城的军队迟迟未至，他希望格里安·斯托曼的人民军能伸出援手。",h="所罗门镇长从湖畔镇向西部荒野求援，以抵御黑石兽人和豺狼人。暴风城的军队迟迟未至，他希望格里安·斯托曼的人民军能伸出援手。",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","人民军","赤脊山","哨兵岭","所罗门的求援","西部荒野"},ang={["faction:Alliance"]="这封信表明，暴风城王国的中央防卫力量已所剩无几，边境城镇只能自行寻求彼此援助。",["race:Human"]="身为人类，你与赤脊山和西部荒野的定居者共同承受着艰辛。首都按兵不动，他们只能依靠志愿战士和雇佣兵。"},sec={{t="危急的求援",b="黑石兽人和豺狼人围攻湖畔镇，而暴风城军队的大部队尚未抵达。所罗门镇长知道，仅凭镇上的卫兵和非正规军，无法独力守住赤脊山。眼看王室的后备部队迟迟不见踪影，他写下了一封正式的求援信。他听说艾尔文森林以西正有一支平民自卫队集结，便将求援信送往那里。"},{t="跨越边界的求援",b="格里安·斯托曼是一位身经百战的指挥官，正以人民军的旗号召集志愿战士。所罗门将信件送往王国另一端，希望西部荒野的志愿战士能在王室大军动员起来之前，增援湖畔镇的边境。但西部荒野也正与迪菲亚潜行者展开殊死斗争。"}},faq={{q="所罗门镇长为何向西部荒野求援？",a="暴风城尚未派出湖畔镇抵御兽人和豺狼人所需的援军。所罗门听说西部荒野正有一支平民武装集结，希望格里安·斯托曼能抽调兵力支援赤脊山。",al={"为何向西部荒野求援","所罗门的求援","为何向格里安求援"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是驻守西部荒野哨兵岭的一名老兵。王室的统治与庇护缺位，他便组建并领导人民军，保护当地农庄免受强盗和迪菲亚潜行者的侵扰。",al={"格里安是谁","斯托曼的职责","谁领导西部荒野"}},{q="这趟送信之旅要去哪里？",a="你从湖畔镇的镇政厅出发，携信向西穿过赤脊山和艾尔文森林，前往西部荒野中部的哨兵岭。",al={"送信地点","斯托曼在哪里","赤脊山到西部荒野"}},{q="暴风城军队为何还未替湖畔镇解围？",a="所罗门镇长说，军队似乎出了什么问题，因为承诺派来的部队迟迟未到。国王不在，由伯瓦尔·弗塔根公爵摄政，而偏远地区等不到预期的后备部队，只能自行抵御威胁。",al={"为何没有暴风城军队","王室卫兵在哪里","暴风城军队失踪"}},{q="西部荒野真的能抽调兵力支援赤脊山吗？",a="不能。当你抵达哨兵岭时，西部荒野在迪菲亚潜行者的进攻下已岌岌可危。人民军无兵可派，连守住自己的边境都十分艰难。",al={"西部荒野是否援助","民兵是否前来","格里安能否援助"}},{q="送达信件之后会怎样？",a="格里安·斯托曼收到信件后，起草了一封回信，说明西部荒野的危急处境。他让你带着回信返回所罗门镇长那里。",al={"接下来做什么","后续任务","送往西部荒野的信之后"}}},fp="21,192,18.370.0,23.332.0,51.212.0,25.222.0,37.125.0,49.231.0,52.187.1,39.154.1"}
